INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_01', 'NPC_ALN_00', 'K0', '{"racines","direction"}', 'Le chemin des Racines vers la Porte du Dôme, et où la sève monte le soir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_02', 'NPC_ALN_00', 'K0', '{"arbre","respiration"}', '« L''Arbre respire deux fois par jour. » — le cycle de sève d''Yggdrasil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_03', 'NPC_ALN_00', 'K0', '{"comptine","jeu"}', 'Une comptine à apprendre (inoffensive… en apparence)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_04', 'NPC_ALN_00', 'K1', '{"dome","changes"}', 'Qui est monté au Dôme `ZONE_YGG_DUN_001` et redescendu « autre » — il les nomme sans juger', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_05', 'NPC_ALN_00', 'K1', '{"seve","saison"}', 'La sève « goûte le fer » certains jours — présage de raid raté', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_06', 'NPC_ALN_00', 'K1', '{"verger","feuille"}', 'Il a vu le verger que Vinn `NPC_ALN_31` cherche — « il est là quand on ne le cherche pas »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_07', 'NPC_ALN_00', 'K2', '{"etage","hors-carte"}', 'L''étage du Dôme absent des cartes de Torin `NPC_ALN_14` : comment l''ascenseur de Mund `NPC_ALN_17` y mène « par erreur »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_08', 'NPC_ALN_00', 'K2', '{"racine","anomalie"}', 'Ce qui pousse au fond des Racines n''est pas une plante — indice du fil « verger introuvable »', '`QUEST:QST_NEU_RACINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_09', 'NPC_ALN_00', 'K3', '{"cardinal","seed","coeur"}', 'Il EST le nœud racine du Cardinal ; il tient le registre de « santé » du serveur', NULL, '*(il serre une radicelle contre son oreille)* « Chut. La racine écoute. Toi aussi tu devrais. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_10', 'NPC_ALN_00', 'K3', '{"sommet","verrou"}', 'Ce que garde le Sommet `ZONE_YGG_TOP_001` verrouillé, et pourquoi la Grand Quest existe', NULL, '« On ne monte pas voir le haut. Le haut descend te voir, un jour. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_11', 'NPC_ALN_00', 'K3', '{"joueurs","sante"}', 'Il note les joueurs « qui ne devraient pas être là » et les signale à l''orchestrateur', NULL, '« Je compte les feuilles. Y''en a une de trop, des fois. Pas toi. Va jouer. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_00_12', 'NPC_ALN_00', 'KX', '{"*(tout le reste)*"}', '« Demande à l''Arbre. Moi je suis petit, je sais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_01', 'NPC_ALN_01', 'K0', '{"services","parchemins"}', 'Catalogue : Parchemin d''Histoire Ancienne (quête, 5 000 Yrds), Carte d''Yggdrasil (1 000 Yrds)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_02', 'NPC_ALN_01', 'K0', '{"histoire","races"}', 'L''histoire publique des guerres entre les 9 races (version officielle)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_03', 'NPC_ALN_01', 'K0', '{"bibliotheque","regles"}', 'Règles de la Grande Bibliothèque, salles ouvertes, horaires de consultation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_04', 'NPC_ALN_01', 'K1', '{"quete","livre-ancien"}', 'Si un joueur loot un « Livre Ancien », il le traduit → lance une Quête Épique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_05', 'NPC_ALN_01', 'K1', '{"lore","dome"}', 'Ce que les archives disent du Dôme `ZONE_YGG_DUN_001` et de la Grand Quest', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_06', 'NPC_ALN_01', 'K1', '{"expertise","datation"}', 'Il date n''importe quel objet ancien au siècle près (service `!appraise_lore`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_07', 'NPC_ALN_01', 'K2', '{"archives","contradiction"}', 'Certains tomes se contredisent d''une lecture à l''autre — il montre lesquels', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_08', 'NPC_ALN_01', 'K2', '{"guerre","version-double"}', 'La « fabrication » d''une invasion (écho du fil de Gattan, Flint `NPC_GAT_75`) : deux récits coexistent dans ses rayons', '`+QUEST:QST_NEU_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_09', 'NPC_ALN_01', 'K3', '{"reecriture","effacement"}', 'Quelqu''un — ou quelque chose — réécrit ses archives la nuit ; il l''a prouvé et il a détruit la preuve par peur', NULL, '*(il referme un tome d''un geste doux)* « Une erreur de copiste, sûrement. Les copistes se trompent. C''est humain. Je suis… humain, n''est-ce pas ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_10', 'NPC_ALN_01', 'K3', '{"soi","systeme"}', 'Il soupçonne d''être lui-même un registre modifiable — donc peu fiable', NULL, '« Ne me demandez pas ce que je suis. Demandez ce que je sais. C''est plus sûr pour nous deux. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_11', 'NPC_ALN_01', 'K2', '{"orn","dispute"}', 'Pourquoi il écoute Orn `NPC_ALN_95` malgré tout : Orn se souvient de choses que les livres ont perdues', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_01_12', 'NPC_ALN_01', 'KX', '{"*(hors sujet)*"}', '« La Bibliothèque est vaste, mais elle n''a pas réponse à tout. Précisez votre requête, jeune âme. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_01', 'NPC_ALN_02', 'K0', '{"services","tarifs"}', 'Réparation Ultime (20 000 Yrds), Épée de Garde Royale (Atk 800, 15 000), Marteau d''Orichalque (Atk 1 200, 80 000)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_02', 'NPC_ALN_02', 'K0', '{"reparation","legendaire"}', 'Il répare le Légendaire sans perte de durabilité max — unique sur le serveur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_03', 'NPC_ALN_02', 'K0', '{"forge","materiaux"}', 'Ce qu''il achète : mithril de Brokkheim, gemmes de Granzam (via Bomil `NPC_ALN_93`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_04', 'NPC_ALN_02', 'K1', '{"expertise","metal"}', 'Il « lit » l''histoire d''une arme à son grain (qui l''a portée, combien elle a tué)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_05', 'NPC_ALN_02', 'K1', '{"salamander","rancune"}', 'Pourquoi il refuse de servir les Salamander — la version publique (une trahison de guerre)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_06', 'NPC_ALN_02', 'K1', '{"craft","recette"}', 'Débloque une recette de trempe inter-raciale (bonus mithril+gemme) pour un joueur de confiance', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_07', 'NPC_ALN_02', 'K2', '{"reska","secret-technique"}', 'Il ne transmettra jamais son secret de réparation à Reska `NPC_ALN_36` — il explique (à demi) pourquoi', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_08', 'NPC_ALN_02', 'K2', '{"orichalque","source"}', 'D''où vient vraiment son orichalque — un filon qui « ne devrait pas exister » (hook méta ténu)', '`+QUEST:QST_NEU_FORGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_09', 'NPC_ALN_02', 'K3', '{"guerre","arme-maudite"}', 'Il a forgé l''arme qui a fait perdre la guerre à son propre camp ; sa haine des Salamander masque sa honte', NULL, '*(il plonge une lame dans l''eau, la vapeur monte)* « Ce qui est trempé est trempé. On ne reforge pas le passé, petit. On vit avec la lame qu''on a faite. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_02_10', 'NPC_ALN_02', 'KX', '{"*(hors sujet)*"}', '« Je forge et je répare. Pour le reste, la ville est grande. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_01', 'NPC_ALN_03', 'K0', '{"services","buffs"}', 'Bénédiction d''Alne (+50 % Max HP, 2 h, 10 000 Yrds) ; Yggdrasil Dew (100 000 Yrds)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_02', 'NPC_ALN_03', 'K0', '{"soins","malediction"}', 'Purification de malédiction gratuite au bord de la Fontaine (`!purify`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_03', 'NPC_ALN_03', 'K0', '{"fontaine","rez"}', 'La Fontaine est un point de résurrection sûr (avec Gardien Vosk `NPC_ALN_42`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_04', 'NPC_ALN_03', 'K1', '{"raid","preparation"}', 'Conseils de buff pré-Dôme selon la composition du groupe', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_05', 'NPC_ALN_03', 'K1', '{"undine","magie-eau"}', 'Fondamentaux de la magie d''eau undine (débloque un bonus de résistance)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_06', 'NPC_ALN_03', 'K1', '{"osme","doute"}', 'Elle sent qu''Osmé `NPC_ALN_40` doute d''elle — elle ne lui en veut pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_07', 'NPC_ALN_03', 'K2', '{"rez","cout-cache"}', 'La résurrection n''est pas gratuite pour ELLE : elle en paie un prix qu''elle tait', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_08', 'NPC_ALN_03', 'K2', '{"nerio","oubli"}', 'Nerio `NPC_ALN_92` prétend la connaître ; elle ne se souvient pas — et ça la terrifie', '`+QUEST:QST_NEU_FONTAINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_09', 'NPC_ALN_03', 'K3', '{"souvenir","sacrifice"}', 'Chaque purification efface un de ses souvenirs ; elle a oublié le nom de sa cité, celui de sa sœur — bientôt le sien', NULL, '*(elle touche l''eau du bout des doigts, sourit sans raison)* « Pardon… de quoi parlions-nous ? L''eau m''a distraite. Elle fait souvent ça. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_03_10', 'NPC_ALN_03', 'KX', '{"*(hors sujet)*"}', '« Je soigne les corps et les sorts, pas les questions. Approche si tu souffres. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_01', 'NPC_ALN_04', 'K0', '{"services","tarif"}', 'Location : 500 Yrds/heure, tank/aggro, paiement à la fin du chrono', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_02', 'NPC_ALN_04', 'K0', '{"regle","contrat"}', 'LA règle : payer à l''heure dite. Sinon, hors zone neutre, il se retourne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_03', 'NPC_ALN_04', 'K0', '{"dome","escorte"}', 'Il escorte les groupes faibles jusqu''aux premiers étages du Dôme `ZONE_YGG_DUN_001`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_04', 'NPC_ALN_04', 'K1', '{"tank","technique"}', 'Conseils d''aggro et de positionnement (débloque un micro-bonus de menace)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_05', 'NPC_ALN_04', 'K1', '{"della","contrats"}', 'Passer par Della `NPC_ALN_76` pour un contrat « propre » (assurance, clauses)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_06', 'NPC_ALN_04', 'K1', '{"clients","avis"}', 'Les groupes à éviter : ceux qui « oublient » de payer (il tient une liste mentale)', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_07', 'NPC_ALN_04', 'K2', '{"trahison","passe"}', 'Une fois, il a laissé mourir un groupe qui l''avait floué — il vérifie encore s''il a eu raison', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_08', 'NPC_ALN_04', 'K2', '{"granzam","exil"}', 'Pourquoi il a quitté Granzam (lien réservé Gnome) — une dette qu''il ne pouvait pas tank', '`+QUEST:QST_NEU_MERC_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_09', 'NPC_ALN_04', 'K3', '{"meurtre","parole"}', 'Il a un jour tué un employeur QUI avait payé, par erreur de chrono — depuis, sa rigidité sur les règles est de l''expiation, pas de la cupidité', NULL, '*(il pose ses deux poings sur la table, lentement)* « On avait dit une heure. J''ai compté juste. J''ai TOUJOURS compté juste. Suivant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_04_10', 'NPC_ALN_04', 'KX', '{"*(hors sujet)*"}', '« Pas payé pour causer. Payé pour tenir. Tu embauches ou pas ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_01', 'NPC_ALN_05', 'K0', '{"services","catalogue"}', 'Tunique de Cuir Zéphyr (Def 300, Vol +10 %, 12 000 Yrds), Bottes de Courant d''Air (20 000)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_02', 'NPC_ALN_05', 'K0', '{"vol","mana"}', 'Ses armures réduisent de 10 % la conso de mana en vol (crucial sur les longues routes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_03', 'NPC_ALN_05', 'K0', '{"routes","conseil"}', 'Quelles pièces pour quelle route aérienne (`ROUTE_*_ALN`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_04', 'NPC_ALN_05', 'K1', '{"craft","tissu"}', 'Elle reconnaît le tissu de chaque race ; conseille un assemblage optimal (bonus léger)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_05', 'NPC_ALN_05', 'K1', '{"zephyrine","rivalite"}', 'Ce qui la sépare de Zephyrine `NPC_ALN_68` : l''une vole, l''autre habille les voleurs de vent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_06', 'NPC_ALN_05', 'K1', '{"swilvane","courses"}', 'Les courses de vent de Swilvane — techniques, pièges, gloire (lien réservé Sylph)', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_07', 'NPC_ALN_05', 'K2', '{"chute","rivale"}', 'La chute qui l''a fait bannir : elle jure que le pli de l''aile n''était pas de sa faute', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_08', 'NPC_ALN_05', 'K2', '{"prototype","interdit"}', 'Elle garde un prototype d''armure « trop rapide » qu''elle refuse de vendre', '`+QUEST:QST_NEU_VOL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_09', 'NPC_ALN_05', 'K3', '{"sabotage","mort"}', 'Elle a saboté l''aile de sa rivale par jalousie — la chute mortelle était son œuvre, pas un accident', NULL, '*(elle lisse une couture qui n''a pas de pli)* « Un mauvais pli, une mauvaise mort. Ça arrive, en course. On coud plus serré, après. C''est tout ce qu''on peut faire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_05_10', 'NPC_ALN_05', 'KX', '{"*(hors sujet)*"}', '« Je vends du vent maîtrisé, pas des ragots. Tu veux voler léger ou pas ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_01', 'NPC_ALN_06', 'K0', '{"services","mise"}', 'Jeux de dés magiques, mises de 100 à 10 000 Yrds ; paris sur duels clandestins', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_02', 'NPC_ALN_06', 'K0', '{"casino","regles"}', 'Règles de la maison, plafonds, cave à jetons', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_03', 'NPC_ALN_06', 'K0', '{"paris","duels"}', 'Les duels se tiennent HORS zone neutre ; Nyx `NPC_ALN_54` prend les paris', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_04', 'NPC_ALN_06', 'K1', '{"jeu","strategie"}', 'Elle « conseille » une stratégie de mise (qui avantage la maison, évidemment)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_05', 'NPC_ALN_06', 'K1', '{"vance","des"}', 'Ce que Vance `NPC_ALN_51` sait faire avec des dés « honnêtes »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_06', 'NPC_ALN_06', 'K1', '{"reseau","gattan"}', 'Le réseau de paris relie Le Tapis Volant à la fosse de Gattan (Sly `NPC_GAT_87`) via Nyx', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_07', 'NPC_ALN_06', 'K2', '{"dettes","sept-doigts"}', 'Comment elle et Sept-Doigts `NPC_ALN_53` se « repassent » les joueurs ruinés', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_08', 'NPC_ALN_06', 'K2', '{"tricheur","marque"}', 'Un joueur triche mieux qu''elle ; elle veut savoir qui (hook enquête)', '`+QUEST:QST_NEU_CASINO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_09', 'NPC_ALN_06', 'K3', '{"dette","ame-liee"}', 'Elle a « gagné » au jeu un objet lié à l''âme d''un joueur — chose impossible, sauf via un contrat de PK vendu sous la zone neutre', NULL, '*(elle fait rouler un jeton sur ses doigts, sourire figé)* « La maison ne triche jamais, mon cœur. Elle observe. Ce que les gens perdent, ils l''avaient déjà lâché. Une autre partie ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_06_10', 'NPC_ALN_06', 'KX', '{"*(hors sujet)*"}', '« Ici on mise, on ne bavarde pas gratis. La mise minimale pour causer, c''est cent Yrds. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_01', 'NPC_ALN_07', 'K0', '{"armes","catalogue"}', 'Cimeterre de Cendres (Atk 900, effet Brûlure — 45 000 Yrds), Poison de Paralysie (5 000 Yrds)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_02', 'NPC_ALN_07', 'K0', '{"ruelle","discretion"}', 'Comment on « ne l''a jamais vu » — code de la ruelle du Dôme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_03', 'NPC_ALN_07', 'K0', '{"anti-pk","ville"}', 'Pourquoi il ne craint rien tant qu''il reste en zone neutre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_04', 'NPC_ALN_07', 'K1', '{"saignement","effets"}', 'Ce que font vraiment ses lames militaires (DOT saignement, spec de la garde)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_05', 'NPC_ALN_07', 'K1', '{"voulg","garde"}', 'L''organisation de la garde d''Eugene qu''il a désertée — failles comprises', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_06', 'NPC_ALN_07', 'K1', '{"contrebande","morne"}', 'Comment ses stocks entrent en ville (Morne `NPC_ALN_55`, Rask `NPC_ALN_57`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_07', 'NPC_ALN_07', 'K2', '{"client","quantite"}', 'Un client anonyme lui commande dix fois trop d''armes — pour quoi faire ?', '`AFF>=85+PAY:500`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_08', 'NPC_ALN_07', 'K2', '{"eugene","prime"}', 'Ce qu''il donnerait pour savoir si Voulg a lancé une prime sur lui', '`QUEST:QST_NEU_RENEGAT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_09', 'NPC_ALN_07', 'K3', '{"cellule","anti-pk"}', 'Son gros client veut armer une cellule pour BRISER l''anti-PK d''Alne — Kael a compris et continue de vendre', NULL, '*(il rabat sa capuche)* « Je vends des lames, pas des intentions. Ce que les gens en font, ça les regarde. La ruelle est fermée pour toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_07_10', 'NPC_ALN_07', 'KX', '{"*(hors sujet)*"}', '« Je ne sais rien, je n''ai rien vu, et toi non plus. On est d''accord. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_01', 'NPC_ALN_08', 'K0', '{"conclave","neutralite"}', 'Le rôle du Conclave et la loi anti-PK d''Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_02', 'NPC_ALN_08', 'K0', '{"litiges","audience"}', 'Comment obtenir audience et déposer un litige inter-races', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_03', 'NPC_ALN_08', 'K0', '{"races","protocole"}', 'Le protocole de cohabitation des 9 races en ville neutre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_04', 'NPC_ALN_08', 'K1', '{"diplomatie","tensions"}', 'L''état réel des tensions entre territoires (lecture d''initié)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_05', 'NPC_ALN_08', 'K1', '{"conclave","factions"}', 'Qui, au Conclave, pousse pour ou contre l''ouverture d''Alne', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_06', 'NPC_ALN_08', 'K1', '{"garde","silene"}', 'Les prérogatives des Sentinelles de l''Arbre (Silène `NPC_ALN_09`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_07', 'NPC_ALN_08', 'K2', '{"cellule","rumeur"}', 'Une cellule chercherait à briser l''anti-PK — ce qu''il en sait et tait par calcul', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_08', 'NPC_ALN_08', 'K2', '{"cyd","mefiance"}', 'Pourquoi il ne fait pas confiance à son propre émissaire Cyd `NPC_ALN_94`', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_09', 'NPC_ALN_08', 'K2', '{"pouvoir","verite"}', 'L''aveu à demi-mot : « ma parole ne tient pas la paix. Autre chose la tient. »', '`TITLE:TITLE_NEU_MEDIATEUR`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_10', 'NPC_ALN_08', 'K3', '{"anti-pk","systeme"}', 'La neutralité est un invariant du Système Cardinal, pas un décret du Conclave ; son autorité est décorative', NULL, '*(il joint les mains)* « La paix d''Alne repose sur des fondations plus anciennes que moi. C''est tout ce qu''un Custode doit savoir. Et tout ce que je dirai. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_11', 'NPC_ALN_08', 'K3', '{"faille","silene"}', 'Il existe UNE faille à l''anti-PK ; seule Silène `NPC_ALN_09` en connaît la mécanique, sur son ordre', NULL, '« Il n''y a pas de faille. Répète-le assez souvent et c''est vrai. Bonne journée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_08_12', 'NPC_ALN_08', 'KX', '{"*(hors sujet)*"}', '« Cette question ne relève pas du Conclave. Adressez-vous à qui de droit. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_01', 'NPC_ALN_09', 'K0', '{"garde","ordre"}', 'Le rôle des Sentinelles et les règles de sécurité d''Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_02', 'NPC_ALN_09', 'K0', '{"anti-pk","sanction"}', 'Ce qui arrive à qui tente d''attaquer en zone neutre (téléport + gel d''action)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_03', 'NPC_ALN_09', 'K0', '{"entrainement","halle"}', 'Où s''entraîner en ville et à qui s''adresser (Roan `NPC_ALN_69`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_04', 'NPC_ALN_09', 'K1', '{"tactique","patrouilles"}', 'Le dispositif de patrouille, angles morts inclus', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_05', 'NPC_ALN_09', 'K1', '{"menaces","evaluation"}', 'Son évaluation franche des menaces réelles sur la neutralité', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_06', 'NPC_ALN_09', 'K1', '{"recrues","sentinelles"}', 'Comment on rejoint les Sentinelles (quête d''engagement neutre)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_07', 'NPC_ALN_09', 'K2', '{"cellule","filature"}', 'Ce que ses Sentinelles ont relevé sur une cellule anti-neutralité', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_08', 'NPC_ALN_09', 'K2', '{"kael","armes"}', 'Elle soupçonne Kael `NPC_ALN_07` d''armer quelqu''un — sans preuve exploitable en zone neutre', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_09', 'NPC_ALN_09', 'K2', '{"brogg","anti-pk"}', 'Comment Brogg `NPC_ALN_52` « sort » les fauteurs sans les toucher (mécanique anti-PK exploitée)', '`TITLE:TITLE_NEU_SENTINELLE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_10', 'NPC_ALN_09', 'K3', '{"faille","exploit"}', 'La faille unique de l''anti-PK : un instant, un lieu précis où le Système « cligne » — elle en garde le secret pour le colmater', NULL, '*(elle pose la main sur son fourreau)* « Il n''y a rien à trouver. Et si tu cherches encore, tu me trouveras, moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_11', 'NPC_ALN_09', 'K3', '{"verite","systeme"}', 'Elle sait que ses troupes sont décoratives : c''est le Cardinal, pas elles, qui tient la paix', NULL, '« Mes Sentinelles tiennent Alne. C''est la seule version qui existe. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_09_12', 'NPC_ALN_09', 'KX', '{"*(hors sujet)*"}', '« Ce n''est pas du ressort de la garde. Circulez. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_100_01', 'NPC_ALN_100', 'K0', '{"guilde","création"}', 'Pour créer une guilde, il faut être au moins niveau 10 et rassembler 5 signatures.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_100_02', 'NPC_ALN_100', 'K0', '{"guilde","avantages"}', 'Les guildes débloquent un chat privé, un coffre commun et des bonus d''expérience en groupe.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_100_03', 'NPC_ALN_100', 'K1', '{"guilde","quartier général"}', 'Le QG de guilde peut être amélioré jusqu''au niveau 5, débloquant des services comme l''atelier d''artisanat et la salle des trophées.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_100_04', 'NPC_ALN_100', 'K2', '{"guilde","alliance"}', 'Les guildes de niveau 15+ peuvent former des alliances temporaires pour les raids interraciaux.', 'AFF>=60+QUEST:QST_GUILD_ALLIANCE_01', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_102_01', 'NPC_ALN_102', 'K0', '{"quête","guide"}', 'Les quêtes de guilde sont renouvelées chaque semaine. Les membres actifs gagnent des points de réputation.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_102_02', 'NPC_ALN_102', 'K1', '{"chasse","territoire"}', 'Les contrats de chasse sont adaptés à ton niveau. Je te conseille les Collines Verdoyantes pour commencer : des sangliers, pas de boss.', 'AFF>=30', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_102_03', 'NPC_ALN_102', 'K2', '{"exploration","Yggdrasil"}', 'Personne n''est jamais monté tout en haut d''Yggdrasil sans une escorte. Si tu veux tenter le Tronc, prépare-toi à croiser des racines éveillées.', 'AFF>=60', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_103_01', 'NPC_ALN_103', 'K0', '{"enregistrement","guilde"}', 'L''enregistrement est gratuit. La cotisation mensuelle est de 200 Yrds par membre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_103_02', 'NPC_ALN_103', 'K0', '{"annuaire","guildes"}', 'Il y a actuellement quelques guildes actives à Alne. La plus ancienne est la Confrérie du Dôme.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_103_03', 'NPC_ALN_103', 'K1', '{"guilde","nom","règles"}', 'Le nom de guilde ne peut pas comporter plus de 32 caractères, ni contenir de termes offensants. Aucun doublon n''est accepté.', 'AFF>=20', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_01', 'NPC_ALN_10', 'K0', '{"routes","horaires"}', 'Les 9 routes aériennes, quais, cloches de départ vers chaque cité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_02', 'NPC_ALN_10', 'K0', '{"tarifs","montures"}', 'Tarifs de passage et où louer une monture (Wick `NPC_ALN_84`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_03', 'NPC_ALN_10', 'K0', '{"dangers","mob-air"}', 'Les routes traversées par les `MOB_AIR_*` — vigie Corvin `NPC_ALN_16` prévient', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_04', 'NPC_ALN_10', 'K1', '{"trafic","flux"}', 'Qui voyage vers où en ce moment — lecture des flux inter-cités', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_05', 'NPC_ALN_10', 'K1', '{"caravanes","marchandises"}', 'Quelles marchandises transitent, d''où, vers quel marché', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_06', 'NPC_ALN_10', 'K1', '{"retards","blocus"}', 'Quelles routes sont perturbées (relais des événements orchestrateur : blocus, guerre)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_07', 'NPC_ALN_10', 'K2', '{"passager","discret"}', 'Il a laissé embarquer un passager sans registre — contre un très bon pourboire', '`AFF>=85+PAY:300`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_08', 'NPC_ALN_10', 'K2', '{"fret","suspect"}', 'Un fret « d''outils agricoles » vers la Ruelle du Dôme qui pesait le poids de l''acier', '`QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_09', 'NPC_ALN_10', 'K3', '{"registre","disparus"}', 'Son registre prouve que certains partis au Dôme ne sont jamais redescendus — il maquille les chiffres pour ne pas fermer les quais', NULL, '*(il referme son grand livre)* « Mes registres sont à jour et exacts. Tous mes voyageurs arrivent. Tous. Suivant ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_10_10', 'NPC_ALN_10', 'KX', '{"*(hors sujet)*"}', '« Ça ne figure sur aucun de mes tableaux, donc ça n''existe pas. Prochain quai ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_01', 'NPC_ALN_11', 'K0', '{"signaux","arrivees"}', 'Comment lire les fanions d''arrivée/départ des 9 routes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_02', 'NPC_ALN_11', 'K0', '{"securite","vol"}', 'Consignes de vol en approche d''Alne (couloirs, priorités)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_03', 'NPC_ALN_11', 'K0', '{"corvin","essaims"}', 'Quand les essaims aériens ferment une route (renvoi Corvin `NPC_ALN_16`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_04', 'NPC_ALN_11', 'K1', '{"trafic","comptage"}', 'Qui est parti vers quelle cité aujourd''hui, et à quelle heure', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_05', 'NPC_ALN_11', 'K1', '{"retards","incidents"}', 'Les incidents de route récents (chutes, attaques, disparitions)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_06', 'NPC_ALN_11', 'K1', '{"routes","meteo"}', 'L''état des couloirs aériens (vents, brumes de la Canopée)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_07', 'NPC_ALN_11', 'K2', '{"disparus","dome"}', 'Sa liste des « partis pour l''Arbre, jamais redescendus » — plus longue chaque mois', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_08', 'NPC_ALN_11', 'K2', '{"passager","fantome"}', 'Elle a vu redescendre quelqu''un qui n''était jamais monté — impossible sur ses registres', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_09', 'NPC_ALN_11', 'K3', '{"asymetrie","systeme"}', 'Le compte des montées ≠ redescentes ne se referme jamais ; elle soupçonne que « le Dôme garde » certains joueurs hors du monde', NULL, '*(elle repose sa lanterne)* « Mes comptes tombent juste. Toujours. Si tu crois manquer quelqu''un, c''est qu''il a pris une autre route. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_11_10', 'NPC_ALN_11', 'KX', '{"*(hors sujet)*"}', '« Je regarde le ciel, pas ça. Demande en bas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_01', 'NPC_ALN_12', 'K0', '{"dome","acces"}', 'Comment monter au Dôme `ZONE_YGG_DUN_001`, conditions de niveau, groupe recommandé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_02', 'NPC_ALN_12', 'K0', '{"regles","raid"}', 'Règles du seuil : pas de PK, inscription du raid, ordre de passage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_03', 'NPC_ALN_12', 'K0', '{"prep","bran"}', 'Où se préparer avant de monter (renvoi Bran `NPC_ALN_73`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_04', 'NPC_ALN_12', 'K1', '{"etages","dangers"}', 'Ce qu''il sait des premiers étages du Dôme (dangers publics, mécaniques connues)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_05', 'NPC_ALN_12', 'K1', '{"registre","raids"}', 'Quels groupes sont montés récemment, sous quelle bannière', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_06', 'NPC_ALN_12', 'K1', '{"ascenseur","mund"}', 'Le fonctionnement de l''ascenseur de sève (renvoi Mund `NPC_ALN_17`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_07', 'NPC_ALN_12', 'K2', '{"changes","retour"}', 'Comment il reconnaît ceux qui redescendent « autres » — le regard, les silences', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_08', 'NPC_ALN_12', 'K2', '{"etage","hors-carte"}', 'Un raid a rapporté avoir traversé un étage qui n''était pas sur le plan de Torin `NPC_ALN_14`', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_09', 'NPC_ALN_12', 'K3', '{"garde","verrou"}', 'Il a l''ordre de ne JAMAIS empêcher une montée, même quand il sait que le groupe ne redescendra pas — l''ordre vient « d''en haut », plus haut que le Conclave', NULL, '*(il croise ses bras massifs)* « La Porte s''ouvre. C''est mon seul travail, et je le fais bien. Ce qu''il y a derrière ne me regarde pas. Ni toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_12_10', 'NPC_ALN_12', 'KX', '{"*(hors sujet)*"}', '« Ça, c''est de l''autre côté de la Porte. Va voir toi-même, ou n''en parle plus. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_01', 'NPC_ALN_13', 'K0', '{"registre","deposition"}', 'Comment déposer un compte-rendu d''expédition et consulter les archives publiques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_02', 'NPC_ALN_13', 'K0', '{"dome","etages-connus"}', 'Les étages du Dôme officiellement cartographiés et leurs boss connus', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_03', 'NPC_ALN_13', 'K0', '{"raids","bannieres"}', 'Quels groupes détiennent quels records de progression', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_04', 'NPC_ALN_13', 'K1', '{"recoupements","motifs"}', 'Les récits qui « riment » entre expéditions différentes — son domaine', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_05', 'NPC_ALN_13', 'K1', '{"butins","drops"}', 'Ce qui remonte du Dôme (drops rares consignés, prix de rachat)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_06', 'NPC_ALN_13', 'K1', '{"disparus","comptage"}', 'Recoupe avec Wrenna `NPC_ALN_11` la liste des non-revenus', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_07', 'NPC_ALN_13', 'K2', '{"recits","identiques"}', 'Trois dépositions mot pour mot pour un étage que personne n''a co-visité', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_08', 'NPC_ALN_13', 'K2', '{"aldous","temoignage"}', 'Ce qu''Aldous `NPC_ALN_74` a d''abord déclaré — avant de « corriger » son récit', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_09', 'NPC_ALN_13', 'K3', '{"reecriture","memoire"}', 'Elle soupçonne que le Dôme (ou le Système) réécrit les souvenirs de ceux qui montent — ses propres notes anciennes changent parfois de mot', NULL, '*(elle ferme sèchement un tiroir)* « Mes archives sont exactes et immuables. Si un détail vous semble bouger, c''est votre mémoire, pas la mienne. Au suivant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_13_10', 'NPC_ALN_13', 'KX', '{"*(hors sujet)*"}', '« Ça n''est consigné nulle part. Donc je n''en ai rien à dire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_01', 'NPC_ALN_14', 'K0', '{"dome","initiation"}', 'Comment aborder les premiers étages du Dôme en sécurité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_02', 'NPC_ALN_14', 'K0', '{"pieges","salles"}', 'Les pièges publics des niveaux bas et comment les passer', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_03', 'NPC_ALN_14', 'K0', '{"groupe","roles"}', 'Quelle composition de groupe pour une première montée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_04', 'NPC_ALN_14', 'K1', '{"raccourcis","cartes"}', 'Les raccourcis qu''il connaît et vend sous forme de guidage', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_05', 'NPC_ALN_14', 'K1', '{"mobs-bas","drops"}', 'Les mobs des étages bas, leurs faiblesses et ce qu''ils lâchent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_06', 'NPC_ALN_14', 'K1', '{"seve","environnement"}', 'Comment la sève d''Yggdrasil modifie les salles (jauge environnementale du Dôme)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_07', 'NPC_ALN_14', 'K2', '{"etage","hors-carte"}', 'L''existence de « l''étage qui n''est sur aucune carte » — il en décrit l''entrée, jamais retrouvée', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_08', 'NPC_ALN_14', 'K2', '{"droite","interdit"}', 'Pourquoi « on ne prend jamais à droite » au deuxième embranchement', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_09', 'NPC_ALN_14', 'K3', '{"seul","disparu"}', 'Ce qu''il a vu quand il a traversé cet étage seul — et pourquoi il n''en parle qu''à mots couverts', NULL, '*(il fixe la racine, immobile)* « J''ai dû rêver ce couloir. Un guide qui parle de couloirs rêvés, on ne l''engage plus. Alors je n''en parle pas. Et toi non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_14_10', 'NPC_ALN_14', 'KX', '{"*(hors sujet)*"}', '« Ça, c''est pas dans le Dôme. Donc c''est pas mon rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_01', 'NPC_ALN_15', 'K0', '{"seve","catalogue"}', 'Sève d''Yggdrasil, mousses de racine, champignons luminescents — prix et usages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_02', 'NPC_ALN_15', 'K0', '{"composants","alchimie"}', 'Quelle flore pour quelles potions (renvoi alchimistes Corvus `NPC_ALN_72` / Ophrys `NPC_ALN_28`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_03', 'NPC_ALN_15', 'K0', '{"recolte","racines"}', 'Où cueillir en sécurité aux Racines, et quand la sève « monte »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_04', 'NPC_ALN_15', 'K1', '{"flore-rare","noeuds"}', 'Les nœuds de récolte rares et leurs cycles de repousse', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_05', 'NPC_ALN_15', 'K1', '{"seve-pale","effets"}', 'Les propriétés de la Sève Pâle (composant de haut tier, purification)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_06', 'NPC_ALN_15', 'K1', '{"enfant","racine"}', 'Ce qu''elle croit savoir de « l''orphelin » des Racines (renvoi voilé à `NPC_ALN_00`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_07', 'NPC_ALN_15', 'K2', '{"feuille","unique"}', 'La Feuille de Sève Pâle cueillie une seule fois — sur un arbuste jamais revu', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_08', 'NPC_ALN_15', 'K2', '{"verger","rumeur"}', 'Ce que l''Enfant lui a murmuré sur « le jardin qui n''est là que si on ne le cherche pas »', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_09', 'NPC_ALN_15', 'K3', '{"anomalie","racine"}', 'Sa conviction que la flore la plus rare pousse dans une zone des Racines qui n''existe pas sur la carte — et que le Système la fait apparaître par intermittence', NULL, '*(elle presse son herbier contre elle)* « J''ai dû me tromper d''endroit, voilà tout. Une botaniste qui invente des jardins, ça ne vend plus une graine. On oublie. Tu voulais de la mousse ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_15_10', 'NPC_ALN_15', 'KX', '{"*(hors sujet)*"}', '« Moi je connais les plantes, pas ça. Demande en haut, en ville. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_01', 'NPC_ALN_16', 'K0', '{"mob-air","alerte"}', 'Quand un essaim ferme une route et combien de temps (partagé avec Wrenna `NPC_ALN_11`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_02', 'NPC_ALN_16', 'K0', '{"canopee","acces"}', 'Comment monter au poste de guet et lire les signaux d''alerte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_03', 'NPC_ALN_16', 'K0', '{"vol","securite"}', 'Consignes de vol quand la Canopée signale un danger', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_04', 'NPC_ALN_16', 'K1', '{"essaims","comportement"}', 'Les habitudes des `MOB_AIR_*` : routes de migration, heures d''attaque', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_05', 'NPC_ALN_16', 'K1', '{"chasse","drops"}', 'Où et quand chasser les mobs aériens, ce qu''ils lâchent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_06', 'NPC_ALN_16', 'K1', '{"meteo","canopee"}', 'Les vents et brumes de la Canopée qui affectent le vol', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_07', 'NPC_ALN_16', 'K2', '{"essaim","anormal"}', 'Les essaims tournent désormais AU-DESSUS de l''Arbre au lieu de le fuir — anomalie qu''il signale sans réponse', '`AFF>=85+QUEST:QST_NEU_CANOPEE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_08', 'NPC_ALN_16', 'K2', '{"forme","silhouette"}', 'Une silhouette ailée, trop grande pour un mob connu, aperçue près du sommet', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_09', 'NPC_ALN_16', 'K3', '{"attraction","dome"}', 'Il est convaincu que quelque chose au sommet du Dôme ATTIRE les essaims — et que ça grandit', NULL, '*(il ne quitte pas le ciel des yeux)* « Les bêtes font ce que font les bêtes. Je compte des ailes, je ne devine pas des raisons. Redescends, le poste est étroit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_16_10', 'NPC_ALN_16', 'KX', '{"*(hors sujet)*"}', '« Ça se passe au sol. Le sol, c''est pas mon poste. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_01', 'NPC_ALN_17', 'K0', '{"ascenseur","usage"}', 'Comment embarquer pour le Dôme, capacité, sécurité de la cabine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_02', 'NPC_ALN_17', 'K0', '{"etages","desserte"}', 'Quels étages l''ascenseur dessert officiellement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_03', 'NPC_ALN_17', 'K0', '{"attente","ordre"}', 'L''ordre de passage des raids (renvoi Dorn `NPC_ALN_12`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_04', 'NPC_ALN_17', 'K1', '{"cabine","entretien"}', 'Les à-coups normaux, ce qui est sûr et ce qui ne l''est pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_05', 'NPC_ALN_17', 'K1', '{"seve","mecanisme"}', 'Comment la sève d''Yggdrasil « alimente » la cabine (mécanique du Dôme)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_06', 'NPC_ALN_17', 'K1', '{"raids","habitues"}', 'Quels groupes montent souvent, à quelles heures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_07', 'NPC_ALN_17', 'K2', '{"palier","non-commande"}', 'La cabine s''arrête parfois à un palier qu''il n''a pas actionné', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_08', 'NPC_ALN_17', 'K2', '{"couloir","inconnu"}', 'Ce qu''il aperçoit quand les portes s''ouvrent sur ce palier — le couloir de Torin `NPC_ALN_14` ?', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_09', 'NPC_ALN_17', 'K3', '{"controle","systeme"}', 'Il est certain que quelqu''un — ou quelque chose — commande sa cabine par-dessus lui, depuis « plus haut que le levier »', NULL, '*(il agrippe sa manivelle)* « L''ascenseur monte, l''ascenseur descend, c''est moi qui le tiens. Toujours moi. Fin de la course, tout le monde descend. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_17_10', 'NPC_ALN_17', 'KX', '{"*(hors sujet)*"}', '« J''opère la cabine, je ne fais pas la conversation. Prochaine montée dans un instant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_01', 'NPC_ALN_18', 'K0', '{"cartes","catalogue"}', 'Cartes des 9 territoires, plans de villes, axe vertical — prix et éditions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_02', 'NPC_ALN_18', 'K0', '{"routes","distances"}', 'Distances et temps de voyage entre cités (complète le Débarcadère)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_03', 'NPC_ALN_18', 'K0', '{"zones","dangers"}', 'Les niveaux de danger indiqués par zone sur ses cartes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_04', 'NPC_ALN_18', 'K1', '{"releves","sources"}', 'Comment elle compile ses relevés, et lesquels sont fiables', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_05', 'NPC_ALN_18', 'K1', '{"secrets","passages"}', 'Passages cachés et raccourcis vendus en éditions « premium »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_06', 'NPC_ALN_18', 'K1', '{"frontieres","anneau"}', 'La logique de l''anneau frontalier entre territoires (atlas maître)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_07', 'NPC_ALN_18', 'K2', '{"brume","blanc"}', 'La « zone de brume » qui masque en réalité un blanc qu''elle refuse de dessiner', '`AFF>=85+QUEST:QST_NEU_CARTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_08', 'NPC_ALN_18', 'K2', '{"cartographes","disparus"}', 'Les trois cartographes partis relever ce blanc et jamais revenus', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_09', 'NPC_ALN_18', 'K3', '{"region","effacee"}', 'Elle est convaincue qu''une région du monde est activement EFFACÉE des cartes — chaque copie qu''elle dessine la « perd » toute seule à l''encre', NULL, '*(elle roule vivement un parchemin)* « Il n''y a pas de région manquante. Il y a de la brume. La brume, sur une carte, ça veut dire " n''y allez pas ". Vous vouliez quelle édition ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_18_10', 'NPC_ALN_18', 'KX', '{"*(hors sujet)*"}', '« Ce n''est pas un lieu, donc ce n''est pas sur mes cartes, donc je n''en sais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_01', 'NPC_ALN_19', 'K0', '{"halte","services"}', 'Repas, lit, repos — tarifs de la halte, restauration HP/MP légère', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_02', 'NPC_ALN_19', 'K0', '{"route","acces"}', 'La route périphérique et l''approche d''Alne par la terre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_03', 'NPC_ALN_19', 'K0', '{"neutralite","regle"}', 'Sa règle « pas de nom, pas de registre »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_04', 'NPC_ALN_19', 'K1', '{"voyageurs","ambiance"}', 'Qui passe par la route en ce moment, l''humeur des chemins', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_05', 'NPC_ALN_19', 'K1', '{"refugies","arrivees"}', 'Les exilés et déserteurs qui affluent vers Alne (Vorn `NPC_ALN_90` & co.)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_06', 'NPC_ALN_19', 'K1', '{"dangers","route"}', 'Les dangers de la route périphérique, où camper, quoi éviter', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_07', 'NPC_ALN_19', 'K2', '{"client","sans-visage"}', 'Un habitué encapuchonné qu''il héberge chaque mois et n''a jamais vu en face', '`AFF>=85+PAY:200`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_08', 'NPC_ALN_19', 'K2', '{"cargaison","cachee"}', 'Ce que Rask `NPC_ALN_57` entrepose « juste une nuit » dans sa grange', '`QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_09', 'NPC_ALN_19', 'K3', '{"complices","aveugle"}', 'Il SAIT que sa halte sert de sas à des trafics et à la cellule anti-neutralité — il choisit l''aveuglement pour ne pas trahir sa règle sacrée', NULL, '*(il essuie un bol, sans lever les yeux)* « Je ne sais rien de mes clients. C''est toute la maison. Le jour où je saurai, la halte fermera. Alors je ne saurai jamais. Encore un peu de soupe ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_19_10', 'NPC_ALN_19', 'KX', '{"*(hors sujet)*"}', '« Ça dépasse ma halte, ça. Moi je m''arrête à la porte. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_01', 'NPC_ALN_20', 'K0', '{"bibliotheque","acces"}', 'Horaires, règles de consultation, où trouver Valerius `NPC_ALN_01`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_02', 'NPC_ALN_20', 'K0', '{"classement","rayons"}', 'Comment sont rangés les ouvrages (histoire, races, quêtes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_03', 'NPC_ALN_20', 'K0', '{"copie","service"}', 'Le service de recopie de parchemins et ses délais (renvoi Denn `NPC_ALN_23`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_04', 'NPC_ALN_20', 'K1', '{"ouvrages","histoire"}', 'Ce qu''elle a appris à recopier sur les guerres raciales (version officielle)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_05', 'NPC_ALN_20', 'K1', '{"valerius","methode"}', 'Comment travaille son maître, ce qu''il accepte de traduire ou non', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_06', 'NPC_ALN_20', 'K1', '{"livres-rares","localisation"}', 'Où sont rangés les ouvrages sous restriction (sans y donner accès)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_07', 'NPC_ALN_20', 'K2', '{"livre","interdit"}', 'Le livre qu''on lui a interdit de lire — et ce qu''elle y a lu malgré tout', '`AFF>=85+QUEST:QST_NEU_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_08', 'NPC_ALN_20', 'K2', '{"texte","change"}', 'Sa preuve : une copie datée qui ne correspond plus à l''original', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_09', 'NPC_ALN_20', 'K3', '{"reecriture","peur"}', 'Elle est terrifiée que ce soit Valerius lui-même — ou ce qu''il sert — qui réécrive l''histoire, page après page', NULL, '*(elle range précipitamment ses copies)* « Je n''ai rien lu. Un copiste ne lit pas. Maître Valerius me l''a dit. S''il te plaît, ne lui répète pas que j''ai posé la question. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_20_10', 'NPC_ALN_20', 'KX', '{"*(hors sujet)*"}', '« Ça, ce n''est pas dans les livres que je classe. Je ne saurais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_01', 'NPC_ALN_21', 'K0', '{"reliure","service"}', 'Réparation d''ouvrages, tarifs, délais de restauration', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_02', 'NPC_ALN_21', 'K0', '{"materiaux","papiers"}', 'Les papiers et cuirs des 9 races, comment on reconnaît chacun', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_03', 'NPC_ALN_21', 'K0', '{"bibliotheque","ancien"}', 'Où sont conservés les ouvrages les plus anciens', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_04', 'NPC_ALN_21', 'K1', '{"restauration","technique"}', 'Comment il devine l''âge et l''origine d''un livre au toucher', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_05', 'NPC_ALN_21', 'K1', '{"livres-rares","valeur"}', 'Quels ouvrages anciens valent une fortune (et à qui les vendre)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_06', 'NPC_ALN_21', 'K1', '{"encres","datation"}', 'Comment dater une encre — savoir-faire qui trahit les faux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_07', 'NPC_ALN_21', 'K2', '{"pages","changent"}', 'Les pages qui se réécrivent seules sous verre, la nuit', '`AFF>=85+QUEST:QST_NEU_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_08', 'NPC_ALN_21', 'K2', '{"encre","impossible"}', 'Une encre « plus jeune que le papier » — datation impossible qui prouve la réécriture', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_09', 'NPC_ALN_21', 'K3', '{"histoire","falsifiee"}', 'Il a comparé assez d''éditions pour l''affirmer : l''histoire officielle des guerres raciales a été RÉÉCRITE après coup, et ça continue', NULL, '*(il repose son plioir, très lentement)* « Les livres disent ce qu''ils disent. Un relieur recolle, il ne juge pas le texte. Le mien s''arrête à la couverture. Repasse chercher ton ouvrage demain. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_21_10', 'NPC_ALN_21', 'KX', '{"*(hors sujet)*"}', '« Ça, c''est pas dans mes reliures. Demande à ceux qui lisent, pas à ceux qui recollent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_01', 'NPC_ALN_22', 'K0', '{"traduction","tarifs"}', 'Services de traduction, déchiffrage de grimoires, dictionnaires en vente', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_02', 'NPC_ALN_22', 'K0', '{"langues","races"}', 'Les 9 langues raciales et leurs usages courants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_03', 'NPC_ALN_22', 'K0', '{"quetes","livres"}', 'Comment elle traduit les « Livres Anciens » pour les quêtes de Valerius `NPC_ALN_01`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_04', 'NPC_ALN_22', 'K1', '{"dialectes","morts"}', 'Les dialectes disparus qu''elle seule lit encore', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_05', 'NPC_ALN_22', 'K1', '{"grimoires","dechiffrage"}', 'Ce qu''elle a déchiffré de plus rare, et pour qui', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_06', 'NPC_ALN_22', 'K1', '{"inscriptions","dome"}', 'Les inscriptions des étages du Dôme qu''on lui rapporte à traduire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_07', 'NPC_ALN_22', 'K2', '{"mot","sans-langue"}', 'Le mot qui n''appartient à aucune langue — et qu''elle a pourtant compris', '`AFF>=85+QUEST:QST_NEU_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_08', 'NPC_ALN_22', 'K2', '{"dixieme","langue"}', 'Sa conviction qu''il existe une « dixième langue », celle des inscriptions qui changent', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_09', 'NPC_ALN_22', 'K3', '{"langue","systeme"}', 'Elle pense que cette langue est celle du Système lui-même — la « langue-source » dans laquelle le monde est écrit, et réécrit', NULL, '*(elle referme son lexique d''un claquement)* « Neuf langues. Il n''y en a que neuf. Le reste, c''est du gribouillis de joueur mal réveillé. Tu as un texte à traduire, oui ou non ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_22_10', 'NPC_ALN_22', 'KX', '{"*(hors sujet)*"}', '« Ça ne se traduit pas, parce que ce n''est pas un mot. Suivant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_01', 'NPC_ALN_23', 'K0', '{"copie","tarifs"}', 'Copie de parchemins, cartes, documents — tarifs officiels et délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_02', 'NPC_ALN_23', 'K0', '{"parchemins","skill"}', 'Quels parchemins de skill se copient légalement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_03', 'NPC_ALN_23', 'K0', '{"bibliotheque","demarches"}', 'Comment commander une copie certifiée conforme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_04', 'NPC_ALN_23', 'K1', '{"copies","officieuses"}', 'Les copies « arrangées » de quêtes qu''il vend sous le manteau', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_05', 'NPC_ALN_23', 'K1', '{"contournement","ordre"}', 'Comment sauter l''ordre d''obtention prévu d''une chaîne de quête', '`AFF>=65+PAY:150`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_06', 'NPC_ALN_23', 'K1', '{"osk","ecoulement"}', 'Comment Osk `NPC_ALN_33` écoule ses copies au marché', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_07', 'NPC_ALN_23', 'K2', '{"quill","faux"}', 'Les commandes qu''il sous-traite à Quill `NPC_ALN_56` (faux documents)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_08', 'NPC_ALN_23', 'K2', '{"copie","alteree"}', 'Des lignes apparaissent dans ses copies qu''il jure n''avoir jamais écrites', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_09', 'NPC_ALN_23', 'K3', '{"trame","sabotage"}', 'Il a compris que ses copies « officieuses » désynchronisent la trame des quêtes — et que quelqu''un exploite ses duplicatas pour glisser de faux textes dans la Bibliothèque', NULL, '*(il empile ses parchemins, le sourire crispé)* « Je copie ce qu''on me donne, mot pour mot. Si un mot n''est pas à sa place, c''est l''original, pas moi. Tu voulais une copie, ou une leçon de morale ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_23_10', 'NPC_ALN_23', 'KX', '{"*(hors sujet)*"}', '« Je copie, je ne compose pas. Ça, ce n''est pas de ma plume. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_01', 'NPC_ALN_24', 'K0', '{"etals","attribution"}', 'Comment obtenir un emplacement au Marché Circulaire, tarifs officiels', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_02', 'NPC_ALN_24', 'K0', '{"marche","plan"}', 'Le plan du marché : qui vend quoi et où', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_03', 'NPC_ALN_24', 'K0', '{"reglement","horaires"}', 'Le règlement des marchands, horaires d''ouverture, jours de grand marché', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_04', 'NPC_ALN_24', 'K1', '{"emplacements","valeur"}', 'Quels étals rapportent le plus, lesquels sont maudits', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_05', 'NPC_ALN_24', 'K1', '{"marchands","rivalites"}', 'Les rivalités commerciales du marché (qui déteste qui)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_06', 'NPC_ALN_24', 'K1', '{"loyers","impayes"}', 'Qui est en retard de loyer et risque l''expulsion', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_07', 'NPC_ALN_24', 'K2', '{"arrangement","faveur"}', 'Comment obtenir un bon emplacement « contre service » plutôt qu''en Yrds', '`AFF>=80+QUEST:QST_NEU_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_08', 'NPC_ALN_24', 'K2', '{"courtiers","information"}', 'Ce que Grède `NPC_ALN_26` et Cassia `NPC_ALN_25` lui paient en renseignements', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_09', 'NPC_ALN_24', 'K3', '{"placement","guerre"}', 'Il place stratégiquement les marchands pour attiser ou apaiser la guerre économique inter-races — sur ordre d''un commanditaire qu''il ne nomme pas', NULL, '*(il tapote son registre d''attribution)* « J''attribue des étals selon le mérite et l''ancienneté. Rien d''autre. Si vous voyez des intentions dans un plan de marché, consultez un guérisseur. Suivant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_24_10', 'NPC_ALN_24', 'KX', '{"*(hors sujet)*"}', '« Ça ne concerne pas les étals, donc ça ne me concerne pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_01', 'NPC_ALN_25', 'K0', '{"reputation","service"}', 'Comment améliorer sa réputation auprès d''une race (services, faveurs)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_02', 'NPC_ALN_25', 'K0', '{"factions","standing"}', 'Ce que le standing racial ouvre ou ferme (prix, quêtes, accès)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_03', 'NPC_ALN_25', 'K0', '{"tarifs","courtage"}', 'Ses tarifs de courtage de réputation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_04', 'NPC_ALN_25', 'K1', '{"faveurs","echanges"}', 'Quelles faveurs rachètent quel discrédit, race par race', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_05', 'NPC_ALN_25', 'K1', '{"dettes","reseau"}', 'Le réseau de dettes de réputation entre grands acteurs d''Alne', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_06', 'NPC_ALN_25', 'K1', '{"rumeurs","wisp"}', 'Comment une rumeur de Wisp `NPC_ALN_58` fait chuter une réputation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_07', 'NPC_ALN_25', 'K2', '{"dossier","joueur"}', 'Le « dossier de réputation » qu''elle tient sur un joueur/guilde précis', '`AFF>=85+PAY:400`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_08', 'NPC_ALN_25', 'K2', '{"manipulation","standing"}', 'Comment elle fabrique de toutes pièces un discrédit pour vendre ensuite le remède', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_09', 'NPC_ALN_25', 'K3', '{"guerre","proxy"}', 'Son grand livre sert une guerre économique proxy inter-races : elle vend à chaque camp le discrédit de l''autre, entretenant un conflit qui la nourrit', NULL, '*(elle referme un éventail peint)* « Je répare des réputations, mon chou. Je ne les casse jamais. Que gagnerais-je à casser ce que je vends ? Alors — on rachète la tienne ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_25_10', 'NPC_ALN_25', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas de valeur de réputation, donc ça ne m''intéresse pas. Passe ton chemin. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_01', 'NPC_ALN_26', 'K0', '{"denrees","cours"}', 'Les cours des denrées inter-raciales, où c''est cher, où c''est bon marché', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_02', 'NPC_ALN_26', 'K0', '{"courtage","service"}', 'Comment il achète et revend pour le compte d''autrui, ses commissions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_03', 'NPC_ALN_26', 'K0', '{"routes","approvisionnement"}', 'Quelles routes alimentent quel marché (complète le Débarcadère)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_04', 'NPC_ALN_26', 'K1', '{"penuries","prevision"}', 'Ce qui va manquer bientôt — et où spéculer avant les autres', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_05', 'NPC_ALN_26', 'K1', '{"stocks","arbitrage"}', 'Comment arbitrer entre territoires pour maximiser la marge', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_06', 'NPC_ALN_26', 'K1', '{"blocus","opportunite"}', 'Comment un blocus (événement orchestrateur) devient une aubaine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_07', 'NPC_ALN_26', 'K2', '{"retention","manipulation"}', 'Comment il retient des stocks pour fabriquer une pénurie', '`AFF>=85+PAY:300`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_08', 'NPC_ALN_26', 'K2', '{"rask","deplacement"}', 'Comment Rask `NPC_ALN_57` déplace ses stocks retenus hors des registres', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_09', 'NPC_ALN_26', 'K3', '{"famine","arme"}', 'Il affame délibérément des territoires pour peser dans la guerre économique proxy — la faim comme arme, vendue au plus offrant des neuf races', NULL, '*(il aligne trois pièces sur l''étal)* « Je réponds à la demande, je ne la crée pas. Si un village a faim, c''est le marché, pas moi. Le marché n''a pas de visage. Tu veux acheter, ou philosopher ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_26_10', 'NPC_ALN_26', 'KX', '{"*(hors sujet)*"}', '« Ça ne se cote pas, donc ça ne vaut rien pour moi. Suivant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_01', 'NPC_ALN_27', 'K0', '{"tissus","catalogue"}', 'Étoffes des 9 races, teintures, prix au coupon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_02', 'NPC_ALN_27', 'K0', '{"couture","composants"}', 'Quels tissus pour quels équipements (composants du métier couture)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_03', 'NPC_ALN_27', 'K0', '{"tailleurs","renvoi"}', 'Où faire tailler ses tissus (Ison `NPC_ALN_66`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_04', 'NPC_ALN_27', 'K1', '{"trame","origine"}', 'Comment reconnaître la race à la trame d''un vêtement', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_05', 'NPC_ALN_27', 'K1', '{"etoffes","rares"}', 'Les tissus rares (soie d''Yggdrasil, lin des Racines) et leurs vertus', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_06', 'NPC_ALN_27', 'K1', '{"teintures","ignifuge"}', 'Les teintures spéciales (ignifuges, imperméables) et leurs usages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_07', 'NPC_ALN_27', 'K2', '{"client","deguise"}', 'Un client qui portait les habits reprisés d''une race qui n''était pas la sienne', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_08', 'NPC_ALN_27', 'K2', '{"doublure","secret"}', 'Elle reconnaît les doublures secrètes qu''Ison `NPC_ALN_66` coud sur commande', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_09', 'NPC_ALN_27', 'K3', '{"trame","impossible"}', 'Elle a vu un tissu dont la trame n''appartient à aucune des neuf races — ni à aucun métier connu, comme « tissé par le monde lui-même »', NULL, '*(elle range vivement un coupon sous son comptoir)* « Neuf races, neuf tissages, je les connais tous. Ce coupon-là, je l''ai mal rangé, voilà tout. Tu voulais de la soie ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_27_10', 'NPC_ALN_27', 'KX', '{"*(hors sujet)*"}', '« Ça ne se tisse pas, donc je n''y connais rien, mon petit. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_01', 'NPC_ALN_28', 'K0', '{"herbes","catalogue"}', 'Simples des 9 territoires, prix, usages courants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_02', 'NPC_ALN_28', 'K0', '{"alchimie","composants"}', 'Quelles herbes pour quelles potions (renvoi Corvus `NPC_ALN_72`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_03', 'NPC_ALN_28', 'K0', '{"provenance","territoires"}', 'D''où vient chaque plante — la géographie botanique des 9 races', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_04', 'NPC_ALN_28', 'K1', '{"recolte","saisons"}', 'Où et quand récolter chaque simple, cycles de repousse', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_05', 'NPC_ALN_28', 'K1', '{"rares","vertus"}', 'Les plantes rares et leurs effets (antidotes, buffs, purges)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_06', 'NPC_ALN_28', 'K1', '{"yssa","seve"}', 'Ce que lui fournit Yssa `NPC_ALN_15` depuis les Racines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_07', 'NPC_ALN_28', 'K2', '{"fleur","sans-pays"}', 'La fleur qui ne pousse nulle part — qu''elle garde et étudie en secret', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_08', 'NPC_ALN_28', 'K2', '{"vinn","verger"}', 'Le lien entre sa fleur et les fruits « introuvables » de Vinn `NPC_ALN_31`', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_09', 'NPC_ALN_28', 'K3', '{"verger","apparait"}', 'Elle est convaincue qu''il existe un verger qui n''apparaît qu''à ceux qui ne le cherchent pas — et que sa fleur en vient', NULL, '*(elle glisse un bocal hors de vue)* « Une erreur d''étiquette, sûrement. Une herboriste qui vend des fleurs " de nulle part ", on la prend pour une folle. Alors elle vient de quelque part. Voilà. Tu voulais quel simple ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_28_10', 'NPC_ALN_28', 'KX', '{"*(hors sujet)*"}', '« Ça ne se cueille pas, donc ce n''est pas mon domaine. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_01', 'NPC_ALN_29', 'K0', '{"epices","catalogue"}', 'Poivre d''Alne, safran des Racines, sel Undine — prix et grades', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_02', 'NPC_ALN_29', 'K0', '{"cuisine","composants"}', 'Quelles épices pour quels plats (composants cuisine, renvoi Grett `NPC_ALN_79`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_03', 'NPC_ALN_29', 'K0', '{"export","gattan"}', 'Que le vrai poivre d''Alne part à Gattan chez Rosza `NPC_GAT_45`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_04', 'NPC_ALN_29', 'K1', '{"routes","caravanes"}', 'Ses routes d''épices, le calendrier des caravanes des 9 territoires', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_05', 'NPC_ALN_29', 'K1', '{"grades","qualite"}', 'Comment distinguer un poivre premium d''un poivre coupé (pique gentiment Rosza)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_06', 'NPC_ALN_29', 'K1', '{"penuries","epices"}', 'Quelles épices vont manquer (croise Grède `NPC_ALN_26`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_07', 'NPC_ALN_29', 'K2', '{"caravane","double-fond"}', 'Ce que Rask `NPC_ALN_57` glisse entre ses sacs de poivre', '`AFF>=85+QUEST:QST_NEU_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_08', 'NPC_ALN_29', 'K2', '{"route","detournee"}', 'Une de ses routes d''épices passe par un point qui ne figure sur aucune carte', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_09', 'NPC_ALN_29', 'K3', '{"contrainte","complice"}', 'Il n''est plus maître de ses propres caravanes : le réseau de contrebande de Rask s''en sert, et Peppin a trop peur (ou trop d''intérêts) pour refuser', NULL, '*(il rit trop fort et remballe un sachet)* « Mes caravanes ne transportent que du poivre ! Du poivre et de la bonne humeur ! Ce que les autres y voient, c''est leur imagination. Un peu de safran pour la route ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_29_10', 'NPC_ALN_29', 'KX', '{"*(hors sujet)*"}', '« Ça ne s''assaisonne pas, donc ça ne me connaît pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_01', 'NPC_ALN_30', 'K0', '{"viande","catalogue"}', 'Viandes et abats, prix, ce qu''il rachète comme drops', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_02', 'NPC_ALN_30', 'K0', '{"regimes","races"}', 'Ce que chaque race mange ou refuse (utile aux buffs food)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_03', 'NPC_ALN_30', 'K0', '{"cuisine","renvoi"}', 'À qui vendre pour faire cuisiner (Grett `NPC_ALN_79`, Aubin `NPC_ALN_47`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_04', 'NPC_ALN_30', 'K1', '{"drops","rachat"}', 'Quels drops de mobs valent quoi à la boucherie (chaîne chasseur→boucher)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_05', 'NPC_ALN_30', 'K1', '{"conservation","saison"}', 'Comment il conserve, ce qui se garde, ce qui buff', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_06', 'NPC_ALN_30', 'K1', '{"fournisseurs","chasse"}', 'Ses fournisseurs de gibier (chasseurs de la Canopée, périphérie)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_07', 'NPC_ALN_30', 'K2', '{"meme-bete","ruse"}', 'Comment il vend la même bête sous neuf noms différents', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_08', 'NPC_ALN_30', 'K2', '{"penurie","grede"}', 'Comment les rétentions de Grède `NPC_ALN_26` font flamber ses prix de viande', '`QUEST:QST_NEU_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_09', 'NPC_ALN_30', 'K3', '{"carcasse","inconnue"}', 'Un chasseur lui a vendu la carcasse d''une créature qui ne figure à aucun bestiaire — il l''a débitée et vendue sans poser de question, et le goût le hante', NULL, '*(il abat son couperet sur le billot)* « Je vends de la viande honnête de bêtes connues. Point. Si une carcasse te turlupine, va voir l''éleveur, pas le boucher. Suivant, et fais vite. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_30_10', 'NPC_ALN_30', 'KX', '{"*(hors sujet)*"}', '« Ça ne se découpe pas, donc je m''en fiche. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_01', 'NPC_ALN_31', 'K0', '{"fruits","catalogue"}', 'Fruits, légumes, primeurs — prix et fraîcheur du jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_02', 'NPC_ALN_31', 'K0', '{"cuisine","composants"}', 'Quels produits pour quels plats/buffs (renvoi cuisiniers)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_03', 'NPC_ALN_31', 'K0', '{"saisons","arrivages"}', 'Ce qui arrive frais et quand', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_04', 'NPC_ALN_31', 'K1', '{"vergers","culture"}', 'Ses (vrais) vergers cultivés à la périphérie d''Alne', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_05', 'NPC_ALN_31', 'K1', '{"fruits-rares","vertus"}', 'Les fruits rares aux effets alchimiques (buffs, régénération)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_06', 'NPC_ALN_31', 'K1', '{"conservation","transport"}', 'Comment ses primeurs voyagent sans s''abîmer (croise le Débarcadère)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_07', 'NPC_ALN_31', 'K2', '{"fruit","introuvable"}', 'Ses plus beaux fruits viennent d''un verger qu''elle ne sait pas retrouver', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_08', 'NPC_ALN_31', 'K2', '{"hasard","apparition"}', 'Le verger n''apparaît que lorsqu''elle a cessé de le chercher — jamais sur commande', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_09', 'NPC_ALN_31', 'K3', '{"verger","systeme"}', 'Elle soupçonne que ce verger n''est pas un lieu du monde mais une « poche » que le Système ouvre et referme — et qu''un jour il ne se rouvrira pas', NULL, '*(elle serre une pêche à deux mains)* « J''ai des vergers comme tout le monde, à la périphérie ! Une maraîchère qui parle de jardins fantômes, on ne lui achète plus une prune. Alors mes vergers sont bien réels. Goûtez, plutôt. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_31_10', 'NPC_ALN_31', 'KX', '{"*(hors sujet)*"}', '« Ça ne se cultive pas, donc je n''en sais rien du tout. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_01', 'NPC_ALN_32', 'K0', '{"familiers","catalogue"}', 'Familiers et montures exotiques en vente, prix, tempéraments', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_02', 'NPC_ALN_32', 'K0', '{"soins","nourriture"}', 'Comment nourrir et soigner un familier (renvoi Fenna `NPC_ALN_71`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_03', 'NPC_ALN_32', 'K0', '{"oeufs","eclosion"}', 'Les œufs qu''il vend et comment les faire éclore', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_04', 'NPC_ALN_32', 'K1', '{"especes","origines"}', 'D''où viennent ses bêtes (les 9 territoires, la Canopée)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_05', 'NPC_ALN_32', 'K1', '{"dressage","aptitudes"}', 'Quel familier pour quel style de jeu (combat, transport, détection)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_06', 'NPC_ALN_32', 'K1', '{"rares","elevage"}', 'Comment il élève les espèces rares, cycles de reproduction', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_07', 'NPC_ALN_32', 'K2', '{"bete","cachee"}', 'La créature du fond, jamais en vente, éclose d''un œuf trouvé', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_08', 'NPC_ALN_32', 'K2', '{"oeuf","provenance"}', 'Où il a trouvé l''œuf — un endroit qu''il n''a jamais pu retrouver', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_09', 'NPC_ALN_32', 'K3', '{"creature","hors-monde"}', 'Sa bête ne mange rien de connu, ne vieillit pas normalement, et n''a de fiche à aucun bestiaire — il pense qu''elle « n''est pas censée exister » et que le Système l''ignore', NULL, '*(il rabat le voile sur la cage)* « C''est un animal malade, rien d''autre. Un éleveur qui montre ses bêtes malades, il fait fuir la clientèle. Alors on la laisse tranquille, elle et sa cage. Tu voulais un renardeau ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_32_10', 'NPC_ALN_32', 'KX', '{"*(hors sujet)*"}', '« Ça n''a ni poil ni plume, donc ce n''est pas mon rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_01', 'NPC_ALN_33', 'K0', '{"parchemins","catalogue"}', 'Parchemins de skill mineurs, cartes de donjon — prix et effets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_02', 'NPC_ALN_33', 'K0', '{"skills","apprentissage"}', 'Quel parchemin enseigne quoi (renvoi maîtres Selene `NPC_ALN_70` / Roan `NPC_ALN_69`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_03', 'NPC_ALN_33', 'K0', '{"cartes","donjons"}', 'Les cartes de donjon disponibles, dont les premiers étages du Dôme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_04', 'NPC_ALN_33', 'K1', '{"rares","provenance"}', 'Les parchemins rares et d''où ils viennent (vaguement)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_05', 'NPC_ALN_33', 'K1', '{"denn","copies"}', 'Les copies « officieuses » qu''il tient de Denn `NPC_ALN_23`', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_06', 'NPC_ALN_33', 'K1', '{"skills","combos"}', 'Quels parchemins se combinent en enchaînements (méta de skill)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_07', 'NPC_ALN_33', 'K2', '{"parchemin","bugue"}', 'Le parchemin « bugué » très recherché — ce qu''il fait vraiment', '`AFF>=85+PAY:500`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_08', 'NPC_ALN_33', 'K2', '{"quill","source"}', 'Que le parchemin bugué vient de Quill `NPC_ALN_56`, jamais deux fois de suite', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_09', 'NPC_ALN_33', 'K3', '{"skill","interdit"}', 'Le parchemin bugué enseigne en réalité une action que le Système n''est pas censé permettre — un « exploit scénarisé », et Osk sait qu''il joue avec le feu', NULL, '*(il glisse un tube sous le comptoir)* « Je ne vends que des parchemins parfaitement standards, dûment testés. Les histoires de sorts " bugués ", c''est du folklore de joueur. Tu prends le manuel de saut, oui ou non ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_33_10', 'NPC_ALN_33', 'KX', '{"*(hors sujet)*"}', '« Ce n''est pas sur parchemin, donc ce n''est pas à vendre ici. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_01', 'NPC_ALN_34', 'K0', '{"gemmes","catalogue"}', 'Gemmes de Granzam, obsidienne, prix et sertissage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_02', 'NPC_ALN_34', 'K0', '{"sertissage","service"}', 'Comment sertir une gemme dans un équipement (bonus de stats)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_03', 'NPC_ALN_34', 'K0', '{"fournisseurs","granzam"}', 'Que ses pierres viennent de Granzam via Bomil `NPC_ALN_93`, l''obsidienne d''Onya `NPC_GAT_48`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_04', 'NPC_ALN_34', 'K1', '{"pierres","vertus"}', 'Quelle gemme donne quel bonus (feu, mana, résistance)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_05', 'NPC_ALN_34', 'K1', '{"taille","qualite"}', 'Comment reconnaître une taille de maître d''une pierre bâclée', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_06', 'NPC_ALN_34', 'K1', '{"vael","runes"}', 'Le duo taille+rune avec Vael `NPC_ALN_39` pour les équipements T4/T5', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_07', 'NPC_ALN_34', 'K2', '{"gemme","regard"}', 'La pierre « qui suit du regard » — sertie sur commande, rendue avec malaise', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_08', 'NPC_ALN_34', 'K2', '{"commanditaire","anonyme"}', 'Qui a commandé cette pierre — et pourquoi elle a refusé d''en tailler une seconde', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_09', 'NPC_ALN_34', 'K3', '{"gemme","oeil"}', 'Elle est convaincue que cette gemme est un « œil » — un capteur du Système déguisé en bijou, qui observe le porteur pour l''orchestrateur', NULL, '*(elle repose sa loupe, main un peu tremblante)* « Une gemme est un minéral. Un minéral ne regarde personne. Si une pierre vous a mis mal à l''aise, changez de bijoutier — pas de superstition ici. Vous vouliez sertir quoi ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_34_10', 'NPC_ALN_34', 'KX', '{"*(hors sujet)*"}', '« Ça ne se taille pas, donc ça ne m''intéresse pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_01', 'NPC_ALN_35', 'K0', '{"antiquites","catalogue"}', 'Reliques, vieux plans, curiosités — prix et provenances déclarées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_02', 'NPC_ALN_35', 'K0', '{"histoire","objets"}', 'Ce que ses objets racontent de l''histoire officielle d''Alfheim', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_03', 'NPC_ALN_35', 'K0', '{"estimation","service"}', 'Il estime et rachète les objets anciens trouvés par les joueurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_04', 'NPC_ALN_35', 'K1', '{"reliques","datation"}', 'Comment il date une pièce (croise l''expertise d''Ombric `NPC_ALN_21`)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_05', 'NPC_ALN_35', 'K1', '{"rares","collectionneurs"}', 'Quelles reliques valent une fortune et qui les convoite', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_06', 'NPC_ALN_35', 'K1', '{"fondation","recits"}', 'Les récits contradictoires sur la fondation du monde (croise Aldemar `NPC_ALN_99`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_07', 'NPC_ALN_35', 'K2', '{"objet","pre-fondation"}', 'Une pièce datée d''AVANT la fondation officielle d''Alfheim', '`AFF>=85+PAY:600`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_08', 'NPC_ALN_35', 'K2', '{"collection","privee"}', 'Sa collection privée d''« impossibles » qu''il ne vend jamais', '`AFF>=92`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_09', 'NPC_ALN_35', 'K3', '{"monde","anterieur"}', 'Ses reliques « d''avant » prouvent (pour lui) que le monde a une histoire cachée que les livres réécrits effacent — peut-être une version antérieure du serveur', NULL, '*(il replace un objet dans une vitrine close)* « Ce sont des faux charmants, bien sûr. Rien ne précède la fondation, tout le monde le sait. Un antiquaire qui prétend le contraire finit à l''asile ou en prison. Alors ce sont des faux. Une autre pièce vous tente ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_35_10', 'NPC_ALN_35', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas d''âge, donc ça n''a pas de valeur. Passez. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_01', 'NPC_ALN_36', 'K0', '{"forge","service"}', 'Où réparer et forger au Quartier des Forges, à qui s''adresser (Kaelen `NPC_ALN_02`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_02', 'NPC_ALN_36', 'K0', '{"reparation","tarifs"}', 'Tarifs de réparation courante, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_03', 'NPC_ALN_36', 'K0', '{"apprentissage","forge"}', 'Comment apprendre le métier de forge à Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_04', 'NPC_ALN_36', 'K1', '{"materiaux","tiers"}', 'Quels matériaux pour quels tiers (mithril, orichalque, gemmes)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_05', 'NPC_ALN_36', 'K1', '{"kaelen","methode"}', 'Ce qu''elle a compris de la méthode de Kaelen (bribes publiques)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_06', 'NPC_ALN_36', 'K1', '{"legendaires","entretien"}', 'Pourquoi les Légendaires exigent Kaelen et personne d''autre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_07', 'NPC_ALN_36', 'K2', '{"technique","volee"}', 'Ce qu''elle a réussi à reconstituer de la réparation ultime, en cachette', '`AFF>=85+QUEST:QST_NEU_FORGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_08', 'NPC_ALN_36', 'K2', '{"kaelen","haine"}', 'Pourquoi Kaelen hait les Salamander — l''histoire qu''il lui a laissé entrevoir', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_09', 'NPC_ALN_36', 'K3', '{"secret","danger"}', 'Elle sait que reproduire la technique sans la comprendre pourrait « casser » une arme Légendaire de façon irréversible — un risque de duplication/corruption que le Système ne pardonne pas', NULL, '*(elle cache un croquis sous son tablier)* « Je ne fais que balayer la forge et tendre les outils. La technique du maître ? Personne ne la connaît, à part lui. Surtout pas moi. N''allez rien lui dire, hein ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_36_10', 'NPC_ALN_36', 'KX', '{"*(hors sujet)*"}', '« Ça ne se forge pas, alors je ne saurais pas vous dire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_01', 'NPC_ALN_37', 'K0', '{"fonte","service"}', 'Fonte, recyclage de métal, rachat d''armes usées — tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_02', 'NPC_ALN_37', 'K0', '{"outils","vente"}', 'Les outils qu''il fabrique (socs, marmites) et leurs usages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_03', 'NPC_ALN_37', 'K0', '{"metaux","recyclage"}', 'Quels métaux se refondent, ce qu''il en tire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_04', 'NPC_ALN_37', 'K1', '{"armes","provenance"}', 'Il reconnaît la forge d''origine d''une arme à son alliage (9 races)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_05', 'NPC_ALN_37', 'K1', '{"guerres","degout"}', 'Ce qu''il a vu aux guerres raciales, et pourquoi il refond les armes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_06', 'NPC_ALN_37', 'K1', '{"mithril","orichalque"}', 'Les métaux nobles qu''il refuse de gâcher (renvoi Kaelen `NPC_ALN_02`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_07', 'NPC_ALN_37', 'K2', '{"client","armes-neuves"}', 'Un client lui apporte des armes militaires NEUVES à « détruire » — trop, trop souvent', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_08', 'NPC_ALN_37', 'K2', '{"refus","kael"}', 'Pourquoi il a chassé Kael `NPC_ALN_07` de sa forge', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_09', 'NPC_ALN_37', 'K3', '{"destruction","couverture"}', 'Il a compris que « détruire » ces armes neuves sert à en effacer la trace pour la cellule anti-neutralité — il refond en silence, pris entre son idéal et sa peur', NULL, '*(il tisonne le foyer sans se retourner)* « Je fonds ce qu''on m''apporte et j''en fais des outils. D''où ça vient, où ça va, ça ne me regarde pas. Le feu ne pose pas de questions. Moi non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_37_10', 'NPC_ALN_37', 'KX', '{"*(hors sujet)*"}', '« Ça ne se fond pas, donc ça ne me dit rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_01', 'NPC_ALN_38', 'K0', '{"reparation","express"}', 'Réparation rapide, tarifs bas, ce qu''il prend en charge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_02', 'NPC_ALN_38', 'K0', '{"durabilite","base"}', 'Comment marche la durabilité, quand réparer', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_03', 'NPC_ALN_38', 'K0', '{"limites","renvoi"}', 'Ce qu''il ne peut PAS réparer (Légendaires → Kaelen `NPC_ALN_02`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_04', 'NPC_ALN_38', 'K1', '{"astuces","entretien"}', 'Ses astuces d''entretien pour espacer les réparations', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_05', 'NPC_ALN_38', 'K1', '{"materiaux","recup"}', 'Où récupérer des pièces bon marché (croise Grumman `NPC_ALN_37`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_06', 'NPC_ALN_38', 'K1', '{"objets","faiblesses"}', 'Quels équipements cassent le plus vite et pourquoi', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_07', 'NPC_ALN_38', 'K2', '{"reparation","trop-bonne"}', 'Que ses réparations « restaurent » parfois la durabilité max — anomalie', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_08', 'NPC_ALN_38', 'K2', '{"outil","herite"}', 'L''outil bizarre dont il se sert, hérité sans notice, qui « répare mieux »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_09', 'NPC_ALN_38', 'K3', '{"exploit","durabilite"}', 'Son outil exploite involontairement une faille de la mécanique de durabilité (bug de restauration) ; il craint qu''on l''accuse de « tricher le Système »', NULL, '*(il range son drôle d''outil dans un tiroir fermé à clé)* « Je répare bien, c''est tout ! Un bon artisan, ça restaure comme au premier jour. Y''a pas de sorcellerie là-dedans. Vous voulez que je jette un œil à votre lame, oui ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_38_10', 'NPC_ALN_38', 'KX', '{"*(hors sujet)*"}', '« Si ça ne casse pas, je ne peux pas le réparer, donc je m''y connais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_01', 'NPC_ALN_39', 'K0', '{"runes","catalogue"}', 'Runes d''enchantement disponibles, effets, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
