INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_03', 'NPC_ALN_39', 'K0', '{"vireth","tandem"}', 'Le duo gemme+rune avec Vireth `NPC_ALN_34` pour le haut tier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_04', 'NPC_ALN_39', 'K1', '{"runes","combinaisons"}', 'Quelles runes se combinent, lesquelles se repoussent', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_05', 'NPC_ALN_39', 'K1', '{"brokkheim","tradition"}', 'La tradition runique de Brokkheim qu''il perpétue', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_06', 'NPC_ALN_39', 'K1', '{"materiaux","encres"}', 'Les composants rares d''une gravure de maître (encres runiques)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_07', 'NPC_ALN_39', 'K2', '{"rune","interdite"}', 'L''existence des runes interdites — ce qu''elles font, pourquoi il refuse', '`AFF>=85+QUEST:QST_NEU_RUNE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_08', 'NPC_ALN_39', 'K2', '{"commande","refus"}', 'Qui lui a commandé une rune interdite, et le « prix » qu''il a exigé pour dissuader', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_09', 'NPC_ALN_39', 'K3', '{"rune","faille"}', 'La rune la plus interdite « écrit » directement dans les règles de l''objet, contournant la mécanique du Système — un exploit gravé, qu''il garde secret pour qu''il ne soit jamais reproduit', NULL, '*(il pose son burin sur l''enclume, définitif)* « Certaines runes n''existent pas. Répète-le : elles n''existent pas. Je grave la protection, le feu, le givre. Le reste est un conte pour effrayer les apprentis. Ton équipement, tu le veux enchanté comment ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_39_10', 'NPC_ALN_39', 'KX', '{"*(hors sujet)*"}', '« Ça ne se grave pas, donc ce n''est pas de mon ressort. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_01', 'NPC_ALN_40', 'K0', '{"soins","service"}', 'Soins mineurs, potions de la Fontaine, files d''attente', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_02', 'NPC_ALN_40', 'K0', '{"resurrection","elara"}', 'Comment obtenir une résurrection auprès d''Elara `NPC_ALN_03`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_03', 'NPC_ALN_40', 'K0', '{"fontaine","rez-sur"}', 'La Fontaine comme point de résurrection sûr (renvoi Vosk `NPC_ALN_42`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_04', 'NPC_ALN_40', 'K1', '{"malediction","purge"}', 'Ce que purifie l''eau de la Fontaine, ce qui résiste', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_05', 'NPC_ALN_40', 'K1', '{"liturgie","benedictions"}', 'Les bénédictions de raid et leur logistique (croise Ilia `NPC_ALN_41`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_06', 'NPC_ALN_40', 'K1', '{"remain-light","penalite"}', 'Ce qu''il en coûte de mourir sans précaution (pénalité, renvoi doctrinal)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_07', 'NPC_ALN_40', 'K2', '{"resurrection","prix"}', 'Son doute : les ressuscités « perdent » quelque chose d''immatériel', '`AFF>=85+QUEST:QST_NEU_FONTAINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_08', 'NPC_ALN_40', 'K2', '{"elara","larmes"}', 'Ce qu''Elara « prend » quand elle pleure ses larmes de purification', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_09', 'NPC_ALN_40', 'K3', '{"ame","echange"}', 'Il craint qu''Elara — ou le Système via elle — prélève des fragments de mémoire des joueurs ressuscités, à leur insu, comme un péage sur la mort', NULL, '*(il baisse les yeux, joint les mains)* « La Prêtresse ne prend rien. Elle donne. C''est un don, entièrement un don. Je ne dois pas… je ne dois pas dire autre chose. Allez en paix, et priez pour moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_40_10', 'NPC_ALN_40', 'KX', '{"*(hors sujet)*"}', '« Ce n''est pas affaire de foi ni de soin. Je ne saurais vous répondre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_01', 'NPC_ALN_41', 'K0', '{"buffs","catalogue"}', 'Les bénédictions de départ disponibles, effets, durées, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_02', 'NPC_ALN_41', 'K0', '{"raid","preparation"}', 'Quels buffs pour quel type de raid (renvoi Bran `NPC_ALN_73`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_03', 'NPC_ALN_41', 'K0', '{"fontaine","benediction"}', 'Comment recevoir une bénédiction et la stacker avec Elara `NPC_ALN_03`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_04', 'NPC_ALN_41', 'K1', '{"composition","chances"}', 'Elle « lit » les chances d''un groupe à sa composition', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_05', 'NPC_ALN_41', 'K1', '{"buffs","synergies"}', 'Quelles bénédictions se combinent le mieux avant le Dôme', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_06', 'NPC_ALN_41', 'K1', '{"dome","retours"}', 'Ce qu''elle sait des groupes qui reviennent (ou pas)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_07', 'NPC_ALN_41', 'K2', '{"benediction","refusee"}', 'La bénédiction rare qu''elle refuse désormais de lancer', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_08', 'NPC_ALN_41', 'K2', '{"changes","lien"}', 'Le lien qu''elle a fait entre sa bénédiction et ceux qui « redescendent autres »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_09', 'NPC_ALN_41', 'K3', '{"buff","marqueur"}', 'Elle soupçonne que sa bénédiction rare agissait comme un « marqueur » que le Dôme (ou le Système) utilisait pour sélectionner qui transformer là-haut', NULL, '*(elle referme ses mains autour d''un pendentif)* « Toutes mes bénédictions sont sûres et bonnes. Celle-là, je ne la lance plus, c''est un choix personnel, rien de plus. Prends la vigueur, prends la chance — elles, je te les donne de tout cœur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_41_10', 'NPC_ALN_41', 'KX', '{"*(hors sujet)*"}', '« Ça ne se bénit pas, donc je n''ai rien à en dire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_01', 'NPC_ALN_42', 'K0', '{"fontaine","resurrection"}', 'La Fontaine comme point de rez sûr, comment y revenir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_02', 'NPC_ALN_42', 'K0', '{"securite","regles"}', 'Les règles autour du point de résurrection (pas de PK, pas de chahut)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_03', 'NPC_ALN_42', 'K0', '{"soins","renvoi"}', 'Où se faire soigner ou bénir (Elara `NPC_ALN_03`, Osmé `NPC_ALN_40`, Ilia `NPC_ALN_41`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_04', 'NPC_ALN_42', 'K1', '{"morts","frequentation"}', 'Qui meurt souvent, à quelle heure, revient d''où', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_05', 'NPC_ALN_42', 'K1', '{"penalite","remain-light"}', 'Les effets de la mort répétée (pénalité, perte, renvoi doctrinal)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_06', 'NPC_ALN_42', 'K1', '{"vulnerables","protection"}', 'Comment il protège les ressuscités hébétés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_07', 'NPC_ALN_42', 'K2', '{"joueur","meurt-trop"}', 'Le joueur (ou PNJ) qui meurt encore et encore — et ce qu''il « perd » à chaque fois', '`AFF>=85+QUEST:QST_NEU_FONTAINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_08', 'NPC_ALN_42', 'K2', '{"mort","cherchee"}', 'Ceux qui cherchent délibérément la mort à la Fontaine — pourquoi', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_09', 'NPC_ALN_42', 'K3', '{"effacement","boucle"}', 'Il est convaincu que mourir à répétition « efface » progressivement un joueur — mémoire, identité — et que quelqu''un exploite cette boucle pour faire disparaître des gens sans les tuer vraiment', NULL, '*(il resserre sa prise sur sa lance)* « La Fontaine rend la vie. Elle ne prend rien. Ceux qui meurent souvent sont maladroits, voilà tout. Repose-toi et cesse de mourir, ça vaudra mieux pour toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_42_10', 'NPC_ALN_42', 'KX', '{"*(hors sujet)*"}', '« Ça ne se passe pas à la Fontaine, donc je n''en réponds pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_01', 'NPC_ALN_43', 'K0', '{"fontaine","voeux"}', 'La coutume des vœux, où jeter sa pièce, ce qu''on souhaite', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_02', 'NPC_ALN_43', 'K0', '{"entretien","place"}', 'L''entretien de la Place, horaires de nettoyage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_03', 'NPC_ALN_43', 'K0', '{"objets-perdus","fontaine"}', 'Les objets tombés dans la Fontaine qu''il récupère et rend', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_04', 'NPC_ALN_43', 'K1', '{"voeux","rumeurs"}', 'Les vœux les plus fréquents — un baromètre de l''humeur d''Alne', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_05', 'NPC_ALN_43', 'K1', '{"pieces","valeur"}', 'Les pièces rares ou anciennes qu''il trouve parfois au fond', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_06', 'NPC_ALN_43', 'K1', '{"lynn","melodie"}', 'Que la mélodie de Lynn `NPC_ALN_82` semble « ranger » les pièces', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_07', 'NPC_ALN_43', 'K2', '{"pieces","motif"}', 'Les pièces s''alignent en motifs, la nuit — son carnet de relevés', '`AFF>=85+QUEST:QST_NEU_FONTAINE_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_08', 'NPC_ALN_43', 'K2', '{"message","dechiffre"}', 'Le début d''un mot qu''il croit lire dans les alignements', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_09', 'NPC_ALN_43', 'K3', '{"fontaine","canal"}', 'Il pense que la Fontaine est un « canal » par lequel quelque chose de très bas (la Racine ? le Cardinal ?) écrit des messages — et que son carnet contient une phrase que nul n''était censé lire', NULL, '*(il fourre son carnet dans sa poche trouée)* « Des pièces, c''est des pièces. Ça tombe, ça coule, ça se pose. Y''a pas de message. Un balayeur qui lit dans les fontaines, on l''enferme. Alors y''a rien. Rien du tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_43_10', 'NPC_ALN_43', 'KX', '{"*(hors sujet)*"}', '« Moi je ramasse, je ne réponds pas aux questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_01', 'NPC_ALN_44', 'K0', '{"auberge","repos"}', 'Repos premium (500 Yrds, restauration 100 %), réservation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_02', 'NPC_ALN_44', 'K0', '{"services","renvoi"}', 'Cave (Dranz `NPC_ALN_45`), cuisine (Aubin `NPC_ALN_47`), coffres (Lom `NPC_ALN_46`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_03', 'NPC_ALN_44', 'K0', '{"chambres","tarifs"}', 'Les chambres, leurs prix, ce que le premium inclut', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_04', 'NPC_ALN_44', 'K1', '{"clients","importance"}', 'Quels voyageurs d''importance logent chez elle (sans trahir de secret)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_05', 'NPC_ALN_44', 'K1', '{"ragots","voyageurs"}', 'Les rumeurs de voyage qui passent par ses murs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_06', 'NPC_ALN_44', 'K1', '{"reservations","complet"}', 'Quand l''auberge se remplit (avant/après les grands raids)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_07', 'NPC_ALN_44', 'K2', '{"chambre-9","entretien"}', 'Qu''elle entretient la chambre 9 pour un occupant qu''on ne voit jamais', '`AFF>=85+QUEST:QST_NEU_CHAMBRE9_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_08', 'NPC_ALN_44', 'K2', '{"serment","ancien"}', 'Le serment qui la lie à ne jamais louer la neuf', '`AFF>=92`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_09', 'NPC_ALN_44', 'K3', '{"occupant","invisible"}', 'La chambre 9 est « occupée » par quelqu''un qui a existé à la fondation d''Alne et n''est jamais reparti — un fantôme du serveur qu''elle sert par loyauté, ou par peur de ce qui arriverait si elle cessait', NULL, '*(elle lisse son tablier, regard fuyant)* « La neuf est en réfection. Une réfection très longue. Prenez la sept, elle a une plus belle vue. La neuf, on n''en parle plus, d''accord ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_44_10', 'NPC_ALN_44', 'KX', '{"*(hors sujet)*"}', '« Ça ne se passe pas sous mon toit, donc je n''en sais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_01', 'NPC_ALN_45', 'K0', '{"vins","catalogue"}', 'Crus des 9 territoires, spiritueux, prix, breuvages à buff', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_02', 'NPC_ALN_45', 'K0', '{"buffs","boissons"}', 'Quels breuvages donnent quels buffs (courage, résistance à l''alcool, VIT)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_03', 'NPC_ALN_45', 'K0', '{"accords","cuisine"}', 'Les accords avec la cuisine d''Aubin `NPC_ALN_47`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_04', 'NPC_ALN_45', 'K1', '{"crus","rares"}', 'Les grands crus rares et leur provenance racial', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_05', 'NPC_ALN_45', 'K1', '{"degustation","palais"}', 'Comment reconnaître un cru à l''aveugle (mini-savoir de sommellerie)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_06', 'NPC_ALN_45', 'K1', '{"vignobles","geographie"}', 'La carte des vignobles d''Alfheim, dont ceux disparus', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_07', 'NPC_ALN_45', 'K2', '{"bouteille","unique"}', 'Le cru dont il ne reste qu''une bouteille — d''un vignoble détruit à la guerre', '`AFF>=85+QUEST:QST_NEU_CRU_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_08', 'NPC_ALN_45', 'K2', '{"peuple","efface"}', 'Ce qu''il sait du peuple et du lieu que ce vin fait exister encore', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_09', 'NPC_ALN_45', 'K3', '{"vin","preuve"}', 'Sa bouteille prouve (pour lui) qu''un territoire entier a été rayé de l''histoire officielle — un vignoble, un village, dont aucun livre ne parle plus, comme s''ils avaient été « supprimés »', NULL, '*(il repose délicatement une bouteille poussiéreuse)* « Un simple vin de collection, hors de prix, hors de vente. Son vignoble ? Fermé, banalement. Rien de tragique. Un sommelier qui raconte des génocides, ça coupe l''appétit. Un verre de blanc, plutôt ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_45_10', 'NPC_ALN_45', 'KX', '{"*(hors sujet)*"}', '« Ça ne se déguste pas, donc mon avis ne vaut rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_01', 'NPC_ALN_46', 'K0', '{"coffres","service"}', 'Location de coffre, consigne, tarifs de garde', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_02', 'NPC_ALN_46', 'K0', '{"conciergerie","commissions"}', 'Les petits services rendus aux clients (messages, courses)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_03', 'NPC_ALN_46', 'K0', '{"banque","renvoi"}', 'La différence entre sa consigne et la banque d''Ovena `NPC_ALN_60`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_04', 'NPC_ALN_46', 'K1', '{"objets","garde"}', 'Ce qu''il accepte ou refuse de garder (rien d''illégal… en théorie)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_05', 'NPC_ALN_46', 'K1', '{"clients","habitudes"}', 'Qui dépose quoi régulièrement (sans trahir le contenu)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_06', 'NPC_ALN_46', 'K1', '{"securite","coffres"}', 'Comment les coffres sont protégés (utile aux quêtes de vol)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_07', 'NPC_ALN_46', 'K2', '{"coffres","abandonnes"}', 'La liste des coffres dont les propriétaires ne reviennent plus', '`AFF>=85+QUEST:QST_NEU_COFFRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_08', 'NPC_ALN_46', 'K2', '{"proprietaires","disparus"}', 'Le recoupement entre ses abandons et les non-revenus du Dôme (Sella `NPC_ALN_13`)', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_09', 'NPC_ALN_46', 'K3', '{"contenu","interdit"}', 'Un des coffres abandonnés contient quelque chose qu''il a entrevu et qu''il aurait préféré ne jamais voir — lié à la cellule anti-neutralité ou à la disparition de son propriétaire', NULL, '*(il vérifie machinalement un trousseau de clés)* « Le contenu des coffres est confidentiel, y compris quand plus personne ne vient. Surtout quand plus personne ne vient. Je garde, je n''ouvre pas, je ne regarde pas. Le vôtre, quel numéro ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_46_10', 'NPC_ALN_46', 'KX', '{"*(hors sujet)*"}', '« Si ce n''est pas dans un coffre, ce n''est pas mon affaire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_01', 'NPC_ALN_47', 'K0', '{"plats","catalogue"}', 'Menu premium, plats à buff, prix, durées d''effet', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_02', 'NPC_ALN_47', 'K0', '{"buffs","food"}', 'Quel plat pour quel buff (STR, VIT, régén, résistances)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_03', 'NPC_ALN_47', 'K0', '{"fournisseurs","marche"}', 'D''où viennent ses ingrédients (Halle `30`, Vinn `31`, Peppin `29`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_04', 'NPC_ALN_47', 'K1', '{"recettes","metier"}', 'Comment apprendre la cuisine à haut niveau (chaîne de métier)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_05', 'NPC_ALN_47', 'K1', '{"ingredients","rares"}', 'Les composants rares qui font les grands plats (sève, fruits introuvables)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_06', 'NPC_ALN_47', 'K1', '{"accords","dranz"}', 'Les accords mets-vins avec Dranz `NPC_ALN_45` pour empiler les buffs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_07', 'NPC_ALN_47', 'K2', '{"plat","interdit"}', 'Le plat qu''il a cuisiné une seule fois — au buff quasi invincible', '`AFF>=85+QUEST:QST_NEU_PLAT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_08', 'NPC_ALN_47', 'K2', '{"recette","brulee"}', 'Pourquoi il a détruit la recette, et ce qu''il en garde en mémoire', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_09', 'NPC_ALN_47', 'K3', '{"plat","exploit"}', 'Le plat exploitait un empilement de buffs que le Système n''était pas censé permettre (buff surpuissant, quasi-exploit) — il l''a brûlé pour ne pas « casser l''équilibre du monde »', NULL, '*(il claque un torchon sur le plan de travail)* « Ce plat n''a jamais existé, c''est une légende de cuisine ! Un chef sérieux ne cuisine pas l''invincibilité. Je fais des buffs honnêtes, équilibrés, délicieux. Vous prendrez le menu du raid ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_47_10', 'NPC_ALN_47', 'KX', '{"*(hors sujet)*"}', '« Ça ne se mange pas, donc ça ne me concerne pas. Ouste, hors de ma cuisine. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_01', 'NPC_ALN_48', 'K0', '{"taverne","menu"}', 'Bière, ragoût, prix populaires, repos léger', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_02', 'NPC_ALN_48', 'K0', '{"ambiance","habitues"}', 'Qui fréquente le rade, où s''asseoir, la vie du Sous-Sol', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_03', 'NPC_ALN_48', 'K0', '{"mercenaires","renvoi"}', 'Où trouver mercenaires et contrats (Gorak `NPC_ALN_04`, Della `NPC_ALN_76`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_04', 'NPC_ALN_48', 'K1', '{"rumeurs","sous-sol"}', 'Les rumeurs qui circulent au comptoir (relais K0 d''autres PNJ)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_05', 'NPC_ALN_48', 'K1', '{"vetrans","histoires"}', 'Les récits des vétérans habitués (Orn `NPC_ALN_95`, Aldous `NPC_ALN_74`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_06', 'NPC_ALN_48', 'K1', '{"casino","voisinage"}', 'Ce qu''on entend du casino de Maelis `NPC_ALN_06` à travers le mur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_07', 'NPC_ALN_48', 'K2', '{"mur","bruits"}', 'Les bruits de lutte et cris étouffés, aux heures des duels clandestins', '`AFF>=85+QUEST:QST_NEU_CASINO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_08', 'NPC_ALN_48', 'K2', '{"clients","disparus"}', 'Des habitués descendus au casino qu''il n''a jamais revus remonter', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_09', 'NPC_ALN_48', 'K3', '{"duels","morts"}', 'Il sait que certains « duels clandestins » de Maelis se terminent en vrais meurtres réglés hors zone neutre, financés par des contrats de PK — et il couvre par lâcheté et bon voisinage', NULL, '*(il monte le volume de la chanson)* « J''entends rien du tout, moi. Vieux murs, vieilles canalisations, ça grince, c''est tout. Le casino, c''est leurs affaires. Ici on boit, on chante. Une autre pinte ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_48_10', 'NPC_ALN_48', 'KX', '{"*(hors sujet)*"}', '« Ça se passe pas dans ma taverne, alors ça me regarde pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_01', 'NPC_ALN_49', 'K0', '{"chansons","repertoire"}', 'Son répertoire, les buffs de chant qu''il offre (courage, entrain)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_02', 'NPC_ALN_49', 'K0', '{"legendes","recits"}', 'Les grandes légendes d''Alfheim qu''il conte pour quelques Yrds', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_03', 'NPC_ALN_49', 'K0', '{"tavernes","tournee"}', 'Les nouvelles des neuf territoires qu''il colporte de rade en rade', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_04', 'NPC_ALN_49', 'K1', '{"rumeurs","itinerance"}', 'Les rumeurs fraîches d''autres cités (relais inter-villes)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_05', 'NPC_ALN_49', 'K1', '{"histoire","chansons"}', 'L''histoire des races telle que la gardent les chansons (parfois ≠ des livres)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_06', 'NPC_ALN_49', 'K1', '{"buffs","performance"}', 'Comment ses chants boostent un groupe avant un raid', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_07', 'NPC_ALN_49', 'K2', '{"ballade","interdite"}', 'La chanson qu''il ne chante plus en entier, et le lieu qu''elle nomme', '`AFF>=85+QUEST:QST_NEU_BALLADE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_08', 'NPC_ALN_49', 'K2', '{"couplet","resistance"}', 'Le malaise physique qui le prend à l''approche du couplet effacé', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_09', 'NPC_ALN_49', 'K3', '{"chanson","verite"}', 'Il pense que sa ballade est un vestige de mémoire que la réécriture officielle n''a pas pu atteindre — parce qu''une chanson vit dans les bouches, pas dans les livres — et que la chanter en entier « réveillerait » ce qu''on a effacé', NULL, '*(il pose sa main à plat sur les cordes, les faisant taire)* « Cette chanson-là est incomplète, je n''en connais qu''un bout, voilà tout. Un barde n''invente pas les couplets manquants. Je te chante autre chose ? Quelque chose de gai, tiens. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_49_10', 'NPC_ALN_49', 'KX', '{"*(hors sujet)*"}', '« Ça ne se chante pas, alors ça ne me revient pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_01', 'NPC_ALN_50', 'K0', '{"service","taverne"}', 'Prendre commande, prix, où s''installer au Sous-Sol', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_02', 'NPC_ALN_50', 'K0', '{"habitues","tables"}', 'Qui s''assoit où, les tables des mercenaires et des vétérans', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_03', 'NPC_ALN_50', 'K0', '{"discretion","service"}', 'Son service particulier : « n''avoir rien entendu » contre paiement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_04', 'NPC_ALN_50', 'K1', '{"rumeurs","salle"}', 'Les rumeurs générales de la salle (tout venant, non nominatif)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_05', 'NPC_ALN_50', 'K1', '{"ambiance","tensions"}', 'Les tensions du soir, qui est à cran, qui cherche la bagarre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_06', 'NPC_ALN_50', 'K1', '{"wisp","difference"}', 'Pourquoi elle vend l''oubli et non le secret (contrairement à Wisp `NPC_ALN_58`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_07', 'NPC_ALN_50', 'K2', '{"conversation","entendue"}', 'Une conversation précise qu''elle a « oubliée » — récupérable si on rachète l''oubli', '`AFF>=85+PAY:300`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_08', 'NPC_ALN_50', 'K2', '{"client","projet"}', 'Le projet qu''un habitué a laissé échapper, ivre, et qu''elle protège', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_09', 'NPC_ALN_50', 'K3', '{"complot","anti-pk"}', 'Elle a entendu, sans le vouloir, une réunion de la cellule anti-neutralité planifier l''exploitation de la faille anti-PK — et elle a été « payée pour l''oublier » par des gens qu''on ne refuse pas', NULL, '*(elle essuie la table, sourire poli)* « Je n''entends jamais rien, monsieur. C''est mon métier de ne rien entendre. Ce que vous imaginez que j''ai entendu, je l''ai déjà oublié. Un autre verre ? C''est ma tournée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_50_10', 'NPC_ALN_50', 'KX', '{"*(hors sujet)*"}', '« Ça, personne ne l''a dit à une table, donc je ne l''ai pas entendu. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_01', 'NPC_ALN_51', 'K0', '{"jeux","regles"}', 'Les règles des dés magiques, mises, gains, plafonds', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_02', 'NPC_ALN_51', 'K0', '{"casino","etiquette"}', 'L''étiquette du Tapis Volant, ce qui est toléré ou non', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_03', 'NPC_ALN_51', 'K0', '{"maison","avantage"}', 'Que la maison gagne toujours (avec le sourire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_04', 'NPC_ALN_51', 'K1', '{"des","lecture"}', 'Comment il « lit » le hasard — bribes de sa maîtrise', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_05', 'NPC_ALN_51', 'K1', '{"joueurs","tells"}', 'Les tells qu''il repère chez les parieurs (utile en PvP social)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_06', 'NPC_ALN_51', 'K1', '{"maelis","confiance"}', 'Sa position d''homme de confiance de Maelis `NPC_ALN_06`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_07', 'NPC_ALN_51', 'K2', '{"des","orientes"}', 'Qu''il oriente réellement l''issue des dés, sans trucage matériel', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_08', 'NPC_ALN_51', 'K2', '{"maison","ruiner"}', 'Qu''il pourrait ruiner le casino d''un seul jet — et pourquoi il s''en abstient', '`AFF>=90+PAY:500`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_09', 'NPC_ALN_51', 'K3', '{"des","systeme"}', 'Sa « lecture du hasard » est en réalité un accès partiel au générateur d''aléa du Système (RNG) — il perçoit le résultat avant qu''il tombe, et il ignore si c''est un don ou un bug de son existence de PNJ', NULL, '*(il fait sauter un dé, le rattrape sans regarder)* « Le hasard, monsieur, n''appartient à personne. Ni à moi, ni à la maison. Je ne fais que le servir. Si je gagnais toujours, croyez bien que je ne serais pas croupier. Faites vos jeux. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_51_10', 'NPC_ALN_51', 'KX', '{"*(hors sujet)*"}', '« Ça ne se joue pas à ma table, donc je n''y connais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_01', 'NPC_ALN_52', 'K0', '{"casino","securite"}', 'Les règles de sécurité du Tapis Volant, comportements bannis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_02', 'NPC_ALN_52', 'K0', '{"anti-pk","ville"}', 'Comment fonctionne l''interdiction de violence en zone neutre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_03', 'NPC_ALN_52', 'K0', '{"expulsion","procedure"}', 'Comment il expulse sans toucher (version publique, dissuasive)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_04', 'NPC_ALN_52', 'K1', '{"tricheurs","reperage"}', 'Comment il repère les tricheurs et les indésirables', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_05', 'NPC_ALN_52', 'K1', '{"pression","technique"}', 'Sa technique d''acculement dans les limites de l''anti-PK', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_06', 'NPC_ALN_52', 'K1', '{"sten","marquage"}', 'Comment Sten `NPC_ALN_59` marque ceux qu''il signale', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_07', 'NPC_ALN_52', 'K2', '{"anti-pk","limites"}', 'Les limites exactes de la neutralité qu''il a cartographiées par l''expérience', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_08', 'NPC_ALN_52', 'K2', '{"silene","surveillance"}', 'Qu''il sait que Silène `NPC_ALN_09` l''observe, et pourquoi il la laisse faire', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_09', 'NPC_ALN_52', 'K3', '{"faille","exploit"}', 'Dans sa cartographie des limites, il a repéré un « angle mort » où le Système tarde à réagir — la même faille que garde Silène — et il pourrait la vendre à qui voudrait tuer en zone neutre', NULL, '*(il croise les bras, immobile comme un mur)* « L''anti-PK est parfait. Personne ne peut faire de mal à personne, ici. C''est pour ça que je sors les gens sans les toucher : je n''ai pas le choix, et eux non plus. Il n''y a pas d''angle mort. Circule. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_52_10', 'NPC_ALN_52', 'KX', '{"*(hors sujet)*"}', '« Ça se passe pas dans mon casino, alors ça me regarde pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_01', 'NPC_ALN_53', 'K0', '{"prets","taux"}', 'Prêts d''urgence, taux (salés), conditions de remboursement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_02', 'NPC_ALN_53', 'K0', '{"gage","procedure"}', 'Comment mettre un objet en gage, délais de saisie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_03', 'NPC_ALN_53', 'K0', '{"casino","symbiose"}', 'Qu''elle prête à ceux que le casino a ruinés (renvoi Maelis `NPC_ALN_06`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_04', 'NPC_ALN_53', 'K1', '{"dettes","recouvrement"}', 'Comment elle recouvre — sans violence (zone neutre), mais implacablement', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_05', 'NPC_ALN_53', 'K1', '{"gages","valeur"}', 'Ce qu''elle accepte en gage et à quelle décote', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_06', 'NPC_ALN_53', 'K1', '{"morne","ecoulement"}', 'Comment Morne `NPC_ALN_55` écoule les gages saisis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_07', 'NPC_ALN_53', 'K2', '{"objets-lies","gage"}', 'Qu''elle peut prendre en gage des objets liés à l''âme — l''impossible', '`AFF>=85+QUEST:QST_NEU_DETTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_08', 'NPC_ALN_53', 'K2', '{"contrat","clause"}', 'La clause cachée du contrat que Quill `NPC_ALN_56` rédige pour elle', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_09', 'NPC_ALN_53', 'K3', '{"ame","transfert"}', 'Son contrat exploite un mécanisme de « transfert d''âme » — une faille du système de liaison d''objets qui permet de céder l''incessible ; ceux qui signent ne récupèrent jamais tout à fait ce qu''ils étaient', NULL, '*(elle tapote le contrat de ses sept doigts)* « Je prête, je récupère, tout est légal, tout est signé. Ce que mes clients cèdent, ils l''ont cédé de leur plein gré, en toutes lettres. L''âme ? Quelle âme ? Signe ici, on parlera de métaphysique plus tard. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_53_10', 'NPC_ALN_53', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas de valeur de gage, donc ça ne vaut rien pour moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_01', 'NPC_ALN_54', 'K0', '{"paris","cotes"}', 'Comment parier sur les duels, cotes, plafonds de mise', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_02', 'NPC_ALN_54', 'K0', '{"duels","lieu"}', 'Que les duels se tiennent HORS zone neutre, discrètement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_03', 'NPC_ALN_54', 'K0', '{"reseau","gattan"}', 'Que le circuit est relié à Gattan via Sly `NPC_GAT_87`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_04', 'NPC_ALN_54', 'K1', '{"cotes","calcul"}', 'Comment elle établit les cotes (lecture des combattants)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_05', 'NPC_ALN_54', 'K1', '{"combattants","della"}', 'Qui se bat, et comment Della `NPC_ALN_76` recrute les duellistes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_06', 'NPC_ALN_54', 'K1', '{"mises","gros-parieurs"}', 'Les gros parieurs récurrents et leurs manies', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_07', 'NPC_ALN_54', 'K2', '{"duel","truque"}', 'Un duel dont l''issue était vendue d''avance — le pari « sûr »', '`AFF>=85+QUEST:QST_NEU_DUEL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_08', 'NPC_ALN_54', 'K2', '{"duel","execution"}', 'Sa gêne : certains « duels » ne sont pas des combats loyaux', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_09', 'NPC_ALN_54', 'K3', '{"pari","contrat-pk"}', 'Elle sait que des paris couvrent en réalité des contrats de PK : miser sur « qui gagne » revient à financer une exécution, et son carnet de cotes est la comptabilité d''un meurtre déguisé', NULL, '*(elle referme son registre de cotes)* « Je fais des maths, pas de la morale. Un duel, deux combattants, une cote. Ce qui arrive au perdant, c''est du sport, pas mon problème. Tu paries, ou tu regardes ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_54_10', 'NPC_ALN_54', 'KX', '{"*(hors sujet)*"}', '« Il n''y a pas de cote là-dessus, donc ça ne m''intéresse pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_01', 'NPC_ALN_55', 'K0', '{"recel","rachat"}', 'Ce qu''elle rachète, à quelle décote, comment vendre discret', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_02', 'NPC_ALN_55', 'K0', '{"ruelle","discretion"}', 'Les règles de la Ruelle du Dôme, comment ne pas se faire remarquer', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_03', 'NPC_ALN_55', 'K0', '{"ecoulement","revente"}', 'Comment elle revend sans traçabilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_04', 'NPC_ALN_55', 'K1', '{"reseau","gattan"}', 'Le circuit avec Snyk `NPC_GAT_80` (production détournée de la Forge de Gattan)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_05', 'NPC_ALN_55', 'K1', '{"objets","provenance"}', 'Comment elle « nettoie » l''origine d''un objet volé', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_06', 'NPC_ALN_55', 'K1', '{"rask","transport"}', 'Comment Rask `NPC_ALN_57` fait entrer et sortir ses lots', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_07', 'NPC_ALN_55', 'K2', '{"lot","armes"}', 'Le lot d''armes militaires neuves de la garde de Gattan qui l''a inquiétée', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_08', 'NPC_ALN_55', 'K2', '{"acheteur","unique"}', 'L''acheteur unique qui rachète tout l''armement d''un coup, sans marchander', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_09', 'NPC_ALN_55', 'K3', '{"armement","cellule"}', 'Elle a compris qu''elle arme une cellule préparant un coup contre la neutralité d''Alne — elle continue par cupidité et par peur, en se répétant qu''elle « n''est qu''un intermédiaire »', NULL, '*(elle range un objet sous une bâche)* « Je recèle des babioles, moi. Des bricoles tombées d''un chariot. Des " armes de guerre ", des " cellules " ? Tu lis trop de romans. Je rachète, je revends, je ne pense pas. Tu vends quelque chose, oui ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_55_10', 'NPC_ALN_55', 'KX', '{"*(hors sujet)*"}', '« Ça ne se revend pas, donc ça ne m''intéresse pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_01', 'NPC_ALN_56', 'K0', '{"faux","catalogue"}', 'Faux papiers courants : sceaux, laissez-passer, attestations — tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_02', 'NPC_ALN_56', 'K0', '{"ruelle","discretion"}', 'Comment la commander sans se faire remarquer', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_03', 'NPC_ALN_56', 'K0', '{"calligraphie","service"}', 'Ses services d''imitation de main et de sceau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_04', 'NPC_ALN_56', 'K1', '{"sceaux","guildes"}', 'Quels sceaux de guilde elle sait reproduire, et leurs usages', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_05', 'NPC_ALN_56', 'K1', '{"contrats","clauses"}', 'Les clauses piégées qu''elle glisse dans les contrats (Sept-Doigts `NPC_ALN_53`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_06', 'NPC_ALN_56', 'K1', '{"reseau","clients"}', 'Ses clients récurrents du marché noir (Kael 07, Denn 23, Osk 33)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_07', 'NPC_ALN_56', 'K2', '{"dome","laissez-passer"}', 'Qu''elle peut forger un droit d''entrée au Dôme accepté par le Système', '`AFF>=85+PAY:800`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_08', 'NPC_ALN_56', 'K2', '{"encre","prend-seule"}', 'Le phénomène de « l''encre qui prend seule » sur ses faux les plus puissants', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_09', 'NPC_ALN_56', 'K3', '{"faux","ecrit-systeme"}', 'Ses faux les plus réussis « écrivent » réellement dans les règles du monde — elle ne falsifie pas un document, elle réécrit brièvement le Système ; c''est la même main que celle qui réécrit les livres, et ça la terrifie', NULL, '*(elle souffle sur une encre encore fraîche)* « Je fais de jolis faux, très convaincants, rien de plus. Un morceau de papier ne change pas le monde. Si mes documents " fonctionnent trop bien ", c''est que je suis douée, point. Tu voulais quel sceau ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_56_10', 'NPC_ALN_56', 'KX', '{"*(hors sujet)*"}', '« Ça ne se contrefait pas, donc ce n''est pas mon rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_01', 'NPC_ALN_57', 'K0', '{"contrebande","service"}', 'Faire passer un colis discret, tarifs, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_02', 'NPC_ALN_57', 'K0', '{"routes","douanes"}', 'Comment il évite les contrôles des 9 routes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_03', 'NPC_ALN_57', 'K0', '{"ruelle","contact"}', 'Comment le contacter dans la Ruelle du Dôme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_04', 'NPC_ALN_57', 'K1', '{"itineraires","caches"}', 'Ses routes détournées et leurs points de transit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_05', 'NPC_ALN_57', 'K1', '{"clients","reseau"}', 'Pour qui il transporte (Morne 55, Kael 07, Grède 26, Peppin 29)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_06', 'NPC_ALN_57', 'K1', '{"ferd","planque"}', 'Comment il utilise la halte de Ferd `NPC_ALN_19` comme relais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_07', 'NPC_ALN_57', 'K2', '{"route","non-surveillee"}', 'La route que « personne ne surveille » — et pourquoi elle est si sûre', '`AFF>=85+QUEST:QST_NEU_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_08', 'NPC_ALN_57', 'K2', '{"cargaison","armes"}', 'La cargaison d''armes qu''il déplace pour la cellule, en quantité anormale', '`QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_09', 'NPC_ALN_57', 'K3', '{"route","hors-carte"}', 'Sa route la plus sûre passe par la « région effacée » des cartes d''Alba `NPC_ALN_18` — un lieu que le Système ne référence pas, donc que nulle douane ne peut surveiller ; il l''exploite sans vouloir savoir ce qu''est cet endroit', NULL, '*(il resserre la sangle d''un ballot)* « Je prends les petits chemins, c''est tout le secret. Des sentiers de chèvre que les douaniers connaissent pas. Y''a pas de " lieu qui existe pas ", faut arrêter. Ton colis, il part quand ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_57_10', 'NPC_ALN_57', 'KX', '{"*(hors sujet)*"}', '« Ça ne se transporte pas, donc ça ne me concerne pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_01', 'NPC_ALN_58', 'K0', '{"rumeurs","service"}', 'Qu''elle vend de l''information, tarifs indicatifs selon la « fraîcheur »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_02', 'NPC_ALN_58', 'K0', '{"reseau","gattan"}', 'Que son réseau relie Alne à Gattan via Fitch `NPC_GAT_89`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_03', 'NPC_ALN_58', 'K0', '{"ruelle","contact"}', 'Comment la trouver et négocier discrètement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_04', 'NPC_ALN_58', 'K1', '{"rumeurs","marche"}', 'Les rumeurs générales fraîches d''Alne (tout venant, monnayable)', '`AFF>=60+PAY:50`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_05', 'NPC_ALN_58', 'K1', '{"secrets","courtage"}', 'Comment elle achète un secret pour le revendre (mécanique de courtage)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_06', 'NPC_ALN_58', 'K1', '{"cassia","reputation"}', 'Comment ses rumeurs alimentent le commerce de réputation de Cassia `NPC_ALN_25`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_07', 'NPC_ALN_58', 'K2', '{"secret","revendu"}', 'Un secret K2 précis d''un autre PNJ, qu''elle vend contre gros paiement', '`AFF>=85+PAY:600`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_08', 'NPC_ALN_58', 'K2', '{"cellule","rumeur"}', 'La rumeur qu''elle a captée sur la cellule anti-neutralité — et qu''elle hésite à vendre', '`QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_09', 'NPC_ALN_58', 'K3', '{"reseau","surveillance"}', 'Son réseau inter-cités est en réalité si complet qu''elle pourrait cartographier les mouvements de la cellule — et elle craint que la connaissance qu''elle détient fasse d''elle la prochaine « disparue »', NULL, '*(elle fait mine de s''éloigner dans l''ombre)* « Je vends des ragots de comptoir, mon chou, pas des secrets d''État. Des " cellules ", des " complots " ? Ça, c''est trop cher pour toi et trop dangereux pour moi. Prends une rumeur légère et va-t''en. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_58_10', 'NPC_ALN_58', 'KX', '{"*(hors sujet)*"}', '« Personne ne sait ça, donc je ne peux pas te le vendre. Reviens avec une vraie question. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_01', 'NPC_ALN_59', 'K0', '{"tatouage","cosmetique"}', 'Tatouages cosmétiques (`!outfit` corporel), motifs, prix affichés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_02', 'NPC_ALN_59', 'K0', '{"ruelle","discretion"}', 'Comment le trouver, comment on ne parle pas de son vrai commerce', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_03', 'NPC_ALN_59', 'K0', '{"statut-pk","base"}', 'Ce qu''est le statut de tueur (marque orange/rouge) et ses effets publics', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_04', 'NPC_ALN_59', 'K1', '{"marque","pose"}', 'Comment il pose (ou renforce) une marque de PK', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_05', 'NPC_ALN_59', 'K1', '{"brogg","signalement"}', 'Comment Brogg `NPC_ALN_52` lui envoie des indésirables à marquer', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_06', 'NPC_ALN_59', 'K1', '{"encres","materiaux"}', 'Les encres spéciales qu''il utilise (croise Zarn de Gattan `NPC_GAT_60`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_07', 'NPC_ALN_59', 'K2', '{"marque","effacement"}', 'Qu''il peut EFFACER un statut de tueur — rendre un PK à nouveau « propre »', '`AFF>=85+PAY:1000`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_08', 'NPC_ALN_59', 'K2', '{"clients","hors-la-loi"}', 'Quels criminels notoires il a « nettoyés » (sans les nommer d''emblée)', '`AFF>=92`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_09', 'NPC_ALN_59', 'K3', '{"statut","ecrit-systeme"}', 'Son encre d''effacement modifie directement le statut PK dans le Système — un pouvoir de réécriture d''état-joueur qui ne devrait pas exister ; il soupçonne que « quelqu''un très haut » ferme les yeux parce que ça sert un dessein', NULL, '*(il essuie son aiguille, sans lever la tête)* « Je fais des dessins sur la peau. De jolis dessins. Effacer un statut de tueur ? Impossible, seul le Système décide de ça. Tu as vu trop de racontars de ruelle. Tu veux un tatouage, ou tu veux sortir ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_59_10', 'NPC_ALN_59', 'KX', '{"*(hors sujet)*"}', '« Ça ne se tatoue pas, donc je ne saurais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_01', 'NPC_ALN_60', 'K0', '{"banque","services"}', 'Dépôt, retrait, virements — `!bank_depot` / `!bank_retrait`, frais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_02', 'NPC_ALN_60', 'K0', '{"reseau","succursales"}', 'Le réseau inter-cités (succursale de Gattan : Ora `NPC_GAT_92`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_03', 'NPC_ALN_60', 'K0', '{"coffres","garantie"}', 'Garantie des dépôts, différence avec la consigne de Lom `NPC_ALN_46`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_04', 'NPC_ALN_60', 'K1', '{"prets","guildes"}', 'Les prêts de guilde légitimes, taux, garanties exigées', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_05', 'NPC_ALN_60', 'K1', '{"flux","economie"}', 'Sa lecture des grands flux financiers du serveur (santé économique)', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_06', 'NPC_ALN_60', 'K1', '{"change","devises"}', 'Le change entre monnaies raciales, les taux (croise Baldo de Gattan `NPC_GAT_49`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_07', 'NPC_ALN_60', 'K2', '{"comptes","anonymes"}', 'Les transferts massifs vers des comptes anonymes qu''elle a repérés', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_08', 'NPC_ALN_60', 'K2', '{"flux","armes"}', 'Que ces flux suivent le rythme des livraisons d''armes de la Ruelle', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_09', 'NPC_ALN_60', 'K3', '{"financement","cellule"}', 'Elle détient la preuve comptable que la cellule anti-neutralité est financée par un commanditaire fortuné — un nom figure dans ses registres, qu''elle protège par peur et par secret bancaire', NULL, '*(elle referme le grand livre d''un geste net)* « Le secret bancaire est absolu, monsieur. Je ne commente aucun compte, aucun flux, aucun nom. C''est ce qui fait la solidité d''Alne. Votre dépôt, à présent ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_60_10', 'NPC_ALN_60', 'KX', '{"*(hors sujet)*"}', '« Cela ne relève pas des affaires bancaires. Je ne peux vous renseigner. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_01', 'NPC_ALN_61', 'K0', '{"poste","services"}', 'Envoi de lettres/colis (`!mail_send`), tarifs, délais inter-cités', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_02', 'NPC_ALN_61', 'K0', '{"reseau","antennes"}', 'Le réseau des 9 cités (antenne de Gattan : Currun `NPC_GAT_93`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_03', 'NPC_ALN_61', 'K0', '{"colis","regles"}', 'Ce qui peut ou non être expédié, les objets interdits au courrier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_04', 'NPC_ALN_61', 'K1', '{"flux","correspondances"}', 'Le volume de courrier entre cités — un baromètre des relations inter-races', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_05', 'NPC_ALN_61', 'K1', '{"colis","suspects"}', 'Les colis « trop lourds » qu''il fait parfois inspecter', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_06', 'NPC_ALN_61', 'K1', '{"mandats","ovena"}', 'Les mandats postaux adossés à la banque d''Ovena `NPC_ALN_60`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_07', 'NPC_ALN_61', 'K2', '{"colis","fantomes"}', 'Les colis sans expéditeur ni destinataire réels qui traversent son réseau', '`AFF>=85+QUEST:QST_NEU_POSTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_08', 'NPC_ALN_61', 'K2', '{"disparition","avant-livraison"}', 'Que ces colis fantômes s''évanouissent avant d''être remis, sans trace', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_09', 'NPC_ALN_61', 'K3', '{"reseau","canal-systeme"}', 'Il pense que son réseau postal sert de « canal » à quelque chose qui n''est pas un client — des messages du Système lui-même transitant par la poste, comme si l''infrastructure d''Alne était détournée par le Cardinal pour communiquer', NULL, '*(il tamponne un peu trop fort un pli)* « La Poste d''Alne est parfaitement fiable, monsieur. Chaque colis a un expéditeur, chaque lettre un destinataire. Les " colis fantômes " sont des erreurs d''affranchissement, rien de plus. Votre envoi part où ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_61_10', 'NPC_ALN_61', 'KX', '{"*(hors sujet)*"}', '« Cela ne passe pas par mon guichet, donc je l''ignore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_01', 'NPC_ALN_62', 'K0', '{"contrats","service"}', 'Rédaction, scellé, garantie de contrats inter-races — tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_02', 'NPC_ALN_62', 'K0', '{"guildes","alliances"}', 'Actes de guilde, alliances, engagements de mercenaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_03', 'NPC_ALN_62', 'K0', '{"garantie","neutralite"}', 'Pourquoi un contrat scellé à Alne est réputé inviolable', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_04', 'NPC_ALN_62', 'K1', '{"clauses","pieges"}', 'Comment repérer une clause piégée (met en garde contre Quill `NPC_ALN_56`)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_05', 'NPC_ALN_62', 'K1', '{"litiges","arbitrage"}', 'Comment se règle un litige de contrat (renvoi Conclave, Aldwin `NPC_ALN_08`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_06', 'NPC_ALN_62', 'K1', '{"actes","archives"}', 'L''organisation de ses archives d''actes scellés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_07', 'NPC_ALN_62', 'K2', '{"contrat","inannulable"}', 'L''acte ancien qu''il ne peut ni annuler ni relire en entier', '`AFF>=85+QUEST:QST_NEU_CONTRAT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_08', 'NPC_ALN_62', 'K2', '{"parties","inconnues"}', 'Qu''il ignore qui sont les parties de ce contrat — les noms sont « illisibles »', '`AFF>=92`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_09', 'NPC_ALN_62', 'K3', '{"contrat","fondation"}', 'Il soupçonne que cet acte est le « contrat fondateur » d''Alne — celui qui lie la ville au Système et garantit l''anti-PK ; le rompre déferait la neutralité elle-même, ce qui explique pourquoi la cellule le cherche', NULL, '*(il replace un rouleau scellé dans un coffre à triple serrure)* « Le secret notarial est sacré, comme le secret bancaire. Cet acte-là ne vous concerne pas, ne me concerne pas vraiment non plus, et ne sera jamais ouvert. Voilà. Vous vouliez faire rédiger quoi ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_62_10', 'NPC_ALN_62', 'KX', '{"*(hors sujet)*"}', '« Cela ne fait l''objet d''aucun acte, je ne peux donc rien attester. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_01', 'NPC_ALN_63', 'K0', '{"taxes","bareme"}', 'Le barème des taxes de marché, de passage, d''étal', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_02', 'NPC_ALN_63', 'K0', '{"paiement","procedure"}', 'Comment s''acquitter, exemptions, pénalités de retard', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_03', 'NPC_ALN_63', 'K0', '{"recettes","usage"}', 'À quoi servent officiellement les taxes (garde, entretien, Conclave)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_04', 'NPC_ALN_63', 'K1', '{"fraude","evasion"}', 'Qui fraude le fisc du marché, comment il les repère', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_05', 'NPC_ALN_63', 'K1', '{"registres","flux"}', 'Sa lecture fiscale de l''économie d''Alne (qui prospère, qui coule)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_06', 'NPC_ALN_63', 'K1', '{"bost","chevauchement"}', 'Les zones grises entre ses taxes et les « faveurs » de Bost `NPC_ALN_24`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_07', 'NPC_ALN_63', 'K2', '{"taxe","sans-beneficiaire"}', 'La taxe dont les fonds ne vont à aucun bénéficiaire identifiable', '`AFF>=85+QUEST:QST_NEU_TAXE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_08', 'NPC_ALN_63', 'K2', '{"ligne","opaque"}', 'La ligne de compte opaque où cette taxe s''évanouit chaque mois', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_09', 'NPC_ALN_63', 'K3', '{"taxe","dime-systeme"}', 'Il en est venu à croire que cette taxe est une « dîme » prélevée par le Système lui-même — comme si le monde faisait payer aux joueurs un impôt invisible dont le Cardinal serait le seul bénéficiaire', NULL, '*(il aligne nerveusement ses jetons de compte)* « Toutes les taxes ont un usage dûment consigné, monsieur. L''administration d''Alne est irréprochable. Une ligne " sans bénéficiaire ", ce serait une faute comptable, et je n''en commets pas. Réglez votre dû, je vous prie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_63_10', 'NPC_ALN_63', 'KX', '{"*(hors sujet)*"}', '« Cela n''entre dans aucune catégorie fiscale. Je ne peux rien pour vous. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_01', 'NPC_ALN_64', 'K0', '{"annonces","jour"}', 'Les annonces publiques du jour (Conclave, marché, garde)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_02', 'NPC_ALN_64', 'K0', '{"evenements","sys"}', 'Les événements serveur qu''elle relaie (`SYS_*` — invasions, festivals)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_03', 'NPC_ALN_64', 'K0', '{"ville","orientation"}', 'Renseignements généraux, orientation des nouveaux venus', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_04', 'NPC_ALN_64', 'K1', '{"annonces","historique"}', 'Ce qui a été annoncé récemment (sa mémoire d''archive vivante)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_05', 'NPC_ALN_64', 'K1', '{"rumeurs","officielles"}', 'La différence entre l''annonce officielle et ce que les gens en disent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_06', 'NPC_ALN_64', 'K1', '{"prell","presse"}', 'Ce que la gazette de Prell `NPC_ALN_89` publie et ce qu''elle tait', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_07', 'NPC_ALN_64', 'K2', '{"annonce","contredite"}', 'Une annonce actuelle qui contredit ce qu''elle a crié le mois passé', '`AFF>=85+QUEST:QST_NEU_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_08', 'NPC_ALN_64', 'K2', '{"correction","silence"}', 'Qu''on lui a « corrigé » des annonces sans explication, en lui demandant d''oublier les anciennes', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_09', 'NPC_ALN_64', 'K3', '{"histoire","direct"}', 'Elle est la preuve vivante que l''histoire récente d''Alne est réécrite en temps réel : sa mémoire de crieuse ne « colle » plus aux registres officiels, et elle craint qu''on finisse par corriger sa mémoire aussi', NULL, '*(elle éclate d''un rire trop fort)* « Moi, contredire une annonce ? Jamais ! Je crie ce que le Conclave dit, et le Conclave a toujours raison, et a toujours eu raison. Si ma mémoire dit autre chose, c''est ma mémoire qui se trompe. Oyez, oyez, passons à autre chose ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_64_10', 'NPC_ALN_64', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas été annoncé, donc ça n''existe pas encore. Reviens quand ce sera crié. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_01', 'NPC_ALN_65', 'K0', '{"cosmetique","service"}', 'Coiffure, traits, couleurs — `!outfit`, tarifs de métamorphose', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_02', 'NPC_ALN_65', 'K0', '{"styles","races"}', 'Les styles emblématiques des 9 races (inspiration cosmétique)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_03', 'NPC_ALN_65', 'K0', '{"tenues","renvoi"}', 'Compléter le look avec Ison `NPC_ALN_66` (tenues)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_04', 'NPC_ALN_65', 'K1', '{"metamorphose","limites"}', 'Ce qu''iel peut changer, ce qui reste immuable (identité de compte)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_05', 'NPC_ALN_65', 'K1', '{"clients","transformations"}', 'Les métamorphoses marquantes qu''iel a réalisées (anonymisées)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_06', 'NPC_ALN_65', 'K1', '{"ode","visages"}', 'Ce qu''Ode `NPC_ALN_83` « voit » que Vane ne peut pas peindre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_07', 'NPC_ALN_65', 'K2', '{"client","disparaitre"}', 'Le client qui voulait devenir totalement méconnaissable', '`AFF>=85+QUEST:QST_NEU_VISAGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_08', 'NPC_ALN_65', 'K2', '{"trait","efface"}', 'Le dernier trait reconnaissable qu''iel a effacé — et le tatouage qu''il cachait', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_09', 'NPC_ALN_65', 'K3', '{"anonymat","complice"}', 'Iel soupçonne d''avoir métamorphosé un membre (ou le chef) de la cellule anti-neutralité pour qu''il se fonde dans Alne — et de porter, sans l''avoir voulu, la responsabilité de ce qu''il prépare', NULL, '*(iel range ses ciseaux, sourire crispé)* « Je change des coiffures et des couleurs, mon chou, pas des destins. Tous mes clients repartent plus beaux, c''est tout. Qui ils étaient avant, qui ils fuient — ça ne me regarde pas. Une petite retouche pour toi ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_65_10', 'NPC_ALN_65', 'KX', '{"*(hors sujet)*"}', '« Ça ne se coiffe pas, donc je n''y touche pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_01', 'NPC_ALN_66', 'K0', '{"tenues","catalogue"}', 'Capes, tenues, équipement léger T1-T2 des 9 races — prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_02', 'NPC_ALN_66', 'K0', '{"couture","service"}', 'Retouches, ajustements, confection sur mesure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_03', 'NPC_ALN_66', 'K0', '{"etoffes","milla"}', 'D''où viennent ses tissus (Milla `NPC_ALN_27`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_04', 'NPC_ALN_66', 'K1', '{"styles","races"}', 'Les codes vestimentaires des 9 races et ce qu''ils signalent', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_05', 'NPC_ALN_66', 'K1', '{"capes","vol"}', 'Les capes qui aident au vol / réduisent la détection (bonus légers)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_06', 'NPC_ALN_66', 'K1', '{"tenues","deguisement"}', 'Comment une tenue peut faire passer pour une autre race (croise Milla)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_07', 'NPC_ALN_66', 'K2', '{"doublure","secrete"}', 'Le service de doublure/poche cachée qu''il coud sur commande', '`AFF>=85+PAY:200`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_08', 'NPC_ALN_66', 'K2', '{"rask","clients"}', 'Que Rask `NPC_ALN_57` et d''autres commandent des vêtements « à compartiment »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_09', 'NPC_ALN_66', 'K3', '{"doublure","arme"}', 'Il a cousu des doublures conçues pour dissimuler des armes en zone neutre — contournant la « fouille » du Système — et il sait désormais que ses vêtements servent la cellule anti-neutralité', NULL, '*(il lisse un revers avec un soin exagéré)* « Je couds de belles doublures pour protéger du froid, voilà tout. Des " compartiments à armes " ? Quelle idée. Un tailleur habille, il ne conspire pas. Vous vouliez une cape, je crois ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_66_10', 'NPC_ALN_66', 'KX', '{"*(hors sujet)*"}', '« Ça ne se coud pas, donc ce n''est pas mon métier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_01', 'NPC_ALN_67', 'K0', '{"ecriture","service"}', 'Rédaction de lettres, plaintes, demandes — tarifs à la ligne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_02', 'NPC_ALN_67', 'K0', '{"formulaires","demarches"}', 'Aide aux démarches administratives d''Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_03', 'NPC_ALN_67', 'K0', '{"poste","notaire"}', 'Où envoyer (Cael `NPC_ALN_61`) ou faire sceller (Verd `NPC_ALN_62`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_04', 'NPC_ALN_67', 'K1', '{"lettres","usages"}', 'Comment tourner une lettre selon son but (supplique, menace polie, aveu)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_05', 'NPC_ALN_67', 'K1', '{"illettres","clientele"}', 'Qui vient dicter, et les grands types de confidences (anonymisés)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_06', 'NPC_ALN_67', 'K1', '{"contrats","simples"}', 'Les contrats simples qu''iel rédige (les complexes → Verd `NPC_ALN_62`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_07', 'NPC_ALN_67', 'K2', '{"lettre","retenue"}', 'Une lettre précise dictée par un client — dont iel a tout retenu', '`AFF>=85+PAY:250`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_08', 'NPC_ALN_67', 'K2', '{"confidences","poids"}', 'Les secrets qu''iel porte et qui l''empêchent de dormir', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_09', 'NPC_ALN_67', 'K3', '{"lettre","menace"}', 'Iel a écrit, sous la dictée, une lettre de menace destinée à un dignitaire du Conclave — signée d''un nom qu''iel a reconnu, lié à la cellule anti-neutralité — et iel vit dans la terreur d''avoir été le témoin qu''on fera taire', NULL, '*(iel repose sa plume, mains jointes)* « Le secret du scribe est sacré, comme celui du prêtre. Ce qu''on me dicte meurt dans mon encre et dans ma mémoire. Je n''ai écrit aucune menace, je ne connais aucun nom. Vous vouliez faire écrire quoi ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_67_10', 'NPC_ALN_67', 'KX', '{"*(hors sujet)*"}', '« Cela ne se met pas en lettres, je ne saurais l''écrire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_01', 'NPC_ALN_68', 'K0', '{"vol","apprentissage"}', 'Comment apprendre à voler, les skills aériens de base, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_02', 'NPC_ALN_68', 'K0', '{"oss-aeriens","catalogue"}', 'Les Original Sword Skills aériens qu''elle enseigne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_03', 'NPC_ALN_68', 'K0', '{"mana","vol"}', 'Le coût en mana du vol (renvoi armures de Lyra `NPC_ALN_05`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_04', 'NPC_ALN_68', 'K1', '{"manoeuvres","combat"}', 'Les manœuvres de charge/esquive aérienne en combat', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_05', 'NPC_ALN_68', 'K1', '{"courants","canopee"}', 'Comment exploiter les courants de la Canopée (croise Corvin `NPC_ALN_16`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_06', 'NPC_ALN_68', 'K1', '{"endurance","altitude"}', 'Les limites d''altitude et d''endurance de vol, comment les repousser', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_07', 'NPC_ALN_68', 'K2', '{"technique","interdite"}', 'L''existence du mouvement de vol qu''elle refuse d''enseigner en ville', '`AFF>=85+QUEST:QST_NEU_VOL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_08', 'NPC_ALN_68', 'K2', '{"hauteurs","interdites"}', 'Où mène ce vol — les hauteurs « qu''on n''est pas censé atteindre »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_09', 'NPC_ALN_68', 'K3', '{"vol","hors-limites"}', 'Son mouvement permet de franchir les murs invisibles du monde et d''atteindre le sommet du Dôme par l''extérieur — un exploit géométrique que le Système ne prévoit pas ; elle l''a vu mener quelqu''un « au-delà », et cette personne n''est jamais revenue', NULL, '*(elle referme ses ailes d''un coup sec)* « Il n''existe pas de vol " magique " qui traverse les murs. Le ciel a ses limites comme tout le reste. Ce que tu as entendu est une légende de tavernier. Je t''enseigne le vol honnête, ou rien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_68_10', 'NPC_ALN_68', 'KX', '{"*(hors sujet)*"}', '« Ça ne se pratique pas dans les airs, donc ce n''est pas mon domaine. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
