INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_04', 'NPC_ALN_69', 'K1', '{"enchainements","combos"}', 'Les enchaînements avancés de Sword Skills (méta de combat)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_05', 'NPC_ALN_69', 'K1', '{"faiblesses","styles"}', 'Les failles de chaque style, comment contrer les 9 écoles', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_06', 'NPC_ALN_69', 'K1', '{"discipline","mental"}', 'La part mentale du duel, lire l''adversaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_07', 'NPC_ALN_69', 'K2', '{"botte","existence"}', 'L''existence de sa botte secrète qui l''a rendu invaincu', '`AFF>=85+QUEST:QST_NEU_ESCRIME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_08', 'NPC_ALN_69', 'K2', '{"botte","principe"}', 'Le principe général de son coup — sans le geste exact', '`AFF>=92+TITLE:TITLE_NEU_DUELLISTE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_09', 'NPC_ALN_69', 'K3', '{"botte","exploit"}', 'Sa botte exploite une faille du timing des Sword Skills (un « cancel » impossible) qui garantit la victoire ; il la garde secrète pour ne pas briser l''équilibre PvP d''Alfheim, sachant que le Système ne l''a jamais corrigée', NULL, '*(il abaisse sa lame d''entraînement)* « Il n''y a pas de coup magique, seulement des années de travail. Ceux qui cherchent un raccourci vers l''invincibilité ne deviennent jamais de vrais escrimeurs. La leçon est finie. En garde une prochaine fois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_69_10', 'NPC_ALN_69', 'KX', '{"*(hors sujet)*"}', '« Ça ne se tranche pas, donc ça ne s''enseigne pas ici. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_01', 'NPC_ALN_70', 'K0', '{"magie","apprentissage"}', 'Comment apprendre la magie, les écoles élémentaires de base, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_02', 'NPC_ALN_70', 'K0', '{"ecoles","elements"}', 'Les écoles des 9 races et leurs éléments dominants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_03', 'NPC_ALN_70', 'K0', '{"mana","gestion"}', 'La gestion du mana, les sorts de base par école', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_04', 'NPC_ALN_70', 'K1', '{"sorts","avances"}', 'Les sorts avancés et les combinaisons inter-écoles', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_05', 'NPC_ALN_70', 'K1', '{"ponts","traditions"}', 'Les ponts qu''elle a établis entre écoles rivales (méta de mage)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_06', 'NPC_ALN_70', 'K1', '{"osk","parchemins"}', 'Sa mise en garde contre le parchemin « bugué » d''Osk `NPC_ALN_33`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_07', 'NPC_ALN_70', 'K2', '{"ecole","sans-nom"}', 'L''existence d''une magie qui ne relève d''aucun élément', '`AFF>=85+QUEST:QST_NEU_MAGIE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_08', 'NPC_ALN_70', 'K2', '{"unification","principe"}', 'Ce qu''elle a compris de ce qui « unifie » toutes les écoles', '`AFF>=92+TITLE:TITLE_NEU_ARCHIMAGE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_09', 'NPC_ALN_70', 'K3', '{"magie","langue-source"}', 'L''école sans nom est la magie de la « langue-source » — celle dans laquelle le monde est écrit ; la manier reviendrait à modifier les règles du Système, et elle soupçonne que c''est ainsi que l''histoire elle-même est réécrite', NULL, '*(elle laisse une flamme s''éteindre au creux de sa paume)* « Il n''y a que les écoles connues, celles que j''enseigne. Une " magie sans élément " ? Une belle rêverie d''apprenti. La vraie maîtrise, c''est la profondeur, pas les secrets imaginaires. Quelle école veux-tu étudier ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_70_10', 'NPC_ALN_70', 'KX', '{"*(hors sujet)*"}', '« Cela ne relève d''aucune école magique. Je ne saurais l''enseigner. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_01', 'NPC_ALN_71', 'K0', '{"apprivoisement","base"}', 'Comment apprivoiser un familier, `!tame`, prérequis, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_02', 'NPC_ALN_71', 'K0', '{"familiers","especes"}', 'Quelles bêtes s''apprivoisent, leurs aptitudes (renvoi Pako `NPC_ALN_32`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_03', 'NPC_ALN_71', 'K0', '{"dressage","ordres"}', 'Les ordres de base d''un familier au combat/transport', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_04', 'NPC_ALN_71', 'K1', '{"liens","affinite"}', 'Comment renforcer le lien, les affinités par tempérament', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_05', 'NPC_ALN_71', 'K1', '{"rares","apprivoisement"}', 'Les familiers rares et les techniques pour les gagner', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_06', 'NPC_ALN_71', 'K1', '{"mob-air","canopee"}', 'Apprivoiser des créatures aériennes (croise Corvin `NPC_ALN_16`, Zephyrine `NPC_ALN_68`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_07', 'NPC_ALN_71', 'K2', '{"bete","resistante"}', 'La créature qui résiste à toutes ses techniques — celle de Pako `NPC_ALN_32`', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_08', 'NPC_ALN_71', 'K2', '{"bete","regard"}', 'Ce que la bête « comprend » qu''aucun familier ne devrait comprendre', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_09', 'NPC_ALN_71', 'K3', '{"creature","conscience"}', 'Elle est convaincue que cette créature n''est pas un animal mais quelque chose de conscient et d''ancien — peut-être un fragment du Système sous forme vivante, un pendant animal de l''Enfant de la Racine `NPC_ALN_00`', NULL, '*(elle caresse le vide, comme une bête absente)* « Toutes les bêtes s''apprivoisent, avec assez de patience. Celle dont tu parles est juste sauvage, très sauvage. Il n''y a pas de " bête consciente " qui lit dans les âmes. Ce serait de la sorcellerie, et je ne fais que du dressage. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_71_10', 'NPC_ALN_71', 'KX', '{"*(hors sujet)*"}', '« Ça ne s''apprivoise pas, donc ce n''est pas mon art. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_01', 'NPC_ALN_72', 'K0', '{"alchimie","apprentissage"}', 'Comment apprendre l''alchimie, recettes de base, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_02', 'NPC_ALN_72', 'K0', '{"potions","catalogue"}', 'Potions/poisons/bombes courants et leurs composants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_03', 'NPC_ALN_72', 'K0', '{"composants","herboristes"}', 'Où trouver les composants (Ophrys `NPC_ALN_28`, Yssa `NPC_ALN_15`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_04', 'NPC_ALN_72', 'K1', '{"recettes","avancees"}', 'Les transmutations avancées, potions de haut tier', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_05', 'NPC_ALN_72', 'K1', '{"poisons","remedes"}', 'La frontière poison/remède, dosages critiques', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_06', 'NPC_ALN_72', 'K1', '{"seve","catalyseur"}', 'L''usage de la sève d''Yggdrasil comme catalyseur rare', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_07', 'NPC_ALN_72', 'K2', '{"formule","interdite"}', 'L''existence de la transmutation qu''il refuse de transmettre', '`AFF>=85+QUEST:QST_NEU_ALCHIMIE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_08', 'NPC_ALN_72', 'K2', '{"transmutation","principe"}', 'Le principe de ce qu''elle fait — « changer la nature même d''une chose »', '`AFF>=92+TITLE:TITLE_NEU_ALCHIMISTE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_09', 'NPC_ALN_72', 'K3', '{"formule","exploit"}', 'Sa formule interdite transmute des propriétés que le Système fige (délier un objet lié, purifier une malédiction permanente) — elle exploite la même faille que le contrat de Sept-Doigts `NPC_ALN_53`, par la chimie plutôt que par l''écrit', NULL, '*(il bouche précipitamment une fiole)* « Toute transmutation a ses limites, imposées par la nature des choses. On ne " délie " pas ce qui est lié, voyons — ce serait rompre les lois du monde. Ma formule interdite est un fantasme d''apprenti ivre. Tu veux apprendre quoi, de réel ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_72_10', 'NPC_ALN_72', 'KX', '{"*(hors sujet)*"}', '« Ça ne se transmute pas, donc ça ne relève pas de mon art. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_01', 'NPC_ALN_73', 'K0', '{"survie","apprentissage"}', 'Cours de survie de donjon, préparation de raid, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_02', 'NPC_ALN_73', 'K0', '{"dome","prep"}', 'Quoi emporter, comment gérer les ressources au Dôme (renvoi Dorn `NPC_ALN_12`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_03', 'NPC_ALN_73', 'K0', '{"raid","roles"}', 'La composition idéale d''un groupe pour l''Arbre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_04', 'NPC_ALN_73', 'K1', '{"etages","dangers"}', 'Les dangers connus des étages, comment les survivre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_05', 'NPC_ALN_73', 'K1', '{"ressources","gestion"}', 'La gestion des consommables en donjon long (jauges, rationnement)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_06', 'NPC_ALN_73', 'K1', '{"wipe","prevention"}', 'Les erreurs qui causent un wipe de groupe, et comment les éviter', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_07', 'NPC_ALN_73', 'K2', '{"groupe","perdu"}', 'Ce qui est arrivé au groupe qu''elle a perdu là-haut', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_08', 'NPC_ALN_73', 'K2', '{"survie","seule"}', 'Pourquoi elle seule est redescendue — la version qu''elle ose dire', '`AFF>=92`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_09', 'NPC_ALN_73', 'K3', '{"sommet","verite"}', 'Son groupe n''est pas mort au combat : à un certain étage, ils ont « changé » et ont cessé de la reconnaître — elle a fui ce qui les avait remplacés, et sait que le Dôme ne tue pas toujours, parfois il substitue', NULL, '*(elle serre les poings sur la table)* « Ils sont morts au combat, comme des raideurs. C''est tout. J''ai eu de la chance, eux non. Ne me demande pas de détails, je n''en donne pas. La leçon, c''est : ne meurs pas. Le reste ne te regarde pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_73_10', 'NPC_ALN_73', 'KX', '{"*(hors sujet)*"}', '« Ça ne se passe pas en donjon, donc ce n''est pas ma matière. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_01', 'NPC_ALN_74', 'K0', '{"dome","sommet"}', 'Ses récits publics du sommet (spectaculaires, invérifiables)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_02', 'NPC_ALN_74', 'K0', '{"etages","hauts"}', 'Ce qu''il « décrit » des étages hauts du Dôme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_03', 'NPC_ALN_74', 'K0', '{"taverne","tournee"}', 'Qu''il raconte contre une tournée (renvoi Krebs `NPC_ALN_48`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_04', 'NPC_ALN_74', 'K1', '{"recit","details"}', 'Les détails de son ascension (qui changent d''une fois sur l''autre)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_05', 'NPC_ALN_74', 'K1', '{"dangers","hauts"}', 'Les dangers qu''il prétend avoir affrontés (utiles ou fabulés ?)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_06', 'NPC_ALN_74', 'K1', '{"groupe","bran"}', 'Sa version de ce qui est arrivé au groupe de Bran `NPC_ALN_73`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_07', 'NPC_ALN_74', 'K2', '{"sommet","vu"}', 'Ce qu''il jure avoir vu tout en haut — et qui lui échappe à mesure qu''il le dit', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_08', 'NPC_ALN_74', 'K2', '{"memoire","trou"}', 'Les « trous » dans son souvenir, les détails qui s''effacent en temps réel', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_09', 'NPC_ALN_74', 'K3', '{"souvenir","faux"}', 'Il ne sait plus s''il est vraiment monté ou si on a « installé » ce souvenir en lui — il est peut-être la première victime consciente de la réécriture de la mémoire, quelqu''un dont on a édité le passé, et il le sent sans pouvoir le prouver', NULL, '*(il fixe son verre vide, la voix qui tremble)* « Bien sûr que je suis monté ! J''ai le souvenir, là, très net… enfin, il était net. Non, écoute, on ne parle plus du sommet. On ne parle plus. Paie-moi un verre et parle-moi d''autre chose. De n''importe quoi d''autre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_74_10', 'NPC_ALN_74', 'KX', '{"*(hors sujet)*"}', '« Ça, je m''en souviens pas. Je me souviens plus de grand-chose, à vrai dire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_01', 'NPC_ALN_75', 'K0', '{"raids","recrutement"}', 'Rejoindre un raid pour le Dôme, comment s''inscrire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_02', 'NPC_ALN_75', 'K0', '{"groupes","depart"}', 'Les groupes en formation, horaires de départ', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_03', 'NPC_ALN_75', 'K0', '{"dome","prerequis"}', 'Niveau et équipement requis pour monter (renvoi Bran `NPC_ALN_73`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_04', 'NPC_ALN_75', 'K1', '{"recrues","appariement"}', 'Comment elle apparie les profils pour un groupe équilibré', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_05', 'NPC_ALN_75', 'K1', '{"mercenaires","della"}', 'Comment Della `NPC_ALN_76` complète ses groupes en mercenaires', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_06', 'NPC_ALN_75', 'K1', '{"raids","historique"}', 'Quels groupes elle a montés, lesquels ont réussi', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_07', 'NPC_ALN_75', 'K2', '{"commanditaire","paye"}', 'Qu''elle est payée « à la tête » par un commanditaire qu''elle n''a jamais vu', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_08', 'NPC_ALN_75', 'K2', '{"groupes","non-revenus"}', 'Qu''elle « oublie » volontairement les groupes qui ne redescendent pas', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_09', 'NPC_ALN_75', 'K3', '{"recrutement","alimente"}', 'Elle soupçonne d''alimenter délibérément le Dôme en joueurs pour son commanditaire — comme si quelqu''un « nourrissait » l''Arbre de raideurs, et qu''elle en était le rabatteur payé', NULL, '*(elle raccroche un sourire commercial)* « Je rends service, moi ! Je trouve des groupes aux esseulés, c''est tout. Ceux qui ne reviennent pas ? L''Arbre est dangereux, on le sait tous. Un " commanditaire " ? Je travaille pour les pourboires, mon grand. Tu montes, oui ou non ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_75_10', 'NPC_ALN_75', 'KX', '{"*(hors sujet)*"}', '« Ça ne concerne pas les raids, donc ça ne me concerne pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_01', 'NPC_ALN_76', 'K0', '{"mercenaires","service"}', 'Louer un mercenaire (escorte, garde, renfort), tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_02', 'NPC_ALN_76', 'K0', '{"gorak","tank"}', 'Le tank Gorak `NPC_ALN_04` et ses conditions (payer, sinon…)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_03', 'NPC_ALN_76', 'K0', '{"contrats","cadre"}', 'Le cadre légal d''un contrat de mercenaire à Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_04', 'NPC_ALN_76', 'K1', '{"talents","appariement"}', 'Quel mercenaire pour quel besoin (profils, spécialités)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_05', 'NPC_ALN_76', 'K1', '{"raids","vira"}', 'Comment elle fournit Vira `NPC_ALN_75` en raiders à louer', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_06', 'NPC_ALN_76', 'K1', '{"reputation","fiabilite"}', 'La fiabilité de ses mercenaires, lesquels trahissent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_07', 'NPC_ALN_76', 'K2', '{"contrats","gris"}', 'Les contrats « gris » qu''elle place hors zone neutre', '`AFF>=85+PAY:500`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_08', 'NPC_ALN_76', 'K2', '{"duels","nyx"}', 'Comment ses combattants alimentent les duels de Nyx `NPC_ALN_54`', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_09', 'NPC_ALN_76', 'K3', '{"contrat","disparition"}', 'Certaines lignes de son carnet sont des contrats de PK déguisés : le « service » est de faire disparaître une personne — elle les place quand même, en se disant qu''elle ne tient que la plume, pas la lame', NULL, '*(elle ferme son carnet d''un coup sec)* « Je place des escortes et des gardes du corps, rien d''autre. Des " contrats de disparition " ? Tu regardes trop les mauvais côtés d''Alne. Mon carnet est propre. Tu veux louer un bras honnête, ou tu perds mon temps ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_76_10', 'NPC_ALN_76', 'KX', '{"*(hors sujet)*"}', '« Ça ne se loue pas, donc ce n''est pas mon commerce. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_01', 'NPC_ALN_77', 'K0', '{"primes","tableau"}', 'Les primes affichées, cibles, récompenses, preuves exigées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_02', 'NPC_ALN_77', 'K0', '{"contrats","chasse"}', 'Comment accepter une prime et rapporter la capture', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_03', 'NPC_ALN_77', 'K0', '{"pk","recherches"}', 'Le statut des PK recherchés (croise Sten `NPC_ALN_59`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_04', 'NPC_ALN_77', 'K1', '{"cibles","pistes"}', 'Les pistes connues des cibles majeures, leurs habitudes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_05', 'NPC_ALN_77', 'K1', '{"preuves","verification"}', 'Comment elle authentifie une capture (anti-fraude aux primes)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_06', 'NPC_ALN_77', 'K1', '{"reseau","inter-cites"}', 'Les primes partagées avec les autres cités (Flint `NPC_GAT_75`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_07', 'NPC_ALN_77', 'K2', '{"cible","neutre"}', 'La prime sur une cible « neutre » que personne ne retrouve jamais', '`AFF>=85+QUEST:QST_NEU_PRIME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_08', 'NPC_ALN_77', 'K2', '{"nom","efface"}', 'Que le nom de cette cible s''efface des avis de recherche tout seul', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_09', 'NPC_ALN_77', 'K3', '{"cible","protegee"}', 'Elle est convaincue que cette cible est protégée par le Système lui-même — un PNJ ou un joueur que le Cardinal soustrait activement à toute traque, en effaçant son nom ; chasser cette proie reviendrait à défier le monde', NULL, '*(elle décroche un avis vierge du tableau)* « Toutes mes primes sont réelles et traçables. Une " cible que le monde protège " ? C''est bon pour les contes. Si un nom manque, c''est qu''on l''a capturé, ou qu''il n''a jamais existé. Tu prends un contrat, ou tu regardes le tableau ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_77_10', 'NPC_ALN_77', 'KX', '{"*(hors sujet)*"}', '« Il n''y a pas de prime là-dessus, donc ça ne me regarde pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_01', 'NPC_ALN_78', 'K0', '{"fleurs","catalogue"}', 'Bouquets, couronnes, pétales — prix et symboliques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_02', 'NPC_ALN_78', 'K0', '{"alchimie","petales"}', 'Quels pétales pour quelles potions (composants, renvoi Ophrys `NPC_ALN_28`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_03', 'NPC_ALN_78', 'K0', '{"fontaine","voeux"}', 'Les fleurs de vœux et de mémorial (croise Pinn `NPC_ALN_43`, Sorne `NPC_ALN_97`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_04', 'NPC_ALN_78', 'K1', '{"fleurs","rares"}', 'Ses fleurs les plus rares et leurs vertus (buffs mineurs, purification)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_05', 'NPC_ALN_78', 'K1', '{"culture","jardin"}', 'Comment elle cultive des fleurs impossibles à faire pousser ailleurs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_06', 'NPC_ALN_78', 'K1', '{"symbolique","races"}', 'Le langage des fleurs des 9 races (utile en RP/quête sociale)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_07', 'NPC_ALN_78', 'K2', '{"jardin","cimetiere"}', 'Que son jardin secret pousse sur le cimetière des « vrais morts »', '`AFF>=85+QUEST:QST_NEU_VERGER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_08', 'NPC_ALN_78', 'K2', '{"fleurs","disparus"}', 'Que chaque fleur correspond à un compte banni — une mémoire végétale des effacés', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_09', 'NPC_ALN_78', 'K3', '{"jardin","anomalie"}', 'Son jardin est peut-être une des « poches » du verger introuvable : il n''apparaît que là où le monde a « supprimé » quelqu''un, comme si la matière effacée par le Système ressortait sous forme de fleurs', NULL, '*(elle rajuste un bouquet, les yeux baissés)* « J''ai un petit jardin comme tout le monde, avec de la bonne terre, voilà tout. " Poussé sur les morts ", " matière effacée " — quelles idées macabres. Ce sont des fleurs, elles sont belles, prends-en un bouquet et souris un peu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_78_10', 'NPC_ALN_78', 'KX', '{"*(hors sujet)*"}', '« Ça ne fleurit pas, donc ce n''est pas mon jardin. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_01', 'NPC_ALN_79', 'K0', '{"brochettes","menu"}', 'Brochettes, prix de rue, le buff mineur qu''elles donnent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_02', 'NPC_ALN_79', 'K0', '{"buff","food"}', 'Ce que remet d''aplomb sa nourriture (petit regen/VIT)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_03', 'NPC_ALN_79', 'K0', '{"fournisseurs","marche"}', 'D''où vient sa viande (Halle `NPC_ALN_30`) et ses épices (Peppin `NPC_ALN_29`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_04', 'NPC_ALN_79', 'K1', '{"recette","gattan"}', 'Que sa recette vient de Danna `NPC_GAT_55` à Gattan', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_05', 'NPC_ALN_79', 'K1', '{"grill","technique"}', 'Ses tours de main de rôtisseur (cuisson, marinade)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_06', 'NPC_ALN_79', 'K1', '{"rue","ambiance"}', 'Les nouvelles du marché qu''il entend toute la journée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_07', 'NPC_ALN_79', 'K2', '{"dette","danna"}', 'Son projet de retourner payer sa dette à Danna `NPC_GAT_55`', '`AFF>=80+QUEST:QST_NEU_BROCHETTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_08', 'NPC_ALN_79', 'K2', '{"exil","salamander"}', 'Pourquoi il a quitté le territoire Salamander pour la neutralité d''Alne', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_09', 'NPC_ALN_79', 'K3', '{"recette","secret"}', 'La recette de Danna avait un « ingrédient » qu''il n''a jamais pu reproduire, et il soupçonne que Danna elle-même le tenait d''ailleurs — une chaîne de recettes volées qui remonte à un plat originel oublié (écho lointain du plat interdit d''Aubin `NPC_ALN_47`)', NULL, '*(il retourne une brochette, gêné)* « C''est ma recette à moi, hein, juste inspirée d''une amie ! Y''a pas de " secret ", pas d''ingrédient magique. De la bonne viande, du feu, de l''amour. Tiens, goûte, c''est offert, et n''en parle plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_79_10', 'NPC_ALN_79', 'KX', '{"*(hors sujet)*"}', '« Ça ne se grille pas, donc j''y connais rien, moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_01', 'NPC_ALN_80', 'K0', '{"guide","rues"}', 'Il mène où on veut dans Alne pour quelques Yrds', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_02', 'NPC_ALN_80', 'K0', '{"raccourcis","passages"}', 'Les raccourcis et passages « de gamins » de la ville', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_03', 'NPC_ALN_80', 'K0', '{"courses","messages"}', 'Il porte messages et petits colis discrètement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_04', 'NPC_ALN_80', 'K1', '{"rues","qui-va-ou"}', 'Qui traîne où, les allées et venues suspectes qu''il remarque', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_05', 'NPC_ALN_80', 'K1', '{"kipp","gattan"}', 'Les nouvelles de Gattan que lui envoie Kipp `NPC_GAT_84`', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_06', 'NPC_ALN_80', 'K1', '{"cachettes","trous"}', 'Les cachettes de la ville, les trous dans les murs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_07', 'NPC_ALN_80', 'K2', '{"ruelle","vu"}', 'Ce qu''il a vu dans la Ruelle du Dôme sans être remarqué (livraisons d''armes)', '`AFF>=85+QUEST:QST_NEU_NEUTRALITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_08', 'NPC_ALN_80', 'K2', '{"reseau","gamins"}', 'Le réseau d''enfants des rues qui voit tout, entre Alne et Gattan', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_09', 'NPC_ALN_80', 'K3', '{"complot","temoin"}', 'Il a assisté, caché, à une réunion de la cellule anti-neutralité et pourrait identifier ses membres — un savoir qui ferait de ce gamin la prochaine « disparition », s''ils apprenaient ce qu''il a vu', NULL, '*(il recule d''un bond, méfiant)* « J''ai rien vu, moi ! Je suis qu''un gamin, je joue dans les rues, c''est tout ! Les " réunions ", les " complots ", ça me regarde pas. Tu veux que je te guide quelque part, ou tu me veux des ennuis ? Deux Yrds, sinon je file. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_80_10', 'NPC_ALN_80', 'KX', '{"*(hors sujet)*"}', '« Ça, je connais pas. Et je connais tout. Alors ça existe pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_01', 'NPC_ALN_81', 'K0', '{"mendiant","aumone"}', 'Il demande l''aumône, remercie étrangement (« ça compte, un Yrd, ça compte au total »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_02', 'NPC_ALN_81', 'K0', '{"ruelle","presence"}', 'Depuis quand il est là (« toujours, et même avant »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_03', 'NPC_ALN_81', 'K0', '{"rues","souvenirs"}', 'Des souvenirs décousus des rues d''Alne « d''avant »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_04', 'NPC_ALN_81', 'K1', '{"fondation","avant"}', 'Ce qu''il dit d''Alne avant sa fondation officielle', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_05', 'NPC_ALN_81', 'K1', '{"reliques","reconnait"}', 'Les objets « d''avant » de Doss `NPC_ALN_35` qu''il identifie', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_06', 'NPC_ALN_81', 'K1', '{"racine","enfant"}', 'Ce qu''il « comprend » de l''Enfant de la Racine `NPC_ALN_00`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_07', 'NPC_ALN_81', 'K2', '{"testeur","monde-brouillon"}', 'Qu''il prétend avoir « joué » quand le monde était un brouillon inachevé', '`AFF>=85+QUEST:QST_NEU_ZERO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_08', 'NPC_ALN_81', 'K2', '{"relance","oubli"}', 'Sa conviction d''avoir été « oublié » lors d''une remise à zéro du monde', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_09', 'NPC_ALN_81', 'K3', '{"serveur","version-anterieure"}', 'Il est un fragment persistant d''une version antérieure du serveur — la preuve vivante qu''ALO a été « relancé » au moins une fois, et que l''histoire officielle efface cette relance ; le Cardinal le tolère parce que l''effacer risquerait de déchirer quelque chose', NULL, '*(il referme les yeux, murmure)* « Chut. Je dis n''importe quoi, tout le monde le sait. Je suis qu''un vieux fou de la ruelle. Le monde a toujours été le monde. Y''a pas eu d''avant. Donne un Yrd au fou et va-t''en, petit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_81_10', 'NPC_ALN_81', 'KX', '{"*(hors sujet)*"}', '« Ça, c''est de maintenant. Moi je suis surtout d''avant. J''sais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_01', 'NPC_ALN_82', 'K0', '{"musique","buffs"}', 'Ses airs et les buffs d''ambiance mineurs qu''ils posent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_02', 'NPC_ALN_82', 'K0', '{"fontaine","place"}', 'La vie de la Place, la coutume des pièces (renvoi Pinn `NPC_ALN_43`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_03', 'NPC_ALN_82', 'K0', '{"repertoire","demandes"}', 'Les airs qu''elle joue sur demande, tarifs au chapeau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_04', 'NPC_ALN_82', 'K1', '{"melodies","source"}', 'Comment elle « entend » ses airs dans l''eau de la Fontaine', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_05', 'NPC_ALN_82', 'K1', '{"nolan","ballade"}', 'La ressemblance entre son air et la ballade interdite de Nolan `NPC_ALN_49`', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_06', 'NPC_ALN_82', 'K1', '{"ambiance","effets"}', 'Comment sa musique apaise (ou agite) la foule de la Place', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_07', 'NPC_ALN_82', 'K2', '{"air","ouvre"}', 'La mélodie qui fait s''aligner les pièces et « ouvre » quelque chose', '`AFF>=85+QUEST:QST_NEU_FONTAINE_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_08', 'NPC_ALN_82', 'K2', '{"porte","grince"}', 'Ce qu''elle « entend » grincer quand elle joue cet air en entier', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_09', 'NPC_ALN_82', 'K3', '{"melodie","clef"}', 'Elle pense que cet air est une « clef » sonore — que la Fontaine (canal de la Racine/du Cardinal) transmet, et que le jouer entièrement au bon moment déverrouillerait un accès caché, peut-être vers ce que garde l''Enfant `NPC_ALN_00`', NULL, '*(elle repose son instrument, un frisson)* « C''est juste un joli air, un peu triste, rien de plus. Les pièces qui bougent ? Un courant dans l''eau. Une " clef " ? Je fais de la musique de rue, pas de la sorcellerie. Je te joue autre chose, quelque chose de léger ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_82_10', 'NPC_ALN_82', 'KX', '{"*(hors sujet)*"}', '« Ça ne se joue pas, donc je ne l''entends pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_01', 'NPC_ALN_83', 'K0', '{"portraits","service"}', 'Portraits, images de guilde, bannières — tarifs, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_02', 'NPC_ALN_83', 'K0', '{"cosmetique","usage"}', 'Comment un portrait sert de cosmétique/souvenir d''avatar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_03', 'NPC_ALN_83', 'K0', '{"styles","races"}', 'Ses styles d''après les 9 traditions raciales', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_04', 'NPC_ALN_83', 'K1', '{"ressemblance","technique"}', 'Comment iel saisit une ressemblance en quelques traits', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_05', 'NPC_ALN_83', 'K1', '{"portraits","notables"}', 'Les grands portraits qu''iel a faits (dignitaires, héros)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_06', 'NPC_ALN_83', 'K1', '{"vane","isilde"}', 'Le lien entre son art et ceux de Vane `NPC_ALN_65` / Isilde `NPC_ALN_98`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_07', 'NPC_ALN_83', 'K2', '{"portrait","futur"}', 'Que ses portraits montrent les modèles « tels qu''ils seront »', '`AFF>=85+QUEST:QST_NEU_PORTRAIT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_08', 'NPC_ALN_83', 'K2', '{"portraits","sombres"}', 'Les portraits prophétiques qu''iel cache (morts annoncées)', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_09', 'NPC_ALN_83', 'K3', '{"main","ecrit-avenir"}', 'Iel soupçonne que sa main ne « prédit » pas mais lit un avenir déjà écrit quelque part — que le Système connaît la suite de chaque joueur, et qu''iel n''est qu''un canal par lequel ce futur figé transparaît', NULL, '*(iel retourne une toile contre le mur)* « Je peins ce que je vois, avec un peu de fantaisie d''artiste, voilà tout. " L''avenir déjà écrit ", quelle angoisse. Un portrait, c''est une image, pas une prophétie. Le vôtre est prêt — le reste n''est que mon coup de pinceau. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_83_10', 'NPC_ALN_83', 'KX', '{"*(hors sujet)*"}', '« Ça ne se peint pas, donc je ne saurais le représenter. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_01', 'NPC_ALN_84', 'K0', '{"montures","location"}', 'Louer une monture aérienne, espèces, tarifs, cautions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_02', 'NPC_ALN_84', 'K0', '{"routes","montures"}', 'Quelles montures pour quelles routes (croise Halvard `NPC_ALN_10`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_03', 'NPC_ALN_84', 'K0', '{"reseau","gattan"}', 'Le réseau de montures partagé avec Stev `NPC_GAT_91` de Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_04', 'NPC_ALN_84', 'K1', '{"especes","tempeaments"}', 'Le caractère de chaque monture, laquelle pour quel cavalier', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_05', 'NPC_ALN_84', 'K1', '{"soins","dressage"}', 'Comment il soigne et dresse son cheptel (croise Fenna `NPC_ALN_71`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_06', 'NPC_ALN_84', 'K1', '{"mob-air","dangers"}', 'Les montures les plus sûres face aux essaims `MOB_AIR_*` (Corvin `NPC_ALN_16`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_07', 'NPC_ALN_84', 'K2', '{"montures","changees"}', 'Les bêtes qui reviennent « éteintes » après un survol des hauteurs', '`AFF>=85+QUEST:QST_NEU_DOME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_08', 'NPC_ALN_84', 'K2', '{"survol","dome"}', 'Quels itinéraires (près du sommet du Dôme) « changent » les montures', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_09', 'NPC_ALN_84', 'K3', '{"betes","temoins"}', 'Ses montures « changées » ont toutes survolé le sommet du Dôme ; il pense qu''elles ont vu ce qui transforme aussi les joueurs, et qu''une bête ne peut pas mentir sur ce qu''elle a vu — ce qui le terrifie plus que tous les récits d''ivrognes', NULL, '*(il flatte l''encolure d''une wyverne)* « Mes bêtes vont très bien, toutes. Un peu fatiguées après un long vol, c''est normal. " Changées par le sommet " ? Des sornettes. Une monture, ça se fatigue, ça ne se hante pas. Tu en loues une, oui ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_84_10', 'NPC_ALN_84', 'KX', '{"*(hors sujet)*"}', '« Ça ne se monte pas, donc c''est pas mes oignons. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_01', 'NPC_ALN_85', 'K0', '{"babioles","catalogue"}', 'Breloques, porte-bonheur, souvenirs des 9 races — prix dérisoires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_02', 'NPC_ALN_85', 'K0', '{"souvenirs","voyageurs"}', 'Ce que les voyageurs achètent en souvenir d''Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_03', 'NPC_ALN_85', 'K0', '{"marche","emplacement"}', 'Où la trouver, ses heures, son bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_04', 'NPC_ALN_85', 'K1', '{"breloques","symbolique"}', 'La (fausse) symbolique porte-bonheur qu''elle vend avec chaque objet', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_05', 'NPC_ALN_85', 'K1', '{"camelote","sourcing"}', 'D''où vient sa camelote (fonds de tiroir, chapardages de Pip `NPC_ALN_80`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_06', 'NPC_ALN_85', 'K1', '{"doss","fouille"}', 'Pourquoi Doss `NPC_ALN_35` fouille régulièrement son étal', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_07', 'NPC_ALN_85', 'K2', '{"objet","authentique"}', 'Qu''une seule de ses mille breloques est un objet de pouvoir réel', '`AFF>=85+QUEST:QST_NEU_BRELOQUE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_08', 'NPC_ALN_85', 'K2', '{"objet","non-identifie"}', 'Qu''elle ne sait pas lequel c''est, et le vend au prix de la pacotille', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_09', 'NPC_ALN_85', 'K3', '{"breloque","artefact"}', 'L''objet vrai est un artefact « d''avant » (reconnu par Zéro `NPC_ALN_81` / Doss `NPC_ALN_35`) qui, entre de mauvaises mains, pourrait faire des ravages — et elle le cache par instinct sans comprendre ce qu''elle protège', NULL, '*(elle mélange vivement ses babioles)* « Tout est de la camelote, mon chou ! Du toc, du joli toc pas cher ! " Un artefact " ? Si j''avais un objet de pouvoir, tu crois que je le vendrais deux Yrds ? Prends une breloque et file rêver ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_85_10', 'NPC_ALN_85', 'KX', '{"*(hors sujet)*"}', '« Ça, ça se vend pas sur mon étal, donc j''en sais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_01', 'NPC_ALN_86', 'K0', '{"colportage","stock"}', 'Ses marchandises itinérantes rares des 9 cités, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_02', 'NPC_ALN_86', 'K0', '{"routes","relais"}', 'Les routes qu''elle parcourt, les relais (Ferd `NPC_ALN_19`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_03', 'NPC_ALN_86', 'K0', '{"ferro","rivalite"}', 'Sa rivalité/trêve avec Ferro `NPC_GAT_07` de Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_04', 'NPC_ALN_86', 'K1', '{"marchandises","sourcing"}', 'Où elle déniche ses raretés dans chaque territoire', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_05', 'NPC_ALN_86', 'K1', '{"routes","dangers"}', 'Les dangers réels des routes, où camper, quoi éviter', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_06', 'NPC_ALN_86', 'K1', '{"nouvelles","inter-cites"}', 'Les nouvelles fraîches qu''elle rapporte des autres cités', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_07', 'NPC_ALN_86', 'K2', '{"route","anomalie"}', 'Ce qu''elle a vu sur les routes qui « ne devrait pas s''y trouver »', '`AFF>=85+QUEST:QST_NEU_ROUTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_08', 'NPC_ALN_86', 'K2', '{"rask","chemins"}', 'Comment Rask `NPC_ALN_57` utilise des chemins qu''elle-même évite', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_09', 'NPC_ALN_86', 'K3', '{"route","disparait"}', 'Elle est tombée deux fois sur un embranchement de route qui n''existait pas la fois d''avant et n''existait plus la fois d''après — la « région effacée » d''Alba `NPC_ALN_18` que Rask exploite ; elle a fait demi-tour et n''y retournera pour rien au monde', NULL, '*(elle resserre les sangles de sa mule)* « Les routes, je les connais toutes, et elles sont toutes bien à leur place. Un " chemin qui apparaît et disparaît " ? J''avais dû forcer sur le vin de Ferd. Y''a pas de route fantôme. Tu m''achètes quelque chose, ou je repars ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_86_10', 'NPC_ALN_86', 'KX', '{"*(hors sujet)*"}', '« Ça ne se colporte pas, donc je ne l''ai pas dans mes sacoches. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_01', 'NPC_ALN_87', 'K0', '{"lessive","service"}', 'Lavage, séchage, entretien du linge — tarifs, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_02', 'NPC_ALN_87', 'K0', '{"lavoirs","acces"}', 'Les lavoirs du Quartier Administratif, comment déposer son linge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_03', 'NPC_ALN_87', 'K0', '{"taches","base"}', 'Comment elle traite les taches courantes (utile RP/quête)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_04', 'NPC_ALN_87', 'K1', '{"linge","indices"}', 'Ce que le linge trahit de ses propriétaires (sang, fumée, boue)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_05', 'NPC_ALN_87', 'K1', '{"clients","garde-robe"}', 'Qui lui confie quoi (uniformes du Conclave, robes de prêtresse)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_06', 'NPC_ALN_87', 'K1', '{"boue","provenance"}', 'Une boue qu''elle ne reconnaît d''aucune route (croise Anse `NPC_ALN_86`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_07', 'NPC_ALN_87', 'K2', '{"cape","tache"}', 'La cape à la tache sombre qui revient toujours après lavage', '`AFF>=80+QUEST:QST_NEU_LESSIVE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_08', 'NPC_ALN_87', 'K2', '{"proprietaire","cape"}', 'À qui appartient cette cape, et pourquoi il la lui rapporte sans cesse', '`AFF>=88`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_09', 'NPC_ALN_87', 'K3', '{"tache","ineffacable"}', 'La tache est du sang versé en zone neutre — une chose « impossible » que l''anti-PK interdit ; l''étoffe garde la preuve d''un meurtre qui n''aurait pas dû pouvoir avoir lieu à Alne, et le linge « se souvient » de ce que les registres nient', NULL, '*(elle plonge la cape dans le baquet, sans lever les yeux)* « C''est une tache de vin, sûrement, ou de rouille. Ça finira par partir, tout finit par partir. " Du sang versé en ville " ? Impossible, l''anti-PK, tout le monde sait ça. Reviens chercher ton linge demain. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_87_10', 'NPC_ALN_87', 'KX', '{"*(hors sujet)*"}', '« Ça ne se lave pas, donc ça n''est pas de mon baquet. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_01', 'NPC_ALN_88', 'K0', '{"affutage","service"}', 'Affûtage de lames/outils, bonus de tranchant temporaire, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_02', 'NPC_ALN_88', 'K0', '{"entretien","lames"}', 'Comment entretenir une arme, quand la faire affûter', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_03', 'NPC_ALN_88', 'K0', '{"marche","tournee"}', 'Son circuit dans le marché, où le trouver', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_04', 'NPC_ALN_88', 'K1', '{"lames","lecture"}', 'Ce qu''il lit d''une arme à son fil (usure, qualité, forge d''origine)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_05', 'NPC_ALN_88', 'K1', '{"tranchant","bonus"}', 'Le bonus exact qu''il confère et sa durée (pré-raid)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_06', 'NPC_ALN_88', 'K1', '{"forges","reconnait"}', 'Les forges des 9 races qu''il reconnaît au tranchant (croise Roan `NPC_ALN_69`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_07', 'NPC_ALN_88', 'K2', '{"lame","a-tue"}', 'Qu''il reconnaît une lame qui a tué un être conscient', '`AFF>=85+QUEST:QST_NEU_LAME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_08', 'NPC_ALN_88', 'K2', '{"lame","recente"}', 'Une lame récente, passée sur sa meule, qui a tué EN ville (impossible ?)', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_09', 'NPC_ALN_88', 'K3', '{"meurtre","preuve"}', 'Il a affûté une lame qui a manifestement servi à tuer en zone neutre — la même preuve que la cape tachée de Sud `NPC_ALN_87` — confirmant que l''anti-PK a été contourné ; il se tait par peur d''être le prochain à passer sous une lame', NULL, '*(il fait tourner sa meule, gerbe d''étincelles)* « Une lame, c''est une lame. Ce qu''elle a coupé, du bois, de la chair de monstre, ça se voit pas au fil. " Tué en ville " ? L''anti-PK empêche ça, voyons. J''affûte, je juge pas. Ta lame est prête. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_88_10', 'NPC_ALN_88', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas de fil, donc ça ne passe pas sur ma pierre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_01', 'NPC_ALN_89', 'K0', '{"gazette","nouvelles"}', 'Les nouvelles publiées d''Alne (événements, marché, faits divers)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_02', 'NPC_ALN_89', 'K0', '{"abonnement","achat"}', 'Comment lire/acheter la Gazette, publier une annonce', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
