INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_04', 'NPC_ALN_89', 'K1', '{"articles","coulisses"}', 'Les dessous d''un article, ce qui a été coupé et pourquoi', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_05', 'NPC_ALN_89', 'K1', '{"reputation","presse"}', 'Comment un article fait ou défait une réputation (Cassia `NPC_ALN_25`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_06', 'NPC_ALN_89', 'K1', '{"rumeurs","verifiees"}', 'La différence entre ce qu''il publie et ce qu''il sait', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_07', 'NPC_ALN_89', 'K2', '{"silence","achete"}', 'Le commerce du silence : les articles enterrés contre paiement', '`AFF>=85+PAY:500`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_08', 'NPC_ALN_89', 'K2', '{"tiroir","non-publies"}', 'Le tiroir des articles jamais publiés — la chronique cachée d''Alne', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_09', 'NPC_ALN_89', 'K3', '{"article","neutralite"}', 'Il détient un article prouvant que la neutralité d''Alne est truquée (meurtres en ville, cellule armée, financement) — un scoop qui ferait s''effondrer la confiance dans l''anti-PK — qu''il n''ose ni publier (on le tuerait) ni monnayer (à qui ?)', NULL, '*(il referme son tiroir à clé)* « La Gazette publie la vérité, toute la vérité vendable. Un " article qui ferait tomber la neutralité " ? Si je l''avais, je serais riche ou mort. Je suis ni l''un ni l''autre, donc je ne l''ai pas. Tu veux passer une annonce ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_89_10', 'NPC_ALN_89', 'KX', '{"*(hors sujet)*"}', '« Ça n''a pas d''intérêt pour mes lecteurs, donc ça ne s''imprime pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_01', 'NPC_ALN_90', 'K0', '{"refuge","racines"}', 'Le Réfuge des Racines, comment les exilés y survivent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_02', 'NPC_ALN_90', 'K0', '{"gattan","deserteur"}', 'Qu''il est un déserteur Salamander (sans détailler pourquoi)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_03', 'NPC_ALN_90', 'K0', '{"travail","journalier"}', 'Où trouver du travail de journalier à Alne (Grumman `NPC_ALN_37`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_04', 'NPC_ALN_90', 'K1', '{"armee","gattan"}', 'Ce qu''il sait de l''organisation militaire de Gattan (utile côté joueur)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_05', 'NPC_ALN_90', 'K1', '{"frontieres","plaines"}', 'Les Plaines de Cendres et la Désolation vues d''un soldat', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_06', 'NPC_ALN_90', 'K1', '{"refugies","reseau"}', 'Le réseau d''exilés d''Alne (Aeliss 91, Nerio 92, Bomil 93)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_07', 'NPC_ALN_90', 'K2', '{"invasion","fabriquee"}', 'Que certaines « invasions » repoussées par Gattan sont mises en scène', '`AFF>=85+QUEST:QST_NEU_INVASION_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_08', 'NPC_ALN_90', 'K2', '{"ordres","flint"}', 'Ce que Flint `NPC_GAT_75` sait (ou non) de la fabrication des invasions', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_09', 'NPC_ALN_90', 'K3', '{"guerre","orchestree"}', 'Il soupçonne que la guerre perpétuelle entre territoires est entretenue *volontairement* d''en haut — par le Système ou par ceux qui veulent briser la neutralité d''Alne, seule à échapper au conflit — et que sa désertion l''a mis sur une liste', NULL, '*(il jette un œil par-dessus son épaule)* « J''ai déserté par lâcheté, c''est tout. Pas de complot, pas d''" invasions fabriquées ". Un soldat qui accuse ses chefs de mentir finit au bout d''une corde. Alors je n''accuse personne. Laisse-moi travailler en paix. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_90_10', 'NPC_ALN_90', 'KX', '{"*(hors sujet)*"}', '« Ça, c''est pas de mon monde de soldat. J''en sais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_01', 'NPC_ALN_91', 'K0', '{"refuge","soins"}', 'Ses soins de fortune au Réfuge, ce qu''elle peut traiter', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_02', 'NPC_ALN_91', 'K0', '{"swilvane","exilee"}', 'Qu''elle vient de Swilvane, capitale Sylph (sans dire pourquoi elle est bannie)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_03', 'NPC_ALN_91', 'K0', '{"refugies","entraide"}', 'L''entraide entre exilés des Racines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_04', 'NPC_ALN_91', 'K1', '{"swilvane","culture"}', 'Ce qu''elle sait de Swilvane (utile avant le lot Swilvane / voyage)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_05', 'NPC_ALN_91', 'K1', '{"soins","herbes"}', 'Ses remèdes de fortune (croise Yssa `NPC_ALN_15`, Osmé `NPC_ALN_40`)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_06', 'NPC_ALN_91', 'K1', '{"sylphes","politique"}', 'Les tensions politiques de la cour Sylph (bribes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_07', 'NPC_ALN_91', 'K2', '{"bannissement","raison"}', 'La vraie raison de son bannissement de Swilvane', '`AFF>=85+QUEST:QST_NEU_EXIL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_08', 'NPC_ALN_91', 'K2', '{"helka","swilvane"}', 'Ce qu''elle sait de la fuite d''Helka `NPC_GAT_54` vers Swilvane *(lien réservé, lot Swilvane)*', '`AFF>=90+QUEST:QST_SYL_HELKA_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_09', 'NPC_ALN_91', 'K3', '{"secret","deux-cites"}', 'Son secret relie Swilvane et Gattan par une affaire que les deux capitales étouffent ; le révéler embraserait une nouvelle querelle inter-raciale — exactement le genre de conflit que la cellule anti-neutralité cherche à provoquer', NULL, '*(elle serre son châle usé)* « Ce que je sais, je l''emporterai dans ma tombe d''exilée. Ça vaut mieux pour tout le monde — pour Swilvane, pour Gattan, pour toi. Certaines vérités ne font que du mal. Laisse-moi soigner ceux qui souffrent déjà assez. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_91_10', 'NPC_ALN_91', 'KX', '{"*(hors sujet)*"}', '« Ça ne se soigne pas, alors ce n''est pas mon affaire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_92_01', 'NPC_ALN_92', 'K0', '{"archipel","emigre"}', 'Qu''il vient de l''Archipel d''Écume (terre Undine)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_92_02', 'NPC_ALN_92', 'K0', '{"fontaine","undine"}', 'Pourquoi il vit près de la Fontaine (l''eau, la mer perdue)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_ALN_92_03', 'NPC_ALN_92', 'K0', '{"refugies","communaute"}', 'La petite communauté Undine expatriée d''Alne', '—', NULL);
