INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_04', 'NPC_DUS_12', 'K1', '{"champignon","pulse"}', 'Le champignon qui pulse dans le noir — il le garde « pour les amateurs »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_05', 'NPC_DUS_12', 'K1', '{"lueur","violet"}', 'Sa lueur violine — elle suit un rythme, pas aléatoire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_06', 'NPC_DUS_12', 'K1', '{"marche","canyon"}', 'Ce qu''il voit au canyon — des ombres qui nettoient les parois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_07', 'NPC_DUS_12', 'K2', '{"champignon","etrange"}', 'Le champignon pulse à l''unisson de la Rivière d''Encre, tout en bas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_08', 'NPC_DUS_12', 'K2', '{"cristal","lien"}', 'Sa pulsation est synchronisée avec les veines de cristal violet de la ville', '`QUEST:QST_IMP_LAME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_09', 'NPC_DUS_12', 'K3', '{"champignon","cardinal"}', 'Le champignon est imprégné par le nœud de régulation des ténèbres — il pulse au rythme du cœur d''ombre du serveur, un capteur vivant piloté par le Cardinal', NULL, '*(il range le champignon)* « Un champignon qui bat ? Rien qu''la roche qui respire. Si tu veux des cœurs, va au Temple. Moi j''vends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_12_10', 'NPC_DUS_12', 'KX', '{"*(hors sujet)*"}', '*(il essuie un cèpe)* « Un marchand ne répond qu''aux bourses. Là, j''vends. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_01', 'NPC_DUS_13', 'K0', '{"falaises","chasse"}', 'Les Falaises du Crépuscule — zone `HUNT_002`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_02', 'NPC_DUS_13', 'K0', '{"frontiere","spriggan"}', 'La frontière Spriggan — postes, accès, tension', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_03', 'NPC_DUS_13', 'K0', '{"patrouille","securite"}', 'Sa patrouille — protège les chasseurs des mobs frontière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_04', 'NPC_DUS_13', 'K1', '{"accord","trafique"}', 'L''accord trafiqué dans le noir — signé à la lueur violette, hors Balcon', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_05', 'NPC_DUS_13', 'K1', '{"spriggan","rencontres"}', 'Qui rencontre les Spriggan la nuit — des ombres du Balcon', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_06', 'NPC_DUS_13', 'K1', '{"rumours","falaises"}', 'Rumeurs des falaises — des cris qui ne viennent pas d''oiseaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_07', 'NPC_DUS_13', 'K2', '{"accord","etrange"}', 'L''accord porte un sceau d''ombre que le Chancelier n''a jamais vu', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_08', 'NPC_DUS_13', 'K2', '{"pacte","ailes"}', 'L''accord clandestin nourrit le Pacte des Ailes — un trafic toléré par le Conseil', '`QUEST:QST_IMP_PACTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_09', 'NPC_DUS_13', 'K3', '{"pacte","cardinal"}', 'Le trafic frontière alimente le Pacte des Ailes, lui-même utile au nœud de régulation des ténèbres pour capter le renseignement — un canal piloté par le Cardinal pour stabiliser le pôle d''ombre', NULL, '*(il serre sa hallebarde)* « Un accord dans l''noir ? Rien qu''des marchands qui s''entendent. Si tu veux des traités, va au Balcon. Moi j''veille. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_13_10', 'NPC_DUS_13', 'KX', '{"*(hors sujet)*"}', '*(il scrute l''horizon)* « Un gardien ne répond qu''aux mouvements. Là, j''patrouille. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_01', 'NPC_DUS_14', 'K0', '{"piste","failles"}', 'Ses pistes des failles — où les lézards passent, où la roche cède', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_02', 'NPC_DUS_14', 'K0', '{"lezards","chasse"}', 'Les lézards des falaises — comportements, drops', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
