INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_04', 'NPC_DUS_14', 'K1', '{"empreinte","fuit"}', 'L''empreinte qui fuit — elle recule au lieu d''avancer', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_05', 'NPC_DUS_14', 'K1', '{"failles","reparation"}', 'Les failles qu''il referme — certaines « se referment » avant lui', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_06', 'NPC_DUS_14', 'K1', '{"clients","piste"}', 'Qui engage ses services — et ce qu''ils cherchent vraiment', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_07', 'NPC_DUS_14', 'K2', '{"empreinte","etrange"}', 'L''empreinte suit le tracé des veines de cristal — comme si l''ombre « tissait » la paroi', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_08', 'NPC_DUS_14', 'K2', '{"riviere","lien"}', 'La trace remonte à la Rivière d''Encre — l''ombre qui répare viendrait d''en bas', '`QUEST:QST_IMP_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_09', 'NPC_DUS_14', 'K3', '{"failles","cardinal"}', 'Les empreintes qui fuient sont les rejets du nœud de régulation des ténèbres — ils comblent les failles pour maintenir le pôle d''ombre du serveur, pilotés par le Cardinal', NULL, '*(il efface une trace du doigt)* « Une empreinte qui fuit ? Rien qu''le vent dans la roche. Si tu veux des failles, va au canyon. Moi j''traque. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_14_10', 'NPC_DUS_14', 'KX', '{"*(hors sujet)*"}', '*(il suit une piste du regard)* « Un pisteur ne répond qu''aux traces. Là, j''traque. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_01', 'NPC_DUS_15', 'K0', '{"cristaux","prix"}', 'Ses cristaux violets — qualité, prix, usage déco', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_02', 'NPC_DUS_15', 'K0', '{"veines","ville"}', 'Les veines de cristal qui éclairent Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_03', 'NPC_DUS_15', 'K0', '{"clientele","marche"}', 'Sa clientèle — artisans, enchanteurs, curieux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_04', 'NPC_DUS_15', 'K1', '{"cristal","bat"}', 'Le cristal qui bat — il le garde « pour les amateurs de pouls »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_05', 'NPC_DUS_15', 'K1', '{"lueur","rythme"}', 'Sa lueur violine suit un rythme, pas aléatoire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_06', 'NPC_DUS_15', 'K1', '{"marche","falaises"}', 'Ce qu''il voit aux falaises — des ombres qui tissent la paroi', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_07', 'NPC_DUS_15', 'K2', '{"cristal","etrange"}', 'Le cristal bat à l''unisson de la Rivière d''Encre, tout en bas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_08', 'NPC_DUS_15', 'K2', '{"ville","synchronisation"}', 'Toute la ville pulse au même rythme que son cristal', '`QUEST:QST_IMP_LAME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_09', 'NPC_DUS_15', 'K3', '{"cristal","cardinal"}', 'Le cristal est le capteur du nœud de régulation des ténèbres — il bat au rythme du cœur d''ombre du serveur, la mesure vive pilotée par le Cardinal', NULL, '*(il emballe le cristal)* « Un cristal qui bat ? Rien qu''la roche qui respire. Si tu veux des cœurs, va au Temple. Moi j''vends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_15_10', 'NPC_DUS_15', 'KX', '{"*(hors sujet)*"}', '*(il polît une facette)* « Un marchand ne répond qu''aux bourses. Là, j''vends. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_01', 'NPC_DUS_16', 'K0', '{"caverne","donjon"}', 'La Caverne des Hurleurs — donjon `DUN_001`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_02', 'NPC_DUS_16', 'K0', '{"registre","raids"}', 'Son registre des raids — qui entre, qui sort', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_03', 'NPC_DUS_16', 'K0', '{"consignes","entree"}', 'Ses consignes — interdiction d''entrer sans torche', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_04', 'NPC_DUS_16', 'K1', '{"groupe","torche"}', 'Le groupe entré sans torche — jamais ressorti, aucune issue', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_05', 'NPC_DUS_16', 'K1', '{"hurlements","caverne"}', 'Les hurlements — ils ne viennent d''aucune bête du bestiaire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_06', 'NPC_DUS_16', 'K1', '{"rumeurs","donjon"}', 'Rumeurs du donjon — des ombres qui marchent au fond', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_07', 'NPC_DUS_16', 'K2', '{"groupe","etrange"}', 'Le groupe n''a laissé ni arme ni os — comme dissous dans l''ombre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_08', 'NPC_DUS_16', 'K2', '{"riviere","lien"}', 'Les hurlements montent à l''unisson de la Rivière d''Encre — la caverne en serait le puits', '`QUEST:QST_IMP_HURLEURS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_09', 'NPC_DUS_16', 'K3', '{"caverne","cardinal"}', 'La caverne est un puits de régulation du nœud de ténèbres — elle hurle pour évacuer l''excès d''obscurité du serveur, et dissolve qui entre sans lumière, pilotée par le Cardinal', NULL, '*(il verrouille la grille)* « Une caverne qui hurle ? Rien qu''le vent dans la roche. Si tu veux des morts, va au Mémorial. Moi j''protège l''entrée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_16_10', 'NPC_DUS_16', 'KX', '{"*(hors sujet)*"}', '*(il complète son registre)* « Un gardien ne répond qu''aux entrées. Là, j''veille. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_01', 'NPC_DUS_17', 'K0', '{"cartes","caverne"}', 'Ses plans de la Caverne des Hurleurs — niveaux, issues', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_02', 'NPC_DUS_17', 'K0', '{"relevés","profondeur"}', 'Ses relevés — où les raids peuvent passer', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_03', 'NPC_DUS_17', 'K0', '{"service","cartes"}', 'Il vend/prête ses cartes aux explorateurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_04', 'NPC_DUS_17', 'K1', '{"salle","silencieuse"}', 'La salle « silencieuse » — aucun instrument n''y capte quoi que ce soit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_05', 'NPC_DUS_17', 'K1', '{"instruments","vides"}', 'Ses sondes y reviennent vierges — comme si la salle effaçait la mesure', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_06', 'NPC_DUS_17', 'K1', '{"rumeurs","caverne"}', 'Rumeurs du donjon — la salle que personne ne décrit pareil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_07', 'NPC_DUS_17', 'K2', '{"salle","etrange"}', 'La salle « silencieuse » suit le tracé de la Rivière d''Encre — elle en serait la chambre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_08', 'NPC_DUS_17', 'K2', '{"riviere","coeur"}', 'La salle serait le cœur de la rivière — l''endroit où l''ombre est parfaite', '`QUEST:QST_IMP_HURLEURS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_09', 'NPC_DUS_17', 'K3', '{"salle","cardinal"}', 'La salle « silencieuse » est le cœur de régulation du nœud de ténèbres — l''ombre y est si dense qu''elle ne renvoie rien, le moteur du pôle d''ombre du serveur piloté par le Cardinal', NULL, '*(il referme le plan)* « Une salle qui ne fait pas de bruit ? Rien qu''une grotte vide. Si tu veux des cœurs, va au Temple. Moi j''dessine. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_17_10', 'NPC_DUS_17', 'KX', '{"*(hors sujet)*"}', '*(il taille une plume)* « Un cartographe ne répond qu''aux murs. Là, je dessine. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_01', 'NPC_DUS_18', 'K0', '{"route","aerienne"}', 'La Route Aérienne Duskarn–Alne — trafic, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_02', 'NPC_DUS_18', 'K0', '{"controle","vols"}', 'Son comptage des vols — qui entre, qui sort', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_03', 'NPC_DUS_18', 'K0', '{"consignes","route"}', 'Ses consignes — escales, interdictions de vol', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_04', 'NPC_DUS_18', 'K1', '{"passagers","ombre"}', 'Les passagers sans ombre — aucune projection, même aux cristaux', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_05', 'NPC_DUS_18', 'K1', '{"registres","vides"}', 'Ses registres — des vols qui ne figurent nulle part ailleurs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_06', 'NPC_DUS_18', 'K1', '{"rumeurs","route"}', 'Rumeurs de la route — des vols fantômes vers Alne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_07', 'NPC_DUS_18', 'K2', '{"passagers","etrange"}', 'Les passagers sans ombre montent à la Rivière d''Encre avant de partir', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_08', 'NPC_DUS_18', 'K2', '{"alne","lien"}', 'Les vols sans ombre vont toujours à Alne — un trafic qui lie les deux capitales', '`QUEST:QST_IMP_ROUTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_09', 'NPC_DUS_18', 'K3', '{"route","cardinal"}', 'Les passagers sans ombre sont des paquets de régulation du nœud de ténèbres — ils circulent entre Duskarn et Alne pour équilibrer les ténèbres du serveur, pilotés par le Cardinal', NULL, '*(il raye une ligne)* « Des passagers sans ombre ? Rien qu''des voyageurs pressés. Si tu veux des fantômes, va aux Hurleurs. Moi j''compte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_18_10', 'NPC_DUS_18', 'KX', '{"*(hors sujet)*"}', '*(il pointe le ciel)* « Une vigie ne répond qu''aux vols. Là, je compte. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_01', 'NPC_DUS_19', 'K0', '{"vol","potions"}', 'Ses potions de vol — durée, coût, buffs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_02', 'NPC_DUS_19', 'K0', '{"buffs","deplacement"}', 'Ses buffs de déplacement — vitesse, furtivité aérienne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
