INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_05', 'NPC_DUS_19', 'K1', '{"route","nuit"}', 'Ce qu''il voit la nuit — des formes sans monture', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_06', 'NPC_DUS_19', 'K1', '{"rumeurs","ile"}', 'Rumeurs de l''Îlot — des vols qui ne déclarent pas d''escale', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_07', 'NPC_DUS_19', 'K2', '{"ombres","etrange"}', 'Les ombres suivent le tracé de la Rivière d''Encre, en contrebas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_08', 'NPC_DUS_19', 'K2', '{"riviere","lien"}', 'Les ombres volantes montent de la rivière — elles en seraient les patrouilles', '`QUEST:QST_IMP_ROUTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_09', 'NPC_DUS_19', 'K3', '{"ombres","cardinal"}', 'Les ombres qui volent sont des rejets du nœud de régulation des ténèbres — elles patrouillent l''air pour maintenir le pôle d''ombre du serveur, pilotées par le Cardinal', NULL, '*(il range une fiole)* « Des ombres qui volent ? Rien qu''le vent qui joue. Si tu veux des ailes, j''ai ça. Sinon, va aux Hurleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_19_10', 'NPC_DUS_19', 'KX', '{"*(hors sujet)*"}', '*(il agite une fiole)* « Un marchand ne répond qu''aux bourses. Là, je vends. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_01', 'NPC_DUS_20', 'K0', '{"temple","entretien"}', 'Son entretien du Temple du Voile — salles, rites de nettoyage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_02', 'NPC_DUS_20', 'K0', '{"horaires","temple"}', 'Les horaires du Temple — ouvertures, fermetures de voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_03', 'NPC_DUS_20', 'K0', '{"service","concierge"}', 'Ce qu''il propose — accès, coffres, ravitaillement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_04', 'NPC_DUS_20', 'K1', '{"ombre","reste"}', 'L''ombre qui reste après son passage — elle ne part pas au balai', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_05', 'NPC_DUS_20', 'K1', '{"temple","etrange"}', 'D''autres lieux où l''ombre « attend » — le Balcon, la Rivière', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_06', 'NPC_DUS_20', 'K1', '{"rumeurs","temple"}', 'Rumeurs du Temple — des rites qui s''achèvent seuls', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_07', 'NPC_DUS_20', 'K2', '{"ombre","etrange"}', 'L''ombre suit le tracé du Voile et de la Rivière d''Encre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_08', 'NPC_DUS_20', 'K2', '{"voile","lien"}', 'L''ombre stationne au Temple pour surveiller le Voile — elle en serait le guetteur', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_09', 'NPC_DUS_20', 'K3', '{"ombre","cardinal"}', 'L''ombre qui reste est un résidu de régulation du nœud de ténèbres — elle stationne au Temple pour surveiller le Voile, membrane du pôle d''ombre du serveur pilotée par le Cardinal', NULL, '*(il repose son balai)* « Une ombre qui reste ? Rien qu''la poussière d''encre. Si tu veux des spectres, va aux Hurleurs. Moi j''nettoie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_20_10', 'NPC_DUS_20', 'KX', '{"*(hors sujet)*"}', '*(il époussette un pilier)* « Un concierge ne répond qu''aux taches. Là, je nettoie. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_01', 'NPC_DUS_21', 'K0', '{"apprentissage","ombre"}', 'Son apprentissage — cours de voile, d''illusion', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_02', 'NPC_DUS_21', 'K0', '{"sorts","base"}', 'Les sorts qu''il apprend — voile mineur, pas d''ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_03', 'NPC_DUS_21', 'K0', '{"ecole","temple"}', 'La vie à l''école du Temple — règles, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_04', 'NPC_DUS_21', 'K1', '{"sort","echappe"}', 'Le sort qui lui échappe — une ombre autonome qui observe', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_05', 'NPC_DUS_21', 'K1', '{"maitre","ecole"}', 'Ce que Lilith lui dit — « certains sorts s''apprennent seuls »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_06', 'NPC_DUS_21', 'K1', '{"rumeurs","temple"}', 'Rumeurs de l''école — des élèves qui « voyaient » à travers le Voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_07', 'NPC_DUS_21', 'K2', '{"sort","etrange"}', 'Le sort suit le battement de la Rivière d''Encre — comme s''il était réglé d''en bas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_08', 'NPC_DUS_21', 'K2', '{"voile","lien"}', 'Le sort « teste » le Voile — il en serait le calibreur vivant', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_09', 'NPC_DUS_21', 'K3', '{"sort","cardinal"}', 'Le sort qui lui échappe est le nœud de régulation des ténèbres qui teste son apprentissage — un calibrage du pôle d''ombre du serveur piloté par le Cardinal', NULL, '*(l''ombre se dissout)* « Mon sort qui s''en va ? Rien qu''une bourde d''apprenti. Si tu veux des prodiges, va au Maître. Moi j''apprends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_21_10', 'NPC_DUS_21', 'KX', '{"*(hors sujet)*"}', '*(il recommence un geste)* « Un apprenti ne répond qu''aux sorts. Là, j''apprends. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_01', 'NPC_DUS_22', 'K0', '{"illusions","enseignement"}', 'Son enseignement — illusions de voile, fausses ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_02', 'NPC_DUS_22', 'K0', '{"skills","ombre"}', 'Les skills qu''il transmet — `!learn_illusion`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
