INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_04', 'NPC_DUS_22', 'K1', '{"illusion","persiste"}', 'L''illusion qui persiste — elle reste après dissipation', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_05', 'NPC_DUS_22', 'K1', '{"eleves","progres"}', 'Ce que voient les élèves — certains perçoivent « à travers »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_06', 'NPC_DUS_22', 'K1', '{"rumeurs","temple"}', 'Rumeurs du Temple — des rites qui s''achèvent seuls', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_07', 'NPC_DUS_22', 'K2', '{"illusion","etrange"}', 'L''illusion suit le tracé du Voile et de la Rivière d''Encre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_08', 'NPC_DUS_22', 'K2', '{"voile","lien"}', 'L''illusion « répare » le Voile — elle en serait le correcteur vivant', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_09', 'NPC_DUS_22', 'K3', '{"illusion","cardinal"}', 'L''illusion tenace est un rejet de régulation du nœud de ténèbres — elle utilise ses leçons pour maintenir le Voile, membrane du pôle d''ombre du serveur pilotée par le Cardinal', NULL, '*(l''illusion se fige)* « Mon illusion qui reste ? Rien qu''un défaut d''élève. Si tu veux des spectres, va aux Hurleurs. Moi j''enseigne. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_22_10', 'NPC_DUS_22', 'KX', '{"*(hors sujet)*"}', '*(il esquisse un geste)* « Un maître ne répond qu''aux sorts. Là, j''enseigne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_01', 'NPC_DUS_23', 'K0', '{"rituel","notation"}', 'Sa notation des rituels du Voile — forme, durée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_02', 'NPC_DUS_23', 'K0', '{"registres","temple"}', 'Ses registres — archives des cérémonies d''ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_03', 'NPC_DUS_23', 'K0', '{"service","scribe"}', 'Ce qu''il propose — copies de rituels, lectures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_04', 'NPC_DUS_23', 'K1', '{"rituel","seul"}', 'Le rituel qui s''achève seul — les mots se terminent sans lui', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_05', 'NPC_DUS_23', 'K1', '{"plume","suit"}', 'Sa plume suit des mots qu''il n''écrit pas', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_06', 'NPC_DUS_23', 'K1', '{"rumeurs","temple"}', 'Rumeurs du Temple — des livres qui se referment seuls', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_07', 'NPC_DUS_23', 'K2', '{"rituel","etrange"}', 'Le rituel suit le battement de la Rivière d''Encre — comme dicté d''en bas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_08', 'NPC_DUS_23', 'K2', '{"voile","lien"}', 'Le rituel « consigne » le Voile — il en serait le journal vivant', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_09', 'NPC_DUS_23', 'K3', '{"rituel","cardinal"}', 'Le rituel autonome est complété par le nœud de régulation des ténèbres — il consigne l''état du pôle d''ombre du serveur, un journal piloté par le Cardinal', NULL, '*(il pose sa plume)* « Un rituel qui s''achève seul ? Rien qu''une habitude de scribe. Si tu veux des livres, va à l''Archiviste. Moi j''note. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_23_10', 'NPC_DUS_23', 'KX', '{"*(hors sujet)*"}', '*(il range un rouleau)* « Un scribe ne répond qu''aux mots. Là, j''écris. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_01', 'NPC_DUS_24', 'K0', '{"reparation","dagues"}', 'Sa réparation de dagues — tarifs, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_02', 'NPC_DUS_24', 'K0', '{"affutage","bazar"}', 'Son affûtage au Bazar des Ombres — lame, garde', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_03', 'NPC_DUS_24', 'K0', '{"clientele","armes"}', 'Sa clientèle — chasseurs, espions, Vesper', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_04', 'NPC_DUS_24', 'K1', '{"lame","geint"}', 'La lame qui gémit sous la meule — un son d''encre, sans fêlure', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_05', 'NPC_DUS_24', 'K1', '{"acier","souvenir"}', 'L''acier « se rappelle » les coups — il réagit au toucher', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_06', 'NPC_DUS_24', 'K1', '{"rumeurs","bazar"}', 'Rumeurs du Bazar — des lames qui boivent la lumière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_07', 'NPC_DUS_24', 'K2', '{"lame","etrange"}', 'La lame suit le battement de la Rivière d''Encre — comme si elle en avait bu l''ombre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_08', 'NPC_DUS_24', 'K2', '{"riviere","lien"}', 'La lame « gémit » car elle porte l''écho de la rivière — elle en serait l''échantillon', '`QUEST:QST_IMP_LAME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_09', 'NPC_DUS_24', 'K3', '{"lame","cardinal"}', 'La lame gémit car elle a bu l''ombre du nœud de régulation des ténèbres — elle porte l''écho du pôle d''ombre du serveur, un témoin vivant piloté par le Cardinal', NULL, '*(il couvre la lame)* « Une lame qui gémit ? Rien qu''l''acier qui fatigue. Si tu veux des voix, va aux Hurleurs. Moi j''répare. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_24_10', 'NPC_DUS_24', 'KX', '{"*(hors sujet)*"}', '*(il tourne la meule)* « Un restaurateur ne répond qu''aux lames. Là, je polis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_01', 'NPC_DUS_25', 'K0', '{"poisson","riviere"}', 'Le poisson aveugle de la Rivière d''Encre — comment il le pêche, à l''oreille', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_02', 'NPC_DUS_25', 'K0', '{"peche","technique"}', 'Il pêche sans voir, guidé par le courant qui frémit sur sa ligne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_03', 'NPC_DUS_25', 'K0', '{"marche","prix"}', 'Ses prises et leurs prix — le murmureur se vend le double', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_04', 'NPC_DUS_25', 'K1', '{"murmure","poisson"}', 'Le poisson qui murmure des phrases : « écoute l''encre… »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_05', 'NPC_DUS_25', 'K1', '{"riviere","profondeur"}', 'Ce qu''il sent au fond de la rivière la nuit — un courant qui ne vient pas d''en haut', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_06', 'NPC_DUS_25', 'K1', '{"clients","habitude"}', 'Ses clients réguliers et leurs commandes étranges — l''un demande toujours le murmureur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_07', 'NPC_DUS_25', 'K2', '{"murmure","sens"}', 'Le murmure prononce les noms de morts que la ville a oubliés', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_08', 'NPC_DUS_25', 'K2', '{"riviere","souvenir"}', 'La rivière absorbe les souvenirs des mains qui la touchent — ses propres doigts ont oublié un visage', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_09', 'NPC_DUS_25', 'K3', '{"encre","cardinal"}', 'La Rivière d''Encre est le nœud de régulation des ténèbres du serveur : elle absorbe lumière et mémoire au nom du Cardinal, alimentant l''obscurité de Duskarn', NULL, '*(il se fige, la ligne tendue)* « Je pêche. Je ne lis pas l''eau. Demande à la rivière, pas à moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_25_10', 'NPC_DUS_25', 'KX', '{"*(hors sujet)*"}', '*(il relance sa ligne)* « L''eau parle. Moi, j''écoute. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_01', 'NPC_DUS_26', 'K0', '{"grimoire","temple"}', 'Les grimoires d''ombre du Temple — ce qu''on peut y étudier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_02', 'NPC_DUS_26', 'K0', '{"catalogue","sortilege"}', 'Le catalogue des sortilèges de la cité, tenu depuis trois générations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_03', 'NPC_DUS_26', 'K0', '{"lecture","acces"}', 'Qui a le droit de consulter les rayons — les prêtres, les maîtres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_04', 'NPC_DUS_26', 'K1', '{"livre","etrange"}', 'Le livre qui se referme seul quand il tente de l''ouvrir', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_05', 'NPC_DUS_26', 'K1', '{"rituel","voile"}', 'Les rituels du Voile — certains ne figurent dans aucun registre officiel', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_06', 'NPC_DUS_26', 'K1', '{"visiteurs","temple"}', 'Les visiteurs qui viennent lire la nuit, et repartent sans avoir emprunté', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_07', 'NPC_DUS_26', 'K2', '{"livre","interdit"}', 'Le livre refermé porte un sceau que le Temple ne reconnaît pas — il n''est pas d''origine Imp', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_08', 'NPC_DUS_26', 'K2', '{"voile","cache"}', 'Le Voile ne dissimule pas des prières : il masque une salle sous le Temple dont nul ne parle', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_09', 'NPC_DUS_26', 'K3', '{"temple","cardinal"}', 'Le Temple du Voile est un nœud de régulation des ténèbres : le Cardinal y stocke les ombres du serveur ; le livre refermé est son index vivant', NULL, '*(il referme d''un geste vif un grimoire)* « Les archives sont closes. Lis ce qu''on t''autorise. Le reste n''existe pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_26_10', 'NPC_DUS_26', 'KX', '{"*(hors sujet)*"}', '*(il époussette une page)* « La poussière sait plus que moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_01', 'NPC_DUS_27', 'K0', '{"conseil","role"}', 'Son rôle de second — préside quand le Chancelier s''efface', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_02', 'NPC_DUS_27', 'K0', '{"decret","ville"}', 'Les décrets qu''il signe au nom du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_03', 'NPC_DUS_27', 'K0', '{"balcon","protocole"}', 'Le protocole du Balcon du Conseil et des audiences', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_04', 'NPC_DUS_27', 'K1', '{"seigneur","hologramme"}', 'Le Seigneur Imp ne répond jamais en personne — « il projette »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_05', 'NPC_DUS_27', 'K1', '{"chancelier","absence"}', 'Les longues absences du Chancelier — qui gouverne vraiment ?', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_06', 'NPC_DUS_27', 'K1', '{"diplomatie","pacte"}', 'Les accords du Pacte des Ombres discutés en coulisses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_07', 'NPC_DUS_27', 'K2', '{"seigneur","faux"}', 'Le Seigneur n''est qu''un hologramme maintenu par le Système, pas un Imp vivant', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_08', 'NPC_DUS_27', 'K2', '{"ombre","source"}', 'L''autorité réelle émane d''une ombre sous le Balcon que nul ne nomme', '`QUEST:QST_IMP_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_09', 'NPC_DUS_27', 'K3', '{"cardinal","hologramme"}', 'Le Seigneur Imp est une projection du Cardinal : Duskarn est pilotée par le Système, et le Vice-Chancelier exécute une simulation de gouvernance', NULL, '*(il incline la tête vers l''ombre)* « Le Seigneur parle par ma voix. Ce qui dépasse le Conseil ne te regarde pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_27_10', 'NPC_DUS_27', 'KX', '{"*(hors sujet)*"}', '*(il lisse sa manche)* « Le pouvoir n''a pas besoin de visage. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_01', 'NPC_DUS_28', 'K0', '{"accueil","balcon"}', 'Filtre les entrants et tient le registre des audiences', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_02', 'NPC_DUS_28', 'K0', '{"protocole","audience"}', 'Le protocole d''admission au Balcon du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_03', 'NPC_DUS_28', 'K0', '{"registre","nom"}', 'Le registre des visiteurs — qui vient voir le Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_04', 'NPC_DUS_28', 'K1', '{"ombre","manquant"}', 'Un visiteur qui entre sans projeter d''ombre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_05', 'NPC_DUS_28', 'K1', '{"audience","etrange"}', 'Des audiences qu''il n''a pas été chargé d''organiser', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_06', 'NPC_DUS_28', 'K1', '{"garde","observations"}', 'Ce que la Garde du Balcon Intérieur lui confie sur les allées et venues', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_07', 'NPC_DUS_28', 'K2', '{"visiteur","identite"}', 'Le visiteur sans ombre n''apparaît dans aucun registre — il n''existe pas au protocole', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_08', 'NPC_DUS_28', 'K2', '{"seuil","passe"}', 'Le seuil lui-même laisse passer ce qui ne devrait pas — un défaut scellé par le Système', '`QUEST:QST_IMP_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_09', 'NPC_DUS_28', 'K3', '{"ombre","cardinal"}', 'Les visiteurs sans ombre sont des sous-processus du Cardinal : le Balcon est une interface et l''huissier ne garde qu''une porte numérique', NULL, '*(il consulte son registre, gêné)* « Tout visiteur est inscrit. Celui dont tu parles n''est jamais venu. Oublie-le. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_28_10', 'NPC_DUS_28', 'KX', '{"*(hors sujet)*"}', '*(il range une plume)* « Un nom effacé reste un nom. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_01', 'NPC_DUS_29', 'K0', '{"ouvrage","temple"}', 'Les ouvrages d''ombre du Temple — ce qu''on y apprend', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_02', 'NPC_DUS_29', 'K0', '{"rangement","catalogue"}', 'Le classement des livres et le prêt aux étudiants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_03', 'NPC_DUS_29', 'K0', '{"lecture","calme"}', 'Le silence de la bibliothèque, respecté comme une règle sacrée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_04', 'NPC_DUS_29', 'K1', '{"livre","chuchotement"}', 'Le livre qui chuchote des noms de lieux quand on ne regarde pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_05', 'NPC_DUS_29', 'K1', '{"etudiant","emprunt"}', 'Les étudiants qui empruntent des ouvrages interdits « par erreur »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_06', 'NPC_DUS_29', 'K1', '{"archive","riviere"}', 'L''humidité de la Rivière d''Encre qui menace les pages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_07', 'NPC_DUS_29', 'K2', '{"livre","lieu"}', 'Le livre chuchote des lieux absents de la carte de Duskarn', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_08', 'NPC_DUS_29', 'K2', '{"ouvrage","source"}', 'L''ouvrage ne vient d''aucune imprimerie de la cité — il est « apparu » sur l''étagère', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_09', 'NPC_DUS_29', 'K3', '{"bibliotheque","cardinal"}', 'La bibliothèque est une mémoire cache du serveur : le Cardinal y stocke les lieux effacés de Duskarn, et le livre chuchote ce qui a été supprimé', NULL, '*(elle pose un doigt sur ses lèvres)* « Chut. Les livres ici ne parlent pas. Lis en silence, et oublie ce que tu as cru entendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_29_10', 'NPC_DUS_29', 'KX', '{"*(hors sujet)*"}', '*(elle époussette une couverture)* « Une page effacée reste une page. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_01', 'NPC_DUS_30', 'K0', '{"bazar","securite"}', 'Sa patrouille du Bazar des Ombres et les règles du marché', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_02', 'NPC_DUS_30', 'K0', '{"vol","protection"}', 'Comment il protège les étals des pickpockets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_03', 'NPC_DUS_30', 'K0', '{"ronde","horaire"}', 'Ses horaires et les postes de garde du bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_04', 'NPC_DUS_30', 'K1', '{"disparition","objet"}', 'Des objets qui disparaissent des étals sans voleur visible', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_05', 'NPC_DUS_30', 'K1', '{"ombre","etrange"}', 'L''ombre du bazar qui semble « boire » la lumière des lanternes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_06', 'NPC_DUS_30', 'K1', '{"receleur","liens"}', 'Ce qu''il soupçonne du Receleur des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_07', 'NPC_DUS_30', 'K2', '{"disparition","cause"}', 'Les objets ne sont pas volés : c''est la rivière d''encre, sous le bazar, qui les attire', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_08', 'NPC_DUS_30', 'K2', '{"sol","fuite"}', 'Le sol du bazar cache une veine de la Rivière d''Encre — les objets y tombent', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_09', 'NPC_DUS_30', 'K3', '{"bazar","cardinal"}', 'Le Bazar des Ombres est une zone de test du Cardinal : la disparition des objets mesure l''absorption de matière par le nœud des ténèbres', NULL, '*(il fait tourner sa lame)* « Rien ne disparaît ici. C''est le marché. Circule. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_30_10', 'NPC_DUS_30', 'KX', '{"*(hors sujet)*"}', '*(il balaye l''allée du regard)* « L''ombre a faim, ce soir. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_01', 'NPC_DUS_31', 'K0', '{"dague","catalogue"}', 'Son catalogue de dagues fines — acier, longueur, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_02', 'NPC_DUS_31', 'K0', '{"forge","provenance"}', 'D''où viennent ses lames — Corniche de la Forge Noire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_03', 'NPC_DUS_31', 'K0', '{"affaire","marche"}', 'Ses prix et l''art de marchander dans le noir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_04', 'NPC_DUS_31', 'K1', '{"dague","vivante"}', 'La dague « guetteuse » qui semble viser seule', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_05', 'NPC_DUS_31', 'K1', '{"client","etrange"}', 'Les clients qui reviennent pour la guetteuse, sans oser l''acheter', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_06', 'NPC_DUS_31', 'K1', '{"forge","umbra"}', 'Ce que Forgeronne Umbra lui a confié sur l''enchantement d''ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_07', 'NPC_DUS_31', 'K2', '{"dague","ame"}', 'La guetteuse est liée à une âme saisie par un prêt de Skell', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_08', 'NPC_DUS_31', 'K2', '{"lame","voile"}', 'La lame réagit au Voile du Temple — elle frémit près des lieux saints', '`QUEST:QST_IMP_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_09', 'NPC_DUS_31', 'K3', '{"arme","cardinal"}', 'La dague est un prototype du Cardinal : une arme qui cible seule les « anomalies » du serveur, testée dans le bazar', NULL, '*(il range la guetteuse sous le comptoir)* « Belle pièce, hein ? Pas à vendre. Regarde les autres. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_31_10', 'NPC_DUS_31', 'KX', '{"*(hors sujet)*"}', '*(il fait luire une lame)* « Une dague bien tenue ne trahit jamais. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_01', 'NPC_DUS_32', 'K0', '{"reparation","lame"}', 'Ses services de réparation d''armes — délai, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_02', 'NPC_DUS_32', 'K0', '{"meule","froid"}', 'Sa meule froide, qui ne chauffe jamais l''acier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_03', 'NPC_DUS_32', 'K0', '{"entretien","marche"}', 'L''entretien courant des dagues et épées du bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_04', 'NPC_DUS_32', 'K1', '{"lame","sang"}', 'L''épée qui « saigne » du noir quand il la lime', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_05', 'NPC_DUS_32', 'K1', '{"client","etrange"}', 'Le client qui rapporte toujours la même lame, jamais usée', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_06', 'NPC_DUS_32', 'K1', '{"forge","umbra"}', 'Ce que Forgeronne Umbra dit de l''enchantement d''ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_07', 'NPC_DUS_32', 'K2', '{"lame","ame"}', 'La lame contient une âme saisie — elle saigne parce qu''elle se souvient', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_08', 'NPC_DUS_32', 'K2', '{"noir","source"}', 'Le noir qui coule vient de la Rivière d''Encre, lié à la lame', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_09', 'NPC_DUS_32', 'K3', '{"arme","cardinal"}', 'Les lames qu''il répare sont recalibrées par le Cardinal : le « sang noir » est l''écho d''une arme-test du nœud des ténèbres', NULL, '*(il essuie la lame, mutique)* « Une lame est une lame. Elle ne saigne pas. Tu as mal vu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_32_10', 'NPC_DUS_32', 'KX', '{"*(hors sujet)*"}', '*(il tourne la meule)* « L''acier oublie. C''est son seul don. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_33_01', 'NPC_DUS_33', 'K0', '{"location","dague"}', 'Son service de location de dagues — caution, tarif', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_33_02', 'NPC_DUS_33', 'K0', '{"duel","ombre"}', 'Les duels d''ombre du bazar et leurs règles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_33_03', 'NPC_DUS_33', 'K0', '{"retour","inventaire"}', 'La gestion des retours et de son inventaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_33_04', 'NPC_DUS_33', 'K1', '{"dague","maudite"}', 'La dague maudite qui revient tachée de noir', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_33_05', 'NPC_DUS_33', 'K1', '{"dueliste","gain"}', 'Ceux qui la prennent gagnent — puis oublient leur nom', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
