INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_39_09', 'NPC_DUS_39', 'K3', '{"crieur","cardinal"}', 'Le Crieur est un haut-parleur du Cardinal : la rivière lui souffle les données du serveur, et il les diffuse sans le savoir', NULL, '*(il s''éclaircit la voix, gêné)* « J''ai dit ce que j''ai dit. Le reste, c''était le vent du canyon. »');
