INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_40_09', 'NPC_DUS_40', 'K3', '{"taverne","cardinal"}', 'L''Encrier est un nœud d''écoute du Cardinal : les secrets bus dans l''hydromel alimentent la mémoire du serveur, et l''oubli est programmé', NULL, '*(il essuie un verre, lointain)* « Les clients viennent, repartent. Je me rappelle plus. C''est l''Encrier, pas moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_40_10', 'NPC_DUS_40', 'KX', '{"*(hors sujet)*"}', '*(il sert un verre)* « Bois noir, parle bas, oublie vite. »', '—', NULL);
