INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_41_06', 'NPC_DUS_41', 'K1', '{"tavernier","confidence"}', 'Ce qu''elle confie au Tavernier de l''Ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_41_07', 'NPC_DUS_41', 'K2', '{"client","identite"}', 'Le client sans ombre n''est pas un Imp — il n''existe pas au registre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_41_08', 'NPC_DUS_41', 'K2', '{"encrier","source"}', 'Le fond de la salle touche la Rivière d''Encre — il attire ce qui n''a pas d''ombre', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_41_09', 'NPC_DUS_41', 'K3', '{"client","cardinal"}', 'Le client sans ombre est un sous-processus du Cardinal : il vient « goûter » les secrets bus à l''Encrier, interface vivante du serveur', NULL, '*(elle recule d''un pas)* « Ce client ? Je le sers, c''est tout. Il n''est jamais là. Oublie-le. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_41_10', 'NPC_DUS_41', 'KX', '{"*(hors sujet)*"}', '*(elle pose un verre)* « Qui boit dans le noir ne paie pas en Yrds. »', '—', NULL);
