INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_43_06', 'NPC_DUS_43', 'K1', '{"veteran","maitre"}', 'Ce que le Vétéran des Chœurs lui a appris', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_43_07', 'NPC_DUS_43', 'K2', '{"chanson","ame"}', 'La chanson arrache un souvenir à l''auditeur endormi', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_43_08', 'NPC_DUS_43', 'K2', '{"musique","source"}', 'La mélodie vient du nœud des ténèbres, relayée par la rivière', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_43_09', 'NPC_DUS_43', 'K3', '{"barde","cardinal"}', 'La chanson est une fréquence du Cardinal : elle efface les souvenirs du serveur par la rivière, et le barde en est l''instrument vivant', NULL, '*(il couvre les cordes)* « Ma chanson dort. Toi aussi, tu devrais. Oublie-la. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
