INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_44_08', 'NPC_DUS_44', 'K2', '{"oubli","source"}', 'L''oubli des dormeurs est absorbé par le nœud des ténèbres', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_44_09', 'NPC_DUS_44', 'K3', '{"auberge","cardinal"}', 'L''auberge est une unité de purge du Cardinal : les souvenirs des dormeurs sont effacés et stockés, la chambre du fond est l''interface d''oubli', NULL, '*(il lisse un drap)* « La chambre du fond est prise. dors dans une autre. Et ne demande pas pourquoi. »');
