INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_46_06', 'NPC_DUS_46', 'K1', '{"receleur","liens"}', 'Ce que le Receleur des Ombres dépose parfois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_46_07', 'NPC_DUS_46', 'K2', '{"coffre","ame"}', 'Le coffre contient une âme saisie par un prêt de Skell', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_46_08', 'NPC_DUS_46', 'K2', '{"larme","source"}', 'La larme d''encre vient de la Rivière d''Encre, sous l''auberge', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_46_09', 'NPC_DUS_46', 'K3', '{"coffre","cardinal"}', 'Le coffre est un terminal du Cardinal : l''âme saisie y est stockée avant absorption par le nœud des ténèbres, et la larme en est le rejet', NULL, '*(il essuie le coffre)* « L''humidité, rien d''autre. Touche pas à ce coffre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_46_10', 'NPC_DUS_46', 'KX', '{"*(hors sujet)*"}', '*(il tourne une clé)* « Ce qui est enfermé dort. Parfois, il pleure. »', '—', NULL);
