INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_47_06', 'NPC_DUS_47', 'K1', '{"route","compagnon"}', 'Les autres colporteurs qu''il croise sur la route', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_47_07', 'NPC_DUS_47', 'K2', '{"oubli","riviere"}', 'Ses trajets passent près de nœuds de ténèbres qui lui effacent des souvenirs', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_47_08', 'NPC_DUS_47', 'K2', '{"origine","source"}', 'La provenance altérée vient du Cardinal qui réécrit les registres', '`QUEST:QST_IMP_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_47_09', 'NPC_DUS_47', 'K3', '{"colporteur","cardinal"}', 'Le colportage est une sonde du Cardinal : les villes sont reliées par des routes qui effacent les données, et le marchand en est le vecteur', NULL, '*(il referme son sac)* « J''ai acheté ça à Alne, j''te dis. Enfin… à un endroit. Achète ou passe. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
