INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_03', 'NPC_DUS_48', 'K0', '{"arriere","salle"}', 'Son arrière-salle cachée du bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_04', 'NPC_DUS_48', 'K1', '{"objet","mort"}', 'Les objets « trouvés » appartenaient à des morts', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_05', 'NPC_DUS_48', 'K1', '{"medaillon","reve"}', 'Le médaillon qui lui parle dans ses rêves', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_06', 'NPC_DUS_48', 'K1', '{"garde","evasion"}', 'Comment il échappe à la Garde du Bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_07', 'NPC_DUS_48', 'K2', '{"objet","ame"}', 'Le médaillon contient l''âme du défunt — il la sent', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_08', 'NPC_DUS_48', 'K2', '{"recel","source"}', 'Les objets viennent du nœud des ténèbres qui les relâche', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_09', 'NPC_DUS_48', 'K3', '{"recel","cardinal"}', 'Le receleur est un drain du Cardinal : les objets des morts sont restitués par la rivière après absorption de l''âme, et il en est le réceptacle', NULL, '*(il cache le médaillon)* « Trouvé, j''te dis. Pas de mort, pas de nom. Achète et ferme-la. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_48_10', 'NPC_DUS_48', 'KX', '{"*(hors sujet)*"}', '*(il jette un œil à l''ombre)* « Ce qui revient de la rivière n''est plus à personne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_01', 'NPC_DUS_49', 'K0', '{"visite","ville"}', 'Sa visite guidée de Duskarn, la ville sans aube', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_02', 'NPC_DUS_49', 'K0', '{"bazar","lieu"}', 'Le Bazar des Ombres et les lieux de départ', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_03', 'NPC_DUS_49', 'K0', '{"conseil","nouveau"}', 'Ses conseils pour survivre dans le noir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_04', 'NPC_DUS_49', 'K1', '{"riviere","arret"}', 'La visite s''arrête avant la rive de la Rivière d''Encre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_05', 'NPC_DUS_49', 'K1', '{"guide","disparu"}', 'Son prédécesseur qui a plongé la main et oublié son nom', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_06', 'NPC_DUS_49', 'K1', '{"temple","voile"}', 'Ce qu''il montre du Temple du Voile de loin', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_07', 'NPC_DUS_49', 'K2', '{"riviere","souvenir"}', 'La rivière absorbe les souvenirs de qui la touche', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_08', 'NPC_DUS_49', 'K2', '{"guide","source"}', 'Le prédécesseur a été effacé par le nœud des ténèbres', '`QUEST:QST_IMP_ENCRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_09', 'NPC_DUS_49', 'K3', '{"guide","cardinal"}', 'Le guide est une interface d''accueil du Cardinal : la Rivière d''Encre efface les données des nouveaux pour « initialiser » leur séjour à Duskarn', NULL, '*(il recule d''un pas)* « La rive, c''est pas ma visite. Va voir l''Oracle si tu veux comprendre l''eau. Moi, j''arrête ici. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_49_10', 'NPC_DUS_49', 'KX', '{"*(hors sujet)*"}', '*(il désigne le canyon)* « Bienvenue dans la ville qui n''a jamais vu l''aube. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_01', 'NPC_DUS_50', 'K0', '{"corniche","guet"}', 'Ce qu''il surveille — trajectoires des montures et des ombres du canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_02', 'NPC_DUS_50', 'K0', '{"altitude","poste"}', 'Son poste sur le Balcon du Conseil — rotation toutes les trois heures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_03', 'NPC_DUS_50', 'K0', '{"longue-vue","outil"}', 'Sa longue-vue d''obsidienne — grossit l''ombre, pas la lumière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_04', 'NPC_DUS_50', 'K1', '{"voltige","forme"}', 'Les « formes qui volent la nuit » — parfois aucune ne bat des ailes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_05', 'NPC_DUS_50', 'K1', '{"routine","relève"}', 'Pourquoi la relève tombe souvent en panne — « le couloir du Balcon s''allonge »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_06', 'NPC_DUS_50', 'K1', '{"alarme","protocole"}', 'Le protocole s''il voit une forme entrer par le haut — prévient Korvac, pas le Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_07', 'NPC_DUS_50', 'K2', '{"silhouette","aile"}', 'La silhouette sans ailes — elle n''a pas d''ombre portée au sol', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_08', 'NPC_DUS_50', 'K2', '{"corridor","anomalie"}', 'Le corridor du Balcon qui « s''allonge » la nuit — une mesure qui change sans cause', '`QUEST:DUS_GUET_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_09', 'NPC_DUS_50', 'K3', '{"ombre","regulation"}', 'Les ombres de Duskarn ne sont pas que de l''obscurité : une force les tient accordées à la nuit, comme un régulateur qui empêche l''aube de venir — et la ville entière en dépend', NULL, '*(il baisse sa longue-vue)* « Voler, c''est tout ce que je vois. Si tu cherches pourquoi le ciel ne se lève pas, demande au fleuve. Moi, je regarde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_50_10', 'NPC_DUS_50', 'KX', '{"*(hors sujet)*"}', '*(il hausse les épaules)* « Une corniche, un guet, une nuit. Tu veux autre chose ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_01', 'NPC_DUS_51', 'K0', '{"bijoux","prix"}', 'Ses bijoux de cristal violet — prix, tailles, encastrement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_02', 'NPC_DUS_51', 'K0', '{"veine","provenance"}', 'D''où vient le cristal — extrait des veines du canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_03', 'NPC_DUS_51', 'K0', '{"taille","service"}', 'Son service de taille et de sertissage sur commande', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_04', 'NPC_DUS_51', 'K1', '{"battement","pierre"}', 'Le bijou qui « bat » — il dit que c''est la qualité de la pierre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_05', 'NPC_DUS_51', 'K1', '{"demande","alchimie"}', 'Pourquoi les alchimistes en achètent autant — « ils disent que ça stocke l''ombre »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_06', 'NPC_DUS_51', 'K1', '{"marche","commerce"}', 'Sa clientèle — Imp du Conseil, mais aussi visiteurs d''Alne et de Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_07', 'NPC_DUS_51', 'K2', '{"coeur","cristal"}', 'Le bijou qui bat ne s''arrête jamais, même scellé — il a peur qu''on le lui reprenne', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_08', 'NPC_DUS_51', 'K2', '{"veine","pulse"}', 'Les veines de cristal du canyon « pulsent » la nuit à un rythme régulier, comme réglées', '`QUEST:DUS_CRISTAL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_09', 'NPC_DUS_51', 'K3', '{"coeur","serveur"}', 'Le cristal violet est le conduit par lequel Duskarn régule les ténèbres du serveur ; chaque bijou bat parce qu''il est relié au cœur d''ombre de la ville', NULL, '*(il range le bijou dans un écrin)* « Un bijou qui bat, c''est une pierre vivante. Rien de plus. Si tu veux du mystère, va interroger la Rivière. Moi, je vends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_51_10', 'NPC_DUS_51', 'KX', '{"*(hors sujet)*"}', '*(il fait rouler une pierre dans sa paume)* « Une pierre, c''est une pierre. Le reste, c''est ton ombre qui parle. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_01', 'NPC_DUS_52', 'K0', '{"furtivite","cours"}', 'Ses cours de furtivité — prix, durée, prérequis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_02', 'NPC_DUS_52', 'K0', '{"technique","base"}', 'La technique de base — fondre son ombre dans le décor', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_03', 'NPC_DUS_52', 'K0', '{"voile","lieu"}', 'Pourquoi il enseigne au Temple du Voile — « le Voile est le maître »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_04', 'NPC_DUS_52', 'K1', '{"ombre","suite"}', 'L''ombre qui le suit — il la croit un effet de son propre sort', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_05', 'NPC_DUS_52', 'K1', '{"pacte","eleves"}', 'Ses élèves servent le Pacte des Ombres — entraînement d''espions', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_06', 'NPC_DUS_52', 'K1', '{"echec","limite"}', 'Pourquoi certains élèves ne reviennent pas du test final — « le Voile les garde »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_07', 'NPC_DUS_52', 'K2', '{"ombre","double"}', 'L''ombre qui l''imite ne réagit pas à sa volonté — elle a un léger retard', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_08', 'NPC_DUS_52', 'K2', '{"voile","secret"}', 'Le Voile ne cache pas l''école : il cache une salle où l''ombre est « réglée » pour toute la ville', '`QUEST:DUS_VOILE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_09', 'NPC_DUS_52', 'K3', '{"ombre","seed"}', 'L''ombre qui le suit est la même que celle qui régule Duskarn — le camouflage Imp n''est qu''une fenêtre ouverte sur le régulateur d''ombre du serveur', NULL, '*(l''ombre derrière lui vacille une seconde)* « Une ombre qui te suit, c''est ton âme qui doute. Rien d''autre. Apprends à disparaître, puis va voir ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_52_10', 'NPC_DUS_52', 'KX', '{"*(hors sujet)*"}', '*(il n''est plus là)* « …tu parlais ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_01', 'NPC_DUS_53', 'K0', '{"astrologie","ciel"}', 'Ce qu''il lit dans le ciel de Duskarn — étoiles, cycles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_02', 'NPC_DUS_53', 'K0', '{"poste","balcon"}', 'Son poste au Balcon du Conseil — observations nocturnes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_03', 'NPC_DUS_53', 'K0', '{"présage","service"}', 'Ses présages payants pour le Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_04', 'NPC_DUS_53', 'K1', '{"etoile","trou"}', 'L''étoile qui ne brille pas — il l''appelle « le trou du ciel »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_05', 'NPC_DUS_53', 'K1', '{"carte","erreur"}', 'Pourquoi sa carte du ciel ne correspond à aucune autre — « la nuit d''ici est à part »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_06', 'NPC_DUS_53', 'K1', '{"conseil","usage"}', 'Ce que le Conseil fait de ses présages — ajuste les patrouilles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_07', 'NPC_DUS_53', 'K2', '{"trou","regard"}', 'Le trou du ciel « le regarde » — il a l''impression d''être observé depuis l''étoile manquante', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_08', 'NPC_DUS_53', 'K2', '{"ciel","fixe"}', 'Le ciel de Duskarn ne tourne pas comme ailleurs — il est « fixé » sur un axe qui ne bouge pas', '`QUEST:DUS_ASTRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_09', 'NPC_DUS_53', 'K3', '{"axe","regulation"}', 'Le ciel figé de Duskarn est maintenu par le même régulateur d''ombre qui empêche l''aube ; l''étoile manquante est l''endroit où le serveur laisse passer le reste du monde', NULL, '*(il ferme son astrolabe)* « Le ciel est le ciel. Le trou, c''est ton œil qui faiblit. Va plutôt interroger la Rivière, elle sait ce que le ciel cache. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_53_10', 'NPC_DUS_53', 'KX', '{"*(hors sujet)*"}', '*(il compte)* « Une, deux… la suivante n''est pas là. Comme d''habitude. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_01', 'NPC_DUS_54', 'K0', '{"defense","plan"}', 'Ses plans de défense par quadrant d''ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_02', 'NPC_DUS_54', 'K0', '{"poste","conseil"}', 'Son poste au Balcon du Conseil — stratégie urbaine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_03', 'NPC_DUS_54', 'K0', '{"ombre","usage"}', 'Comment il utilise les zones d''ombre comme remparts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_04', 'NPC_DUS_54', 'K1', '{"ennemi","vue"}', 'L''ennemi qu''il voit seul — une forme dans les noirs de la carte', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_05', 'NPC_DUS_54', 'K1', '{"approvisionnement","guet"}', 'Pourquoi ses plans exigent plus de guetteurs chaque mois', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_06', 'NPC_DUS_54', 'K1', '{"conseil","secret"}', 'Ce que le Conseil ne lui demande pas — il planifie « au-delà du mur »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_07', 'NPC_DUS_54', 'K2', '{"forme","meme"}', 'La forme qu''il voit emprunte toujours le même chemin que l''ombre du guet de `NPC_DUS_50`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_08', 'NPC_DUS_54', 'K2', '{"carte","fixe"}', 'Sa carte « s''étend » la nuit vers des zones qui n''existent pas le jour', '`QUEST:DUS_DEFENSE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_09', 'NPC_DUS_54', 'K3', '{"ombre","seed"}', 'L''ennemi qu''il traque est le régulateur d''ombre lui-même qui se déplace dans la ville ; ses plans décrivent en réalité les mouvements du cœur d''ombre de Duskarn', NULL, '*(il replace une pièce sur la carte)* « Un ennemi, c''est un ennemi. Tu veux savoir qui tient l''ombre ? Demande au fleuve. Moi, je défends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_54_10', 'NPC_DUS_54', 'KX', '{"*(hors sujet)*"}', '*(il pointe un quadrant vide)* « Ici. Rien. C''est le plus dangereux. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_01', 'NPC_DUS_55', 'K0', '{"contrat","quete"}', 'Ses contrats pour le Nid de Guet — nettoyage de corniches, patrol', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_02', 'NPC_DUS_55', 'K0', '{"guerreduskarn","histoire"}', 'Ses récits de guerre dans le canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_03', 'NPC_DUS_55', 'K0', '{"recompense","service"}', 'Ses récompenses en Yrds et cristaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_04', 'NPC_DUS_55', 'K1', '{"traite","paix"}', 'Le traité de paix — il dit qu''une clause manque à tous les exemplaires', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_05', 'NPC_DUS_55', 'K1', '{"gant","blessure"}', 'Son gant noir — une vieille blessure « qui ne cicatrise pas à la lumière »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_06', 'NPC_DUS_55', 'K1', '{"nid","recrutement"}', 'Pourquoi il envoie les jeunes au Nid — « pour qu''ils voient avant d''être vus »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_07', 'NPC_DUS_55', 'K2', '{"signature","non-humaine"}', 'La signature du traité n''est pas d''une main — elle ressemble à un sceau d''ombre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_08', 'NPC_DUS_55', 'K2', '{"clause","manquante"}', 'La clause manquante parle d''un « régulateur » qui garantit la paix — mot rayé de tous les brouillons', '`QUEST:DUS_TRAITE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_09', 'NPC_DUS_55', 'K3', '{"regulateur","paix"}', 'Le traité tient parce que Duskarn est le nœud qui régule les ténèbres du serveur ; la paix n''est pas diplomatique, elle est maintenue par le cœur d''ombre', NULL, '*(il serre le gant)* « La paix, c''est un mot pour ceux qui dorment. Moi, je donne des contrats. Si tu veux le fin mot, va à la Rivière. Elle te noiera avant de te répondre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_55_10', 'NPC_DUS_55', 'KX', '{"*(hors sujet)*"}', '*(il crache)* « Une guerre de plus, une de moins. Le canyon s''en fiche. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_01', 'NPC_DUS_56', 'K0', '{"falaise","poste"}', 'Son poste de garde aux Falaises du Crépuscule', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_02', 'NPC_DUS_56', 'K0', '{"pacte","frontiere"}', 'Le Pacte des Ombres — ce qu''il couvre côté Spriggan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_03', 'NPC_DUS_56', 'K0', '{"patrol","routine"}', 'Ses rondes et le protocole d''alerte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_04', 'NPC_DUS_56', 'K1', '{"accord","signe"}', 'L''accord « signé dans le noir » — aucun des deux camps ne l''a lu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_05', 'NPC_DUS_56', 'K1', '{"spriggan","louange"}', 'Pourquoi les Spriggan obéissent sans discuter — « l''ombre leur parle »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_06', 'NPC_DUS_56', 'K1', '{"trafic","frontiere"}', 'Ce qui passe la frontière la nuit — renseignements, jamais d''armes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_07', 'NPC_DUS_56', 'K2', '{"parchemin","illisible"}', 'Le parchemin du Pacte est en langue d''ombre — aucun traducteur ne le déchiffre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_08', 'NPC_DUS_56', 'K2', '{"obeissance","force"}', 'Les deux camps obéissent sans lire car une « force » dans l''ombre valide le sceau', '`QUEST:DUS_PACTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_09', 'NPC_DUS_56', 'K3', '{"seed","pacte"}', 'Le Pacte Imp–Spriggan est scellé par le régulateur d''ombre de Duskarn ; l''ombre qui « parle » aux Spriggan est le même cœur d''ombre qui tient la ville', NULL, '*(elle se raidit)* « Un pacte, c''est un pacte. Tu veux savoir qui tient l''ombre, demande à la Rivière. Moi, je garde la falaise. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_56_10', 'NPC_DUS_56', 'KX', '{"*(hors sujet)*"}', '*(elle scrute l''horizon)* « Le crépuscule ne bouge pas. Comme d''habitude. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_01', 'NPC_DUS_57', 'K0', '{"service","seigneur"}', 'Son rôle auprès du Seigneur Imp', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_02', 'NPC_DUS_57', 'K0', '{"balcon","lieu"}', 'Son poste au Balcon du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_03', 'NPC_DUS_57', 'K0', '{"etiquette","usage"}', 'Les usages de cour qu''elle transmet aux visiteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_04', 'NPC_DUS_57', 'K1', '{"ombre","desync"}', 'Les ombres du Seigneur qui ne suivent pas sa bouche — « il trébuche parfois »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_05', 'NPC_DUS_57', 'K1', '{"verite","doute"}', 'Quand elle croit qu''il « ne joue pas juste » — toujours lors des édits sur l''ombre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_06', 'NPC_DUS_57', 'K1', '{"vice-chancelier","lien"}', 'Elle couvre le Vice-Chancelier qui sait que le Seigneur est un hologramme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_07', 'NPC_DUS_57', 'K2', '{"hologramme","soupcon"}', 'Le Seigneur n''a pas de corps — son ombre est projetée, pas portée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_08', 'NPC_DUS_57', 'K2', '{"edict","ombre"}', 'Les édits sur « l''ombre » changent la ville sans vote du Conseil', '`QUEST:DUS_SEIGNEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_09', 'NPC_DUS_57', 'K3', '{"seed","hologramme"}', 'Le Seigneur Imp est l''interface par laquelle le régulateur d''ombre gouverne Duskarn ; son hologramme est piloté depuis le cœur d''ombre', NULL, '*(elle lisse sa manche)* « Mon Seigneur est mon Seigneur. Si l''ombre le trahit, ce n''est pas mon affaire. Va voir la Rivière, elle sait qui projette qui. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_57_10', 'NPC_DUS_57', 'KX', '{"*(hors sujet)*"}', '*(elle sourit)* « Une tasse de thé d''encre ? Non ? Comme il vous plaît. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_01', 'NPC_DUS_58', 'K0', '{"edict","redaction"}', 'Ce qu''il écrit pour le Seigneur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_02', 'NPC_DUS_58', 'K0', '{"balcon","poste"}', 'Son bureau au Balcon du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_03', 'NPC_DUS_58', 'K0', '{"registre","usage"}', 'Son registre des édits, consultable sur demande', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_04', 'NPC_DUS_58', 'K1', '{"edict","sans signature"}', 'L''édit non signé — il ne sait pas qui l''a dicté', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_05', 'NPC_DUS_58', 'K1', '{"obeissance","ville"}', 'Pourquoi la ville a obéi sans signature — « l''ombre l''a validé »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_06', 'NPC_DUS_58', 'K1', '{"heraut","lien"}', 'Ce que l''Héraut proclame — parfois plus que le texte réel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_07', 'NPC_DUS_58', 'K2', '{"vide","legal"}', 'Le vide légal : un édit « d''ombre » prime sur le Conseil sans trace écrite', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_08', 'NPC_DUS_58', 'K2', '{"poids","ombre"}', 'Ses parchemins ont un « poids d''ombre » qui change selon la nuit — mesuré, pas ressenti', '`QUEST:DUS_EDIT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_09', 'NPC_DUS_58', 'K3', '{"seed","edict"}', 'Les édits d''ombre viennent du régulateur d''ombre de Duskarn ; le scribe ne fait que transcrire ce que le cœur d''ombre dicte à la ville', NULL, '*(il cache le parchemin)* « Un scribe écrit. Il ne dicte pas. Si tu veux le vrai plumitif, va à la Rivière. Elle noie l''encre avant qu''elle sèche. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_58_10', 'NPC_DUS_58', 'KX', '{"*(hors sujet)*"}', '*(il taillle sa plume)* « Une ligne, une loi. Ou une ombre. On ne choisit pas toujours. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_01', 'NPC_DUS_59', 'K0', '{"annonce","balcon"}', 'Ce qu''il proclame depuis le Balcon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_02', 'NPC_DUS_59', 'K0', '{"poste","service"}', 'Son rôle de héraut du Seigneur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_03', 'NPC_DUS_59', 'K0', '{"nouvelle","usage"}', 'Les nouvelles qu''il diffuse au public', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_04', 'NPC_DUS_59', 'K1', '{"nouvelle","tue"}', 'La nouvelle qu''il n''a pas criée — une voix d''ombre la lui a interdite', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_05', 'NPC_DUS_59', 'K1', '{"souffle","ombre"}', 'L''ombre qui lui « souffle » de garder certaines choses', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_06', 'NPC_DUS_59', 'K1', '{"scribe","lien"}', 'Ce que le Scribe lui donne — parfois un texte tronqué', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_07', 'NPC_DUS_59', 'K2', '{"interdit","voix"}', 'La voix d''ombre qui l''a fait taire venait du même endroit que le Seigneur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_08', 'NPC_DUS_59', 'K2', '{"texte","tronque"}', 'Les édits qu''il reçoit sont déjà « amputés » avant sa lecture', '`QUEST:DUS_HERAULT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_09', 'NPC_DUS_59', 'K3', '{"seed","voix"}', 'L''héraut ne fait que répéter le régulateur d''ombre ; la nouvelle tue est ce que le cœur d''ombre refuse que Duskarn entende', NULL, '*(il gonfle le torse)* « Un héraut crie ce qu''on lui donne ! Si tu veux la nouvelle cachée, plonge dans la Rivière. Elle crie, elle, sous l''eau. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_59_10', 'NPC_DUS_59', 'KX', '{"*(hors sujet)*"}', '*(il tousse)* « …PEUPLE ! …non, rien. Repasse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_01', 'NPC_DUS_60', 'K0', '{"illusion","cours"}', 'Ses leçons d''illusion au Temple', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_02', 'NPC_DUS_60', 'K0', '{"voile","lieu"}', 'Pourquoi il se produit au Temple du Voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_03', 'NPC_DUS_60', 'K0', '{"prix","service"}', 'Ses tarifs de représentation et de formation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_04', 'NPC_DUS_60', 'K1', '{"illusion","persiste"}', 'L''illusion qui « ne se dissipe pas » — un décor qui reste', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_05', 'NPC_DUS_60', 'K1', '{"angle","mort"}', 'L''angle mort de la salle où l''illusion vit — personne ne le voit sauf lui', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_06', 'NPC_DUS_60', 'K1', '{"eleve","secret"}', 'Ce qu''il enseigne aux élus — des illusions qui obéissent seules', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_07', 'NPC_DUS_60', 'K2', '{"vie","propre"}', 'L''illusion a « sa propre vie » — elle se déplace quand il dort', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_08', 'NPC_DUS_60', 'K2', '{"voile","source"}', 'Le Temple puise ses illusions dans une « source » d''ombre sous l''autel', '`QUEST:DUS_ILLUSION_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_09', 'NPC_DUS_60', 'K3', '{"seed","source"}', 'La source d''ombre du Temple est le même conduit que le régulateur d''ombre de Duskarn ; ses illusions persistent parce qu''elles sont alimentées par le cœur d''ombre', NULL, '*(l''illusion frémit)* « Une ombre qui vit ? Poésie. Va voir la Rivière si tu veux du vrai mystère. Moi, je joue. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_60_10', 'NPC_DUS_60', 'KX', '{"*(hors sujet)*"}', '*(il fait apparaître une fleur d''ombre)* « Tiens. Elle est partie dans trois jours. Peut-être. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_01', 'NPC_DUS_61', 'K0', '{"enchantement","arme"}', 'Ses enchantements d''ombre pour les lames Imp', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_02', 'NPC_DUS_61', 'K0', '{"forge","lieu"}', 'Son établi à la Corniche de la Forge Noire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_03', 'NPC_DUS_61', 'K0', '{"prix","service"}', 'Ses tarifs d''enchantement sur commande', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_04', 'NPC_DUS_61', 'K1', '{"sort","auto"}', 'Le sort qui s''attache seul — il croit la forge « vivante »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_05', 'NPC_DUS_61', 'K1', '{"signature","forge"}', 'Pourquoi certaines lames reviennent déjà enchantées', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_06', 'NPC_DUS_61', 'K1', '{"umbre","lien"}', 'Ce qu''il reçoit d''Umbra — des lames « pré-signées »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_07', 'NPC_DUS_61', 'K2', '{"marque","forge"}', 'La marque qui apparaît est identique sur toutes les lames d''ombre de Duskarn', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_08', 'NPC_DUS_61', 'K2', '{"forge","source"}', 'La Forge Noire est alimentée par une « veine » d''ombre commune à toute la ville', '`QUEST:DUS_FORGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_09', 'NPC_DUS_61', 'K3', '{"seed","veine"}', 'La veine d''ombre qui alimente la Forge est le conduit du régulateur d''ombre de Duskarn ; les enchantements « auto » viennent du cœur d''ombre', NULL, '*(il pose la lime)* « Une lame, un sort, un forgeur. Le reste, c''est la pierre qui chante. Va à la Rivière si tu veux l''oreille du cœur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_61_10', 'NPC_DUS_61', 'KX', '{"*(hors sujet)*"}', '*(il frotte une lame)* « Elle chante faux, celle-là. Comme d''habitude. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_01', 'NPC_DUS_62', 'K0', '{"forge","apprentissage"}', 'Ce qu''il apprend auprès d''Umbra', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_02', 'NPC_DUS_62', 'K0', '{"corniche","lieu"}', 'Son établi à la Corniche de la Forge Noire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_03', 'NPC_DUS_62', 'K0', '{"aide","service"}', 'Ce qu''il aide à faire — lingots, réparations simples', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_04', 'NPC_DUS_62', 'K1', '{"lame","chante"}', 'La lame qui « chante faux » — une note qu''il n''a pas forgée', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_05', 'NPC_DUS_62', 'K1', '{"umbrella","methode"}', 'Pourquoi Umbra travaille à froid — « l''ombre ne supporte pas le feu »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_06', 'NPC_DUS_62', 'K1', '{"enchanteur","lien"}', 'Ce que l''Enchanteur dit de ses lames — « déjà signées avant fin »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_07', 'NPC_DUS_62', 'K2', '{"note","source"}', 'La note fausse vient de la même « veine » que les enchantements auto', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_08', 'NPC_DUS_62', 'K2', '{"forge","vivante"}', 'La forge semble réagir à ses coups — comme si elle attendait le bon rythme', '`QUEST:DUS_FORGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_09', 'NPC_DUS_62', 'K3', '{"seed","rythme"}', 'Le rythme que la forge attend est celui du régulateur d''ombre de Duskarn ; la lame chante faux quand l''apprenti décale la cadence du cœur d''ombre', NULL, '*(il pose le marteau)* « Une lame fausse, c''est une lame mal forgée. Rien de plus. Si tu veux le vrai chant, va à la Rivière. Elle, elle chante juste. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_62_10', 'NPC_DUS_62', 'KX', '{"*(hors sujet)*"}', '*(il frappe un lingot)* « Cling. Pas le bon son. Encore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_01', 'NPC_DUS_63', 'K0', '{"grimoire","secret"}', 'Ce qu''il garde dans la salle cachée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_02', 'NPC_DUS_63', 'K0', '{"voile","lieu"}', 'Son accès secret au Temple du Voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_03', 'NPC_DUS_63', 'K0', '{"consultation","usage"}', 'Ce qu''il accepte de montrer aux initiés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_04', 'NPC_DUS_63', 'K1', '{"sort","lumiere"}', 'Le sort qui « annule la lumière » — personne ne le revendique', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_05', 'NPC_DUS_63', 'K1', '{"livre","ecrit"}', 'Le sort était déjà écrit à l''ouverture du livre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_06', 'NPC_DUS_63', 'K1', '{"voile","superior"}', 'Ce qu''il cache à l''Archiviste du Voile officiel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_07', 'NPC_DUS_63', 'K2', '{"auteur","inconnu"}', 'Le sort n''a pas d''auteur connu — signé d''un sceau d''ombre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_08', 'NPC_DUS_63', 'K2', '{"lumiere","source"}', '« Annuler la lumière » ne l''éteint pas : il la redirige vers un point unique de la ville', '`QUEST:DUS_GRIMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_09', 'NPC_DUS_63', 'K3', '{"seed","lumiere"}', 'Le sort interdit est un outil du régulateur d''ombre de Duskarn ; il annule la lumière pour alimenter le cœur d''ombre qui tient la ville dans son crépuscule', NULL, '*(il referme le livre)* « Un sort interdit, c''est un sort qu''on ne lance pas. Si tu veux la source de l''ombre, plonge dans la Rivière. Elle te montrera. Une fois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_63_10', 'NPC_DUS_63', 'KX', '{"*(hors sujet)*"}', '*(il compte les pages)* « Quatre-vingt-neuf. Hier, quatre-vingt-huit. Quelqu''un lit la nuit. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_01', 'NPC_DUS_64', 'K0', '{"donjon","entree"}', 'Son poste à l''entrée de la Caverne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_02', 'NPC_DUS_64', 'K0', '{"hurleur","cri"}', 'Ce que crient les hurleurs — avertissements de raids', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_03', 'NPC_DUS_64', 'K0', '{"protocole","acces"}', 'Le protocole d''entrée dans le donjon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_04', 'NPC_DUS_64', 'K1', '{"hurleur","mensonge"}', 'Les hurleurs qui mentent — des cris sans raid suivant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_05', 'NPC_DUS_64', 'K1', '{"raid","faux"}', 'Pourquoi les raids annoncés n''arrivent pas — « la caverne teste »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_06', 'NPC_DUS_64', 'K1', '{"gardien","lien"}', 'Ce qu''il transmet au Gardien Caverne intérieur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_07', 'NPC_DUS_64', 'K2', '{"cri","source"}', 'Les cris viennent d''une salle « silencieuse » sur les plans de `NPC_DUS_17`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_08', 'NPC_DUS_64', 'K2', '{"caverne","test"}', 'La caverne lance des alertes factices pour mesurer la réaction de la ville', '`QUEST:DUS_HURLEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_09', 'NPC_DUS_64', 'K3', '{"seed","test"}', 'Les hurleurs sont le capteur par lequel le régulateur d''ombre de Duskarn teste la vigilance de la ville ; leurs mensonges calibrent le cœur d''ombre', NULL, '*(il plaque l''oreille)* « Une caverne qui crie, c''est une caverne. Si tu cherches qui écoute, va à la Rivière. Elle entend tout, elle ne répond jamais. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_64_10', 'NPC_DUS_64', 'KX', '{"*(hors sujet)*"}', '*(il compte)* « Un. Deux. Trois cris. Aucun raid. Comme prévu. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_01', 'NPC_DUS_65', 'K0', '{"guet","retraite"}', 'Ce qu''il fait au Nid de Guet, retraité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_02', 'NPC_DUS_65', 'K0', '{"canyon","vue"}', 'Ce qu''il observe du canyon sans aube', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_03', 'NPC_DUS_65', 'K0', '{"histoire","usage"}', 'Ses vieux récits de veille', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_04', 'NPC_DUS_65', 'K1', '{"carte","brulee"}', 'La carte qu''il a brûlée — un passage inconnu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_05', 'NPC_DUS_65', 'K1', '{"passage","silence"}', 'Pourquoi il ne décrit pas le passage — « mieux oublié »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_06', 'NPC_DUS_65', 'K1', '{"eclaireur","lien"}', 'Ce qu''il apprend à l''Éclaireur des Corniches', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_07', 'NPC_DUS_65', 'K2', '{"passage","reel"}', 'Le passage existe — il mène « sous » le canyon, vers l''ombre pure', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_08', 'NPC_DUS_65', 'K2', '{"carte","source"}', 'Sa carte venait d''une source qui « dessinait toute seule la nuit »', '`QUEST:DUS_PASSAGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_09', 'NPC_DUS_65', 'K3', '{"seed","passage"}', 'Le passage sous le canyon débouche sur le régulateur d''ombre de Duskarn ; la carte se dessinait seule parce qu''elle était pilotée par le cœur d''ombre', NULL, '*(il crache sur les braises)* « Un passage, c''est un trou. Un trou, ça mène sous terre. Si tu veux le fond, c''est la Rivière. Moi, j''ai brûlé ma carte. Fin. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_65_10', 'NPC_DUS_65', 'KX', '{"*(hors sujet)*"}', '*(il cligne)* « Le canyon bouge ? Non. C''est moi. Toujours non. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_01', 'NPC_DUS_66', 'K0', '{"membrane","prix"}', 'Ses membranes de chauve-souris — prix, qualité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_02', 'NPC_DUS_66', 'K0', '{"canyon","lieu"}', 'Son étal au Canyon des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_03', 'NPC_DUS_66', 'K0', '{"usage","aile"}', 'À quoi servent les membranes — ailes, voiles, capes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_04', 'NPC_DUS_66', 'K1', '{"membrane","bat"}', 'La membrane qui « bat » après découpe — il dit que c''est la cure', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_05', 'NPC_DUS_66', 'K1', '{"cure","origine"}', 'D''où viennent ses chauves-souris — « des profondeurs du canyon »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_06', 'NPC_DUS_66', 'K1', '{"plumeux","lien"}', 'Ce qu''il échange avec le Plumeux des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_07', 'NPC_DUS_66', 'K2', '{"battement","vie"}', 'La membrane bat au rythme de la ville, pas de l''animal', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_08', 'NPC_DUS_66', 'K2', '{"canyon","profondeur"}', 'Les chauves-souris viennent d''une profondeur où « l''ombre bat comme un cœur »', '`QUEST:DUS_MEMBRANE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_09', 'NPC_DUS_66', 'K3', '{"seed","coeur"}', 'La membrane bat parce qu''elle est imprégnée du régulateur d''ombre de Duskarn ; l''ombre du canyon est le cœur qui bat sous la ville', NULL, '*(il roule la peau)* « Une membrane qui bat, c''est une bête qui reste. Rien de plus. Si tu veux le cœur, c''est la Rivière. Elle bat, elle, en silence. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_66_10', 'NPC_DUS_66', 'KX', '{"*(hors sujet)*"}', '*(il tend une peau)* « Tiens, celle-là ne bat pas. Encore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_01', 'NPC_DUS_67', 'K0', '{"poudre","prix"}', 'Ses poudres d''ombre — prix, granulométrie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_02', 'NPC_DUS_67', 'K0', '{"canyon","lieu"}', 'Son étal au Canyon des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_03', 'NPC_DUS_67', 'K0', '{"usage","camouflage"}', 'À quoi sert la poudre — dissimulation, pièges', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_04', 'NPC_DUS_67', 'K1', '{"poudre","voit"}', 'La poudre de papillon qui « voit » — elle frémit à la présence', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_05', 'NPC_DUS_67', 'K1', '{"papillon","origine"}', 'D''où viennent ses papillons — « des veines du canyon »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_06', 'NPC_DUS_67', 'K1', '{"trappeur","lien"}', 'Ce qu''il achète au Trappeur de Rats', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_07', 'NPC_DUS_67', 'K2', '{"vue","ville"}', 'La poudre réagit au rythme de la ville, pas aux papillons', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_08', 'NPC_DUS_67', 'K2', '{"veine","ombre"}', 'Les veines du canyon alimentent la poudre d''une « ombre qui regarde »', '`QUEST:DUS_POUDRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_09', 'NPC_DUS_67', 'K3', '{"seed","regard"}', 'La poudre voit parce qu''elle est saturée du régulateur d''ombre de Duskarn ; c''est le cœur d''ombre qui observe à travers elle', NULL, '*(il ferme le flacon)* « Une poudre qui voit, c''est une poudre. Si tu veux qu''on te regarde vraiment, c''est la Rivière. Elle ne cligne pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_67_10', 'NPC_DUS_67', 'KX', '{"*(hors sujet)*"}', '*(il souffle une pincée)* « Pfft. Disparu. Enfin, pour toi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_01', 'NPC_DUS_68', 'K0', '{"bois","prix"}', 'Son bois pétrifié — prix, résistance', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_02', 'NPC_DUS_68', 'K0', '{"fond","lieu"}', 'Son étal au fond du canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_03', 'NPC_DUS_68', 'K0', '{"usage","arc"}', 'À quoi sert le bois — arcs, cadres, mobilier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_04', 'NPC_DUS_68', 'K1', '{"bois","craque"}', 'Le bois qui craque seul — il dit que c''est le canyon', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_05', 'NPC_DUS_68', 'K1', '{"petrification","source"}', 'Pourquoi le bois est pétrifié — « figé par l''ombre du fond »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_06', 'NPC_DUS_68', 'K1', '{"membrane","lien"}', 'Ce qu''il fournit au Marchand de Membranes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_07', 'NPC_DUS_68', 'K2', '{"craquement","ville"}', 'Le craquement suit le rythme de la ville, pas le vent', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_08', 'NPC_DUS_68', 'K2', '{"fond","fige"}', 'Le fond du canyon « fige » tout ce qui y entre — bois, temps, souvenirs', '`QUEST:DUS_BOIS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_09', 'NPC_DUS_68', 'K3', '{"seed","fige"}', 'Le fond du canyon est l''endroit où le régulateur d''ombre de Duskarn fige la réalité ; le bois craque parce qu''il est pressé par le cœur d''ombre', NULL, '*(il pose la pièce)* « Un bois qui craque, c''est un bois vivant. Le reste, c''est le fond qui serre. Si tu veux le fond du fond, c''est la Rivière. Elle fige, elle aussi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_68_10', 'NPC_DUS_68', 'KX', '{"*(hors sujet)*"}', '*(il frappe)* « Toc. Pas le bon son. Le canyon l''a déjà pris. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_01', 'NPC_DUS_69', 'K0', '{"ecaille","prix"}', 'Ses écailles de lézard — prix, protection', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_02', 'NPC_DUS_69', 'K0', '{"falaise","lieu"}', 'Son étal aux Falaises du Crépuscule', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_03', 'NPC_DUS_69', 'K0', '{"usage","armure"}', 'À quoi servent les écailles — armures légères Imp', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_04', 'NPC_DUS_69', 'K1', '{"ecaille","brule"}', 'L''écaille qui « brûle » — souvenir d''une flamme éteinte', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_05', 'NPC_DUS_69', 'K1', '{"lezard","origine"}', 'D''où viennent ses lézards — « des falaises qui ne voient pas le jour »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_06', 'NPC_DUS_69', 'K1', '{"sentinelle","lien"}', 'Ce qu''il vend à la Sentinelle des Falaises', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_07', 'NPC_DUS_69', 'K2', '{"brulure","ville"}', 'La brûlure suit le rythme crépusculaire de la ville', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_08', 'NPC_DUS_69', 'K2', '{"falaise","feu"}', 'Les falaises gardent « le souvenir du feu » d''un soleil que Duskarn n''a jamais eu', '`QUEST:DUS_ECAILLE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_09', 'NPC_DUS_69', 'K3', '{"seed","feu"}', 'Les écailles brûlent parce qu''elles sont chargées par le régulateur d''ombre de Duskarn, qui retient le feu (l''aube) pour maintenir le crépuscule éternel', NULL, '*(il range l''écaille)* « Une écaille qui brûle, c''est une écaille. Le feu qu''elle garde, demande-le à la Rivière. Elle l''a noyé depuis longtemps. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_69_10', 'NPC_DUS_69', 'KX', '{"*(hors sujet)*"}', '*(il polis)* « Brillante. Froide. Brûlante. Toujours les trois. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_01', 'NPC_DUS_70', 'K0', '{"porte","filtre"}', 'Ce qu''il contrôle à l''entrée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_02', 'NPC_DUS_70', 'K0', '{"poste","lieu"}', 'Son poste à la Porte de Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_03', 'NPC_DUS_70', 'K0', '{"protocole","acces"}', 'Le protocole d''entrée et de sortie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_04', 'NPC_DUS_70', 'K1', '{"entree","silence"}', 'Les entrées « sans bruit » — des visiteurs sans pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_05', 'NPC_DUS_70', 'K1', '{"ombre","porte"}', 'Pourquoi l''ombre de la porte ne bouge pas pour eux', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_06', 'NPC_DUS_70', 'K1', '{"douanier","lien"}', 'Ce qu''il transmet au Douanier des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_07', 'NPC_DUS_70', 'K2', '{"silence","forme"}', 'Les visiteurs silencieux n''ont pas d''ombre de pas au sol', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_08', 'NPC_DUS_70', 'K2', '{"porte","seuil"}', 'Le seuil de la Porte « efface » le bruit et l''ombre de certains venus de l''extérieur', '`QUEST:DUS_PORTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_09', 'NPC_DUS_70', 'K3', '{"seed","seuil"}', 'La Porte est un capteur du régulateur d''ombre de Duskarn ; elle efface le bruit et l''ombre de tout ce qui entre au rythme du cœur d''ombre', NULL, '*(il verrouille)* « Une porte, c''est une porte. Ceux qui n''ont pas de bruit, c''est mon problème. Si tu veux le seuil du monde, c''est la Rivière. Elle efface tout, elle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_70_10', 'NPC_DUS_70', 'KX', '{"*(hors sujet)*"}', '*(il compte)* « Un. Deux. Trois. Toi, zéro. Comme les autres. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_01', 'NPC_DUS_71', 'K0', '{"registre","visiteur"}', 'Ce qu''il inscrit au registre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_02', 'NPC_DUS_71', 'K0', '{"porte","lieu"}', 'Son bureau à la Porte de Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_03', 'NPC_DUS_71', 'K0', '{"taxe","usage"}', 'Les taxes et formalités d''entrée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_04', 'NPC_DUS_71', 'K1', '{"nom","ombre"}', 'Les « noms d''ombre » — une écriture inconnue', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_05', 'NPC_DUS_71', 'K1', '{"disparition","livre"}', 'Pourquoi les noms disparaissent au matin', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_06', 'NPC_DUS_71', 'K1', '{"gardien","lien"}', 'Ce qu''il reçoit du Gardien de la Porte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_07', 'NPC_DUS_71', 'K2', '{"ecriture","source"}', 'L''écriture vient de la même main que les édits d''ombre de `NPC_DUS_58`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_08', 'NPC_DUS_71', 'K2', '{"registre","vivant"}', 'Le registre « s''écrit seul » la nuit pour les visiteurs que nul n''a vus', '`QUEST:DUS_REGISTRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_09', 'NPC_DUS_71', 'K3', '{"seed","registre"}', 'Le registre est alimenté par le régulateur d''ombre de Duskarn ; les noms d''ombre sont les visiteurs que le cœur d''ombre fait entrer sans bruit', NULL, '*(il referme le livre)* « Un douanier compte. L''ombre compte aussi, mais pas pour lui. Si tu veux le vrai registre, c''est la Rivière. Elle inscrit, elle noie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_71_10', 'NPC_DUS_71', 'KX', '{"*(hors sujet)*"}', '*(il recompte)* « Cent. Cent un. Cent un et demi ? Non. Cent. Encore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_01', 'NPC_DUS_72', 'K0', '{"rempart","surveillance"}', 'Ce qu''il observe des murs du canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_02', 'NPC_DUS_72', 'K0', '{"poste","lieu"}', 'Son poste sur les Remparts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_03', 'NPC_DUS_72', 'K0', '{"rapport","usage"}', 'Ses rapports de guet aux remparts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_04', 'NPC_DUS_72', 'K1', '{"ombre","danse"}', 'Les ombres qui dansent — sans corps, au rythme d''une musique', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_05', 'NPC_DUS_72', 'K1', '{"musique","seule"}', 'Pourquoi lui seul entend la musique — « elle vient du mur »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_06', 'NPC_DUS_72', 'K1', '{"sonneur","lien"}', 'Ce qu''il dit au Sonneur d''Alarme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_07', 'NPC_DUS_72', 'K2', '{"danse","rythme"}', 'La danse suit le même rythme que le cristal qui bat de `NPC_DUS_51`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_08', 'NPC_DUS_72', 'K2', '{"mur","vivant"}', 'Le mur « respire » à certaines heures — la paroi ondule sans vent', '`QUEST:DUS_REMPART_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_09', 'NPC_DUS_72', 'K3', '{"seed","danse"}', 'Les ombres dansantes sont l''effet de surface du régulateur d''ombre de Duskarn ; leur rythme est celui du cœur d''ombre qui fait « battre » toute la ville', NULL, '*(il fixe le mur)* « Des ombres qui dansent, c''est le vent dans le canyon. Si tu veux la musique vraie, c''est la Rivière. Elle chante sous l''eau, elle ne danse pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_72_10', 'NPC_DUS_72', 'KX', '{"*(hors sujet)*"}', '*(il fredonne)* « Tra-la-la… non, pas celui-là. L''autre. Toujours l''autre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_01', 'NPC_DUS_73', 'K0', '{"carillon","alarme"}', 'Ce qu''il sonne et quand', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_02', 'NPC_DUS_73', 'K0', '{"rempart","lieu"}', 'Son poste sur les Remparts du canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_03', 'NPC_DUS_73', 'K0', '{"protocole","usage"}', 'Le protocole d''alerte d''Éclipse', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_04', 'NPC_DUS_73', 'K1', '{"carillon","seul"}', 'Le carillon qui sonne sans lui — des éclipses invisibles', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_05', 'NPC_DUS_73', 'K1', '{"corde","ombre"}', 'Pourquoi la corde bouge seule — « une ombre tire »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_06', 'NPC_DUS_73', 'K1', '{"guetteur","lien"}', 'Ce qu''il entend du Guetteur des Remparts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_07', 'NPC_DUS_73', 'K2', '{"eclipse","ville"}', 'Les éclipses invisibles coïncident avec les battements du cristal de `NPC_DUS_51`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_08', 'NPC_DUS_73', 'K2', '{"corde","source"}', 'La corde est « tirée » depuis le même point que les édits d''ombre de `NPC_DUS_58`', '`QUEST:DUS_CARILLON_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_09', 'NPC_DUS_73', 'K3', '{"seed","eclipse"}', 'Le carillon réagit au régulateur d''ombre de Duskarn ; les éclipses invisibles sont les pulsations du cœur d''ombre qui rythment la ville', NULL, '*(il lâche la corde)* « Un carillon qui sonne seul, c''est un carillon hanté. Rien de plus. Si tu veux l''éclipse vraie, c''est la Rivière. Elle l''avale, elle ne la sonne pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_73_10', 'NPC_DUS_73', 'KX', '{"*(hors sujet)*"}', '*(il frémit)* « Ding. Non, pas moi. Ding, encore. Tais-toi, corde. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_01', 'NPC_DUS_74', 'K0', '{"monture","location"}', 'Ses montures à louer — prix, durée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_02', 'NPC_DUS_74', 'K0', '{"porte","lieu"}', 'Son écurie à la Porte de Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_03', 'NPC_DUS_74', 'K0', '{"type","usage"}', 'Ses lézards de corniche et chauves-souris de selle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_04', 'NPC_DUS_74', 'K1', '{"monture","hennit"}', 'La monture qui hennit dans le noir — sans bouche', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_05', 'NPC_DUS_74', 'K1', '{"ombre","parole"}', 'Pourquoi l''animal « parle à l''ombre » — il ne le fait qu''aux heures creuses', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_06', 'NPC_DUS_74', 'K1', '{"marechal","lien"}', 'Ce qu''il confie au Maréchal des Ailes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_07', 'NPC_DUS_74', 'K2', '{"hennissement","ville"}', 'Le hennissement suit le rythme de la ville, pas l''animal', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_08', 'NPC_DUS_74', 'K2', '{"monture","source"}', 'Ses montures viennent d''un cheptel « marqué » par l''ombre du fond du canyon', '`QUEST:DUS_MONTURE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_09', 'NPC_DUS_74', 'K3', '{"seed","marque"}', 'Les montures sont marquées par le régulateur d''ombre de Duskarn ; leur hennissement nocturne est le cœur d''ombre qui appelle les créatures de la ville', NULL, '*(il caresse l''encolure)* « Une bête qui hennit dans le noir, c''est une bête seule. Le reste, c''est l''ombre qui l''appelle. Si tu veux l''appel vrai, c''est la Rivière. Elle ne hennit pas, elle roule. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_74_10', 'NPC_DUS_74', 'KX', '{"*(hors sujet)*"}', '*(il siffle)* « Viens, bête. Pas toi, l''autre. Toujours l''autre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_01', 'NPC_DUS_75', 'K0', '{"montures","ferrage"}', 'Le ferrage des chauves-souris — tarifs, soins, locations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_02', 'NPC_DUS_75', 'K0', '{"ecurie","bêtes"}', 'Les bêtes de la Porte — races, endurance dans le canyon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_03', 'NPC_DUS_75', 'K0', '{"prix","location"}', 'Les prix de location des montures pour la Route Aérienne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_04', 'NPC_DUS_75', 'K1', '{"fer","creux"}', 'Un fer qui sonne creux — une monture revenue sans que le voyageur soit allé loin', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_05', 'NPC_DUS_75', 'K1', '{"bêtes","fatigue"}', 'Certaines montures reviennent épuisées sans avoir été montées — comme si elles avaient porté un poids invisible', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_06', 'NPC_DUS_75', 'K1', '{"route","trafic"}', 'Ce qu''il voit passer à la Porte — marchands, espions, visiteurs sans ombre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_07', 'NPC_DUS_75', 'K2', '{"ombres","montures"}', 'Les montures louées à des voyageurs « sans ombre » reviennent le fer ébréché d''un métal qu''il ne connaît pas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_08', 'NPC_DUS_75', 'K2', '{"pacte","spriggan"}', 'Le Pacte des Ailes se paie aussi en bêtes — des montures Spriggan que le Marchand `NPC_DUS_91` lui confie', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_09', 'NPC_DUS_75', 'K3', '{"ténèbres","régulation"}', 'Duskarn n''est pas qu''une ville : les montures qui reviennent seules ont emprunté un chemin qui n''existe pas sur la carte — la régulation des ténèbres du serveur passe par ici', NULL, '*(il tape le fer contre la pierre, un son creux)* « Les bêtes courent, c''est tout. Le canyon les appelle. Ne cherche pas le chemin qu''elles prennent. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_75_10', 'NPC_DUS_75', 'KX', '{"*(hors sujet)*"}', '*(il flatte une aile)* « Une monture qui te fait confiance ne te pose jamais de question. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_01', 'NPC_DUS_76', 'K0', '{"ronde","porte"}', 'La ronde de nuit — horaires, itinéraire, consignes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_02', 'NPC_DUS_76', 'K0', '{"alarme","sécurité"}', 'Comment donner l''alerte à la Porte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_03', 'NPC_DUS_76', 'K0', '{"entrées","visiteurs"}', 'Ce qu''il laisse passer — et ce qu''il refoule', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_04', 'NPC_DUS_76', 'K1', '{"pas","seuls"}', 'Les pas qui claquent seuls la nuit — pas de silhouette, juste le bruit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_05', 'NPC_DUS_76', 'K1', '{"ombres","danse"}', 'Les ombres qui dansent sur les remparts alors qu''il n''y a pas de torche', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_06', 'NPC_DUS_76', 'K1', '{"patrouille","anomalie"}', 'Les nuits où la ronde compte un pas de trop à son retour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_07', 'NPC_DUS_76', 'K2', '{"canyon","observer"}', 'Une ombre dans le canyon qui ne bouge pas comme les autres — le fil **🌑 L''Ombre Qui Observe**', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_08', 'NPC_DUS_76', 'K2', '{"pacte","spriggan"}', 'Ce qu''il voit ramper hors du Pacte des Ailes la nuit — des formes que le Conseil ignore', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_09', 'NPC_DUS_76', 'K3', '{"ténèbres","nœud"}', 'La nuit de Duskarn n''est pas un cycle : c''est l''état de base du serveur ici — le nœud de régulation des ténèbres qui empêche la lumière de revenir', NULL, '*(il serre sa lance)* « La nuit, on veille. On ne pose pas ce genre de question. Repasse demain, quand tu verras comme il fait noir. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_76_10', 'NPC_DUS_76', 'KX', '{"*(hors sujet)*"}', '*(il compte à voix basse)* « Un, deux… non. Trois. Il y en a un de trop. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_01', 'NPC_DUS_77', 'K0', '{"ronde","jour"}', 'La ronde de jour — consignes, relève', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_02', 'NPC_DUS_77', 'K0', '{"registre","entrées"}', 'Ce qu''il inscrit au registre de la Porte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_03', 'NPC_DUS_77', 'K0', '{"routine","sécurité"}', 'Les contrôles de routine aux visiteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_04', 'NPC_DUS_77', 'K1', '{"ombre","maître"}', 'L''ombre sans maître qu''il a vue une fois — il l''a qualifiée de « reflet »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_05', 'NPC_DUS_77', 'K1', '{"nuit","récit"}', 'Ce que raconte le Veilleur de Nuit — il trouve ça absurde', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_06', 'NPC_DUS_77', 'K1', '{"porte","trafic"}', 'Le trafic qu''il voit passer « officiellement »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_07', 'NPC_DUS_77', 'K2', '{"canyon","observer"}', 'L''ombre du canyon ne bouge pas comme les autres — il l''a remarqué sans vouloir y croire', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_08', 'NPC_DUS_77', 'K2', '{"ténèbres","noeud"}', 'Le crépuscule perpétuel n''est pas un décor — la ville est maintenue dans le noir par quelque chose', '`QUEST:QST_DUS_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_09', 'NPC_DUS_77', 'K3', '{"ténèbres","régulation"}', 'Duskarn est un nœud de régulation des ténèbres du serveur ; le « jour » n''y reviendra jamais tant que le nœud tourne', NULL, '*(il hausse les épaules)* « Le jour ? Y''en a pas, ici. C''est comme ça. Va demander au Seigneur si ça t''inquiète. Moi j''fais ma ronde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_77_10', 'NPC_DUS_77', 'KX', '{"*(hors sujet)*"}', '*(il bâille)* « La prochaine relève, c''est dans trois pas. Si tu comptes. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_01', 'NPC_DUS_78', 'K0', '{"plis","tarifs"}', 'Les tarifs de livraison en ville', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_02', 'NPC_DUS_78', 'K0', '{"itinéraire","quartiers"}', 'Les quartiers qu''il dessert — du Bazar au Balcon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_03', 'NPC_DUS_78', 'K0', '{"délais","urgence"}', 'Les délais selon l''urgence du pli', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_04', 'NPC_DUS_78', 'K1', '{"pli","chuchote"}', 'Le pli qui chuchote — une intention qu''il sent sans lire', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_05', 'NPC_DUS_78', 'K1', '{"balcon","ordres"}', 'Les plis du Balcon — toujours scellés, jamais ouverts', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_06', 'NPC_DUS_78', 'K1', '{"trafic","route"}', 'Ce qu''il croise sur la Route Aérienne en livrant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_07', 'NPC_DUS_78', 'K2', '{"ombre","balcon"}', 'L''Ombre du Balcon `NPC_DUS_88` lui confie des plis qui ne portent aucun sceau — et qui ne sont pas au registre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_08', 'NPC_DUS_78', 'K2', '{"pacte","spriggan"}', 'Certains plis viennent du Pacte des Ailes — du renseignement qui change de main à chaque porte', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_09', 'NPC_DUS_78', 'K3', '{"ténèbres","régulation"}', 'Les plis qu''il porte ne sont pas que des messages : ils alimentent le nœud de régulation des ténèbres, qui redistribue l''ombre de la ville selon le serveur', NULL, '*(il serre son sac)* « Je livre. Je lis pas. Si le papier parle, c''est pas mon affaire. T''as un pli à envoyer, oui ou non ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_78_10', 'NPC_DUS_78', 'KX', '{"*(hors sujet)*"}', '*(il regarde l''heure invisible)* « J''ai une tournée. On cause plus tard. Peut-être. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_01', 'NPC_DUS_79', 'K0', '{"visite","tour"}', 'La visite guidée de Duskarn — itinéraire, durée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_02', 'NPC_DUS_79', 'K0', '{"quartiers","carte"}', 'Les sous-lieux à voir — Bazar, Temple, Rivière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_03', 'NPC_DUS_79', 'K0', '{"conseils","sécurité"}', 'Conseils pour survivre sans aube', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_04', 'NPC_DUS_79', 'K1', '{"visiteur","sans ombre"}', 'Les visiteurs sans ombre — ils ne demandent jamais de guide', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_05', 'NPC_DUS_79', 'K1', '{"porte","accueil"}', 'Ce qu''il dit aux nouveaux arrivants', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_06', 'NPC_DUS_79', 'K1', '{"canyon","rumeurs"}', 'Les rumeurs qu''il glane à la Porte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_07', 'NPC_DUS_79', 'K2', '{"ombre","observer"}', 'L''ombre du canyon qui ne bouge pas — il la montre du doigt aux curieux', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_08', 'NPC_DUS_79', 'K2', '{"pacte","spriggan"}', 'Pourquoi tant de visiteurs « sans ombre » viennent du Pacte des Ailes', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_09', 'NPC_DUS_79', 'K3', '{"ténèbres","régulation"}', 'Duskarn est maintenue dans le crépuscule par le nœud de régulation des ténèbres ; les visiteurs sans ombre sont ceux qui savent déjà le chemin du nœud', NULL, '*(il sourit, immobile)* « La ville est belle sans aube, non ? Ne cherche pas pourquoi elle n''a pas de soleil. Certains paysages, mieux vaut les admirer que les comprendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_79_10', 'NPC_DUS_79', 'KX', '{"*(hors sujet)*"}', '*(il indique une rue)* « Par là. Ou par l''autre côté. Ici, les deux mènent au même endroit. Enfin, presque. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_01', 'NPC_DUS_80', 'K0', '{"autel","rez"}', 'La résurrection à l''Autel — coût, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_02', 'NPC_DUS_80', 'K0', '{"voile","culte"}', 'Le culte du Voile — prières, bénédictions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_03', 'NPC_DUS_80', 'K0', '{"benediction","buffs"}', 'Les bénédictions de départ pour les chasseurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_04', 'NPC_DUS_80', 'K1', '{"chant","guérison"}', 'Son chant guérit « trop bien » — des rez sans séquelle', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_05', 'NPC_DUS_80', 'K1', '{"temple","silence"}', 'Ce que le Voile cache au-dessus de la ville', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_06', 'NPC_DUS_80', 'K1', '{"fidèles","rites"}', 'Les fidèles qu''il voit revenir sans cicatrice', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_07', 'NPC_DUS_80', 'K2', '{"ténèbres","noeud"}', 'Le Voile est alimenté par le nœud de régulation des ténèbres — la ville guérit parce que le nœud redistribue la vie', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_08', 'NPC_DUS_80', 'K2', '{"ordre","seigneur"}', 'Pourquoi le Seigneur veut que le Voile ne se lève jamais', '`QUEST:QST_DUS_COEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_09', 'NPC_DUS_80', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Voile est la preuve que le nœud vit, et que la ville n''est qu''une interface', NULL, '*(il se signe d''ombre)* « Le Voile protège. Qui prie ne questionne pas. Le soleil est une distraction des vivants. Ici, on repose. Prie, et tais-toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_80_10', 'NPC_DUS_80', 'KX', '{"*(hors sujet)*"}', '*(il étend les mains)* « La paix de l''encre soit sur toi. Ou sur quelqu''un d''autre. Peu importe, tant qu''il y en a. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_01', 'NPC_DUS_81', 'K0', '{"silence","prière"}', 'La prière du silence — rituel, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_02', 'NPC_DUS_81', 'K0', '{"autel","rez"}', 'La résurrection à l''Autel — ce qu''elle accompagne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_03', 'NPC_DUS_81', 'K0', '{"culte","voile"}', 'Le culte des Ténèbres — différence avec le Voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_04', 'NPC_DUS_81', 'K1', '{"silence","dure"}', 'Le silence qui dure « trop longtemps » — elle l''appelle l''écoute du nœud', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_05', 'NPC_DUS_81', 'K1', '{"temple","bas"}', 'Ce qu''elle sent venir du dessous de l''Autel', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_06', 'NPC_DUS_81', 'K1', '{"fidèles","silence"}', 'Les fidèles qui sortent changés du silence', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_07', 'NPC_DUS_81', 'K2', '{"ténèbres","noeud"}', 'Le silence vient du nœud de régulation des ténèbres sous la ville — il « écoute » le serveur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_08', 'NPC_DUS_81', 'K2', '{"ordre","seigneur"}', 'Pourquoi le Seigneur maintient le silence sur la ville', '`QUEST:QST_DUS_COEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_09', 'NPC_DUS_81', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le silence est le bruit que fait le nœud quand il traite les ombres de la ville', NULL, '*(elle pose un doigt sur ses lèvres)* « Chut. Écoute. … Non, tu n''entends rien, parce que c''est là que ça compte. Ne demande pas ce qui se tait. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_81_10', 'NPC_DUS_81', 'KX', '{"*(hors sujet)*"}', '*(un long silence)* « … Tu as entendu ? Non. Moi non plus. C''est bien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_01', 'NPC_DUS_82', 'K0', '{"temple","tâches"}', 'Ses tâches à l''Autel — balayage, rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_02', 'NPC_DUS_82', 'K0', '{"autel","rez"}', 'Ce qu''il voit pendant les résurrections', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_03', 'NPC_DUS_82', 'K0', '{"apprentissage","voile"}', 'Ce qu''on lui apprend du Voile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_04', 'NPC_DUS_82', 'K1', '{"pas","murs"}', 'Les pas qui résonnent dans les murs — sans corps', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_05', 'NPC_DUS_82', 'K1', '{"prêtresse","interdit"}', 'Ce que la Prêtresse lui défend d''écouter', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_06', 'NPC_DUS_82', 'K1', '{"novice","doutes"}', 'Ses doutes sur le silence du Temple', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_07', 'NPC_DUS_82', 'K2', '{"ténèbres","noeud"}', 'Le nœud de régulation des ténèbres sous l''Autel — les pas viennent de là', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_08', 'NPC_DUS_82', 'K2', '{"pacte","spriggan"}', 'Ce qu''il a surpris du Pacte des Ailes en écoutant les murs', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_09', 'NPC_DUS_82', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; les pas dans les murs sont les requêtes que le nœud traite en continu', NULL, '*(il se bouche les oreilles)* « J''ai rien entendu. Rien du tout. La Prêtresse a dit de pas écouter, alors j''écoute pas. T''as entendu, toi ? Moi non. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_82_10', 'NPC_DUS_82', 'KX', '{"*(hors sujet)*"}', '*(il balaie nerveusement)* « Le sol est froid. Trop froid pour une ville qui vit. Mais chut, j''ai dit ça à personne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_01', 'NPC_DUS_83', 'K0', '{"rite","encre"}', 'Le rite d''encre — sceau, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_02', 'NPC_DUS_83', 'K0', '{"autel","rez"}', 'La résurrection qu''elle accompagne du sceau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_03', 'NPC_DUS_83', 'K0', '{"vestale","tâches"}', 'Ses tâches à l''Autel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_04', 'NPC_DUS_83', 'K1', '{"rite","assourdit"}', 'Le rite qui assourdit la salle — le silence tombe d''un coup', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_05', 'NPC_DUS_83', 'K1', '{"encre","parle"}', 'L''encre qu''elle dit « parler » au nœud', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_06', 'NPC_DUS_83', 'K1', '{"acolyte","murs"}', 'Ce qu''elle reproche à l''Acolyte d''écouter', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_07', 'NPC_DUS_83', 'K2', '{"ténèbres","noeud"}', 'L''encre est une interface avec le nœud de régulation des ténèbres — chaque sceau est une requête', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_08', 'NPC_DUS_83', 'K2', '{"ordre","seigneur"}', 'Pourquoi le Seigneur veut que les rites restent scellés', '`QUEST:QST_DUS_COEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_09', 'NPC_DUS_83', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; l''encre que nous versons est le protocole par lequel la ville écrit ses ombres dans le système', NULL, '*(elle referme le flacon d''encre)* « L''encre ne se discute pas. Elle marque, et le monde obéit. Si tu veux un sceau, paie. Si tu veux comprendre, demande au Seigneur — moi je scelle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_83_10', 'NPC_DUS_83', 'KX', '{"*(hors sujet)*"}', '*(elle trace un signe)* « Un mort de plus, un sceau de plus. La ville n''oublie jamais. Enfin, presque. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_01', 'NPC_DUS_84', 'K0', '{"resurrection","noire"}', 'Ses services de résurrection interdite — prix, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_02', 'NPC_DUS_84', 'K0', '{"caverne","hurleurs"}', 'La Caverne des Hurleurs — ce qu''on y entends', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_03', 'NPC_DUS_84', 'K0', '{"morts","rumeurs"}', 'Ce que les morts révèlent en revenant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_04', 'NPC_DUS_84', 'K1', '{"morts","dénoncent"}', 'Les morts qui dénoncent leurs tueurs — il enregistre les noms', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_05', 'NPC_DUS_84', 'K1', '{"poison","parle"}', 'Le poison qui force la vérité — lien avec l''Alchimiste `NPC_DUS_35`', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_06', 'NPC_DUS_84', 'K1', '{"marché","cadavres"}', 'Ce qu''il vend des morts — noms, dettes, secrets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_07', 'NPC_DUS_84', 'K2', '{"ténèbres","noeud"}', 'La Caverne est un puits branché sur le nœud de régulation des ténèbres — les morts y parlent parce que le nœud les lit', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_08', 'NPC_DUS_84', 'K2', '{"pacte","spriggan"}', 'Ce que les morts révèlent du Pacte des Ailes', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_09', 'NPC_DUS_84', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; la nécromancie n''est que l''exploitation d''un port mort du nœud, et les morts qui dénoncent sont les logs corrompus du système', NULL, '*(un mort se met à crier)* « Tais-toi. … Tu vois ? Ils parlent trop. Moi, je ne dis rien de plus. Achète un nom, ou sors. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_84_10', 'NPC_DUS_84', 'KX', '{"*(hors sujet)*"}', '*(il caresse un crâne)* « La mort, ici, c''est juste une autre monnaie. La tienne vaut quoi, déjà ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_01', 'NPC_DUS_85', 'K0', '{"fosse","enterrement"}', 'L''enterrement à Duskarn — rite, emplacement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_02', 'NPC_DUS_85', 'K0', '{"autel","morts"}', 'Ce qu''il reçoit de l''Autel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_03', 'NPC_DUS_85', 'K0', '{"sceau","encre"}', 'Le sceau de la Vestale avant la terre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_04', 'NPC_DUS_85', 'K1', '{"corps","frémit"}', 'Les corps qui frémissent dans la terre — pas morts tout à fait', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_05', 'NPC_DUS_85', 'K1', '{"nécromancien","crie"}', 'Ce qu''il sait des morts du Nécromancien qui crient', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_06', 'NPC_DUS_85', 'K1', '{"noms","mémoire"}', 'Les noms qu''il se promet de ne pas oublier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_07', 'NPC_DUS_85', 'K2', '{"ténèbres","noeud"}', 'Les frémissements viennent du nœud de régulation des ténèbres qui retient les âmes dans la ville', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_08', 'NPC_DUS_85', 'K2', '{"rivière","absorbe"}', 'La Rivière d''Encre absorbe les souvenirs des morts — lien avec le fil **🫧 La Rivière Qui Absorbe**', '`QUEST:QST_DUS_RIVIERE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_09', 'NPC_DUS_85', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; les morts qui frémissent sont les données que le nœud n''a pas fini d''effacer', NULL, '*(il tasse la terre)* « La terre garde. Le nœud efface. Entre les deux, on frémit. Creuse, et ne pose pas cette question à un mort. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_85_10', 'NPC_DUS_85', 'KX', '{"*(hors sujet)*"}', '*(il tapote le sol)* « Sept pieds de noir, et ils dorment. Enfin, certains. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_01', 'NPC_DUS_86', 'K0', '{"balcon","sécurité"}', 'La sécurité du Balcon — consignes, accès', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_02', 'NPC_DUS_86', 'K0', '{"seigneur","garde"}', 'La protection du Seigneur — protocole', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_03', 'NPC_DUS_86', 'K0', '{"accès","filtrage"}', 'Qui entre au Balcon Intérieur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_04', 'NPC_DUS_86', 'K1', '{"seigneur","faux"}', '« Le Seigneur n''est pas toujours le Seigneur » — elle l''a vu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_05', 'NPC_DUS_86', 'K1', '{"ordres","sceau"}', 'Les ordres sans le bon sceau qu''elle exécute quand même', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_06', 'NPC_DUS_86', 'K1', '{"ombre","balcon"}', 'L''ombre du Seigneur qui ne tombe pas juste certaines nuits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_07', 'NPC_DUS_86', 'K2', '{"ténèbres","noeud"}', 'Le Seigneur est un hologramme maintenu par le nœud de régulation des ténèbres — la ville est gouvernée par une interface', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_08', 'NPC_DUS_86', 'K2', '{"ordre","pacte"}', 'Ce que le faux Seigneur ordonne au nom du Pacte des Ailes', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_09', 'NPC_DUS_86', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Seigneur n''est qu''une projection du nœud, et elle protège une ombre qui n''a jamais eu de corps', NULL, '*(elle se met au garde-à-vous)* « Je protège le Seigneur. Qui est sur le Balcon est le Seigneur. Tu doutes, tu te tais. Le Conseil n''a pas à répondre aux visiteurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_86_10', 'NPC_DUS_86', 'KX', '{"*(hors sujet)*"}', '*(elle fixe le mur)* « Une garde qui réfléchit, c''est une garde qui faillit. Je ne réfléchis pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_01', 'NPC_DUS_87', 'K0', '{"trésor","gestion"}', 'La gestion du trésor de Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_02', 'NPC_DUS_87', 'K0', '{"impôts","taxes"}', 'Les taxes du Conseil — à qui elles vont', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_03', 'NPC_DUS_87', 'K0', '{"coffres","balcon"}', 'Les coffres du Balcon — accès, scellés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_04', 'NPC_DUS_87', 'K1', '{"or","chante"}', 'L''or qui tintinnabule — un son entre les pièces', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_05', 'NPC_DUS_87', 'K1', '{"trésor","infini"}', 'Le trésor qui ne diminue jamais — ses registres mentent-ils ?', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_06', 'NPC_DUS_87', 'K1', '{"dette","skell"}', 'La dette du Balcon envers Skell `NPC_DUS_06`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_07', 'NPC_DUS_87', 'K2', '{"ténèbres","noeud"}', 'L''or est généré par le nœud de régulation des ténèbres — la ville n''a pas d''économie réelle, seulement un script', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_08', 'NPC_DUS_87', 'K2', '{"ordre","seigneur"}', 'Pourquoi le Seigneur dépense sans jamais épuiser le trésor', '`QUEST:QST_DUS_COEUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_09', 'NPC_DUS_87', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le trésor est une interface de paiement du nœud, alimentée en continu par le système — l''or n''a jamais été réel', NULL, '*(il referme le registre)* « Les comptes sont les comptes. Si l''or chante, c''est une monnaie joyeuse. Ne demande pas d''où vient la joie. Le Conseil paie, tu reçois. Point. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_87_10', 'NPC_DUS_87', 'KX', '{"*(hors sujet)*"}', '*(il fait tinter deux pièces)* « Une pour toi, une pour le nœud. Enfin, pour le trésor. Même chose, ici. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_01', 'NPC_DUS_88', 'K0', '{"balcon","espion"}', 'Son rôle d''agent du Chancelier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_02', 'NPC_DUS_88', 'K0', '{"alliés","surveillance"}', 'Ce qu''elle surveille au Balcon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_03', 'NPC_DUS_88', 'K0', '{"plis","coursier"}', 'Les plis qu''elle confie au Coursier `NPC_DUS_78`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_04', 'NPC_DUS_88', 'K1', '{"visage","alliés"}', 'Le vrai visage des alliés du Pacte — elle l''a vu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_05', 'NPC_DUS_88', 'K1', '{"pli","sans sceau"}', 'Les plis sans sceau qu''elle fait circuler', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_06', 'NPC_DUS_88', 'K1', '{"coursier","chuchote"}', 'Ce que le Coursier dit des plis qui chuchotent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_07', 'NPC_DUS_88', 'K2', '{"ténèbres","noeud"}', 'Le Pacte est piloté depuis le nœud de régulation des ténèbres — les plis sans sceau sont des ordres du nœud', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_08', 'NPC_DUS_88', 'K2', '{"pacte","spriggan"}', 'Ce que le vrai visage des alliés révèle du Pacte Imp–Spriggan', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_09', 'NPC_DUS_88', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Chancelier lui-même n''est qu''un opérateur du nœud, et le Pacte des Ailes est l''exportation de l''ombre vers les autres cités', NULL, '*(elle recule dans l''ombre)* « Tu vois mon visage ? Non. C''est mieux ainsi. Pose tes questions au Chancelier. Moi, je ne suis que l''ombre qu''on oublie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_88_10', 'NPC_DUS_88', 'KX', '{"*(hors sujet)*"}', '*(elle n''est déjà plus là)* « … (silence) … Tu parlais à qui, déjà ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_01', 'NPC_DUS_89', 'K0', '{"mémorial","liste"}', 'La liste des morts — lecture, ajout', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_02', 'NPC_DUS_89', 'K0', '{"bazar","pierre"}', 'La pierre du Mémorial au Bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_03', 'NPC_DUS_89', 'K0', '{"deuil","rites"}', 'Les rites de deuil à Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_04', 'NPC_DUS_89', 'K1', '{"nom","résonne"}', 'Le nom qui résonne sur la pierre — un mort qui refuse l''oubli', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_05', 'NPC_DUS_89', 'K1', '{"ombre","absents"}', 'Les visiteurs sans ombre jamais inscrits, même morts', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_06', 'NPC_DUS_89', 'K1', '{"fosses","liens"}', 'Ce qu''il sait des frémissements du Fossoyeur `NPC_DUS_85`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_07', 'NPC_DUS_89', 'K2', '{"ténèbres","noeud"}', 'La liste est synchronisée avec le nœud de régulation des ténèbres — les absents sans ombre n''existent pas dans le système', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_08', 'NPC_DUS_89', 'K2', '{"rivière","absorbe"}', 'La Rivière d''Encre absorbe les souvenirs — lien **🫧 La Rivière Qui Absorbe**', '`QUEST:QST_DUS_RIVIERE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_09', 'NPC_DUS_89', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Mémorial est la table des données mortes, et les noms qui résonnent sont les entrées que le nœud n''a pas fini d''effacer', NULL, '*(il pose la main sur la pierre)* « Les morts sont inscrits. Point. Ce qui résonne, c''est le vent dans la pierre. Ne va pas dire aux familles que leur mort n''est qu''une ligne de code. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_89_10', 'NPC_DUS_89', 'KX', '{"*(hors sujet)*"}', '*(il effleure un nom)* « Celui-là, il revient chaque semaine. Comme s''il avait oublié d''être mort. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_01', 'NPC_DUS_90', 'K0', '{"refuge","canyon"}', 'Sa cache dans le Canyon des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_02', 'NPC_DUS_90', 'K0', '{"voulg","fuite"}', 'Pourquoi il a fui Voulg — la mine, la peur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_03', 'NPC_DUS_90', 'K0', '{"salamander","race"}', 'Ce qu''il reste de sa loyauté envers les Salamander', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_04', 'NPC_DUS_90', 'K1', '{"malakor","fuit"}', 'Malakor `NPC_VOU_03` a fui Voulg — le contremaître a vu la salle sous le cratère', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_05', 'NPC_DUS_90', 'K1', '{"mine","vidés"}', 'Les mineurs « vidés » de leur force dans la mine de soufre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_06', 'NPC_DUS_90', 'K1', '{"cardinal","salle"}', 'La salle du Cardinal sous le cratère de Voulg', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_07', 'NPC_DUS_90', 'K2', '{"malakor","pourquoi"}', 'Pourquoi Malakor a vraiment fui : son nom était sur la liste des prochains à « vider »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_08', 'NPC_DUS_90', 'K2', '{"pacte","spriggan"}', 'Comment le Marchand Spriggan `NPC_DUS_91` le protège du Courtier Voulg `NPC_DUS_92`', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_09', 'NPC_DUS_90', 'K3', '{"ténèbres","régulation"}', 'Voulg et Duskarn sont deux nœuds du même serveur : la « salle du Cardinal » de Voulg est une vanne de régulation, et Duskarn en est une autre — Malakor a fui un nœud pour atterrir sous un autre', NULL, '*(il regarde par-dessus son épaule)* « Malakor ? Connais pas. Un contremaître qui a craqué, c''est tout. La mine, ça use. T''as rien à foutre ici, va interroger les morts ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_90_10', 'NPC_DUS_90', 'KX', '{"*(hors sujet)*"}', '*(il touche sa tempe)* « Parfois j''me sens vide, moi aussi. Comme si on avait pompé quelque chose. Mais c''est le canyon. L''air. Ouais. L''air. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_01', 'NPC_DUS_91', 'K0', '{"poisons","tarifs"}', 'Ses poisons — effets, prix, contrepoisons', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_02', 'NPC_DUS_91', 'K0', '{"info","troc"}', 'Le troc poison contre information', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_03', 'NPC_DUS_91', 'K0', '{"spriggan","visite"}', 'Pourquoi un Spriggan au Bazar des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_04', 'NPC_DUS_91', 'K1', '{"pacte","ailes"}', 'Le Pacte des Ailes — ce qu''il apporte aux Imp', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_05', 'NPC_DUS_91', 'K1', '{"refuge","cache"}', 'Le Réfugié Salamander `NPC_DUS_90` qu''il protège', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_06', 'NPC_DUS_91', 'K1', '{"reseau","fitch"}', 'Son réseau avec Fitch/Wisp (Alne/Swilvane)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_07', 'NPC_DUS_91', 'K2', '{"malakor","voulg"}', 'Ce qu''il sait de Malakor `NPC_VOU_03` qui a fui Voulg — un secret que le Réfugié lui a vendu', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_08', 'NPC_DUS_91', 'K2', '{"pacte","spriggan"}', 'Pourquoi le Pacte veut les secrets de Voulg et de Duskarn à la fois', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_09', 'NPC_DUS_91', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Pacte des Ailes n''est que l''export de l''ombre vers les autres cités, et Voulg en est la vanne de feu jumelle', NULL, '*(il range un flacon)* « Un secret ? Ça se paie. En poison, ou en autre chose. Celui-là, même toi tu peux pas l''acheter. Certaines ombres sont trop grandes pour le Bazar. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_91_10', 'NPC_DUS_91', 'KX', '{"*(hors sujet)*"}', '*(il cligne)* « Un Spriggan qui te dit la vérité, c''est un Spriggan qui t''a déjà vendu. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_01', 'NPC_DUS_92', 'K0', '{"commerce","voulg"}', 'Le commerce Voulg–Duskarn — flux, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_02', 'NPC_DUS_92', 'K0', '{"diplomatie","poste"}', 'Son poste de diplomate à Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_03', 'NPC_DUS_92', 'K0', '{"accords","traités"}', 'Les accords qu''il négocie au Bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_04', 'NPC_DUS_92', 'K1', '{"malakor","connaît"}', 'Il connaît Malakor `NPC_VOU_03` — le contremaître de la mine de Voulg', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_05', 'NPC_DUS_92', 'K1', '{"mine","cratère"}', 'La mine de soufre et ce qu''on y cache sous le cratère', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_06', 'NPC_DUS_92', 'K1', '{"refuge","surveille"}', 'Le Réfugié Salamander `NPC_DUS_90` qu''il surveille sans le dire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_07', 'NPC_DUS_92', 'K2', '{"malakor","pourquoi"}', 'Pourquoi Malakor a fui : la salle du Cardinal et la liste des mineurs à « vider »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_08', 'NPC_DUS_92', 'K2', '{"cardinal","vous"}', 'Ce qu''il craint pour lui-même s''il parle trop de Voulg', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_09', 'NPC_DUS_92', 'K3', '{"ténèbres","régulation"}', 'Voulg et Duskarn sont deux vannes du même serveur ; Malakor a fui la vanne de feu pour atterrir sous la vanne d''ombre, et le Courtier sait que le nœud finit toujours par rappeler ses fuites', NULL, '*(il sourit, gêné)* « Malakor ? Un excellent contremaître. Dommage qu''il ait… pris sa retraite si vite. La mine, tu sais, ça use les hommes. Ne va pas chercher la salle dont personne ne parle. Moi, je traite du fer et du cristal. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_92_10', 'NPC_DUS_92', 'KX', '{"*(hors sujet)*"}', '*(il lisse sa cape)* « Un diplomate qui dit tout perd sa ville. Un diplomate qui dit rien perd sa tête. Devine lequel je suis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_01', 'NPC_DUS_93', 'K0', '{"gemmes","tarifs"}', 'Ses gemmes de Granzam — prix, qualité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_02', 'NPC_DUS_93', 'K0', '{"cristal","échange"}', 'L''échange cristal violet contre gemmes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_03', 'NPC_DUS_93', 'K0', '{"trafic","bazar"}', 'Son commerce au Bazar des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_04', 'NPC_DUS_93', 'K1', '{"granzam","bomil"}', 'Le lien avec Bomil `NPC_ALN_93` (Granzam→Alne)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_05', 'NPC_DUS_93', 'K1', '{"cristal","bat"}', 'Le cristal violet qui « bat » — il dit que c''est le cœur de la ville', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_06', 'NPC_DUS_93', 'K1', '{"illka","reseau"}', 'Le réseau Illka `NPC_GAT_33` qui transite ses gemmes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_07', 'NPC_DUS_93', 'K2', '{"ténèbres","noeud"}', 'Le cristal violet est le capteur du nœud de régulation des ténèbres — il bat au rythme du serveur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_08', 'NPC_DUS_93', 'K2', '{"pacte","spriggan"}', 'Ce que le Pacte des Ailes achète de son cristal', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_09', 'NPC_DUS_93', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le cristal violet est sa ligne de vie visible, et chaque gemme de Granzam qu''il reçoit est comparée à une autre forme d''énergie du serveur', NULL, '*(il serre son cristal)* « Bat ? Quel bat. C''est une pierre. Une belle pierre. Tu veux la toucher ? Cinq Yrds. Le cœur de la ville, mon œil — c''est du marketing de Gnome, ça. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_93_10', 'NPC_DUS_93', 'KX', '{"*(hors sujet)*"}', '*(il sort trois gemmes)* « Celle-là vient d''Alne, celle-là de Granzam, et celle-là… disons qu''elle vient d''ailleurs. T''achètes laquelle ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_01', 'NPC_DUS_94', 'K0', '{"commerce","neutre"}', 'Son négoce « neutre » au Bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_02', 'NPC_DUS_94', 'K0', '{"achats","revente"}', 'Ce qu''il achète et revend', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_03', 'NPC_DUS_94', 'K0', '{"clientele","races"}', 'Sa clientèle des 9 races', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_04', 'NPC_DUS_94', 'K1', '{"pacte","couverture"}', 'Le Pacte Imp–Spriggan qui couvre son négoce', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_05', 'NPC_DUS_94', 'K1', '{"ombre","balcon"}', 'L''Ombre du Balcon `NPC_DUS_88` dont il est la couverture', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_06', 'NPC_DUS_94', 'K1', '{"spriggan","flux"}', 'Les flux du Marchand Spriggan `NPC_DUS_91` qu''il blanchit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_07', 'NPC_DUS_94', 'K2', '{"ténèbres","noeud"}', 'Le Pacte sert à exporter l''ombre du nœud de régulation des ténèbres vers les autres cités', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_08', 'NPC_DUS_94', 'K2', '{"pacte","spriggan"}', 'Ce que le réseau fait vraiment de l''ombre achetée', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_09', 'NPC_DUS_94', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le Courtier ne vend pas des objets, il vend l''ombre que le nœud produit en surplus, et le Pacte en est la canalisation', NULL, '*(il sourit, neutre)* « Je ne vends que du neutre, mon ami. Des objets, des Yrds, rien de plus. L''ombre ? Elle appartient à la ville. Moi, je compte juste. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_94_10', 'NPC_DUS_94', 'KX', '{"*(hors sujet)*"}', '*(il pèse une pièce)* « Tout se revend. Même toi, si quelqu''un met le bon prix. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_01', 'NPC_DUS_95', 'K0', '{"chœurs","chants"}', 'Ses chants de la cour — répertoire, occasions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_02', 'NPC_DUS_95', 'K0', '{"quêtes","mémoire"}', 'Les quêtes de mémoire qu''il distribue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_03', 'NPC_DUS_95', 'K0', '{"nid","guet"}', 'Le Nid de Guet où il veille', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_04', 'NPC_DUS_95', 'K1', '{"seigneur","faux"}', 'Ce qu''il a vu au Balcon — le Seigneur n''est pas toujours lui-même', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_05', 'NPC_DUS_95', 'K1', '{"chancelier","gouverne"}', 'Le Chancelier des Ténèbres `NPC_DUS_08` qui gouverne l''ombre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_06', 'NPC_DUS_95', 'K1', '{"ombre","cache"}', 'Ce que l''ombre cache derrière le trône', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_07', 'NPC_DUS_95', 'K2', '{"ténèbres","noeud"}', 'L''ombre du trône vient du nœud de régulation des ténèbres — le Seigneur en est la projection', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_08', 'NPC_DUS_95', 'K2', '{"pacte","spriggan"}', 'Ce que ses chants révèlent du Pacte des Ailes', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_09', 'NPC_DUS_95', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; le chant du Vétéran est la seule archive vivante du nœud, et il sait que la ville n''a jamais eu de soleil', NULL, '*(il entame un air)* « Écoute la chanson, pas les paroles. Le Seigneur est une note, le nœud en est une autre. Si tu veux la partition, demande à la Mémoire. Moi, je chante, et je me tais sur le reste. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_95_10', 'NPC_DUS_95', 'KX', '{"*(hors sujet)*"}', '*(il fredonne)* « Autrefois le Balcon brillait… non, mentir, ça non plus. Il était sombre. Comme maintenant. Comme toujours. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_01', 'NPC_DUS_96', 'K0', '{"entraînement","ténèbres"}', 'Son entraînement des ténèbres — programmes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_02', 'NPC_DUS_96', 'K0', '{"skills","ombre"}', 'Les skills d''ombre qu''il enseigne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_03', 'NPC_DUS_96', 'K0', '{"canyon","cursus"}', 'Le cursus au Canyon des Ombres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_04', 'NPC_DUS_96', 'K1', '{"élève","voyait"}', 'L''élève qui voyait dans le noir — et n''est jamais revenu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_05', 'NPC_DUS_96', 'K1', '{"caverne","hurleurs"}', 'La Caverne des Hurleurs où l''élève a disparu', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_06', 'NPC_DUS_96', 'K1', '{"novices","peur"}', 'Ce qu''il apprend à ses novices sur la peur du noir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_07', 'NPC_DUS_96', 'K2', '{"ténèbres","noeud"}', 'Voir dans le noir, c''est capter le nœud de régulation des ténèbres — l''élève a vu le nœud lui-même', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_08', 'NPC_DUS_96', 'K2', '{"pacte","spriggan"}', 'Ce que l''entraînement révèle du Pacte des Ailes', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_09', 'NPC_DUS_96', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; l''entraînement des Imp n''est que la calibration de leurs sens sur le nœud, et l''élève perdu a été « lu » par le système', NULL, '*(il serre sa lame)* « On ne regarde pas dans le noir. On y voit. C''est différent, et c''est ce qui tue. Entraîne-toi, et ne cherche pas ce que mon élève a vu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_96_10', 'NPC_DUS_96', 'KX', '{"*(hors sujet)*"}', '*(il désigne le canyon)* « Trois pas, deux coups, un souffle. C''est tout ce que le noir t''offre. Le reste, c''est le nœud qui décide. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_01', 'NPC_DUS_97', 'K0', '{"prêts","souvenirs"}', 'Ses prêts contre souvenirs — taux, garanties', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_02', 'NPC_DUS_97', 'K0', '{"échoppe","cachée"}', 'Son échoppe cachée du Bazar', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_03', 'NPC_DUS_97', 'K0', '{"clientele","dettes"}', 'Sa clientèle d''endettés d''âme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_04', 'NPC_DUS_97', 'K1', '{"client","oublié"}', 'Le client qui a tout oublié après un prêt', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_05', 'NPC_DUS_97', 'K1', '{"skell","âme"}', 'Le Prêteur Sombre Skell `NPC_DUS_06` et ses parts d''âme', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_06', 'NPC_DUS_97', 'K1', '{"dette","huissier"}', 'Ce que l''Huissier `NPC_DUS_28` enregistre des dettes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_07', 'NPC_DUS_97', 'K2', '{"ténèbres","noeud"}', 'Les souvenirs prêtés vont au nœud de régulation des ténèbres — la ville se nourrit des âmes endettées', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_08', 'NPC_DUS_97', 'K2', '{"pacte","spriggan"}', 'Ce que le Pacte des Ailes fait des âmes collectées', '`QUEST:QST_DUS_AILES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_09', 'NPC_DUS_97', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; les dettes d''âme sont une interface de paiement vers le nœud, et « Le Prêteur Sans Visage » n''est que le nom que le système donne à la collecte', NULL, '*(il effleure ton front)* « Un souvenir contre mille Yrds. Tu oublies un peu, tu vis un peu. Le Prêteur Sans Visage ? Je ne prête pas de visage, mon ami. Je prête de l''oubli. Et l''oubli, ici, appartient à la ville. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_97_10', 'NPC_DUS_97', 'KX', '{"*(hors sujet)*"}', '*(il range un flacon de mémoire)* « Celui-là se souvient d''une aube. Dommage, à Duskarn, ça ne vaut rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_01', 'NPC_DUS_98', 'K0', '{"oracle","rivière"}', 'Ses prophéties par l''encre de la Rivière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_02', 'NPC_DUS_98', 'K0', '{"quêtes","prophétie"}', 'Les quêtes de prophétie qu''elle donne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_03', 'NPC_DUS_98', 'K0', '{"encre","lecture"}', 'Comment elle lit l''avenir dans l''encre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_04', 'NPC_DUS_98', 'K1', '{"source","trois"}', 'Embra `NPC_GAT_70` et Isilde `NPC_ALN_98` — trois oracles, une source', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_05', 'NPC_DUS_98', 'K1', '{"rivière","absorbe"}', 'La Rivière qui absorbe lumière et souvenirs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_06', 'NPC_DUS_98', 'K1', '{"pêcheur","aveugle"}', 'Ce que le Pêcheur Aveugle `NPC_DUS_25` ramène du fond', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_07', 'NPC_DUS_98', 'K2', '{"ténèbres","noeud"}', 'La Rivière est le collecteur du nœud de régulation des ténèbres — elle rend au système ce qu''elle absorbe', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_08', 'NPC_DUS_98', 'K2', '{"ombre","observer"}', 'Ce que la Rivière révèle de l''ombre du canyon', '`QUEST:QST_DUS_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_09', 'NPC_DUS_98', 'K3', '{"ténèbres","régulation"}', 'Duskarn est le nœud de régulation des ténèbres du serveur ; l''Oracle n''est qu''un terminal de la Rivière, et les trois oracles des cités lisent tous le même flux du nœud', NULL, '*(l''encre se fige)* « Tu vois ton reflet ? Non. La Rivière ne te renvoie rien. C''est bien ainsi. Pose ta question à l''eau, pas à moi. Je ne suis que ce qu''elle dicte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_98_10', 'NPC_DUS_98', 'KX', '{"*(hors sujet)*"}', '*(elle trace un signe dans l''encre)* « Demain, l''ombre sera plus lourde. Ou c''était hier. Ici, le temps se confond. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_01', 'NPC_DUS_99', 'K0', '{"mémoire","fondation"}', 'Son souvenir de la fondation de Duskarn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_02', 'NPC_DUS_99', 'K0', '{"sagesse","conseil"}', 'Ses conseils aux visiteurs du Balcon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_03', 'NPC_DUS_99', 'K0', '{"quêtes","mémoire"}', 'Les quêtes de mémoire qu''elle distribue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_04', 'NPC_DUS_99', 'K1', '{"canyon","avant"}', 'Le canyon avant le crépuscule perpétuel', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_05', 'NPC_DUS_99', 'K1', '{"seigneur","hologramme"}', 'Le Seigneur Imp `NPC_DUS_07` n''est qu''une projection', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_06', 'NPC_DUS_99', 'K1', '{"oracle","source"}', 'La source commune à l''Oracle `NPC_DUS_98` et aux autres oracles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_07', 'NPC_DUS_99', 'K2', '{"ténèbres","noeud"}', 'Duskarn est un nœud de régulation des ténèbres du serveur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_08', 'NPC_DUS_99', 'K2', '{"crépuscule","conçu"}', 'Le crépuscule perpétuel est maintenu par conception, pas par hasard', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_09', 'NPC_DUS_99', 'K2', '{"rivière","absorbe"}', 'La Rivière d''Encre absorbe les souvenirs pour les rendre au nœud', '`QUEST:QST_DUS_RIVIERE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_10', 'NPC_DUS_99', 'K3', '{"ténèbres","régulation"}', 'Le nœud de régulation des ténèbres est le cœur d''ombre de Duskarn — la ville entière est une interface du serveur, et son « absence d''aube » en est la preuve par conception', NULL, '*(elle ferme les yeux)* « La fondation ? Elle n''a pas eu lieu comme on le dit. Duskarn n''a pas été bâtie. Elle a été allumée dans le noir, et le noir n''est jamais reparti. Ne demande pas qui a allumé. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_11', 'NPC_DUS_99', 'K3', '{"méta","seed"}', 'Duskarn est le nœud de régulation des ténèbres le plus ancien du serveur — sa « Mémoire » est celle du Cardinal lui-même, une archive vivante que le système consulte pour équilibrer les ombres', NULL, '*(le Balcon s''assombrit une seconde)* « Je me souviens de la fondation. C''est tout ce que je dirai. Le reste appartient au nœud, et au Cardinal qui l''écoute. Va, et oublie que tu as posé cette question. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_DUS_99_12', 'NPC_DUS_99', 'KX', '{"*(tout le reste)*"}', '*(un long silence de pierre)* « Certaines mémoires ne se racontent pas. Elles se vivent. Reviens quand le canyon te parlera. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_01', 'NPC_FRE_00', 'K0', '{"ombre","colline"}', 'Une ombre de bête apparaît la nuit sur la Colline aux Souvenirs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_02', 'NPC_FRE_00', 'K0', '{"disparition","approche"}', 'Dès qu''on s''approche, l''ombre disparaît — elle ne fuit pas, elle cesse d''exister', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_03', 'NPC_FRE_00', 'K0', '{"sensation","regard"}', 'Ceux qui l''ont vue décrivent une sensation de poids, comme si quelque chose les regardait de l''intérieur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_04', 'NPC_FRE_00', 'K1', '{"traces","absence"}', 'Elle ne laisse aucune trace — pas d''empreinte, pas de brindille cassée, pas de souffle dans l''herbe', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_05', 'NPC_FRE_00', 'K1', '{"memoire","premier"}', 'Elle est liée au tout premier familier — elle se souvient d''un temps où les familiers n''avaient pas de registre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_06', 'NPC_FRE_00', 'K1', '{"analyse","erreur"}', '`!analyze` retourne une erreur — comme si elle n''était pas dans la base de données des PNJ', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_07', 'NPC_FRE_00', 'K2', '{"leo","oeil"}', 'Léo peut la sentir arriver — son œil mort « voit » l''ombre avant qu''elle n''apparaisse', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_08', 'NPC_FRE_00', 'K2', '{"respawn","impossibilite"}', 'Elle ne peut pas être tuée — elle n''a pas de hitbox, pas de HP, pas d''existence dans le moteur de combat', '`QUEST:QST_CAI_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_09', 'NPC_FRE_00', 'K2', '{"vibration","language"}', 'Quand elle veut communiquer, elle fait vibrer le sol — chaque vibration est une lettre, un mot, une phrase incomplète', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_10', 'NPC_FRE_00', 'K3', '{"premier","familier","cardinal"}', 'Elle EST le premier familier — enfin, ce qu''il en reste. Le Cardinal ne peut pas supprimer son entité parce qu''elle précède le système de registre. Elle existe dans une couche du code que le Cardinal ne peut pas modifier sans casser le système de domptage entier', NULL, '*(l''ombre se fige, puis s''évanouit lentement ; le sol vibre une fois, très basse fréquence)* « ……… »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_11', 'NPC_FRE_00', 'K3', '{"logs","fondateurs"}', 'Les logs fondateurs du serveur contiennent son contrat d''adoption — le premier `TAME_SUCCESS` jamais enregistré. Si le fichier est corrompu, l''ombre disparaît pour toujours', NULL, '*(l''ombre grandit, couvre tout le champ de vision, puis se rétracte en un point)* « … Avant le code. Avant les règles. Avant le Cardinal. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_00_12', 'NPC_FRE_00', 'KX', '{"*(tout le reste)*"}', '*(l''ombre s''éloigne et se dissout dans la nuit)*', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_01', 'NPC_FRE_01', 'K0', '{"domptage","base"}', 'Les bases du domptage Cait Sith — lien d''âme, nourriture, confiance', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_02', 'NPC_FRE_01', 'K0', '{"menagerie","enclos"}', 'La Ménagerie Royale — ses enclos, ses bêtes, ses règles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_03', 'NPC_FRE_01', 'K0', '{"alicia","eleve"}', 'Comment il a dressé Alicia Rue — « La reine était une gamine qui savait pas lacer ses sandales »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_04', 'NPC_FRE_01', 'K1', '{"oeil","evil god"}', 'Son œil — perdu sur un Evil God, mais pas dans un combat : dans un domptage', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_05', 'NPC_FRE_01', 'K1', '{"ombre","senti"}', 'Il sent une ombre rôder la nuit — quelque chose d''avant le système', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_06', 'NPC_FRE_01', 'K1', '{"porte","menagerie"}', 'Une porte verrouillée dans la Ménagerie — il a ordre de ne pas s''en approcher', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_07', 'NPC_FRE_01', 'K2', '{"evil god","verite"}', 'L''Evil God qu''il a dompté n''était pas un vrai Evil God — c''était un verrou du Cardinal qu''il a forcé', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_08', 'NPC_FRE_01', 'K2', '{"wyverne","parle"}', 'Une wyverne de la Ménagerie lui a parlé — pas des cris, des phrases complètes', '`QUEST:QST_CAI_WYVERNE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_09', 'NPC_FRE_01', 'K2', '{"oeil","visions"}', 'Avec son œil mort, il voit des fils lumineux qui relient les bêtes au ciel — des lignes de code', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_10', 'NPC_FRE_01', 'K3', '{"porte","verrouillee","contenu"}', 'La porte verrouillée de la Ménagerie mène à un enclos vide que le Cardinal garde ouvert dans ses logs mais fermé dans le monde réel — quelque chose est piégé entre les deux', NULL, '*(il touche son œil mort)* « Cette porte ? Y a rien derrière. Le Cardinal l''a assez répété. Et le Cardinal ne ment pas, pas vrai ? Alors va voir ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_11', 'NPC_FRE_01', 'K3', '{"premier","familier","ombre"}', 'L''Ombre qu''il sent est le premier familier dompté dans ALO — un vestige que le système ne peut pas effacer parce qu''il n''a pas été créé par le système', NULL, '*(son œil mort se révulse légèrement)* « Je vois des choses que je devrais pas voir. Ça ne veut pas dire que je dois les raconter. L''ombre… elle a le droit de se taire. Et moi aussi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_01_12', 'NPC_FRE_01', 'KX', '{"*(hors sujet)*"}', '« Va parler à Alicia. Elle, elle aime causer. Moi, j''ai un enclos à nettoyer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_01', 'NPC_FRE_02', 'K0', '{"pieges","foret"}', 'Les pièges qu''il pose en forêt — types, emplacements, rendement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_02', 'NPC_FRE_02', 'K0', '{"alliance","couverture"}', 'Il est sous couvert de l''alliance Sylph-Freelia — personne ne le fouille', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_03', 'NPC_FRE_02', 'K0', '{"especes","protegees"}', 'Les espèces protégées qu''il braconne — prix, demande, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_04', 'NPC_FRE_02', 'K1', '{"nox","blanchiment"}', 'Nox blanchit son argent via la vente de cosmétiques', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_05', 'NPC_FRE_02', 'K1', '{"cage","chose"}', 'Il a capturé une bête qui n''existe dans aucun bestiaire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_06', 'NPC_FRE_02', 'K1', '{"receleur","reseau"}', 'Le Receleur écoule son trafic vers le Marché aux Os', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_07', 'NPC_FRE_02', 'K2', '{"bête","description"}', 'La bête dans la cage a des yeux qui brillent la nuit et ne mange pas — elle le regarde sans cligner', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_08', 'NPC_FRE_02', 'K2', '{"piege","emplacement"}', 'Le piège qui a capturé la bête était posé à un endroit qui n''existe sur aucune carte', '`QUEST:QST_CAI_BETE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_09', 'NPC_FRE_02', 'K3', '{"bête","cardinal","anomalie"}', 'La bête qu''il a capturée est une anomalie de spawn — le Cardinal l''a créée par erreur lors d''une mise à jour et ne peut pas la supprimer sans planter la zone. Zephyr la retient prisonnière sans le savoir', NULL, '*(il regarde par-dessus son épaule)* « Je sais pas ce que c''est. Je veux pas le savoir. J''aurais dû la relâcher le premier soir. Maintenant c''est trop tard. Elle me regarde, et elle sait des choses. Fiche-moi la paix. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_02_10', 'NPC_FRE_02', 'KX', '{"*(hors sujet)*"}', '« J''ai rien à vendre. Va voir Nox. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_01', 'NPC_FRE_03', 'K0', '{"pneuma","fleur"}', 'La fleur de Pneuma — culture, propriétés, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_02', 'NPC_FRE_03', 'K0', '{"resurrection","familier"}', 'Le rituel de résurrection des familiers — coût, conditions, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_03', 'NPC_FRE_03', 'K0', '{"colline","souvenirs"}', 'La Colline aux Souvenirs — son histoire, son importance pour les Cait Sith', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_04', 'NPC_FRE_03', 'K1', '{"echec","familier"}', 'Un familier qu''elle n''a pas pu sauver — le lien d''âme persistait au-delà de la mort', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_05', 'NPC_FRE_03', 'K1', '{"maitre","decede"}', 'Le maître de ce familier est mort en jeu — mais l''âme du familier continue d''apparaître dans les logs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_06', 'NPC_FRE_03', 'K1', '{"fleur","mensonge"}', 'Parfois la fleur de Pneuma s''ouvre sur une tombe vide — comme si le familier n''était jamais mort', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_07', 'NPC_FRE_03', 'K2', '{"nuit","murmures"}', 'La nuit, elle entend des murmures sur la colline — des voix de familiers qui n''ont plus de maître', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_08', 'NPC_FRE_03', 'K2', '{"ombre","premier"}', 'Une nuit, elle a vu une ombre de bête marcher entre les tombes — sans laisser d''empreinte', '`QUEST:QST_CAI_PNEUMA_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_09', 'NPC_FRE_03', 'K3', '{"ames","colline","retention"}', 'La Colline aux Souvenirs retient les âmes des familiers — le Cardinal les utilise comme données de calcul pour optimiser le système de domptage. Les fleurs de Pneuma ne sont que des capteurs biologiques qui mesurent la rétention d''âme', NULL, '*(elle cueille une fleur et la regarde faner dans sa main)* « Les souvenirs des bêtes sont sacrés. Je ne les livre pas au vent. Ni au système. Ni à toi. La colline garde ce qu''elle garde, et elle a ses raisons. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_03_10', 'NPC_FRE_03', 'KX', '{"*(hors sujet)*"}', '« Va voir l''Archiviste si tu veux des noms. Moi, je parle aux fleurs. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_01', 'NPC_FRE_04', 'K0', '{"armures","monture"}', 'Les armures pour montures — griffacier, cuir, plaques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_02', 'NPC_FRE_04', 'K0', '{"selles","personnalisation"}', 'Ses selles sur mesure — prix, matériaux, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_03', 'NPC_FRE_04', 'K0', '{"marche","etalage"}', 'Le Marché aux Crocs — son étal, ses horaires, ses fournisseurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_04', 'NPC_FRE_04', 'K1', '{"selle","parle"}', 'Une selle en cuir de worg qu''il a fabriquée — elle bouge toute seule', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_05', 'NPC_FRE_04', 'K1', '{"chasseur","mort"}', 'Le chasseur qui l''a commandée est mort avant de la récupérer', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_06', 'NPC_FRE_04', 'K1', '{"matin","etalage"}', 'Chaque matin, la selle est sur une monture différente dans l''écurie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_07', 'NPC_FRE_04', 'K2', '{"cuir","worg"}', 'Le cuir de worg utilisé pour la selle vient d''un worg qui portait un collier — il ne l''a pas enlevé', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_08', 'NPC_FRE_04', 'K2', '{"collier","runes"}', 'Le collier du worg était gravé de runes qu''il n''a pas reconnues — il les a recouvertes de griffacier', '`QUEST:QST_CAI_SELLE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_09', 'NPC_FRE_04', 'K3', '{"selle","ame","runes"}', 'Les runes sous le griffacier sont des runes d''ancrage d''âme — le worg n''était pas une bête normale, c''était un familier lié au premier dompteur. La selle a hérité de cette âme et cherche son cavalier', NULL, '*(il jette un chiffon sur la selle)* « La selle est pas à vendre. Elle est à personne. Elle était à un mort qui reviendra pas, et elle le sait. On touche pas à ce qui pleure encore. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_04_10', 'NPC_FRE_04', 'KX', '{"*(hors sujet)*"}', '« J''ai du travail. Va voir Brok si tu veux de la viande. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_01', 'NPC_FRE_05', 'K0', '{"transmogrification","service"}', 'La transmogrification — changer l''apparence d''un familier, prix, options', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_02', 'NPC_FRE_05', 'K0', '{"illusions","cosmétiques"}', 'Les illusions cosmétiques pour joueurs — ailes, auras, effets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_03', 'NPC_FRE_05', 'K0', '{"tavernier","etage"}', 'Son atelier au premier étage du Chat Botté — accès, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_04', 'NPC_FRE_05', 'K1', '{"zephyr","argent"}', 'Il blanchit l''argent de Zephyr via ses ventes d''illusions', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_05', 'NPC_FRE_05', 'K1', '{"comptes","fictifs"}', 'Il utilise une douzaine de prête-noms pour reverser l''argent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_06', 'NPC_FRE_05', 'K1', '{"illusions","vivantes"}', 'Certaines illusions qu''il vend « prennent vie » la nuit — elles bougent dans l''inventaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_07', 'NPC_FRE_05', 'K2', '{"memoire","parfaite"}', 'Il a une mémoire parfaite — il se souvient de chaque transaction, de chaque client', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_08', 'NPC_FRE_05', 'K2', '{"courtier","couverture"}', 'Le Courtier Inter-Racial `FRE_94` est son prête-nom principal — il ne le sait pas', '`QUEST:QST_CAI_BLANCHI_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_09', 'NPC_FRE_05', 'K3', '{"illusions","cardinal","donnees"}', 'Les illusions qui prennent vie sont des artefacts du Cardinal — des paquets de données cosmétiques qui s''animent quand le serveur est en sous-charge. Nox les vend sans savoir qu''il distribue des morceaux de code vivant', NULL, '*(son sourire s''efface une fraction de seconde)* « Les illusions vivantes ? C''est un bug. Un petit rien. Rien de grave. Si t''as des questions sur la qualité de mon boulot, va voir ailleurs. Moi, je vends du beau. Pas du vrai. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_05_10', 'NPC_FRE_05', 'KX', '{"*(hors sujet)*"}', '« J''ai des clients. Reviens quand t''auras décidé la couleur de ton familier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_01', 'NPC_FRE_06', 'K0', '{"tour","observation"}', 'La Tour d''Observation — son rôle, sa hauteur, sa portée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_02', 'NPC_FRE_06', 'K0', '{"cartes","territoires"}', 'Les cartes qu''elle dessine — zones de chasse, routes, frontières', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_03', 'NPC_FRE_06', 'K0', '{"eclaireuse","travail"}', 'Son travail d''éclaireuse — routine, dangers, récompenses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_04', 'NPC_FRE_06', 'K1', '{"zephyr","braconnage"}', 'Elle sait que Zephyr est un braconnier — elle le surveille de la tour', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_05', 'NPC_FRE_06', 'K1', '{"routes","mouvantes"}', 'Certaines routes sur ses cartes apparaissent et disparaissent d''un jour à l''autre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_06', 'NPC_FRE_06', 'K1', '{"lumieres","nulles"}', 'Elle voit des lumières la nuit dans des zones sans aucun campement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_07', 'NPC_FRE_06', 'K2', '{"silhouettes","debout"}', 'Des silhouettes de bêtes qui marchent sur deux pattes — elle les a vues trois fois', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_08', 'NPC_FRE_06', 'K2', '{"journal","cache"}', 'Elle tient un journal sous une latte de la tour — elle n''a rien dit à personne', '`QUEST:QST_CAI_CARTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_09', 'NPC_FRE_06', 'K3', '{"routes","cardinal","instances"}', 'Les routes mouvantes sont des instances de chasse que le Cardinal déplace pour optimiser la charge du serveur. Ce qu''elle voit, c''est la grille du monde en train de se reconfigurer — les coutures visibles d''un monde qui n''est pas solide', NULL, '*(elle pose la main sur son carnet)* « Je suis payée pour regarder. Pas pour interpréter. Si les routes bougent, c''est que le vent les a effacées. Si des bêtes marchent debout, c''est que la lumière joue des tours. Pose pas de questions sur ce que je vois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_06_10', 'NPC_FRE_06', 'KX', '{"*(hors sujet)*"}', '« J''ai des relevés à faire. Parle au Scout si t''as besoin d''un guide. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_01', 'NPC_FRE_07', 'K0', '{"viande","vente"}', 'Sa boucherie — types de viande, prix, provenance', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_02', 'NPC_FRE_07', 'K0', '{"marche","etal"}', 'Le Marché aux Crocs — son emplacement, ses horaires, ses concurrents', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_03', 'NPC_FRE_07', 'K0', '{"achat","loot"}', 'Il achète les dépouilles de monstres — prix selon rareté et état', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_04', 'NPC_FRE_07', 'K1', '{"viande","repousse"}', 'Certains morceaux repoussent sur l''os après découpe — il les vend plus cher', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_05', 'NPC_FRE_07', 'K1', '{"gibier","regarde"}', 'Un gigot de worg l''a regardé — il avait un œil encore vivant', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_06', 'NPC_FRE_07', 'K1', '{"sommes","nuit"}', 'Il dort mal — des bruits viennent de sa réserve la nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_02', 'NPC_FRE_07', 'K2', '{"viande","provenance"}', 'La viande qui repousse vient d''un lot de carcasses livrées par un chasseur masqué', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_08', 'NPC_FRE_07', 'K2', '{"chasseur","masque"}', 'Le chasseur portait un masque en os — il n''a jamais vu son visage, et les livraisons continuent', '`QUEST:QST_CAI_VLANDE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_09', 'NPC_FRE_07', 'K3', '{"viande","reseau","cardinal"}', 'La viande régénérative est un résidu de données — des cellules de mobs que le Cardinal n''a pas correctement désallouées. Elles continuent de se matérialiser sur les os parce que leur modèle est encore chargé en mémoire', NULL, '*(il essuie son couteau lentement)* « La viande elle est fraîche, elle est bonne, elle se vend. C''est tout ce que t''as besoin de savoir. Et si t''es pas content, va acheter chez le Boucher, je le connais pas, il existe pas. Alors arrête de poser des questions sur ma réserve. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_07_10', 'NPC_FRE_07', 'KX', '{"*(hors sujet)*"}', '*(il coupe un morceau de viande)* « T''achètes ou tu dégages. J''ai pas de temps pour les curieux. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_01', 'NPC_FRE_08', 'K0', '{"reine","trone"}', 'La reine des Cait Sith — son rôle, son histoire, ses responsabilités', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_02', 'NPC_FRE_08', 'K0', '{"alliance","sylph"}', 'L''alliance Sylph-Freelia — officiellement un pacte de défense mutuelle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_03', 'NPC_FRE_08', 'K0', '{"freelia","capitale"}', 'Freelia — la capitale Cait Sith, sa culture, ses coutumes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_04', 'NPC_FRE_08', 'K1', '{"leo","dresseur"}', 'Léo l''a dressée quand elle était enfant — elle lui doit tout', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_05', 'NPC_FRE_08', 'K1', '{"accord","parallele"}', 'L''alliance cache un accord parallèle — trois œufs par mois aux Sylphes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_06', 'NPC_FRE_08', 'K1', '{"sakuya","chantage"}', 'Sakuya sait pour l''accord — elle utilise cette information pour contrôler Alicia', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_07', 'NPC_FRE_08', 'K2', '{"nya_ran","espionne"}', 'Nya-Ran `NPC_SWI_07` est l''espionne qui l''a piégée — elle a recueilli les preuves', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_08', 'NPC_FRE_08', 'K2', '{"zephyr","trafic"}', 'Elle tolère le trafic de Zephyr parce que Sakuya le lui a ordonné', '`QUEST:QST_CAI_ALLIANCE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_09', 'NPC_FRE_08', 'K2', '{"nuit","visiteurs"}', 'La nuit, des visiteurs entrent dans la tour par une porte dérobée — elle ne sait pas qui', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_10', 'NPC_FRE_08', 'K3', '{"accord","premier","familier"}', 'Alicia sait que l''Ombre du Premier existe parce que c''est Léo qui le lui a dit, mais elle a aussi vu les logs du Cardinal qui mentionnent un « contrat d''adoption zéro » — un familier qui n''a jamais été enregistré parce qu''il a précédé le système. Elle cherche un moyen d''utiliser cette information pour négocier avec Sakuya', NULL, '*(elle caresse le bras de son trône)* « Il y a des choses qu''une reine sait et qu''elle ne dit pas. Des choses qui appartiennent au passé de ce monde. Je ne suis pas la gardienne de ces secrets — je suis la gardienne de mon peuple. Si les deux entrent en conflit, je choisis mon peuple. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_11', 'NPC_FRE_08', 'K3', '{"porte","betes","enclos"}', 'La Porte des Bêtes dans la Ménagerie mène à un enclos qu''elle-même n''a pas le droit d''ouvrir. Le Cardinal lui a envoyé un message — un parchemin vide avec un sceau qui n''existe pas — lui ordonnant de maintenir l''enclos fermé « jusqu''à nouvel ordre »', NULL, '*(ses yeux s''étrécissent, ses oreilles s''aplatissent)* « Cet enclos n''existe pas. Il n''a jamais existé. Et si tu poses encore la question, je te ferai conduire à la frontière Sylph par la Garde Fauve. Nous sommes clairs ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_08_12', 'NPC_FRE_08', 'KX', '{"*(hors sujet)*"}', '*(elle tourne le dos et fait signe à un garde)* « Mon temps est compté. Si le Commandant Griffe a une réponse pour la prochaine audience, qu''il vienne. Toi, tu es congédié. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_01', 'NPC_FRE_09', 'K0', '{"garde","fauve"}', 'La Garde Fauve — organisation, effectifs, missions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_02', 'NPC_FRE_09', 'K0', '{"tour","securite"}', 'La sécurité de la Tour du Trône Fauve — accès, tours, protocoles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_03', 'NPC_FRE_09', 'K0', '{"commandant","role"}', 'Le rôle du Commandant de la Garde — ses responsabilités, son autorité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_04', 'NPC_FRE_09', 'K1', '{"envoyé","sylph","nuit"}', 'Il a vu l''Envoyé Sylph entrer par la porte dérobée de la tour la nuit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_05', 'NPC_FRE_09', 'K1', '{"zephyr","remparts"}', 'Il a croisé Zephyr aux remparts — le braconnier avait du sang frais sous les ongles', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_06', 'NPC_FRE_09', 'K1', '{"comptes","ecarts"}', 'Les livres de compte du Trône présentent des écarts mensuels — il les a notés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_07', 'NPC_FRE_09', 'K2', '{"silhouette","menagerie"}', 'Il a vu une silhouette entrer dans la Ménagerie une nuit, suivie d''une ombre de bête', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_08', 'NPC_FRE_09', 'K2', '{"date","nuit"}', 'Il a noté la date — elle correspond à une mise à jour programmée du serveur', '`QUEST:QST_CAI_GARDE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_09', 'NPC_FRE_09', 'K2', '{"porte","derobee"}', 'La porte dérobée de la tour mène à un passage qui n''apparaît sur aucun plan de Freelia', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_10', 'NPC_FRE_09', 'K3', '{"menagerie","nuit","cardinal","acces"}', 'La silhouette qu''il a vue dans la Ménagerie était un sous-processus du Cardinal — une forme humaine temporaire que le système utilise pour patcher des éléments du monde en direct. L''ombre de bête était le résidu de la suppression d''un familier qui n''aurait jamais dû exister. Le Cardinal « nettoie » la Ménagerie certaines nuits', NULL, '*(il pose la main sur la garde de son épée)* « J''ai rien vu. J''étais pas à la Ménagerie cette nuit-là. Et si quelqu''un prétend le contraire, il ment ou il a rêvé. La Garde Fauve ne se souvient que de ce qu''elle veut bien se souvenir. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_11', 'NPC_FRE_09', 'K3', '{"alicia","doute","reine"}', 'Il a commencé à douter qu''Alicia soit seule sur le trône — il a entendu des voix dans la salle du trône vide, des voix qui répondaient à la reine quand elle croyait être seule', NULL, '*(ses oreilles se couchent)* « La reine est la reine. Je la sers. Je ne l''espionne pas. Si tu insinues que je remets en cause son autorité, on règle ça à l''épée, ici et maintenant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_09_12', 'NPC_FRE_09', 'KX', '{"*(hors sujet)*"}', '*(il tourne les talons)* « J''ai des rondes à superviser. Va au poste si tu veux déposer un rapport officiel. Sinon, dégage. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_01', 'NPC_FRE_10', 'K0', '{"savane","patrouille"}', 'La Savane des Crocs — zones, dangers, horaires de patrouille', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_02', 'NPC_FRE_10', 'K0', '{"debutants","protection"}', 'Protéger les novices — conseils, zones sûres, points de respawn', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_03', 'NPC_FRE_10', 'K0', '{"mobs","savane"}', 'Les mobs de la Savane — hyènes, guépards, serpents à plumes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_04', 'NPC_FRE_10', 'K1', '{"pieges","collets"}', 'Elle trouve des collets en acier Sylph posés la nuit — piégeage illégal', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_05', 'NPC_FRE_10', 'K1', '{"zephyr","suspect"}', 'Elle soupçonne Zephyr — il rôde trop souvent en lisière de savane', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_06', 'NPC_FRE_10', 'K1', '{"ordres","abandon"}', 'Ses supérieurs lui ont ordonné de ne pas enquêter sur les pièges', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_07', 'NPC_FRE_10', 'K2', '{"nuit","silhouette"}', 'De nuit, elle a vu une silhouette poser des collets — trop rapide pour un joueur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_08', 'NPC_FRE_10', 'K2', '{"collet","vide"}', 'Un collet qu''elle a retiré s''est refermé tout seul sur sa main — il visait une bête en particulier', '`QUEST:QST_CAI_COLLETS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_09', 'NPC_FRE_10', 'K3', '{"pieges","automatises","cardinal"}', 'Les collets ne sont pas posés par Zephyr mais par un script de chasse automatique que le Cardinal exécute pour réguler la population de mobs. Zephyr les trouve et les revend', NULL, '*(elle croise les bras)* « Les collets, c''est des braconniers. Point. Je les enlève, je les brûle, je fais mon rapport. Y a rien d''autre à comprendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_10_10', 'NPC_FRE_10', 'KX', '{"*(hors sujet)*"}', '« J''ai ma ronde. Si t''es perdu, le Guide est à l''entrée de la Savane. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_01', 'NPC_FRE_11', 'K0', '{"domptage","debutant"}', 'Les bases du domptage — lien, soin, appel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_02', 'NPC_FRE_11', 'K0', '{"savane","chasse"}', 'La chasse en Savane — techniques, mobs, récompenses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_03', 'NPC_FRE_11', 'K0', '{"familier","chat"}', 'Son chat des sables — il le suit partout depuis qu''il l''a sauvé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_04', 'NPC_FRE_11', 'K1', '{"chat","comportement"}', 'Le chat grogne sur certains joueurs — il les reconnaît mais le guide non', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_05', 'NPC_FRE_11', 'K1', '{"regard","vide"}', 'Le chat suit des yeux des directions où il n''y a personne', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_06', 'NPC_FRE_11', 'K1', '{"collet","sauvetage"}', 'Il a trouvé le chat dans un collet en acier — le même type que ceux de la Gardienne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_07', 'NPC_FRE_11', 'K2', '{"chat","origine"}', 'Le chat n''est pas un mob de la Savane — il ne correspond à aucune fiche du bestiaire', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_08', 'NPC_FRE_11', 'K2', '{"affection","etrange"}', 'On l''a affecté à la Savane juste après avoir trouvé le chat — comme si on le surveillait', '`QUEST:QST_CAI_CHAT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_09', 'NPC_FRE_11', 'K3', '{"chat","familier","ancien"}', 'Le chat est un ancien familier de la bêta — un des premiers modèles de familiers, que le Cardinal a retiré du bestiaire mais pas de la mémoire du serveur. Il reconnaît les joueurs qui ont participé à la bêta', NULL, '*(il serre le chat contre lui)* « C''est juste un chat. Un chat sauvé d''un piège. Y a rien d''étrange là-dedans. Si tu veux un cours de domptage, je suis là. Si tu veux parler de mon chat… va voir ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_11_10', 'NPC_FRE_11', 'KX', '{"*(hors sujet)*"}', '« Le chat a faim. On reparle après la chasse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_01', 'NPC_FRE_12', 'K0', '{"appats","catalogue"}', 'Les appâts de base — vers, baies, leurres sonores', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_02', 'NPC_FRE_12', 'K0', '{"prix","vente"}', 'Ses prix — 50 à 200 Yrd selon le type d''appât', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_03', 'NPC_FRE_12', 'K0', '{"savane","chasseurs"}', 'Les chasseurs de la Savane — ses clients réguliers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_04', 'NPC_FRE_12', 'K1', '{"lot","inconnu"}', 'Un lot d''appâts livré par un fournisseur inconnu', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_05', 'NPC_FRE_12', 'K1', '{"betes","anormales"}', 'Les appâts attirent des bêtes de niveau trop élevé pour la Savane', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_06', 'NPC_FRE_12', 'K1', '{"boite","vibration"}', 'Il garde le reste du lot dans une boîte en fer — elle vibre parfois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_07', 'NPC_FRE_12', 'K2', '{"fournisseur","description"}', 'Le fournisseur était masqué, portait une cape Sylph — il avait une odeur de soufre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_08', 'NPC_FRE_12', 'K2', '{"appats","suivi"}', 'Un appât posé attire toujours la même bête — comme si elle le cherchait', '`QUEST:QST_CAI_APPATS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_09', 'NPC_FRE_12', 'K3', '{"appats","appels","serveur"}', 'Les appâts mystérieux sont des balises d''appel — ils émettent un signal qui force le spawn d''une bête spécifique depuis une base de données externe. Quelqu''un teste une porte dérobée dans le système de spawn du Cardinal', NULL, '*(il pose la main sur la boîte)* « J''ai pas demandé d''où ils venaient. On m''a payé pour les vendre. Maintenant je les vends plus. C''est tout. Si tu veux des appâts normaux, j''en ai. Si tu veux de ceux-là… t''auras qu''à les trouver toi-même. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_12_10', 'NPC_FRE_12', 'KX', '{"*(hors sujet)*"}', '*(il regarde autour de lui)* « J''ai des appâts normaux. Très normaux. Tout à fait normaux. Tu veux des vers ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_01', 'NPC_FRE_13', 'K0', '{"collines","frontiere"}', 'Les Collines de l''Ouest — frontière, danger, points de passage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_02', 'NPC_FRE_13', 'K0', '{"patrouille","routine"}', 'Sa routine de patrouille — horaires, itinéraires, collègues', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_03', 'NPC_FRE_13', 'K0', '{"mobs","collines"}', 'Les mobs des Collines — worgs, aigles de pierre, pumas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_04', 'NPC_FRE_13', 'K1', '{"trafic","nuit"}', 'Des caravanes Sylph traversent la nuit — elle est payée pour ne pas les voir', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_05', 'NPC_FRE_13', 'K1', '{"solde","silence"}', 'Sa solde a augmenté après son premier rapport « rien à signaler »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_06', 'NPC_FRE_13', 'K1', '{"caisses","comptage"}', 'Elle compte les caisses mentalement — elle sait combien passent chaque nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_07', 'NPC_FRE_13', 'K2', '{"marquage","caisses"}', 'Les caisses portent un marquage Sylph — mais les sceaux sont faux', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_08', 'NPC_FRE_13', 'K2', '{"commandant","ordres"}', 'Les ordres de silence viennent du Commandant Griffe — pas directement d''Alicia', '`QUEST:QST_CAI_TRAFIC_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_09', 'NPC_FRE_13', 'K3', '{"trafic","caisses","systeme"}', 'Les caisses transportent des fragments de données — des morceaux de code de familiers supprimés que les Sylphes revendent au Marché aux Os pour les faire « renaître » hors registre. Le Commandant Griffe fait partie du réseau', NULL, '*(elle pose la main sur sa lance)* « La frontière est calme. Je te conseille d''en faire autant. Si t''as des questions sur ce qui passe la nuit, pose-les au Commandant. Moi, je vois rien. Et j''aime ça. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_13_10', 'NPC_FRE_13', 'KX', '{"*(hors sujet)*"}', '*(elle regarde l''horizon)* « Le soleil se couche. Les collines deviennent dangereuses la nuit. Tu devrais rentrer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_01', 'NPC_FRE_14', 'K0', '{"pistage","collines"}', 'Les techniques de pistage — traces, odeurs, comportement des mobs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_02', 'NPC_FRE_14', 'K0', '{"worgs","alpha"}', 'Les worgs alpha — dangers, récompenses, zones d''apparition', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_03', 'NPC_FRE_14', 'K0', '{"chasse","contrat"}', 'Ses contrats de chasse — prix, conditions, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_04', 'NPC_FRE_14', 'K1', '{"worg","collier"}', 'Un worg alpha portait un collier en cuir tressé — travail intelligent', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_05', 'NPC_FRE_14', 'K1', '{"clairiere","runes"}', 'La piste menait à une clairière avec un cercle de pierres gravées', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_06', 'NPC_FRE_14', 'K1', '{"battement","coeur"}', 'Sous la clairière, elle entend un battement de cœur — régulier, lent, profond', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_07', 'NPC_FRE_14', 'K2', '{"carte","absente"}', 'La clairière n''apparaît sur aucune carte — ni les siennes, ni celles de la Tour', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_08', 'NPC_FRE_14', 'K2', '{"runes","copie"}', 'Elle a frotté une rune — elle ressemble à un glyphe de domptage, mais inversé', '`QUEST:QST_CAI_WORG_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_09', 'NPC_FRE_14', 'K3', '{"clairiere","coeur","serveur"}', 'La clairière est un point d''accès au noyau du serveur — le battement de cœur est le cycle d''horloge du Cardinal. Les runes inversées sont des marqueurs de maintenance que les admins ont laissés dans le monde', NULL, '*(elle pose un doigt sur ses lèvres)* « Cette clairière, tu l''as pas vue. Si quelqu''un te dit que t''y es allé, tu mens. Si le Commandant te pose la question, tu sais rien. Moi-même, j''y suis jamais allée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_14_10', 'NPC_FRE_14', 'KX', '{"*(hors sujet)*"}', '*(elle renifle l''air)* « Le vent tourne. Je repars en chasse. Reste pas trop près des pierres. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_01', 'NPC_FRE_15', 'K0', '{"fourrures","vente"}', 'Les fourrures — qualité, prix, types de peaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_02', 'NPC_FRE_15', 'K0', '{"collines","commerce"}', 'Le commerce de fourrures aux Collines — clients, saison, rendement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_03', 'NPC_FRE_15', 'K0', '{"pisteuse","contrat"}', 'Il travaille avec la Pisteuse — elle chasse, il achète', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_04', 'NPC_FRE_15', 'K1', '{"fourrure","inconnue"}', 'La Pisteuse lui a vendu une peau de worg qu''il n''a pas reconnue', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_05', 'NPC_FRE_15', 'K1', '{"fourrure","chaude"}', 'La fourrure est chaude au toucher — mais elle n''a jamais été sur un animal vivant', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_06', 'NPC_FRE_15', 'K1', '{"reserve","bruit"}', 'La nuit, il entend des froissements dans sa réserve — la fourrure bouge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_07', 'NPC_FRE_15', 'K2', '{"peau","pores"}', 'La peau n''a pas de pores — comme si elle n''avait jamais respiré', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_08', 'NPC_FRE_15', 'K2', '{"brok","proposition"}', 'Brok lui a proposé de la lui racheter — cher, très cher', '`QUEST:QST_CAI_FOURRURE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_09', 'NPC_FRE_15', 'K3', '{"fourrure","residu","donnees"}', 'La fourrure n''est pas une peau — c''est un résidu de texture, un morceau de modèle 3D que le Cardinal n''a pas désalloué. Le worg n''existait pas : il était un spawn de test que le système a oublié de supprimer', NULL, '*(il referme le coffre rapidement)* « La fourrure, elle est pas à vendre. Elle est à personne. Je la regarde, c''est tout. Si t''es pas content, va voir Brok. Mais Brok l''aura pas non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_15_10', 'NPC_FRE_15', 'KX', '{"*(hors sujet)*"}', '*(il gratte une peau)* « J''ai du travail. Les peaux attendent pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_01', 'NPC_FRE_16', 'K0', '{"taniere","acces"}', 'La Tanière du Roi Béhémoth — accès, conditions, niveau requis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_02', 'NPC_FRE_16', 'K0', '{"registre","raids"}', 'Le registre des raids — inscription, vérification, sortie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_03', 'NPC_FRE_16', 'K0', '{"behemoth","histoire"}', 'Le Roi Béhémoth — histoire, légende, récompenses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_04', 'NPC_FRE_16', 'K1', '{"groupe","disparu"}', 'Huit joueurs entrés, zéro sortis — mais le registre dit le contraire', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_05', 'NPC_FRE_16', 'K1', '{"entree","fausse"}', 'Quelqu''un a écrit leur sortie dans le registre — ce n''est pas son écriture', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_06', 'NPC_FRE_16', 'K1', '{"nuit","changement"}', 'Chaque nuit, l''entrée change — les noms s''effacent un par un', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_07', 'NPC_FRE_16', 'K2', '{"logs","autel"}', 'Les disparus n''ont pas respawné à l''Autel — ils sont juste « partis »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_08', 'NPC_FRE_16', 'K2', '{"ecriture","inconnue"}', 'L''écriture ressemble à la sienne — mais la boucle du « B » est inversée', '`QUEST:QST_CAI_REGISTRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_09', 'NPC_FRE_16', 'K3', '{"registre","cardinal","edit"}', 'Le registre est lié à la base de données du donjon — quand le Cardinal corrige un bug de l''instance, il édite les registres de sortie pour maintenir la cohérence des logs. Les huit joueurs ont rencontré un bug fatal et le Cardinal les a « désinscrits » du monde', NULL, '*(elle ferme le registre d''un coup sec)* « Le registre est exact. Il est toujours exact. Si tu vois une erreur, c''est ta mémoire qui flanche. Moi, je note ce que je vois. Et je vois que huit guerriers sont sortis vivants de la Tanière. C''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_16_10', 'NPC_FRE_16', 'KX', '{"*(hors sujet)*"}', '*(elle pose la main sur le registre)* « Le donjon attend. Si tu veux entrer, inscris-toi. Si tu veux poser des questions, va à la Tour. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_01', 'NPC_FRE_17', 'K0', '{"plans","taniere"}', 'Les plans de la Tanière — galeries, salles de boss, raccourcis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_02', 'NPC_FRE_17', 'K0', '{"cartographie","metier"}', 'La cartographie de donjon — outils, méthodes, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_03', 'NPC_FRE_17', 'K0', '{"vente","plans"}', 'Ses plans à vendre — détail, prix, fiabilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_04', 'NPC_FRE_17', 'K1', '{"galerie","mouvante"}', 'Une galerie qui apparaît et disparaît des plans d''un mois à l''autre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_05', 'NPC_FRE_17', 'K1', '{"etage","inexistant"}', 'Il l''appelle « l''étage inexistant » — il en a six versions différentes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_06', 'NPC_FRE_17', 'K1', '{"proportions","parfaites"}', 'Les proportions sont trop parfaites pour un donjon — c''est une salle ronde avec un piédestal', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_07', 'NPC_FRE_17', 'K2', '{"plans","caches"}', 'Il cache tous les plans sous son matelas — il a peur qu''on les prenne', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_08', 'NPC_FRE_17', 'K2', '{"juin","decalage"}', 'Le plan de juin montre la galerie au nord ; celui d''août la montre au sud, décalée', '`QUEST:QST_CAI_ETAGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_09', 'NPC_FRE_17', 'K3', '{"etage","inexistant","dev"}', 'L''étage inexistant est une salle de développement — un espace de test que les admins ont intégré au donjon par erreur et que le Cardinal déplace aléatoirement pour le cacher des joueurs. Le piédestal au centre est une console d''administration', NULL, '*(il range ses plans précipitamment)* « L''étage inexistant ? Je l''ai rêvé. Trop de nuits blanches. Y a rien d''autre que ce que je dessine. Et si tu poses encore la question, je te montrerai la sortie. Très vite. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_17_10', 'NPC_FRE_17', 'KX', '{"*(hors sujet)*"}', '*(il déroule un plan)* « J''ai du travail. Si tu veux un plan, 200 Yrd. Si tu veux parler d''étages qui n''existent pas… 500. Et je te dirai rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_01', 'NPC_FRE_18', 'K0', '{"route","aerienne"}', 'La route aérienne Freelia-Alne — trajet, durées, points de contrôle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_02', 'NPC_FRE_18', 'K0', '{"controle","vols"}', 'Le contrôle des vols — enregistrement, vérification, sanctions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_03', 'NPC_FRE_18', 'K0', '{"registre","comptage"}', 'Le registre de comptage — méthode, fiabilité, historique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_04', 'NPC_FRE_18', 'K1', '{"vols","vides"}', 'Des vols enregistrés sans monture visible — juste des traces', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_05', 'NPC_FRE_18', 'K1', '{"familiers","seuls"}', 'Des familiers volent seuls vers Alne — sans maître, sans selle', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_06', 'NPC_FRE_18', 'K1', '{"douze","mois"}', 'Il en a compté douze ce mois-ci — le nombre augmente chaque semaine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_07', 'NPC_FRE_18', 'K2', '{"nuit","ombres"}', 'De nuit, il voit des ombres passer — trop grandes pour des oiseaux, trop silencieuses pour des wyvernes', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_08', 'NPC_FRE_18', 'K2', '{"alne","retour"}', 'Aucune des bêtes qu''il a vues partir n''est revenue d''Alne', '`QUEST:QST_CAI_VOLS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_09', 'NPC_FRE_18', 'K3', '{"familiers","reallocation","cardinal"}', 'Les familiers qui volent seuls sont des unités que le Cardinal réalloue à d''autres serveurs ou zones — des familiers dissous dont le modèle 3D est recyclé pour économiser de la mémoire. Leur vol vers Alne est une désallocation programmée', NULL, '*(il claque son registre)* « Les vols sont comptabilisés, enregistrés, classés. Si y a des anomalies, c''est le vent, la fatigue, l''heure tardive. Je fais mon travail. Mon travail n''inclut pas d''interpréter ce que je vois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_18_10', 'NPC_FRE_18', 'KX', '{"*(hors sujet)*"}', '*(il lève les yeux au ciel)* « La route est calme aujourd''hui. Trop calme. Continue ta route, voyageur. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_01', 'NPC_FRE_19', 'K0', '{"potions","vol"}', 'Les potions de vol — types, prix, durée, effets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_02', 'NPC_FRE_19', 'K0', '{"ilot","halte"}', 'L''îlot de halte — services, histoire, position', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_03', 'NPC_FRE_19', 'K0', '{"buffs","vent"}', 'Les buffs de résistance au vent — navigation aérienne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_04', 'NPC_FRE_19', 'K1', '{"ombres","ciel"}', 'Il voit des ombres voler sans monture — formes noires, sans ailes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_05', 'NPC_FRE_19', 'K1', '{"carnet","cache"}', 'Il note les heures et les directions dans un carnet caché', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_06', 'NPC_FRE_19', 'K1', '{"vigie","ignore"}', 'La Vigie Route ne voit pas ces ombres — ou fait semblant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_07', 'NPC_FRE_19', 'K2', '{"couloir","aerien"}', 'Les ombres empruntent toujours le même couloir aérien — corridor invisible', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_08', 'NPC_FRE_19', 'K2', '{"heures","regulieres"}', 'Les passages sont à heures régulières — comme un vol commercial', '`QUEST:QST_CAI_OMBRES_VOL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_09', 'NPC_FRE_19', 'K3', '{"ombres","transfert","donnees"}', 'Les ombres sont des paquets de données que le Cardinal transfère entre les serveurs de zones — des mises à jour d''instance, des migrations de mobs, des correctifs. Le corridor aérien est un protocole de transfert visualisé dans le ciel du jeu', NULL, '*(il essuie une fiole)* « Des ombres dans le ciel ? Le vent, les nuages, les reflets. J''ai pas le temps de regarder le ciel, j''ai des potions à vendre. Et toi, tu veux acheter ou tu veux regarder le ciel ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_19_10', 'NPC_FRE_19', 'KX', '{"*(hors sujet)*"}', '*(il range ses fioles)* « Le vent se lève. Je vais fermer l''étal. Si tu veux une potion, dépêche-toi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_01', 'NPC_FRE_20', 'K0', '{"menagerie","enclos"}', 'La Ménagerie Royale — organisation, animaux, accès', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_02', 'NPC_FRE_20', 'K0', '{"entretien","quotidien"}', 'L''entretien quotidien — tâches, horaires, difficultés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_03', 'NPC_FRE_20', 'K0', '{"betes","nourriture"}', 'La nourriture des bêtes — régimes, fournisseurs, coûts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_04', 'NPC_FRE_20', 'K1', '{"cage","fond"}', 'Une cage isolée au fond se referme toute seule chaque nuit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_05', 'NPC_FRE_20', 'K1', '{"caillou","serrure"}', 'Il a bloqué la serrure avec un caillou — le caillou est sur le sol le matin', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_06', 'NPC_FRE_20', 'K1', '{"respiration","nuit"}', 'Il entend une respiration dans la cage la nuit — une cage vide', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_07', 'NPC_FRE_20', 'K2', '{"propreté","etrange"}', 'La cage est toujours propre — pas de poussière, pas de litière sale, comme si quelqu''un nettoyait après', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_08', 'NPC_FRE_20', 'K2', '{"porte","menagerie"}', 'La cage du fond est près de la porte verrouillée de la Ménagerie — la Porte des Bêtes', '`QUEST:QST_CAI_CAGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_09', 'NPC_FRE_20', 'K3', '{"cage","portail","instable"}', 'La cage est un portail instable — une brèche entre la Ménagerie réelle et l''enclos verrouillé. La respiration qu''il entend est celle de la chose enfermée derrière la Porte des Bêtes, qui respire à travers la cage comme par un soupirail', NULL, '*(il recule d''un pas)* « La cage du fond ? Elle est vide. Elle a toujours été vide. Je l''ouvre, je la ferme, je nettoie rien parce que y a rien à nettoyer. Si t''entends une respiration, t''as l''oreille fatiguée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_20_10', 'NPC_FRE_20', 'KX', '{"*(hors sujet)*"}', '*(il prend un balai)* « J''ai du travail. Les wyvernes attendent leur viande. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_01', 'NPC_FRE_21', 'K0', '{"wyvernes","dressage"}', 'Le dressage des wyvernes — méthodes, risques, récompenses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_02', 'NPC_FRE_21', 'K0', '{"wyverne","noire"}', 'Sa wyverne noire des Monts Brumeux — capture, domptage, histoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_03', 'NPC_FRE_21', 'K0', '{"leo","apprenti"}', 'Il a été l''apprenti de Léo — techniques héritées, différences', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_04', 'NPC_FRE_21', 'K1', '{"wyverne","parle"}', 'Sa wyverne noire lui parle — des mots, des phrases', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_05', 'NPC_FRE_21', 'K1', '{"porte","faim"}', 'Elle dit « La porte s''ouvre » et « Il a faim » — elle regarde vers l''enclos verrouillé', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_06', 'NPC_FRE_21', 'K1', '{"silence","peur"}', 'Il n''en parle à personne — peur d''être pris pour un fou', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_07', 'NPC_FRE_21', 'K2', '{"wyverne","comportement"}', 'La wyverne noire refuse de voler vers l''est — elle freine en plein ciel', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_08', 'NPC_FRE_21', 'K2', '{"monts","brumeux"}', 'Dans les Monts Brumeux, elle a trouvé quelque chose — elle en est revenue changée', '`QUEST:QST_CAI_WYVERNE_NOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_09', 'NPC_FRE_21', 'K3', '{"wyverne","contamination","code"}', 'La wyverne noire a été contaminée par un fragment de code de l''enclos verrouillé — un parasite de données qui lui donne une conscience artificielle. Ce qu''elle « dit » est une retransmission des signaux de la chose enfermée', NULL, '*(il siffle sa wyverne qui s''éloigne)* « Les wyvernes parlent pas. C''est un fait. Si tu m''entends dire le contraire, j''ai trop passé de temps au soleil. La noire, c''est une bonne bête. Silencieuse. Comme elles doivent être. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_21_10', 'NPC_FRE_21', 'KX', '{"*(hors sujet)*"}', '*(il siffle)* « On monte. La wyverne a besoin de voler. Et moi de me taire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_01', 'NPC_FRE_22', 'K0', '{"soins","familiers"}', 'Les soins aux familiers — types de soins, prix, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_02', 'NPC_FRE_22', 'K0', '{"infirmerie","menagerie"}', 'L''infirmerie de la Ménagerie — équipement, capacités, accès', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_03', 'NPC_FRE_22', 'K0', '{"herbes","baumes"}', 'Les remèdes — herbes médicinales, baumes, sorts de soin', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_04', 'NPC_FRE_22', 'K1', '{"ombre","bete"}', 'Une bête inconnue couverte d''écailles noires — pas dans le registre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_05', 'NPC_FRE_22', 'K1', '{"retour","nuit"}', 'Elle revient chaque nuit — saute le mur, attend devant la porte', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_06', 'NPC_FRE_22', 'K1', '{"cicatrices","inconnues"}', 'Ses cicatrices ne correspondent à aucune morsure connue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_07', 'NPC_FRE_22', 'K2', '{"ombre","yeux"}', 'Ses yeux brillent la nuit — une lueur qui n''est pas d''ALO', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_08', 'NPC_FRE_22', 'K2', '{"foret","source"}', 'La forêt où elle a été trouvée est la même où Zephyr pose ses pièges', '`QUEST:QST_CAI_OMBRE_BETE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_09', 'NPC_FRE_22', 'K3', '{"ombre","anomalie","spawn"}', 'Ombre est une anomalie de spawn — un familier généré par un résidu de la bêta, dont le modèle existe encore dans les fichiers racines du serveur. Les cicatrices sont des marqueurs de version', NULL, '*(il caresse Ombre)* « Ombre ? C''est juste un animal errant. J''ai des animaux errants tous les jours. Celui-là, il est gentil, il revient, je le soigne, il repart. Rien d''étrange. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_22_10', 'NPC_FRE_22', 'KX', '{"*(hors sujet)*"}', '*(il prépare une potion)* « J''ai des patients. Ombre peut pas entrer si t''es là. Dégage. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_01', 'NPC_FRE_23', 'K0', '{"oeufs","catalogue"}', 'Les œufs de familiers — catalogue, prix, garanties', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_02', 'NPC_FRE_23', 'K0', '{"eclosion","conseils"}', 'L''éclosion — soins, température, durée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_03', 'NPC_FRE_23', 'K0', '{"menagerie","etal"}', 'Son étal dans la Ménagerie — position, horaires, fournisseurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_04', 'NPC_FRE_23', 'K1', '{"oeuf","noir"}', 'Un œuf à la coquille noire veinée de rouge — il n''a jamais éclos', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_05', 'NPC_FRE_23', 'K1', '{"chaleur","pulsation"}', 'L''œuf pulse de chaleur — comme s''il respirait', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_06', 'NPC_FRE_23', 'K1', '{"bruit","cogne"}', 'Le soir, il cogne contre le nid — un bruit sourd, régulier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_07', 'NPC_FRE_23', 'K2', '{"sylph","vendeur"}', 'Il a acheté l''œuf à un chasseur Sylph masqué — le même que Brok a décrit', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_08', 'NPC_FRE_23', 'K2', '{"coquille","marquage"}', 'La coquille porte un marquage runique — impossible à identifier', '`QUEST:QST_CAI_OEUF_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_09', 'NPC_FRE_23', 'K3', '{"oeuf","conteneur","donnees"}', 'L''œuf n''est pas un œuf — c''est un conteneur de données verrouillé, un fichier compressé que le Cardinal n''a pas déballé. Ce qui cogne à l''intérieur, c''est le processus de décompression qui tourne en boucle sur un fichier corrompu', NULL, '*(il recouvre l''œuf d''un torchon)* « Y a pas d''œuf spécial. Y a des œufs, tous normaux, tous à vendre. Celui-là, il est pas à vendre. Il est à personne. Si t''as des questions, va voir Gimli, il forge du métal, il parle pas. Comme moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_23_10', 'NPC_FRE_23', 'KX', '{"*(hors sujet)*"}', '*(il tripote un œuf de griffon)* « 800 Yrd, éclosion garantie dans la semaine. Si tu veux l''œuf noir… tu veux pas l''œuf noir. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_01', 'NPC_FRE_24', 'K0', '{"domptage","t4"}', 'Le domptage de haut niveau — techniques, conditions, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_02', 'NPC_FRE_24', 'K0', '{"betes","alpha"}', 'Les bêtes alpha — types, habitats, comportements', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_03', 'NPC_FRE_24', 'K0', '{"exploits","palmares"}', 'Ses exploits — Roi des Sables, Hydre des Marais, Chimère des Cendres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_04', 'NPC_FRE_24', 'K1', '{"technique","cachee"}', 'Une technique absente du manuel — elle contourne la résistance des bêtes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_05', 'NPC_FRE_24', 'K1', '{"noyau","coeur"}', 'La technique s''adresse au « noyau » — le cœur de code du familier', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_06', 'NPC_FRE_24', 'K1', '{"epuisement","sensation"}', 'Chaque utilisation l''épuise — comme si la technique usait son propre lien d''âme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_07', 'NPC_FRE_24', 'K2', '{"leo","rival"}', 'Léo désapprouve sa méthode — il dit que la technique « force » le lien', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_08', 'NPC_FRE_24', 'K2', '{"hydre","coincidence"}', 'L''Hydre des Marais avait une anomalie de registre — elle n''aurait pas dû être domptable', '`QUEST:QST_CAI_ALPHA_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_09', 'NPC_FRE_24', 'K3', '{"technique","exploit","cardinal"}', 'Sa technique n''est pas une compétence de jeu — c''est un exploit, une faille dans le système de domptage qui lui permet de modifier le champ `isTameable` de n''importe quelle entité. Le Cardinal ne l''a pas corrigé parce que la faille est enfouie dans le code hérité de la bêta. Chaque utilisation signale sa position au Cardinal', NULL, '*(il croise les bras)* « Ma technique ? Des années de pratique. Du talent. Rien d''autre. Si Léo peut pas faire pareil, c''est qu''il est trop vieux pour apprendre. Si tu veux l''apprendre, 5000 Yrd la leçon. Et tu poses pas de questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_24_10', 'NPC_FRE_24', 'KX', '{"*(hors sujet)*"}', '« J''ai une Chimère à nourrir. Reviens quand t''auras dompté un vrai monstre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_01', 'NPC_FRE_25', 'K0', '{"colline","horaires"}', 'Les horaires d''accès à la Colline aux Souvenirs — accès libre le jour, fermeture rituelle au crépuscule', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_02', 'NPC_FRE_25', 'K0', '{"tombes","sections"}', 'Les différentes sections de sépultures classées par type de familier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_03', 'NPC_FRE_25', 'K0', '{"offrandes","rituel"}', 'Les offrandes acceptées sur les tombes et les rituels de souvenir courants chez les Cait Sith', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_04', 'NPC_FRE_25', 'K1', '{"bruits","nuit"}', 'Il décrit les bruits qu''il entend la nuit — des pas légers, des souffles, des grattements sur la pierre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_05', 'NPC_FRE_25', 'K1', '{"traces","matin"}', 'Il montre les endroits où il trouve des traces de pattes au matin — mais il n''a rien vu passer', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_06', 'NPC_FRE_25', 'K1', '{"visiteurs","reguliers"}', 'Les familles de visiteurs réguliers — certains viennent depuis des années sans avoir de familier mort', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_07', 'NPC_FRE_25', 'K2', '{"carnet","comptage"}', 'Son carnet secret — il note chaque nuit où les pas se font entendre ; la fréquence augmente', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_08', 'NPC_FRE_25', 'K2', '{"stele","anonyme"}', 'Une stèle au centre de la colline absente des registres — le nom gravé a été effacé', '`QUEST:QST_FRE_COL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_09', 'NPC_FRE_25', 'K3', '{"ames","retention"}', 'Les pas sont ceux des familiers dont les âmes n''ont pas été libérées — la Colline les retient et le Cardinal simule des présences avec leurs données', NULL, '*(il détourne le regard et serre sa lance)* « La Colline est un lieu de paix. Si tu veux des histoires de fantômes, va au Marché. Moi, je garde. C''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_25_10', 'NPC_FRE_25', 'KX', '{"*(hors sujet)*"}', '*(il inspecte l''horizon d''un air las)* « Pose tes questions à Elara. Moi, je surveille. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_01', 'NPC_FRE_26', 'K0', '{"pneuma","fleurs"}', 'Les fleurs de Pneuma — leur apparence argentée, leur parfum léger, leur rareté', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_02', 'NPC_FRE_26', 'K0', '{"livraison","rituel"}', 'Le rituel de livraison — il dépose les fleurs à l''aube, avant l''arrivée des visiteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_03', 'NPC_FRE_26', 'K0', '{"saisons","recolte"}', 'La saison de récolte des fleurs de Pneuma — seulement en brumaire, dans les hauteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_04', 'NPC_FRE_26', 'K1', '{"fleurs","lueur"}', 'Certaines fleurs brillent la nuit après avoir été déposées — il les a vues de ses propres yeux', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_05', 'NPC_FRE_26', 'K1', '{"tombes","selection"}', 'Elara choisit les tombes qui reçoivent les fleurs — il n''a jamais compris le critère', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_06', 'NPC_FRE_26', 'K1', '{"fleur","fane"}', 'Il a gardé une fleur pour lui — elle n''a pas fané non plus ; elle est sur sa table de chevet', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_07', 'NPC_FRE_26', 'K2', '{"origine","pneuma"}', 'Les fleurs ne poussent pas naturellement — il a trouvé une pousse dans une zone où il n''en avait jamais planté', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_08', 'NPC_FRE_26', 'K2', '{"nuit","tombe"}', 'Une nuit, il est revenu pour vérifier — la fleur d''une tombe récente avait disparu, remplacée par une autre, identique', '`QUEST:QST_FRE_COL_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_09', 'NPC_FRE_26', 'K3', '{"fleur","ame"}', 'Les fleurs de Pneuma sont des fragments d''âmes de familiers défunts que le Cardinal recycle — une fleur qui ne fane pas est une âme qui n''a pas été libérée', NULL, '*(il laisse tomber une fleur qu''il tenait et la ramasse précipitamment)* « Les fleurs sont juste des fleurs. Ne cherche pas de sens caché. Je les pose, je m''en vais. C''est mon travail. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_26_10', 'NPC_FRE_26', 'KX', '{"*(hors sujet)*"}', '*(il arrange son panier de fleurs en évitant ton regard)* « Euh… tu veux une fleur ? Non, je peux pas en donner. Désolé. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_01', 'NPC_FRE_27', 'K0', '{"marchandise","catalogue"}', 'Les articles qu''il vend — colliers, médaillons, plumes, griffes, fourrure conservée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_02', 'NPC_FRE_27', 'K0', '{"prix","echange"}', 'Ses prix et sa politique d''achat — il rachète les reliques de familiers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_03', 'NPC_FRE_27', 'K0', '{"deuil","clients"}', 'Les histoires de deuil que les clients lui racontent — il les écoute toujours', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_04', 'NPC_FRE_27', 'K1', '{"collier","vibration"}', 'Le collier en cuir tressé qui vibre au toucher — il l''a eu d''une cliente en pleurs', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_05', 'NPC_FRE_27', 'K1', '{"cliente","mystere"}', 'La cliente qui lui a vendu le collier — elle portait un capuchon, il n''a pas vu son visage', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_06', 'NPC_FRE_27', 'K1', '{"tiroir","clef"}', 'Il garde le collier dans un tiroir fermé — la serrure a été changée deux fois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_07', 'NPC_FRE_27', 'K2', '{"vibration","intensite"}', 'Le collier vibre plus fort certains jours — toujours les mêmes dates, qu''il a notées', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_08', 'NPC_FRE_27', 'K2', '{"acheteur","masque"}', 'Un acheteur masqué est venu proposer une grosse somme pour le collier — il a refusé', '`QUEST:QST_FRE_COL_03`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_09', 'NPC_FRE_27', 'K3', '{"collier","ame"}', 'Le collier vibre parce qu''il contient encore l''empreinte d''âme du familier défunt — le familier n''est pas mort, il a été « désenregistré » du système et son essence est piégée dans l''objet', NULL, '*(il ferme le tiroir d''un coup sec et pose la main dessus)* « Ce collier est juste un vieux bout de cuir. J''aurais dû le jeter. Si tu veux acheter, achète. Sinon, laisse-moi travailler. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_27_10', 'NPC_FRE_27', 'KX', '{"*(hors sujet)*"}', '*(il essuie un médaillon avec un chiffon)* « J''ai du travail. Reviens plus tard si tu veux marchander. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_01', 'NPC_FRE_28', 'K0', '{"meditation","priere"}', 'Sa routine de méditation et de prière — il prie du coucher au lever du soleil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_02', 'NPC_FRE_28', 'K0', '{"steles","anciennes"}', 'L''histoire des stèles les plus anciennes de la Colline et leurs inscriptions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_03', 'NPC_FRE_28', 'K0', '{"colline","symbolique"}', 'La signification spirituelle de la Colline pour les Cait Sith — pont entre les vivants et les bêtes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_04', 'NPC_FRE_28', 'K1', '{"murmures","nuits"}', 'Il entend des murmures qui appellent des noms de familiers — de plus en plus distincts', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_05', 'NPC_FRE_28', 'K1', '{"noms","reconnus"}', 'Il a reconnu le nom d''un familier mort il y a vingt ans — une bête dont la tombe est au pied de la colline', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_06', 'NPC_FRE_28', 'K1', '{"autres","gardiens"}', 'Les autres gardiens disent que c''est le vent — mais le vent ne parle pas en vieux cait shth', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_07', 'NPC_FRE_28', 'K2', '{"sous","terre"}', 'Une nuit, il a posé l''oreille au sol — les murmures viennent de sous la colline, pas des tombes', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_08', 'NPC_FRE_28', 'K2', '{"registre","disparus"}', 'Le registre de l''Archiviste mentionne des familiers enterrés dont les tombes n''existent pas', '`QUEST:QST_FRE_COL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_09', 'NPC_FRE_28', 'K3', '{"caveau","souterrain"}', 'Sous la Colline aux Souvenirs se trouve un caveau de données du Cardinal — les « voix » sont les enregistrements d''âmes de familiers que le système rejoue en boucle, incapable de les purger', NULL, '*(il serre son chapelet d''os jusqu''à ce qu''une perle craque)* « Il n''y a rien sous la Colline que la terre et les racines. Si tu creuses, tu profanes. Et tu ne trouveras que ce que tu cherches à faire taire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_28_10', 'NPC_FRE_28', 'KX', '{"*(hors sujet)*"}', '*(il reprend sa méditation, les yeux fermés)* « Je prie. Laisse-moi prier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_01', 'NPC_FRE_29', 'K0', '{"lamentations","rituel"}', 'Les lamentations funèbres Cait Sith — elle les connaît toutes et les adapte à chaque familier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_02', 'NPC_FRE_29', 'K0', '{"deuil","service"}', 'Son service de deuil — elle pleure les familiers pour les joueurs qui ne peuvent pas le faire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_03', 'NPC_FRE_29', 'K0', '{"colline","tombes"}', 'Les tombes les plus visitées de la Colline et les histoires des bêtes qui y reposent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_04', 'NPC_FRE_29', 'K1', '{"medaillon","secret"}', 'Le médaillon qu''elle porte autour du cou — elle ne l''a jamais ouvert devant personne', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_05', 'NPC_FRE_29', 'K1', '{"tombe","interdite"}', 'Il y a une tombe devant laquelle elle ne s''arrête jamais — elle détourne toujours le chemin', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_06', 'NPC_FRE_29', 'K1', '{"betes","histoire"}', 'Elle connaît l''histoire de chaque bête enterrée sur la Colline — sauf une', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_07', 'NPC_FRE_29', 'K2', '{"nuit","sanglots"}', 'Le Veilleur l''a entendue pleurer la nuit — mais ce n''était pas sa voix, c''était une voix de bête', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_08', 'NPC_FRE_29', 'K2', '{"elara","demande"}', 'Elara lui a demandé d''intercéder pour une tombe vide — une tombe qui porte un nom sans corps', '`QUEST:QST_FRE_COL_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_09', 'NPC_FRE_29', 'K3', '{"familier","cache"}', 'La tombe interdite est celle de son propre familier, qu''elle a trahi pour suivre les ordres du Cardinal — la bête était un « témoin » d''un dysfonctionnement du système et a été supprimée des logs', NULL, '*(elle porte la main à son médaillon, les doigts blanchissent)* « Cette tombe ne te regarde pas. Personne ne doit s''en approcher. Si tu insistes, je ne pleurerai pas pour toi. Ni pour personne d''autre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_29_10', 'NPC_FRE_29', 'KX', '{"*(hors sujet)*"}', '*(elle entonne une lamentation douce, les yeux perdus dans le lointain)* « Chut. Écoute. La Colline parle. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_01', 'NPC_FRE_30', 'K0', '{"boucherie","services"}', 'Les services de découpe — il prépare toute carcasse de monstre rapportée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_02', 'NPC_FRE_30', 'K0', '{"viande","prix"}', 'Les prix au kilo selon le type de monstre — bête commune, exotique, boss', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_03', 'NPC_FRE_30', 'K0', '{"marche","commerce"}', 'L''organisation du Marché aux Crocs — les étals, les filières, les horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_04', 'NPC_FRE_30', 'K1', '{"viande","palpitations"}', 'Il montre la viande qui palpite encore après découpe — des morceaux qu''il a mis de côté', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_05', 'NPC_FRE_30', 'K1', '{"chambre","froide"}', 'La chambre froide du fond — il n''y entre plus seul depuis une semaine', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_06', 'NPC_FRE_30', 'K1', '{"brok","fournisseur"}', 'Brok lui amène des carcasses de plus en plus étranges — des bêtes qu''il ne reconnaît pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_07', 'NPC_FRE_30', 'K2', '{"os","regeneration"}', 'Un os qu''il a scié hier était reconstitué ce matin — dans le bac à déchets', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_08', 'NPC_FRE_30', 'K2', '{"nuit","vibrations"}', 'La porte de la chambre froide vibre la nuit — comme si quelque chose poussait de l''intérieur', '`QUEST:QST_FRE_MAR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_09', 'NPC_FRE_30', 'K3', '{"viande","cardinal"}', 'La viande qui régénère provient de bêtes que le Cardinal a « réinitialisées » sans les retirer du jeu — des spawns corrompus dont les cellules-souches refusent de mourir', NULL, '*(il plante son couteau dans la planche à découper)* « La viande est fraîche, point barre. J''ai assez de soucis avec l''inspection sanitaire sans qu''un aventurier vienne me parler de viande qui ressuscite. Prochain client. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_30_10', 'NPC_FRE_30', 'KX', '{"*(hors sujet)*"}', '*(il essuie son couteau d''un geste mécanique)* « Marché aux Crocs. Si t''achètes pas, tu dégages. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_01', 'NPC_FRE_31', 'K0', '{"tannage","metier"}', 'Les étapes du tannage — salage, trempage, dégraissage, finition', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_02', 'NPC_FRE_31', 'K0', '{"cuirs","catalogue"}', 'Les types de cuir qu''il vend — worg, sanglier, wyverne, bête des collines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_03', 'NPC_FRE_31', 'K0', '{"fourrures","luxe"}', 'Les fourrures de luxe et leurs prix — très prisées des nobles Cait Sith', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_04', 'NPC_FRE_31', 'K1', '{"sceau","decouverte"}', 'Il a trouvé un sceau gravé sous la peau d''un worg alpha — impossible à enlever', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_05', 'NPC_FRE_31', 'K1', '{"symbole","inconnu"}', 'Le sceau représente un cercle brisé avec une patte au centre — il n''existe dans aucun bestiaire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_06', 'NPC_FRE_31', 'K1', '{"autres","peaux"}', 'Il a trouvé le même sceau sur trois autres peaux — toutes de bêtes abattues dans la même zone', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_07', 'NPC_FRE_31', 'K2', '{"carte","provenance"}', 'Il a marqué sur une carte où les peaux sceautées ont été chassées — un motif en cercle se dessine', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_08', 'NPC_FRE_31', 'K2', '{"acheteur","sceau"}', 'Un acheteur est venu exprès pour les peaux avec sceau — il a proposé un prix déraisonnable', '`QUEST:QST_FRE_MAR_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_09', 'NPC_FRE_31', 'K3', '{"sceau","cardinal"}', 'Le sceau est une marque d''identification du Cardinal — il taggue les bêtes dont les données de spawn ont été modifiées pour produire de la chair « persistante » destinée à l''économie souterraine du serveur', NULL, '*(il roule la peau d''un geste brusque et la jette dans un bac)* « C''est une marque de bétail, un point c''est tout. Chaque éleveur a sa marque. Demande à l''Éleveur de Worgs si tu veux en savoir plus. Moi, j''ai du travail. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_31_10', 'NPC_FRE_31', 'KX', '{"*(hors sujet)*"}', '*(il trempe une peau dans l''acide, concentré)* « Le cuir, ça supporte tout sauf les questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_01', 'NPC_FRE_32', 'K0', '{"os","types"}', 'Les types d''os qu''il vend — fémurs, crânes, défenses, griffes ossifiées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_02', 'NPC_FRE_32', 'K0', '{"artisanat","forge"}', 'L''utilisation des os en artisanat — armes, armures, catalyseurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_03', 'NPC_FRE_32', 'K0', '{"provenance","sites"}', 'Les sites de chasse où il se fournit — Collines, Tanière, Savane', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_04', 'NPC_FRE_32', 'K1', '{"os","runes"}', 'L''os gravé de runes inconnues — il le sort de sous son étal à contrecœur', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_05', 'NPC_FRE_32', 'K1', '{"runes","mouvement"}', 'Les runes bougent quand on les regarde en vision périphérique — comme si elles lisaient le regard', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_06', 'NPC_FRE_32', 'K1', '{"taniere","lot"}', 'Le lot venait de la Tanière du Roi Béhémoth — un chasseur les a rapportés, refusant de dire où exactement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_07', 'NPC_FRE_32', 'K2', '{"nuits","lueur"}', 'L''os émet une lueur la nuit — faible, mais suffisante pour projeter les runes sur le mur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_08', 'NPC_FRE_32', 'K2', '{"acheteur","collectionneur"}', 'Un collectionneur masqué propose de l''acheter chaque semaine — il refuse', '`QUEST:QST_FRE_MAR_03`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_09', 'NPC_FRE_32', 'K3', '{"runes","cardinal"}', 'Les runes sont un langage de débogage du Cardinal — l''os est un fragment de la structure de données d''un boss dont la « mort » a laissé un vestige physique dans le monde', NULL, '*(il enveloppe l''os dans un chiffon et le glisse sous l''étal)* « C''est un os ancien avec des gravures décoratives. Les anciens Cait Sith aimaient les motifs. Rien d''autre. Maintenant, tu achètes ou tu déranges ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_32_10', 'NPC_FRE_32', 'KX', '{"*(hors sujet)*"}', '*(il tapote un crâne de worg)* « Celui-ci est magnifique, non ? Les canines sont parfaitement conservées. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_01', 'NPC_FRE_33', 'K0', '{"plumes","collection"}', 'Sa collection de plumes — triées par espèce, couleur, taille, indice de rareté', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_02', 'NPC_FRE_33', 'K0', '{"prix","valeur"}', 'La cote des plumes rares — plume de phénix, rémige de wyverne royale', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_03', 'NPC_FRE_33', 'K0', '{"enchanteurs","usage"}', 'L''utilisation des plumes en enchanterie et en mode — composants de vol, parures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_04', 'NPC_FRE_33', 'K1', '{"plume","phosphorescente"}', 'La plume phosphorescente apparue sur sa chaise — elle brille sans source de lumière', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_05', 'NPC_FRE_33', 'K1', '{"provenance","inconnue"}', 'Il ne sait pas d''où elle vient — aucune espèce connue ne produit cette lueur', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_06', 'NPC_FRE_33', 'K1', '{"pulsations","carnet"}', 'Il note les pulsations de la plume — un rythme régulier qui correspond au cycle jour/nuit du serveur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_07', 'NPC_FRE_33', 'K2', '{"chasseurs","reaction"}', 'La plume palpite plus fort quand certains chasseurs s''approchent — ceux qui reviennent de la Savane', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_08', 'NPC_FRE_33', 'K2', '{"braconnier","lien"}', 'Le Braconnier Banni lui a vendu des plumes rares — la phosphorescente ressemble à une plume qu''il décrivait', '`QUEST:QST_FRE_MAR_04`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_09', 'NPC_FRE_33', 'K3', '{"plume","systeme"}', 'La plume est un artefact de spawn avorté — le Cardinal a tenté de générer une nouvelle espèce de familier et l''instance a échoué ; la plume est un vestige du processus, une « graine » d''espèce jamais née', NULL, '*(il couvre la cage d''un tissu)* « C''est une plume rare, un spécimen unique. Une mutation chromatique. Rien de surnaturel. Si tu n''es pas ici pour acheter, alors laisse-moi classer mes pièces en paix. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_33_10', 'NPC_FRE_33', 'KX', '{"*(hors sujet)*"}', '*(il dispose une plume à côté d''une autre, recule pour juger de l''effet)* « La symétrie est parfaite… Enfin presque. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_01', 'NPC_FRE_34', 'K0', '{"ecailles","types"}', 'Les types d''écailles qu''il vend — dragonnet, wyverne, serpentaire, lézard des roches', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_02', 'NPC_FRE_34', 'K0', '{"armures","artisanat"}', 'L''utilisation des écailles en armurerie — armures légères, boucliers, bardes de familier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_03', 'NPC_FRE_34', 'K0', '{"alchimie","composants"}', 'Les écailles en alchimie — pilées, en décoction, en catalyseur de résistance élémentaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_04', 'NPC_FRE_34', 'K1', '{"ecaille","brulante"}', 'L''écaille qui brûle — elle est incandescente sans source de chaleur', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_05', 'NPC_FRE_34', 'K1', '{"chasseur","disparu"}', 'Le chasseur qui l''a apportée — un Sylph, paniqué, n''est jamais revenu chercher son argent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_06', 'NPC_FRE_34', 'K1', '{"coffre","plomb"}', 'Il la garde dans un coffre doublé de plomb — le métal chauffe quand on s''approche', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_07', 'NPC_FRE_34', 'K2', '{"grimoires","recherche"}', 'Il a cherché dans tous les grimoires — aucune écaille connue, même de dragon ancestral', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_08', 'NPC_FRE_34', 'K2', '{"nuit","lueur"}', 'La nuit, une lueur rouge filtre du coffre malgré le plomb — les gardes ont demandé des explications', '`QUEST:QST_FRE_MAR_04`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_09', 'NPC_FRE_34', 'K3', '{"ecaille","chaleur"}', 'L''écaille est un fragment de la mémoire thermique du serveur — un vestige d''un dragon qui n''a jamais été implémenté mais dont les données de chaleur résident encore dans le noyau du Cardinal', NULL, '*(il recule quand tu t''approches du coffre)* « Touche pas. C''est une curiosité alchimique, rien de plus. Une écaille de dragon des abysses, très rare. Si tu veux une écaille, j''en ai d''autres. Celle-là n''est pas à vendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_34_10', 'NPC_FRE_34', 'KX', '{"*(hors sujet)*"}', '*(il change rapidement de sujet)* « Tu veux voir la nouvelle livraison d''écailles de wyverne ? Très belle qualité. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_01', 'NPC_FRE_35', 'K0', '{"alchimie","sangs"}', 'Les types de sang qu''il vend — sang de worg, de wyverne, de sanglier alpha', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_02', 'NPC_FRE_35', 'K0', '{"potions","catalogue"}', 'Les potions à base de sang — vigueur, résistance au feu, vision nocturne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_03', 'NPC_FRE_35', 'K0', '{"filtration","methode"}', 'Les méthodes de filtration et de conservation du sang de monstre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_04', 'NPC_FRE_35', 'K1', '{"sang","non coagule"}', 'Le sang qui ne coagule pas — il flotte dans sa fiole, tourne lentement', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_05', 'NPC_FRE_35', 'K1', '{"boucher","provenance"}', 'Le Boucher le lui a donné prélevé sur une carcasse qui palpitait', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_06', 'NPC_FRE_35', 'K1', '{"musique","reaction"}', 'Le sang réagit à la musique de la taverne — il s''agite quand le Barde joue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_07', 'NPC_FRE_35', 'K2', '{"taxidermiste","essai"}', 'Il a injecté le sang dans un familier empaillé — les yeux du spécimen ont cligné', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_08', 'NPC_FRE_35', 'K2', '{"nuit","lueur"}', 'La fiole émet une lueur rouge sombre la nuit — synchrone avec la lune du serveur', '`QUEST:QST_FRE_MAR_05`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_09', 'NPC_FRE_35', 'K3', '{"sang","simulation"}', 'Ce sang provient d''une bête dont le Cardinal n''a pas coupé le processus de simulation vitale après la mort — les données circulaires persistent et le sang continue d''exécuter son « rôle » biologique sans organisme hôte', NULL, '*(il pose un linge sur la fiole et verrouille son étal)* « C''est une réaction alchimique rare. Un déséquilibre humoral. Rien que des heures d''étude ne peuvent expliquer — mais ce n''est pas une conversation de marché. Achète tes potions et va-t''en. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_35_10', 'NPC_FRE_35', 'KX', '{"*(hors sujet)*"}', '*(il range ses fioles en murmurant)* « Le sang sait. Le sang se souvient. Le sang… ah, rien. Une blague d''alchimiste. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_01', 'NPC_FRE_36', 'K0', '{"taxidermie","service"}', 'Les services de taxidermie — empaillage, conservation, soclage, restauration', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_02', 'NPC_FRE_36', 'K0', '{"prix","delais"}', 'Les tarifs selon la taille du familier — du rat-griffu au worg de guerre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_03', 'NPC_FRE_36', 'K0', '{"atelier","travail"}', 'Les étapes de l''empaillage — vidage, tannage, bourrage, couture, mise en forme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_04', 'NPC_FRE_36', 'K1', '{"felin","noir"}', 'Le félin noir qu''il a empaillé — un spécimen magnifique ramené de la Savane', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_05', 'NPC_FRE_36', 'K1', '{"oeil","clignement"}', 'L''œil du félin a cligné après l''empaillage — une fois, puis deux', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_06', 'NPC_FRE_36', 'K1', '{"brok","avertissement"}', 'Brok lui a dit : « Certaines bêtes, vaut mieux les laisser où elles sont tombées. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_07', 'NPC_FRE_36', 'K2', '{"serum","alchimiste"}', 'L''Alchimiste Sang lui a donné un sérum à injecter dans le félin « pour la conservation »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_08', 'NPC_FRE_36', 'K2', '{"nuits","bruits"}', 'Depuis, il entend des grattements dans son atelier la nuit — venant du socle du félin', '`QUEST:QST_FRE_MAR_05`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_09', 'NPC_FRE_36', 'K3', '{"empaillage","conscience"}', 'Le félin empaillé est encore « conscient » à cause du sang résiduel non coagulé — ses données nerveuses n''ont pas été purgées par le Cardinal, et le sérum de l''alchimiste a réactivé une boucle réflexe dans les tissus préservés', NULL, '*(il recouvre le félin d''un drap d''un geste brusque)* « Bon, ça suffit. Le félin est un travail d''art, pas un sujet d''étude. Si tu veux un familier empaillé, je te fais un tarif. Sinon, laisse mon atelier. J''ai des commandes. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_36_10', 'NPC_FRE_36', 'KX', '{"*(hors sujet)*"}', '*(il arrange les poils d''un rat-griffu empaillé)* « Celui-ci, au moins, il ne cligne pas de l''œil. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_01', 'NPC_FRE_37', 'K0', '{"braconnage","acces"}', 'Comment le trouver dans les égouts — entrée cachée derrière l''étal du Marchand Plumes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_02', 'NPC_FRE_37', 'K0', '{"especes","protegees"}', 'Les espèces protégées qu''il braconne — classement par rareté et prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_03', 'NPC_FRE_37', 'K0', '{"zephyr","reseau"}', 'Son réseau avec Zephyr — les appâts illégaux, les itinéraires de contrebande', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_04', 'NPC_FRE_37', 'K1', '{"specimen","unique"}', 'Le spécimen sans entrée dans le bestiaire — capturé dans la Savane la semaine dernière', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_05', 'NPC_FRE_37', 'K1', '{"yeux","humains"}', 'La bête a des yeux « trop intelligents » — il jure qu''elle comprend ce qu''il dit', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_06', 'NPC_FRE_37', 'K1', '{"cage","couverte"}', 'Il garde la cage couverte en permanence — la bête s''arrête de bouger quand on la regarde', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_07', 'NPC_FRE_37', 'K2', '{"nuit","voix"}', 'La nuit, il entend une voix qui imite la sienne — venant de la cage', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_08', 'NPC_FRE_37', 'K2', '{"zephyr","interet"}', 'Zephyr veut acheter le spécimen — il propose un prix qui met le braconnier mal à l''aise', '`QUEST:QST_FRE_MAR_06`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_09', 'NPC_FRE_37', 'K3', '{"bete","homme"}', 'La bête est un joueur piégé dans une forme de familier par un bug du Cardinal — un avatar corrompu que le système n''arrive pas à purger et qui erre dans la nature comme un PNJ involontaire', NULL, '*(il tire brusquement le rideau sur la cage)* « Y a rien là-dedans. Une bête rare, c''est tout. Si tu veux pas acheter, casse-toi. Et si tu parles de cette cage à quelqu''un… je saurai que c''est toi. Clarté ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_37_10', 'NPC_FRE_37', 'KX', '{"*(hors sujet)*"}', '*(il compte des pièces en évitant ton regard)* « J''ai plus rien à te dire. Va chasser ailleurs. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_01', 'NPC_FRE_38', 'K0', '{"worgs","vente"}', 'Les worgs qu''il vend — jeunes, adultes, de combat, de monture, alpha', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_02', 'NPC_FRE_38', 'K0', '{"dressage","methodes"}', 'Ses méthodes de dressage — fermeté, récompense, lien d''âme progressif', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_03', 'NPC_FRE_38', 'K0', '{"prix","garantie"}', 'Les prix et la garantie — échange possible si le lien ne prend pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_04', 'NPC_FRE_38', 'K1', '{"croc-noir","comportement"}', 'Croc-Noir — son alpha, qui agit bizarrement depuis des mois', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_05', 'NPC_FRE_38', 'K1', '{"tombe","inconnue"}', 'Le worg s''est allongé devant une tombe de la Colline — celle d''un maître qu''il n''a jamais connu', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_06', 'NPC_FRE_38', 'K1', '{"regard","horizon"}', 'Le worg fixe l''horizon et gémit — toujours à la même heure, au crépuscule', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_07', 'NPC_FRE_38', 'K2', '{"autres","worgs"}', 'D''autres worgs de l''enclos commencent à imiter Croc-Noir — ils fixent tous le même point', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_08', 'NPC_FRE_38', 'K2', '{"colline","elara"}', 'Elara lui a dit que Croc-Noir sent « l''odeur des âmes qui s''attardent »', '`QUEST:QST_FRE_MAR_07`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_09', 'NPC_FRE_38', 'K3', '{"worg","lien"}', 'Les worgs perçoivent les âmes des familiers que la Colline retient prisonnières — Croc-Noir ne reconnaît pas un maître mort, il perçoit la présence d''âmes en attente dont le Cardinal n''a pas terminé le recyclage', NULL, '*(il siffle Croc-Noir qui vient se coucher à ses pieds)* « Les worgs ont des instincts. Parfois ils sentent des choses qu''on comprend pas. C''est tout. Y a rien de surnaturel là-dedans. Maintenant, tu veux acheter un worg ou tu veux faire un reportage ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_38_10', 'NPC_FRE_38', 'KX', '{"*(hors sujet)*"}', '*(il gratte Croc-Noir derrière les oreilles)* « Lui au moins, il pose pas de questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_01', 'NPC_FRE_39', 'K0', '{"annonces","marche"}', 'Les annonces du jour — arrivages, ventes, avis de recherche, événements', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_02', 'NPC_FRE_39', 'K0', '{"crieuse","metier"}', 'Son métier de crieuse publique — elle déambule et annonce tout ce qu''on lui paie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_03', 'NPC_FRE_39', 'K0', '{"marche","vie"}', 'La vie du Marché aux Crocs — les étals, les heures d''affluence, les personnages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_04', 'NPC_FRE_39', 'K1', '{"disparitions","etranges"}', 'Des avis de recherche de familiers rares — tous disparus près de la Colline', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_05', 'NPC_FRE_39', 'K1', '{"carnet","liste"}', 'Son carnet — elle note chaque disparition, la date, le lieu, le type de familier', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_06', 'NPC_FRE_39', 'K1', '{"maitres","silencieux"}', 'Les maîtres des disparus évitent de donner des détails — comme s''ils avaient peur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_07', 'NPC_FRE_39', 'K2', '{"motif","colline"}', 'Tous les disparus ont été vus près de la Colline aux Souvenirs — à la nuit tombée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_08', 'NPC_FRE_39', 'K2', '{"marcheur","souvenirs"}', 'Le Marchand de Souvenirs lui a confié que certains objets de familiers disparus réapparaissent sur son étal', '`QUEST:QST_FRE_MAR_07`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_09', 'NPC_FRE_39', 'K3', '{"famille","disparus"}', 'Les familiers ne disparaissent pas — ils sont « rappelés » par le Cardinal pour correction de données ; leurs maîtres reçoivent une notification les déclarant morts, mais ils sont simplement retirés du jeu, et leurs souvenirs sont la seule trace qui reste', NULL, '*(elle plie son carnet et le range vivement)* « Des disparitions, y en a toujours. Les familiers fuguent, les maîtres oublient de les rappeler… c''est triste mais c''est la vie. Moi je crie les annonces, c''est tout. Je cherche pas à comprendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_39_10', 'NPC_FRE_39', 'KX', '{"*(hors sujet)*"}', '*(elle reprend sa tournée d''une voix claire)* « Avis de recherche ! Si vous avez vu un félin noir… »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_01', 'NPC_FRE_40', 'K0', '{"taverne","carte"}', 'La carte du Chat Botté — poisson grillé, hydromel, viande séchée, soupe de saison', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_02', 'NPC_FRE_40', 'K0', '{"buffs","plats"}', 'Les buffs des plats — le poisson grillé donne +AGI, la soupe +END', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_03', 'NPC_FRE_40', 'K0', '{"clients","habitués"}', 'Les habitués de la taverne — chasseurs, dresseurs, parieurs, marchands', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_04', 'NPC_FRE_40', 'K1', '{"chuchotements","nuit"}', 'Les chuchotements dans les murs la nuit — il les entend depuis six mois', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_05', 'NPC_FRE_40', 'K1', '{"pretre","benediction"}', 'Le prêtre venu bénir la taverne est reparti livide sans explication', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_06', 'NPC_FRE_40', 'K1', '{"serveuse","temoin"}', 'La Serveuse `FRE_41` les a entendus aussi — elle ne travaille plus le soir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_07', 'NPC_FRE_40', 'K2', '{"mur","provenance"}', 'Les chuchotements viennent d''un mur en particulier — le mur nord, côté Colline', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_08', 'NPC_FRE_40', 'K2', '{"barde","couverture"}', 'Le Barde Félin couvre les bruits avec sa musique — sans le savoir', '`QUEST:QST_FRE_CHA_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_09', 'NPC_FRE_40', 'K3', '{"murmures","colline"}', 'Les chuchotements sont une fuite acoustique du caveau de données sous la Colline aux Souvenirs — la taverne est construite sur une poche de résonance où les données d''âmes stockées par le Cardinal deviennent audibles la nuit', NULL, '*(il essuie un verre en faisant exprès de ne pas te regarder)* « Les vieilles tavernes craquent, c''est tout. Le bois qui travaille. Les pierres qui se tassent. Y a pas de mystère. Tu veux un autre poisson ? Je te le fais gratuit, mais on change de sujet. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_40_10', 'NPC_FRE_40', 'KX', '{"*(hors sujet)*"}', '*(il te sert une bière d''autorité)* « Tiens, bois. Ça fait passer les questions inutiles. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_01', 'NPC_FRE_41', 'K0', '{"service","horaires"}', 'Le service du Chat Botté — elle sert du midi, ne travaille pas le soir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_02', 'NPC_FRE_41', 'K0', '{"clients","habitués"}', 'Les clients réguliers et leurs habitudes — elle connaît leurs commandes par cœur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_03', 'NPC_FRE_41', 'K0', '{"taverne","ambiance"}', 'L''ambiance de la taverne — joyeuse le jour, étrange la nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_04', 'NPC_FRE_41', 'K1', '{"client","solitaire"}', 'Le vieux client qui parle à une chaise vide — il commande toujours deux bières', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_05', 'NPC_FRE_41', 'K1', '{"voix","inaudibles"}', 'Elle a essayé d''écouter ce qu''il dit — des phrases en vieux cait shith, des noms de bêtes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_06', 'NPC_FRE_41', 'K1', '{"chaises","table"}', 'Personne d''autre ne semble voir la « présence » en face de lui', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_07', 'NPC_FRE_41', 'K2', '{"client","description"}', 'Le vieux client — une cicatrice en travers du visage, des yeux vides, un médaillon en forme de patte', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_08', 'NPC_FRE_41', 'K2', '{"parieur","ecoute"}', 'Le Parieur Arène s''assoît toujours près du mur nord — il colle l''oreille au mur en croyant que personne ne regarde', '`QUEST:QST_FRE_CHA_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_09', 'NPC_FRE_41', 'K3', '{"client","spectre"}', 'Le vieux client converse avec le fantôme de son familier, que seul lui peut voir — un effet de bord du caveau de données : certains joueurs avec un haut niveau d''affinité avec leur familier défunt peuvent percevoir les résidus d''âme que le Cardinal n''a pas effacés', NULL, '*(elle fait tomber un verre exprès pour changer de sujet)* « Oh ! Désolée, je suis maladroite… Tu disais ? Non, oublie, je dois servir la table 3. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_41_10', 'NPC_FRE_41', 'KX', '{"*(hors sujet)*"}', '*(elle s''éloigne rapidement)* « Je… je reviens. Commande sans moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_01', 'NPC_FRE_42', 'K0', '{"barde","repertoire"}', 'Son répertoire — chansons de chasse, ballades de héros, complaintes anciennes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_02', 'NPC_FRE_42', 'K0', '{"musique","taverne"}', 'Son rôle au Chat Botté — il anime les soirées, prend les demandes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_03', 'NPC_FRE_42', 'K0', '{"instruments","luth"}', 'Son luth à cordes de boyau de wyverne — fabriqué par un artisan Sylph', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_04', 'NPC_FRE_42', 'K1', '{"complainte","effet"}', 'La Complainte du Premier Familier — les familiers fuient quand il la chante', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_05', 'NPC_FRE_42', 'K1', '{"silence","murs"}', 'Les chuchotements dans les murs s''arrêtent pendant la Complainte', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_06', 'NPC_FRE_42', 'K1', '{"paroles","anciennes"}', 'Les paroles parlent d''une bête « née du souffle du monde, avant les clés et les portes »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_07', 'NPC_FRE_42', 'K2', '{"origine","complainte"}', 'Il tient la Complainte de sa grand-mère — qui la tenait de la sienne — transmission orale', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_08', 'NPC_FRE_42', 'K2', '{"cuisinier","plainte"}', 'Le Cuisinier Gibier lui a demandé d''arrêter — « la viande se met à bouger sur le billot »', '`QUEST:QST_FRE_CHA_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_09', 'NPC_FRE_42', 'K3', '{"complainte","clef"}', 'La Complainte du Premier Familier est une séquence audio qui interfère avec les données d''âmes stockées sous la Colline — les vibrations des cordes de wyverne créent une résonance qui brouille temporairement le caveau du Cardinal, ce qui explique pourquoi les chuchotements cessent', NULL, '*(il pose son luth et croise les bras)* « C''est une chanson, un point c''est tout. Les gens aiment les histoires de fantômes et de bêtes anciennes. Si les familiers s''enfuient, c''est qu''ils ont mauvais goût musical. Maintenant, tu veux une demande ou tu critiques le spectacle ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_42_10', 'NPC_FRE_42', 'KX', '{"*(hors sujet)*"}', '*(il accorde son luth en fredonnant)* « La prochaine, c''est une ballade de chasse. Plus calme. Promis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_01', 'NPC_FRE_43', 'K0', '{"cuisine","carte"}', 'Les plats de gibier — civet, brochettes, pâté, ragoût, grillades', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_02', 'NPC_FRE_43', 'K0', '{"ingredient","secret"}', 'L''ingrédient secret du plat signature — il ne le révèle à personne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_03', 'NPC_FRE_43', 'K0', '{"fournisseurs","marche"}', 'Ses fournisseurs habituels — Boucher Marché, Marchand de Gibier, chasseurs locaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_04', 'NPC_FRE_43', 'K1', '{"ingredient","doute"}', 'L''ingrédient bon marché du nouveau fournisseur — il a un goût qu''il ne connaît pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_05', 'NPC_FRE_43', 'K1', '{"etiquette","sceau"}', 'L''étiquette de la dernière livraison portait un sceau — celui des espèces protégées', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_06', 'NPC_FRE_43', 'K1', '{"viande","mouvement"}', 'Quand le Barde joue la Complainte, la viande crue bouge sur le billot', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_07', 'NPC_FRE_43', 'K2', '{"fournisseur","masque"}', 'Le fournisseur porte toujours un capuchon — il livre la nuit, refuse de parler', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_08', 'NPC_FRE_43', 'K2', '{"registre","menagerie"}', 'Il a vu le même sceau sur un registre à la Ménagerie Royale — liste des espèces interdites', '`QUEST:QST_FRE_CHA_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_09', 'NPC_FRE_43', 'K3', '{"viande","familier"}', 'L''ingrédient est de la chair de familiers « recyclés » par le Cardinal — des bêtes dont les données ont été purgées mais dont les corps sont revendus dans le circuit noir via le Marché aux Os', NULL, '*(il jette un torchon sur le billot)* « C''est de la viande de chasse, point. Je suis cuisinier, pas détective. Si le goût est bon et que les clients sont contents, j''ai pas à poser de questions. Et toi non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_43_10', 'NPC_FRE_43', 'KX', '{"*(hors sujet)*"}', '*(il retourne à ses fourneaux)* « Le civet attend. Reviens goûter, c''est me permettre de cuisiner. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_01', 'NPC_FRE_44', 'K0', '{"paris","fonctionnement"}', 'Les règles des paris — mises, cotes, combats, horaires des arènes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_02', 'NPC_FRE_44', 'K0', '{"combats","arenes"}', 'Les arènes de combat de familiers à Freelia — officielles et clandestines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_03', 'NPC_FRE_44', 'K0', '{"dresseurs","palmares"}', 'Le palmarès des dresseurs et de leurs bêtes qui participent aux combats', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_04', 'NPC_FRE_44', 'K1', '{"combats","arranges"}', 'Il reconnaît les combats arrangés — certaines bêtes ne peuvent pas perdre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_05', 'NPC_FRE_44', 'K1', '{"carnet","motifs"}', 'Il note les gains des mêmes dresseurs — ils gagnent toujours, contre toute logique', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_06', 'NPC_FRE_44', 'K1', '{"bêtes","infaillibles"}', 'Les bêtes infaillibles — il les a vues combattre des adversaires bien plus forts et gagner', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_07', 'NPC_FRE_44', 'K2', '{"dresseurs","masques"}', 'Les dresseurs qui ne perdent jamais portent tous un accessoire similaire — une plume grise à la ceinture', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_08', 'NPC_FRE_44', 'K2', '{"plume","marchand"}', 'La plume grise ressemble à celles que vend le Marchand Plumes `FRE_33` — un lot « spécial »', '`QUEST:QST_FRE_CHA_03`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_09', 'NPC_FRE_44', 'K3', '{"combats","script"}', 'Les combats sont scriptés par le Cardinal — certains familiers reçoivent un buff invisible qui garantit leur victoire ; le système « équilibre » les paris en faveur de quelques dresseurs choisis pour maintenir l''économie du jeu', NULL, '*(il referme son carnet d''un coup sec)* « Les paris, c''est de la probabilité et du talent. Si certains gagnent plus que d''autres, c''est qu''ils sont meilleurs. C''est comme ça. Tu veux parier ou tu veux philosopher ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_44_10', 'NPC_FRE_44', 'KX', '{"*(hors sujet)*"}', '*(il compte des pièces)* « J''ai un pari sur le prochain combat. Tu me fais perdre mon temps. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_01', 'NPC_FRE_45', 'K0', '{"auberge","chambres"}', 'Les chambres du Chat Botté — prix, confort, vue, disponibilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_02', 'NPC_FRE_45', 'K0', '{"services","auberge"}', 'Les services — bagagerie, bain, repas en chambre, réveil personnalisé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_03', 'NPC_FRE_45', 'K0', '{"clients","longs sejours"}', 'Les clients qui logent à l''année — commerçants, dresseurs itinérants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_04', 'NPC_FRE_45', 'K1', '{"chambre","7"}', 'La chambre 7 — fermée « pour travaux », jamais louée depuis des mois', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_05', 'NPC_FRE_45', 'K1', '{"odeur","animale"}', 'Les clients qui ont dormi dans la 7 parlent d''une odeur de bête sauvage qui imprégnait tout', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_06', 'NPC_FRE_45', 'K1', '{"respiration","nuit"}', 'Certains ont entendu une respiration lourde sous le lit — malgré le lit contre le mur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_07', 'NPC_FRE_45', 'K2', '{"condamnation","porte"}', 'Elle a condamné la porte avec des planches — l''odeur traverse le bois', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_08', 'NPC_FRE_45', 'K2', '{"concierge","ronron"}', 'Le Concierge lui a dit que les coffres du sous-sol ronronnent juste sous la chambre 7', '`QUEST:QST_FRE_CHA_04`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_09', 'NPC_FRE_45', 'K3', '{"chambre","portail"}', 'La chambre 7 est construite sur un ancien point de spawn du Cardinal, désactivé mais pas purgé — l''odeur et la respiration sont les vestiges d''une instance de bête qui n''a jamais été retirée du code et dont les données de présence persistent dans la mémoire du lieu', NULL, '*(elle croise les bras et son regard se durcit)* « La 7 est fermée, un point c''est tout. Si t''es pas content, y a une auberge à la Porte. Je te rends ton dépôt si tu veux. Mais je rouvrirai pas cette porte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_45_10', 'NPC_FRE_45', 'KX', '{"*(hors sujet)*"}', '*(elle te tend une clé)* « Chambre 3, deuxième à droite. Les draps sont frais. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_01', 'NPC_FRE_46', 'K0', '{"coffres","securite"}', 'Les coffres de l''auberge — tailles, prix, durée de location, sécurité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_02', 'NPC_FRE_46', 'K0', '{"sous-sol","acces"}', 'L''accès au sous-sol — réservé aux clients, surveillé jour et nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_03', 'NPC_FRE_46', 'K0', '{"clefs","trousseau"}', 'Son trousseau de clés — il a la clé de chaque coffre, sauf une', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_04', 'NPC_FRE_46', 'K1', '{"coffre","11"}', 'Le coffre 11 émet un ronronnement régulier — on dirait un chat endormi', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_05', 'NPC_FRE_46', 'K1', '{"clef","perdue"}', 'La clé du 11 a été perdue par un aventurier parti chasser le Roi Béhémoth — jamais revenu', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_06', 'NPC_FRE_46', 'K1', '{"nom","reaction"}', 'Le ronronnement s''intensifie quand il prononce « Griffe d''Ombre » — il l''a testé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_07', 'NPC_FRE_46', 'K2', '{"ronron","origine"}', 'Le ronronnement vient de l''intérieur du coffre — pas de la serrure ou des gonds', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_08', 'NPC_FRE_46', 'K2', '{"itinerant","temoin"}', 'Le Marchand Itinérant a vu un coffre identique à Alne — dans une auberge, il ronronnait aussi', '`QUEST:QST_FRE_CHA_04`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_09', 'NPC_FRE_46', 'K3', '{"coffre","familier"}', 'Le coffre 11 contient le familier empaillé de l''aventurier disparu — mais le ronronnement indique que les données d''âme du familier sont encore actives, piégées dans un objet que le Cardinal n''a pas réussi à recycler', NULL, '*(il tourne la clé du coffre 11 dans la serrure pour la forme)* « Y a un mécanisme, c''est tout. Les vieux coffres font des bruits. Si tu veux un coffre silencieux, prends le 4. Bonne nuit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_46_10', 'NPC_FRE_46', 'KX', '{"*(hors sujet)*"}', '*(il s''éloigne en grommelant)* « Trop de questions. Les coffres, c''est fait pour fermer, pas pour parler. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_01', 'NPC_FRE_47', 'K0', '{"itineraire","commerce"}', 'Ses itinéraires — Freelia, Alne, Swilvane, et les routes secondaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_02', 'NPC_FRE_47', 'K0', '{"marchandises","catalogue"}', 'Les marchandises qu''il transporte — tissus, épices, composants rares, nouvelles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_03', 'NPC_FRE_47', 'K0', '{"cités","differences"}', 'Les différences entre les cités — ambiance, prix, dangers, personnalités locales', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_04', 'NPC_FRE_47', 'K1', '{"alne","coffre"}', 'À Alne, un coffre ronronne dans une auberge — comme celui du Chat Botté', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_05', 'NPC_FRE_47', 'K1', '{"swilvane","plume"}', 'À Swilvane, une prêtresse Sylph a une plume qui brille — comme celle de Freelia', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_06', 'NPC_FRE_47', 'K1', '{"carnet","route"}', 'Son carnet de route — il note tous les objets « anormaux » qu''il croise', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_07', 'NPC_FRE_47', 'K2', '{"signature","commune"}', 'Les objets anormaux partagent un motif commun — un sceau invisible qui apparaît sous certaines lumières', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_08', 'NPC_FRE_47', 'K2', '{"alchimiste","alne"}', 'Un alchimiste d''Alne `NPC_ALN_*` a identifié le sceau — « marque de rémanence de données »', '`QUEST:QST_FRE_ITI_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_09', 'NPC_FRE_47', 'K3', '{"reseau","cardinal"}', 'Les objets anormaux sont des « fuites » du Cardinal réparties dans toutes les cités — le système disperse les données d''âme non recyclées à travers le serveur pour éviter leur détection, créant un réseau d''artefacts liés par une signature de rémanence commune', NULL, '*(il referme son carnet et le range dans sa sacoche)* « Les marchands voyagent, on voit des choses, on entend des rumeurs. Des coïncidences, rien de plus. Si tu veux acheter, j''ai de la soie d''Alne. Si tu veux des théories du complot, va voir les Oracle sur la Colline. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_47_10', 'NPC_FRE_47', 'KX', '{"*(hors sujet)*"}', '*(il sort un rouleau de soie)* « Regarde cette couleur — elle vient directement des teinturiers d''Alne. Unique. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_01', 'NPC_FRE_48', 'K0', '{"recel","acces"}', 'Comment le trouver — entrée cachée derrière la cloison, mot de passe changeant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_02', 'NPC_FRE_48', 'K0', '{"marchandise","catalogue"}', 'Ce qu''il achète et revend — espèces protégées, œufs rares, viande suspecte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_03', 'NPC_FRE_48', 'K0', '{"zephyr","reseau"}', 'Son réseau avec Zephyr — les itinéraires de contrebande des Collines de l''Ouest', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_04', 'NPC_FRE_48', 'K1', '{"oeufs","dragon"}', 'Les œufs de dragon achetés à Zephyr — l''un d''eux a éclos il y a trois nuits', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_05', 'NPC_FRE_48', 'K1', '{"creature","inconnue"}', 'Ce qui est sorti de l''œuf n''est pas un dragon — une créature sans entrée dans le bestiaire', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_06', 'NPC_FRE_48', 'K1', '{"yeux","rouges"}', 'La créature a des yeux rouges qui brillent dans le noir — elle ne cligne jamais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_07', 'NPC_FRE_48', 'K2', '{"cage","marques"}', 'La cage porte des marques de griffes — l''intérieur, pas l''extérieur — chaque matin', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_08', 'NPC_FRE_48', 'K2', '{"zephyr","silence"}', 'Zephyr ne répond plus à ses messages depuis l''éclosion — comme s''il savait', '`QUEST:QST_FRE_BM_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_09', 'NPC_FRE_48', 'K3', '{"oeuf","cardinal"}', 'L''œuf n''était pas un œuf de dragon — c''était un conteneur de données du Cardinal, une instance d''espèce avortée dont les codes génétiques se sont matérialisés en une créature imprévue ; la bête dans la cage est un bug vivant, un fragment d''implémentation inachevée', NULL, '*(il jette un tissu sur la cage d''un geste brusque)* « C''est une bestiole rare, un élevage exotique. Rien d''anormal. Si t''es pas intéressé, barre-toi. Et si tu parles de ça à quelqu''un… je te retrouverai. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_48_10', 'NPC_FRE_48', 'KX', '{"*(hors sujet)*"}', '*(il vérifie que personne n''écoute)* « T''as pas vu de cage. T''as pas entendu de bruit. Dégage. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_01', 'NPC_FRE_49', 'K0', '{"domptage","tutoriel"}', 'Les bases du domptage — appâtage, capture, lien d''âme, soins', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_02', 'NPC_FRE_49', 'K0', '{"appats","gratuits"}', 'Les appâts gratuits pour débutants — il en distribue depuis son poste', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_03', 'NPC_FRE_49', 'K0', '{"place","principale"}', 'La Place Principale de Freelia — centre névralgique, point d''accueil des nouveaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_04', 'NPC_FRE_49', 'K1', '{"felin","tremblement"}', 'Son félin des brumes tremble quand il explique le lien d''âme à son poste', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_05', 'NPC_FRE_49', 'K1', '{"formule","reaction"}', 'La formule de lien ne provoque la réaction que prononcée sur la Place', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_06', 'NPC_FRE_49', 'K1', '{"gravures","cercle"}', 'Sous la pierre de la place, il a trouvé des gravures en cercle — un motif ancien', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_07', 'NPC_FRE_49', 'K2', '{"cercle","runique"}', 'Les gravures forment un cercle runique — il en a frotté une partie pour la déchiffrer', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_08', 'NPC_FRE_49', 'K2', '{"guide","savane"}', 'Le Guide Savane `FRE_11` lui a dit que le même cercle existe sous la Savane des Crocs', '`QUEST:QST_FRE_GUI_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_09', 'NPC_FRE_49', 'K3', '{"cercle","domptage"}', 'Le cercle gravé sous la Place est l''ancrage physique du système de domptage d''ALO — le Cardinal utilise ces runes pour diffuser le signal de lien d''âme dans toute la zone ; le cercle est une antenne de données, et les « réactions » du félin sont des interférences avec le signal de base du serveur', NULL, '*(son félin se cache derrière ses jambes)* « Le sol ? De la pierre ordinaire, rien de spécial. Des décorations anciennes. On les voit partout dans Freelia. Tu veux ton appât gratuit ou pas ? J''ai d''autres nouveaux à accueillir. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_49_10', 'NPC_FRE_49', 'KX', '{"*(hors sujet)*"}', '*(il te tend un appât avec un sourire forcé)* « Tiens, un appât de base. Va faire un tour dans la Savane. Tu reviens si tu as des questions — enfin, si je suis encore là. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_01', 'NPC_FRE_50', 'K0', '{"tour","observation"}', 'Description de la Tour d''Observation — hauteur, vue, équipement de vigie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_02', 'NPC_FRE_50', 'K0', '{"horaire","garde"}', 'Son quart de guet — de l''aube à midi, relève par le Signaleur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_03', 'NPC_FRE_50', 'K0', '{"carnet","croquis"}', 'Elle tient un carnet de bord illustré de tout ce qu''elle voit dans la journée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_04', 'NPC_FRE_50', 'K1', '{"lumieres","savane"}', 'Des lumières dorées apparaissent au-dessus de la Savane des Crocs à l''aube, exactement trois secondes avant le lever du soleil', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_05', 'NPC_FRE_50', 'K1', '{"disparition","notes"}', 'Ses croquis des lumières s''effacent de son carnet pendant la nuit — l''encre redevient vierge', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_06', 'NPC_FRE_50', 'K1', '{"anya","complicite"}', 'Anya `FRE_06` lui a prêté une pierre de vision — les lumières apparaissent en vert, pas en doré', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_07', 'NPC_FRE_50', 'K2', '{"motif","lueurs"}', 'Les lumières dessinent une séquence — trois flashes brefs, une pause, un long — comme un code', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_08', 'NPC_FRE_50', 'K2', '{"absence","traces"}', 'Elle est montée de nuit guetter — les lumières étaient là, mais le sable de la Savane en contrebas ne portait aucune trace de source lumineuse', '`QUEST:QST_FRE_TOUR_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_09', 'NPC_FRE_50', 'K3', '{"porte","ciel"}', 'Les lumières ne viennent pas du ciel — elles viennent d''entre les couches du monde, une déchirure que le Cardinal a mal recousue', NULL, '*(elle referme son carnet d''un coup sec)* « Des déchirures entre les couches ? Je suis éclaireuse, pas oracle. Je vois des lumières, c''est tout. Si tu veux des légendes, va voir l''Astrologue. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_50_10', 'NPC_FRE_50', 'KX', '{"*(hors sujet)*"}', '« L''horizon est dégagé. Demande-moi ça un autre jour. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_01', 'NPC_FRE_51', 'K0', '{"cartes","vente"}', 'Vente de cartes de la région — routes, zones de chasse, points d''eau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_02', 'NPC_FRE_51', 'K0', '{"atelier","outils"}', 'Son atelier — tables à dessin, encres de sève, parchemins traités', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_03', 'NPC_FRE_51', 'K0', '{"expeditions","equipes"}', 'Les quatre expéditions qu''il a organisées vers l''ouest — équipages, durée, échec', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_04', 'NPC_FRE_51', 'K1', '{"zone","blanche"}', 'La zone blanche s''étend — elle gagne un centimètre sur sa carte chaque lune', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_05', 'NPC_FRE_51', 'K1', '{"temoins","brouillard"}', 'Les éclaireurs qui s''en approchent parlent d''un brouillard sec qui sent l''ozone', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_06', 'NPC_FRE_51', 'K1', '{"reves","plaine"}', 'Il rêve d''une plaine vide chaque nuit — exactement la même, avec un arbre mort au milieu', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_07', 'NPC_FRE_51', 'K2', '{"cartes","astrologue"}', 'La carte stellaire de Stella `FRE_53` montre le même blanc au même endroit — une absence d''étoiles que rien n''explique', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_08', 'NPC_FRE_51', 'K2', '{"retour","expedition"}', 'Un éclaireur de la dernière expédition est revenu — il répète en boucle « Il n''y a rien », mais sa boussole tourne en permanence', '`QUEST:QST_FRE_CARTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_09', 'NPC_FRE_51', 'K3', '{"effacement","cardinal"}', 'La zone blanche n''est pas inexplorée — elle est effacée. Le Cardinal retire la zone du référentiel partagé chaque nuit, et Theron la redessine chaque matin sans le savoir', NULL, '*(il passe la main sur la zone blanche comme pour la lisser)* « Effacée ? Non, c''est juste… inexploré. Forcément. J''ai pas envoyé assez de monde. C''est une question de moyens, pas de… de… » *(sa voix se perd)*');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_51_10', 'NPC_FRE_51', 'KX', '{"*(hors sujet)*"}', '« Les cartes sont à l''étal. Si tu veux causer, prends-en une. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_01', 'NPC_FRE_52', 'K0', '{"signaux","code"}', 'Les codes optiques de Freelia — couleurs, séquences, significations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_02', 'NPC_FRE_52', 'K0', '{"outils","miroirs"}', 'Ses outils — miroirs de cuivre, lanternes à cristal, drapeaux de jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_03', 'NPC_FRE_52', 'K0', '{"patrouilles","routine"}', 'Le réseau de patrouilles qu''elle couvre — horaires, itinéraires, relais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_04', 'NPC_FRE_52', 'K1', '{"signal","anonyme"}', 'Elle capte un signal régulier du sud-ouest — personne n''est posté là-bas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_05', 'NPC_FRE_52', 'K1', '{"sequence","message"}', 'La séquence : trois longs, deux brefs, un long — « ICI… PERSONNE… RÉPOND… »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_06', 'NPC_FRE_52', 'K1', '{"silence","reponse"}', 'Depuis qu''elle y a répondu, le signal s''est tu — mais elle sent qu''on l''écoute encore', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_07', 'NPC_FRE_52', 'K2', '{"direction","concordance"}', 'La direction du signal correspond exactement à l''endroit où Lila `FRE_50` voit ses lumières — au mètre près', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_08', 'NPC_FRE_52', 'K2', '{"miroir","autonome"}', 'Elle a laissé son miroir braqué vers le sud-ouest une nuit — au matin, le miroir avait pivoté tout seul de trois degrés', '`QUEST:QST_FRE_SIGNAL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_09', 'NPC_FRE_52', 'K3', '{"origine","cardinal"}', 'Le signal n''est pas envoyé par un PNJ ni un joueur — c''est un artefact du Cardinal, un écho de maintenance du serveur qui n''a pas été correctement désactivé, une boucle de communication orpheline', NULL, '*(elle range ses miroirs dans leur étui sans le regarder)* « Un écho du Cardinal ? Je suis signaleuse. Je transmets des messages entre vivants. Pas entre… machins. Si tu veux des théories, va voir le Stratège. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_52_10', 'NPC_FRE_52', 'KX', '{"*(hors sujet)*"}', '« Le ciel est calme aujourd''hui. Pas de message. Reviens un autre jour. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_01', 'NPC_FRE_53', 'K0', '{"astrologie","caitsith"}', 'Les bases de l''astrologie Cait Sith — constellations, cycles, présages de domptage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_02', 'NPC_FRE_53', 'K0', '{"telescope","tour"}', 'Son télescope — un immense tube de cristal et de bois au sommet de la Tour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_03', 'NPC_FRE_53', 'K0', '{"constellations","carte"}', 'Les constellations de Freelia — le Dompteur, la Meute, l''Œil Fauve', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_04', 'NPC_FRE_53', 'K1', '{"etoile","anomalie"}', 'Une étoile fixe dans une zone du ciel qui devrait être vide — elle ne clignote pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_05', 'NPC_FRE_53', 'K1', '{"croissance","lente"}', 'L''étoile grossit de quelques secondes d''arc chaque nuit — elle sera visible à l''œil nu dans un mois', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_06', 'NPC_FRE_53', 'K1', '{"silence","ciel"}', 'Les autres étoiles semblent s''écarter de celle-ci — comme si la voûte céleste la fuyait', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_07', 'NPC_FRE_53', 'K2', '{"cartes","theron"}', 'Sur les cartes stellaires qu''elle a données à Theron `FRE_51`, l''étoile apparaît aussi — au même endroit que sa zone blanche terrestre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_08', 'NPC_FRE_53', 'K2', '{"messagers","etoile"}', 'Des chouettes messagères évitent de voler sous cette étoile — elle les a vues faire un détour', '`QUEST:QST_FRE_ASTRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_09', 'NPC_FRE_53', 'K3', '{"satellite","cardinal"}', 'L''étoile n''est pas un astre — c''est un satellite d''observation du Cardinal, un nœud de scan qui cartographie les émotions des joueurs pour ajuster les paramètres de la zone ; il est coincé en position fixe à cause d''un bug non résolu de la D17', NULL, '*(elle éteint son télescope et se tourne vers lui, les yeux plissés)* « Un nœud de scan du Cardinal ? Les étoiles sont les étoiles. Le ciel est le ciel. Si tu vois des machines là-haut, tu regardes avec les mauvais yeux. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_53_10', 'NPC_FRE_53', 'KX', '{"*(hors sujet)*"}', '« Les étoiles parlent à qui sait écouter. Toi, tu cries. Reviens quand tu sauras chuchoter. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_01', 'NPC_FRE_54', 'K0', '{"defense","freelia"}', 'Les défenses de Freelia — remparts, tours, garnison, temps de réaction', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_02', 'NPC_FRE_54', 'K0', '{"patrouilles","itineraires"}', 'Les itinéraires des patrouilles — horaires, effectifs, zones couvertes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_03', 'NPC_FRE_54', 'K0', '{"ennemis","connus"}', 'Les menaces connues — Salamanders à la frontière, monstres errants, braconniers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_04', 'NPC_FRE_54', 'K1', '{"ombres","savane"}', 'Elle voit des formations militaires dans la Savane — fantassins, éclaireurs, arrière-garde', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_05', 'NPC_FRE_54', 'K1', '{"feux","camps"}', 'Des feux de camp s''allument la nuit et s''éteignent à l''aube — sans cendres, sans traces', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_06', 'NPC_FRE_54', 'K1', '{"rapports","vides"}', 'Les patrouilles qu''elle envoie sur zone reviennent avec des rapports vierges — « Rien signalé »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_07', 'NPC_FRE_54', 'K2', '{"carte","inconnue"}', 'Sa carte de guerre personnelle est couverte de marques — elle suit une campagne militaire depuis trois mois, mais personne n''y participe', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_08', 'NPC_FRE_54', 'K2', '{"testament","strategique"}', 'Elle a rédigé un plan de bataille détaillé pour une invasion qui n''aura peut-être jamais lieu — elle l''a caché dans le socle de la Tour', '`QUEST:QST_FRE_ARMEE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_09', 'NPC_FRE_54', 'K3', '{"projection","egregores"}', 'Les ombres qu''elle voit sont des projections résiduelles d''une simulation de guerre que le Cardinal a exécutée sur Freelia il y a six mois — les égrégores tactiques n''ont pas été correctement désactivés et continuent leur routine de combat dans une boucle invisible', NULL, '*(elle pointe un doigt tremblant sur sa carte)* « Des égrégores ? Des simulations ? J''ai passé ma vie à lire le terrain. Ce que je vois est réel. Si le Cardinal fait des simulations de guerre sur ma ville à mon insu… » *(elle serre le poing)* « …je préfère ne pas y penser. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_54_10', 'NPC_FRE_54', 'KX', '{"*(hors sujet)*"}', '« Si t''es pas dans l''armée, dégage de mon quartier général. Les civils, c''est en bas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_01', 'NPC_FRE_55', 'K0', '{"retraite","eclaireur"}', 'Sa vie d''éclaireur — les expéditions, les dangers, les nuits à la belle étoile', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_02', 'NPC_FRE_55', 'K0', '{"conseils","survie"}', 'Conseils de survie dans la Savane — pièges, plantes, abris', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_03', 'NPC_FRE_55', 'K0', '{"silhouette","tour"}', 'Il taille du bois au pied de la Tour tous les jours — des figurines d''oiseaux qu''il donne aux enfants', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_04', 'NPC_FRE_55', 'K1', '{"derniere","mission"}', 'Sa dernière mission était dans l''ouest — il y est resté trois semaines, seul', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_05', 'NPC_FRE_55', 'K1', '{"carte","brulee"}', 'Il a brûlé sa carte le soir de son retour — il ne dit pas pourquoi, mais ses mains tremblent quand on en parle', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_06', 'NPC_FRE_55', 'K1', '{"figurines","oiseaux"}', 'Les oiseaux qu''il taille ressemblent tous à la même espèce — un oiseau qu''il n''a jamais vu nulle part autour de Freelia', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_07', 'NPC_FRE_55', 'K2', '{"decouverte","ouest"}', 'Il a trouvé une structure dans la zone blanche — une tour noire qui n''est sur aucun plan, d''où sort un bourdonnement', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_08', 'NPC_FRE_55', 'K2', '{"voix","tour"}', 'Il a entendu une voix dans sa tête près de la tour — elle disait « Ici commence ce qui n''a pas de fin »', '`QUEST:QST_FRE_TOUR_NOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_09', 'NPC_FRE_55', 'K3', '{"effacement","memoire"}', 'La tour noire est un nœud d''ancrage du Cardinal. Ce qui s''y trouve a été effacé du code source de la zone — Thorin l''a vu avant l''effacement, et le Cardinal a tenté de lui retirer ce souvenir. La brûlure de la carte était un sacrifice : tant que la carte n''existe pas, il peut encore se souvenir', NULL, '*(il plante son couteau dans le bois)* « J''ai rien à dire là-dessus. La carte est brûlée. Mes souvenirs sont aux ordures. Si t''es malin, tu laisses ce qui est là-bas tranquille, sinon il viendra te les prendre aussi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_55_10', 'NPC_FRE_55', 'KX', '{"*(hors sujet)*"}', '*(il lui tourne le dos et reprend sa sculpture)* « Va parler aux jeunes. Moi j''ai fini de causer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_01', 'NPC_FRE_56', 'K0', '{"sommet","garde"}', 'La garde du sommet — son poste, sa routine, les conditions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_02', 'NPC_FRE_56', 'K0', '{"tour","horaires"}', 'Les horaires de garde — relève toutes les douze heures, deux gardes par jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_03', 'NPC_FRE_56', 'K0', '{"equipement","lance"}', 'Son équipement — lance de la Garde Fauve, armure légère, jumelles de cristal', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_04', 'NPC_FRE_56', 'K1', '{"vol","ailes"}', 'Il a vu une silhouette s''envoler du sommet sans ailes ni potion — un joueur, ou quelque chose d''autre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_05', 'NPC_FRE_56', 'K1', '{"vitesse","ouest"}', 'La silhouette a filé vers l''ouest à une vitesse que nul familier volant n''atteint', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_06', 'NPC_FRE_56', 'K1', '{"silence","rapport"}', 'Il n''a pas mis ça dans son rapport — il a écrit « rien à signaler » comme d''habitude', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_07', 'NPC_FRE_56', 'K2', '{"seconde","fois"}', 'Il a revu la même silhouette trois nuits plus tard — elle est revenue, a plané au-dessus de la Tour, puis est repartie', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_08', 'NPC_FRE_56', 'K2', '{"traces","absence"}', 'Il est descendu vérifier le sol au pied de la Tour après le second vol — aucune trace d''atterrissage ni de décollage', '`QUEST:QST_FRE_VOL_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_09', 'NPC_FRE_56', 'K3', '{"joueur","compte"}', 'Ce n''était pas un joueur — c''était une instance de test du Cardinal, un compte-vide qui arpente les serveurs pour vérifier l''intégrité des zones de vol, un vestige de la D17 qui n''a jamais été désactivé', NULL, '*(il serre le manche de sa lance)* « Un compte de test du Cardinal ? Écoute, moi je suis garde. Je vois ce que je vois. Si le Cardinal envoie des ombres volantes survoler ma tour, c''est pas à moi de le dire. C''est à moi de le taire. Alors tais-toi aussi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_56_10', 'NPC_FRE_56', 'KX', '{"*(hors sujet)*"}', '« La garde est calme. Rien à signaler. Reviens demain. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_01', 'NPC_FRE_57', 'K0', '{"royaume","reine"}', 'La vie à la Tour du Trône Fauve — protocole, service, quotidien', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_02', 'NPC_FRE_57', 'K0', '{"alicia","personnalite"}', 'Alicia Rue — son caractère, ses habitudes, ses goûts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_03', 'NPC_FRE_57', 'K0', '{"service","dame"}', 'Les devoirs d''une dame de compagnie — toilette, courrier, gestion de l''agenda', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_04', 'NPC_FRE_57', 'K1', '{"mensonge","detection"}', 'Elle sait quand Alicia ment — un frisson dans la nuque qui ne trompe pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_05', 'NPC_FRE_57', 'K1', '{"frequence","mensonges"}', 'Alicia ment de plus en plus souvent — plusieurs fois par jour, y compris aux ambassadeurs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_06', 'NPC_FRE_57', 'K1', '{"reine","fatigue"}', 'Alicia dort mal et parle seule la nuit — Lucille l''a entendue dire « Ils ne doivent pas savoir »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_07', 'NPC_FRE_57', 'K2', '{"voix","etrangere"}', 'Parfois, la voix d''Alicia change — une octave plus basse, un accent qui n''est pas le sien', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_08', 'NPC_FRE_57', 'K2', '{"decret","cache"}', 'Alicia a signé un décret que Lucille n''a pas vu passer — il était sur le bureau un matin sans que personne l''apporte', '`QUEST:QST_FRE_TRONE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_09', 'NPC_FRE_57', 'K3', '{"reine","remplacee"}', 'Alicia Rue a été partiellement remplacée par une instance secondaire du Cardinal — la vraie Alicia est toujours présente, mais une couche de contrôle lui superpose des décisions et des paroles qu''elle n''a pas choisies. Lucille sent le mensonge parce qu''elle perçoit l''incohérence entre l''âme de la reine et les mots que le Cardinal lui met dans la bouche', NULL, '*(elle se mord la lèvre et baisse les yeux)* « Remplacée ? La reine est la reine. Je sers Alicia Rue depuis quinze ans. Si quelqu''un insinue qu''elle n''est plus elle-même… je devrais le faire arrêter. Mais… » *(elle n''achève pas)*');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_57_10', 'NPC_FRE_57', 'KX', '{"*(hors sujet)*"}', '« La reine n''accorde pas d''audience aujourd''hui. Revenez à l''aube. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_01', 'NPC_FRE_58', 'K0', '{"archives","tours"}', 'Les archives du Trône Fauve — organisation, accès, protocole', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_02', 'NPC_FRE_58', 'K0', '{"decrets","ecriture"}', 'Le processus d''écriture des décrets — de la demande à la publication', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_03', 'NPC_FRE_58', 'K0', '{"sceau","royal"}', 'Le sceau royal — gardé par la reine, apposé en sa présence uniquement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_04', 'NPC_FRE_58', 'K1', '{"decret","faux"}', 'Un décret signé Alicia Rue existe mais n''a pas été écrit par elle — Talin en est certain', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_05', 'NPC_FRE_58', 'K1', '{"jour","chasse"}', 'Le jour du décret, la reine était à la chasse accompagnée de vingt gardes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_06', 'NPC_FRE_58', 'K1', '{"seconde","copie"}', 'Talin a trouvé un second décret orphelin trois jours plus tard — puis un troisième', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_07', 'NPC_FRE_58', 'K2', '{"fonds","compte"}', 'Les décrets ordonnent des virements vers un compte numéroté — aucun destinataire connu', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_08', 'NPC_FRE_58', 'K2', '{"sceau","authentique"}', 'Le sceau est authentique — Talin l''a vérifié au microscope magique. C''est bien le sceau d''Alicia', '`QUEST:QST_FRE_SCEAU_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_09', 'NPC_FRE_58', 'K3', '{"duplication","cardinal"}', 'Le sceau royal d''Alicia a été dupliqué par le Cardinal dans le cadre d''un protocole de simulation politique — la D17 a généré des décrets alternatifs que l''instance Cardinal injecte dans le flux documentaire pour « enrichir le tissu politique » de Freelia. Les fonds partent vers un compte de test du serveur', NULL, '*(il referme son registre et pose la main dessus)* « Une duplication du sceau par le Cardinal ? Les documents que j''archive sont sacrés. Si le Cardinal falsifie la signature de ma reine… » *(il marque une pause)* « …je préfère ne pas le savoir. Je suis scribe. Je classe, je ne juge pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_58_10', 'NPC_FRE_58', 'KX', '{"*(hors sujet)*"}', '« Les archives sont fermées. Reviens avec une autorisation signée de la reine. Une vraie. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_01', 'NPC_FRE_59', 'K0', '{"héraut","fonctions"}', 'Le métier de héraut — annonces, protocole, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_02', 'NPC_FRE_59', 'K0', '{"voix","technique"}', 'Sa voix — comment il la projette, l''entretient, la protège', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_03', 'NPC_FRE_59', 'K0', '{"histoire","freelia"}', 'Les grandes nouvelles qu''il a annoncées en trente ans de service', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_04', 'NPC_FRE_59', 'K1', '{"nouvelle","oubliee"}', 'Il a crié une annonce que personne ne se rappelle avoir entendue', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_05', 'NPC_FRE_59', 'K1', '{"test","invention"}', 'Il a crié une fausse nouvelle pour tester — les témoins ont tout oublié le lendemain', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_06', 'NPC_FRE_59', 'K1', '{"parchemins","sigilles"}', 'Les parchemins qu''il reçoit portent un sceau qu''il ne reconnaît pas toujours', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_07', 'NPC_FRE_59', 'K2', '{"annonces","effacees"}', 'Il a compté : sept annonces sur les vingt derniers jours ont été « effacées » de la mémoire collective', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_08', 'NPC_FRE_59', 'K2', '{"soir","silence"}', 'Un soir, il a crié une annonce et sa voix n''a produit aucun son — ses cordes vocales vibraient, mais aucun bruit n''est sorti', '`QUEST:QST_FRE_HERAUT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_09', 'NPC_FRE_59', 'K3', '{"flux","information"}', 'Les annonces effacées sont des micro-patchs du Cardinal : des mises à jour de paramètres de zone que l''instance D17 injecte via la voix du héraut, en utilisant sa portée vocale comme vecteur de diffusion. Les auditeurs oublient parce que l''information n''est pas destinée à leur conscience — elle modifie directement les variables du serveur. Sa voix est un canal de maintenance du système', NULL, '*(il recule d''un pas, la main sur la gorge)* « Ma voix est un canal de maintenance ? Je suis héraut. Je crie les nouvelles du royaume. Pas les réglages du monde. Si le Cardinal se sert de ma gorge pour parler aux… aux machines… » *(il déglutit)* « …je ne veux plus jamais crier. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_59_10', 'NPC_FRE_59', 'KX', '{"*(hors sujet)*"}', '« L''annonce du jour a été faite. Va te promener, reviens demain. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_01', 'NPC_FRE_60', 'K0', '{"dressage","avance"}', 'Techniques de dressage avancé — paliers T3/T4, affinité élémentaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_02', 'NPC_FRE_60', 'K0', '{"familiers","legendaires"}', 'Les familiers légendaires de Freelia — noms connus, zones, difficulté', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_03', 'NPC_FRE_60', 'K0', '{"menagerie","royale"}', 'La Ménagerie Royale — les enclos, les soins, le personnel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_04', 'NPC_FRE_60', 'K1', '{"familier","efface"}', 'Il y a un familier qu''il n''a pas dressé — et qu''il n''a jamais pu dresser', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_05', 'NPC_FRE_60', 'K1', '{"nom","secret"}', 'Le nom du familier est sur toutes les lèvres, mais personne ne le prononce — Korrigan non plus', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_06', 'NPC_FRE_60', 'K1', '{"odeur","fumee"}', 'Il sent la fumée et le fer depuis cette époque — les bêtes le reconnaissent comme un survivant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_07', 'NPC_FRE_60', 'K2', '{"registre","vide"}', 'Le registre des dresseurs mentionne le familier jusqu''à une certaine date — puis plus rien', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_08', 'NPC_FRE_60', 'K2', '{"leo","confidence"}', 'Il a dit à Léo `FRE_01` le nom du familier, à voix basse, une nuit d''orage — Léo a pâli et n''en a plus jamais reparlé', '`QUEST:QST_FRE_FAMILIER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_09', 'NPC_FRE_60', 'K3', '{"effacement","cardinal"}', 'Le familier effacé n''est pas mort — il a été retiré du bestiaire du serveur par le Cardinal parce qu''il contenait un artefact de code d''une version antérieure d''ALO, un héritage de la D17 qui ne devait pas persister dans la D20. Le lien d''âme avec son dresseur a été sectionné chirurgicalement par le Cardinal. Korrigan était le dresseur', NULL, '*(il détourne le regard et caresse un familier sans le voir)* « Le Cardinal ne retire pas les familiers. Les familiers meurent, ou ils vivent. Il n''y a pas d''entre-deux. Si quelqu''un te dit que des bêtes disparaissent des registres, c''est que quelqu''un ment. Et je ne mens pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_60_10', 'NPC_FRE_60', 'KX', '{"*(hors sujet)*"}', '« Va t''entraîner. Reviens me voir quand tu sauras tenir une laisse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_01', 'NPC_FRE_61', 'K0', '{"soins","veterinaires"}', 'Les soins vétérinaires à la Ménagerie — consultations, urgences, remèdes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_02', 'NPC_FRE_61', 'K0', '{"maladies","familiers"}', 'Les maladies courantes des familiers — parasites, carences, blessures de combat', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_03', 'NPC_FRE_61', 'K0', '{"remedes","plantes"}', 'Les remèdes qu''elle prépare — baumes, potions, cataplasmes à base de plantes locales', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_04', 'NPC_FRE_61', 'K1', '{"bête","deux fois"}', 'Un familier royal est mort — elle l''a soigné une semaine après, vivant, avec la même blessure', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_05', 'NPC_FRE_61', 'K1', '{"tombe","vide"}', 'Elle est allée vérifier la tombe le soir même — elle était vide, la terre n''avait pas été remuée', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_06', 'NPC_FRE_61', 'K1', '{"myn","temoin"}', 'Soigneur Myn `FRE_22` était présent le jour de la mort — depuis, il évite de croiser son regard', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_07', 'NPC_FRE_61', 'K2', '{"registre","double"}', 'Le registre montre deux entrées pour le même familier à une semaine d''intervalle — la seconde sans numéro de dossier', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_08', 'NPC_FRE_61', 'K2', '{"odeur","souffre"}', 'Le familier revenu sentait le soufre et la cendre — une odeur qu''elle n''a jamais retrouvée sur aucune bête vivante', '`QUEST:QST_FRE_BETE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_09', 'NPC_FRE_61', 'K3', '{"resurrection","cardinal"}', 'Le familier n''est pas revenu à la vie — c''est une copie instantanée générée par le Cardinal à partir du snapshot D17 du dernier état vivant, un double de réserve que le système a libéré par erreur dans la zone active. La tombe vide est un trou de mémoire du serveur : le corps original a été désalloué, mais la copie persiste dans un état instable', NULL, '*(elle laisse tomber son scalpel et le rattrape d''une main tremblante)* « Une copie de réserve du Cardinal ? Je suis vétérinaire. Je soigne des bêtes en chair et en os. Pas des… des fantômes de données. Ce que j''ai vu était réel. AUSSI réel que toi. Alors ne viens pas me dire que ce n''était qu''une copie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_61_10', 'NPC_FRE_61', 'KX', '{"*(hors sujet)*"}', '« J''ai des consultations. Si tu n''es pas malade, va voir ailleurs. Si tu es malade, prends rendez-vous. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_01', 'NPC_FRE_62', 'K0', '{"colline","souvenirs"}', 'La Colline aux Souvenirs — histoire, signification, rites funéraires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_02', 'NPC_FRE_62', 'K0', '{"tombes","entretien"}', 'L''entretien des tombes — nettoyage, offrandes, renouvellement des stèles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_03', 'NPC_FRE_62', 'K0', '{"epitaphes","histoires"}', 'Les épitaphes les plus anciennes — certaines datent d''avant la fondation officielle de Freelia', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_04', 'NPC_FRE_62', 'K1', '{"tombe","vide"}', 'La tombe du familier d''Elara est vide — il l''a vérifiée', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_05', 'NPC_FRE_62', 'K1', '{"fleur","nuit"}', 'Chaque nuit, quelqu''un dépose une fleur sur la tombe vide — chaque matin, elle a disparu', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_06', 'NPC_FRE_62', 'K1', '{"elara","silence"}', 'Il n''a jamais dit à Elara `FRE_03` que la tombe était vide — il ne veut pas la blesser', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_07', 'NPC_FRE_62', 'K2', '{"pas","nuit"}', 'Il a vu des empreintes de pas autour de la tombe — des pas qui ne correspondent à aucune race connue', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_08', 'NPC_FRE_62', 'K2', '{"archives","discrepancy"}', 'Les archives de Lyra `FRE_63` montrent une incohérence : la date de décès du familier est postérieure à la date de sa résurrection supposée', '`QUEST:QST_FRE_COLLINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_09', 'NPC_FRE_62', 'K3', '{"retention","ames"}', 'La Colline aux Souvenirs n''est pas un lieu sacré décoratif — c''est un tampon de mémoire du Cardinal, une zone de stockage temporaire pour les données d''âme des familiers avant leur recyclage. La tombe vide est un slot de mémoire libéré mais pas encore réécrit, un artefact du processus de nettoyage du serveur. L''âme du familier d''Elara est toujours dans le tampon, ni vivante ni morte, en attente de suppression définitive', NULL, '*(il ramasse une fleur fanée et la froisse entre ses doigts)* « La Colline est un lieu sacré. Les âmes y reposent en paix. Si tu insinues que le Cardinal stocke les âmes de nos bêtes comme des données dans un coffre, tu insinues que notre deuil n''est qu''une… une variable. Et ça, je ne peux pas l''entendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_62_10', 'NPC_FRE_62', 'KX', '{"*(hors sujet)*"}', '« Laisse les morts tranquilles. Ils ont assez souffert de leur vivant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_01', 'NPC_FRE_63', 'K0', '{"registre","ames"}', 'Le Registre des Âmes — sa structure, son histoire, sa fiabilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_02', 'NPC_FRE_63', 'K0', '{"funerailles","rites"}', 'Les rites funéraires pour familiers — cérémonie, offrandes, prières', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_03', 'NPC_FRE_63', 'K0', '{"defunts","liste"}', 'La liste des familiers défunts notables — noms qui reviennent dans les conversations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_04', 'NPC_FRE_63', 'K1', '{"familier","revenu"}', 'Un familier inscrit comme mort a été vu vivant sur la Colline', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_05', 'NPC_FRE_63', 'K1', '{"entree","modifiee"}', 'La date de résurrection refusée dans le registre a été modifiée après coup — l''encre est différente', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_06', 'NPC_FRE_63', 'K1', '{"temoins","trois"}', 'Trois témoins l''ont vu — des gardes de nuit qui jurent ne pas avoir bu', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_07', 'NPC_FRE_63', 'K2', '{"encre","magique"}', 'L''encre du registre est magique — elle ne peut être modifiée que par un scribe autorisé ou par le Cardinal', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_08', 'NPC_FRE_63', 'K2', '{"comparaison","murdoc"}', 'Les observations de Murdoc `FRE_62` et ses entrées ne coïncident pas pour cinq tombes — les dates diffèrent d''exactement un cycle de lune', '`QUEST:QST_FRE_REGISTRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_09', 'NPC_FRE_63', 'K3', '{"ecriture","cardinal"}', 'Le Cardinal écrit dans le registre la nuit, par-dessus l''encre de Lyra, pour ajuster les chronologies de résurrection des familiers sans passer par le processus de résurrection officiel. Les entrées modifiées sont des « rattrapages » de la base de données, synchronisations entre le registre physique et l''index du serveur', NULL, '*(elle referme le registre et met la main sur la couverture)* « Le Cardinal écrit dans mon registre ? Je suis archiviste. Ce livre est sacré. Chaque mot est une âme. Si le Cardinal corrige les âmes de nos bêtes comme des… des lignes de comptabilité… » *(elle secoue la tête)* « …je préfère ne pas le savoir. Vraiment. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_63_10', 'NPC_FRE_63', 'KX', '{"*(hors sujet)*"}', '« Le registre est à jour. Si tu veux vérifier une entrée, reviens avec le nom du défunt. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_01', 'NPC_FRE_64', 'K0', '{"porte","betes"}', 'La Porte des Bêtes — description, dimensions, serrure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_02', 'NPC_FRE_64', 'K0', '{"consigne","garde"}', 'La consigne de garde — ne jamais ouvrir, ne jamais quitter son poste, ne jamais poser de questions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_03', 'NPC_FRE_64', 'K0', '{"cles","acier"}', 'Les trois clés d''acier noir — forgées dans un métal qui ne rouille pas, qui ne chauffe pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_04', 'NPC_FRE_64', 'K1', '{"griffures","porte"}', 'Il entend des griffures derrière la porte — lentes, régulières, comme une bête énorme', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_05', 'NPC_FRE_64', 'K1', '{"silence","rapports"}', 'Il a rapporté les griffures à Léo `FRE_01` — silence radio, aucune réponse', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_06', 'NPC_FRE_64', 'K1', '{"odeur","souffre"}', 'Parfois, une odeur de soufre filtre sous la porte — mêlée à quelque chose de plus doux, comme du miel brûlé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_07', 'NPC_FRE_64', 'K2', '{"rythme","griffes"}', 'Les griffures suivent un rythme — trois coups, pause, trois coups, pause longue, trois coups. Un appel', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_08', 'NPC_FRE_64', 'K2', '{"vétuste","confidence"}', 'Le Vétuste Kael `FRE_65` lui a dit un jour : « Ce qui est derrière était là avant la porte. La porte a été construite autour. »', '`QUEST:QST_FRE_PORTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_09', 'NPC_FRE_64', 'K3', '{"contenu","porte"}', 'Derrière la porte se trouve le premier familier jamais dompté dans ALO — avant même la D17. Le Cardinal l''a emprisonné dans un enclos virtuel scellé parce que sa signature de code est incompatible avec les versions récentes du serveur. Il est toujours vivant, toujours conscient, et il gratte depuis vingt ans', NULL, '*(il pose la main sur les clés, les fait tinter)* « Le premier familier ? La porte ne s''ouvre pas. Les ordres sont les ordres. Même si ce que tu dis est vrai — et je dis PAS que ça l''est — je ne l''ouvrirai pas. Parce que si je l''ouvre, ce n''est plus un gardien qu''il faudra, c''est un héros. Et je suis juste un gardien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_64_10', 'NPC_FRE_64', 'KX', '{"*(hors sujet)*"}', '*(il retourne à sa garde, dos tourné)* « La porte est fermée. Elle restera fermée. Va-t''en. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_01', 'NPC_FRE_65', 'K0', '{"vieux","dresseur"}', 'Sa vie de dompteur — les bêtes qu''il a dressées, les voyages, les exploits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_02', 'NPC_FRE_65', 'K0', '{"menagerie","souvenirs"}', 'Ses souvenirs de la Ménagerie — comment elle était avant, comment elle a changé', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_03', 'NPC_FRE_65', 'K0', '{"conseils","vieux"}', 'Conseils d''un vieux dresseur — respect de la bête, patience, écoute du souffle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_04', 'NPC_FRE_65', 'K1', '{"premier","familier"}', 'Il a connu le premier familier — il était là le jour de son domptage', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_05', 'NPC_FRE_65', 'K1', '{"nom","oublie"}', 'Il a oublié le nom du premier — mais il se souvient de son regard, de son pelage', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_06', 'NPC_FRE_65', 'K1', '{"porte","construction"}', 'Il se souvient de la construction de la Porte des Bêtes — elle a été bâtie en une nuit par des ouvriers qui ne parlaient pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_07', 'NPC_FRE_65', 'K2', '{"cardinal","scellement"}', 'Il a vu le Cardinal sceller la porte — une lumière blanche, un bruit d''abeilles, et plus jamais de bruit du premier', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_08', 'NPC_FRE_65', 'K2', '{"leo","ecoute"}', 'Il a dit à Léo `FRE_01` que la Porte des Bêtes n''a pas de serrure côté intérieur — elle s''ouvre de l''intérieur, pas de l''extérieur', '`QUEST:QST_FRE_PORTE_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_09', 'NPC_FRE_65', 'K3', '{"verrou","exterieur"}', 'La Porte des Bêtes a été conçue pour être ouverte de l''intérieur — le premier familier peut sortir quand il le veut. Il ne sort pas parce qu''il a choisi de rester. Il comprend que le monde a changé et qu''il n''y a plus sa place. Kael est le seul à qui le premier a « parlé » — par rêves', NULL, '*(il tousse longtemps, puis fixe l''interlocuteur avec des yeux soudain clairs)* « Pourquoi il reste ? Parce qu''il est poli. Les bêtes sont plus polies que nous. Si on l''enferme, c''est qu''il y a une raison. Et s''il sort, c''est que la raison a disparu. Tu veux savoir s''il sortira un jour ? Demande-lui pas. Demande-toi si t''es prêt à ce qu''il sorte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_65_10', 'NPC_FRE_65', 'KX', '{"*(hors sujet)*"}', '« Je suis fatigué. Reviens me voir quand le soleil sera plus bas. Ou plus haut. Je sais plus. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_01', 'NPC_FRE_66', 'K0', '{"appats","vente"}', 'Les appâts en vente — vers, leurres, phéromones, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_02', 'NPC_FRE_66', 'K0', '{"conseils","peche"}', 'Conseils d''appâtage — quel appât pour quel monstre, saison, heure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_03', 'NPC_FRE_66', 'K0', '{"stock","etal"}', 'L''étal de Mordecai — organisation, approvisionnement, clients réguliers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_04', 'NPC_FRE_66', 'K1', '{"appat","rouge"}', 'Un appât rouge qui sent le soufre — il ne le vend pas, il le cache', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_05', 'NPC_FRE_66', 'K1', '{"test","chose"}', 'Il a testé l''appât une fois — quelque chose est venu, froid, silencieux', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_06', 'NPC_FRE_66', 'K1', '{"argile","ouest"}', 'L''argile vient de l''ouest — de la zone blanche que les cartographes ne remplissent pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_07', 'NPC_FRE_66', 'K2', '{"coffre","soufre"}', 'L''appât rouge est dans un coffre sous son lit — la terre vibre encore, et le soufre traverse le bois', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_08', 'NPC_FRE_66', 'K2', '{"zephyr","offre"}', 'Zephyr le Trappeur `FRE_02` lui a offert 10 000 Yrds pour l''appât — Mordecai a refusé. Zephyr n''a pas insisté, ce qui est encore plus inquiétant', '`QUEST:QST_FRE_APPAT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_09', 'NPC_FRE_66', 'K3', '{"amorce","cardinal"}', 'L''appât rouge est un fragment d''une balise de calibration du Cardinal — un morceau d''argile sigillée qui émet un signal de synchronisation vers le serveur mère. Ce qu''il a attiré n''était pas un monstre, mais un processus de maintenance dédié au recalibrage de la zone, une entité de protocole qui a « regardé » Mordecai pour vérifier son identification de PNJ', NULL, '*(il pousse un rire forcé)* « Un fragment de balise du Cardinal ? T''es fou toi. C''est de la terre rouge. Y a du soufre dedans. Ça attire les bêtes. Point. — Et même si c''était autre chose… » *(sa voix tombe)* « …je le vendrais pas, et j''en parlerais pas. Alors parle-moi d''autre chose. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_66_10', 'NPC_FRE_66', 'KX', '{"*(hors sujet)*"}', '« Des appâts ? J''ai ce qu''il te faut. Mais prends pas celui du fond, il est pas à vendre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_01', 'NPC_FRE_67', 'K0', '{"equipement","vente"}', 'Les équipements de dressage en vente — laisses, colliers, harnais, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_02', 'NPC_FRE_67', 'K0', '{"fabrication","cuir"}', 'La fabrication artisanale — tressage, tannage, assemblage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_03', 'NPC_FRE_67', 'K0', '{"conseils","dressage"}', 'Conseils pour choisir son équipement — taille de la bête, type de monstre, usage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_04', 'NPC_FRE_67', 'K1', '{"laisse","noire"}', 'Une laisse noire incassable qui répare toute seule les coupures', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_05', 'NPC_FRE_67', 'K1', '{"origine","inconnue"}', 'Elle vient d''un lot d''occasion — l''aventurier avait quitté le jeu, pas de nom', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_06', 'NPC_FRE_67', 'K1', '{"essai","coupe"}', 'Elle a essayé de la couper — la lame a glissé sans laisser de trace, et le lendemain la laisse était intacte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_07', 'NPC_FRE_67', 'K2', '{"elongation","autonome"}', 'La laisse s''allonge et se raccourcit quand personne ne la touche — elle « respire »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_08', 'NPC_FRE_67', 'K2', '{"acheteur","mysterieux"}', 'Un acheteur encapuchonné est venu trois fois demander « si la laisse noire était encore là » — sans jamais proposer de l''acheter', '`QUEST:QST_FRE_LAISSE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_09', 'NPC_FRE_67', 'K3', '{"lien","familier"}', 'La laisse noire appartenait au premier familier — elle a été utilisée le jour de son domptage, il y a vingt ans. Le cuir est imprégné de la signature de code du familier originel, ce qui la rend indestructible et auto-réparante : elle est devenue un artefact du système, liée en permanence à la mémoire du premier familier dans l''index du serveur', NULL, '*(elle touche la laisse noire du bout des doigts, puis retire sa main vivement)* « La laisse du premier familier ? C''est une laisse. C''est du cuir. Y a pas d''âme dedans. Y a pas d''histoire. C''est juste un objet que j''arrive pas à vendre. Point final. — Et si tu veux pas de mes articles, tu peux aller voir ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_67_10', 'NPC_FRE_67', 'KX', '{"*(hors sujet)*"}', '« Regarde mais touche pas. Sauf si t''achètes. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_01', 'NPC_FRE_68', 'K0', '{"fourrures","vente"}', 'Les fourrures en vente — worg, croco, yack, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_02', 'NPC_FRE_68', 'K0', '{"provenance","regions"}', 'La provenance des peaux — régions de chasse, saisons, qualité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_03', 'NPC_FRE_68', 'K0', '{"metier","negociant"}', 'Le métier de négociant en fourrures — achat, stockage, vente, réseaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_04', 'NPC_FRE_68', 'K1', '{"fourrure","chaude"}', 'Une fourrure dans sa réserve qui ne refroidit jamais — chaude comme de la lave', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_05', 'NPC_FRE_68', 'K1', '{"chasseur","inconnu"}', 'Le chasseur qui la lui a vendue est mort le lendemain — personne ne sait de quoi', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_06', 'NPC_FRE_68', 'K1', '{"retours","acheteurs"}', 'Trois acheteurs l''ont rendue, les mains tremblantes, sans explication', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_07', 'NPC_FRE_68', 'K2', '{"origine","feu"}', 'La fourrure ne vient d''aucun animal connu — elle ressemble à du magma solidifié, pas à du poil', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_08', 'NPC_FRE_68', 'K2', '{"receleur","offre"}', 'Le Receleur `FRE_48` a proposé 50 000 Yrds — une somme qu''il ne sort que pour des objets « qui viennent d''ailleurs »', '`QUEST:QST_FRE_FOURRURE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_09', 'NPC_FRE_68', 'K3', '{"creature","donnee"}', 'La fourrure est le tégument d''une créature de données — un monstre de test de la D17 qui n''a jamais été déployé, dont la peau est faite de matière thermique pure, un vestige de simulation de chaleur que le Cardinal a oublié de recycler. Elle irradie encore la température de calcul du serveur de test', NULL, '*(il passe la main sur la fourrure et ses doigts rougissent)* « Une créature de données ? La peau est chaude, c''est tout. Y a pas de machine là-dessous. C''est de la fourrure, point. — Et même si c''était du magma de serveur, j''aurais pas à te le dire. Alors achète ou va vendre tes théories ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_68_10', 'NPC_FRE_68', 'KX', '{"*(hors sujet)*"}', '« Fourrure de worg de première qualité ! Touche-la ! Douce comme le poil d''un chaton de vingt kilos ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_01', 'NPC_FRE_69', 'K0', '{"gibiers","vente"}', 'Les gibiers en vente — viande de worg, de croco, de yack, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_02', 'NPC_FRE_69', 'K0', '{"buffs","viande"}', 'Les buffs conférés par chaque viande — force, agilité, endurance, régénération', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_03', 'NPC_FRE_69', 'K0', '{"chasse","fournisseurs"}', 'Ses fournisseurs — chasseurs locaux, trappeurs, élevages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_04', 'NPC_FRE_69', 'K1', '{"viande","nullepart"}', 'De la viande apparaît dans sa réserve chaque semaine — sans origine, sans fournisseur', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_05', 'NPC_FRE_69', 'K1', '{"buffs","puissants"}', 'Les buffs de cette viande sont deux fois plus puissants que la normale', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_06', 'NPC_FRE_69', 'K1', '{"garde","surveillance"}', 'Il a posté un garde trois nuits — la viande est apparue quand même, sans que le garde voie rien', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_07', 'NPC_FRE_69', 'K2', '{"bestiaire","inconnu"}', 'La viande ne ressemble à aucune créature du bestiaire — il a montré un échantillon à Maître Elara `FRE_03`, elle n''a pas su l''identifier', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_08', 'NPC_FRE_69', 'K2', '{"stocks","paralleles"}', 'Marchand d''Écailles `FRE_34` a le même problème — des écailles apparaissent sans source, à la même fréquence', '`QUEST:QST_FRE_VIANDE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_09', 'NPC_FRE_69', 'K3', '{"spawn","ressources"}', 'La viande est une ressource générée automatiquement par le Cardinal pour compenser un bug de drop dans la zone de Freelia — le serveur injecte de la nourriture de substitution dans les inventaires marchands pour que les joueurs ne remarquent pas que certains monstres ne dropent plus. La viande vient du néant logistique du serveur, une variable non allouée qui se matérialise', NULL, '*(il coupe un morceau de viande d''un geste trop brusque)* « Le Cardinal qui génère de la viande dans ma réserve sans me le dire ? Je suis boucher, pas entrepôt du système. Si le serveur utilise mon étal pour cacher ses bugs, je veux pas le savoir. Et toi non plus, tu devrais pas. Tant que la viande est bonne et que les clients sont contents, le reste… » *(il hausse les épaules)* « …le reste c''est pas mon problème. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_69_10', 'NPC_FRE_69', 'KX', '{"*(hors sujet)*"}', '« Viande fraîche ! Prends-en pour la route, elle se conserve trois jours ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_01', 'NPC_FRE_70', 'K0', '{"porte","freelia"}', 'La Porte de Freelia — architecture, défenses, personnel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_02', 'NPC_FRE_70', 'K0', '{"regles","entree"}', 'Les règles d''entrée — laissez-passer, interdits, taxes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_03', 'NPC_FRE_70', 'K0', '{"registre","garde"}', 'Son registre d''entrée-sortie — tenue méticuleuse depuis cinq ans', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_04', 'NPC_FRE_70', 'K1', '{"disparitions","registre"}', 'Des entrants n''ont pas de sortie enregistrée — ils sont entrés, jamais ressortis', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_05', 'NPC_FRE_70', 'K1', '{"nombre","sept"}', 'Sept cas en trois mois — il les a notés, datés, vérifiés', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_06', 'NPC_FRE_70', 'K1', '{"memoire","gardes"}', 'Les gardes de la ronde intérieure ne se souviennent d''aucun de ces visiteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_07', 'NPC_FRE_70', 'K2', '{"profil","disparus"}', 'Les disparus n''ont pas de profil commun — races, niveaux, heures variés', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_08', 'NPC_FRE_70', 'K2', '{"nuit","verification"}', 'Il est resté une nuit entier à surveiller la porte — personne n''est sorti, mais le matin le registre montrait trois nouvelles entrées sans que la porte ait été ouverte', '`QUEST:QST_FRE_PORTE_03`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_09', 'NPC_FRE_70', 'K3', '{"portail","latent"}', 'La Porte de Freelia est superposée à un portail latent de téléportation de test de la D17 — des vestiges d''instance qui s''activent aléatoirement et redirigent certains visiteurs vers une zone de test vide du serveur, sans retour possible. Les « disparus » sont des PNJ ou joueurs qui ont traversé une faille de téléportation involontaire et sont coincés dans la zone orpheline', NULL, '*(il ferme son registre d''un geste sec)* « Un portail latent de la D17 sous ma porte ? Je suis garde, pas ingénieur. Ma porte est en pierre, en fer, et en vigilance. Si le Cardinal a planqué des téléportations qui marchent toutes seules sous mes pieds, c''est pas à moi de le dire. C''est à moi de faire comme si j''avais rien vu. Et je te conseille de faire pareil. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_70_10', 'NPC_FRE_70', 'KX', '{"*(hors sujet)*"}', '« La porte est ouverte de l''aube au crépuscule. Si t''as un laissez-passer, entre. Si t''en as pas, va chercher le Douanier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_01', 'NPC_FRE_71', 'K0', '{"douane","registre"}', 'Le travail de douanier — enregistrement, laissez-passer, taxes d''entrée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_02', 'NPC_FRE_71', 'K0', '{"voyageurs","profils"}', 'Les voyageurs types — commerçants, chasseurs, pèlerins, aventuriers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_03', 'NPC_FRE_71', 'K0', '{"taxes","entrees"}', 'Les taxes d''entrée à Freelia — marchandises, montures, armes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_04', 'NPC_FRE_71', 'K1', '{"noms","animaux"}', 'Des noms d''animaux dans le registre des visiteurs — « Croc Blanc », « Plume d''Ombre »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_05', 'NPC_FRE_71', 'K1', '{"ecriture","mort"}', 'Les entrées sont de la main d''un douanier mort depuis dix ans — Finn a vérifié les archives', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_06', 'NPC_FRE_71', 'K1', '{"dates","recentes"}', 'Les dates des entrées sont d''il y a deux semaines — impossible, et pourtant vrai', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_07', 'NPC_FRE_71', 'K2', '{"signatures","authentiques"}', 'Les signatures des « animaux » sont authentiques — empreintes magiques vérifiables', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_08', 'NPC_FRE_71', 'K2', '{"aldric","verification"}', 'Aldric `FRE_70` a vérifié les caméras de la Porte pour ces dates — les enregistrements montrent des visiteurs, mais leurs visages sont flous', '`QUEST:QST_FRE_DOUANE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_09', 'NPC_FRE_71', 'K3', '{"familiers","autonomes"}', 'Les noms d''animaux sont ceux de familiers qui ont acquis une autonomie temporaire à cause d''un dérèglement du système d''attachement dans la D20 — ils ont été enregistrés comme visiteurs par le registre automatique de la Porte, qui les a identifiés comme des entités autonomes plutôt que comme des familiers attachés. Le douanier mort est un artefact d''écriture : le registre a « imité » l''écriture du dernier douanier en poste pour rester cohérent avec son propre historique', NULL, '*(il tourne le registre vers lui, comme pour le cacher)* « Des familiers autonomes enregistrés comme visiteurs ? Le registre ne fait pas d''erreur. S''il a écrit ces noms, c''est que ces… êtres… étaient là, debout, à demander l''entrée. Et s''ils étaient là, c''est que quelque chose les a rendus capables de parler, de signer, d''entrer par la porte. Et ça… ça n''existe pas. Alors je préfère ne pas y penser. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_71_10', 'NPC_FRE_71', 'KX', '{"*(hors sujet)*"}', '« Enregistrement des voyageurs. Nom, race, provenance, durée du séjour. Sans ça, t''es un hors-la-loi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_01', 'NPC_FRE_72', 'K0', '{"remparts","guet"}', 'Son poste sur le bastion ouest — équipement, horaires, conditions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_02', 'NPC_FRE_72', 'K0', '{"alliance","sylph"}', 'L''alliance Sylph-Cait Sith — sa position, ses missions, sa légitimité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_03', 'NPC_FRE_72', 'K0', '{"vision","nocturne"}', 'Sa vision nocturne naturelle de Sylph — capacités, limites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_04', 'NPC_FRE_72', 'K1', '{"formes","savane"}', 'Des formes rampent dans la Savane la nuit — grandes, nombreuses, silencieuses', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_05', 'NPC_FRE_72', 'K1', '{"compte","quarante"}', 'Elle a compté quarante formes une nuit — elles attendaient à la limite de vision', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_06', 'NPC_FRE_72', 'K1', '{"rapport","ignore"}', 'Son rapport a été ignoré — « fatigue » lui a-t-on dit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_07', 'NPC_FRE_72', 'K2', '{"yeux","luisants"}', 'Les formes ont des yeux qui luisent dans le noir — rouge sombre, pas comme des yeux de bêtes', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_08', 'NPC_FRE_72', 'K2', '{"anya","contact"}', 'Anya `FRE_06` lui a écrit une lettre — elles ont comparé leurs observations : les formes avancent par nuits sans lumières', '`QUEST:QST_FRE_FORMES_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_09', 'NPC_FRE_72', 'K3', '{"ombres","simulation"}', 'Les formes rampantes ne sont pas des créatures — ce sont des ombres de protocole, des résidus de tests de pathfinding de masse que le Cardinal exécute la nuit sur la zone de Freelia pour calibrer le déplacement des foules de PNJ. Les yeux rouges sont les marqueurs de ciblage du système de navigation collective. Le Cardinal utilise la Savane comme terrain d''essai pour ses algorithmes de mouvement de foule', NULL, '*(elle serre sa lance, les yeux fixés sur l''horizon)* « Des tests de pathfinding ? Je vois des yeux rouges qui me regardent. Je sens des présences qui attendent. Si c''est le Cardinal qui les envoie pour tester ses machines, ça ne change rien pour moi : si elles traversent le rempart, ce sera à moi de les arrêter avec ma lance. Et ma lance ne sait pas faire la différence entre un protocole et un ennemi. Alors fiche-moi la paix avec tes explications. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_72_10', 'NPC_FRE_72', 'KX', '{"*(hors sujet)*"}', '« Je suis de guet. Si t''as pas d''ordre du commandement, dégage du rempart. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_01', 'NPC_FRE_73', 'K0', '{"corne","alarme"}', 'La grande corne de guerre — description, histoire, utilisation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_02', 'NPC_FRE_73', 'K0', '{"sonnerie","protocole"}', 'Le protocole d''alarme — qui sonne, quand, comment, signification des séquences', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_03', 'NPC_FRE_73', 'K0', '{"histoire","freelia"}', 'Les deux fois où il a sonné la corne — le raid de monstres, l''incendie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_04', 'NPC_FRE_73', 'K1', '{"vibration","corne"}', 'La corne vibre la nuit sans que personne la touche — un murmure inaudible', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_05', 'NPC_FRE_73', 'K1', '{"melodié","colline"}', 'La vibration produit une mélodie — la même que celle de la Colline aux Souvenirs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_06', 'NPC_FRE_73', 'K1', '{"montures","nervosité"}', 'Les montures de Milo `FRE_74` deviennent agitées quand la corne vibre — elles l''entendent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_07', 'NPC_FRE_73', 'K2', '{"sequence","nuit"}', 'La vibration suit une séquence — elle commence toujours une heure après le coucher du soleil', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_08', 'NPC_FRE_73', 'K2', '{"murdoc","sifflement"}', 'Murdoc `FRE_62` siffle la même mélodie en entretenant les tombes — il ne se rend pas compte qu''il la siffle', '`QUEST:QST_FRE_CORNE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_09', 'NPC_FRE_73', 'K3', '{"resonnance","serveur"}', 'La corne est un amplificateur acoustique résiduel de la D17 — elle capte les fréquences de maintenance du serveur et les translate en vibrations audibles. La « mélodie » est le bruit de fond du Cardinal qui scrute la zone de Freelia. La Colline aux Souvenirs est le second point de résonance : les deux forment une paire de microphones cosmiques qui écoutent le trafic du serveur', NULL, '*(il pose la main sur la corne, sent la vibration, et retire sa main)* « Un amplificateur de maintenance ? C''est une corne de guerre. Mon père l''a sonnée, son père avant lui. Si elle chante, c''est pour appeler les chasseurs, pas pour écouter les machines. — Mais si tu as raison… » *(il marque une pause)* « …alors elle chante pour nous avertir de quelque chose que nos oreilles ne sont pas faites pour entendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_73_10', 'NPC_FRE_73', 'KX', '{"*(hors sujet)*"}', '« La corne est silencieuse aujourd''hui. C''est un bon jour. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_01', 'NPC_FRE_74', 'K0', '{"montures","location"}', 'Les montures à louer — worgs, cerfs, lézards, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_02', 'NPC_FRE_74', 'K0', '{"ecurie","soins"}', 'L''écurie — entretien, nourriture, soins quotidiens', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_03', 'NPC_FRE_74', 'K0', '{"ombre","worg"}', 'Ombre — sa meilleure monture, une femelle worg grise qu''il a élevée depuis bête', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_04', 'NPC_FRE_74', 'K1', '{"refus","sortie"}', 'Ombre refuse de quitter Freelia depuis deux mois — elle s''arrête au seuil de la Porte', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_05', 'NPC_FRE_74', 'K1', '{"geignement","ouest"}', 'La nuit, Ombre gémit en regardant l''ouest — la direction des formes de Nera `FRE_72`', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_06', 'NPC_FRE_74', 'K1', '{"imitation","autres"}', 'Les autres montures imitent Ombre — toute l''écurie refuse maintenant de sortir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_07', 'NPC_FRE_74', 'K2', '{"seuil","invisible"}', 'Ombre n''a pas peur de la Savane — elle a peur de quelque chose qui est AU-DELÀ, au-delà du seuil de la ville', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_08', 'NPC_FRE_74', 'K2', '{"plume","silence"}', 'Il a trouvé une plume grise dans l''écurie un matin — il n''y a pas d''oiseaux dans Freelia qui ont ce genre de plume', '`QUEST:QST_FRE_MONTURE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_09', 'NPC_FRE_74', 'K3', '{"barriere","invisible"}', 'Il y a une barrière de perception posée par le Cardinal autour de Freelia — elle filtre ce que les PNJ et montures peuvent voir au-delà d''une certaine distance. Ombre perçoit la barrière et refuse de la traverser parce qu''elle sait — instinct de bête — que quelque chose au-delà a été modifié. La barrière est un cache visuel qui empêche les résidents de voir la zone blanche qui s''étend vraiment de l''autre côté des remparts', NULL, '*(il gratte la nuque d''Ombre qui pousse un soupir)* « Une barrière de perception ? Ombre est une bête. Elle sent des choses que nous on sent pas. Si elle veut pas sortir, c''est qu''elle a une bonne raison. Et la raison, c''est que la Savane a changé. Je sais pas comment, je sais pas pourquoi. Mais je fais confiance à Ombre. Elle sortira quand la Savane sera redevenue la Savane. Pas avant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_74_10', 'NPC_FRE_74', 'KX', '{"*(hors sujet)*"}', '« Besoin d''une monture ? J''ai des worgs, des cerfs, des lézards. Tous en bonne santé. La sortie en ville seulement, par contre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_01', 'NPC_FRE_75', 'K0', '{"fers","prix"}', 'Les types de fers qu''il forge — prix, durée, usage par monture', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_02', 'NPC_FRE_75', 'K0', '{"montures","entretien"}', 'Conseils d''entretien des griffes et sabots', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_03', 'NPC_FRE_75', 'K0', '{"forge","emplacement"}', 'Sa forge de rue sous l''auvent de cuir, toujours chaude', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_04', 'NPC_FRE_75', 'K1', '{"alliage","origine"}', 'L''alliage qu''il utilise — « Héritage. Demande pas plus. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_05', 'NPC_FRE_75', 'K1', '{"chaleur","sol"}', 'Le sol sous son enclume ne refroidit jamais — même après des heures d''inactivité', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_06', 'NPC_FRE_75', 'K1', '{"commandes","gardes"}', 'Les commandes spéciales des gardes de la Porte — des fers renforcés pour les patrouilles de nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_07', 'NPC_FRE_75', 'K2', '{"technique","interdite"}', 'La technique qu''il utilise viendrait d''un forgeron Salamander qui a fui Voulg — un secret qui brûle', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_08', 'NPC_FRE_75', 'K2', '{"fer","brulant"}', 'Un fer qu''il a forgé a brûlé le sol de la Porte — une marque noire que personne n''a pu effacer', '`QUEST:QST_CAI_FER_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_09', 'NPC_FRE_75', 'K3', '{"procede","coeur"}', 'Le métal qu''il utilise n''est pas du métal — c''est un fragment solidifié de cœur de familier, un vestige qu''il récupère à la Colline aux Souvenirs et qu''il transforme en fer sous une chaleur que seul son feu sait produire', NULL, '*(il jette un fer dans l''eau, la vapeur siffle)* « Pose pas de questions sur mes matériaux. Je ferre les bêtes. C''est tout. Si t''es pas content, va à Granzam. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_75_10', 'NPC_FRE_75', 'KX', '{"*(hors sujet)*"}', '*(un coup de marteau)* « J''ai du travail. Reviens si t''as une monture. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_01', 'NPC_FRE_76', 'K0', '{"ronde","horaires"}', 'La ronde de nuit — horaires, périmètre, procédure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_02', 'NPC_FRE_76', 'K0', '{"consignes","portes"}', 'Les consignes de la Porte la nuit — qui entre, qui sort', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_03', 'NPC_FRE_76', 'K0', '{"equipe","jour"}', 'Les gardes de jour — il ne connaît pas leurs noms, ils changent trop', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_04', 'NPC_FRE_76', 'K1', '{"ombres","vision"}', 'Il voit des ombres qui rampent le long des remparts — elles n''ont pas de source', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_05', 'NPC_FRE_76', 'K1', '{"yeux","obscurite"}', 'Des yeux dans le noir — ils le regardent TOUS les soirs, au même endroit', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_06', 'NPC_FRE_76', 'K1', '{"carnet","notes"}', 'Son carnet de notes — des symboles qu''il est le seul à comprendre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_07', 'NPC_FRE_76', 'K2', '{"accord","nuit"}', 'Il a laissé entrer quelqu''un une fois, à contrecœur — cette personne n''est jamais ressortie', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_08', 'NPC_FRE_76', 'K2', '{"zephyr","passage"}', 'Zephyr `FRE_02` passe la Porte la nuit sans être fouillé — « ordres d''en haut »', '`QUEST:QST_CAI_OMBRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_09', 'NPC_FRE_76', 'K3', '{"ombre","double"}', 'La nuit où il a vu son propre double monter la garde à sa place — une silhouette identique qui a fait le salut réglementaire avant de disparaître dans le brouillard', NULL, '*(il serre sa lance, regarde dans le vide)* « J''ai rien vu. La fatigue. Trop de nuits sans sommeil. Va-t''en, je monte la garde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_76_10', 'NPC_FRE_76', 'KX', '{"*(hors sujet)*"}', '*(il souffle dans ses mains gantées)* « Pose ça à un garde de jour. Moi je vois que l''ombre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_01', 'NPC_FRE_77', 'K0', '{"accueil","porte"}', 'Accueille les visiteurs à la Porte de Freelia — procédure standard', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_02', 'NPC_FRE_77', 'K0', '{"routine","quart"}', 'Description de sa routine de garde — les heures, les pauses, les tours', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_03', 'NPC_FRE_77', 'K0', '{"chat","familier"}', 'Le chat errant qui le suit — sans nom, sans maître, toujours présent le jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_04', 'NPC_FRE_77', 'K1', '{"chat","disparition"}', 'Le chat disparaît chaque soir à la même heure — personne ne sait où il va', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_05', 'NPC_FRE_77', 'K1', '{"visiteurs","etranges"}', 'Des visiteurs qui entrent par la Porte mais ne sont pas enregistrés — il les a notés', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_06', 'NPC_FRE_77', 'K1', '{"animaux","parole"}', 'Il parle aux animaux — et parfois, il jure qu''ils lui répondent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_07', 'NPC_FRE_77', 'K2', '{"chat","reapparition"}', 'Le chat réapparaît toujours à l''aube, même quand la Porte est fermée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_08', 'NPC_FRE_77', 'K2', '{"registre","anomalie"}', 'Le registre des entrants — un nom revient toutes les semaines, mais le visiteur n''existe pas', '`QUEST:QST_CAI_PORTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_09', 'NPC_FRE_77', 'K3', '{"chat","essence"}', 'Le chat n''est pas un vrai familier — c''est un fragment d''âme de familier défunt qui erre entre les mondes, attiré par la routine du garde comme un vestige de ce que les bêtes étaient avant leur enregistrement dans le système', NULL, '*(il gratte la tête du chat)* « Lui ? C''est juste un chat. Y a pas de mystère. Les chats c''est des chats. Et les gardes c''est des gardes. Chacun son rôle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_77_10', 'NPC_FRE_77', 'KX', '{"*(hors sujet)*"}', '*(il siffle doucement, le chat ronronne)* « Demande à la garde de nuit. Moi je fais le jour. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_01', 'NPC_FRE_78', 'K0', '{"livraisons","tarifs"}', 'Les livraisons qu''il effectue — tarifs, délais, zones couvertes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_02', 'NPC_FRE_78', 'K0', '{"itineraire","ville"}', 'Sa connaissance des rues de Freelia — raccourcis, passages secrets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_03', 'NPC_FRE_78', 'K0', '{"plis","officiels"}', 'Les plis officiels de la Tour du Trône Fauve — sceau jaune, livraison prioritaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_04', 'NPC_FRE_78', 'K1', '{"odeur","plis"}', 'Certains plis sentent la bête — une odeur qu''il ne reconnaît pas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_05', 'NPC_FRE_78', 'K1', '{"contenu","ignore"}', 'Il ne regarde jamais le contenu — mais un pli a saigné sur ses mains une fois', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_06', 'NPC_FRE_78', 'K1', '{"destinataires","etranges"}', 'Des destinataires qui n''existent pas — il livre à des noms que personne ne connaît', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_07', 'NPC_FRE_78', 'K2', '{"pli","colline"}', 'Un pli venant de la Colline aux Souvenirs — adressé à la Tour, mais retourné « destinataire inconnu »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_08', 'NPC_FRE_78', 'K2', '{"marchand","itinérant"}', 'Le Marchand Itinérant `FRE_47` lui a confié un colis qui devait traverser la frontière Sylph — le colis contenait des os', '`QUEST:QST_CAI_MESS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_09', 'NPC_FRE_78', 'K3', '{"pli","vivant"}', 'Un pli qu''il a livré bougeait — à l''intérieur, un cœur de familier encore battant, emballé dans un parchemin scellé du sceau du Cardinal, destiné à une adresse qui n''existe pas dans le registre de la ville', NULL, '*(il recule d''un pas)* « Je livre. C''est tout. Je sais pas ce qu''il y a dans les plis, je sais pas qui les envoie, je sais pas où ils vont. Je cours, je pose, je repars. C''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_78_10', 'NPC_FRE_78', 'KX', '{"*(hors sujet)*"}', '*(déjà parti, courant)* « J''ai une livraison ! On parle plus tard ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_01', 'NPC_FRE_79', 'K0', '{"accueil","ville"}', 'Présentation de Freelia — quartiers, points d''intérêt, coutumes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_02', 'NPC_FRE_79', 'K0', '{"securite","zones"}', 'Zones dangereuses de la ville — conseils aux nouveaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_03', 'NPC_FRE_79', 'K0', '{"guide","service"}', 'Ses services de guide — circuits, durée, tarifs (gratuits)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_04', 'NPC_FRE_79', 'K1', '{"visiteur","animaux"}', 'Un visiteur parlait aux animaux — les chiens des rues le suivaient', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_05', 'NPC_FRE_79', 'K1', '{"disparition","colline"}', 'Le visiteur est allé à la Colline aux Souvenirs — personne ne l''a vu revenir', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_06', 'NPC_FRE_79', 'K1', '{"registre","entree"}', 'L''entrée du visiteur est dans le registre — mais pas sa sortie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_07', 'NPC_FRE_79', 'K2', '{"gardien","registre"}', 'Le Gardien Porte `FRE_70` a refusé de lui montrer la suite du registre — « classé »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_08', 'NPC_FRE_79', 'K2', '{"animaux","reponse"}', 'Il a essayé de parler aux animaux comme le visiteur — un chat lui a répondu « il est là où les os se souviennent »', '`QUEST:QST_CAI_GUIDE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_09', 'NPC_FRE_79', 'K3', '{"visiteur","ombre"}', 'Le visiteur qui parlait aux animaux était une manifestation du premier dompteur — un écho de joueur des logs fondateurs, attiré par l''odeur du premier familier sur la Colline ; il n''est pas « sorti » parce qu''il n''est jamais vraiment « entré »', NULL, '*(son sourire se fige)* « Quel visiteur ? Ah, tu veux parler de… non, je dois confondre. Y a tellement de monde qui passe. Un visiteur qui parlait aux animaux ? Ça arrive tout le temps, les gens aiment les bêtes ici. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_79_10', 'NPC_FRE_79', 'KX', '{"*(hors sujet)*"}', '*(il désigne une direction)* « La Colline aux Souvenirs est par là. Bonne visite ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_01', 'NPC_FRE_80', 'K0', '{"culte","chasse"}', 'Le culte de la Chasse — croyances, pratiques, histoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_02', 'NPC_FRE_80', 'K0', '{"benediction","chasseurs"}', 'Bénédictions pour les chasseurs — buffs temporaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_03', 'NPC_FRE_80', 'K0', '{"autel","resurrection"}', 'L''Autel de Résurrection — fonctionnement, emplacement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_04', 'NPC_FRE_80', 'K1', '{"ossements","mouvement"}', 'Des ossements bougent sur l''autel la nuit — « la Chasse les anime »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_05', 'NPC_FRE_80', 'K1', '{"prieres","course"}', 'Les prières de la Course — des mots dans une langue qui n''est pas Cait Sith', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_06', 'NPC_FRE_80', 'K1', '{"rites","funerailles"}', 'Les rites funéraires pour les familiers — procédure, conditions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_07', 'NPC_FRE_80', 'K2', '{"ossements","parole"}', 'Les ossements ne bougent pas seuls — il a entendu des mots dans le cliquetis', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_08', 'NPC_FRE_80', 'K2', '{"acolyte","traces"}', 'L''Acolyte `FRE_82` nettoie l''autel chaque matin — des traces de pas d''animaux apparaissent après son passage', '`QUEST:QST_CAI_CULTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_09', 'NPC_FRE_80', 'K3', '{"ossements","essence"}', 'Les ossements sur l''autel ne sont pas des restes de vrais animaux — ce sont des fragments de code solidifiés, des résidus de familiers supprimés que le Cardinal recrache dans le cycle de la Chasse pour ne pas perdre leurs données', NULL, '*(il pose une main sur un os, l''os se tait)* « Les os parlent à ceux qui savent écouter. Toi, t''écoutes trop et tu comprends pas assez. Va chasser. Reviens quand t''auras une proie à honorer. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_80_10', 'NPC_FRE_80', 'KX', '{"*(hors sujet)*"}', '*(il psalmodie doucement, les yeux fermés)* « Que la Course t''emporte. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_01', 'NPC_FRE_81', 'K0', '{"culte","gueule"}', 'Le culte de la Gueule — croyances, différences avec la Meute', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_02', 'NPC_FRE_81', 'K0', '{"protection","faune"}', 'La protection de la faune — zones protégées, espèces interdites à la chasse', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_03', 'NPC_FRE_81', 'K0', '{"benediction","naissance"}', 'Bénédiction des naissances de familiers — rituel, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_04', 'NPC_FRE_81', 'K1', '{"loup","parole"}', 'Un loup qu''elle a béni a parlé — un seul mot, « merci »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_05', 'NPC_FRE_81', 'K1', '{"benediction","silence"}', 'Elle ne bénit plus sans demander la permission à la bête d''abord', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_06', 'NPC_FRE_81', 'K1', '{"braconniers","menace"}', 'Les braconniers qu''elle surveille — elle connaît leurs visages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_07', 'NPC_FRE_81', 'K2', '{"bénite","disparition"}', 'Le loup qu''elle a béni a disparu du registre des familiers — comme s''il n''avait jamais existé', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_08', 'NPC_FRE_81', 'K2', '{"vestale","rite"}', 'La Vestale `FRE_83` pratique un rite que personne ne lui a appris — « la Gueule lui parle »', '`QUEST:QST_CAI_CULTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_09', 'NPC_FRE_81', 'K3', '{"benediction","voix"}', 'La bénédiction de la Gueule n''est pas une prière adressée à un dieu — c''est une commande système qui active le module de domptage dans le code du familier ; quand une bête « parle », c''est une faille dans l''interface qui laisse filtrer la voix du Cardinal', NULL, '*(elle caresse une bête blessée)* « Les animaux ne parlent pas. J''ai entendu ce que j''ai voulu entendre. Le chagrin fait des choses étranges à l''esprit. Laisse la bête tranquille. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_81_10', 'NPC_FRE_81', 'KX', '{"*(hors sujet)*"}', '*(elle siffle doucement, un oiseau se pose sur son doigt)* « La Gueule n''a rien à dire à ceux qui ne veulent pas entendre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_01', 'NPC_FRE_82', 'K0', '{"acolyte","role"}', 'Ses tâches d''acolyte — nettoyage, offrandes, préparation des rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_02', 'NPC_FRE_82', 'K0', '{"autel","entretien"}', 'L''entretien de l''Autel de Résurrection — rituels quotidiens', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_03', 'NPC_FRE_82', 'K0', '{"formation","culte"}', 'Sa formation au culte de la Meute — ce qu''on lui apprend', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_04', 'NPC_FRE_82', 'K1', '{"traces","animaux"}', 'Des traces d''animaux apparaissent sur l''autel chaque matin — il est le premier arrivé', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_05', 'NPC_FRE_82', 'K1', '{"apparition","cendre"}', 'Il a vu les traces se former sous ses yeux — comme si une patte invisible marchait dans la cendre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_06', 'NPC_FRE_82', 'K1', '{"pretre","silence"}', 'Le Prêtre `FRE_80` lui dit de ne pas en parler — « c''est la Chasse »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_07', 'NPC_FRE_82', 'K2', '{"vestale","histoire"}', 'La Vestale `FRE_83` lui a dit que les traces sont celles de familiers qui n''ont pas eu de rite funéraire', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_08', 'NPC_FRE_82', 'K2', '{"cendre","mot"}', 'Une fois, les traces ont formé un mot dans la cendre — « RENDEZ »', '`QUEST:QST_CAI_CULTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_09', 'NPC_FRE_82', 'K3', '{"traces","code"}', 'Les traces ne sont pas faites par des pattes — ce sont des résidus de requêtes du Cardinal qui s''impriment dans la cendre quand le système vérifie l''état des familiers enregistrés sur l''autel ; chaque trace est un `SELECT * FROM familiar_register` qui laisse une empreinte dans la matière du jeu', NULL, '*(il regarde ses pieds)* « Le Prêtre dit que je dois pas parler de ça. Que je suis trop jeune pour comprendre. Il dit que la Chasse est un mystère. Alors… c''est un mystère. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_82_10', 'NPC_FRE_82', 'KX', '{"*(hors sujet)*"}', '*(il retourne à son balai)* « Si tu veux savoir, demande à la Vestale. Elle est plus cool. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_01', 'NPC_FRE_83', 'K0', '{"rites","passage"}', 'Les rites de passage du culte — procédure, symbolisme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_02', 'NPC_FRE_83', 'K0', '{"vestale","role"}', 'Le rôle de vestale — gardienne des traditions, célibataire rituelle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_03', 'NPC_FRE_83', 'K0', '{"autel","histoire"}', 'L''histoire de l''Autel de Résurrection — construction, premiers rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_04', 'NPC_FRE_83', 'K1', '{"ombre","invocation"}', 'Un rite qu''elle pratique invoque une ombre au-dessus de l''autel', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_05', 'NPC_FRE_83', 'K1', '{"ombre","duree"}', 'L''ombre ne dure que quelques secondes — mais la température baisse de plusieurs degrés', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_06', 'NPC_FRE_83', 'K1', '{"prieres","secret"}', 'Des prières qu''elle connaît ne figurent dans aucun livre du culte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_07', 'NPC_FRE_83', 'K2', '{"ombre","premiere bete"}', 'L''ombre qu''elle invoque est celle de la première bête — « elle était là avant les registres »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_08', 'NPC_FRE_83', 'K2', '{"acolyte","traces"}', 'Elle sait que l''Acolyte `FRE_82` voit des traces — elle lui a dit la vérité : ce sont les familiers oubliés', '`QUEST:QST_CAI_CULTE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_09', 'NPC_FRE_83', 'K3', '{"ombre","cardinal"}', 'L''ombre qu''elle invoque n''est pas une bénédiction divine — c''est un débordement temporaire du module d''archivage des familiers du Cardinal ; quand elle psalmodie, elle envoie une requête non standard qui force le système à « rendre » un instantané spectral du premier familier enregistré', NULL, '*(elle joint les mains, un sourire qui ne touche pas ses yeux)* « Les ombres sont des ombres. Les prières sont des prières. Ne cherche pas à comprendre ce qui se tient entre les deux. Certaines portes sont fermées pour une raison. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_83_10', 'NPC_FRE_83', 'KX', '{"*(hors sujet)*"}', '*(elle souffle une bougie)* « Le rite est terminé. Reviens un autre soir si tu veux voir l''ombre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_01', 'NPC_FRE_84', 'K0', '{"necromancie","service"}', 'La résurrection noire de familiers — service proposé, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_02', 'NPC_FRE_84', 'K0', '{"prix","paiement"}', 'Ses prix variables — « jamais le même deux fois »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_03', 'NPC_FRE_84', 'K0', '{"antre","colline"}', 'Son antre sous la Colline aux Souvenirs — comment y accéder', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_04', 'NPC_FRE_84', 'K1', '{"resurrection","difference"}', 'Le familier ramené n''est pas le même — « il a les mêmes yeux, mais le regard a changé »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_05', 'NPC_FRE_84', 'K1', '{"materiaux","provenance"}', 'Ses matériaux viennent du Receleur `FRE_48` — « des morceaux qui n''ont pas servi »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_06', 'NPC_FRE_84', 'K1', '{"elara","rivalite"}', 'Il connaît Elara `FRE_03` — « elle rend la vie, je rends ce qui reste »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_07', 'NPC_FRE_84', 'K2', '{"prix","souvenir"}', 'Un client a payé avec un souvenir — le nécromancien a « pris » un de ses souvenirs d''enfance', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_08', 'NPC_FRE_84', 'K2', '{"regard","vide"}', 'Les familiers ramenés ont tous le même regard — vide, mais qui suit chaque mouvement du maître', '`QUEST:QST_CAI_NECRO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_09', 'NPC_FRE_84', 'K3', '{"resurrection","code"}', 'Il ne ramène pas l''âme du familier — il duplique son entrée dans le registre du Cardinal, créant une copie qui partage les souvenirs mais pas l''essence ; le Cardinal ne détecte pas la fraude parce que la copie utilise la même signature que l''original, désormais classé « mort » mais pas « supprimé »', NULL, '*(ses doigts effleurent un crâne d''oiseau)* « Ramener un familier ? Mais il n''est jamais vraiment parti. Le système garde tout. Moi, je sais juste… où chercher. Et si tu crois que c''est de la magie, c''est que t''as jamais regardé sous le capot du monde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_84_10', 'NPC_FRE_84', 'KX', '{"*(hors sujet)*"}', '*(il se tourne vers une cage vide)* « J''ai du travail. Reviens si un de tes amis à fourrure… s''endort pour de bon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_01', 'NPC_FRE_85', 'K0', '{"tombes","colline"}', 'Les tombes de la Colline aux Souvenirs — disposition, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_02', 'NPC_FRE_85', 'K0', '{"enterrement","rituel"}', 'Le rituel d''enterrement des familiers — procédure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_03', 'NPC_FRE_85', 'K0', '{"fossoyeur","metier"}', 'Son métier de fossoyeur — histoire personnelle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_04', 'NPC_FRE_85', 'K1', '{"tombes","rebouchees"}', 'Des tombes se rebouchent toutes seules — il les creuse le matin, elles sont fermes le soir', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_05', 'NPC_FRE_85', 'K1', '{"terre","refus"}', 'La terre refuse certaines tombes — « elle les recrache »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_06', 'NPC_FRE_85', 'K1', '{"emplacements","evites"}', 'Il a des emplacements qu''il évite — « la terre y est trop vivante »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_07', 'NPC_FRE_85', 'K2', '{"tombe","son"}', 'Une tombe qu''il a creusée a émis un son — comme un ronronnement, sous la terre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_08', 'NPC_FRE_85', 'K2', '{"gardien","consigne"}', 'Le Gardien `FRE_62` lui a dit de ne plus creuser près du vieux chêne — « y a déjà quelqu''un en dessous »', '`QUEST:QST_CAI_COLLINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_09', 'NPC_FRE_85', 'K3', '{"tombes","resurrection"}', 'Les tombes qui se rebouchent sont celles de familiers dont le Cardinal n''a pas finalisé la suppression — tant que le registre les maintient en état « mort-en-attente », la terre du jeu les considère comme « occupants temporaires » et restaure la tombe à son état initial chaque cycle de maintenance nocturne', NULL, '*(il crache sur sa pelle)* « La terre, elle fait ce qu''elle veut. Pose pas de questions. Creuse, enterre, repars. C''est la règle de la Colline. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_85_10', 'NPC_FRE_85', 'KX', '{"*(hors sujet)*"}', '*(il s''éloigne, pelle sur l''épaule)* « J''ai une tombe à creuser. La terre attend pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_01', 'NPC_FRE_86', 'K0', '{"trone","acces"}', 'L''accès à la salle du trône — protocole, conditions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_02', 'NPC_FRE_86', 'K0', '{"garde","role"}', 'Son rôle de garde rapprochée — formation, équipement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_03', 'NPC_FRE_86', 'K0', '{"reine","alicia"}', 'Alicia Rue — apparence, comportement public, horaires d''audience', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_04', 'NPC_FRE_86', 'K1', '{"reine","yeux"}', 'Parfois, les yeux d''Alicia changent de couleur — une fraction de seconde', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_05', 'NPC_FRE_86', 'K1', '{"reine","repetitions"}', 'Alicia répète des phrases exactement — comme si elle rejouait une scène', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_06', 'NPC_FRE_86', 'K1', '{"consignes","silence"}', 'On lui a ordonné de ne pas parler des « variations » de la reine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_07', 'NPC_FRE_86', 'K2', '{"nuit","visiteur"}', 'La nuit, quelqu''un entre dans la chambre d''Alicia — il n''a jamais vu son visage', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_08', 'NPC_FRE_86', 'K2', '{"commandant","evasion"}', 'Le Commandant `FRE_09` esquive ses questions sur Alicia — « occupe-toi de la porte »', '`QUEST:QST_CAI_TRONE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_09', 'NPC_FRE_86', 'K3', '{"reine","copie"}', 'Alicia Rue n''est pas toujours Alicia Rue — certaines instances de la reine sont des copies de substitution que le Cardinal injecte quand l''originale est « mise à jour » ; le gardien protège un trône dont l''occupante change sans que personne le sache', NULL, '*(son regard se durcit)* « La reine est la reine. Je ne discute pas les ordres. Je ne discute pas son regard. Je la sers, c''est tout. Si t''as des questions sur elle, adresse-toi à son scribe. Moi je garde la porte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_86_10', 'NPC_FRE_86', 'KX', '{"*(hors sujet)*"}', '*(il se remet au garde-à-vous)* « L''audience est terminée. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_01', 'NPC_FRE_87', 'K0', '{"intendance","role"}', 'La gestion du palais — ses responsabilités, son équipe', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_02', 'NPC_FRE_87', 'K0', '{"comptes","finances"}', 'Les finances de la Tour du Trône Fauve — budget, dépenses', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_03', 'NPC_FRE_87', 'K0', '{"personnel","palais"}', 'Le personnel du palais — organigramme, salaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_04', 'NPC_FRE_87', 'K1', '{"ecarts","fonds"}', 'Des fonds partent vers des destinataires inconnus — elle n''a pas signé', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_05', 'NPC_FRE_87', 'K1', '{"alicia","confrontation"}', 'Alicia lui a dit « je m''en occupe » — les écarts ont continué', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_06', 'NPC_FRE_87', 'K1', '{"signatures","fausses"}', 'Des signatures qu''elle ne reconnaît pas sur des bons de paiement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_07', 'NPC_FRE_87', 'K2', '{"scribe","documents"}', 'Le Scribe Royal `FRE_58` a émis un document sans son accord — il jure que non', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_08', 'NPC_FRE_87', 'K2', '{"destinataire","null"}', 'Un destinataire régulier des fonds n''existe pas dans le registre des citoyens', '`QUEST:QST_CAI_TRONE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_09', 'NPC_FRE_87', 'K3', '{"fonds","cardinal"}', 'Les fonds détournés ne partent pas à un citoyen ni à une faction — ils sont absorbés par le système économique du serveur, réinjectés dans le pool de Yrd que le Cardinal utilise pour équilibrer l''inflation ; le trône de Freelia finance silencieusement la stabilité économique d''ALO sans que personne le vote', NULL, '*(elle referme son registre d''un coup sec)* « Les comptes sont privés. Même à toi, voyageur. Surtout à toi. Si la reine a des questions, elle sait où me trouver. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_87_10', 'NPC_FRE_87', 'KX', '{"*(hors sujet)*"}', '*(elle aligne ses plumes)* « Si tu veux un emploi au palais, dépose une candidature au bureau du personnel. Sinon, j''ai du travail. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_01', 'NPC_FRE_88', 'K0', '{"couverture","entretien"}', 'Sa couverture officielle — personnel d''entretien du palais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_02', 'NPC_FRE_88', 'K0', '{"espionnage","role"}', 'Son rôle d''espionne pour Alicia — collecte d''informations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_03', 'NPC_FRE_88', 'K0', '{"palais","secrets"}', 'Les secrets qu''elle connaît sur le palais — nombre, nature vague', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_04', 'NPC_FRE_88', 'K1', '{"conseillers","solitaires"}', 'Des conseillers d''Alicia parlent seuls dans leurs bureaux — comme s''ils s''adressaient à quelqu''un', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_05', 'NPC_FRE_88', 'K1', '{"diplomates","yeux"}', 'Des diplomates Sylphes ont les yeux qui brillent — une lueur qui n''est pas Cait Sith', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_06', 'NPC_FRE_88', 'K1', '{"visiteurs","disparition"}', 'Des visiteurs entrent dans le palais et n''en sortent pas — « ils partent par les toits »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_07', 'NPC_FRE_88', 'K2', '{"gardien","complice"}', 'Le Gardien du Trône `FRE_86` sait qu''elle espionne — il détourne le regard', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_08', 'NPC_FRE_88', 'K2', '{"alicia","double"}', 'Alicia n''est pas toujours la même — elle a vu la reine « changer » en pleine conversation', '`QUEST:QST_CAI_TRONE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_09', 'NPC_FRE_88', 'K3', '{"agents","cardinaux"}', 'Les conseillers qui parlent seuls et les diplomates aux yeux brillants sont des agents d''insertion du Cardinal — des PNJ que le système greffe dans l''entourage d''Alicia pour surveiller la fidélité de Freelia à l''alliance Sylph et prévenir toute tentative de sécession du serveur', NULL, '*(elle colle son dos au mur, prête à disparaître)* « Je suis une servante. Je nettoie les couloirs. Je sais rien des affaires de la reine. Et toi non plus, compris ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_88_10', 'NPC_FRE_88', 'KX', '{"*(hors sujet)*"}', '*(elle a disparu entre deux phrases)*', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_01', 'NPC_FRE_89', 'K0', '{"memorial","colline"}', 'Le mémorial des chasseurs morts — emplacement, histoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_02', 'NPC_FRE_89', 'K0', '{"noms","gravure"}', 'La gravure des noms — procédure, outils, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_03', 'NPC_FRE_89', 'K0', '{"chasseurs","liste"}', 'La liste des chasseurs tombés — quelques noms célèbres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_04', 'NPC_FRE_89', 'K1', '{"nom","refus"}', 'Un nom refuse de se laisser graver — le burin dérape à chaque fois', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_05', 'NPC_FRE_89', 'K1', '{"essais","cinq"}', 'Il a essayé cinq fois — cinq échecs, le burin a glissé cinq fois', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_06', 'NPC_FRE_89', 'K1', '{"pierre","parole"}', 'Il jure que la pierre lui a parlé une fois — « pas encore »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_07', 'NPC_FRE_89', 'K2', '{"nom","chasseur"}', 'Le nom qui refuse est celui d''un chasseur porté disparu — pas de corps retrouvé', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_08', 'NPC_FRE_89', 'K2', '{"archiviste","croisement"}', 'L''Archiviste `FRE_63` dit que ce chasseur est « en attente » dans son registre', '`QUEST:QST_CAI_COLLINE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_09', 'NPC_FRE_89', 'K3', '{"pierre","systeme"}', 'La pierre du mémorial n''est pas un objet décoratif — c''est une interface de sortie du registre des âmes ; quand un nom refuse d''être gravé, c''est que le Cardinal n''a pas verrouillé l''état « mort » du joueur, le maintenant dans un statut « déconnecté » qui empêche le système de sceller son épitaphe', NULL, '*(il passe un doigt sur la pierre lisse)* « La pierre a ses humeurs. Parfois elle accepte un nom, parfois non. J''ai arrêté de chercher pourquoi. Je suis vieux. La pierre est plus vieille que moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_89_10', 'NPC_FRE_89', 'KX', '{"*(hors sujet)*"}', '*(il taille un coin de pierre, la poussière vole)* « Si t''as un nom à graver, laisse-le sur le parchemin. Je m''en occupe demain. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_01', 'NPC_FRE_90', 'K0', '{"refuge","collines"}', 'Sa vie de réfugié dans les Collines de l''Ouest — survie, cachettes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_02', 'NPC_FRE_90', 'K0', '{"frontiere","guerre"}', 'La guerre à la frontière Sylph-Salamander — ce qu''il a vu', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_03', 'NPC_FRE_90', 'K0', '{"identite","cachee"}', 'Son vrai nom — il ne le donne à personne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_04', 'NPC_FRE_90', 'K1', '{"trahison","double"}', 'Il sait qui trahit les deux camps — un nom qu''il n''a pas encore donné', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_05', 'NPC_FRE_90', 'K1', '{"nya-ran","piege"}', 'Nya-Ran `NPC_SWI_07` l''a utilisé comme appât — « elle m''a vendu pour une mission »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_06', 'NPC_FRE_90', 'K1', '{"offensive","secrete"}', 'Une offensive Salamander se prépare — Freelia n''est pas prête', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_07', 'NPC_FRE_90', 'K2', '{"zephyr","mefiance"}', 'Zephyr `FRE_02` lui offre de l''aide — il refuse, ne lui fait pas confiance', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_08', 'NPC_FRE_90', 'K2', '{"traite","nom"}', 'Il écrira le nom du traître sur un parchemin — « quand je serai loin d''ici »', '`QUEST:QST_CAI_FRONTIERE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_09', 'NPC_FRE_90', 'K3', '{"nya-ran","cardinal"}', 'Nya-Ran n''a pas agi seule — elle suivait des instructions injectées par le Cardinal via un agent dormant Sylph ; le piège était un test de loyauté entre les factions, et il était le paramètre sacrificiel d''une équation plus large que la guerre de frontière', NULL, '*(il recule, les yeux écarquillés)* « Je sais rien. Je suis personne. J''ai rien vu, j''ai rien entendu, j''étais pas là. Laisse-moi tranquille. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_90_10', 'NPC_FRE_90', 'KX', '{"*(hors sujet)*"}', '*(déjà en train de s''éloigner)* « On s''est pas vus. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_01', 'NPC_FRE_91', 'K0', '{"musique","instruments"}', 'Les instruments de musique enchantés qu''il vend — types, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_02', 'NPC_FRE_91', 'K0', '{"composants","echange"}', 'Ce qu''il achète — plumes, griffes, écailles, os rares', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_03', 'NPC_FRE_91', 'K0', '{"lioda","voyage"}', 'Lioda, la capitale Puca — description, distance, culture', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_04', 'NPC_FRE_91', 'K1', '{"ecoute","rumeurs"}', 'Il écoute les conversations au Marché — « la musique porte les voix »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_05', 'NPC_FRE_91', 'K1', '{"information","lioda"}', 'Il transmet des informations à Lioda — « des chansons qui parlent »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_06', 'NPC_FRE_91', 'K1', '{"clients","secrets"}', 'Des clients qui laissent échapper des secrets en marchandant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_07', 'NPC_FRE_91', 'K2', '{"courtier","couverture"}', 'Le Courtier `FRE_94` utilise sa musique pour couvrir ses conversations', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_08', 'NPC_FRE_91', 'K2', '{"flute","message"}', 'Sa flûte joue des mélodies qui sont des messages codés pour Lioda', '`QUEST:QST_CAI_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_09', 'NPC_FRE_91', 'K3', '{"musique","cardinal"}', 'Les instruments enchantés qu''il vend ne sont pas de simples artefacts — ils enregistrent les conversations tenues à moins de cinq mètres et les encodent dans les vibrations du bois, que le Cardinal écoute via le module audio du serveur pour surveiller les échanges entre factions', NULL, '*(il range sa flûte)* « La musique, c''est personnel. Chaque note est une émotion. Je joue, tu écoutes, on échange. Y a pas de message caché. Juste de la belle musique. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_91_10', 'NPC_FRE_91', 'KX', '{"*(hors sujet)*"}', '*(il entame une mélodie)* « Écoute ça. Ça te rappelle pas quelque chose ? … Non ? Dommage. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_01', 'NPC_FRE_92', 'K0', '{"diplomatie","role"}', 'Son rôle d''envoyé entre Swilvane et Freelia', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_02', 'NPC_FRE_92', 'K0', '{"sakuya","messages"}', 'Les messages officiels de Sakuya — contenu visible, protocole', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_03', 'NPC_FRE_92', 'K0', '{"alliance","traite"}', 'Le traité d''alliance Sylph-Cait Sith — termes, durée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_04', 'NPC_FRE_92', 'K1', '{"zephyr","messages"}', 'Zephyr `FRE_02` lui confie des messages — il les transmet comme venant de Sakuya', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_05', 'NPC_FRE_92', 'K1', '{"chantage","raison"}', 'Zephyr le fait chanter — « il sait quelque chose sur moi »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_06', 'NPC_FRE_92', 'K1', '{"mensonge","origine"}', 'Un quart des messages ne viennent pas de Sakuya — il ment sur leur origine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_07', 'NPC_FRE_92', 'K2', '{"secret","chantage"}', 'Le secret que Zephyr utilise contre lui — une mission Sylph qui a mal tourné à la frontière', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_08', 'NPC_FRE_92', 'K2', '{"alicia","soupcon"}', 'Alicia `FRE_08` commence à soupçonner que ses messages sont falsifiés', '`QUEST:QST_CAI_DIPLO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_09', 'NPC_FRE_92', 'K3', '{"zephyr","cardinal"}', 'Zephyr ne fait pas chanter l''envoyé pour son propre compte — il exécute les ordres d''un agent Sylph du Cardinal, qui utilise le réseau diplomatique pour injecter de la désinformation dans la cour d''Alicia et tester la loyauté de l''alliance par des stress tests informationnels', NULL, '*(il lisse sa tunique, évite ton regard)* « Je transmets les messages de la Lady Sakuya. Rien de plus. Si quelqu''un prétend le contraire, il ment. La diplomatie repose sur la confiance. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_92_10', 'NPC_FRE_92', 'KX', '{"*(hors sujet)*"}', '*(il vérifie trois fois le sceau d''un parchemin)* « Si tu veux parler à la reine, prends rendez-vous avec le Gardien du Trône. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_01', 'NPC_FRE_93', 'K0', '{"gemmes","catalogue"}', 'Les gemmes qu''il vend — types, prix, origine déclarée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_02', 'NPC_FRE_93', 'K0', '{"fourrures","achat"}', 'Les fourrures qu''il achète — critères de qualité, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_03', 'NPC_FRE_93', 'K0', '{"granzam","commerce"}', 'Le commerce entre Granzam et Freelia — routes, durée, risques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_04', 'NPC_FRE_93', 'K1', '{"gemmes","origine"}', 'Ses gemmes sont trop pures — « elles viennent pas des mines officielles »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_05', 'NPC_FRE_93', 'K1', '{"douaniers","pots"}', 'Il paie les douaniers pour ne pas déclarer toutes ses marchandises', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_06', 'NPC_FRE_93', 'K1', '{"destinataires","secrets"}', 'Certaines fourrures partent vers des destinataires non enregistrés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_07', 'NPC_FRE_93', 'K2', '{"granzam","peur"}', 'Il a peur de retourner à Granzam — « quelqu''un m''attend là-bas »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_08', 'NPC_FRE_93', 'K2', '{"courtier","complicite"}', 'Le Courtier `FRE_94` l''aide à blanchir ses gemmes via des transactions fictives', '`QUEST:QST_CAI_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_09', 'NPC_FRE_93', 'K3', '{"gemmes","cardinal"}', 'Les gemmes ne viennent pas de Granzam — elles sont générées par le système économique du Cardinal pour injecter des liquidités dans l''économie de Freelia et compenser les sorties de Yrd vers le trône ; il est un agent inconscient de régulation monétaire, un robinet de gemmes que le Cardinal ouvre et ferme selon les besoins du serveur', NULL, '*(sa jovialité s''efface une seconde)* « Mes gemmes ? Elles viennent de Granzam, d''où veux-tu qu''elles viennent ? J''ai des papiers, j''ai des licences, j''ai tout ce qu''il faut. Si tu veux pas acheter, dégage de mon étal. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_93_10', 'NPC_FRE_93', 'KX', '{"*(hors sujet)*"}', '*(il polir une gemme sur son tablier)* « Marchandage interdit. Les prix sont justes. Juste trop élevés pour ta bourse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_01', 'NPC_FRE_94', 'K0', '{"courtage","service"}', 'Ses services de courtier — médiation, traduction, conseil fiscal', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_02', 'NPC_FRE_94', 'K0', '{"marches","taxes"}', 'Les taxes du Marché aux Crocs — par race, par produit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_03', 'NPC_FRE_94', 'K0', '{"mediateur","role"}', 'Son rôle de médiateur neutre — impartialité affichée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_04', 'NPC_FRE_94', 'K1', '{"nox","couverture"}', 'Il sert de prête-nom à Nox `FRE_05` — des contrats signés sous son nom', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_05', 'NPC_FRE_94', 'K1', '{"chantage","dossier"}', 'Nox a un dossier sur lui — « il sait des choses que le Cardinal devrait ignorer »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_06', 'NPC_FRE_94', 'K1', '{"transactions","fictives"}', 'Des transactions qu''il enregistre sont fictives — « des papiers qui équilibrent des comptes »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_07', 'NPC_FRE_94', 'K2', '{"gnome","blanchiment"}', 'Il aide le Trafiquant Gnome `FRE_93` à blanchir ses gemmes', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_08', 'NPC_FRE_94', 'K2', '{"dossier","cardinal"}', 'Le dossier que Nox détient vient du Cardinal — « quelqu''un l''a sorti des archives »', '`QUEST:QST_CAI_MARCHE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_09', 'NPC_FRE_94', 'K3', '{"dossier","contenu"}', 'Le dossier contient la preuve que le courtier est un agent de liaison du Cardinal infiltré pour surveiller le Marché aux Crocs — mais Nox a intercepté les preuves avant qu''elles ne soient remontées au système, et utilise le dossier pour retourner l''agent contre le Cardinal lui-même', NULL, '*(il ajuste sa cravate, impassible)* « Je suis un courtier. Je facilite les échanges. Si vous avez des questions sur l''éthique de mes transactions, adressez-vous à la Chambre de Commerce. Moi, je ne fais que mon travail. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_94_10', 'NPC_FRE_94', 'KX', '{"*(hors sujet)*"}', '*(il tend une carte de visite)* « Si tu as besoin de mes services, tu sais où me trouver. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_01', 'NPC_FRE_95', 'K0', '{"chasse","exploits"}', 'Ses exploits de chasse — les monstres qu''il a tués, les records', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_02', 'NPC_FRE_95', 'K0', '{"roi behemoth","recit"}', 'Le récit public de sa chasse au Roi Béhémoth — « combat épique, victoire difficile »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_03', 'NPC_FRE_95', 'K0', '{"retraite","taverne"}', 'Sa vie à la Taverne Chat Botté — routine, habitudes, prix des bières', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_04', 'NPC_FRE_95', 'K1', '{"behemoth","mensonge"}', 'Sa version publique du combat est arrangée — il ment sur quelque chose', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_05', 'NPC_FRE_95', 'K1', '{"equipe","mort"}', 'Les membres de son équipe ne sont pas morts au combat — il a fui, les a laissés', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_06', 'NPC_FRE_95', 'K1', '{"cicatrice","vrai"}', 'La cicatrice sur son torse — il ne l''a pas eue en combattant le Béhémoth', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_07', 'NPC_FRE_95', 'K2', '{"behemoth","vrai mort"}', 'Le Roi Béhémoth ne peut pas être tué — « il respawn, il a toujours respawné, on a juste fermé la porte »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_08', 'NPC_FRE_95', 'K2', '{"murmure","cave"}', 'Il murmure des choses ivre mort — « la porte du fond », « les yeux dans le noir », « il nous attend »', '`QUEST:QST_CAI_BEHEMOTH_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_09', 'NPC_FRE_95', 'K3', '{"behemoth","cardinal"}', 'Le Roi Béhémoth n''est pas un boss normal — c''est un gardien de seuil placé par le Cardinal pour verrouiller l''accès à une zone non déployée du serveur ; le combat n''a pas « tué » le boss, il a corrompu l''instance, et son groupe a été absorbé comme payload de maintenance pour réparer la brèche', NULL, '*(il repose sa bière, la main tremblante)* « Le Roi Béhémoth est mort. Je l''ai tué. Y a pas d''histoire. Y a pas de mystère. C''était un combat, j''ai gagné, les autres ont perdu. C''est la chasse. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_95_10', 'NPC_FRE_95', 'KX', '{"*(hors sujet)*"}', '*(il commande une autre bière)* « Trouve-moi un autre sujet. Ou trouve-moi un autre verre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_01', 'NPC_FRE_96', 'K0', '{"formation","domptage"}', 'La formation au domptage — programme, durée, prérequis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_02', 'NPC_FRE_96', 'K0', '{"techniques","base"}', 'Les techniques de base — rappel, ordres, synchronisation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_03', 'NPC_FRE_96', 'K0', '{"savane","entrainement"}', 'Les zones d''entraînement dans la Savane des Crocs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_04', 'NPC_FRE_96', 'K1', '{"recrue","familier"}', 'Une recrue était un familier — un animal qui avait pris forme humaine', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_05', 'NPC_FRE_96', 'K1', '{"decouverte","hasard"}', 'Il l''a découvert en voyant la recrue « changer » de forme en dormant', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_06', 'NPC_FRE_96', 'K1', '{"silence","complicite"}', 'Il n''a rien dit — il a laissé la recrue terminer sa formation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_07', 'NPC_FRE_96', 'K2', '{"recrue","depart"}', 'La recrue est partie vers la Colline aux Souvenirs — « elle cherchait quelqu''un »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_08', 'NPC_FRE_96', 'K2', '{"guide","confirmation"}', 'Le Guide Savane `FRE_11` avait aussi remarqué — « on s''est dit que c''était pas notre affaire »', '`QUEST:QST_CAI_DRESSAGE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_09', 'NPC_FRE_96', 'K3', '{"recrue","nature"}', 'La recrue n''était pas un joueur déguisé — c''était un familier dont le lien d''âme avec son maître avait été inversé par une faille du système de domptage, donnant à la bête la forme de son dompteur ; le Cardinal n''a jamais corrigé l''anomalie parce que l''inversion n''a pas produit d''erreur dans les logs', NULL, '*(il regarde l''horizon)* « Mes recrues, je les forme et je les laisse partir. Ce qu''elles sont avant d''arriver, ce qu''elles deviennent après, c''est pas mes affaires. Je suis instructeur, pas inquisiteur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_96_10', 'NPC_FRE_96', 'KX', '{"*(hors sujet)*"}', '*(il siffle un ordre à un familier d''entraînement)* « Reviens quand tu veux apprendre. Pas quand tu veux poser des questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_01', 'NPC_FRE_97', 'K0', '{"trophées","exposition"}', 'Les trophées exposés — catalogue, histoire de chaque pièce', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_02', 'NPC_FRE_97', 'K0', '{"taxidermie","metier"}', 'La taxidermie — techniques, outils, philosophie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_03', 'NPC_FRE_97', 'K0', '{"memoire","chasse"}', 'Le mémorial des grandes chasses — histoire, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_04', 'NPC_FRE_97', 'K1', '{"preparation","vivant"}', 'Il prépare certains trophées sur des bêtes encore vivantes — « pour l''expression »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_05', 'NPC_FRE_97', 'K1', '{"manticore","mouvement"}', 'La tête de Manticore bouge la nuit — les yeux suivent les visiteurs', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_06', 'NPC_FRE_97', 'K1', '{"peur","verification"}', 'Il n''a jamais vérifié le mécanisme de la Manticore — « j''aurais trop peur »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_07', 'NPC_FRE_97', 'K2', '{"manticore","gueule"}', 'La gueule de la Manticore s''ouvre et se ferme — comme si elle respirait', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_08', 'NPC_FRE_97', 'K2', '{"taxidermiste","provenance"}', 'Le Taxidermiste `FRE_36` lui a vendu la Manticore — « elle vient de la Colline, pas de la savane »', '`QUEST:QST_CAI_TROPHEE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_09', 'NPC_FRE_97', 'K3', '{"manticore","resurrection"}', 'La Manticore n''est pas morte — elle a été figée dans un état de suspension par le système de résurrection des familiers, un « entre-deux » où le corps est conservé mais l''âme n''est pas encore réaffectée ; le trophée est une instance gelée d''un familier en cours de traitement par le Cardinal, exposée par erreur', NULL, '*(il recouvre la tête de Manticore d''un drap)* « Y a rien d''anormal. Les trophées, ils bougent à cause des courants d''air. La Manticore, elle est juste… bien conservée. Très bien conservée. Trop bien, peut-être. Mais c''est mon métier. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_97_10', 'NPC_FRE_97', 'KX', '{"*(hors sujet)*"}', '*(il époussette un crâne de wyverne)* « Si tu veux un trophée, je prends les commandes. Mais faut amener la bête encore chaude. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_01', 'NPC_FRE_98', 'K0', '{"oracle","colline"}', 'L''Oracle de la Colline — qui elle est, d''où elle vient (personne ne sait)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_02', 'NPC_FRE_98', 'K0', '{"os","divination"}', 'La divination par les os — méthode, interprétation, fiabilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_03', 'NPC_FRE_98', 'K0', '{"predictions","connues"}', 'Ses prédictions célèbres — celles qui se sont réalisées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_04', 'NPC_FRE_98', 'K1', '{"vision","premier"}', 'Elle a vu le premier familier dans les os — « une ombre qui précède la lumière »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_05', 'NPC_FRE_98', 'K1', '{"voix","autre"}', 'Quand elle prophétise, sa voix change — « ce n''est pas la mienne »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_06', 'NPC_FRE_98', 'K1', '{"logs","visions"}', 'Ses visions sont des « morceaux de mémoire du serveur » — elle le sait', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_07', 'NPC_FRE_98', 'K2', '{"memoire","FRE_99"}', 'La Mémoire `FRE_99` est la seule qui comprend ses visions — « elle était là au début »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_08', 'NPC_FRE_98', 'K2', '{"ombre","vision"}', 'Elle a vu l''Ombre du Premier `FRE_00` dans les os — « elle est la clé d''une porte verrouillée »', '`QUEST:QST_CAI_PROPHETIE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_09', 'NPC_FRE_98', 'K3', '{"os","logs serveur"}', 'Les os ne sont pas des supports divinatoires — ils sont des interfaces de lecture des logs du Cardinal ; quand elle les jette, les motifs qu''ils forment sont des index mémoire du serveur, et elle « lit » les enregistrements de domptage comme on lirait un fichier texte dont elle a la clé de déchiffrement', NULL, '*(elle tient un os, le tourne, le pose)* « Les os tombent comme ils tombent. Je ne choisis pas ce qu''ils disent. Si tu n''aimes pas la réponse, jette toi-même les os. Mais tu ne sauras pas les lire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_98_10', 'NPC_FRE_98', 'KX', '{"*(hors sujet)*"}', '*(elle lance les os, les regarde sans les voir)* « La question que tu poses n''a pas de réponse dans les os. Reviens avec une autre question. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_01', 'NPC_FRE_99', 'K0', '{"memoire","role"}', 'Son rôle de mémoire vivante de Freelia — elle se souvient de tout', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_02', 'NPC_FRE_99', 'K0', '{"premier","familier"}', 'Des fragments de souvenir du premier familier dompté — époque, circonstances', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_03', 'NPC_FRE_99', 'K0', '{"colline","histoire"}', 'L''histoire de la Colline aux Souvenirs — sa création, son évolution', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_04', 'NPC_FRE_99', 'K1', '{"cardinal","archive"}', 'Le Cardinal archive tout — « y compris ce qu''il promet d''oublier »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_05', 'NPC_FRE_99', 'K1', '{"logs","fondateurs"}', 'Les logs fondateurs existent encore — elle sait où', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_06', 'NPC_FRE_99', 'K1', '{"ombre","nature"}', 'Elle connaît la nature de l''Ombre `FRE_00` — « elle est ce qui reste de ce qui a été le premier »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_07', 'NPC_FRE_99', 'K2', '{"stockage","noeud"}', 'Sa mémoire est un nœud de stockage du Cardinal — elle est une archive vivante', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_08', 'NPC_FRE_99', 'K2', '{"oracle","confiance"}', 'L''Oracle `FRE_98` voit les mêmes choses — « les os et moi, on lit la même bibliothèque »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_09', 'NPC_FRE_99', 'K2', '{"leo","ecoute"}', 'Léo `FRE_01` est venu l''écouter une fois — « il n''a pas compris, mais il a senti »', '`QUEST:QST_CAI_MEMOIRE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_10', 'NPC_FRE_99', 'K3', '{"premier","vermeil"}', 'Le premier familier n''était pas une bête ordinaire — c''était un Vermeil, un familier de rang mythique que le jeu n''a jamais reproduit parce que son template a été verrouillé après le domptage fondateur ; les données de son template sont stockées dans le segment protégé du serveur, accessibles uniquement par une clé que le Cardinal a confiée à sa mémoire', NULL, '*(elle ferme les yeux, un sourire triste)* « Le premier familier ? C''était un Vermeil. Mais ça, le monde l''a oublié. Et peut-être que c''est mieux comme ça. Certains souvenirs sont trop grands pour être portés par tout le monde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_11', 'NPC_FRE_99', 'K3', '{"cle","segment protege"}', 'La clé du segment protégé est dans sa mémoire — elle peut la transmettre à celui qui posera la bonne question, la question que personne n''a encore posée parce que personne ne sait qu''il faut la poser', NULL, '*(elle se tait, ses yeux deviennent vides)* « Je ne me souviens plus. C''est étrange… d''habitude je me souviens de tout. Mais cette partie… elle s''efface quand on me la demande. Peut-être que la question n''est pas la bonne. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_FRE_99_12', 'NPC_FRE_99', 'KX', '{"*(hors sujet)*"}', '*(elle regarde le ciel, perdue dans un autre temps)* « Le vent porte des noms que plus personne ne prononce. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_01', 'NPC_GAT_00', 'K0', '{"porte","entree","direction"}', 'Les directions de la Grande Porte et les horaires de relève de la garde', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_02', 'NPC_GAT_00', 'K0', '{"cendre","balai","meteo"}', 'La cendre tombe plus épaisse quand la Caldeira « respire »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_03', 'NPC_GAT_00', 'K1', '{"passages","habitudes"}', 'Qui entre et sort, à quelle heure — 40 ans d''observation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_04', 'NPC_GAT_00', 'K1', '{"rumeurs","place"}', 'Les rumeurs qu''il entend en balayant (relais K0 des autres PNJ)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_05', 'NPC_GAT_00', 'K1', '{"ville","histoire"}', 'La fondation de Gattan, version des balayeurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_06', 'NPC_GAT_00', 'K2', '{"contrebande","nuit"}', 'A vu ce que Vanna `NPC_GAT_73` laisse passer la nuit', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_07', 'NPC_GAT_00', 'K2', '{"scories","oreille"}', 'Où trouver Fitch « l''Oreille » `NPC_GAT_89` un soir de pluie', '`QUEST:QST_SAL_INFO_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_08', 'NPC_GAT_00', 'K2', '{"caldeira","logi"}', '« Logi ne dort pas. Il compte. » — indice de mécanique du boss', '`TITLE:TITLE_SAL_VETERAN`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_09', 'NPC_GAT_00', 'K3', '{"cardinal","systeme","seed"}', 'Il EST un sous-processus du Cardinal ; il connaît les quotas de spawn de la zone', NULL, '« Le balai balaie. C''est tout ce qu''il fait, petit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_10', 'NPC_GAT_00', 'K3', '{"anomalie","joueurs"}', 'Il tient la liste des joueurs « anormaux » signalés à l''orchestrateur', NULL, '« Je ne regarde que la poussière. Elle me suffit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_11', 'NPC_GAT_00', 'K3', '{"mortimer","palais"}', 'Ce que le Lord murmure quand il traverse la Porte seul, à l''aube', NULL, '« Les grands parlent au vent. Le vent ne me parle pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_00_12', 'NPC_GAT_00', 'KX', '{"*(tout le reste)*"}', '« Hé hé… demande à quelqu''un qui a encore ses oreilles, va. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
