('QI_GAT_01_03', 'NPC_GAT_01', 'K0', '{"metier","forge"}', 'Où apprendre la forge (renvoi guilde des forges, Vulko `NPC_GAT_29`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_04', 'NPC_GAT_01', 'K1', '{"materiaux","minerai"}', 'Quels minerais pour quels tiers — dont le mithril de Brokkheim exigé en T4/T5', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
