INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_06', 'NPC_GAT_01', 'K1', '{"mobs","drops"}', 'Quels drops de `MOB_SAL_*` il rachète pour la forge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_07', 'NPC_GAT_01', 'K2', '{"craft","magma"}', 'La recette de la Couronne de Magma Dormant (`ARM_TET_016`)', '`QUEST:QST_SAL_FORGE_01+ITEM:MAT_SAL_COEUR_MAGMA`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_08', 'NPC_GAT_01', 'K2', '{"gram","entretien"}', 'Comment Gram se comporte à la forge — « elle chante faux »', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_09', 'NPC_GAT_01', 'K2', '{"brokkheim","formation"}', 'Sa formation chez les Leprechauns et ce qu''il y a laissé', '`AFF>=70+PAY:200`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_10', 'NPC_GAT_01', 'K3', '{"lame","brisee"}', 'La lame brisée : pour QUI elle était forgée, et pourquoi il a raté la trempe', NULL, '*(il pose son marteau)* « La forge est fermée pour toi aujourd''hui. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_11', 'NPC_GAT_01', 'K3', '{"heaume","coeur de forge"}', 'Le rituel exact du craft T5 `ARM_TET_018` (co-forgé avec Brokk IX)', NULL, '« Reviens quand Gattan te connaîtra par ton nom. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_01_12', 'NPC_GAT_01', 'KX', '{"*(tout le reste)*"}', '« Je forge. Le reste, c''est du bruit. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_01', 'NPC_GAT_02', 'K0', '{"armure","prix","catalogue"}', 'Catalogue armures lourdes/boucliers T2-T4, dont `ARM_TET_012` Heaume de Basalte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_02', 'NPC_GAT_02', 'K0', '{"taille","ajustement"}', 'Service d''ajustement d''armure (gratuit à l''achat)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_03', 'NPC_GAT_02', 'K0', '{"quartier","militaire"}', 'Plan du Quartier Militaire et horaires des instructeurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_04', 'NPC_GAT_02', 'K1', '{"penalites","vol"}', 'Pénalités de vol par classe d''armure (Plaque -3/-6% — grille D14)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_05', 'NPC_GAT_02', 'K1', '{"surchauffe","caldeira"}', 'Pourquoi le `ARM_TET_014` réduit la Surchauffe : doublage céramique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_06', 'NPC_GAT_02', 'K1', '{"entretien"}', 'Entretien du métal en zone volcanique (cendre = rouille acide)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_07', 'NPC_GAT_02', 'K2', '{"legionnaire","craft"}', 'Recette du Heaume du Légionnaire d''Obsidienne (`ARM_TET_014`)', '`QUEST:QST_SAL_ARMURE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_08', 'NPC_GAT_02', 'K2', '{"desertion","raid"}', 'Sa version complète de la nuit de la « désertion »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_09', 'NPC_GAT_02', 'K2', '{"armee","defauts"}', 'Les défauts connus des armures de série de l''armée (utile en PvP faction)', '`AFF>=80+RACE:SALAMANDER`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_10', 'NPC_GAT_02', 'K3', '{"piege","embuscade"}', 'QUI avait tendu le piège cette nuit-là — un nom encore en service', NULL, '« J''ai payé pour me taire une fois. Le prix n''a pas baissé. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_11', 'NPC_GAT_02', 'K3', '{"volcanus"}', 'Ce que Volcanus lui a dit le jour de sa réhabilitation', NULL, '« Ça, c''est entre lui, moi, et une bouteille vide. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_02_12', 'NPC_GAT_02', 'KX', '{"*(tout le reste)*"}', '« Pas mon rayon. Moi c''est le fer, pas les devinettes. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_01', 'NPC_GAT_03', 'K0', '{"potions","prix"}', 'Catalogue : potions de force, antifeu, bombes incendiaires (licence d''État)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_02', 'NPC_GAT_03', 'K0', '{"alchimie","apprendre"}', 'Où apprendre `!alchimie` (il prend des élèves — qui survivent, en général)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_03', 'NPC_GAT_03', 'K0', '{"ruelle"}', 'Qui fait quoi dans la Ruelle de l''Alchimiste', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_04', 'NPC_GAT_03', 'K1', '{"ingredients","recolte"}', 'Quelles herbes des Plaines de Cendres pour quelles bases (`!gather`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_05', 'NPC_GAT_03', 'K1', '{"resistances","feu"}', 'Théorie des résistances élémentaires et du cumul de buffs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_06', 'NPC_GAT_03', 'K1', '{"venins"}', 'Ce que valent les glandes de `MOB_SAL_*` (renvoie à Vess `NPC_GAT_63` pour la vente)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_07', 'NPC_GAT_03', 'K2', '{"antidote","surchauffe"}', 'Formule du Tonique de Caldeira (réduction jauge HEAT, D12)', '`QUEST:QST_SAL_ALCHI_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_08', 'NPC_GAT_03', 'K2', '{"experience","cobaye"}', 'Le journal de ses auto-expérimentations (buffs non documentés)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_09', 'NPC_GAT_03', 'K2', '{"commande","armee"}', 'Ce que l''armée lui commande en ce moment — « du volume, disons »', '`AFF>=70+RACE:SALAMANDER`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_10', 'NPC_GAT_03', 'K3', '{"formule","interdite"}', 'La formule qu''il a scellée : une bombe qui brûle même sous l''eau', NULL, '« J''ai oublié. Volontairement. C''est une compétence, tu sais. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_11', 'NPC_GAT_03', 'K3', '{"oeil","accident"}', 'Ce que son œil gauche voit VRAIMENT depuis l''accident', NULL, '*(il couvre son œil)* « Lui, il ne répond pas aux questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_03_12', 'NPC_GAT_03', 'KX', '{"*(tout le reste)*"}', '« Hmm ? Non, aucune idée. Nyssa ! On sait ça, nous ? Non. Voilà. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_01', 'NPC_GAT_04', 'K0', '{"familiers","prix"}', 'Catalogue : salamandres de compagnie, phénix miniatures, tarifs de pension', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_02', 'NPC_GAT_04', 'K0', '{"soins","nourriture"}', 'Que mange un familier de feu (`!pet_feed`) — jamais de glace, évidemment', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_03', 'NPC_GAT_04', 'K0', '{"domptage","base"}', 'Bases du `!tame` : approche, offrande, patience', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_04', 'NPC_GAT_04', 'K1', '{"especes","feu"}', 'Éthologie des bêtes de feu des Plaines et de la Désolation (`MOB_SAL_*` apprivoisables)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_05', 'NPC_GAT_04', 'K1', '{"oeufs","eclosion"}', 'Conditions d''éclosion (température, proximité de lave)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_06', 'NPC_GAT_04', 'K1', '{"resurrection","pet"}', 'Comment fonctionne `!pet_resurrect` et ses limites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_07', 'NPC_GAT_04', 'K2', '{"alpha","nid"}', 'Où niche l''alpha apprivoisable de la Désolation de Magma', '`AFF>=70+QUEST:QST_SAL_TAME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_04_08', 'NPC_GAT_04', 'K2', '{"phenix","vrai"}', 'Le phénix miniature n''est PAS une miniature — c''est un juvénile', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
