INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_06_11', 'NPC_GAT_06', 'K3', '{"balayeur"}', 'Ce qu''il a compris sur le Vieux Sorren — et pourquoi il ne le chasse pas', NULL, '*(il regarde ailleurs)* « Il balaie bien. C''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
