INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_11_11', 'NPC_GAT_11', 'K3', '{"cardinal","spawns"}', 'Elle a compris que les « cycles » du gibier sont artificiels — et note les exceptions', NULL, '« Les plaines ont leurs règles. Je ne discute pas les règles. Je chasse. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
