INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_12_11', 'NPC_GAT_12', 'K3', '{"veine","interdite"}', 'L''entrée de la veine qu''il a condamnée de ses mains — ce qu''il y a entendu creuser DE L''AUTRE CÔTÉ', NULL, '*(il sourit trop vite)* « Y''a rien là-bas. Rien. Achète une carte. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
