INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_16_10', 'NPC_GAT_16', 'K3', '{"chose","nuages"}', 'La CHOSE qu''il a vue dans les nuages pendant sa chute — plus grande que quatre wyvernes', NULL, '*(il regarde le ciel)* « Le ciel garde ses bêtes. Moi je garde ma halte. Chacun chez soi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_16_11', 'NPC_GAT_16', 'K3', '{"wyverne","mort"}', 'Sa wyverne n''est pas morte d''épuisement — quelque chose l''a mordue AU-DESSUS des nuages', NULL, '« Elle est morte en vol. Point. On boit à sa mémoire ou on change de sujet. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_16_12', 'NPC_GAT_16', 'KX', '{"*(tout le reste)*"}', '« Je connais le ciel entre ici et Alne. Le reste du monde, très peu pour moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_01', 'NPC_GAT_17', 'K0', '{"ciel","alerte"}', 'L''état du ciel en temps réel (prédateurs en vol ou non)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_02', 'NPC_GAT_17', 'K0', '{"signaux","code"}', 'Le code des signaux de la Tour (une corne = vu, deux = en chasse, trois = fuyez)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_03', 'NPC_GAT_17', 'K0', '{"tour","montee"}', 'On peut monter à la Tour (vue imprenable, point de `!mark` populaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_04', 'NPC_GAT_17', 'K1', '{"reperage","technique"}', 'Ses techniques de repérage (contre-jour, ombres portées, vols d''oiseaux)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_05', 'NPC_GAT_17', 'K1', '{"roc","habitudes"}', 'Les habitudes de chasse de chaque `MOB_AIR_001-004` — elle les a nommés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_06', 'NPC_GAT_17', 'K1', '{"trafic","route"}', 'Qui est passé sur la route aujourd''hui (voyageurs, convois)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_07', 'NPC_GAT_17', 'K2', '{"nid","roc"}', 'Où niche « Vieille-Serre », le roc dominant du secteur', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_08', 'NPC_GAT_17', 'K2', '{"angle mort"}', 'L''angle mort de la Tour — le seul couloir qu''elle ne peut PAS surveiller', '`AFF>=80+RACE:SALAMANDER`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_09', 'NPC_GAT_17', 'K2', '{"pari","tour"}', 'Le pari qui l''a fait grimper ici — et ce qu''elle y a trouvé gravé au sommet', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_10', 'NPC_GAT_17', 'K3', '{"lumiere","yggdrasil"}', 'La lumière qu''elle voit certains soirs au sommet d''Yggdrasil — et qui lui répond quand elle signale', NULL, '*(elle range sa longue-vue)* « Le règlement dit : signaler les menaces. Ça, c''en est pas une. Enfin… je crois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_11', 'NPC_GAT_17', 'K3', '{"halric","chose"}', 'Elle a vu la CHOSE de Halric, une fois. Elle a préféré ne pas l''inscrire au registre', NULL, '« Mon registre est public. S''il n''y est pas, je ne l''ai pas vu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_17_12', 'NPC_GAT_17', 'KX', '{"*(tout le reste)*"}', '« Si ça ne vole pas et que ça ne passe pas sur ma route, je ne l''ai jamais vu. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
