INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_03', 'NPC_GAT_18', 'K0', '{"voulg","nouvelles"}', 'Les nouvelles publiques de Voulg (il y était ce matin)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_04', 'NPC_GAT_18', 'K1', '{"raccourcis"}', 'Les raccourcis de messager entre les deux villes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_05', 'NPC_GAT_18', 'K1', '{"visages","memoire"}', 'Qui voyage sur la route ces temps-ci (sa mémoire des visages)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_06', 'NPC_GAT_18', 'K1', '{"endurance","course"}', 'Techniques d''endurance de course longue (RP stamina)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_07', 'NPC_GAT_18', 'K2', '{"doublures","service"}', 'Son service « doublures » : envoyer un message hors registre postal', '`AFF>=65+PAY:100`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_08', 'NPC_GAT_18', 'K2', '{"expediteurs","reguliers"}', 'QUI utilise régulièrement ses doublures (sans le contenu, jamais)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_09', 'NPC_GAT_18', 'K2', '{"patrouilles","horaires"}', 'Les horaires réels des patrouilles de la route (pratique… pour beaucoup de choses)', '`PAY:250`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_10', 'NPC_GAT_18', 'K3', '{"sacoche","scellee"}', 'Ce que pèse la sacoche scellée de cette semaine — et pourquoi on lui a donné une escorte fantôme', NULL, '« La sacoche est scellée. Ma bouche aussi. C''est le même sceau. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_11', 'NPC_GAT_18', 'K3', '{"lettre","jamais livree"}', 'La seule lettre qu''il n''a jamais livrée en douze ans — à qui elle était adressée', NULL, '*(il accélère le pas)* « On bifurque ici. Bonne route. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_18_12', 'NPC_GAT_18', 'KX', '{"*(tout le reste)*"}', '« Je transporte les mots des autres. J''en garde très peu pour moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_19_01', 'NPC_GAT_19', 'K0', '{"menu","prix"}', 'Le menu du jour et les prix (ragoût de cendrelin : 8 Yrds, buff VIT mineur)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_19_02', 'NPC_GAT_19', 'K0', '{"camp","regles"}', 'La règle du camp : pas d''armes sous la tente, pas d''exceptions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_19_03', 'NPC_GAT_19', 'K0', '{"passage","monde"}', 'Qui mange chez elle ces jours-ci (le tout-venant public)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
