INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_19_11', 'NPC_GAT_19', 'K3', '{"poison","refuse"}', 'Qui lui a demandé un jour d''empoisonner une marmite — et combien il offrait', NULL, '« Ma marmite est propre depuis quarante ans. Fin de l''histoire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_19_12', 'NPC_GAT_19', 'KX', '{"*(tout le reste)*"}', '« Ça, mon petit, ça ne se cuisine pas ici. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_20_01', 'NPC_GAT_20', 'K0', '{"armes","prix"}', 'Catalogue T1-T3 (grille D14) et promotions de la semaine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
