INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_20_06', 'NPC_GAT_20', 'K1', '{"grande forge"}', 'Ce que la Grande Forge fait mieux que lui — et ce qu''ELLE fait payer trop cher', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
