INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_20_09', 'NPC_GAT_20', 'K3', '{"piece","kagemune"}', 'Il possède une pièce ratée de Kagemune, achetée aux enchères sous un faux nom — son trésor et sa honte', NULL, '*(il essuie son comptoir)* « Mon coffre, c''est mon coffre. Tu achètes quelque chose ou pas ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_20_10', 'NPC_GAT_20', 'KX', '{"*(tout le reste)*"}', '« Ça se vend pas, donc j''en sais rien ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_21_01', 'NPC_GAT_21', 'K0', '{"fonderie","visite"}', 'Horaires des coulées publiques (spectacle apprécié des visiteurs)', '—', NULL);
