INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_21_04', 'NPC_GAT_21', 'K1', '{"alliages","coulees"}', 'Quels alliages sortent des fonderies cette semaine (influence les stocks de craft)', '—', NULL);
