('QI_GAT_21_05', 'NPC_GAT_21', 'K1', '{"equipes","ouvriers"}', 'Qui travaille aux fonderies et depuis quand', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_21_06', 'NPC_GAT_21', 'K1', '{"rendement","technique"}', 'Optimiser une coulée (lore technique du craft de masse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
