INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_05', 'NPC_GAT_22', 'K1', '{"basalte","qualite"}', 'Reconnaître un bon basalte d''un mauvais (utile pour `MAT` de minerais)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_06', 'NPC_GAT_22', 'K1', '{"coulees","incidents"}', 'Les incidents de coulée récents et leurs causes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_07', 'NPC_GAT_22', 'K2', '{"conversations","forge"}', 'Ce qu''il a « lu » sur les lèvres des visiteurs de la Forge cette semaine', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_08', 'NPC_GAT_22', 'K2', '{"junn","carnet"}', 'Junn `NPC_GAT_25` note quelque chose en cachette pendant les trempes du maître', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_09', 'NPC_GAT_22', 'K3', '{"metal","vol"}', 'Il a lu sur des lèvres le nom du voleur de métal que cherche Berra — et se tait parce que ce nom l''a terrifié', NULL, '*(il se tourne vers la fosse)* « J''entends rien. C''est pratique, parfois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_22_10', 'NPC_GAT_22', 'KX', '{"*(tout le reste)*"}', '« QUOI ? Articule. Non, toujours rien compris. »', '—', NULL);
