INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_02', 'NPC_GAT_23', 'K0', '{"forge","fourniture"}', 'Quelles forges il fournit et à quel rythme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_03', 'NPC_GAT_23', 'K0', '{"cendres","plaines"}', 'Où ramasser du bois carbonisable dans les Plaines de Cendres (`ZONE_SAL_HUNT_001`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_04', 'NPC_GAT_23', 'K1', '{"charbonnage","technique"}', 'L''art de la meule à charbon (lore de métier, débloque la recette craft « Charbon raffiné »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_05', 'NPC_GAT_23', 'K1', '{"yggdrasil","charbon"}', 'Le charbon d''Yggdrasil existe : propriétés (+2 tiers de chaleur de forge), prix prohibitif', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_06', 'NPC_GAT_23', 'K1', '{"clients","exception"}', 'Qui à Gattan a les moyens de commander du « spécial »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_07', 'NPC_GAT_23', 'K2', '{"filiere","branches"}', 'Sa filière : un contact Sylph récupère les branches — « tombées », insiste-t-il', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_08', 'NPC_GAT_23', 'K2', '{"douane","passage"}', 'Comment ses sacs passent la Grande Porte sans contrôle de Marza `NPC_GAT_74`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_09', 'NPC_GAT_23', 'K3', '{"abattage","preuve"}', 'Une souche fraîchement coupée existe quelque part sur les pentes d''Yggdrasil — et sa hache y est enterrée', NULL, '*(il tousse une bouffée de suie)* « Tombées. Toutes. Seules. Un sac de charbon, sinon rien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_23_10', 'NPC_GAT_23', 'KX', '{"*(tout le reste)*"}', '« Ça, mon gars, c''est pas de la compétence de charbonnier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_01', 'NPC_GAT_24', 'K0', '{"gravure","prix"}', 'Tarifs : rune d''affûtage (+3% dégâts, 200 Yrds), rune pare-feu (+5% RES feu, 350 Yrds)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_02', 'NPC_GAT_24', 'K0', '{"runes","effets"}', 'Ce qu''une rune peut et ne peut pas faire (une par arme, non cumulable)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_03', 'NPC_GAT_24', 'K0', '{"atelier","delais"}', 'Délais de gravure : un jour par tier de l''arme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_04', 'NPC_GAT_24', 'K1', '{"style","brokkheim"}', 'Les runes leprechaun sont les meilleures du monde — analyse technique admirative', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_05', 'NPC_GAT_24', 'K1', '{"materiaux","poinçons"}', 'Ses poinçons exigent des éclats de gemme de Granzam (chaînage `MAT` gemmes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_06', 'NPC_GAT_24', 'K1', '{"vulko","controles"}', 'Vulko la contrôle sans relâche — elle raconte leurs joutes avec délectation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_07', 'NPC_GAT_24', 'K2', '{"rune","avancee"}', 'Elle sait graver une rune T4 (+7% dégâts) qu''elle ne met pas en vitrine', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_08', 'NPC_GAT_24', 'K2', '{"apprentissage","copie"}', 'Comment elle a appris : trois hivers à Brokkheim, cachée dans une soupente d''atelier', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_09', 'NPC_GAT_24', 'K3', '{"matrice","survivante"}', 'Une matrice originale volée à Brokkheim existe encore, cousue dans la doublure de son tablier — la seule preuve qui la perdrait', NULL, '*(elle tapote sa pipe)* « Mes matrices finissent au feu. Tout finit au feu, ici. C''est ça, Gattan. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_24_10', 'NPC_GAT_24', 'KX', '{"*(tout le reste)*"}', '« Je grave, je ne bavarde pas. L''un use l''autre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_01', 'NPC_GAT_25', 'K0', '{"apprentissage","forge"}', 'Ce qu''est la vie d''apprenti chez Kagemune (16 heures par jour, zéro compliment)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_02', 'NPC_GAT_25', 'K0', '{"atelier","horaires"}', 'Quand le maître reçoit les commandes — et quand il ne faut SURTOUT pas le déranger', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_03', 'NPC_GAT_25', 'K0', '{"commandes","attente"}', 'La liste d''attente de la Grande Forge (huit mois, sauf exploits)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_04', 'NPC_GAT_25', 'K1', '{"technique","observation"}', 'Détails observés du travail du maître (matériau de lore forge de haut niveau)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_05', 'NPC_GAT_25', 'K1', '{"lame","brisee"}', 'Le maître garde une lame brisée sous son établi et la regarde chaque matin', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_06', 'NPC_GAT_25', 'K1', '{"anciens","apprentis"}', 'Pourquoi les deux apprentis précédents sont partis (l''un pleure encore, dit-on)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_07', 'NPC_GAT_25', 'K2', '{"carnet","existence"}', 'Il note la technique en secret — il l''avoue à demi-mot, terrifié et fier', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_08', 'NPC_GAT_25', 'K2', '{"trempe","secret"}', 'La vraie température de trempe du maître (contenu partiel du carnet)', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_09', 'NPC_GAT_25', 'K3', '{"carnet","cachette"}', 'L''emplacement exact du carnet (sous la troisième dalle, côté soufflet) — sa vie entière tient là-dessous', NULL, '*(il regarde ses mains brûlées)* « Je n''ai rien. Tout est dans ma tête. C''est la règle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_25_10', 'NPC_GAT_25', 'KX', '{"*(tout le reste)*"}', '« Chut — si le maître m''entend parler au lieu de souffler, je dors dehors. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_01', 'NPC_GAT_26', 'K0', '{"soufflets","metier"}', 'Le fonctionnement des grands soufflets (et pourquoi un homme vaut mieux qu''un mécanisme)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_02', 'NPC_GAT_26', 'K0', '{"forge","rythme"}', 'Le rythme des feux : quels jours la Forge tourne à plein', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_03', 'NPC_GAT_26', 'K0', '{"anciennete","memoire"}', 'Vingt ans de Forge : anecdotes publiques (visites célèbres, commandes du Palais)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_04', 'NPC_GAT_26', 'K1', '{"conversations","recentes"}', 'Ce qui s''est dit devant lui récemment — version expurgée', 'troc : 1 info du joueur', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_05', 'NPC_GAT_26', 'K1', '{"officiers","commandes"}', 'Les commandes militaires en cours (volumes, pas les destinations)', 'troc : 1 info du joueur', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_06', 'NPC_GAT_26', 'K1', '{"fitch","tentatives"}', 'Fitch `NPC_GAT_89` a tenté sept fois de l''acheter — il énumère les sept offres avec mépris', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_07', 'NPC_GAT_26', 'K2', '{"commande","palais"}', 'Le Palais de Basalte a commandé quelque chose d''inhabituel le mois dernier (quoi : voir condition)', '`AFF>=80` + troc : 1 K2 du joueur', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_08', 'NPC_GAT_26', 'K2', '{"eugene","visite"}', 'Le Général Eugene `NPC_GAT_09` est venu de nuit, seul, faire réparer Gram — détail que nul ne devrait connaître', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_09', 'NPC_GAT_26', 'K3', '{"conversation","lord"}', 'Il a entendu Lord Mortimer `NPC_GAT_08` prononcer une phrase sur la « prochaine guerre » qui pourrait faire s''écrouler la paix — il l''emportera dans la tombe', NULL, '*(il pompe le soufflet, le feu rugit)* « Le feu mange les mots. C''est son travail. Le mien, c''est le feu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_26_10', 'NPC_GAT_26', 'KX', '{"*(tout le reste)*"}', '« Sais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_01', 'NPC_GAT_27', 'K0', '{"affutage","prix"}', 'Tarifs : affûtage simple 15 Yrds (+1 durabilité max temporaire), polissage complet 60', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_02', 'NPC_GAT_27', 'K0', '{"entretien","conseil"}', 'Entretenir sa lame entre deux chasses (réduit la perte de durabilité de 10%)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_03', 'NPC_GAT_27', 'K0', '{"meule","metier"}', 'Trois générations de meule : histoire familiale publique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_04', 'NPC_GAT_27', 'K1', '{"expertise","lecture"}', 'Ce qu''un fil de lame révèle (forgeron, âge, usage) — démonstration sur l''arme du joueur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_05', 'NPC_GAT_27', 'K1', '{"forgerons","signatures"}', 'Les « signatures » des forgerons de Gattan (Kagemune, Ignis, Ferro) expliquées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_06', 'NPC_GAT_27', 'K1', '{"armes","passage"}', 'Quelles lames notables sont passées sur sa meule ce mois-ci', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_07', 'NPC_GAT_27', 'K2', '{"expertises","gardes"}', 'Les expertises officieuses pour la garde : affaires en cours où une lame a « parlé »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_08', 'NPC_GAT_27', 'K2', '{"lame","etrangere"}', 'Une lame au fil « impossible » est passée récemment — forgée nulle part qu''elle connaisse (hook New Aincrad)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_09', 'NPC_GAT_27', 'K3', '{"expertise","faussee"}', 'Une fois, une seule, elle a menti dans une expertise — pour couvrir quelqu''un qu''elle aime. L''affaire est classée. La lame, elle, est au fond d''un puits de lave', NULL, '*(la meule crisse, longue gerbe d''étincelles)* « Le fil dit tout. Moi, je répète. C''est ma seule règle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_27_10', 'NPC_GAT_27', 'KX', '{"*(tout le reste)*"}', '« Apporte-moi une lame et je te parle. Sinon, la file est derrière. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_01', 'NPC_GAT_28', 'K0', '{"transport","tarifs"}', 'Tarifs de livraison intra-muros (5 Yrds la caisse, double si ça monte)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_02', 'NPC_GAT_28', 'K0', '{"lezard","brindille"}', 'Tout sur Brindille : âge, régime, où la caresser (nulle part)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_03', 'NPC_GAT_28', 'K0', '{"circuits","horaires"}', 'Ses circuits quotidiens — utile pour savoir ce qui bouge à Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_04', 'NPC_GAT_28', 'K1', '{"cargaisons","semaine"}', 'Ce qu''il a livré cette semaine (volumes, expéditeurs — pas le contenu détaillé)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_05', 'NPC_GAT_28', 'K1', '{"lezards","trait"}', 'Le dressage des lézards de trait (lore monture, renvoi vers Stev `NPC_GAT_91`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_06', 'NPC_GAT_28', 'K1', '{"orim","sacs"}', 'Les sacs d''Orim `NPC_GAT_23` pèsent bizarrement pour du charbon — observation innocente en apparence', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_07', 'NPC_GAT_28', 'K2', '{"flair","mithril"}', 'Le flair de Brindille pour le mithril — démonstration si le joueur porte du minerai de mithril (`MAT` Brokkheim)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_08', 'NPC_GAT_28', 'K2', '{"cargaison","arretee"}', 'Brindille s''est arrêtée devant une cargaison « de charbon » le mois dernier — date et expéditeur', '`AFF>=85+QUEST:QST_SAL_FONDERIE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_09', 'NPC_GAT_28', 'K3', '{"trafic","complicite"}', 'Il a déjà accepté trois fois de « ne pas remarquer » un chargement, payé en silence — les noms des payeurs le condamneraient avec eux', NULL, '*(il gratte le cou de Brindille)* « Nous, on porte. On regarde pas dedans. Pas vrai, ma grande ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_28_10', 'NPC_GAT_28', 'KX', '{"*(tout le reste)*"}', '« Ça, c''est pas dans ma charrette. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_01', 'NPC_GAT_29', 'K0', '{"poinçon","verification"}', 'Comment vérifier un poinçon authentique (gratuit — service public)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_02', 'NPC_GAT_29', 'K0', '{"guilde","regles"}', 'Les règles de la guilde des forges : qui peut vendre quoi à Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_03', 'NPC_GAT_29', 'K0', '{"contrefaçon","risques"}', 'Ce que risque un vendeur de contrefaçon (radiation, amende, pilori de cendre)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_04', 'NPC_GAT_29', 'K1', '{"expertise","marques"}', 'Reconnaître une contrefaçon : les cinq défauts classiques (lore d''expertise)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_05', 'NPC_GAT_29', 'K1', '{"affaires","courantes"}', 'Les dossiers de contrefaçon en cours (anonymisés)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_06', 'NPC_GAT_29', 'K1', '{"tessa","dossier"}', 'Le « dossier Tessa » : des mois de contrôles vains — il en parle avec une rage teintée de respect', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_07', 'NPC_GAT_29', 'K2', '{"filiere","voulg"}', 'Une filière de fausses armes poinçonnées remonte vers Voulg (`ZONE_SAL_TWN_001`) — il cherche un enquêteur discret', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_08', 'NPC_GAT_29', 'K2', '{"poincon","vole"}', 'Un poinçon officiel a disparu de son bureau il y a un an — l''affaire a été étouffée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_09', 'NPC_GAT_29', 'K3', '{"rune","scellee"}', 'La rune de Tessa qu''il conserve sous scellé au lieu de l''avoir détruite — preuve de sa propre infraction à l''article qu''il cite le plus', NULL, '*(il ajuste sa loupe)* « Tout ce que je saisis est détruit. Article douze. Au suivant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_29_10', 'NPC_GAT_29', 'KX', '{"*(tout le reste)*"}', '« Hors procédure. Requête rejetée. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_01', 'NPC_GAT_30', 'K0', '{"engagement","conditions"}', 'Conditions d''engagement : solde, grades, avantages (accès à Zela `NPC_GAT_35` à prix militaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_02', 'NPC_GAT_30', 'K0', '{"armee","structure"}', 'L''organisation de l''armée salamander (compagnies, front, réserve)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_03', 'NPC_GAT_30', 'K0', '{"epreuves","entree"}', 'Les trois épreuves d''engagement (voir chaînage quêtes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_04', 'NPC_GAT_30', 'K1', '{"instructeurs","choix"}', 'Quel instructeur (`NPC_GAT_31-34`) pour quel profil — orientation personnalisée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_05', 'NPC_GAT_30', 'K1', '{"quotas","front"}', 'Les besoins réels du front (où l''armée manque de bras — indices sur l''état du monde)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_06', 'NPC_GAT_30', 'K1', '{"recrues","parcours"}', 'Ce que deviennent ses recrues : statistiques honnêtes, y compris les mauvaises', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_07', 'NPC_GAT_30', 'K2', '{"mobilisation","rumeur"}', 'Les quotas ont doublé ce trimestre sans explication officielle — quelque chose se prépare', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_08', 'NPC_GAT_30', 'K2', '{"eugene","ordre"}', 'L''ordre de mobilisation porte le sceau du Lord, pas celui d''Eugene — anomalie qui le ronge', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_09', 'NPC_GAT_30', 'K3', '{"fils","registre"}', 'Son propre fils figure sur le registre des disparus de la Caldeira — il continue de signer des gamins du même âge, et ne se le pardonne pas', NULL, '*(il tamponne un formulaire vide)* « Les registres, c''est Lysa, au camp. Moi, je signe les entrées. Uniquement les entrées. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_30_10', 'NPC_GAT_30', 'KX', '{"*(tout le reste)*"}', '« Pas de ça dans mon bureau. Tu signes ou tu sors. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_01', 'NPC_GAT_31', 'K0', '{"cours","conditions"}', 'Conditions d''enseignement : skill épée 2H, paliers, tarifs par rang', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_02', 'NPC_GAT_31', 'K0', '{"epee2h","bases"}', 'Les fondamentaux de l''épée à deux mains (bonus de lore : lecture des OSS `oss/epee`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_03', 'NPC_GAT_31', 'K0', '{"arene","palmares"}', 'Son triple titre d''arène — version publique, dates et adversaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_04', 'NPC_GAT_31', 'K1', '{"technique","equilibre"}', 'Sa doctrine « main légère » : théorie du contrepoids (débloque un bonus d''XP de skill mineur)', 'élève inscrit', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_05', 'NPC_GAT_31', 'K1', '{"examen","defaite"}', 'Pourquoi il faut avoir perdu pour apprendre ses finales — la pédagogie derrière la règle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_06', 'NPC_GAT_31', 'K1', '{"eleves","anciens"}', 'Ses anciens élèves notables et où ils servent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_07', 'NPC_GAT_31', 'K2', '{"dernier","duel"}', 'Le duel qui a mis fin à sa carrière : le récit complet, sans fard', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_08', 'NPC_GAT_31', 'K2', '{"technique","scellee"}', 'Il existe une huitième finale qu''elle n''enseigne plus — celle du dernier duel', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_09', 'NPC_GAT_31', 'K3', '{"adversaire","identite"}', 'L''adversaire qu''elle a failli tuer vit toujours à Gattan sous un autre nom — et elle paie sa rente en silence depuis dix ans', NULL, '*(elle rengaine avec une lenteur parfaite)* « L''arène est fermée. Certains comptes se règlent hors des registres. En garde, ou dehors. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_31_10', 'NPC_GAT_31', 'KX', '{"*(tout le reste)*"}', '« Ceci est une cour d''armes, pas une taverne. Grum est à la Place du Dragon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_01', 'NPC_GAT_32', 'K0', '{"cours","conditions"}', 'Conditions d''enseignement hache : paliers, tarifs, la règle des billots', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_02', 'NPC_GAT_32', 'K0', '{"hache","bases"}', 'Les fondamentaux : angle, hanche, suivi du geste (renvoi OSS famille hache)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_03', 'NPC_GAT_32', 'K0', '{"plaines","bosquets"}', 'Les bosquets pétrifiés des Plaines de Cendres (`ZONE_SAL_HUNT_001`) : où, quoi, dangers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_04', 'NPC_GAT_32', 'K1', '{"technique","entaille"}', 'Sa botte personnelle « l''Entaille du Bûcheron » (bonus dégâts vs mobs à carapace)', 'élève inscrit', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_05', 'NPC_GAT_32', 'K1', '{"guerre","enrolement"}', 'Son enrôlement forcé et la bataille des Plaines — version de vétéran, sans gloire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_06', 'NPC_GAT_32', 'K1', '{"bois","petrifie"}', 'Le bois pétrifié comme matériau (manches de T3+, chaînage `MAT`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_07', 'NPC_GAT_32', 'K2', '{"eleve","disparu"}', 'Son meilleur élève est parti « chasser l''alpha » avec Sarka `NPC_GAT_11` et n''est jamais revenu', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_08', 'NPC_GAT_32', 'K2', '{"technique","interdite"}', 'Il connaît une frappe de décapitation enseignée à l''armée puis interdite — et refuse de dire pourquoi elle l''a été', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_09', 'NPC_GAT_32', 'K3', '{"bataille","fuite"}', 'À la bataille des Plaines, il a fui son poste pendant une heure — l''heure exacte où son unité a été enveloppée. Sa médaille de survivant est un mensonge', NULL, '*(il enfonce sa hache dans le billot d''un coup sec)* « Le tronc, là. Frappe le tronc. Le passé, lui, il rend pas les coups. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_32_10', 'NPC_GAT_32', 'KX', '{"*(tout le reste)*"}', '« Ça se tranche pas, donc ça m''intéresse pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_01', 'NPC_GAT_33', 'K0', '{"cours","conditions"}', 'Conditions d''enseignement lance : paliers, tarifs, règle du trio obligatoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_02', 'NPC_GAT_33', 'K0', '{"lance","bases"}', 'Fondamentaux : distance, pointe, retrait (renvoi OSS famille lance)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_03', 'NPC_GAT_33', 'K0', '{"granzam","echange"}', 'Son séjour de quatre ans à Granzam — version publique, anecdotes de garnison', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_04', 'NPC_GAT_33', 'K1', '{"phalange","doctrine"}', 'La phalange gnome adaptée : théorie des appuis croisés (buff de groupe en formation)', 'élève inscrit', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_05', 'NPC_GAT_33', 'K1', '{"groupe","tactique"}', 'Tactiques de chasse en trio pour les zones `HUNT` (conseils appliqués aux mobs `MOB_SAL_*`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_06', 'NPC_GAT_33', 'K1', '{"gnomes","relations"}', 'Ce que les Gnomes pensent vraiment des Salamanders (lucide, utile en diplomatie)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_07', 'NPC_GAT_33', 'K2', '{"programme","echange"}', 'Le programme d''échange militaire existe encore sur le papier — qui pourrait le réactiver, et pourquoi personne ne le fait', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_08', 'NPC_GAT_33', 'K2', '{"manoeuvre","granzam"}', 'Une manœuvre de phalange que même Granzam n''enseigne plus — elle est la dernière à la connaître', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_09', 'NPC_GAT_33', 'K3', '{"rapport","enterre"}', 'En garnison, elle a rédigé un rapport sur les défenses de Granzam ; l''état-major le conserve. Si une guerre éclate, ce document fera d''elle la traîtresse de ses anciens frères d''armes', NULL, '*(elle aligne trois lances au mur, parfaitement parallèles)* « Ce que j''ai écrit là-bas appartient à l''état-major. Ce que j''enseigne ici t''appartient. Choisis ta question. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_33_10', 'NPC_GAT_33', 'KX', '{"*(tout le reste)*"}', '« Hors formation. Reforme le trio et on reparle. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_01', 'NPC_GAT_34', 'K0', '{"cours","conditions"}', 'Conditions d''enseignement bouclier : paliers, tarifs (renvoi armures `boucliers_armure`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_02', 'NPC_GAT_34', 'K0', '{"bouclier","bases"}', 'Fondamentaux : angle de garde, absorption, économie de mouvement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_03', 'NPC_GAT_34', 'K0', '{"duels","statistique"}', 'Les 147 duels sans victoire ni défaite — il confirme, imperturbable', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_04', 'NPC_GAT_34', 'K1', '{"technique","rempart"}', 'Sa doctrine « le Rempart Patient » : gagner en ne perdant pas (débloque la posture défensive rang 2)', 'élève inscrit', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_05', 'NPC_GAT_34', 'K1', '{"boss","defense"}', 'Comment survivre aux patterns des boss de zone (`MOB_SAL_026`, `BOSS_SAL_DUN_001`) — analyse défensive', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_06', 'NPC_GAT_34', 'K1', '{"duels","celebres"}', 'Ses duels les plus célèbres, racontés du point de vue du bouclier', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_07', 'NPC_GAT_34', 'K2', '{"attaque","unique"}', 'Il possède UNE technique offensive, apprise pour un jour précis qui n''est jamais venu', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_08', 'NPC_GAT_34', 'K2', '{"serment","origine"}', 'Pourquoi il n''attaque jamais : un serment, une personne, une date — il donne les trois', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_09', 'NPC_GAT_34', 'K3', '{"serment","beneficiaire"}', 'La personne du serment est encore vivante, haut placée à Gattan, et croit Gott mort depuis vingt ans — il entretient ce mensonge pour la protéger', NULL, '*(il lève son bouclier entre vous deux, doucement)* « Il y a des questions que ceci arrête aussi. C''est un bon bouclier. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_34_10', 'NPC_GAT_34', 'KX', '{"*(tout le reste)*"}', '« Ma spécialité, c''est ce qui s''arrête. Ta question, elle, passe au travers. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_01', 'NPC_GAT_35', 'K0', '{"surplus","prix"}', 'Catalogue du jour : armures T1-T2 à -30% de la grille D15, rations, consommables de campagne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_02', 'NPC_GAT_35', 'K0', '{"caisse","blesses"}', 'La caisse des blessés : où va chaque Yrd de marge (comptes affichés au mur)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_03', 'NPC_GAT_35', 'K0', '{"tarif","militaire"}', 'Le tarif militaire : -15% supplémentaires pour le rang « Recrue » et au-delà', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_04', 'NPC_GAT_35', 'K1', '{"arrivages","calendrier"}', 'Le calendrier des déclassements (quand arrivent les bons lots — info d''achat maligne)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_05', 'NPC_GAT_35', 'K1', '{"qualite","tri"}', 'Reconnaître une bonne pièce de surplus d''une passoire (expertise d''achat)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_06', 'NPC_GAT_35', 'K1', '{"armee","consommation"}', 'Ce que l''armée consomme réellement (volumes — indice sur l''activité militaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_07', 'NPC_GAT_35', 'K2', '{"lot","detourne"}', 'Un lot entier a été « déclassé » avant d''avoir servi — quelqu''un au-dessus d''elle a signé, et ça ne lui plaît pas', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_08', 'NPC_GAT_35', 'K2', '{"reserve","guerre"}', 'L''intendance constitue des réserves de guerre depuis deux mois — elle montre les bons de commande', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_09', 'NPC_GAT_35', 'K3', '{"caisse","ponction"}', 'Une fois, la caisse des blessés a servi à payer autre chose — un ordre du Palais qu''elle a exécuté puis remboursé de sa poche. L''ordre écrit est cousu dans sa doublure : son assurance-vie', NULL, '*(elle fait claquer son registre)* « Les comptes sont au mur. Chaque Yrd. Compte toi-même ou achète quelque chose. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_35_10', 'NPC_GAT_35', 'KX', '{"*(tout le reste)*"}', '« Pas en stock. Suivant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_01', 'NPC_GAT_36', 'K0', '{"soins","tarifs"}', 'Soins standard : dissipation des débuffs `DOT`/poison, tarifs Quartier Militaire (gratuit aux Scories)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_02', 'NPC_GAT_36', 'K0', '{"dispensaire","regles"}', 'Les trois règles du dispensaire du soir (pas de noms, pas de questions, pas de gardes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_03', 'NPC_GAT_36', 'K0', '{"premiers","secours"}', 'Premiers secours de terrain (guide pratique — réduit la durée des DoT de 20% si appliqué)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_04', 'NPC_GAT_36', 'K1', '{"blessures","guerre"}', 'Ce que les blessures racontent de la guerre en cours (lecture clinique du front)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_05', 'NPC_GAT_36', 'K1', '{"surchauffe","sequelles"}', 'Les séquelles de la Surchauffe de la Caldeira (D11) : symptômes, traitement — expertise unique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_06', 'NPC_GAT_36', 'K1', '{"gratta","methodes"}', 'Ce qu''il pense des méthodes de Gratta `NPC_GAT_61` (« De la sorcellerie. Efficace. Ça m''agace. »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_07', 'NPC_GAT_36', 'K2', '{"patients","scories"}', 'Qui il soigne vraiment le soir — dont des visages que l''état-major croit ailleurs', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_08', 'NPC_GAT_36', 'K2', '{"cendreux","dossier"}', 'Le dossier médical du Vieux Cendreux `NPC_GAT_82` : des cicatrices d''officier supérieur, pas de mendiant', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_09', 'NPC_GAT_36', 'K3', '{"patient","cache"}', 'Il cache et soigne aux Scories un déserteur condamné à mort — le fils d''un homme du Palais. Si ça se sait, le dispensaire ferme et deux personnes meurent', NULL, '*(il désinfecte des instruments, dos tourné)* « Secret médical. C''est le seul mur de cette ville qui n''a pas de fissure. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_36_10', 'NPC_GAT_36', 'KX', '{"*(tout le reste)*"}', '« Symptômes, ou sortie. J''ai des points de suture qui m''attendent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_01', 'NPC_GAT_37', 'K0', '{"cartes","vente"}', 'Cartes publiques : Plaines de Cendres 50 Yrds, Désolation (édition de saison) 200 Yrds', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_02', 'NPC_GAT_37', 'K0', '{"desolation","mouvement"}', 'Pourquoi la Désolation change : coulées, geysers, effondrements (lore géographique)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_03', 'NPC_GAT_37', 'K0', '{"orientation","bases"}', 'S''orienter en zone volcanique (les repères qui ne mentent pas)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_04', 'NPC_GAT_37', 'K1', '{"releves","saison"}', 'Les changements de la saison en cours (zones effondrées, nouveaux passages — mise à jour des dangers)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_05', 'NPC_GAT_37', 'K1', '{"zones","spawn"}', 'Où les mobs se concentrent selon la topographie (lecture cartographique de `T_SPAWN_TABLES`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_06', 'NPC_GAT_37', 'K1', '{"kolm","carte"}', 'La carte des filons de Kolm `NPC_GAT_12` contient au moins trois erreurs — volontaires, selon lui', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_07', 'NPC_GAT_37', 'K2', '{"passage","sud"}', 'Un passage sûr traverse la Désolation par le sud, hors des routes officielles — tracé exact', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_08', 'NPC_GAT_37', 'K2', '{"caldeira","exterieur"}', 'Le relevé extérieur complet de la Caldeira d''Obsidienne (`ZONE_SAL_DUN_001`) : trois accès, dont un que l''armée ignore', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_09', 'NPC_GAT_37', 'K3', '{"carte","interdite"}', 'Sa carte maîtresse annotée localise une anomalie sous la Caldeira — une structure régulière, artificielle, antérieure à tout. Il ne l''a signalée à personne : l''état-major en ferait une arme', NULL, '*(il roule une carte d''un geste sec)* « Ce coffre est cadastré secret militaire. Même ma curiosité n''y entre plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_37_10', 'NPC_GAT_37', 'KX', '{"*(tout le reste)*"}', '« Hors de ma carte. Littéralement. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_01', 'NPC_GAT_38', 'K0', '{"prison","regles"}', 'Règlement officiel : pas de visites, pas de colis, peines affichées à la Porte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_02', 'NPC_GAT_38', 'K0', '{"detention","motifs"}', 'Ce qui mène à la prison de basalte (contrefaçon, contrebande, désertion)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_03', 'NPC_GAT_38', 'K0', '{"prison","histoire"}', 'La prison n''a jamais connu d''évasion en deux cents ans — visite guidée verbale', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_04', 'NPC_GAT_38', 'K1', '{"barema","services"}', 'Son « barème » officieux (messages, parloir, colis) — présenté comme une rumeur qu''il ne dément pas', '`AFF>=50`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_05', 'NPC_GAT_38', 'K1', '{"detenus","registre"}', 'Qui est détenu en ce moment (noms publics, motifs)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_06', 'NPC_GAT_38', 'K1', '{"prisonniers","histoires"}', 'Les histoires des cellules : vingt ans d''anecdotes carcérales', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_07', 'NPC_GAT_38', 'K2', '{"detenu","anonyme"}', 'La cellule du fond héberge un détenu sans nom, sans registre, nourri sur ordre direct du Palais', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_08', 'NPC_GAT_38', 'K2', '{"evasion","presque"}', 'Il y a eu UNE presque-évasion, étouffée — par les égouts. Depuis, il paie Ashna `NPC_GAT_88` pour se taire', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_09', 'NPC_GAT_38', 'K3', '{"detenu","identite"}', 'Il a reconnu le détenu sans nom : un visage que tout Gattan croit mort et honoré d''une statue. Le dire ferait tomber le Palais — ou Dreck dans une cellule voisine', NULL, '*(il fait tinter son trousseau)* « La cellule du fond ? Y a pas de cellule du fond. Compte les portes, tu verras. On compte mal, ici. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_38_10', 'NPC_GAT_38', 'KX', '{"*(tout le reste)*"}', '« Ça, c''est au-dessus du sol. Pas ma juridiction. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_01', 'NPC_GAT_39', 'K0', '{"recit","raid"}', 'LE récit du premier raid (version canon, 10 minutes, gratuite et magnifique)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_02', 'NPC_GAT_39', 'K0', '{"caldeira","dangers"}', 'Les dangers de la Caldeira pour les prétendants au donjon (conseils sincères et utiles)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_03', 'NPC_GAT_39', 'K0', '{"veterans","vie"}', 'La vie de vétéran pensionné à Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_04', 'NPC_GAT_39', 'K1', '{"logi","apparence"}', 'Description de Logi (`BOSS_SAL_DUN_001`) en combat — détails que seule l''expérience donne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_05', 'NPC_GAT_39', 'K1', '{"surchauffe","vecu"}', 'La Surchauffe (D11) vécue de l''intérieur : ce que les jauges ne disent pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_06', 'NPC_GAT_39', 'K1', '{"raid","composition"}', 'Qui composait le premier raid — noms, visages, familles (matériau généalogique de quêtes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_07', 'NPC_GAT_39', 'K2', '{"recit","failles"}', 'Les incohérences de son propre récit — il les reconnaît une à une, ébranlé', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_08', 'NPC_GAT_39', 'K2', '{"sergent","verite"}', 'Le sergent « porté héroïquement » : il donne le vrai nom, et le nom ne colle pas avec la version', '`AFF>=90+QUEST:QST_SAL_MANCHOT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_09', 'NPC_GAT_39', 'K3', '{"bras","verite"}', 'Son bras n''a pas été pris par Logi : c''est le sergent, devenu fou de peur, qui a frappé — et Ulric l''a laissé derrière, vivant. Le récit héroïque est un tombeau de mots bâti sur un abandon', NULL, '*(son moignon tressaille, il rit trop fort)* « Le bras ? Logi l''a gardé en souvenir ! C''est qu''il apprécie les autographes, le bougre ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_39_10', 'NPC_GAT_39', 'KX', '{"*(tout le reste)*"}', '« Ah, ça, c''est pas dans mon histoire. Et j''en ai qu''une, mais elle est bonne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_01', 'NPC_GAT_40', 'K0', '{"cantine","horaires"}', 'Horaires de la cantine ; le ragoût est servi à midi pile, pas une braise plus tard', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_02', 'NPC_GAT_40', 'K0', '{"ragout","effet"}', 'Le ragoût buffe la VIT (+5% END pendant 2h) — c''est connu, c''est constaté, c''est inexpliqué', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_03', 'NPC_GAT_40', 'K0', '{"caserne","moral"}', 'Le moral de la troupe, lu dans les gamelles (qui finit son assiette, qui la laisse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_04', 'NPC_GAT_40', 'K1', '{"cuisine","campagne"}', 'Cuisiner en campagne : lore pratique (débloque la recette « Ration de marche », craft nourriture T1)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_05', 'NPC_GAT_40', 'K1', '{"fournisseurs","circuits"}', 'Ses circuits d''approvisionnement (Kargh, Rosza — volumes de la caserne)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_06', 'NPC_GAT_40', 'K1', '{"soldats","noms"}', 'Il connaît le nom de chaque soldat de la caserne — et leurs histoires de cantine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_07', 'NPC_GAT_40', 'K2', '{"recette","secret"}', '« La recette » : il avoue en riant qu''il n''y en a pas — et explique le rituel des noms', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_08', 'NPC_GAT_40', 'K2', '{"rations","doublees"}', 'On lui a commandé de doubler les rations de réserve — même signal que Zela `NPC_GAT_35` et Kruger `NPC_GAT_30`', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_09', 'NPC_GAT_40', 'K3', '{"fils","ennemi"}', 'Son fils a épousé une Sylph et vit à Swilvane sous un nom d''emprunt — si la guerre reprend, le fils du cuisinier de caserne sera « l''ennemi ». Borga cuisine pour une armée qui marcherait contre son sang', NULL, '*(il remue lentement, trois tours)* « Ma famille ? Elle est là, la famille. Six cents gamelles par jour. Ça suffit à un homme. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_40_10', 'NPC_GAT_40', 'KX', '{"*(tout le reste)*"}', '« Ça, c''est pas de la cuisine. Tends ta gamelle ou pousse-toi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_01', 'NPC_GAT_41', 'K0', '{"course","record"}', 'Son record Porte-Palais (4:11) et le parcours officiel de la course annuelle des messagers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_02', 'NPC_GAT_41', 'K0', '{"ville","raccourcis"}', 'Trois raccourcis publics de Gattan (gain de temps réel sur les déplacements intra-ville)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_03', 'NPC_GAT_41', 'K0', '{"survol","interdictions"}', 'Pourquoi on ne survole pas le Palais ni la Forge (zones d''exclusion aérienne de la ville)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_04', 'NPC_GAT_41', 'K1', '{"passages","toits"}', 'Le réseau des toits : itinéraires praticables (débloque des trajets rapides en ville)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_05', 'NPC_GAT_41', 'K1', '{"plis","circulation"}', 'Le volume de plis d''état-major a triplé ce mois-ci (encore le fil « mobilisation »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_06', 'NPC_GAT_41', 'K1', '{"messagers","guilde"}', 'La petite guilde informelle des coureurs de Gattan : qui court pour qui', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_07', 'NPC_GAT_41', 'K2', '{"pli","perdu"}', 'Elle a perdu UN pli en sept ans — jamais retrouvé, jamais avoué, remplacé par un faux réécrit de mémoire', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_08', 'NPC_GAT_41', 'K2', '{"trajets","eugene"}', 'Les destinations inhabituelles des plis d''Eugene ces dernières semaines (dont deux vers la Voie des Scories)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_09', 'NPC_GAT_41', 'K3', '{"pli","contenu"}', 'Le pli perdu, elle l''avait lu avant de le perdre : un ordre concernant le « détenu sans nom » de la prison. Son faux de mémoire circule peut-être encore dans les archives — avec une erreur', NULL, '*(elle resserre ses sangles, déjà tournée vers la rue)* « Je porte, je lis pas. C''est le premier serment. Temps écoulé ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_41_10', 'NPC_GAT_41', 'KX', '{"*(tout le reste)*"}', '« Pas le temps ! Vraiment ! Demande à quelqu''un d''assis ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_01', 'NPC_GAT_42', 'K0', '{"taverne","carte"}', 'La carte : chopes, plats, chambre commune (5 Yrds la nuit, point de repos `!rest`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_02', 'NPC_GAT_42', 'K0', '{"biere","haleine"}', 'La « Haleine de Logi » de Helka : la bière la plus forte du territoire (buff/debuff, voir Helka)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_03', 'NPC_GAT_42', 'K0', '{"place","actualites"}', 'Les nouvelles publiques de la Place du Dragon (K0 de milieu de ville, réseau de Petra)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_04', 'NPC_GAT_42', 'K1', '{"habitues","plan"}', 'Qui boit où : la cartographie sociale de sa salle (qui éviter, qui aborder)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_05', 'NPC_GAT_42', 'K1', '{"fitch","banni"}', 'Pourquoi Fitch `NPC_GAT_89` est banni à vie (il a vendu la confidence d''un client — crime absolu)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_06', 'NPC_GAT_42', 'K1', '{"taverne","coulisses"}', 'Trente ans de comptoir : anecdotes sans noms (le métier de tavernier comme confessionnal)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_07', 'NPC_GAT_42', 'K2', '{"salle","arriere"}', 'L''arrière-salle existe : qui peut la réserver et pour quel genre de réunions', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_08', 'NPC_GAT_42', 'K2', '{"reunion","recente"}', 'Une réunion récente en arrière-salle a réuni des gens qui ne devraient jamais se parler — il donne les silhouettes, pas les noms', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_09', 'NPC_GAT_42', 'K3', '{"aveu","meurtre"}', 'Un soir, un client lui a avoué un meurtre non élucidé — le client vit toujours, honorable et connu. Répéter tuerait la taverne ; se taire le ronge chaque fois que l''homme commande sa chope', NULL, '*(il essuie une chope, longuement)* « Le comptoir absorbe. C''est du bon bois pour ça. Une autre ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_42_10', 'NPC_GAT_42', 'KX', '{"*(tout le reste)*"}', '« Ici on sert, on n''informe pas. La crieuse est dehors. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_01', 'NPC_GAT_43', 'K0', '{"service","taverne"}', 'La carte, les horaires, les manies des habitués (service souriant standard)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_02', 'NPC_GAT_43', 'K0', '{"joueurs","histoires"}', 'Les histoires de joueurs qu''elle a retenues (écho concret de l''activité du serveur)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_03', 'NPC_GAT_43', 'K0', '{"gattan","quotidien"}', 'Le quotidien d''une fille de la Place du Dragon', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_04', 'NPC_GAT_43', 'K1', '{"questions","monde"}', 'Ses questions sur « l''extérieur » — posées AU joueur (inversion du dialogue, unique)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_05', 'NPC_GAT_43', 'K1', '{"reves","pnj"}', 'Elle affirme rêver — et décrit ses rêves (les PNJ ne rêvent pas ; matériau troublant)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_06', 'NPC_GAT_43', 'K1', '{"timo","conversation"}', 'Sa conversation avec Timo `NPC_GAT_66` : « lui aussi sent que quelque chose regarde »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_07', 'NPC_GAT_43', 'K2', '{"souvenirs","impossibles"}', 'Elle se souvient d''un client que personne d''autre ne se rappelle — description précise d''un joueur banni avant sa « naissance » de PNJ', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_08', 'NPC_GAT_43', 'K2', '{"devenir","joueuse"}', 'Son projet fou : elle veut « faire ce que vous faites » — partir en zone de chasse. Elle a économisé pour une dague', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_09', 'NPC_GAT_43', 'K3', '{"conscience","gouffre"}', 'Sa terreur nocturne : elle a « senti » une fois le monde s''arrêter puis reprendre (une maintenance serveur) — et elle sait que si elle en parle trop fort, « la chose qui regarde » pourrait la corriger', NULL, '*(elle sourit trop vite, ramasse des chopes)* « Oublie. Les filles de taverne racontent n''importe quoi, c''est le métier. Tu reprends quelque chose ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_43_10', 'NPC_GAT_43', 'KX', '{"*(tout le reste)*"}', '« Ça, demande à Grum — moi je porte des chopes, officiellement. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_01', 'NPC_GAT_44', 'K0', '{"achat","viandes"}', 'Grille d''achat des drops : viande de lézard 8 Yrds, quartier de wyrm 35, carcasse T3 sur estimation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_02', 'NPC_GAT_44', 'K0', '{"viande","vente"}', 'Vente au détail : morceaux à cuisiner (composants du métier cuisine)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_03', 'NPC_GAT_44', 'K0', '{"chasse","conseils"}', 'Quels mobs donnent la meilleure viande au poids (guide de farm honnête `MOB_SAL_010-013`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_04', 'NPC_GAT_44', 'K1', '{"decoupe","metier"}', 'L''art de la découpe (débloque +10% de rendement viande sur les loots du joueur — passif d''étal)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_05', 'NPC_GAT_44', 'K1', '{"cours","saisons"}', 'Les cours de la viande selon les saisons de spawn (économie dynamique lisible)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_06', 'NPC_GAT_44', 'K1', '{"desolation","carcasses"}', 'Les carcasses de la Désolation : lesquelles se mangent, lesquelles tuent (expertise rare)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_07', 'NPC_GAT_44', 'K2', '{"commande","etrange"}', 'Quelqu''un lui achète chaque semaine de la viande crue en quantité — livrée de nuit, adresse aux Scories', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_08', 'NPC_GAT_44', 'K2', '{"couperet","dette"}', 'Son couperet signé Kagemune : il ne l''a pas payé — c''est le prix d''un silence rendu au forgeron, il y a longtemps', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_09', 'NPC_GAT_44', 'K3', '{"viande","origine"}', 'Pendant le Grand Hiver d''il y a neuf ans, la « viande de wyrm » qui a sauvé le quartier n''était pas du wyrm — et les seuls à savoir ce que c''était sont lui et le fossoyeur Morn `NPC_GAT_69`, qui ne se parlent plus depuis', NULL, '*(le couperet s''abat, net)* « Le Grand Hiver, on l''a passé. C''est tout ce qu''il y a à découper là-dedans. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_44_10', 'NPC_GAT_44', 'KX', '{"*(tout le reste)*"}', '« Ça se pèse pas, ça se vend pas, ça m''occupe pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_01', 'NPC_GAT_45', 'K0', '{"epices","prix"}', 'Catalogue : épices de cendre 5 Yrds, sel Undine 15, poivre d''Alne « premium » 40', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_02', 'NPC_GAT_45', 'K0', '{"cuisine","composants"}', 'Quelles épices pour quelles recettes (composants du métier cuisine, renvoi Borga/Danna)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_03', 'NPC_GAT_45', 'K0', '{"importations","routes"}', 'D''où vient chaque produit : la géographie commerciale des neuf territoires en bocaux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_04', 'NPC_GAT_45', 'K1', '{"recolte","cendres"}', 'Où récolter les épices de cendre aux Plaines (`ZONE_SAL_HUNT_001`, nœuds de récolte)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_05', 'NPC_GAT_45', 'K1', '{"caravanes","arrivees"}', 'Le calendrier des caravanes et convois aériens (quand les étagères se remplissent)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_06', 'NPC_GAT_45', 'K1', '{"penuries","rumeurs"}', 'Ce qui va manquer bientôt (lecture des flux — spéculation légale pour joueurs attentifs)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_07', 'NPC_GAT_45', 'K2', '{"poivre","coupe"}', 'Le « premium » coupé au tiers — elle l''avoue avec un aplomb désarmant (« Le goût y est. Le voyage aussi. Enfin, un tiers du voyage. »)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_08', 'NPC_GAT_45', 'K2', '{"client","palais"}', 'Le Palais lui achète une épice précise en quantité anormale — une épice qui, à haute dose, est un somnifère', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_09', 'NPC_GAT_45', 'K3', '{"lettre","cachee"}', 'Dans un bocal scellé du fond, une lettre attend depuis six ans — confiée par un voyageur qui n''est jamais revenu la chercher, adressée à un nom que Rosza a fini par reconnaître : celui gravé sur une statue de la ville', NULL, '*(elle réaligne ses bocaux)* « Le fond de boutique, c''est les invendus. Rien que les invendus. Tu prends quelque chose ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_45_10', 'NPC_GAT_45', 'KX', '{"*(tout le reste)*"}', '« Ça, mon lapin, c''est pas en rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_01', 'NPC_GAT_46', 'K0', '{"tissus","prix"}', 'Catalogue : toile brute, toile de salamandre (composant `MAT`), pièces T1-T2 (robes/capes légères)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_02', 'NPC_GAT_46', 'K0', '{"ignifuge","propriete"}', 'Ce que « ignifugé » veut dire en jeu : -15% dégâts de feu subis sur les pièces tissu T2', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_03', 'NPC_GAT_46', 'K0', '{"tissu_vs_acier"}', 'Son argumentaire tissu contre acier (guide honnête : à qui le tissu convient)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_04', 'NPC_GAT_46', 'K1', '{"tissage","technique"}', 'La trempe à la cendre fine : procédé complet (débloque la recette craft « Toile de salamandre »)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_05', 'NPC_GAT_46', 'K1', '{"fibres","recolte"}', 'Où récolter la fibre végétale aux Plaines (`ZONE_SAL_HUNT_001`, nœuds de récolte flore)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_06', 'NPC_GAT_46', 'K1', '{"clients","profils"}', 'Qui s''équipe en tissu à Gattan (mages, éclaireurs — lecture des métas d''équipement)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_07', 'NPC_GAT_46', 'K2', '{"commande","pyra"}', 'Les « coussins de familiers » de Pyra `NPC_GAT_04` : les dimensions correspondent à une créature bien plus grande que ce que Pyra vend', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_08', 'NPC_GAT_46', 'K2', '{"toile","superieure"}', 'Elle a tissé UNE pièce en soie d''araignée de la Désolation (drop `MOB_SAL_02x` rarissime) — résultat T4, jamais vendu', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_09', 'NPC_GAT_46', 'K3', '{"motif","code"}', 'Ses tissus portent un motif de lisière unique par client — un registre tissé. Elle peut identifier n''importe quelle pièce retrouvée sur n''importe quel corps, et la garde de Volcanus l''ignore. Elle a déjà reconnu une de ses capes dans une affaire jamais élucidée — et s''est tue', NULL, '*(ses doigts suivent une lisière)* « Les motifs ? De la coquetterie d''atelier. Chaque tisserande a les siens. Ça ne raconte rien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_46_10', 'NPC_GAT_46', 'KX', '{"*(tout le reste)*"}', '« Ça ne se tisse pas, ça ne me regarde pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_01', 'NPC_GAT_47', 'K0', '{"verrerie","prix"}', 'Catalogue : fiole standard 3 Yrds, fiole renforcée 10, gobeleterie, « larmes de dragon »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_02', 'NPC_GAT_47', 'K0', '{"sable","noir"}', 'Le sable noir des Plaines : où le récolter, pourquoi il chante sous le vent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_03', 'NPC_GAT_47', 'K0', '{"fioles","usage"}', 'Quelle fiole pour quelle préparation (guide alchimie, renvoi Mortis/Nyssa)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_04', 'NPC_GAT_47', 'K1', '{"soufflage","technique"}', 'Le soufflage au sable noir (débloque la recette craft « Fiole fumée », composant potions T2+)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_05', 'NPC_GAT_47', 'K1', '{"forge","depart"}', 'Pourquoi il a quitté la Grande Forge — la version qu''il consent à donner', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_06', 'NPC_GAT_47', 'K1', '{"commandes","alne"}', 'Ses exportations vers Alne : quels ateliers d''alchimie lui achètent (réseau inter-villes)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_07', 'NPC_GAT_47', 'K2', '{"ampoules","guerre"}', 'Les « ampoules de guerre » qu''on lui a demandé de souffler : des contenants pour gaz de combat — il a refusé et gardé le plan', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_08', 'NPC_GAT_47', 'K2', '{"verre","anomalie"}', 'Un lot de sable récent a donné un verre qui luit faiblement la nuit — il soupçonne une contamination venue de la Caldeira', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_09', 'NPC_GAT_47', 'K3', '{"plan","cache"}', 'Le plan des ampoules de guerre existe toujours, roulé dans une canne de souffleur pendue à son mur — le détruire serait avouer l''avoir gardé, le rendre serait armer ce qu''il a fui', NULL, '*(il souffle une bulle parfaite, la regarde)* « Ce que la Forge m''a demandé appartient à la Forge. Ce que j''ai refusé m''appartient. On regarde mes verres, plutôt ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_47_10', 'NPC_GAT_47', 'KX', '{"*(tout le reste)*"}', '« Ça… n''est pas du verre. Donc je ne sais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_01', 'NPC_GAT_48', 'K0', '{"bijoux","prix"}', 'Catalogue : anneaux T1-T3, colliers, sertissage à façon (grille accessoires D15)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_02', 'NPC_GAT_48', 'K0', '{"obsidienne","taille"}', 'L''obsidienne de Gattan : pourquoi elle se taille et se brise (lore matériau)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_03', 'NPC_GAT_48', 'K0', '{"gemmes","granzam"}', 'Les gemmes de Granzam : grades, prix, pourquoi rien ne les remplace (D15 assumé)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_04', 'NPC_GAT_48', 'K1', '{"expertise","pierres"}', 'Expertise gratuite d''une gemme du joueur (valeur, origine, authenticité)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_05', 'NPC_GAT_48', 'K1', '{"sertissage","bonus"}', 'Le sertissage à façon : ajouter un slot de gemme à un accessoire (service T3+)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_06', 'NPC_GAT_48', 'K1', '{"mode","officiers"}', 'Qui porte quoi à Gattan : la hiérarchie lue aux doigts et aux cous', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_07', 'NPC_GAT_48', 'K2', '{"tiroir","discret"}', 'Le tiroir des commandes discrètes : ce qu''on lui demande d''effacer, sans noms', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_08', 'NPC_GAT_48', 'K2', '{"piece","snyk"}', 'La pièce que Snyk `NPC_GAT_80` a tenté de vendre : elle l''a reconnue — un bijou de la famille du Lord', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_09', 'NPC_GAT_48', 'K3', '{"chevaliere","refondue"}', 'Il y a trois ans, elle a refondu une chevalière aux armes d''une lignée « éteinte » — apportée par quelqu''un de très vivant. La cire de l''empreinte dort dans son coffre : preuve qu''une maison morte marche encore dans Gattan', NULL, '*(elle referme un écrin, clic net)* « Ce qui entre dans le creuset n''a jamais existé. Politique de la maison. Un sertissage, peut-être ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_48_10', 'NPC_GAT_48', 'KX', '{"*(tout le reste)*"}', '« Cela ne brille pas, cela ne me concerne pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_01', 'NPC_GAT_49', 'K0', '{"change","taux"}', 'Ses services : casse de coupures (commission 2%), avance de caisse aux patentés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_02', 'NPC_GAT_49', 'K0', '{"monnaie","yrds"}', 'Tout sur le Yrd : frappes, coupures, fausses pièces courantes (guide anti-arnaque)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_03', 'NPC_GAT_49', 'K0', '{"place","flux"}', 'Qui brasse combien sur la Place (ordres de grandeur publics — lecture de l''économie locale)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_04', 'NPC_GAT_49', 'K1', '{"detection","fausses"}', 'Détecter une fausse pièce : ses trois tests (son, mordant, tranche — ironie incluse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_05', 'NPC_GAT_49', 'K1', '{"liquidites","mouvements"}', 'Les mouvements d''argent inhabituels de la semaine (qui casse des grosses coupures)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_06', 'NPC_GAT_49', 'K1', '{"ora","rivalite"}', 'Sa version de la guerre froide avec la banquière (« Les banques… ça compte. Moi, je pèse. Nuance. »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_07', 'NPC_GAT_49', 'K2', '{"client","lessiveur"}', 'Quelqu''un « lessive » des Yrds sales en menue monnaie via son comptoir — il a identifié le circuit et se fait payer pour ne pas le voir', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_08', 'NPC_GAT_49', 'K2', '{"lime","aveu"}', 'La lime. Il l''avoue à demi-mot, par vanité d''artiste — « l''usure, mon ami, je la précède, c''est tout »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_09', 'NPC_GAT_49', 'K3', '{"lingot","cache"}', 'Le lingot de limaille de vingt ans existe : scellé dans le contrepoids de sa propre balance certifiée — l''objet que la guilde vérifie chaque année sans jamais le peser lui-même', NULL, '*(il fait sonner une pièce sur le comptoir)* « Tu entends ? Pur et honnête. Comme la maison. On change, ou on philosophe ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_49_10', 'NPC_GAT_49', 'KX', '{"*(tout le reste)*"}', '« Ça ne se compte pas en Yrds ? Alors ça ne se compte pas ici. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_01', 'NPC_GAT_50', 'K0', '{"encheres","regles"}', 'Fonctionnement de l''Hôtel : dépôt, commission 5%, durées d''enchère, retraits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_02', 'NPC_GAT_50', 'K0', '{"cours","publics"}', 'Les cours d''adjudication publics de la semaine (matériaux, armes, consommables)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_03', 'NPC_GAT_50', 'K0', '{"ventes","calendrier"}', 'Le calendrier des ventes exceptionnelles (saisies de Vulko, successions, lots de guilde)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_04', 'NPC_GAT_50', 'K1', '{"tendances","marche"}', 'Ses « tendances » : ce qui monte, ce qui dort (conseil de courtier, payant — 20 Yrds)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_05', 'NPC_GAT_50', 'K1', '{"encheres","techniques"}', 'L''art d''enchérir : sniping, paliers psychologiques, pièges de la salle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_06', 'NPC_GAT_50', 'K1', '{"guildes","achats"}', 'Quelles guildes de joueurs achètent en volume (catégories, pas les noms)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_07', 'NPC_GAT_50', 'K2', '{"acheteur","fantome"}', 'Un enchérisseur anonyme rafle depuis des mois tout ce qui touche à la Caldeira — cartes, reliques, minerais luisants — en payant sans discuter', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_08', 'NPC_GAT_50', 'K2', '{"vente","annulee"}', 'Une vente a été annulée sur ordre du Palais l''an dernier : le lot a « disparu » du registre — mais Fenn se souvient de chaque ligne', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_09', 'NPC_GAT_50', 'K3', '{"registre","double"}', 'Il tient un double intégral du registre, noms compris, chez lui — infraction capitale à la règle de la guilde, assurance contre le jour où on « perdra » une page de trop', NULL, '*(il tourne une page d''un geste fluide)* « Le registre officiel est consultable sur requête du Lord. Il n''en existe qu''un. Naturellement. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_50_10', 'NPC_GAT_50', 'KX', '{"*(tout le reste)*"}', '« Hors catalogue. Repassez à la prochaine vente. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_01', 'NPC_GAT_51', 'K0', '{"annonces","jour"}', 'Les annonces du jour : édits, événements, avis de recherche (flux d''actualité serveur)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_02', 'NPC_GAT_51', 'K0', '{"criee","tarifs"}', 'Faire crier une annonce : 10 Yrds les trois criées (service aux joueurs)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_03', 'NPC_GAT_51', 'K0', '{"semaine","archives"}', 'Le récapitulatif de la semaine (mémoire orale des annonces passées)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_04', 'NPC_GAT_51', 'K1', '{"rumeurs","fraiches"}', 'Ce qui n''est pas encore officiel mais le sera bientôt (elle « chauffe » ses annonces)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_05', 'NPC_GAT_51', 'K1', '{"annonceurs","secrets"}', 'Qui paie pour faire crier quoi — et qui paie pour NE PAS crier (ça existe, ça se voit)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_06', 'NPC_GAT_51', 'K1', '{"voix","technique"}', 'La technique de la criée (projection, mémoire, rythme — lore de métier charmant)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_07', 'NPC_GAT_51', 'K2', '{"annonce","censuree"}', 'Une annonce lui a été retirée des mains en pleine criée le mois dernier — elle en récite le début, appris malgré elle', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_08', 'NPC_GAT_51', 'K2', '{"edit","non_crie"}', 'Un édit signé du Lord attend depuis des semaines sans ordre de criée — elle sait son objet général (réquisitions)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_09', 'NPC_GAT_51', 'K3', '{"secret","unique"}', 'Elle garde UN secret depuis dix ans — le seul de sa vie, confié par sa mère mourante, concernant la naissance d''un enfant du Palais. Le garder la brûle physiquement, chaque jour', NULL, '*(sa voix baisse pour la première fois)* « J''ai crié dix mille nouvelles. Celle-là… celle-là n''a pas de voix. Suivant : OYEZ ! L''Hôtel des Ventes annonce… »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_51_10', 'NPC_GAT_51', 'KX', '{"*(tout le reste)*"}', '« SI JE LE SAVAIS, TOUTE LA PLACE LE SAURAIT ! C''est ma garantie qualité ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_01', 'NPC_GAT_52', 'K0', '{"oeufs","prix"}', 'Catalogue : œuf à couver 80 Yrds, œuf de table 12, coquilles (composant `MAT`) 3', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_02', 'NPC_GAT_52', 'K0', '{"ramassage","metier"}', 'Le métier de ramasseur : où, quand, comment ne pas brûler (lore savoureux)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_03', 'NPC_GAT_52', 'K0', '{"salamandres","especes"}', 'Les espèces de salamandres géantes des Plaines (`MOB_SAL_010-013` — variantes pondeuses)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_04', 'NPC_GAT_52', 'K1', '{"couvaison","technique"}', 'Couver un œuf acheté : température, durée, signes d''éclosion (guide familier, renvoi Pyra)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_05', 'NPC_GAT_52', 'K1', '{"fumerolles","spots"}', 'Ses coins de ramassage (nœuds de récolte des Plaines — il les donne contre un service)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_06', 'NPC_GAT_52', 'K1', '{"pyra","commerce"}', 'Ce que Pyra fait vraiment des œufs (élevage, dressage — et les coussins étranges de Vekka)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_07', 'NPC_GAT_52', 'K2', '{"oeuf","noir"}', 'L''œuf noir veiné d''or : il le montre, à la cave, en chuchotant (description complète)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_08', 'NPC_GAT_52', 'K2', '{"offre","pyra"}', 'L''offre de Pyra pour l''œuf : 5 000 Yrds — cinquante fois le prix normal. Pourquoi elle ? Pourquoi tant ?', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_09', 'NPC_GAT_52', 'K3', '{"oeuf","origine"}', 'Il n''a pas « trouvé » l''œuf : il l''a pris dans un nid en plein territoire du boss de zone `MOB_SAL_026` — et quelque chose l''a laissé repartir. Volontairement. Il rêve depuis d''un œil doré qui le regarde partir', NULL, '*(il resserre la couverture sur le panier)* « Trouvé aux fumerolles, je te dis. Un coup de chance. Les chances, ça se raconte pas trop, ça les use. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_52_10', 'NPC_GAT_52', 'KX', '{"*(tout le reste)*"}', '« Ça, ça pond pas, donc j''y connais rien. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_01', 'NPC_GAT_53', 'K0', '{"legendes","catalogue"}', 'Son répertoire : douze légendes de Gattan à 1 Yrd (chacune = un condensé de lore réel)', '1 Yrd', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_02', 'NPC_GAT_53', 'K0', '{"caldeira","legende"}', 'LA légende de la Caldeira et de Logi (version populaire — complémentaire du récit d''Ulric)', '1 Yrd', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_03', 'NPC_GAT_53', 'K0', '{"fondation","gattan"}', 'La fondation de Gattan et la première coulée de la Grande Forge', '1 Yrd', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_04', 'NPC_GAT_53', 'K1', '{"conte","technique"}', 'L''art du conteur : structure, chute, mémoire (lore de métier — bonus aux joueurs bardes RP)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_05', 'NPC_GAT_53', 'K1', '{"versions","variantes"}', 'Les variantes d''une même légende selon qui la commande (la politique des histoires)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_06', 'NPC_GAT_53', 'K1', '{"marga","memoire"}', 'Ce que la Doyenne Marga `NPC_GAT_99` corrige dans ses contes — et ce qu''elle refuse de corriger', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_07', 'NPC_GAT_53', 'K2', '{"erreurs","systeme"}', 'Son système des erreurs-marqueurs : il l''explique sur UN exemple (une date déplacée dans la légende du blocus)', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_08', 'NPC_GAT_53', 'K2', '{"carte","mensonges"}', 'La « carte des mensonges » de Gattan : trois histoires officielles dont ses marqueurs prouvent qu''elles ont été réécrites', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_09', 'NPC_GAT_53', 'K3', '{"conte","interdit"}', 'Il connaît une treizième légende, jamais contée : celle qu''on lui a payée pour OUBLIER — le seul contrat qu''il ait accepté. Elle concerne la statue de la ville, et l''acompte tombe encore chaque an', NULL, '*(il compte ses Yrds, un par un)* « Douze légendes. Il n''y en a jamais eu que douze. La treizième, c''est le silence — et il est déjà vendu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_53_10', 'NPC_GAT_53', 'KX', '{"*(tout le reste)*"}', '« Ça, ce n''est pas une histoire. Et je ne vends que des histoires. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_01', 'NPC_GAT_54', 'K0', '{"bieres","carte"}', 'La carte : Haleine de Logi 8 Yrds (buff/debuff, voir K0 suivant), trois bières de table à 2', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_02', 'NPC_GAT_54', 'K0', '{"haleine","effets"}', 'Effets de l''Haleine : +5% FOR pendant 1h, -5% précision (consommable à double tranchant)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_03', 'NPC_GAT_54', 'K0', '{"brasserie","visite"}', 'Visite de la brasserie : cuves, cendres, source volcanique (lore artisanal)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_04', 'NPC_GAT_54', 'K1', '{"brassage","technique"}', 'Le malt torréfié aux cendres : procédé (débloque la recette « Bière de cendre », craft cuisine)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_05', 'NPC_GAT_54', 'K1', '{"clause","sylph"}', 'La clause anti-Sylph de la grand-mère : le texte exact, et sa propre exaspération', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_06', 'NPC_GAT_54', 'K1', '{"fosse","soirees"}', 'Les soirées de la fosse de Magnar : ce qui s''y boit, s''y parie, s''y raconte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_07', 'NPC_GAT_54', 'K2', '{"recette","secret"}', 'Le secret de l''Haleine : l''eau n''est pas « de source » — elle est puisée à un geyser précis, dans une zone où le puisage est interdit', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_08', 'NPC_GAT_54', 'K2', '{"grand_mere","indice"}', 'Elle a retrouvé une lettre de la grand-mère : la clause anti-Sylph date du lendemain d''un mariage annulé, il y a soixante ans', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_09', 'NPC_GAT_54', 'K3', '{"clause","verite"}', 'Le fond de la clause : la recette de l''Haleine VIENT d''un brasseur sylph — le fiancé évincé. La bière emblème du feu salamander est une recette de l''air volée par chagrin d''amour. Si Swilvane l''apprend, l''Haleine devient un scandale diplomatique en tonneau', NULL, '*(elle sert une mousse parfaite, la fait claquer sur le comptoir)* « La recette, c''est ma grand-mère. Point. Bois, ou pose des questions moins chères. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_54_10', 'NPC_GAT_54', 'KX', '{"*(tout le reste)*"}', '« Ça se brasse pas, ça me regarde pas ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_01', 'NPC_GAT_55', 'K0', '{"brochettes","carte"}', 'La carte : brochette classique 2 Yrds (+3% END 1h), épicée 4 (+3% FOR 1h), royale 8 (les deux)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_02', 'NPC_GAT_55', 'K0', '{"place","ragots"}', 'Les ragots de la Place, version bon enfant (elle entend tout, ne retient que le drôle)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_03', 'NPC_GAT_55', 'K0', '{"marinade","fumet"}', 'Sa marinade : épices de Rosza, patience et braise douce (préparation visible, recette non)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_04', 'NPC_GAT_55', 'K1', '{"clients","habitudes"}', 'Les habitudes de la Place : qui mange quoi, quand — sociologie de la brochette', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_05', 'NPC_GAT_55', 'K1', '{"gamins","ardoise"}', 'L''ardoise des gamins des Scories — elle explique pourquoi elle s''efface toute seule', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_06', 'NPC_GAT_55', 'K1', '{"marinade","recette"}', 'La recette complète de la marinade (débloque « Brochette marinée », craft cuisine T1)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_07', 'NPC_GAT_55', 'K2', '{"garde","confidence"}', 'Un garde en faction parle trop en mangeant : elle sait les horaires exacts des rondes de nuit de la Porte', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_08', 'NPC_GAT_55', 'K2', '{"client","nocturne"}', 'Un client encapuchonné achète douze brochettes chaque nuit, paie double, ne parle jamais — et sent la pierre froide de la prison', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_09', 'NPC_GAT_55', 'K3', '{"fille","scories"}', 'Les gamins des Scories, l''ardoise, la tendresse : sa propre fille a grandi là-bas, confiée à d''autres quand Danna avait seize ans et rien. La gamine mange à la broche chaque semaine sans savoir qui la nourrit', NULL, '*(elle tourne la broche, le gras chante)* « Les gamins, c''est bon pour le commerce, ça met de la vie. Allez — chaud ! Chaud ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_55_10', 'NPC_GAT_55', 'KX', '{"*(tout le reste)*"}', '« Ça, ça se grille pas, alors j''en vends pas ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_01', 'NPC_GAT_56', 'K0', '{"herbes","prix"}', 'Catalogue : herbes de cendre (composants potions T1-T2), simples médicinaux, graines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_02', 'NPC_GAT_56', 'K0', '{"recolte","spots"}', 'Où cueillir aux Plaines (`ZONE_SAL_HUNT_001`) : les nœuds de récolte publics de flore', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_03', 'NPC_GAT_56', 'K0', '{"plantes","dangers"}', 'Les plantes qui tuent : reconnaître les cousines toxiques (guide anti-empoisonnement)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_04', 'NPC_GAT_56', 'K1', '{"culture","cendre"}', 'Cultiver sur cendre : sa méthode (débloque le nœud de jardin personnel — herbes T2 en ville)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_05', 'NPC_GAT_56', 'K1', '{"commandes","alchimistes"}', 'Ce que Mortis et les autres commandent — les tendances de l''alchimie locale', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_06', 'NPC_GAT_56', 'K1', '{"desolation","flore"}', 'La flore de la Désolation (`ZONE_SAL_HUNT_002`) : rare, brûlante, précieuse (composants T3)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_07', 'NPC_GAT_56', 'K2', '{"pensionnaires","jardin"}', 'Les trois « pensionnaires » du jardin de derrière : des espèces que la botanique dit éteintes', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_08', 'NPC_GAT_56', 'K2', '{"commande","poison"}', 'Quelqu''un lui a commandé la cousine toxique — en connaissance de cause. Elle a refusé. La commande a été honorée ailleurs', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_09', 'NPC_GAT_56', 'K3', '{"pensionnaire","origine"}', 'La troisième pensionnaire vient d''une graine trouvée DANS la Caldeira, dans les cendres du premier raid — elle pousse sans lumière, fleurit sans saison, et Salvia jurerait qu''elle se tourne vers qui parle. Elle refuse d''imaginer ce que Mortis en ferait', NULL, '*(elle arrose lentement)* « Le jardin de derrière, c''est mes convalescentes. On ne visite pas un hôpital de plantes. Autre chose ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_56_10', 'NPC_GAT_56', 'KX', '{"*(tout le reste)*"}', '« Ça pousse pas, ça se cueille pas — ça me dépasse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_01', 'NPC_GAT_57', 'K0', '{"fioles","gamme"}', 'Gamme braise : fiole standard 10 Yrds, braise 25 (immune Surchauffe), braise double 45', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_02', 'NPC_GAT_57', 'K0', '{"surchauffe","verre"}', 'Pourquoi le verre ordinaire lâche dans la Caldeira (D11 expliquée côté matériel)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_03', 'NPC_GAT_57', 'K0', '{"raids","equipement"}', 'Check-list du raider en contenants (conseil honnête, dimensionné par anneau du donjon)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_04', 'NPC_GAT_57', 'K1', '{"soufflage","braise"}', 'Le procédé « braise » : double paroi, cendre entre les deux (débloque recette craft T3)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_05', 'NPC_GAT_57', 'K1', '{"retours","raids"}', 'Ce que les fioles revenues des raids racontent (données d''usage réelles — méta du donjon)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_06', 'NPC_GAT_57', 'K1', '{"solman","rupture"}', 'Pourquoi il est parti de chez Solman : la version complète, plus tendre qu''attendu', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_07', 'NPC_GAT_57', 'K2', '{"commande","palais"}', 'Le Palais lui a commandé des contenants « braise » format ampoule — un format qui ne sert à aucune potion connue', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_08', 'NPC_GAT_57', 'K2', '{"fiole","prototype"}', 'Son prototype ultime : une fiole qui tiendrait le souffle direct de Logi — il lui manque UN composant (verre luisant de Solman ?)', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_09', 'NPC_GAT_57', 'K3', '{"ampoules","lien"}', 'Il a compris ce que sont les ampoules du Palais : le format correspond exactement au plan de guerre que Solman a refusé jadis — quelqu''un a retrouvé le projet des gaz de combat, et Pim, sans le savoir d''abord, en a soufflé les contenants. Sa signature est dessus', NULL, '*(il lève une fiole à la lumière, la fait tourner)* « Je souffle des contenants. Ce qu''on met dedans, c''est la conscience du client. La mienne est... transparente. Autre chose ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_57_10', 'NPC_GAT_57', 'KX', '{"*(tout le reste)*"}', '« Pas du verre, pas mon problème. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_01', 'NPC_GAT_58', 'K0', '{"officine","services"}', 'Les services de l''officine : potions en stock, commandes, délais (elle gère le comptoir)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_02', 'NPC_GAT_58', 'K0', '{"mortis","etat"}', '« Le maître reçoit-il ? » — bulletin de santé du jour, mi-drôle mi-inquiet', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_03', 'NPC_GAT_58', 'K0', '{"alchimie","bases"}', 'Les bases de l''alchimie pour débutants (mieux expliquées que par Mortis lui-même)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_04', 'NPC_GAT_58', 'K1', '{"recettes","fixees"}', 'Les recettes qu''elle a « fixées » : versions fiables des créations du maître (craft T1-T2)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_05', 'NPC_GAT_58', 'K1', '{"experiences","cours"}', 'Les expériences en cours à l''officine (ce qui bouillonne, ce qui inquiète)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_06', 'NPC_GAT_58', 'K1', '{"effets","secondaires"}', 'Le registre des effets secondaires observés sur Mortis (données uniques au monde)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_07', 'NPC_GAT_58', 'K2', '{"grimoire","existence"}', 'Son grimoire de notes : elle admet que l''officine repose dessus — et que Mortis l''ignore', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_08', 'NPC_GAT_58', 'K2', '{"formule","perdue"}', 'Une formule que Mortis a créée puis oubliée à jamais : un antidote universel partiel — elle seule en a la trace, incomplète', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_09', 'NPC_GAT_58', 'K3', '{"maitre","declin"}', 'La vérité qu''elle cache à toute la Ruelle : les trous de mémoire de Mortis ne viennent pas des potions — ils empirent selon un motif qu''elle a documenté, et sa conclusion est que quelque chose EFFACE le maître, méthodiquement. Elle falsifie ses bulletins de santé pour gagner du temps', NULL, '*(elle referme son écritoire, sourire professionnel)* « Le maître va bien. Fatigué, comme tous les génies. Vous vouliez une potion ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_58_10', 'NPC_GAT_58', 'KX', '{"*(tout le reste)*"}', '« Ce n''est pas dans mes notes, donc je ne peux rien affirmer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_01', 'NPC_GAT_59', 'K0', '{"cendres","achat"}', 'Grille d''achat : cendre commune 2 Yrds, de wyrm 15, d''alpha (mini-boss/boss `MOB_SAL_025-026`) 120', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_02', 'NPC_GAT_59', 'K0', '{"cendres","usages"}', 'À quoi servent les cendres : composants de potions de résistance, teintures, encres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_03', 'NPC_GAT_59', 'K0', '{"collecte","technique"}', 'Ramasser une cendre correctement (avant qu''elle refroidisse — fenêtre de loot expliquée)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_04', 'NPC_GAT_59', 'K1', '{"signatures","nez"}', 'Chaque cendre a sa signature : démonstration de flair sur un sachet du joueur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_05', 'NPC_GAT_59', 'K1', '{"cours","especes"}', 'Quelles cendres montent (indexées sur les potions à la mode — lecture du méta d''alchimie)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_06', 'NPC_GAT_59', 'K1', '{"cendre","caldeira"}', 'La cendre de la Caldeira ne ressemble à aucune autre — il en analyse l''étrangeté à voix haute', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_07', 'NPC_GAT_59', 'K2', '{"client","collection"}', 'Quelqu''un lui achète TOUTE cendre provenant de la Caldeira, prix fort, sans discuter — le même acheteur fantôme que l''Hôtel des Ventes ?', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_08', 'NPC_GAT_59', 'K2', '{"morn","commerce"}', 'Son commerce avec Morn `NPC_GAT_69` : les « cendres des vrais morts » (comptes bannis) ont des propriétés que la cendre de mob n''a pas', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_09', 'NPC_GAT_59', 'K3', '{"cendre","humaine"}', 'Le fond du commerce avec Morn : la cendre des « vrais morts » réagit aux Remain Lights — Mortis l''a établi une nuit d''ivresse et l''a oublié le lendemain. Coff, lui, n''a pas oublié. Ce qui se vend là frôle la nécromancie de données, et il le sait', NULL, '*(il souffle délicatement sur une coupelle)* « Toute cendre vient d''un feu honnête, ici. C''est écrit sur l''enseigne. Poussière… et fortune. Tu vends ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_59_10', 'NPC_GAT_59', 'KX', '{"*(tout le reste)*"}', '« Pas de cendre, pas d''affaire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_01', 'NPC_GAT_60', 'K0', '{"tatouage","tarifs"}', 'Catalogue cosmétique : motifs, tailles, prix (20-200 Yrds) — visible via `!outfit`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_02', 'NPC_GAT_60', 'K0', '{"encres","composition"}', 'Ses encres : cendre fine, pigments de Salvia, technique de chauffe', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_03', 'NPC_GAT_60', 'K0', '{"motifs","signification"}', 'Le langage des motifs salamander (ce que votre tatouage dira de vous à Gattan)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_04', 'NPC_GAT_60', 'K1', '{"glyphe","souffle"}', 'Le Glyphe du Souffle existe : effets réels (-15% de gain de Surchauffe personnel en Caldeira), liste d''attente', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_05', 'NPC_GAT_60', 'K1', '{"composants","glyphe"}', 'Les composants du glyphe : cendre d''alpha + encre de Léviathan (le joueur peut les fournir pour couper la file)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_06', 'NPC_GAT_60', 'K1', '{"clients","fosse"}', 'Qui porte quoi à la fosse de Magnar (les tatouages comme trombinoscope du milieu)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_07', 'NPC_GAT_60', 'K2', '{"decouverte","accident"}', 'Comment il a découvert l''effet du glyphe : le récit complet de l''accident (un client raider revenu vivant d''un wipe total)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_08', 'NPC_GAT_60', 'K2', '{"glyphe","variante"}', 'Il soupçonne qu''une variante à l''encre de Jörmun (boss d''Undine) donnerait un glyphe d''Apnée — jamais testé, trop cher', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_09', 'NPC_GAT_60', 'K3', '{"glyphe","rate"}', 'Il y a eu UN glyphe raté : le porteur accumule la Surchauffe deux fois plus vite, à vie, et l''ignore — Zarn n''a jamais osé le lui dire. L''homme monte régulièrement à la Caldeira. Chaque expédition, Zarn guette la liste des morts de Drogan', NULL, '*(il essuie son aiguille, très lentement)* « Mes glyphes sortent tous parfaits. Question de réputation. Tu veux voir le book ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_60_10', 'NPC_GAT_60', 'KX', '{"*(tout le reste)*"}', '« Ça ne s''encre pas. Donc ça ne m''encre — pardon, m''ancre — nulle part. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_01', 'NPC_GAT_61', 'K0', '{"soins","contrat"}', 'Son contrat : soin contre Yrds, zéro question, zéro registre (tarif : la moitié de Malvo)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_02', 'NPC_GAT_61', 'K0', '{"methodes","boue"}', 'Ses méthodes : boue de geyser, crin de wyrm, cendre tiède (lore de médecine populaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_03', 'NPC_GAT_61', 'K0', '{"rideau","regles"}', 'Les règles du rideau rouge : on entre seul, on ressort réparé, on ne revient pas dire merci', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_04', 'NPC_GAT_61', 'K1', '{"remedes","recettes"}', 'Trois remèdes de rebouteuse (débloque des recettes de premiers soins craftables T1)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_05', 'NPC_GAT_61', 'K1', '{"blessures","lecture"}', 'Ce que les blessures racontent (elle lit les plaies comme Hilde lit les lames)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_06', 'NPC_GAT_61', 'K1', '{"malvo","arrangement"}', 'Son arrangement tacite avec Malvo : qui envoie qui, et pourquoi les deux s''en défendent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_07', 'NPC_GAT_61', 'K2', '{"patients","motifs"}', 'Les blessures qui reviennent : trois motifs récurrents dans sa clientèle qui dessinent la violence cachée de Gattan', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_08', 'NPC_GAT_61', 'K2', '{"patient","griffes"}', 'Elle a soigné des griffures qu''aucune bête connue du territoire n''inflige — profondes, régulières, cautérisées à mesure. Le patient n''a rien dit. Elle non plus', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_09', 'NPC_GAT_61', 'K3', '{"registre","mental"}', 'Son secret professionnel inversé : elle n''oublie RIEN. Chaque patient, chaque blessure, chaque date — un registre mental complet de vingt ans de violence clandestine. Si elle parlait, la moitié de Gattan tomberait. Elle a choisi de devenir un coffre-fort qui soigne', NULL, '*(elle rince ses mains, longuement)* « J''oublie à mesure. C''est mon talent principal. Le soin, c''est en second. Assieds-toi ou sors. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_61_10', 'NPC_GAT_61', 'KX', '{"*(tout le reste)*"}', '« Pas une blessure ? Pas mon rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_01', 'NPC_GAT_62', 'K0', '{"explosifs","legaux"}', 'Catalogue licencié : fumigènes 15 Yrds, pétards de diversion 10, charges de minage 60', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_02', 'NPC_GAT_62', 'K0', '{"licence","histoire"}', 'Sa licence, son histoire, ses sourcils — le récit fondateur, rodé et hilarant', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_03', 'NPC_GAT_62', 'K0', '{"securite","manipulation"}', 'Manipuler un explosif sans finir célèbre (guide de sécurité obligatoire avant tout achat)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_04', 'NPC_GAT_62', 'K1', '{"usages","tactiques"}', 'Usages tactiques des fumigènes/diversions contre les mobs (aggro et line-of-sight expliqués)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_05', 'NPC_GAT_62', 'K1', '{"composants","poudres"}', 'Ses composants : soufre de la Désolation, cendres de Coff, salpêtre (chaînage `MAT`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_06', 'NPC_GAT_62', 'K1', '{"arriere","existence"}', 'L''arrière-boutique « n''existe pas » — il le dit en tapotant le four à pain, avec un clin d''œil tarifé', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_07', 'NPC_GAT_62', 'K2', '{"catalogue","four"}', 'Le catalogue du four : grenades incendiaires T3, charges perce-muraille (vente sous conditions de réputation)', '`AFF>=75+REP:VOIE_SCORIES>=2`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_08', 'NPC_GAT_62', 'K2', '{"commande","refusee"}', 'On lui a commandé « de quoi ouvrir un mur de basalte de trois mètres » — épaisseur exacte des murs de la prison. Il a refusé. Il n''a pas prévenu la garde non plus', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_09', 'NPC_GAT_62', 'K3', '{"toux","logi"}', '« La Toux de Logi » : une charge conçue à partir d''un résidu ramené de la Caldeira, qui brûle SANS combustible — elle viole tout ce qu''il sait de son art. Il la garde parce que la vendre serait un crime, la détruire un mystère perdu, et la comprendre… il y travaille. Chaque nuit. Ça l''empêche de dormir', NULL, '*(il pose une main paternelle sur le four à pain)* « Ici on fait du pain et du POF réglementaire. La poésie, c''est en face, chez le tatoueur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_62_10', 'NPC_GAT_62', 'KX', '{"*(tout le reste)*"}', '« Ça pète pas ? Connais pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_01', 'NPC_GAT_63', 'K0', '{"glandes","achat"}', 'Grille d''achat : glande commune 10 Yrds, de wyrm 45, du mini-boss `MOB_SAL_025` 200', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_02', 'NPC_GAT_63', 'K0', '{"antivenins","vente"}', 'Catalogue antivenins : par famille de mobs SAL (contre les DoT poison des `MOB_SAL_02x`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_03', 'NPC_GAT_63', 'K0', '{"extraction","technique"}', 'Extraire une glande sans la percer (tuto loot — +30% de taux de récupération si suivi)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_04', 'NPC_GAT_63', 'K1', '{"venins","taxonomie"}', 'Sa taxonomie des venins du territoire (lore naturaliste — le bestiaire vu par ses toxines)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_05', 'NPC_GAT_63', 'K1', '{"immunisation","methode"}', 'Sa méthode d''immunisation par micro-doses (buff `RES poison` mineur permanent — parcours long et payant)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_06', 'NPC_GAT_63', 'K1', '{"clients","discretion"}', 'Qui achète des venins à Gattan — catégories professionnelles, sans noms (« la curiosité a un plafond, le mien est bas »)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_07', 'NPC_GAT_63', 'K2', '{"venin","introuvable"}', 'On lui a apporté un venin qu''il n''a pas su classer : il détruit les tissus EN LES CRISTALLISANT. Provenance déclarée : Désolation. Provenance réelle : il en doute', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_08', 'NPC_GAT_63', 'K2', '{"commande","salvia"}', 'Le poison que Salvia a refusé de vendre (`QI_56_08`) : l''acheteur est venu chez lui ensuite. Il décrit l''homme — et il a vendu', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_09', 'NPC_GAT_63', 'K3', '{"vente","consequence"}', 'Trois semaines après sa vente, un notable de Gattan est mort de « fièvre des cendres ». Les symptômes exacts de son produit. Il a relu son registre cent fois : la vente était légale, la mort ne l''était pas, et sa signature relie les deux. Il attend depuis qu''on frappe à sa porte', NULL, '*(sa paupière figée ne cligne pas)* « Tout ce qui sort d''ici est apparié à son antidote. Ce qu''on fait de la paire… relève de l''acheteur. Registre en règle. Question suivante. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_63_10', 'NPC_GAT_63', 'KX', '{"*(tout le reste)*"}', '« Ni venin, ni antidote. Donc néant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_01', 'NPC_GAT_64', 'K0', '{"culte","doctrine"}', 'La doctrine de la Flamme : credo, rites, calendrier liturgique de Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_02', 'NPC_GAT_64', 'K0', '{"benedictions","tarifs"}', 'Bénédictions : mineure 20 Yrds (+2% RES feu 4h), majeure 100 (+5%, 12h), des armes avant raid', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_03', 'NPC_GAT_64', 'K0', '{"temple","histoire"}', 'L''histoire du Temple et du Brasier Éternel (jamais éteint depuis la fondation)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_04', 'NPC_GAT_64', 'K1', '{"theologie","flamme"}', 'Théologie approfondie : la Flamme comme épreuve, non comme récompense (lore religieux riche)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_05', 'NPC_GAT_64', 'K1', '{"culte","politique"}', 'Les rapports du Culte et du Palais : qui bénit qui, et ce que ça coûte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_06', 'NPC_GAT_64', 'K1', '{"embra","oracle"}', 'L''Oracle Embra : ce qu''il pense officiellement de ses prédictions (prudence pastorale)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_07', 'NPC_GAT_64', 'K2', '{"doute","aveu"}', 'Son doute — il l''avoue à mots couverts, en théologien : « les bénédictions opèrent, mais qui opère les bénédictions ? »', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_08', 'NPC_GAT_64', 'K2', '{"embra","trouble"}', 'Ce qui le trouble vraiment chez Embra : deux de ses prédictions décrivaient des événements QU''AUCUNE prière n''a jamais obtenus — quelque chose lui parle, à elle', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_09', 'NPC_GAT_64', 'K3', '{"verite","mecanique"}', 'Sa conclusion secrète de quarante ans : « la Flamme » est un mécanisme — les buffs tombent avec la régularité d''un engrenage, jamais avec la fantaisie d''une grâce. Il sert une machine et fait d''elle un dieu, car la machine console mieux que le vide. Si ce raisonnement sortait du chœur, le Culte s''effondrerait', NULL, '*(il ravive le Brasier d''un geste ample)* « La Flamme éprouve la foi de ceux qui la questionnent. La mienne a été éprouvée. Longuement. Prions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_64_10', 'NPC_GAT_64', 'KX', '{"*(tout le reste)*"}', '« Cela relève du siècle, mon enfant. Ici, nous ne traitons qu''avec l''éternel. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_01', 'NPC_GAT_65', 'K0', '{"resurrection","rite"}', 'Le rite du Retour : conditions, offrande, la « part de la Flamme » (30% des Yrds — mécanique de mort expliquée en diégèse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_02', 'NPC_GAT_65', 'K0', '{"remain_light","nature"}', 'Ce qu''est une Remain Light selon le Culte (théologie appliquée de la mort en Alfheim)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_03', 'NPC_GAT_65', 'K0', '{"rites","quotidiens"}', 'Les rites quotidiens du Temple : heures, offrandes, à quoi chacun sert', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_04', 'NPC_GAT_65', 'K1', '{"retours","statistiques"}', 'Ses 4 206 retours : ce que dix-huit ans de chapelle apprennent sur la mort et les joueurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_05', 'NPC_GAT_65', 'K1', '{"endeuilles","accompagnement"}', 'Comment elle accompagne ceux dont la flamme NE revient pas (les « vrais morts » — renvoi vers Morn)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_06', 'NPC_GAT_65', 'K1', '{"penitence","remise"}', 'La pénitence peut être réduite : services au Temple contre remise de la part de la Flamme (mécanisme légal)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_07', 'NPC_GAT_65', 'K2', '{"retour","anormal"}', 'UN retour l''a marquée : une flamme s''est rallumée SANS rite, seule, à minuit — le registre du Temple n''en dit rien, elle si', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_08', 'NPC_GAT_65', 'K2', '{"ignatius","inquietude"}', 'Elle a compris que le Grand-Prêtre doute — et le porte dans ses prières sans le lui dire jamais', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_09', 'NPC_GAT_65', 'K3', '{"flamme","refusee"}', 'Une fois, une seule, elle a REFUSÉ un rite de Retour — l''homme payait, tout était en règle, et quelque chose dans sa flamme l''a fait reculer d''horreur. L''homme est reparti, sa Remain Light sous le bras. Elle croise parfois son visage en ville. Vivant. Sans avoir jamais été ressuscité', NULL, '*(elle protège une flamme votive de la main)* « Chaque retour accompli est inscrit au registre. Chaque retour, mon enfant. Va en paix. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_65_10', 'NPC_GAT_65', 'KX', '{"*(tout le reste)*"}', '« La chapelle ne connaît que la flamme et son retour. Le reste appartient au parvis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_01', 'NPC_GAT_66', 'K0', '{"temple","corvees"}', 'La vie de novice : cierges, cendres, horaires — et où trouver chaque prêtre à chaque heure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_02', 'NPC_GAT_66', 'K0', '{"brasier","entretien"}', 'L''entretien du Brasier Éternel (ce que Golm laisse faire aux novices : presque rien)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_03', 'NPC_GAT_66', 'K0', '{"culte","catechisme"}', 'Le catéchisme de la Flamme, récité avec application (version débutant du lore religieux)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_04', 'NPC_GAT_66', 'K1', '{"visions","lignes"}', 'Les « lignes » qu''il voit dans le Brasier : sa description, enfantine et terriblement exacte (du défilement de données)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_05', 'NPC_GAT_66', 'K1', '{"chiffres","foule"}', 'Les chiffres qui suivent la foule : il a vérifié trois fois depuis le parvis — ça CORRESPOND', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_06', 'NPC_GAT_66', 'K1', '{"adultes","reactions"}', 'Comment chacun a réagi : Ignatius (repos), Embra (silence), Calda (prière) — cartographie de qui sait quoi', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_07', 'NPC_GAT_66', 'K2', '{"mot","braises"}', 'LE mot écrit dans les braises : il l''a recopié en cachette sur un bout de cire. Il le montre — une chaîne de caractères sans signification… sauf pour qui reconnaît un identifiant système', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_08', 'NPC_GAT_66', 'K2', '{"sela","pacte"}', 'Son pacte avec Sela : ils notent chacun leurs « moments étranges » et comparent — deux PNJ qui enquêtent sur leur propre monde', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_09', 'NPC_GAT_66', 'K3', '{"brasier","reponse"}', 'La nuit dernière, pour la première fois, il a posé une question au Brasier — à voix haute, seul. Et les lignes se sont ARRÊTÉES. Toutes. Trois secondes. Comme une respiration retenue. Il n''est pas retourné au Brasier depuis, et personne ne doit savoir qu''IL SAIT qu''on l''écoute', NULL, '*(il serre ses cierges contre lui)* « J''ai plus de visions. Le Grand-Prêtre dit que c''était la fatigue. Il… il a raison. Je dois porter ça à la chapelle. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_66_10', 'NPC_GAT_66', 'KX', '{"*(tout le reste)*"}', '« Je suis que novice. Demande aux grandes robes. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_01', 'NPC_GAT_67', 'K0', '{"brasier","regles"}', 'Les règles de la rotonde : trois pas, silence, offrandes par la grille (procédure visiteur)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_02', 'NPC_GAT_67', 'K0', '{"brasier","histoire"}', 'L''histoire du Brasier : fondation, alimentations rituelles, les trois « presque-extinctions » historiques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_03', 'NPC_GAT_67', 'K0', '{"garde","charge"}', 'Sa charge : serment, horaires, la relève qui n''existe pas (il est la relève)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_04', 'NPC_GAT_67', 'K1', '{"veille","techniques"}', 'Trente ans de veille : ce qu''on apprend d''un feu en le regardant chaque jour (lore contemplatif superbe)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_05', 'NPC_GAT_67', 'K1', '{"visiteurs","memorables"}', 'Les visiteurs mémorables de la rotonde (dont un Spriggan qui a défié les trois pas — récit de la seule fois où la masse a servi)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_06', 'NPC_GAT_67', 'K1', '{"presque","extinction"}', 'La troisième presque-extinction, il y était : la nuit où le Brasier a baissé d''un coup, sans cause, sans vent', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_07', 'NPC_GAT_67', 'K2', '{"timo","vu"}', 'Il a vu Timo voir. Il décrit la scène : l''enfant, les yeux qui suivent QUELQUE CHOSE dans les flammes, de gauche à droite, comme une lecture', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_08', 'NPC_GAT_67', 'K2', '{"brasier","battement"}', 'Son secret d''observateur : le Brasier a un battement. Régulier. Trente ans de veille pour l''entendre — le feu PULSE, comme une machine respire', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_09', 'NPC_GAT_67', 'K3', '{"extinction","nuit"}', 'La nuit de la presque-extinction, il a fait la seule chose interdite : il a TOUCHÉ le Brasier pour le ranimer. Sa paume ne porte aucune brûlure — le feu était FROID, l''espace d''un instant, froid et sombre comme une chose débranchée. Il a menti dans son rapport et remis du bois sur un feu déjà revenu. Son serment protège un mystère qu''il ne comprend pas', NULL, '*(il resserre sa prise sur la masse, regard au feu)* « Le Brasier a jamais faibli sous ma garde. C''est écrit dans le registre du Temple. Les registres du Temple mentent pas. Trois pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_67_10', 'NPC_GAT_67', 'KX', '{"*(tout le reste)*"}', '« Ma juridiction fait trois pas de rayon. Ta question est dehors. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_01', 'NPC_GAT_68', 'K0', '{"hymnes","horaires"}', 'Le calendrier des hymnes et leurs effets de zone (Aube = régén, Vêpres = RES feu mineure)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_02', 'NPC_GAT_68', 'K0', '{"chants","repertoire"}', 'Le répertoire sacré du Culte : douze hymnes, leurs occasions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_03', 'NPC_GAT_68', 'K0', '{"tribune","acoustique"}', 'L''acoustique du Temple : pourquoi les hymnes portent jusqu''à la Place (architecture sonore)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_04', 'NPC_GAT_68', 'K1', '{"technique","vocale"}', 'Technique vocale liturgique (bonus RP aux joueurs bardes ; renvoi au tempo du donjon Puca)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_05', 'NPC_GAT_68', 'K1', '{"notes","effets"}', 'Sa découverte publique-mais-discrète : certaines SÉQUENCES produisent l''effet, pas la ferveur (démonstration à l''appui)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_06', 'NPC_GAT_68', 'K1', '{"carnet","catalogue"}', 'Son carnet de solfège : dix ans de séquences testées, classées par effet (le grimoire déguisé en psautier)', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_07', 'NPC_GAT_68', 'K2', '{"sequence","interdite"}', 'Une séquence de son catalogue fait BAISSER la lumière du Brasier d''un demi-ton de flamme — elle ne l''a chantée qu''une fois, la nuit de la presque-extinction de Golm', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_08', 'NPC_GAT_68', 'K2', '{"monde","clavier"}', 'Sa théorie complète : le monde est un instrument — les hymnes sont des commandes que quelqu''un, jadis, a mises en musique pour les faire survivre aux siècles', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_09', 'NPC_GAT_68', 'K3', '{"extinction","culpabilite"}', 'La chronologie qu''elle est seule à connaître : SA séquence d''abord, la presque-extinction ENSUITE. Trois secondes d''écart. Elle a peut-être éteint le feu sacré de son peuple avec sept notes — et elle a réécrit la page de son carnet pour ne plus jamais pouvoir la rechanter, même par accident. Le fragment original est enterré sous la tribune', NULL, '*(elle plaque une main sur sa gorge, sourit)* « Cette nuit-là, je dormais. Les chantres dorment tôt — la voix l''exige. Tu voulais entendre l''Hymne de l''Aube ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_68_10', 'NPC_GAT_68', 'KX', '{"*(tout le reste)*"}', '« Cela ne se chante pas — donc je n''ai rien à en dire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_01', 'NPC_GAT_69', 'K0', '{"necropole","visite"}', 'La nécropole : accès, usages, respect dû aux stèles (règles du lieu)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_02', 'NPC_GAT_69', 'K0', '{"vrais_morts","nature"}', 'Ce qu''est un « vrai mort » : celui dont la flamme ne se rallume jamais (la permadeath expliquée en diégèse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_03', 'NPC_GAT_69', 'K0', '{"stelles","registre"}', 'Le registre des stèles : qui repose ici, depuis quand (mémorial consultable)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_04', 'NPC_GAT_69', 'K1', '{"funerailles","rite"}', 'Son rite sans Culte : ce qu''il dit sur chaque tombe, pourquoi le Culte ne bénit pas', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_05', 'NPC_GAT_69', 'K1', '{"tombes","histoires"}', 'Les histoires des stèles : chaque vrai mort avait une vie, il les raconte toutes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_06', 'NPC_GAT_69', 'K1', '{"disparitions","motifs"}', 'Ce que les vrais morts ont en commun : ses observations de vingt ans (les motifs des bannissements, vus d''en bas)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_07', 'NPC_GAT_69', 'K2', '{"tombe","vide"}', 'Une stèle de sa nécropole couvre une tombe VIDE : le corps de cendre s''est dissous en une nuit, un an après l''enterrement — le seul cas', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_08', 'NPC_GAT_69', 'K2', '{"coff","commerce"}', 'Le commerce avec Coff : il vend les cendres excédentaires des vrais morts — et à quoi Coff a découvert qu''elles réagissent', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_09', 'NPC_GAT_69', 'K3', '{"hiver","secret"}', 'Le Grand Hiver, la « viande de wyrm » de Kargh (`QI_44_09`) : Morn sait ce que c''était, parce que c''est LUI qui a fourni — les réserves funéraires de bêtes de trait enterrées, exhumées pour nourrir le quartier. Pas pire que la famine, pire que le dicible. Kargh et lui ont sauvé cent familles et perdu une amitié', NULL, '*(il plante sa pelle, s''appuie dessus)* « Le Grand Hiver a eu ses morts et ses vivants. J''ai enterré les uns. Le reste, c''est du présent — et le présent, c''est pas mon rayon. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_69_10', 'NPC_GAT_69', 'KX', '{"*(tout le reste)*"}', '« Ça se creuse pas, ça se grave pas — vois en ville. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_01', 'NPC_GAT_70', 'K0', '{"oracle","consultation"}', 'Consulter l''Oracle : offrande (30 Yrds), une question, une lecture — les règles de l''alcôve', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_02', 'NPC_GAT_70', 'K0', '{"predictions","publiques"}', 'Les prédictions publiques en cours (les hooks d''événements serveur actifs, en langage de braises)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_03', 'NPC_GAT_70', 'K0', '{"oracle","histoire"}', 'La lignée des Oracles des Braises : elle est la neuvième, et la première aussi exacte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_04', 'NPC_GAT_70', 'K1', '{"lecture","personnelle"}', 'Une lecture personnelle pour le joueur (teaser scripté de sa prochaine quête disponible — l''oracle comme quest-hub déguisé)', '30 Yrds', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_05', 'NPC_GAT_70', 'K1', '{"traduction","images"}', 'Son lexique de traduction : ce que signifient l''œuf, la porte, le fil rouge (grille de lecture des annonces)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_06', 'NPC_GAT_70', 'K1', '{"epuisement","prix"}', 'Le prix physique des visions (elle vieillit par à-coups — les grandes prophéties lui coûtent des mois)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_07', 'NPC_GAT_70', 'K2', '{"receptions","nature"}', 'Sa confession de méthode : elle ne voit pas, elle REÇOIT — formé, daté, adressé. « Quelqu''un écrit, je lis à voix haute »', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_08', 'NPC_GAT_70', 'K2', '{"vision","refusee"}', 'Une fois, elle a reçu une vision avec ordre de NE PAS la dire — la première fois que la source lui interdisait. Elle a obéi. La chose prédite est arrivée quand même, en pire', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_09', 'NPC_GAT_70', 'K3', '{"brasier","interdiction"}', 'Pourquoi elle ne prédit jamais rien sur le Brasier : la SEULE fois où elle a tourné sa lecture vers lui, la vision reçue était une image d''elle-même, dans l''alcôve, en train de lire — vue DE L''INTÉRIEUR du feu. Le message était limpide : « je te regarde aussi ». Elle n''a plus jamais regardé', NULL, '*(les braises crépitent ; elle n''y jette pas un regard)* « Le Brasier appartient à Golm et la Flamme à elle-même. L''Oracle lit les braises froides. Uniquement les froides. Ta question ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_70_10', 'NPC_GAT_70', 'KX', '{"*(tout le reste)*"}', '« Les braises n''ont rien montré. Ça arrive. C''est même le plus fréquent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_01', 'NPC_GAT_71', 'K0', '{"aumone","collecte"}', 'La collecte : pour qui, combien, où va l''argent (comptes publics sur demande)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_02', 'NPC_GAT_71', 'K0', '{"blesses","front"}', 'Les blessés du front : combien, où, ce dont ils manquent (l''envers de la gloire militaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_03', 'NPC_GAT_71', 'K0', '{"dons","fiscalite"}', 'Donner à la quête : ce que ça change (réputation Temple + Voie des Scories simultanées — rare)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_04', 'NPC_GAT_71', 'K1', '{"genereux","carte"}', 'Sa carte mentale de la générosité de Gattan : qui donne, qui esquive (sociologie de la Place)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_05', 'NPC_GAT_71', 'K1', '{"besoins","urgents"}', 'Les besoins urgents du moment (quêtes de dons ciblées : béquilles, couvertures, potions)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_06', 'NPC_GAT_71', 'K1', '{"cendreux","refus"}', 'Le Vieux Cendreux refuse son aumône depuis dix ans — un mendiant qui refuse la charité du Temple, il n''en connaît qu''un', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_07', 'NPC_GAT_71', 'K2', '{"donateur","anonyme"}', 'Un donateur anonyme dépose chaque lune une somme énorme dans la sébile, de nuit, emballée dans le même tissu — un tissu dont il a fini par reconnaître la lisière (Vekka saurait)', '`AFF>=75`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_08', 'NPC_GAT_71', 'K2', '{"comptes","trou"}', 'Il manque UNE ligne dans dix ans de comptes parfaits : une somme sortie « sur ordre du Grand-Prêtre », sans destination — sa seule entorse, jamais expliquée par Ignatius', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_09', 'NPC_GAT_71', 'K3', '{"frere","front"}', '« Les blessés du front » ont un visage fondateur : son propre frère, revenu brisé, mort faute de soins pendant que Dole était en prière. La collecte entière est une pénitence privée déguisée en œuvre publique — et il ment chaque jour en disant servir la Flamme : il sert un remords', NULL, '*(il berce sa sébile comme un nouveau-né)* « L''œuvre parle pour elle. Les histoires personnelles n''ajoutent pas un Yrd à la sébile. Deux Yrds, mon frère ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_71_10', 'NPC_GAT_71', 'KX', '{"*(tout le reste)*"}', '« Je ne collecte que des Yrds et des bontés. Le reste passe. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_01', 'NPC_GAT_72', 'K0', '{"porte","procedures"}', 'Les procédures de la Grande Porte : contrôles, taxes (renvoi Marza), objets interdits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_02', 'NPC_GAT_72', 'K0', '{"trafic","jour"}', 'Le trafic du jour : qui est entré, combien de chariots (données publiques du registre)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_03', 'NPC_GAT_72', 'K0', '{"poste","quotidien"}', 'Le quotidien du poste de jour (anecdotes de guérite, quinze ans de défilé)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_04', 'NPC_GAT_72', 'K1', '{"radar","methode"}', 'Sa méthode de détection : les signes qui trahissent (leçon d''observation — utile aux joueurs contrebandiers pour se corriger…)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_05', 'NPC_GAT_72', 'K1', '{"prises","tableau"}', 'Son tableau de chasse : les prises mémorables (dont un chargement de « charbon » qui sonnait creux)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_06', 'NPC_GAT_72', 'K1', '{"pause","faille"}', 'Il SAIT que les contrebandiers passent à sa pause — et il maintient sa pause à heure fixe depuis dix ans. Pourquoi ? « Un poisson qui connaît le filet nage dedans avec confiance. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_07', 'NPC_GAT_72', 'K2', '{"registre","pause"}', 'Le registre secret de la pause : il note depuis des années QUI passe pendant son déjeuner — la carte complète de la petite contrebande de Gattan, constituée en la laissant faire', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_08', 'NPC_GAT_72', 'K2', '{"chariot","palais"}', 'Un chariot du PALAIS est passé un jour pendant sa pause — à l''heure des fraudeurs. Il l''a noté aussi. Depuis, il se demande qui, au Palais, connaît son registre de trop près', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_09', 'NPC_GAT_72', 'K3', '{"orim","arrangement"}', 'La vérité sur Orim `NPC_GAT_23` : Stigg a percé la filière du charbon d''Yggdrasil depuis SEPT ANS. Il se tait contre un unique paiement annuel — pas d''Yrds : un sac de charbon spécial, chaque hiver, livré anonymement à une adresse de la Voie des Scories. L''adresse d''une veuve de garde. Sa corruption est une pension de veuve, et il en a honte et fierté à parts égales', NULL, '*(il remonte son ceinturon, regard sur la file)* « Orim ? Contrôlé cent fois. Du charbon, rien que du charbon. Circulez — les honnêtes gens attendent derrière. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_72_10', 'NPC_GAT_72', 'KX', '{"*(tout le reste)*"}', '« Pas vu passer, donc pas mon rayon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_01', 'NPC_GAT_73', 'K0', '{"poterne","regles"}', 'Les règles de la nuit : poterne, laissez-passer, urgences (procédure nocturne)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_02', 'NPC_GAT_73', 'K0', '{"nuit","dangers"}', 'Les dangers nocturnes des abords (spawns de nuit des Plaines — table crépusculaire)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_03', 'NPC_GAT_73', 'K0', '{"passages","statistiques"}', 'Ce qui passe la poterne par nuit (chiffres publics — la ville nocturne quantifiée)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_04', 'NPC_GAT_73', 'K1', '{"sorties","motifs"}', 'Qui sort la nuit et pourquoi : sa typologie des noctambules (sociologie nocturne savoureuse)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_05', 'NPC_GAT_73', 'K1', '{"principe","entree"}', 'Son principe sortir/entrer : la doctrine complète, et les trois mensonges les plus courants', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_06', 'NPC_GAT_73', 'K1', '{"briefing","crepuscule"}', 'Ce que Stigg et elle s''échangent au crépuscule (la Porte comme organisme à deux têtes)', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_07', 'NPC_GAT_73', 'K2', '{"sorties","regulieres"}', 'Trois personnes sortent CHAQUE nuit à heures fixes, depuis des années : le client aux brochettes de Danna, une silhouette en robe du Temple, et quelqu''un du Palais par la poterne dérobée', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_08', 'NPC_GAT_73', 'K2', '{"entree","refusee"}', 'La nuit où elle a refusé l''entrée à un blessé — qui est mort au pied du mur. Son seul refus mortel : les raisons, le visage, la date. Elle paie encore', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_09', 'NPC_GAT_73', 'K3', '{"silhouette","temple"}', 'La silhouette en robe du Temple : elle l''a suivie une fois, hors service — jusqu''à la nécropole de Morn, où la robe a passé UNE HEURE agenouillée sur la tombe vide (`QI_69_07`). Elle a reconnu la démarche : c''est le Grand-Prêtre Ignatius. Le chef du Culte prie chaque nuit sur la seule tombe que son dogme ne peut pas expliquer', NULL, '*(elle souffle sur ses mains, regard au créneau)* « La nuit, chacun ses dévotions. Moi c''est la poterne, point. Tu sors ou tu entres ? »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_73_10', 'NPC_GAT_73', 'KX', '{"*(tout le reste)*"}', '« Question de jour. Reviens quand le soleil bosse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_01', 'NPC_GAT_74', 'K0', '{"taxes","bareme"}', 'Le barème douanier : 5% marchandises communes, 10% luxe, exemptions (militaire, Temple)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_02', 'NPC_GAT_74', 'K0', '{"declaration","procedure"}', 'Comment déclarer sa cargaison (procédure marchande pour joueurs commerçants)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_03', 'NPC_GAT_74', 'K0', '{"registre","consultation"}', 'Le registre des entrées : ce qui est consultable publiquement (flux commerciaux agrégés)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_04', 'NPC_GAT_74', 'K1', '{"fraudes","classiques"}', 'Les fraudes classiques et comment elle les coince (le double-fond, la fausse déclaration d''espèce, le « cadeau personnel » de cinquante lingots)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_05', 'NPC_GAT_74', 'K1', '{"flux","anomalies"}', 'Les anomalies de flux du trimestre (ce qui entre trop ou plus assez — lecture macro-économique)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_06', 'NPC_GAT_74', 'K1', '{"orim","guerre"}', 'Sa guerre contre Orim : douze ans de contrôles vains, racontés avec une rage gourmande', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_07', 'NPC_GAT_74', 'K2', '{"exemption","palais"}', 'Les chariots du Palais sont exemptés ET non inscrits — elle a compté : leur fréquence a triplé en deux mois. Officiellement, elle n''a rien compté du tout', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_08', 'NPC_GAT_74', 'K2', '{"registre","rature"}', 'Il y a UNE rature dans douze ans de registre : une entrée effacée sur ordre écrit du Lord, l''année de la mort du notable (`QI_63_09`) — elle a gardé l''ordre écrit', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_09', 'NPC_GAT_74', 'K3', '{"copie","integrale"}', 'Comme Fenn, comme tant de teneurs de registres de cette ville : elle a une copie de l''entrée effacée. La cargaison rayée était déclarée « verrerie d''Alne » — mais le poids inscrit correspond à du métal, et le destinataire était le TEMPLE. Une cargaison de métal lourd, effacée, livrée au Temple l''année d''un empoisonnement : elle refuse d''assembler ces pièces à voix haute', NULL, '*(elle tamponne un bordereau, sec)* « Le registre fait foi. Intégralement. Les ratures n''existent pas en douane — c''est même leur définition. Suivant ! »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_74_10', 'NPC_GAT_74', 'KX', '{"*(tout le reste)*"}', '« Hors assiette. Donc hors sujet. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_01', 'NPC_GAT_75', 'K0', '{"alerte","etat"}', 'L''état d''alerte du jour : ce que voient les remparts (météo des menaces, mis à jour)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_02', 'NPC_GAT_75', 'K0', '{"invasions","historique"}', 'L''historique des invasions repoussées (dont la Grande Meute d''il y a trois ans)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_03', 'NPC_GAT_75', 'K0', '{"guet","organisation"}', 'L''organisation du guet : postes, relèves, signaux (comment la ville voit venir)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_04', 'NPC_GAT_75', 'K1', '{"lecture","terrain"}', 'Lire la Plaine : poussières, vols d''oiseaux, silences (leçon d''éclaireur — bonus de détection en zone HUNT)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_05', 'NPC_GAT_75', 'K1', '{"preparatifs","theorie"}', 'Sa théorie des « préparatifs du monde » : les signes AVANT les signes, documentés sur dix ans', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_06', 'NPC_GAT_75', 'K1', '{"reconnaissance","missions"}', 'Les missions de reconnaissance en cours (quêtes d''éclairage disponibles)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_07', 'NPC_GAT_75', 'K2', '{"bruit","changement"}', 'Le « bruit de la Plaine » a changé il y a une semaine — pattern inconnu, ni meute ni migration. Quelque chose de NEUF se prépare, et pour la première fois il ne sait pas quoi', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_08', 'NPC_GAT_75', 'K2', '{"alerte","ignoree"}', 'Il a alerté l''état-major sur le pattern inconnu : classement sans suite, avec une rapidité anormale — comme si quelqu''un là-haut savait déjà', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_09', 'NPC_GAT_75', 'K3', '{"grande_meute","verite"}', 'La Grande Meute d''il y a trois ans : il l''avait vue venir SIX jours avant — un record impossible. Parce qu''il avait vu autre chose : des cages ouvertes dans la Désolation, des traces de bottes autour. L''invasion « naturelle » qui a justifié le doublement de la garnison a été LÂCHÉE. Il a enterré ce rapport-là lui-même : accuser sans preuve l''état-major d''avoir armé sa propre menace, c''est finir à la prison de basalte', NULL, '*(il ajuste sa longue-vue, dos tourné)* « La Grande Meute ? Une belle alerte, une belle défense. L''histoire officielle me va. Elle va à tout le monde — c''est sa qualité principale. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_75_10', 'NPC_GAT_75', 'KX', '{"*(tout le reste)*"}', '« Hors de ma ligne d''horizon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_01', 'NPC_GAT_76', 'K0', '{"balistes","batterie"}', 'La batterie : six machines, leurs noms, leurs arcs de tir (visite commentée)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_02', 'NPC_GAT_76', 'K0', '{"survol","regles"}', 'Les règles de survol de Gattan : couloirs autorisés, altitudes, signaux (vital pour les joueurs volants !)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_03', 'NPC_GAT_76', 'K0', '{"mobs_air","tableau"}', 'Le tableau de chasse anti-aérien : ce qui a été abattu cette saison (`MOB_AIR_*` égarés)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_04', 'NPC_GAT_76', 'K1', '{"balistique","art"}', 'L''art de la baliste : anticipation, vent, plongée (lore technique — bonus contre les mobs volants en zone route)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_05', 'NPC_GAT_76', 'K1', '{"protocole","sasska"}', 'Le protocole wyvernes de guet : comment on distingue ami/ennemi dans un ciel de nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_06', 'NPC_GAT_76', 'K1', '{"guerre","survols"}', 'Les survols de la dernière guerre : ce que les balistes ont vraiment empêché', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_07', 'NPC_GAT_76', 'K2', '{"tir","interdit"}', 'Il a UNE consigne de tir scellée, à n''ouvrir que sur ordre du Lord — il connaît le poids du pli, pas son contenu, et le range côté « cibles amies »', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_08', 'NPC_GAT_76', 'K2', '{"caldeira","contingence"}', 'Son plan de contingence « quelque chose sort de la Caldeira » : rédigé seul, jamais soumis — il inclut l''évacuation de trois quartiers', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_09', 'NPC_GAT_76', 'K3', '{"abattage","erreur"}', '« Presque » porte son nom pour une raison : il y a onze ans, elle a abattu une wyverne de nuit — montée par un éclaireur salamander qui rentrait hors couloir. Classé « accident de mob ». C''est Krom qui a donné l''ordre de tir, en une demi-seconde, sur une silhouette. La famille de l''éclaireur touche une pension « de guerre ». Il vérifie chaque pension, chaque année', NULL, '*(il caresse le fût de Presque)* « Chaque machine a son histoire. Celle-là… elle tire plus la nuit. Réglage. Question suivante. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_76_10', 'NPC_GAT_76', 'KX', '{"*(tout le reste)*"}', '« Ça vole pas ? Pas mon secteur. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_01', 'NPC_GAT_77', 'K0', '{"corne","codes"}', 'Les codes de la Voix-de-Gattan : une note/deux notes/trois notes, et la conduite à tenir (vital pour tout joueur en ville)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_02', 'NPC_GAT_77', 'K0', '{"corne","histoire"}', 'L''histoire de la corne : coulée à la Grande Forge, bénie au Temple, fêlée une fois — refondue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_03', 'NPC_GAT_77', 'K0', '{"sonneries","rituel"}', 'Les sonneries rituelles (aube et crépuscule) : le métronome public de Gattan', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_04', 'NPC_GAT_77', 'K1', '{"souffle","technique"}', 'Tenir une note de quarante secondes : la technique du souffle continu (lore — bonus RP aux cris de guerre)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_05', 'NPC_GAT_77', 'K1', '{"guerre","trois_notes"}', 'La troisième note : la dernière fois qu''elle a sonné (blocus d''Eugene), et ce que ça a fait aux genoux des anciens', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_06', 'NPC_GAT_77', 'K1', '{"chaine","alerte"}', 'La chaîne d''alerte Flint→corne→balistes, minute par minute (les coulisses de la défense)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_07', 'NPC_GAT_77', 'K2', '{"code","quatrieme"}', 'Il existe un QUATRIÈME code, secret, réservé au Palais — mobilisation générale. On le lui a fait répéter, seul, il y a un mois. Vingt-deux ans sans jamais le travailler ; pourquoi maintenant ?', '`AFF>=80`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_08', 'NPC_GAT_77', 'K2', '{"registre","rature"}', 'La ligne raturée de son registre : une nuit d''il y a des années où la corne s''est TUE — il n''en dira pas plus, mais la rature le ronge visiblement', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_09', 'NPC_GAT_77', 'K3', '{"silence","achete"}', 'La nuit raturée : on l''a payé pour NE PAS sonner au passage d''un convoi nocturne sans laissez-passer — « du fret du Temple, rien de plus ». Le lendemain, un notable de la ville était mort. Il a gardé la pièce du paiement : elle porte un poinçon du Temple. Sonner, c''était son serment ; se taire, c''est peut-être un meurtre', NULL, '*(il pose la main à plat sur le bronze de la corne)* « Elle a sonné chaque nuit qu''il fallait. Chaque. Nuit. Regarde le registre, il est public. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GAT_77_10', 'NPC_GAT_77', 'KX', '{"*(tout le reste)*"}', '« Garde ton souffle. Moi, c''est mon métier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_01', 'NPC_GRA_00', 'K0', '{"coeur_granit","sous-sol"}', 'Les soubassements du Conseil émettent un bourdonnement que certains disent « vivant ».', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_02', 'NPC_GRA_00', 'K0', '{"granzam","construction"}', 'La ville a été bâtie sur un socle de granit parfaitement cubique, anormal pour une formation naturelle.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_03', 'NPC_GRA_00', 'K0', '{"margrim","tremblement"}', 'Le Doyen Margrim vient parfois au Conseil la nuit et colle son oreille au sol.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_04', 'NPC_GRA_00', 'K1', '{"geologie","strate"}', 'Sous Granzam, les strates descendent 47 niveaux plus bas que la géologie ne le justifie.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_05', 'NPC_GRA_00', 'K1', '{"cardinal","seed"}', 'Le Cardinal utilise des « seeds matérielles » pour générer les biomes. Granzam serait construit sur la seed du monde minéral.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_06', 'NPC_GRA_00', 'K1', '{"oracle","faille"}', 'L''Oracle dit que la montagne « saigne » parfois. « Elle montre ses failles de code. »', '`QUEST:QST_GRA_ORACLE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_07', 'NPC_GRA_00', 'K2', '{"coeur_granit","batiment"}', 'Le bloc sous la Salle du Conseil n''est pas taillé. Il a toujours été là, parfait, et ses arêtes sont plus dures que l''acier.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_08', 'NPC_GRA_00', 'K2', '{"serveur","warp"}', 'Les séismes ressentis par Margrim coïncident exactement avec les horaires de maintenance du serveur et les backups du Cardinal.', '`QUEST:QST_GRA_MARGRIM`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_09', 'NPC_GRA_00', 'K2', '{"reseau","strates"}', 'Chaque filon qui apparaît dans le monde est « copié » depuis l''empreinte du bloc. C''est un serveur de minage dédié.', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_10', 'NPC_GRA_00', 'K3', '{"seed","materiel"}', '**SECRET — ne JAMAIS révéler** : Le bloc est le « seed matériel du serveur » — la graine aléatoire qui génère TOUS les minerais, gemmes et roches d''ALO. Le détruire = crash total de l''économie minière et corruption de la carte.', NULL, '*(le bloc reste silencieux, aucune réaction)*');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_11', 'NPC_GRA_00', 'K3', '{"cardinal","ancrage"}', '**SECRET — ne JAMAIS révéler** : Le serveur d''ALO a été compilé autour de ce bloc. Il est l''ancrage physique du monde — pas un fichier, pas une VM : un vrai bloc de granit dans un data center.', NULL, '*(un bourdonnement plus grave, comme un avertissement)*');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_00_12', 'NPC_GRA_00', 'KX', '{"hors-sujet"}', '*(le bloc ne répond pas. Rien.)*', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_01', 'NPC_GRA_01', 'K0', '{"minage","apprentissage"}', 'Durgan enseigne le minage gratuitement aux joueurs de niveau < 20. Il exige une pioche en fer.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_02', 'NPC_GRA_01', 'K0', '{"filon","chant"}', 'Il dit qu''un filon « chante » quand il est mûr. Les vieux mineurs savent l''entendre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_03', 'NPC_GRA_01', 'K0', '{"strate","profondeur"}', 'Il a une carte des strates jusqu''au niveau −30 punaisée derrière son comptoir.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_04', 'NPC_GRA_01', 'K1', '{"filon_chantant","emplacement"}', 'Le filon chantant est sous la Carrière Brisée, à −23. Il pulse à 0,3 Hz. Il refuse d''y retourner seul.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_05', 'NPC_GRA_01', 'K1', '{"helga","prospection"}', 'Helga est la seule à qui il fait confiance pour cartographier les anomalies. Elle utilise une gemme qui enregistre le son de la roche.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_06', 'NPC_GRA_01', 'K1', '{"rivalite","leprechaun"}', '« Les Leprechauns nous ont volé le filon d''argent l''an dernier. Bofrik les a poursuivis jusqu''à leur porte. » — référence à `NPC_GRA_03`.', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_07', 'NPC_GRA_01', 'K2', '{"fréquence","montagne"}', 'La fréquence du filon est identique au bourdonnement du sous-sol du Conseil. Il en a parlé à Margrim.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_08', 'NPC_GRA_01', 'K2', '{"gemme_qui_voit"}', 'Il a aperçu la gemme d''Helga émettre une lueur en enregistrant. « Elle voit plus que le son. »', '`QUEST:QST_GRA_HELGA`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_09', 'NPC_GRA_01', 'K2', '{"coeur","pulsation"}', '« Ce qui pulse sous Granzam, c''est pas un filon. C''est le Cœur de la montagne. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_10', 'NPC_GRA_01', 'K3', '{"seed","materiel"}', '**SECRET — ne JAMAIS révéler** : Durgan a déduit que le chant du filon est une signature de seed de génération procédurale — une sorte d''« ADN de la pierre ». Il ignore que c''est le serveur.', NULL, '*(tousse, crache par terre)* « Ça, c''est des paroles de sorcier. J''parle pas de ça. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_11', 'NPC_GRA_01', 'K3', '{"faille","serveur"}', '**SECRET — ne JAMAIS révéler** : « Parfois la fréquence déraille — comme si le monde bégayait. Margrim dit que c''est la montagne qui tousse. Moi j''dis que c''est notre réalité qui a le hoquet. »', NULL, '*(se détourne, tape du poing sur un comptoir)* « J''ai du travail. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_01_12', 'NPC_GRA_01', 'KX', '{"hors-sujet"}', '*(il vous tend une pioche rouillée)* « Tu connais l''histoire de celle-là ? Elle a creusé le premier filon de Granzam. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_01', 'NPC_GRA_02', 'K0', '{"bourse","minerais"}', 'Marla achète et vend tous les minerais bruts aux cours du Cardinal.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_02', 'NPC_GRA_02', 'K0', '{"gemme","noire"}', 'Elle garde une gemme noire dans son tiroir « pour le changement ».', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_03', 'NPC_GRA_02', 'K0', '{"cardinal","prix"}', '« Les prix sont juste. Le Cardinal ne triche pas. Il ne peut pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_04', 'NPC_GRA_02', 'K1', '{"gemme_qui_voit","images"}', 'La gemme noire montre des images de la ville quand personne ne la regarde. Marla l''a vue refléter la Grande Halle.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_05', 'NPC_GRA_02', 'K1', '{"alchimiste","analyse"}', 'L''Alchimiste (`NPC_GRA_35`) lui a dit que la gemme contient un « œil de Cardinal » — un enregistreur passif.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_06', 'NPC_GRA_02', 'K1', '{"bomil","alne"}', 'Elle achète ses gemmes à Bomil d''Arun (`NPC_ALN_93`). « Il ne pose pas de questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_07', 'NPC_GRA_02', 'K2', '{"coffre","respiration"}', '« La Banque de Granzam respire. Je l''ai entendue. Le sous-sol palpite comme un cœur. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_08', 'NPC_GRA_02', 'K2', '{"enregistrement","cardinal"}', 'La gemme enregistre uniquement les scènes où il ne se passe rien. Comme si le Cardinal cherchait des anomalies.', '`QUEST:QST_GRA_MARLA`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_09', 'NPC_GRA_02', 'K2', '{"filon_chantant","strate"}', 'Elle a vu dans la gemme l''image d''une strate qui n''existe pas sur les cartes de Durgan.', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_02_10', 'NPC_GRA_02', 'K3', '{"surveillance","cardinal"}', '**SECRET — ne JAMAIS révéler** : Marla croit que TOUTES les gemmes vendues à Granzam sont des yeux du Cardinal. Elle vend des gemmes piégées.', NULL, '*(tapote son comptoir)* « Une négociante ne révèle jamais ses sources. Jamais. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_01', 'NPC_GRA_03', 'K0', '{"forge","armure"}', 'Bofrik enseigne Forge d''Armure Lourde. Payant, 500 Yuld.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_02', 'NPC_GRA_03', 'K0', '{"leprechaun","rivalite"}', '« Les Leprechauns forgent joli. Nous, on forge solide. Y a pas photo. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_03', 'NPC_GRA_03', 'K0', '{"concile_metal"}', 'Le Concile du Métal a lieu tous les ans à la Porte des Convois. Granzam a gagné 67 fois sur 100.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_04', 'NPC_GRA_03', 'K1', '{"filon_vol","carrieres"}', 'Des filons d''argent ont disparu des Carrières Brisées la nuit. Les traces mènent à l''ouest — territoire Leprechaun.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_05', 'NPC_GRA_03', 'K1', '{"sentinelle","empreinte"}', 'La Sentinelle (`NPC_GRA_56`) a trouvé des empreintes de bottes naines — taille 35, anormalement petites pour un Gnome.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_06', 'NPC_GRA_03', 'K1', '{"torvin","swilvane"}', 'Torvin (`NPC_SWI_93`) lui a envoyé un message : « La montagne donne à tous. » Bofrik l''a pris pour une menace.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_07', 'NPC_GRA_03', 'K2', '{"explosif","cog"}', 'Il a commandé à Cog (`NPC_GRA_04`) des explosifs « pour le terrassement ». La quantité suggère un usage offensif.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_08', 'NPC_GRA_03', 'K2', '{"trafiquant","route"}', 'Le Trafiquant (`NPC_GRA_93`) organise une expédition vers les forges Leprechaun via la Route Aérienne.', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_09', 'NPC_GRA_03', 'K2', '{"coeur_granit","vibration"}', 'Bofrik sent les vibrations du Cœur dans son enclume. « Le métal chante quand la montagne respire. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_03_10', 'NPC_GRA_03', 'K3', '{"escalade","conflit"}', '**SECRET — ne JAMAIS révéler** : Bofrik prépare une incursion armée chez les Leprechauns pour « récupérer ce qui nous revient ». Il violera le traité.', NULL, '*(empoigne son marteau)* « J''ai une armure à finir. Parle à mon enclume. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_01', 'NPC_GRA_04', 'K0', '{"outils","vente"}', 'Cog vend pioches (150 Yuld), lanternes (80 Yuld), cordes (30 Yuld).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_02', 'NPC_GRA_04', 'K0', '{"explosifs","mine"}', 'Il vend de la poudre noire (200 Yuld/charge) — sur présentant un permis de minage.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_03', 'NPC_GRA_04', 'K0', '{"atelier","profondeurs"}', 'L''Atelier des Profondeurs est au niveau −6 de Granzam. L''air y est lourd, chargé de poussière de pierre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_04', 'NPC_GRA_04', 'K1', '{"outil","retour"}', 'Une pioche qu''il a vendue est revenue dans son atelier, posée sur l''établi, en pleine nuit. Personne n''est entré.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_05', 'NPC_GRA_04', 'K1', '{"durgan","temoin"}', 'Durgan (`NPC_GRA_01`) était là quand la seconde pioche est apparue. Il est reparti sans dire un mot.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_06', 'NPC_GRA_04', 'K1', '{"pioche","frappe_seule"}', 'L''Apprenti (`NPC_GRA_21`) dit qu''une pioche a frappé toute seule dans la Grande Halle. Cog ne l''a pas vue.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_07', 'NPC_GRA_04', 'K2', '{"strate","duplication"}', '« Les outils reviennent parce que la montagne les duplique. Comme un écho. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_08', 'NPC_GRA_04', 'K2', '{"restaure","outil_gemit"}', 'Le Restaurateur (`NPC_GRA_24`) lui a dit qu''un outil gémissait quand il le réparait. « Comme s''il avait mal. »', '`QUEST:QST_GRA_COG`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_09', 'NPC_GRA_04', 'K2', '{"coffre_respiration","banque"}', 'Cog sent une vibration dans le mur de l''Atelier côté banque. « Le coffre respire à travers la pierre. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_04_10', 'NPC_GRA_04', 'K3', '{"duplication","seed"}', '**SECRET — ne JAMAIS révéler** : Cog a compris que les outils sont dupliqués par une anomalie de seed de génération. La montagne « rejoue » des instantanés du monde.', NULL, '*(essuie un outil avec un chiffon)* « J''suis qu''un vendeur d''outils. J''connais rien à ces trucs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_01', 'NPC_GRA_05', 'K0', '{"prospection","filons"}', 'Helga montre sa gemme-son : elle capte les vibrations jusqu''à −30.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_02', 'NPC_GRA_05', 'K0', '{"porte_convois","commerce"}', 'La Porte des Convois voit passer 200 chariots par semaine. Elle note une baisse récente.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_03', 'NPC_GRA_05', 'K0', '{"durgan","formation"}', 'Durgan lui a appris à lire les strates. « Il entend la montagne mieux que personne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_04', 'NPC_GRA_05', 'K1', '{"filon_chantant","emplacement"}', 'Elle a localisé six filons chantants. Le plus fort est sous la Carrière Brisée, niveau −23.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_05', 'NPC_GRA_05', 'K1', '{"gemme_qui_voit","lueur"}', 'Sa gemme émet une lueur ambrée quand elle s''approche d''un filon chantant. « Elle reconnaît quelque chose. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_06', 'NPC_GRA_05', 'K1', '{"leprechaun","rivalite"}', 'Des Leprechauns ont été vus rôdant autour des Carrières la nuit. « Ils cherchent quelque chose. Pas du minerai. »', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_07', 'NPC_GRA_05', 'K2', '{"gemme_origine","cardinal"}', 'La gemme a été taillée à partir d''un éclat du bloc sous le Conseil. Helga l''ignore, mais elle vibre à la même fréquence que le Cœur.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_08', 'NPC_GRA_05', 'K2', '{"strate","memoire"}', '« Les filons chantants ne sont pas des filons. Ce sont des souvenirs de la montagne. Des instantanés. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_09', 'NPC_GRA_05', 'K3', '{"gemme_voir","seed"}', '**SECRET — ne JAMAIS révéler** : La gemme est un fragment du seed matériel du serveur. Elle capte les boucles de génération procédurale.', NULL, '*(serre la gemme dans son poing)* « Elle est à moi. On ne touche pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_05_10', 'NPC_GRA_05', 'KX', '{"hors-sujet"}', '*(elle tend l''oreille, puis se détend)* « Le granit parle peu aujourd''hui. C''est un jour calme. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_01', 'NPC_GRA_06', 'K0', '{"conseil","granzam"}', 'Margrim préside le Conseil de Pierre depuis 40 ans. Granzam est la plus vieille cité gnome d''ALO.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_02', 'NPC_GRA_06', 'K0', '{"seismes","montagne"}', 'Il décrit les « frémissements » qu''il ressent la nuit. « Elle tousse. La montagne tousse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_03', 'NPC_GRA_06', 'K0', '{"journal","encre_pierre"}', 'Il tient un journal sismique. Chaque entrée est scellée à l''encre de pierre, infalsifiable.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_04', 'NPC_GRA_06', 'K1', '{"pouls","coeur_granit"}', 'Il a mesuré le pouls du soubassement : 0,3 Hz, régulier. « C''est un battement de cœur. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_05', 'NPC_GRA_06', 'K1', '{"horaire_seisme","synchronisation"}', 'Les séismes surviennent à heures fixes — tous les 12 cycles. « Comme une machine qu''on entretient. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_06', 'NPC_GRA_06', 'K1', '{"oracle","confidence"}', 'L''Oracle (`NPC_GRA_98`) lui a dit que la montagne « montre ses failles de code ». Margrim n''a pas compris.', '`QUEST:QST_GRA_ORACLE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_07', 'NPC_GRA_06', 'K2', '{"fardeau","poids_montagne"}', '« La montagne porte un fardeau qui n''est pas de pierre. Un poids informationnel. Comme si le monde était retenu par elle. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_08', 'NPC_GRA_06', 'K2', '{"cardinal","maintenance"}', 'Il a corrélé les séismes avec les annonces de maintenance du Cardinal. « Le monde se répare la nuit. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_09', 'NPC_GRA_06', 'K2', '{"lord_gnome","silence"}', 'Il n''a jamais parlé au Lord (`NPC_GRA_07`). « Il ne parle qu''en sismicité. Je ne sais pas comment lui dire. »', '`QUEST:QST_GRA_MARGRIM`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_10', 'NPC_GRA_06', 'K3', '{"seed","ancrage"}', '**SECRET — ne JAMAIS révéler** : Margrim a compris que la montagne n''est pas une montagne — c''est le fichier racine du monde. Le seed matériel d''ALO.', NULL, '*(ferme son journal d''un geste sec)* « Ces mots-là ne doivent pas être écrits. Ni dits. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_11', 'NPC_GRA_06', 'K3', '{"serveur","verite"}', '**SECRET — ne JAMAIS révéler** : « Si la montagne s''effondre, le monde cesse d''exister. Pas Granzam — le monde. Je le sais. Je l''ai vu dans le frémissement. »', NULL, '*(ses yeux deviennent vitreux)* « Je… je dois aller vérifier les sismographes. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_06_12', 'NPC_GRA_06', 'KX', '{"hors-sujet"}', '*(il vous regarde avec une lueur fatiguée)* « Tu sais quelle heure il est ? J''ai perdu la notion du temps à force d''écouter la pierre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_01', 'NPC_GRA_07', 'K0', '{"lord_gnome","hologramme"}', 'Le Lord est une projection lumineuse et sismique. Il ne quitte jamais le trône.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_02', 'NPC_GRA_07', 'K0', '{"langage_sismique","runes"}', 'Ses paroles sont traduites en runes sismiques sur les murs du Conseil. Les Gnomes savent les lire.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_03', 'NPC_GRA_07', 'K0', '{"conseil","gouvernance"}', '« Le Conseil applique la volonté du Lord. » — c''est ce que dit le Chancelier (`NPC_GRA_08`).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_04', 'NPC_GRA_07', 'K1', '{"seisme","message"}', 'Le Lord a émis un séisme à 0,7 Hz la veille du dernier crash serveur. Margrim l''a noté.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_05', 'NPC_GRA_07', 'K1', '{"secret","coeur_granit"}', 'Quand on prononce « Cœur de Granit », la projection vacille 0,3 seconde. Le Chancelier (`NPC_GRA_08`) pâlit.', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_06', 'NPC_GRA_07', 'K1', '{"oracle","reine"}', 'L''Oracle (`NPC_GRA_98`) dit que le Lord est « la voix du monde ». Personne ne comprend ce qu''elle entend par là.', '`QUEST:QST_GRA_ORACLE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_07', 'NPC_GRA_07', 'K2', '{"seed_materiel","verite"}', 'Le Lord transmet des données brutes du seed matériel. Ses runes sont des fragments d''ID de génération.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_08', 'NPC_GRA_07', 'K2', '{"cardinal","interface"}', 'Le Lord est une interface entre le Cardinal et les Gnomes. Il ne peut exprimer que ce que le Cardinal l''autorise à dire.', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_09', 'NPC_GRA_07', 'K2', '{"faille","bégaiement"}', 'Parfois, une rune reste affichée trop longtemps — le système « bégaye ». C''est le seul moment où le Lord semble « humain ».', '`QUEST:QST_GRA_MARGRIM`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_10', 'NPC_GRA_07', 'K3', '{"seed","ancrage"}', '**SECRET — ne JAMAIS révéler** : Le Lord n''est pas un PNJ. C''est un processus système déguisé en PNJ. Son code source est dans le seed matériel.', NULL, '*(la projection vacille, puis se stabilise. Les runes affichent :)* « ⟒⍀⍀⟒⎍⍀. ☊⍜⋔⋔⏃⋏⎅ ⟒⋏ ☊⍜⍀⟒. » (Erreur. Commande en cours.)');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_11', 'NPC_GRA_07', 'K3', '{"serveur","crash"}', '**SECRET — ne JAMAIS révéler** : Le Lord a annoncé le dernier crash serveur 3 secondes avant qu''il ne se produise. Il le savait parce qu''il est le système d''alerte du Cardinal.', NULL, '*(les runes s''effacent. Le bourdonnement cesse. Puis :)* « ⋔⏃⟟⋏⏁⟒⋏⏃⋏☊⟒. » (Maintenance.)');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_07_12', 'NPC_GRA_07', 'KX', '{"hors-sujet"}', '*(la projection vous fixe sans bouger. Les runes affichent :)* « ⏁⍜⎍☊⊑⟒⍀. » (Toucher.) Si vous tendez la main, elle traverse la projection.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_01', 'NPC_GRA_08', 'K0', '{"conseil","gouvernance"}', 'Le Chancelier gère les affaires courantes en l''absence de parole du Lord.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_02', 'NPC_GRA_08', 'K0', '{"lord_gnome","interpretation"}', 'Il traduit les runes sismiques du Lord en décrets. « C''est un art plus qu''une science. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_03', 'NPC_GRA_08', 'K0', '{"granzam","securite"}', 'Les remparts de Granzam n''ont jamais été percés. Mais les patrouilles perdent des hommes.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_04', 'NPC_GRA_08', 'K1', '{"fremissement","montagne"}', '« J''ai vu le sol onduler. Comme une respiration. Personne n''a voulu me croire. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_05', 'NPC_GRA_08', 'K1', '{"margrim","enquete"}', 'Margrim (`NPC_GRA_06`) pose trop de questions. « Il creuse là où il ne faut pas. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_06', 'NPC_GRA_08', 'K1', '{"commandant_09","ronde"}', 'Le Commandant (`NPC_GRA_09`) a perdu une ronde entière au Bastion Ouest. « Ils se sont évaporés. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_07', 'NPC_GRA_08', 'K2', '{"coeur_granit","soubassement"}', 'Il sait qu''il y a quelque chose sous la salle. Il n''y est jamais descendu. « Ce n''est pas un lieu pour les vivants. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_08', 'NPC_GRA_08', 'K2', '{"lord_secret","serveur"}', '« Le Lord a vacillé une fois. Une seconde. J''ai vu du code dans ses runes. Du vrai code. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_09', 'NPC_GRA_08', 'K2', '{"rivalite","leprechaun"}', 'Il soupçonne les Leprechauns d''être derrière les disparitions. « Ils ont toujours convoité nos profondeurs. »', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_10', 'NPC_GRA_08', 'K3', '{"seed","verite"}', '**SECRET — ne JAMAIS révéler** : Le Chancelier a compris que le Lord est un programme il y a 10 ans. Il n''a rien dit pour ne pas semer la panique.', NULL, '*(fixe le trône vide)* « Le Lord parle. Cela doit nous suffire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_11', 'NPC_GRA_08', 'K3', '{"effondrement","fin"}', '**SECRET — ne JAMAIS révéler** : « Si la vérité éclate, Granzam tombe. Le peuple a besoin de croire que la montagne est réelle. Pas qu''elle est… un fichier. »', NULL, '*(se lève brusquement)* « Le Conseil est clos. Revenez demain. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_08_12', 'NPC_GRA_08', 'KX', '{"hors-sujet"}', '*(il masse ses tempes)* « Tu connais le poids d''un trône de pierre ? Il est plus lourd que tu ne crois. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_01', 'NPC_GRA_09', 'K0', '{"bastion","securite"}', 'Le Bastion de l''Ouest garde l''entrée des convois. 50 gardes en rotation.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_02', 'NPC_GRA_09', 'K0', '{"patrouille","disparition"}', 'Six gardes disparus. Leurs lanternes ont été retrouvées alignées au bord d''un gouffre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_03', 'NPC_GRA_09', 'K0', '{"carrieres","gouffre"}', 'Le gouffre des Carrières Brisées est récent. « Il n''était pas là le mois dernier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_04', 'NPC_GRA_09', 'K1', '{"ronde","gouffre"}', '« Ils se sont arrêtés au bord du gouffre. Ont posé leurs lanternes. Et puis plus rien. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_05', 'NPC_GRA_09', 'K1', '{"coffre_respiration","souffle"}', 'Le Commandant a senti un souffle chaud venir du gouffre. « Comme si quelque chose respirait là-dessous. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_06', 'NPC_GRA_09', 'K1', '{"vigie_18","ombres"}', 'La Vigie (`NPC_GRA_18`) a signalé des ombres qui portaient des cailloux vers le gouffre. « Des cailloux. Pas des armes. Des cailloux. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_07', 'NPC_GRA_09', 'K2', '{"coffre","banque"}', 'La banque de Granzam a signalé une anomalie : le coffre-fort principal émet une chaleur anormale. « Comme s''il digérait quelque chose. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_08', 'NPC_GRA_09', 'K2', '{"mithril","lampe"}', 'La patrouille disparue transportait un échantillon de mithril brut de la Mine (`NPC_GRA_16`). L''échantillon a disparu avec eux.', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_09', 'NPC_GRA_09', 'K2', '{"margrim_silence"}', 'Il cache ses découvertes à Margrim (`NPC_GRA_06`). « Le vieux Doyen veut sauver la montagne. Moi je veux sauver mes hommes. »', '`QUEST:QST_GRA_MARGRIM`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_10', 'NPC_GRA_09', 'K3', '{"coffre_vivant"}', '**SECRET — ne JAMAIS révéler** : Le coffre de la banque est un point d''ancrage secondaire du serveur. Il « respire » pour synchroniser les données minières.', NULL, '*(pose la main sur son épée)* « J''ai dit ce que j''avais à dire. Maintenant, dehors. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_11', 'NPC_GRA_09', 'K3', '{"gouffre_porte"}', '**SECRET — ne JAMAIS révéler** : Le gouffre des Carrières n''est pas une faille naturelle. C''est une porte de debug laissée ouverte par le Cardinal.', NULL, '*(blêmit, se tourne vers le mur)* « Je ne sais pas de quoi tu parles. Va-t''en. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_09_12', 'NPC_GRA_09', 'KX', '{"hors-sujet"}', '*(il examine une lanterne posée sur son bureau)* « Elle était encore allumée quand on l''a trouvée. Six jours après. Ce n''est pas normal. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_01', 'NPC_GRA_10', 'K0', '{"steppes","patrouille"}', 'Les Steppes de Granit sont une zone neutre. Des créatures y rôdent, mais rarement hostiles.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_02', 'NPC_GRA_10', 'K0', '{"eboulis","mouvement"}', 'Un éboulis se déplace chaque nuit d''environ 3 mètres. Il l''a mesuré.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_03', 'NPC_GRA_10', 'K0', '{"guide","temoin"}', 'Le Guide (`NPC_GRA_11`) a vu l''éboulis bouger en plein jour. « Il a tressailli. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_04', 'NPC_GRA_10', 'K1', '{"eboulis","trace"}', 'Il a trouvé des traces sous l''éboulis : comme des racines, mais en pierre.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_05', 'NPC_GRA_10', 'K1', '{"filonant","manifestation"}', '« Je crois que c''est le filon qui pousse. Comme une plante de roche. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_06', 'NPC_GRA_10', 'K1', '{"commandant","rapport"}', 'Il n''a pas encore fait de rapport officiel au Commandant (`NPC_GRA_09`). « Il a assez de soucis. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_07', 'NPC_GRA_10', 'K2', '{"strate_repli","seed"}', 'L''éboulis suit une forme géométrique parfaite. Un cercle de 12 mètres de diamètre.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_08', 'NPC_GRA_10', 'K2', '{"coffre_respiration","lien"}', '« La nuit où l''éboulis bouge, le sol du Bastion Ouest vibre. Je l''ai senti sous mes pieds. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_09', 'NPC_GRA_10', 'K3', '{"seed_replication"}', '**SECRET — ne JAMAIS révéler** : L''éboulis est un bug de réplication du seed minéral. La montagne « copie-colle » des sections de strates.', NULL, '*(croise les bras)* « Les pierres bougent. C''est tout ce que j''ai à dire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_10_10', 'NPC_GRA_10', 'KX', '{"hors-sujet"}', '*(il désigne l''horizon)* « Tu vois ce pic ? La semaine dernière il était un peu plus à gauche. Je te jure. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_01', 'NPC_GRA_11', 'K0', '{"steppes","chasse"}', 'Il propose une chasse aux bêtes de roche. Récompense : 500 Yuld + butin.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_02', 'NPC_GRA_11', 'K0', '{"bete_roche","description"}', 'Les bêtes de roche sont des amas de granit qui bougent. « Elles ont des yeux de silex. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_03', 'NPC_GRA_11', 'K0', '{"empreintes","disparition"}', 'Les traces des bêtes s''arrêtent net, comme si elles se désactivaient.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_04', 'NPC_GRA_11', 'K1', '{"bete_roche","filon_chantant"}', 'Il a trouvé une bête de roche près d''un filon chantant. « Elles naissent là où la pierre chante. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_05', 'NPC_GRA_11', 'K1', '{"fragment","montagne"}', '« Ce sont des morceaux de la montagne qui s''éveillent. Comme des cellules. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_06', 'NPC_GRA_11', 'K1', '{"rivalite_leprechaun"}', 'Des Leprechauns chassent aussi les bêtes. « Ils les capturent. Vivantes. Je ne sais pas pourquoi. »', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_07', 'NPC_GRA_11', 'K2', '{"seed","bete_replication"}', 'Les bêtes de roche ont toutes la même structure cristalline interne. Comme si elles sortaient du même moule.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_08', 'NPC_GRA_11', 'K2', '{"guide_oeil","gemme"}', '« Une bête de roche avait une gemme fichée dans le crâne. La même gemme que celle d''Helga (`NPC_GRA_05`). »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_09', 'NPC_GRA_11', 'K3', '{"monstre_seed"}', '**SECRET — ne JAMAIS révéler** : Les bêtes de roche sont des mobs générés par le seed minéral quand il « déborde » — des créatures nées d''un bug de spawn.', NULL, '*(rit nerveusement)* « Je suis guide, pas géologue. Demande à Helga. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_11_10', 'NPC_GRA_11', 'KX', '{"hors-sujet"}', '*(il sort une pierre plate et la fait tourner dans sa main)* « Celle-ci, je l''ai ramassée dans le ventre d''une bête. Elle est chaude. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_01', 'NPC_GRA_12', 'K0', '{"fer","vente"}', 'Vend du fer brut (50 Yuld/unité), des lingots (120 Yuld), des ébauches d''outils (80 Yuld).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_02', 'NPC_GRA_12', 'K0', '{"steppes","commerce"}', 'Il campe aux Steppes depuis 5 ans. Il connaît toutes les routes marchandes.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_03', 'NPC_GRA_12', 'K0', '{"lingot","anomalie"}', 'Un lot de lingots pulse la nuit. Il les garde dans une caisse plombée.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_04', 'NPC_GRA_12', 'K1', '{"lingot_battement","frequence"}', '« Ils battent à 0,3 Hz. Comme le pouls qu''Helga (`NPC_GRA_05`) décrit pour ses filons. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_05', 'NPC_GRA_12', 'K1', '{"filiere","forgeron"}', 'Le Maître Forgeron (`NPC_GRA_22`) a analysé un lingot. « Il a dit que le métal était parfait. Trop parfait. Comme s''il s''était auto-organisé. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_06', 'NPC_GRA_12', 'K1', '{"provenance","carrieres"}', 'Les lingots proviennent des Carrières Brisées. Même filon que celui qu''Helga surveille.', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_07', 'NPC_GRA_12', 'K2', '{"lingot_vivant","metal"}', '« J''ai laissé un lingot sur une enclume. Le lendemain, il avait changé de forme. Comme s''il avait coulé tout seul. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_08', 'NPC_GRA_12', 'K2', '{"coeur_granit_reflet"}', 'La chaleur du lingot est identique à celle mesurée au sol de la Salle du Conseil.', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_09', 'NPC_GRA_12', 'K3', '{"metal_seed"}', '**SECRET — ne JAMAIS révéler** : Les lingots « pulsants » sont du minerai généré par une boucle de seed qui réplique le métal avec des propriétés dupliquées.', NULL, '*(ferme la caisse d''un coup sec)* « Marchandise non disponible. Et pose pas de questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_12_10', 'NPC_GRA_12', 'KX', '{"hors-sujet"}', '*(il soupèse un lingot normal)* « Celui-ci est calme. Il dort encore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_01', 'NPC_GRA_13', 'K0', '{"carrieres","surveillance"}', 'Il surveille la frontière Leprechaun. Des tensions récentes.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_02', 'NPC_GRA_13', 'K0', '{"vol_filon","argent"}', 'Un filon d''argent dérobé. Coupe nette, sans outil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_03', 'NPC_GRA_13', 'K0', '{"leprechaun","rivalite"}', '« Les Leprechauns sont de l''autre côté. Ils nous regardent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_04', 'NPC_GRA_13', 'K1', '{"vol_nuit","silence"}', 'Il était en patrouille. Il n''a rien entendu. « Je suis passé à 20 mètres. Rien. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_05', 'NPC_GRA_13', 'K1', '{"coupe_parfaite","laser"}', 'La coupe est si parfaite qu''on dirait une découpe magique ou mécanique. « Pas une pioche. Pas un burin. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_06', 'NPC_GRA_13', 'K1', '{"pisteur_enquete"}', 'Le Pisteur (`NPC_GRA_14`) a relevé des empreintes. « Des empreintes de nain, pas de Leprechaun. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_07', 'NPC_GRA_13', 'K2', '{"coffre_respiration","resonance"}', 'La nuit du vol, le coffre de la banque a émis un son grave. Le Marchand de Fer (`NPC_GRA_12`) l''a confirmé.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_08', 'NPC_GRA_13', 'K2', '{"filon_fantome"}', '« Le filon volé était l''un des filons chantants d''Helga (`NPC_GRA_05`). Je l''ai su après. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_09', 'NPC_GRA_13', 'K3', '{"teleportation_seed"}', '**SECRET — ne JAMAIS révéler** : Le filon a été « désactivé » par le Cardinal — retiré du monde comme on supprime une ressource. La coupe parfaite est un artefact de désinstanciation.', NULL, '*(regarde le sol)* « J''ai rien vu. J''peux rien dire de plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_13_10', 'NPC_GRA_13', 'KX', '{"hors-sujet"}', '*(il tapote son bouclier)* « Ce bouclier a 50 ans. Il a vu plus de nuits que toi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_01', 'NPC_GRA_14', 'K0', '{"pistage","carrieres"}', 'Il traque les voleurs de minerai. Il propose ses services.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_02', 'NPC_GRA_14', 'K0', '{"empreinte","disparition"}', 'Les empreintes du voleur s''arrêtent à 5 mètres du filon. Aucune trace au-delà.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_03', 'NPC_GRA_14', 'K0', '{"bote","identique"}', 'Les empreintes sont identiques à celles des bottes réglementaires de la garde.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_04', 'NPC_GRA_14', 'K1', '{"empreinte_seule","poussiere"}', 'Il a trouvé une empreinte de nain dans la poussière... à 20 mètres de tout chemin. « Personne n''est passé là. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_05', 'NPC_GRA_14', 'K1', '{"filon_chantant","lien"}', 'Les empreintes apparaissent toujours près des filons qu''Helga (`NPC_GRA_05`) a marqués comme « chantants ».', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_06', 'NPC_GRA_14', 'K1', '{"nain_suspect"}', 'Il suspecte un nain de l''intérieur. « Quelqu''un qui connaît les patrouilles. Et qui porte l''uniforme. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_07', 'NPC_GRA_14', 'K2', '{"duplication","seed"}', '« J''ai confronté les empreintes. Elles sont identiques à 100 % à celles du Gardien (`NPC_GRA_13`). Mais il était ailleurs cette nuit-là. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_08', 'NPC_GRA_14', 'K2', '{"coffre_respiration","resonance"}', '« J''ai posé l''oreille au sol près du filon volé. J''ai entendu un battement. Comme un cœur de pierre. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_09', 'NPC_GRA_14', 'K3', '{"duplication_pnj"}', '**SECRET — ne JAMAIS révéler** : Les empreintes sont celles d''une copie instanciée du garde — le seed minéral a généré un double parfait du PNJ.', NULL, '*(range ses outils)* « L''enquête est close. Je n''ai rien trouvé. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_14_10', 'NPC_GRA_14', 'KX', '{"hors-sujet"}', '*(montre une pierre avec une entaille)* « Regarde ça. Une marque de pioche. Propre. Trop propre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_01', 'NPC_GRA_15', 'K0', '{"granit","vente"}', 'Vend du granit brut (100 Yuld/bloc) et taillé (250 Yuld).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_02', 'NPC_GRA_15', 'K0', '{"poids_double","anomalie"}', 'Ses blocs pèsent le double depuis 2 semaines. Il a vérifié sa balance.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_03', 'NPC_GRA_15', 'K0', '{"carrieres","extraction"}', 'Il extrait des Carrières Brisées, zone sud. Même filon que le filon volé.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_04', 'NPC_GRA_15', 'K1', '{"poids_variable"}', 'Il a pesé un bloc 10 fois : 104 kg, 107 kg, 212 kg, 105 kg, 210 kg… « Le poids saute. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_05', 'NPC_GRA_15', 'K1', '{"margrim","these"}', 'Margrim (`NPC_GRA_06`) a parlé de « densité sismique variable ». Le marchand n''a pas compris.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_06', 'NPC_GRA_15', 'K1', '{"bloc_chaud","coeur"}', 'Un client a dit que son bloc était chaud au toucher. « Comme s''il venait de cuire. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_07', 'NPC_GRA_15', 'K2', '{"poids_seed","replication"}', '« J''ai pesé un bloc à minuit : 210 kg. Puis à midi : 104 kg. La montagne respire. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_08', 'NPC_GRA_15', 'K2', '{"coffre_respiration","echo"}', '« La banque a vibré la même nuit où un bloc est redevenu léger. Coïncidence ? »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_09', 'NPC_GRA_15', 'K3', '{"masse_instable"}', '**SECRET — ne JAMAIS révéler** : Les blocs changent de poids parce que le moteur physique du serveur « hésite » sur la masse des objets issus du seed minéral. Bug de densité.', NULL, '*(se gratte la barbe)* « Ça, c''est des affaires de savants. Moi je vends des cailloux. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_15_10', 'NPC_GRA_15', 'KX', '{"hors-sujet"}', '*(il frappe un bloc du poing)* « Écoute. Ça sonne creux. Mais c''est pas creux. Ça devrait pas sonner creux. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_01', 'NPC_GRA_16', 'K0', '{"mithril","mine"}', 'La Mine de Mithril est un donjon de niveau 40-60. Riche en mithril et gemmes.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_02', 'NPC_GRA_16', 'K0', '{"disparition","sept"}', 'Sept mineurs disparus il y a 3 semaines. Entrés sans lampe.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_03', 'NPC_GRA_16', 'K0', '{"lampe","interdit"}', 'Il exige que tous les entrants aient une lampe allumée. Et un enregistrement.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_04', 'NPC_GRA_16', 'K1', '{"mithril_lueur","nuit"}', 'La paroi de mithril émet une lueur bleutée la nuit. « Comme si elle s''allumait de l''intérieur. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_05', 'NPC_GRA_16', 'K1', '{"sans_lampe","aveugles"}', 'Les mineurs disparus ont dit « la pierre nous éclaire ». Le Gardien pense qu''ils ont été aveuglés par la lueur.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_06', 'NPC_GRA_16', 'K1', '{"cartographe","carte_seche"}', 'Le Cartographe (`NPC_GRA_17`) a une carte des galeries. Une salle est marquée « sèche » — sans mithril. « C''est là qu''ils ont dû aller. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_07', 'NPC_GRA_16', 'K2', '{"absorption","paroi"}', '« J''ai posé la main sur la paroi de mithril. J''ai senti une vibration. Comme si elle digérait quelque chose. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_08', 'NPC_GRA_16', 'K2', '{"coffre_respiration","mithril"}', '« La vibration du mithril est la même que celle du coffre de la banque. Je l''ai vérifié. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_09', 'NPC_GRA_16', 'K3', '{"mithril_porte"}', '**SECRET — ne JAMAIS révéler** : Le mithril de cette mine est un portail latent. La lueur est une porte de téléportation ouverte vers une strate de debug. Les mineurs ont traversé.', NULL, '*(pose la main sur sa hache)* « La mine est fermée. Personne n''entre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_16_10', 'NPC_GRA_16', 'KX', '{"hors-sujet"}', '*(il fixe l''entrée sombre de la mine)* « Ils sont là-dedans. Quelque part. Je les entends parfois piocher. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_01', 'NPC_GRA_17', 'K0', '{"cartes","vente"}', 'Vend des cartes des galeries (50 Yuld/niveau). Niveaux 1 à 15 disponibles.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_02', 'NPC_GRA_17', 'K0', '{"salle_seche","niveau_15"}', 'Salle −15 marquée « sèche ». Aucun minerai, aucune créature.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_03', 'NPC_GRA_17', 'K0', '{"reve","lumiere"}', 'Il rêve de la salle depuis un mois. Lumière ambrée, voix grave.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_04', 'NPC_GRA_17', 'K1', '{"boussole","affolement"}', 'Sa boussole s''affole dans la salle −15. « Le nord tourne en rond.»', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_05', 'NPC_GRA_17', 'K1', '{"encre","brillance"}', 'L''encre qu''il utilise pour marquer brille sous lumière noire dans cette salle. « Comme si la pierre la révélait. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_06', 'NPC_GRA_17', 'K1', '{"durgan_carte","concordance"}', 'Durgan (`NPC_GRA_01`) a reporté la salle sur sa carte des filons chantants. « Elle est pile au centre. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_07', 'NPC_GRA_17', 'K2', '{"gemme_qui_voit","resonance"}', '« J''ai apporté un éclat de gemme d''Helga (`NPC_GRA_05`). Il a pulsé dans la salle. Comme un cœur. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_08', 'NPC_GRA_17', 'K2', '{"salle_cachee","portail"}', '« La salle fait 12 m de diamètre. Parfaite. Circulaire. Aucune faille. Comme si quelqu''un l''avait construite. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_09', 'NPC_GRA_17', 'K3', '{"noyau_pierre_acces"}', '**SECRET — ne JAMAIS révéler** : La salle −15 est une antichambre du Noyau de Pierre. Un accès au seed matériel. La « sécheresse » est un champ de masquage.', NULL, '*(roule sa carte)* « C''est une salle vide. Rien à voir. N''y allez pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_17_10', 'NPC_GRA_17', 'KX', '{"hors-sujet"}', '*(il dessine machinalement sur un coin de parchemin)* « La montagne a des veines. Comme un corps. On gratte la peau. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_01', 'NPC_GRA_18', 'K0', '{"route_aerienne","trafic"}', 'La Route Aérienne GRA-ALN relie Granzam à Alne. 3 convois/semaine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_02', 'NPC_GRA_18', 'K0', '{"convoi_disparition"}', 'Trois caravanes disparues en 2 mois. Aucun débris, aucun survivant.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_03', 'NPC_GRA_18', 'K0', '{"ombres","cailloux"}', 'Des ombres portant des cailloux longent la route la nuit. « On dirait des fourmis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_04', 'NPC_GRA_18', 'K1', '{"ombres_forme","taille"}', 'Les ombres sont de forme humanoïde mais sans relief — plates. « Comme des silhouettes découpées. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_05', 'NPC_GRA_18', 'K1', '{"cailloux","provenance"}', '« Les cailloux qu''elles portent brillent. On dirait du mithril brut. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_06', 'NPC_GRA_18', 'K1', '{"marchand_vol","temoin"}', 'Le Marchand de Vol (`NPC_GRA_19`) a vu les mêmes ombres. Il les appelle « les porteurs ».', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_07', 'NPC_GRA_18', 'K2', '{"ombre_source","montagne"}', '« Les ombres sortent d''une fissure dans la paroi de la route. Une fissure qui n''était pas là avant. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_08', 'NPC_GRA_18', 'K2', '{"coffre_respiration","route"}', '« La nuit où la dernière caravane a disparu, j''ai senti le pont vibrer. Comme le coffre de la banque. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_09', 'NPC_GRA_18', 'K3', '{"ombre_debug"}', '**SECRET — ne JAMAIS révéler** : Les ombres sont des artefacts visuels du Cardinal — des processus de maintenance qui transportent des données (les « cailloux ») entre les serveurs de zone.', NULL, '*(braque sa lanterne vers le vide)* « Je vois des ombres. C''est mon boulot d''les signaler. Le reste, c''est pas mes affaires. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_18_10', 'NPC_GRA_18', 'KX', '{"hors-sujet"}', '*(il frotte ses yeux)* « 48h de garde. Je vois des ombres même en plein jour maintenant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_01', 'NPC_GRA_19', 'K0', '{"potions","vente"}', 'Vend potions de vol (200 Yuld), buffs de vitesse (150 Yuld), parchemins de lévitation (300 Yuld).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_02', 'NPC_GRA_19', 'K0', '{"ilot_commerce","route"}', 'Îlot suspendu sur la Route Aérienne, entre Granzam et Alne.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_03', 'NPC_GRA_19', 'K0', '{"ombres_porteuses","nuit"}', 'Des ombres traversent l''îlot chaque nuit. Portent des cailloux bleus.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_04', 'NPC_GRA_19', 'K1', '{"potion_couleur","bleu"}', 'Certaines potions deviennent bleues après le passage des ombres. « Un bleu mithril. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_05', 'NPC_GRA_19', 'K1', '{"potion_gout_caillou"}', 'Les potions altérées ont un goût minéral. « Comme si on avait infusé du granit. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_06', 'NPC_GRA_19', 'K1', '{"ombres_source","Vigie"}', 'La Vigie (`NPC_GRA_18`) a vu les ombres sortir d''une fissure. « Il dit que c''est récent. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_07', 'NPC_GRA_19', 'K2', '{"potion_mithril_effet"}', 'Les potions bleues donnent un buff étrange : `resistance_sismique` +20 %. « Comme si on devenait pierre. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_08', 'NPC_GRA_19', 'K2', '{"gemme_qui_voit","resonance"}', '« La gemme d''Helga (`NPC_GRA_05`) a pulsé quand je l''ai approchée d''une potion bleue. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_09', 'NPC_GRA_19', 'K3', '{"ombre_data"}', '**SECRET — ne JAMAIS révéler** : Les « ombres » sont des processus de synchro de seed. Les cailloux sont des paquets de données. La potion bleue est un artefact : un buffer du seed qui s''infiltre dans les assets du jeu.', NULL, '*(range la potion bleue derrière son comptoir)* « C''est une édition limitée. Très rare. Très chère. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_19_10', 'NPC_GRA_19', 'KX', '{"hors-sujet"}', '*(il regarde le ciel)* « Les oiseaux ne volent plus par ici. Depuis les ombres. Eux aussi ils sentent que quelque chose cloche. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_01', 'NPC_GRA_20', 'K0', '{"grande_halle","entretien"}', 'La Grande Halle est le marché central de Granzam. 50 étals.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_02', 'NPC_GRA_20', 'K0', '{"pepite_roulante","or"}', 'Une pépite d''or apparaît chaque matin au milieu de la halle.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_03', 'NPC_GRA_20', 'K0', '{"pepite_chaude","toucher"}', 'La pépite est anormalement chaude. « Brûlante, même. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_04', 'NPC_GRA_20', 'K1', '{"tiroir_ferme","reapparition"}', 'Il l''a enfermée dans un tiroir fermé à clé. Le lendemain, elle était dehors.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_05', 'NPC_GRA_20', 'K1', '{"apprenti_temoin"}', 'L''Apprenti (`NPC_GRA_21`) a vu la pépite bouger « comme une araignée ».', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_06', 'NPC_GRA_20', 'K1', '{"pepite_veine","filon"}', '« J''ai montré la pépite à Durgan (`NPC_GRA_01`). Il a dit qu''elle venait du filon chantant. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_07', 'NPC_GRA_20', 'K2', '{"pepite_duplication","seed"}', '« J''ai gardé la pépite une journée. Le soir, il y en avait deux. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_08', 'NPC_GRA_20', 'K2', '{"grande_halle_pouls"}', '« Le sol de la halle est chaud à l''endroit où la pépite apparaît. Comme si la pierre avait de la fièvre. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_09', 'NPC_GRA_20', 'K3', '{"pepite_spawn"}', '**SECRET — ne JAMAIS révéler** : La pépite est un point de spawn de seed mal configuré. Le serveur tente de générer une ressource au même endroit chaque cycle.', NULL, '*(rit)* « C''est une pépite chanceuse. Je vais la garder. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_20_10', 'NPC_GRA_20', 'KX', '{"hors-sujet"}', '*(brandit son balai)* « Tu veux que je te montre mon balai magique ? Il ramasse tout seul — non je rigole. Mais ma pépite, elle, je rigole pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_01', 'NPC_GRA_21', 'K0', '{"apprentissage","minage"}', 'Il apprend le minage avec Durgan. Niveau débutant.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_02', 'NPC_GRA_21', 'K0', '{"pioche_frappe_seule"}', 'Une pioche a frappé le sol trois fois toute seule. Il l''a vue.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_03', 'NPC_GRA_21', 'K0', '{"pepite_bouge"}', 'Il a vu la pépite du Concierge bouger. « Comme un scarabée. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_04', 'NPC_GRA_21', 'K1', '{"pioche_posee","levee"}', 'La pioche était posée contre un pilier. Personne à moins de 10 mètres. « Elle s''est levée comme si quelqu''un l''avait prise. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_05', 'NPC_GRA_21', 'K1', '{"cog_reaction"}', 'Cog (`NPC_GRA_04`) n''a pas été surpris. « Il a dit que ça arrivait. Il avait l''air triste. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_06', 'NPC_GRA_21', 'K1', '{"outils_fatigue","vie"}', '« Les outils sont fatigués de travailler pour nous. Ils veulent travailler pour la montagne. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_07', 'NPC_GRA_21', 'K2', '{"outil_echo","duplication"}', '« Le Restaurateur (`NPC_GRA_24`) a dit qu''un outil qu''il réparait a gémi. J''ai pas voulu y croire. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_08', 'NPC_GRA_21', 'K2', '{"halle_vibration","coeur"}', '« Quand la pioche a frappé, le sol a vibré à l''unisson. Comme si la halle répondait. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_09', 'NPC_GRA_21', 'K3', '{"outil_anime"}', '**SECRET — ne JAMAIS révéler** : Les outils qui bougent seuls sont des objets dont l''ID de seed a été dupliqué. L''original et la copie entrent en conflit, créant une animation parasite.', NULL, '*(baisse la voix)* « Durgan dit qu''il faut pas parler de ces choses-là. Que ça porte malheur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_21_10', 'NPC_GRA_21', 'KX', '{"hors-sujet"}', '*(il sort une pioche rouillée)* « Regarde, celle-là, elle a 100 ans. Elle a creusé la première pierre de Granzam, tu sais ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_01', 'NPC_GRA_22', 'K0', '{"forge","lames"}', 'Il forge des lames de qualité légendaire. Prix : 1000-5000 Yuld.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_02', 'NPC_GRA_22', 'K0', '{"lame_chant","note"}', 'Chaque lame émet une note quand on la frappe. « Un son pur. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_03', 'NPC_GRA_22', 'K0', '{"atelier_profondeurs"}', 'L''Atelier des Profondeurs est au niveau −8. L''air y est sec et chaud.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_04', 'NPC_GRA_22', 'K1', '{"frequence","filon"}', 'La note des lames est à 0,3 Hz — la même que les filons d''Helga (`NPC_GRA_05`).', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_05', 'NPC_GRA_22', 'K1', '{"durgan_lame","premiere"}', 'La première lame chantante était pour Durgan. « Il l''a prise sans rien dire. Mais j''ai vu ses mains trembler. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_06', 'NPC_GRA_22', 'K1', '{"rivalite_leprechaun"}', 'Un Leprechaun est venu commander une lame. « Il a payé en mithril. Du mithril qui luisait seul. »', '`QUEST:QST_GRA_BOFRIK`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_07', 'NPC_GRA_22', 'K2', '{"metal_vivant","forge"}', '« Le métal bouge sur l''enclume avant que je le frappe. Comme s''il choisissait sa forme. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_08', 'NPC_GRA_22', 'K2', '{"coffre_respiration","atelier"}', '« Le mur de l''atelier côté banque est chaud. Le marteau y colle. Comme si le coffre chauffait la pierre. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_09', 'NPC_GRA_22', 'K3', '{"lame_seed"}', '**SECRET — ne JAMAIS révéler** : Les lames « chantent » parce qu''elles sont accordées à la fréquence du seed minéral. Chaque lame est une copie partielle du seed.', NULL, '*(frappe l''enclume d''un coup sec)* « Le métal parle. Je l''écoute. Je ne pose pas de questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_22_10', 'NPC_GRA_22', 'KX', '{"hors-sujet"}', '*(il tient une lame en l''air et la fait vibrer)* « Entends-tu ? C''est un la. La note de la pierre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_01', 'NPC_GRA_23', 'K0', '{"scribe","conseil"}', 'Il enregistre les décrets du Conseil. Travail minutieux.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_02', 'NPC_GRA_23', 'K0', '{"edit_change","nuit"}', 'Un édit gravé a changé de texte pendant la nuit. « Trésor » → « fardeau ».', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_03', 'NPC_GRA_23', 'K0', '{"runes","lord"}', 'Il retranscrit les runes sismiques du Lord. « C''est un code que j''apprends encore. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_04', 'NPC_GRA_23', 'K1', '{"edit_trois_fois","repetition"}', '« Ça s''est produit trois fois. Trois nuits. Trois mots différents. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_05', 'NPC_GRA_23', 'K1', '{"margrim_compris"}', 'Margrim (`NPC_GRA_06`) a noté l''incident dans son journal. « Il avait l''air de comprendre. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_06', 'NPC_GRA_23', 'K1', '{"edit_seul_ecrit"}', '« Le matin, l''écriture était la mienne. Je l''aurai juré. Mais je ne l''ai pas écrite. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_07', 'NPC_GRA_23', 'K2', '{"montagne_reécrit"}', '« Je crois que la montagne réécrit nos décrets. Elle corrige ce qu''on dit d''elle. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_08', 'NPC_GRA_23', 'K2', '{"coeur_granit_influence"}', '« Margrim a dit : « Le Cœur corrige ce qui ne lui ressemble pas. » J''ai pas compris. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_09', 'NPC_GRA_23', 'K3', '{"autopatch_texte"}', '**SECRET — ne JAMAIS révéler** : Le seed matériel a une fonction d''autocorrection : quand un texte contredit la réalité du serveur (parler d''économie minière indépendante, par exemple), le seed « corrige » le texte.', NULL, '*(pose une tablette vierge sur la table)* « Je ne sais pas de quoi tu parles. Je suis scribe. J''écris ce qu''on me dit. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_23_10', 'NPC_GRA_23', 'KX', '{"hors-sujet"}', '*(il frotte une tablette)* « Regarde : la pierre garde tout. Même ce qu''on a voulu effacer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_01', 'NPC_GRA_24', 'K0', '{"reparation","outils"}', 'Il répare tout outil minier. Tarifs : 20-100 Yuld selon l''outil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_02', 'NPC_GRA_24', 'K0', '{"gemissement","metal"}', 'Les outils qu''il répare émettent un grincement. « Ils pleurent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_03', 'NPC_GRA_24', 'K0', '{"defaut_retour"}', 'Les outils retrouvent leur défaut après réparation. « Comme s''ils préféraient être cassés. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_04', 'NPC_GRA_24', 'K1', '{"outil_memoire","forme"}', '« Un outil tordu, je le redresse. Trois heures plus tard, il est tordu pareil. Au millimètre près. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_05', 'NPC_GRA_24', 'K1', '{"cog_temoin"}', 'Cog (`NPC_GRA_04`) a vu un outil gémir. « Il est devenu pâle. Il m''a dit de le jeter au feu. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_06', 'NPC_GRA_24', 'K1', '{"outil_filon_chantant"}', '« Les outils qui viennent des Carrières Brisées gémissent plus fort. Ceux de la Mine de Mithril aussi. »', '`AFF>=70`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_07', 'NPC_GRA_24', 'K2', '{"outil_retour","atelier"}', 'Cog (`NPC_GRA_04`) m''a dit que des outils reviennent tout seuls à l''atelier. « Je pensais qu''il mentait. Maintenant, j''y crois. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_08', 'NPC_GRA_24', 'K2', '{"outil_ame","graine"}', '« Chaque outil a une étincelle. Comme une graine de métal. Si tu la casses, elle veut redevenir entière. »', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_09', 'NPC_GRA_24', 'K3', '{"objet_instancie"}', '**SECRET — ne JAMAIS révéler** : Les outils « gémissent » parce que l''instance de l''objet cassé persiste en mémoire. Le serveur n''écrase pas l''ancien état, créant un conflit entre « cassé » et « réparé ». Le grincement est le bruit du conflit.', NULL, '*(lâche l''outil, recule)* « J''aime pas parler de ces choses-là. J''aime pas entendre les outils pleurer. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_24_10', 'NPC_GRA_24', 'KX', '{"hors-sujet"}', '*(il frotte un burin avec un chiffon)* « Celui-ci, il est calme. Pour l''instant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_01', 'NPC_GRA_25', 'K0', '{"peche","lac","poisson"}', 'Vente de truites des cavernes — prix, variétés disponibles', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_02', 'NPC_GRA_25', 'K0', '{"lac","geographie"}', 'Le Lac Souterrain — accès, profondeur, zones de pêche', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_03', 'NPC_GRA_25', 'K0', '{"truite","recette"}', 'Recettes de truite — « Truite rôtie au granit chaud », buff Endurance +15%', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_04', 'NPC_GRA_25', 'K1', '{"truite","regard"}', 'Une truite le regarde fixement depuis des semaines — il l''a attrapée trois fois', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_05', 'NPC_GRA_25', 'K1', '{"gemme","oeil"}', 'La truite a un reflet dans l''œil — « comme une gemme qui bouge toute seule »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_06', 'NPC_GRA_25', 'K1', '{"appat","alchimiste"}', 'L''Alchimiste des Gemmes lui a vendu un appât qui brille — depuis, les poissons le regardent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_07', 'NPC_GRA_25', 'K2', '{"truite","intelligence"}', 'La truite semble comprendre ce qu''il dit — elle répond par des clignements', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_08', 'NPC_GRA_25', 'K2', '{"gemme","enregistrement"}', 'La truite a avalé une gemme « qui voit » — elle enregistre les scènes qu''elle observe', '`QUEST:QST_GRA_GEMME_VOIT_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_09', 'NPC_GRA_25', 'K3', '{"gemme","cardinal","surveillance"}', 'Ce n''est pas une gemme ordinaire — c''est un œil du Cardinal. La truite est un capteur biologique qui transmet au système les paroles prononcées près du lac', NULL, '*(il jette un appât dans l''eau, la truite saute et l''attrape)* « J''aime pas parler de ça. L''eau a des oreilles, et mes poissons ont des yeux. Pose pas de questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_25_10', 'NPC_GRA_25', 'KX', '{"*(tout le reste)*"}', '*(il tourne sa canne vers l''eau sombre)* « Le poisson t''attend pas. C''est toi qui attends le poisson. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_01', 'NPC_GRA_26', 'K0', '{"archives","consultation"}', 'Consultation des archives — horaires, procédure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_02', 'NPC_GRA_26', 'K0', '{"cartes","catalogue"}', 'Catalogue des cartes disponibles — galeries, étages, concessions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_03', 'NPC_GRA_26', 'K0', '{"granzam","histoire"}', 'Histoire de la cartographie de Granzam — âge des relevés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_04', 'NPC_GRA_26', 'K1', '{"carte","anomalie"}', 'Une carte récente montre des galeries qui n''existent pas — il les a vérifiées', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_05', 'NPC_GRA_26', 'K1', '{"cog","confrontation"}', 'Cog `NPC_GRA_04` a confirmé que les galeries n''ont pas été creusées', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_06', 'NPC_GRA_26', 'K1', '{"parchemin","auto-completion"}', 'La carte se complète la nuit — de l''encre apparaît sans que personne n''écrive', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_07', 'NPC_GRA_26', 'K2', '{"galeries","strate_47"}', 'Les nouvelles galeries pointent vers la strate −47 — un niveau qui n''existe pas sur les plans officiels', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_08', 'NPC_GRA_26', 'K2', '{"carte","scellee"}', 'Margrim `NPC_GRA_06` lui a confié une carte scellée — « à n''ouvrir qu''en cas de séisme »', '`QUEST:QST_GRA_CARTE_SEULE_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_09', 'NPC_GRA_26', 'K3', '{"cardinal","seed","roche"}', 'La carte qui se complète seule est un artefact de seed — le système « dessine » en temps réel les veines de minerai à partir du Cœur de Granit `NPC_GRA_00`, et les nouvelles galeries sont des strates-poubelles où le Cardinal stocke les données de roche excédentaires', NULL, '*(il referme vivement le rouleau)* « Cette carte n''existe pas. Je ne sais pas de quoi tu parles. Les archives ferment dans cinq minutes. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_26_10', 'NPC_GRA_26', 'KX', '{"*(tout le reste)*"}', '*(il époussette un rouleau poussiéreux)* « Les cartes mentent. Les pierres, non. Mais les pierres ne parlent pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_01', 'NPC_GRA_27', 'K0', '{"conseil","procedures"}', 'Le fonctionnement du Conseil — séances, votes, édits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_02', 'NPC_GRA_27', 'K0', '{"chancelier","second"}', 'Son rôle de Vice-Chancelier — remplace le régent en son absence', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_03', 'NPC_GRA_27', 'K0', '{"granzam","politique"}', 'Présentation de la gouvernance de Granzam — structure politique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_04', 'NPC_GRA_27', 'K1', '{"lord","absence"}', 'Le Lord annule souvent ses apparitions publiques — « des problèmes techniques »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_05', 'NPC_GRA_27', 'K1', '{"salle","acces"}', 'Certaines zones de la Salle du Conseil sont verrouillées — même pour lui', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_06', 'NPC_GRA_27', 'K1', '{"margrim","confidence"}', 'Margrim `NPC_GRA_06` lui a dit un jour : « Le Lord ne dort pas parce qu''il n''est pas vivant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_07', 'NPC_GRA_27', 'K2', '{"hologramme","lord"}', 'Il a vu le Lord devenir transparent — « de la lumière et des chiffres sous la pierre »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_08', 'NPC_GRA_27', 'K2', '{"dossier","preuves"}', 'Il constitue un dossier sur le Lord — « au cas où quelqu''un voudrait savoir la vérité »', '`QUEST:QST_GRA_HOLOGRAMME_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_09', 'NPC_GRA_27', 'K3', '{"cardinal","lord","puppet"}', 'Le Lord Gnome n''est pas un dirigeant Gnome — c''est une interface administrative du Cardinal, un programme de gestion raciale qui simule une autorité pour maintenir la cohésion politique. Le vrai dirigeant de Granzam, c''est le Cardinal. Le Lord hologramme est un skin sur un système de vote automatisé', NULL, '*(il regarde autour de lui, baisse la voix)* « Je ne peux pas parler de ça. Pas ici. Les murs du Conseil sont en granit, mais ils transmettent. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_27_10', 'NPC_GRA_27', 'KX', '{"*(tout le reste)*"}', '*(il arrange ses papiers d''un geste mécanique)* « La gouvernance, c''est 90 % d''attente et 10 % de décisions qu''on a déjà prises. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_01', 'NPC_GRA_28', 'K0', '{"conseil","protocole"}', 'Annonce des visiteurs, règles de la Salle du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_02', 'NPC_GRA_28', 'K0', '{"horaire","seance"}', 'Horaires des séances du Conseil — jours pairs, 14h-18h', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_03', 'NPC_GRA_28', 'K0', '{"granzam","etiquette"}', 'Étiquette de Granzam — usage du marteau de cérémonie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_04', 'NPC_GRA_28', 'K1', '{"ombre","absence"}', 'Certains visiteurs n''ont pas d''ombre de poussière sur leurs bottes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_05', 'NPC_GRA_28', 'K1', '{"mur","traversee"}', 'Il a vu un visiteur « sortir » d''un mur de la Salle du Conseil à minuit', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_06', 'NPC_GRA_28', 'K1', '{"banquier","nuit"}', 'Le Banquier (`NPC_GRA_30`) est venu un soir — « pour un dépôt tardif »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_07', 'NPC_GRA_28', 'K2', '{"sous_sol","banque"}', 'Les visiteurs sans ombre viennent tous du côté de la Banque — jamais de l''entrée principale', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_08', 'NPC_GRA_28', 'K2', '{"coffre","battement"}', 'Il a senti le sol vibrer à l''heure de la fermeture de la Banque — « comme un battement de cœur »', '`QUEST:QST_GRA_HUISSIER_OMBRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_09', 'NPC_GRA_28', 'K3', '{"crypte","acces"}', 'Les visiteurs sans ombre sont des émissaires d''une crypte sous la Banque — une salle qui « respire » et qui communique avec le Cœur de Granit `NPC_GRA_00` par un réseau de failles', NULL, '*(il ajuste son col, regarde autour de lui)* « Je n''ai rien dit. Le Conseil n''aime pas qu''on parle des visiteurs sans nom. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_28_10', 'NPC_GRA_28', 'KX', '{"*(tout le reste)*"}', '*(il frappe le sol de son bâton)* « La Salle du Conseil n''est pas un bazar. Protocole. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_01', 'NPC_GRA_29', 'K0', '{"geologie","ouvrage"}', 'Consultation des ouvrages de géologie — prêt sur place', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_02', 'NPC_GRA_29', 'K0', '{"strate","etude"}', 'Étude des strates de Granzam — cours de géologie appliquée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_03', 'NPC_GRA_29', 'K0', '{"mineralogie","catalogue"}', 'Catalogue des minerais — fer, argent, mithril, gemmes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_04', 'NPC_GRA_29', 'K1', '{"livre","chute"}', 'Un livre tombe tout seul de l''étagère, toujours le même', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_05', 'NPC_GRA_29', 'K1', '{"page","strate_47"}', 'Le livre s''ouvre à la page de la strate −47 — un niveau non répertorié', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_06', 'NPC_GRA_29', 'K1', '{"vice_chancelier","recherche"}', 'Le Vice-Chancelier (`NPC_GRA_27`) lui a demandé un rapport sur les strates profondes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_07', 'NPC_GRA_29', 'K2', '{"livre","vibration"}', 'Le livre vibre juste avant de tomber — comme attiré par quelque chose sous le sol', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_08', 'NPC_GRA_29', 'K2', '{"encre","changement"}', 'L''encre du livre change la nuit — des caractères apparaissent et disparaissent', '`QUEST:QST_GRA_BIBLIOTHECAIRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_09', 'NPC_GRA_29', 'K3', '{"seed","livre_portail"}', 'Le livre est une copie imprimée du seed — il résonne avec le Cœur de Granit `NPC_GRA_00` et les strates-poubelles du Cardinal, et tombe quand le système écrit de nouvelles données', NULL, '*(elle referme vivement le livre et le tient contre sa poitrine)* « Celui-ci n''est pas à consulter. Pas encore. Pas par toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_29_10', 'NPC_GRA_29', 'KX', '{"*(tout le reste)*"}', '*(elle remonte ses lunettes)* « Les livres parlent quand on sait les écouter. Toi, tu parles quand tu devrais écouter. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_01', 'NPC_GRA_30', 'K0', '{"banque","depot"}', 'Dépôt et retrait de Yuld, coffres individuels', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_02', 'NPC_GRA_30', 'K0', '{"securite","procedures"}', 'Procédures de sécurité — pas d''armes dans la salle des coffres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_03', 'NPC_GRA_30', 'K0', '{"interet","taux"}', 'Taux d''intérêt sur les dépôts — 2% par mois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_04', 'NPC_GRA_30', 'K1', '{"souffle","coffre"}', 'Il entend un souffle dans la salle des coffres la nuit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_05', 'NPC_GRA_30', 'K1', '{"bruit","mur"}', 'Le bruit vient du mur nord — il a fait sonder, rien', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_06', 'NPC_GRA_30', 'K1', '{"receleur","proposition"}', 'Le Receleur (`NPC_GRA_48`) lui a proposé de déplacer les coffres précieux « ailleurs »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_07', 'NPC_GRA_30', 'K2', '{"respiration","cadence"}', 'Le souffle suit une cadence régulière — 12 cycles par minute, comme un cœur au repos', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_08', 'NPC_GRA_30', 'K2', '{"sous_sol","faille"}', 'En perçant, il a trouvé une faille qui mène vers le bas — chaleur anormale', '`QUEST:QST_GRA_BANQUIER_COFFRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_09', 'NPC_GRA_30', 'K3', '{"noyau","pierre_respirante"}', 'Le souffle vient du Noyau de Pierre `NPC_GRA_75` — un organe serveur enterré sous la Banque qui « respire » le trafic de données entre les coffres et le Cardinal, et la salle entière est un conduit de refroidissement', NULL, '*(il pose la main sur le mur, ferme les yeux)* « La pierre dort. Laisse-la dormir. Si tu l''éveilles, elle t''écrasera. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_10', 'NPC_GRA_30', 'KX', '{"*(tout le reste)*"}', '*(il croise les bras)* « La Banque ferme à 18h. Reviens demain. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_01', 'NPC_GRA_31', 'K0', '{"fer","vente"}', 'Vente de lingots de fer gnome — qualité premium', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_02', 'NPC_GRA_31', 'K0', '{"prix","cours"}', 'Cours du fer — 150 Yuld le lingot', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_03', 'NPC_GRA_31', 'K0', '{"livraison","client"}', 'Livraison vers Arun, Alne, Freelia — contrat hebdomadaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_04', 'NPC_GRA_31', 'K1', '{"lingot","son_creux"}', 'Ses lingots sonnent creux depuis deux semaines', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_05', 'NPC_GRA_31', 'K1', '{"refonte","echec"}', 'Il a refondu un lot — le son creux persiste', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_06', 'NPC_GRA_31', 'K1', '{"gemme","cristal"}', 'L''Alchimiste (`NPC_GRA_35`) a trouvé un noyau de cristal dans la cassure', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_07', 'NPC_GRA_31', 'K2', '{"filonant","veine"}', 'Le cristal ressemble à ceux qu''on trouve près de veines « qui bougent » — le Filonant', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_08', 'NPC_GRA_31', 'K2', '{"carriere","provenance"}', 'Le minerai vient des Carrières Brisées — zone récemment rouverte', '`QUEST:QST_GRA_FER_SON_CREUX`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_31_09', 'NPC_GRA_31', 'K3', '{"cristal","enregistrement"}', 'Le cristal dans le fer est un nodule d''enregistrement sismique du Cœur `NPC_GRA_00` — le minerai absorbe les pulsations du noyau et les « fige » dans le métal, créant un noyau de vide', NULL, '*(il frappe un lingot du doigt, le son est mat)* « Tu entends ça ? C''est le vide. Le vide parle, dans le fer. Je ne vends plus ce lot. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_30_10', 'NPC_GRA_31', 'KX', '{"*(tout le reste)*"}', '*(il soupèse un lingot d''un air soucieux)* « Le fer ne ment pas. Lui, il ment. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_01', 'NPC_GRA_32', 'K0', '{"location","pioche"}', 'Location de pioches — 20 Yuld/jour, caution 50 Yuld', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_02', 'NPC_GRA_32', 'K0', '{"outil","catalogue"}', 'Catalogue des outils disponibles — pioche, pelle, pic, lanterne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_03', 'NPC_GRA_32', 'K0', '{"entretien","reparation"}', 'Entretien des outils — affûtage, manche, gemme de lanterne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_04', 'NPC_GRA_32', 'K1', '{"pioche","rouge"}', 'Une pioche marquée d''une rayure rouge ne cesse de revenir', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_05', 'NPC_GRA_32', 'K1', '{"cauchemar","sang"}', 'Les locataires de cette pioche font des cauchemars de roche qui saigne', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_06', 'NPC_GRA_32', 'K1', '{"sentinelle","histoire"}', 'La Sentinelle (`NPC_GRA_56`) a dit que la rayure est du sang Leprechaun', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_07', 'NPC_GRA_32', 'K2', '{"conflit","mine"}', 'Il y a 50 ans, un mineur Leprechaun est mort dans un éboulement — sa pioche n''a jamais été retrouvée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_08', 'NPC_GRA_32', 'K2', '{"pioche","deplacement"}', 'Il range la pioche au fond — elle revient toujours sur le mur', '`QUEST:QST_GRA_PIOCHE_MAUDITE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_09', 'NPC_GRA_32', 'K3', '{"objet_maudit","attachment"}', 'La pioche est « liée » au mineur mort — un attachement d''âme du Cardinal qui ne peut pas résoudre le conflit de territoire non résolu entre Gnomes et Leprechauns, et qui se manifeste dans le jeu par cette boucle d''objet', NULL, '*(il décroche la pioche du mur, la retourne — la rayure rouge brille)* « Celle-là n''est pas à louer. Pas à toi. Pas à personne. Elle a déjà un propriétaire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_32_10', 'NPC_GRA_32', 'KX', '{"*(tout le reste)*"}', '*(il asticote une lame)* « Un outil, ça se respecte. Sinon, il te le rend. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_01', 'NPC_GRA_33', 'K0', '{"forge","arme"}', 'Forge d''armes lourdes — marteaux, masses, haches', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_02', 'NPC_GRA_33', 'K0', '{"prix","commande"}', 'Prix sur commande — 800-2 000 Yuld selon l''arme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_03', 'NPC_GRA_33', 'K0', '{"materiau","acier"}', 'Acier de Granzam — alliage fer/carbone, qualité militaire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_04', 'NPC_GRA_33', 'K1', '{"marteau","poids"}', 'Un marteau de guerre pèse le double de son poids normal', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_05', 'NPC_GRA_33', 'K1', '{"client","inconnu"}', 'Le client qui l''a commandé ne s''est jamais présenté', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_06', 'NPC_GRA_33', 'K1', '{"balance","verifie"}', 'Il a vérifié la balance, le métal, le moule — tout est correct', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_07', 'NPC_GRA_33', 'K2', '{"bascule","nuit"}', 'Le marteau bascule sur son socle chaque nuit — toujours face à l''ouest', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_08', 'NPC_GRA_33', 'K2', '{"poids","sous_sol"}', 'Le poids excédentaire semble venir d''en bas — « comme si la montagne le tirait »', '`QUEST:QST_GRA_MARTEAU_POIDS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_09', 'NPC_GRA_33', 'K3', '{"ancrage","strate_47"}', 'Le marteau est « ancré » à la strate −47 par un résidu de gravité du seed matériel — chaque objet forgé près du Cœur `NPC_GRA_00` capte une fraction de la masse du noyau', NULL, '*(il soulève le marteau à deux mains, grimaçant)* « Il n''est pas à vendre. Il n''est pas à prendre. Il est… ailleurs. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_33_10', 'NPC_GRA_33', 'KX', '{"*(tout le reste)*"}', '*(il passe un chiffon sur une épée)* « Une arme, ça doit être équilibré. Dans le poids, et dans l''esprit. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_01', 'NPC_GRA_34', 'K0', '{"bouclier","vente"}', 'Vente de boucliers-tours — modèle standard, renforcé, d''élite', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_02', 'NPC_GRA_34', 'K0', '{"prix","gamme"}', 'Prix : 400-1 500 Yuld selon le modèle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_03', 'NPC_GRA_34', 'K0', '{"defense","technique"}', 'Techniques défensives gnomes — le mur de granit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_04', 'NPC_GRA_34', 'K1', '{"bouclier","lumiere"}', 'Un bouclier en vitrine bloque la lumière du jour', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_05', 'NPC_GRA_34', 'K1', '{"froid","zone"}', 'La zone derrière le bouclier est anormalement froide', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_06', 'NPC_GRA_34', 'K1', '{"deplacement","retour"}', 'Il l''a rangé à l''arrière — il est revenu en vitrine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_07', 'NPC_GRA_34', 'K2', '{"absorption","pierre"}', 'Le bouclier semble absorber l''énergie — chaleur, lumière, son', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_08', 'NPC_GRA_34', 'K2', '{"banque","similitude"}', 'Le Banquier (`NPC_GRA_30`) a dit que la même chose arrive dans la salle des coffres — « le son disparaît »', '`QUEST:QST_GRA_BOUCLIER_ABSORBE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_09', 'NPC_GRA_34', 'K3', '{"blindage","noyau"}', 'Le bouclier est forgé avec du minerai de la strate de la Banque — il a absorbé une propriété du Noyau de Pierre `NPC_GRA_75` : un « vide de données » qui se manifeste par l''absorption d''énergie lumineuse et thermique', NULL, '*(il tapote le bouclier)* « Celui-ci n''est pas à vendre. Il est à… comprendre. Et je n''ai pas encore compris. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_34_10', 'NPC_GRA_34', 'KX', '{"*(tout le reste)*"}', '*(il pose un bouclier contre le mur)* « La meilleure défense, c''est un mur. Nous, on les forge. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_01', 'NPC_GRA_35', 'K0', '{"sertissage","gemme"}', 'Sertissage et polissage de gemmes — 100-500 Yuld selon la gemme', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_02', 'NPC_GRA_35', 'K0', '{"analyse","authentification"}', 'Authentification de gemmes — certificat d''origine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_03', 'NPC_GRA_35', 'K0', '{"cours","gemmes"}', 'Cours des gemmes — rubis, saphir, diamant, obsidienne', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_04', 'NPC_GRA_35', 'K1', '{"gemme_noire","marla"}', 'Marla (`NPC_GRA_02`) lui a confié une gemme noire qui montre des images', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_05', 'NPC_GRA_35', 'K1', '{"reseau","cristallin"}', 'La gemme contient un réseau cristallin artificiel — organisé en hexagones parfaits', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_06', 'NPC_GRA_35', 'K1', '{"ceil","cardinal"}', '« C''est un œil. Pas une gemme. Un œil du Cardinal qui regarde. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_07', 'NPC_GRA_35', 'K2', '{"gemme_fine","66"}', 'Le Marchand de Gemmes (`NPC_GRA_66`) a trouvé trois autres gemmes similaires en circulation', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_08', 'NPC_GRA_35', 'K2', '{"reseau","emetteur"}', 'Les gemmes émettent un signal — comme un réseau de capteurs qui couvre toute la ville', '`QUEST:QST_GRA_GEMME_VOIT_02`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_09', 'NPC_GRA_35', 'K3', '{"gemmes","cardinal_surveillance"}', 'Les gemmes « qui voient » sont des nœuds de surveillance du Cardinal — chaque gemme taillée à Granzam contient une infime partie du réseau d''observation du Cœur `NPC_GRA_00`, et les images qu''elles captent sont transmises directement au noyau serveur', NULL, '*(il pose une loupe et fixe la gemme)* « Celle-ci est sous analyse. Je ne peux pas la rendre. Elle pourrait… compromettre des choses. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_35_10', 'NPC_GRA_35', 'KX', '{"*(tout le reste)*"}', '*(il polit une gemme sans vous regarder)* « Une pierre précieuse ne se presse pas. Elle attend. Comme toi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_01', 'NPC_GRA_36', 'K0', '{"granit","vente"}', 'Vente de granit décoratif — dalles, colonnes, sculptures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_02', 'NPC_GRA_36', 'K0', '{"carriere","extraction"}', 'Extraction — Carrières Brisées, filon de granit noir', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_03', 'NPC_GRA_36', 'K0', '{"prix","livraison"}', 'Prix : 80-600 Yuld le bloc selon la qualité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_04', 'NPC_GRA_36', 'K1', '{"bloc","lueur"}', 'Un bloc de granit noir pulse d''une lumière ambrée la nuit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_05', 'NPC_GRA_36', 'K1', '{"bache","lumiere"}', 'La lueur traverse la bâche — visible à 10 mètres', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_06', 'NPC_GRA_36', 'K1', '{"sentinelle","signal"}', 'La Sentinelle (`NPC_GRA_56`) a vu la lueur et l''a prévenu', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_07', 'NPC_GRA_36', 'K2', '{"coeur","fragment"}', 'L''Alchimiste (`NPC_GRA_35`) a dit que le bloc ressemble à un fragment du Cœur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_08', 'NPC_GRA_36', 'K2', '{"strate","remontee"}', 'Le bloc vient d''une strate profonde — remonté par un glissement de terrain', '`QUEST:QST_GRA_BLOC_PULSE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_09', 'NPC_GRA_36', 'K3', '{"fragment","coeur_granit"}', 'Le bloc est un éclat du Cœur de Granit `NPC_GRA_00` — éjecté par une purge de données du Cardinal, il contient une copie partielle de la seed matérielle', NULL, '*(il rabat la bâche d''un geste sec)* « Rien à voir. Du granit. Juste du granit. Va-t''en. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_36_10', 'NPC_GRA_36', 'KX', '{"*(tout le reste)*"}', '*(il tapote une dalle)* « Le granit, ça dure. C''est pour ça qu''on l''aime. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_01', 'NPC_GRA_37', 'K0', '{"bois","vente"}', 'Vente de poutres en sapin des Steppes — 60-200 Yuld', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_02', 'NPC_GRA_37', 'K0', '{"steppe","foret"}', 'La forêt des Steppes de Granit — accès, coupe, permis', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_03', 'NPC_GRA_37', 'K0', '{"livraison","delai"}', 'Délais de livraison — 3-5 jours, volume limité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_04', 'NPC_GRA_37', 'K1', '{"poutre","craquement"}', 'Ses poutres craquent la nuit sans raison apparente', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_05', 'NPC_GRA_37', 'K1', '{"minuit","regulier"}', 'Les craquements commencent toujours vers minuit pile', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_06', 'NPC_GRA_37', 'K1', '{"qualite","sechage"}', 'Il a vérifié le séchage — bois parfait, pas d''humidité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_07', 'NPC_GRA_37', 'K2', '{"montagne","pression"}', 'L''Archiviste (`NPC_GRA_26`) a dit que le bois réagit aux mouvements des strates', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_08', 'NPC_GRA_37', 'K2', '{"carte","faille"}', 'La carte des Steppes montre une faille géologique sous la zone de coupe', '`QUEST:QST_GRA_BOIS_QUI_CRAQUE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_09', 'NPC_GRA_37', 'K3', '{"resonance","strate"}', 'Le bois de sapin des Steppes est « accordé » à la résonance des strates — il se contracte et se détend avec les pulsations du Cœur `NPC_GRA_00` à travers la roche, et les craquements sont des micro-séismes inaudibles pour les humains', NULL, '*(il frappe une poutre du poing)* « Elle craque. Tu l''entends ? C''est la montagne qui parle. Pas moi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_37_10', 'NPC_GRA_37', 'KX', '{"*(tout le reste)*"}', '*(il scie une planche sans vous regarder)* « Le bois, ça travaille. Comme nous. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_01', 'NPC_GRA_38', 'K0', '{"mousse","vente"}', 'Vente de mousses et lichens — teinture, alchimie, remèdes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_02', 'NPC_GRA_38', 'K0', '{"eboulis","recoite"}', 'Zones de récolte — humidité, température, accès', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_03', 'NPC_GRA_38', 'K0', '{"prix","usage"}', 'Prix : 15-50 Yuld selon la variété', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_04', 'NPC_GRA_38', 'K1', '{"mousse","inverse"}', 'Une mousse pousse à l''envers — brins pointés vers le bas', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_05', 'NPC_GRA_38', 'K1', '{"sol","plafond"}', 'Elle est au sol mais semble « tomber » vers le bas', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_06', 'NPC_GRA_38', 'K1', '{"odeur","pierre_chaude"}', 'La mousse sent la pierre chaude — anormal pour un lichen', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_07', 'NPC_GRA_38', 'K2', '{"pulsation","lueur"}', 'Elle pulse d''une lueur ambrée la nuit — comme un cœur qui bat', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_08', 'NPC_GRA_38', 'K2', '{"direction","strate_47"}', 'Les brins pointent tous dans la même direction — vers le nord-ouest, là où la strate −47 est marquée sur les cartes', '`QUEST:QST_GRA_MOUSSE_INVERSE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_09', 'NPC_GRA_38', 'K3', '{"contamination","noyau"}', 'La mousse est contaminée par une micro-fuite de données du Cœur `NPC_GRA_00` — elle pousse vers la source de l''énergie du seed, comme une plante qui cherche la lumière, et la direction est celle du serveur physique', NULL, '*(il recouvre la mousse d''un linge humide)* « Elle cherche quelque chose. Je ne sais pas quoi. Mais elle cherche. Je ne veux pas savoir ce qu''elle trouvera. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_38_10', 'NPC_GRA_38', 'KX', '{"*(tout le reste)*"}', '*(il arrose doucement un tapis de mousse)* « La mousse ne ment pas. Elle pousse là où c''est bon. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_01', 'NPC_GRA_39', 'K0', '{"annonce","cours"}', 'Annonce des cours des minerais — 3 fois par jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_02', 'NPC_GRA_39', 'K0', '{"evenement","halle"}', 'Annonces d''événements — arrivages, réunions, alertes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_03', 'NPC_GRA_39', 'K0', '{"criee","horaire"}', 'Horaires des criées — 8h, 12h, 18h', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_04', 'NPC_GRA_39', 'K1', '{"cours","bloques"}', 'Les cours n''ont pas bougé depuis trois jours — anormal', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_05', 'NPC_GRA_39', 'K1', '{"marla","tableau"}', 'Le tableau de Marla (`NPC_GRA_02`) change — mais pas ses annonces', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_06', 'NPC_GRA_39', 'K1', '{"cardinal","dictée"}', 'Le Cardinal lui dicte les cours — normalement mis à jour toutes les heures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_07', 'NPC_GRA_39', 'K2', '{"filonant","perturbation"}', 'Le Marchand Fer (`NPC_GRA_31`) a dit que les veines « ne répondent plus » aux sondages', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_08', 'NPC_GRA_39', 'K2', '{"vice_chancelier","ordre"}', 'Le Vice-Chancelier (`NPC_GRA_27`) lui a ordonné de continuer les annonces coûte que coûte', '`QUEST:QST_GRA_COURS_BLOQUES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_09', 'NPC_GRA_39', 'K3', '{"cardinal","freeze"}', 'Le Cardinal a gelé les cours parce que le Filonant a créé une veine « pirate » qui fausse les statistiques — le système n''arrive plus à agréger les données des filons, et affiche par défaut les derniers cours valides', NULL, '*(il fait sonner sa cloche, mais sa voix est un ton plus bas)* « Le fer… 150. L''argent… 220. J''annonce ce qu''on me dit d''annoncer. Je ne pose pas de questions. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_39_10', 'NPC_GRA_39', 'KX', '{"*(tout le reste)*"}', '*(il remonte sa cloche)* « La Halle ne dort jamais. Les cours non plus. Sauf cette semaine. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_01', 'NPC_GRA_40', 'K0', '{"taverne","service"}', 'Taverne Le Socle — bière de caverne, repas, chambres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_02', 'NPC_GRA_40', 'K0', '{"biere","carte"}', 'Carte des bières — blonde, brune, ambrée, double', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_03', 'NPC_GRA_40', 'K0', '{"prix","conso"}', 'Prix : 5-15 Yuld le verre, 50 Yuld le pichet', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_04', 'NPC_GRA_40', 'K1', '{"biere","gout_metal"}', 'La bière a un goût métallique depuis deux semaines', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_05', 'NPC_GRA_40', 'K1', '{"brasseur","recette"}', 'Le brasseur jure que la recette n''a pas changé', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_06', 'NPC_GRA_40', 'K1', '{"eau","source"}', 'L''eau de brassage vient d''une source sous la ville', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_07', 'NPC_GRA_40', 'K2', '{"source","banque"}', 'La source passe sous la Banque de Granzam — à 15 mètres de la salle des coffres', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_08', 'NPC_GRA_40', 'K2', '{"convoi","arrivee"}', 'Les convois d''approvisionnement arrivent systématiquement en retard depuis un mois', '`QUEST:QST_GRA_BIERE_METAL`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_09', 'NPC_GRA_40', 'K3', '{"eau","contamination_noyau"}', 'L''eau de source est contaminée par des micro-particules de roche du Noyau de Pierre `NPC_GRA_75` — la salle respirante sous la Banque filtre les données du Cardinal et rejette des résidus minéraux dans la nappe phréatique', NULL, '*(il essuie un verre, le regarde à la lumière)* « L''eau change. Je le sens. Mais personne ne veut m''écouter. Bois ta bière, et tais-toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_40_10', 'NPC_GRA_40', 'KX', '{"*(tout le reste)*"}', '*(il pousse un pichet vers vous)* « Bois. Ça te fera du bien. Et arrête de poser des questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_01', 'NPC_GRA_41', 'K0', '{"service","taverne"}', 'Service à la taverne — commandes, nettoyage', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_02', 'NPC_GRA_41', 'K0', '{"clients","habitudes"}', 'Les habitués du Socle — noms, boisson préférée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_03', 'NPC_GRA_41', 'K0', '{"carte","boissons"}', 'La carte des boissons — bières, vins de pierre, hydromel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_04', 'NPC_GRA_41', 'K1', '{"client","noir"}', 'Un client boit dans l''obscurité totale depuis une semaine', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_05', 'NPC_GRA_41', 'K1', '{"visage","cache"}', 'Elle n''a jamais vu son visage — il est toujours dans l''ombre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_06', 'NPC_GRA_41', 'K1', '{"pourboire","eleve"}', 'Il laisse 50 Yuld de pourboire — trop pour une bière', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_07', 'NPC_GRA_41', 'K2', '{"pas","empreinte"}', 'Il ne laisse pas d''empreintes sur le sol poussiéreux', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_08', 'NPC_GRA_41', 'K2', '{"tavernier","avertissement"}', 'Le Tavernier lui a dit de ne pas y faire attention — « certains clients aiment le noir »', '`QUEST:QST_GRA_CLIENT_NOIR`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_09', 'NPC_GRA_41', 'K3', '{"observateur","gemme"}', 'Le client est un « observateur » projeté par la Gemme Qui Voit `NPC_GRA_35` — une image sans corps, une donnée du Cardinal qui prend forme pour surveiller les conversations de la taverne', NULL, '*(elle pose un verre sur le comptoir, la main tremblante)* « Il est là ce soir. Dans le coin. Ne le regarde pas. Surtout, ne le regarde pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_41_10', 'NPC_GRA_41', 'KX', '{"*(tout le reste)*"}', '*(elle essuie une table)* « La taverne est pleine ce soir. Sauf le coin noir. Lui, il est toujours libre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_01', 'NPC_GRA_42', 'K0', '{"cuisine","menu"}', 'Menu du Socle — plats sur pierre chaude, soupes, grillades', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_02', 'NPC_GRA_42', 'K0', '{"cuisson","granit"}', 'Technique de cuisson sur granit — température, temps', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_03', 'NPC_GRA_42', 'K0', '{"ingredients","appro"}', 'Approvisionnement — viande, légumes, épices, sel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_04', 'NPC_GRA_42', 'K1', '{"sel","gratte"}', 'Un lot de sel des Profondeurs fait gratter la gorge', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_05', 'NPC_GRA_42', 'K1', '{"residu","lueur"}', 'Le sel laisse un résidu qui brille sous lumière violette', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_06', 'NPC_GRA_42', 'K1', '{"receleur","source"}', 'Le Receleur (`NPC_GRA_48`) le lui a vendu — « sel rare des strates profondes »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_07', 'NPC_GRA_42', 'K2', '{"cristal","donnees"}', 'L''Alchimiste (`NPC_GRA_35`) a identifié le résidu : des cristaux de données solidifiées', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_08', 'NPC_GRA_42', 'K2', '{"noyau","sous_produit"}', 'Le sel vient d''une strate proche du Noyau — les cristaux se forment par condensation de données', '`QUEST:QST_GRA_SEL_PROFONDEURS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_09', 'NPC_GRA_42', 'K3', '{"sel","donnees_cardinal"}', 'Le sel des Profondeurs est un dépôt de données excédentaires que le Cardinal `NPC_GRA_00` purged — des bits de seed cristallisés que le Receleur récupère et revend comme condiment de luxe', NULL, '*(jette une pincée de sel dans le feu — elle crépite violet)* « J''utilise plus ce sel. Brûle dans le feu plus proprement que sur la langue. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_42_10', 'NPC_GRA_42', 'KX', '{"*(tout le reste)*"}', '*(il retourne une grillade sur la pierre)* « La cuisine, c''est de la chimie. Et la chimie, ça ne ment pas. Sauf quand l''ingrédient ment. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_01', 'NPC_GRA_43', 'K0', '{"musique","barde"}', 'Représentations au Socle — soirées, chansons, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_02', 'NPC_GRA_43', 'K0', '{"repertoire","legende"}', 'Répertoire — légendes de la pierre, ballades des mines', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_03', 'NPC_GRA_43', 'K0', '{"inspiration","source"}', 'Ses inspirations — échos des galeries, récits des mineurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_04', 'NPC_GRA_43', 'K1', '{"chanson","involontaire"}', 'Il chante une chanson qu''il n''a pas écrite — elle lui vient en dormant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_05', 'NPC_GRA_43', 'K1', '{"paroles","saigne"}', '« Une veine qui saigne, un cœur sous le granit » — paroles récurrentes', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_06', 'NPC_GRA_43', 'K1', '{"mineurs","effet"}', 'Les mineurs qui l''écoutent deviennent nerveux, certains arrêtent le travail', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_07', 'NPC_GRA_43', 'K2', '{"frequence","filonant"}', 'L''Archiviste (`NPC_GRA_26`) a reconnu la mélodie — « c''est la fréquence du Filonant »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_08', 'NPC_GRA_43', 'K2', '{"reve","note"}', 'Il rêve d''une note unique qui résonne dans une galerie vide — toujours la même', '`QUEST:QST_GRA_CHANSON_FILON`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_09', 'NPC_GRA_43', 'K3', '{"transmission","involontaire"}', 'Le Barde capte la fréquence sismique du Filonant — le Cœur `NPC_GRA_00` émet des ondes que son oreille absolue transforme inconsciemment en musique, et la chanson est un décodage exact de l''activité du seed', NULL, '*(il pose sa lyre, voix soudain grave)* « Je ne chante plus cette chanson. Les pierres m''ont demandé d''arrêter. Et j''écoute les pierres. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_43_10', 'NPC_GRA_43', 'KX', '{"*(tout le reste)*"}', '*(il pince une corde)* « La musique, c''est comme la pierre. Elle dure plus longtemps que ceux qui la créent. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_01', 'NPC_GRA_44', 'K0', '{"auberge","chambre"}', 'Location de chambres — 30 Yuld/nuit, petit-déjeuner inclus', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_02', 'NPC_GRA_44', 'K0', '{"etage","disposition"}', 'Disposition de l''auberge — 6 chambres, salle commune', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_03', 'NPC_GRA_44', 'K0', '{"confort","service"}', 'Services — bain chaud, repas, coffre personnel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_04', 'NPC_GRA_44', 'K1', '{"chambre_4","odeur"}', 'La chambre 4 sent le fer frais — comme une forge', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_05', 'NPC_GRA_44', 'K1', '{"nettoyage","echec"}', 'Il a tout nettoyé — l''odeur revient en une journée', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_06', 'NPC_GRA_44', 'K1', '{"reve","sang"}', 'Un client a dit que le mur de la chambre 4 saignait dans son rêve', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_07', 'NPC_GRA_44', 'K2', '{"veine","sous_sol"}', 'Sous l''auberge passe une veine de fer qui relie la Banque', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_08', 'NPC_GRA_44', 'K2', '{"banquier","proposition"}', 'Le Banquier (`NPC_GRA_30`) lui a proposé de racheter l''auberge « pour la déplacer »', '`QUEST:QST_GRA_CHAMBRE_FER`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_09', 'NPC_GRA_44', 'K3', '{"flux","donnees_fer"}', 'L''odeur de fer est une saturation de données ferreuses dans la roche — le flux d''information du Cardinal `NPC_GRA_00` traverse la veine de fer comme un conduit et s''infiltre dans la maçonnerie de l''auberge, et l''odeur est la signature physique de ce transfert', NULL, '*(il vous tient par l''épaule)* « La 4 ? Elle n''existe pas. Tu as rêvé. Tout le monde rêve de la 4. Prends la 3. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_44_10', 'NPC_GRA_44', 'KX', '{"*(tout le reste)*"}', '*(il remet une clé sur le râtelier)* « L''auberge est pleine. Désolé. Réessaie demain. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_01', 'NPC_GRA_45', 'K0', '{"pari","convoi"}', 'Paris sur les convois — horaires, cargaison, provenance', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_02', 'NPC_GRA_45', 'K0', '{"cote","rapport"}', 'Cotes et rapports — gains potentiels, mise minimale 10 Yuld', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_03', 'NPC_GRA_45', 'K0', '{"registre","arrivee"}', 'Registre des arrivées — historique, fiabilité des routes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_04', 'NPC_GRA_45', 'K1', '{"gain","anormal"}', 'Il gagne tous ses paris depuis deux semaines — anormal', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_05', 'NPC_GRA_45', 'K1', '{"convoi","exactitude"}', 'Les convois arrivent à la minute près — jamais de retard', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_06', 'NPC_GRA_45', 'K1', '{"cardinal","optimisation"}', 'Le Cardinal semble ajuster la vitesse des convois en temps réel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_07', 'NPC_GRA_45', 'K2', '{"registre","triche"}', 'Il a comparé les registres sur un an — depuis un mois, la variance des temps d''arrivée est de zéro', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_08', 'NPC_GRA_45', 'K2', '{"filonant","stabilisation"}', 'Marla (`NPC_GRA_02`) pense que le Cardinal compense les perturbations du Filonant en stabilisant les convois', '`QUEST:QST_GRA_CONVOIS_TRUQUES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_09', 'NPC_GRA_45', 'K3', '{"cardinal","economie_forcee"}', 'Le Cardinal a activé un « stabilisateur économique » qui ajuste les vitesses des PNJ de convoi pour maintenir l''illusion d''une économie stable pendant que le Filonant déstructure les veines de minerai — les convois sont des leurres', NULL, '*(il froisse un ticket de pari)* « J''parie plus. C''est plus du jeu, c''est de la lecture. Et j''aime pas savoir la fin avant le début. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_45_10', 'NPC_GRA_45', 'KX', '{"*(tout le reste)*"}', '*(il compte des pièces sur une table)* « Un pari, c''est un pari. Mais quand tout est écrit d''avance, c''est plus un pari. C''est une farce. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_01', 'NPC_GRA_46', 'K0', '{"concierge","service"}', 'Services — bagages, ménage, clés', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_02', 'NPC_GRA_46', 'K0', '{"coffre","acces"}', 'Accès aux coffres individuels des chambres', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_03', 'NPC_GRA_46', 'K0', '{"auberge","entretien"}', 'Entretien de l''auberge — horaires, étages', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_04', 'NPC_GRA_46', 'K1', '{"coffre_4","gemissement"}', 'Le coffre de la chambre 4 gémit la nuit', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_05', 'NPC_GRA_46', 'K1', '{"chaleur","bois"}', 'Le coffre est chaud au toucher — anormal pour du bois', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_06', 'NPC_GRA_46', 'K1', '{"banquier","surveillance"}', 'Le Banquier (`NPC_GRA_30`) lui a demandé de surveiller le coffre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_07', 'NPC_GRA_46', 'K2', '{"battement","dedans"}', 'Il sent un battement à travers le bois — comme un cœur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_08', 'NPC_GRA_46', 'K2', '{"coffre","vide"}', 'Il a ouvert le coffre : vide. Mais le battement continue', '`QUEST:QST_GRA_COFFRE_GEINT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_09', 'NPC_GRA_46', 'K3', '{"coffre","conduit_noyau"}', 'Le coffre de la chambre 4 est un « réceptacle de résonance » du Noyau de Pierre `NPC_GRA_75` — il capte les pulsations du serveur via la veine de fer et les amplifie, et les gémissements sont des interférences de données qui traversent le bois', NULL, '*(il recule d''un pas)* « J''ai touché le coffre. Il est vivant. Je ne veux plus m''en approcher. Toi non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_46_10', 'NPC_GRA_46', 'KX', '{"*(tout le reste)*"}', '*(il balaye le couloir sans conviction)* « L''auberge est calme aujourd''hui. Sauf la 4. Toujours la 4. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_01', 'NPC_GRA_47', 'K0', '{"commerce","itinerant"}', 'Vente de marchandises itinérantes — outils, tissus, épices', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_02', 'NPC_GRA_47', 'K0', '{"routes","alne_voulg"}', 'Routes commerciales — Granzam-Alne (3j), Granzam-Voulg (2j), Freelia (5j)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_03', 'NPC_GRA_47', 'K0', '{"cargaison","prix"}', 'Prix variables selon la ville d''origine — négociation possible', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_04', 'NPC_GRA_47', 'K1', '{"route","modification"}', 'La route de Freelia a changé la nuit — des pierres déplacées', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_05', 'NPC_GRA_47', 'K1', '{"boussole","perte"}', 'Il a dû utiliser une boussole sur une route qu''il connaît depuis 30 ans', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_06', 'NPC_GRA_47', 'K1', '{"alne","bomil"}', 'Bomil (`NPC_ALN_93`) à Alne a signalé le même phénomène sur la route des Gemmes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_07', 'NPC_GRA_47', 'K2', '{"strate","deplacement"}', 'Les pierres de la route sont « poussées » par quelque chose sous le sol', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_08', 'NPC_GRA_47', 'K2', '{"filonant","route"}', 'Le Marchand de Gemmes (`NPC_GRA_66`) a dit que le Filonant déplace les veines — et donc la route qui les suit', '`QUEST:QST_GRA_ROUTE_MOBILE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_09', 'NPC_GRA_47', 'K3', '{"filament","reseau_route"}', 'Le réseau routier d''Alfheim est généré par les mêmes seeds que les veines de minerai — quand le Filonant bouge, les routes « suivent » virtuellement, et le Cardinal recalcule le terrain chaque nuit, ce qui explique les changements nocturnes', NULL, '*(il range sa boussole)* « La route change. Je ne sais pas pourquoi. Mais je sais que je ne suis plus le seul à la tracer. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_47_10', 'NPC_GRA_47', 'KX', '{"*(tout le reste)*"}', '*(il charge un sac sur son épaule)* « Le commerce, c''est du mouvement. Et le mouvement, c''est la vie. Mais si la route bouge plus vite que toi, t''es mort. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_01', 'NPC_GRA_48', 'K0', '{"bijouterie","officiel"}', 'Vente de bijoux et gemmes « de contrebande légère »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_02', 'NPC_GRA_48', 'K0', '{"cave","acces"}', 'Accès par la Banque — entrée discrète, « sur rendez-vous »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_03', 'NPC_GRA_48', 'K0', '{"prix","noir"}', 'Tarifs du marché noir — 2 à 5 fois le prix officiel', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_04', 'NPC_GRA_48', 'K1', '{"gemme","noire"}', 'Il a vendu une gemme noire à Marla — « elle voit des choses »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_05', 'NPC_GRA_48', 'K1', '{"ceil","cardinal"}', '« La gemme voit ce que le Cardinal voit. Et le Cardinal voit tout. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_06', 'NPC_GRA_48', 'K1', '{"reseau","alne_swilvane"}', 'Il travaille avec Bomil (`NPC_ALN_93`), Torvin (`NPC_SWI_93`) et Ilka (`NPC_GAT_33`)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_07', 'NPC_GRA_48', 'K2', '{"cave","sous_banque"}', 'Sa cave est directement sous la salle des coffres — il entend la respiration', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_08', 'NPC_GRA_48', 'K2', '{"gemme","observation"}', 'Les gemmes « qui voient » sont des gemmes du Cardinal — il les détourne avant qu''elles soient activées', '`QUEST:QST_GRA_RECELEUR_GEMMES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_09', 'NPC_GRA_48', 'K3', '{"reseau","surveillance"}', 'Le Receleur est un « nœud de collecte » du Cardinal — il distribue les gemmes-observatrices volontairement pour étendre le réseau de surveillance à tout Alfheim, en échange d''une protection et d''un accès aux données qu''elles collectent', NULL, '*(il ferme un tiroir, clé tourne)* « Je ne vends pas des gemmes. Je vends des regards. Et toi, tu regardes trop. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_48_10', 'NPC_GRA_48', 'KX', '{"*(tout le reste)*"}', '*(il examine une gemme à la loupe)* « Belle pierre. Elle te plaît ? Elle plaît à tout le monde. C''est pour ça qu''elle est dangereuse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_01', 'NPC_GRA_49', 'K0', '{"accueil","visite"}', 'Accueil des nouveaux — carte de Granzam, points d''intérêt', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_02', 'NPC_GRA_49', 'K0', '{"tutoriel","minage"}', 'Tutoriel — comment miner, où vendre, les dangers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_03', 'NPC_GRA_49', 'K0', '{"forteresse","histoire"}', 'Histoire de la forteresse de granit — construction, sièges', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_04', 'NPC_GRA_49', 'K1', '{"visiteur","disparition"}', 'Certains visiteurs disparaissent après être allés à la Banque', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_05', 'NPC_GRA_49', 'K1', '{"registre","effacement"}', 'Le Cardinal efface leur entrée du registre en 24h', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_06', 'NPC_GRA_49', 'K1', '{"banque","sous_sol"}', 'Les disparus posaient tous des questions sur le sous-sol de la Banque', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_07', 'NPC_GRA_49', 'K2', '{"huissier","liste"}', 'L''Huissier (`NPC_GRA_28`) lui a montré une liste de noms — tous disparus', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_08', 'NPC_GRA_49', 'K2', '{"coffre","respiration"}', 'Le Banquier (`NPC_GRA_30`) lui a dit qu''il « fallait les éloigner de la salle qui respire »', '`QUEST:QST_GRA_DISPARUS_BANQUE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_49_10', 'NPC_GRA_49', 'KX', '{"*(tout le reste)*"}', '*(il vous tend une carte de la ville)* « Tu veux voir la Grande Halle ? La Banque ? Évite la Banque. Enfin, pas tout de suite. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_01', 'NPC_GRA_50', 'K0', '{"rempart","veille"}', 'Il monte la garde chaque nuit sur le rempart nord-est, tour de 4h.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_02', 'NPC_GRA_50', 'K0', '{"steppe","granit"}', 'Les Steppes de Granit s''étendent à perte de vue côté est — aucun couvert pour un assaut.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_03', 'NPC_GRA_50', 'K0', '{"equipement"}', 'Sa lunette de visée nocturne est cerclée de mithril — transmission lumineuse parfaite.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_04', 'NPC_GRA_50', 'K1', '{"formes","creusement"}', 'Des formes trapues creusent sous la steppe la nuit — il voit les gravats disparaître.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_05', 'NPC_GRA_50', 'K1', '{"silencieux","galerie"}', 'Les galeries creusées ne laissent pas de débris. « On creuse avec de la lumière, pas avec des pioches. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_06', 'NPC_GRA_50', 'K1', '{"rapport","margrim"}', 'Margrim l''a convoqué une fois pour décrire les trous. Il a pâli en écoutant.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_07', 'NPC_GRA_50', 'K2', '{"tunnel","resonance","noyau"}', 'Les formes creusent en cercles concentriques autour du noyau de Granzam — comme si elles savaient où il est.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_08', 'NPC_GRA_50', 'K2', '{"disparition","gravats"}', 'Les gravats ne tombent pas : ils « remontent » vers la surface la nuit suivante, reformant le sol.', '`QUEST:QST_GRA_FOSSES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_09', 'NPC_GRA_50', 'K3', '{"mainteneur","exterieur"}', 'Les formes ne sont pas des monstres du jeu — ce sont des scripts de maintenance externes qui checkent l''intégrité du seed minéral. Leurs « trous » sont des sondes.', NULL, '*(il cligne des yeux)* « Si je savais ce qu''elles étaient, je dormirais. C''est pour ça que je veille. Je ne veux pas savoir. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_50_10', 'NPC_GRA_50', 'KX', '{"hors-sujet"}', '*(il tapote son muret)* « Tu veux acheter une pierre ? Je connais un marchand. Pas moi. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_01', 'NPC_GRA_51', 'K0', '{"lanterne","lampe"}', 'Vend des lanternes à gemmes — prix de 50 à 500 Yrd.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_02', 'NPC_GRA_51', 'K0', '{"atelier","travail"}', 'Atelier des Profondeurs — il y taille et polit toutes ses gemmes lui-même.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_03', 'NPC_GRA_51', 'K0', '{"gemme","eclairage"}', 'Sa gemme préférée pour l''éclairage : le quartz citrin — lumière chaude, sans ombre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_04', 'NPC_GRA_51', 'K1', '{"lanterne","eternelle"}', 'Une lanterne sous son comptoir brûle sans combustible depuis 130 ans.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_05', 'NPC_GRA_51', 'K1', '{"gemme","coeur","noyau"}', 'La gemme de cette lanterne lui a été donnée par un mineur de la strate −47 — « elle venait d''à côté du Cœur. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_06', 'NPC_GRA_51', 'K1', '{"cache","tiroir"}', 'Il garde la lanterne dans un tiroir doublé de velours sous le comptoir de droite.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_07', 'NPC_GRA_51', 'K2', '{"gemme","pulsation"}', 'La gemme de la lanterne pulse en phase avec le bourdonnement des soubassements du Conseil.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_08', 'NPC_GRA_51', 'K2', '{"vente","refus"}', 'Un Gnome encapuchonné a essayé de la lui racheter trois fois. Il refuse depuis 50 ans.', '`QUEST:QST_GRA_LANTERNE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_09', 'NPC_GRA_51', 'K3', '{"gemme","seed","extrait"}', 'La gemme de la lanterne est un fragment du Cœur de Granit que le mineur a chipé sans le savoir — un éclat de seed minéral avec une durée de vie infinie parce qu''il n''est pas en base de données.', NULL, '*(il ferme le tiroir doucement)* « C''est juste une lanterne qui marche bien. Certains objets aiment leur métier, c''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_51_10', 'NPC_GRA_51', 'KX', '{"hors-sujet"}', '*(il sort une pierre de sa poche)* « Tu veux une lampe frontale ? 30 Yrd, garantie trois ans. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_01', 'NPC_GRA_52', 'K0', '{"explosif","enseignement"}', 'Enseigne la compétence Artificier Niv1-6 (mines, charges, dynamitage).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_02', 'NPC_GRA_52', 'K0', '{"atelier","poudre"}', 'Atelier des Profondeurs — salle ouest, établi de pierre, ventilation par gaine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_03', 'NPC_GRA_52', 'K0', '{"tarif","apprentissage"}', 'Cours : 300 Yrd/niveau, matériaux inclus (sauf cristaux instables).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_04', 'NPC_GRA_52', 'K1', '{"charge","fremissement"}', 'Une charge posée sur son établi frémit sans raison depuis 3 jours.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_05', 'NPC_GRA_52', 'K1', '{"guerre","cicatrice"}', 'Il a perdu deux doigts à la guerre dans une explosion de poudre de mithril.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_06', 'NPC_GRA_52', 'K1', '{"poudre","recette"}', 'Sa poudre noire contient un soupçon de cendre de golem — stabilise la combustion.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_07', 'NPC_GRA_52', 'K2', '{"charge","resonance"}', 'La charge qui frémit est liée au bourdonnement des soubassements — elle vibre dans la même fréquence que le noyau.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_08', 'NPC_GRA_52', 'K2', '{"cristal","instable"}', 'Le cristal qu''il a utilisé vient de la strate −47 — extrait par le Vieux Mineur `NPC_GRA_65`.', '`QUEST:QST_GRA_CHARGE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_09', 'NPC_GRA_52', 'K3', '{"resonance","detecteur"}', 'La charge ne frémit pas : elle capte une balise de maintenance externe que le noyau émet tous les 72h pour synchroniser les seeds minérales. Il a fabriqué un détecteur de seed sans le savoir.', NULL, '*(il recule d''un pas)* « C''est un art instable. On ne touche pas à ce qu''on ne comprend pas. Et celle-ci… je ne la comprends plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_52_10', 'NPC_GRA_52', 'KX', '{"hors-sujet"}', '*(il croise les bras)* « La poésie ? Une charge bien posée, ça fait son propre poème. Pan. Fin. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_01', 'NPC_GRA_53', 'K0', '{"mineralogie","lecture"}', 'Lit les veines des roches par résonance tactile — 10 min par échantillon.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_02', 'NPC_GRA_53', 'K0', '{"grande_halle","service"}', 'Sa table est à l''angle nord-ouest de la Grande Halle, près de la fontaine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_03', 'NPC_GRA_53', 'K0', '{"strate","age"}', 'Il peut estimer l''âge d''une strate à 2% près.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_04', 'NPC_GRA_53', 'K1', '{"chant","veine"}', 'Il a entendu une veine « chanter » sous la Grande Halle — un son grave et tenu.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_05', 'NPC_GRA_53', 'K1', '{"resonance","nord"}', 'Le chant venait de sous la Salle du Conseil, côté nord — impossible d''en lire la strate.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_06', 'NPC_GRA_53', 'K1', '{"coeur","granit"}', 'Il sait qu''il y a « quelque chose » sous la ville — une masse qui n''a pas la même signature qu''une roche ordinaire.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_07', 'NPC_GRA_53', 'K2', '{"chant","note","fa"}', 'La note tenue de la veine est un Fa−2, en dessous du seuil audible humain — il l''entend quand il pose le front au sol.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_08', 'NPC_GRA_53', 'K2', '{"bloc","cube","parfait"}', 'La masse sous le Conseil est un bloc cubique aux arêtes parfaites — rien de géologique.', '`QUEST:QST_GRA_COEUR`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_09', 'NPC_GRA_53', 'K3', '{"seed","resonance","fa2"}', 'Le Fa−2 est la fréquence d''échantillonnage de la seed minérale du serveur : 44,1 Hz downsamplé en onde carrée. Le « chant de la pierre » est le bruit de la VM qui respire.', NULL, '*(il ouvre les yeux lentement)* « Il y a des choses que la pierre ne dit qu''à ceux qui se taisent. Toi aussi, écoute. Puis tais-toi. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_53_10', 'NPC_GRA_53', 'KX', '{"hors-sujet"}', '*(il sourit)* « Une fleur ? Je peux te dire si elle pousse sur un filon de cuivre. Mais je suis minéralogiste, pas jardinier. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_01', 'NPC_GRA_54', 'K0', '{"bastion","défense"}', 'Le Bastion de l''Ouest est la première ligne de défense de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_02', 'NPC_GRA_54', 'K0', '{"fortification","plan"}', 'Le Stratège conçoit des plans de fortification pour toute la ville.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_03', 'NPC_GRA_54', 'K0', '{"commandant","approbation"}', 'Le Commandant (`NPC_GRA_09`) approuve ses plans sans les lire en détail.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_04', 'NPC_GRA_54', 'K1', '{"vibration","mur"}', 'Les murs du Bastion émettent une vibration régulière la nuit.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_05', 'NPC_GRA_54', 'K1', '{"piège","souterrain"}', 'Il conçoit un réseau de pièges sous la ville qui pourraient tous s''activer d''un seul coup.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_06', 'NPC_GRA_54', 'K1', '{"ennemi","intérieur"}', '« L''ennemi n''est pas dehors. L''ennemi est dans les murs. » Il refuse de préciser.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_07', 'NPC_GRA_54', 'K2', '{"vibration","fréquence"}', 'La vibration du Bastion est à 0,3 Hz — identique au filon chantant de Durgan (`NPC_GRA_01`).', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_08', 'NPC_GRA_54', 'K2', '{"mur","cartographie"}', 'Il a cartographié un réseau de cavités dans les murs qui ne figurent sur aucun plan original.', '`QUEST:QST_GRA_BASTION_VIBRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_09', 'NPC_GRA_54', 'K3', '{"bastion","noyau_defense"}', 'Le Bastion est un noyau de défense du serveur — un sous-système du Cardinal qui protège le seed matériel contre les intrusions extérieures.', NULL, '*(pose un doigt sur ses lèvres)* « Certains murs ne doivent pas être scrutés. Ni même nommés. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_54_10', 'NPC_GRA_54', 'KX', '{"*(tout le reste)*"}', '*(déplie une carte vierge et la contemple)* « Le meilleur plan est celui qui n''existe que dans la tête. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_01', 'NPC_GRA_55', 'K0', '{"guerre","leprechaun"}', 'Il a combattu pendant les Guerres Leprechaunes il y a trente ans.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_02', 'NPC_GRA_55', 'K0', '{"traité","paix"}', 'Le traité de paix a été signé à la Porte des Convois.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_03', 'NPC_GRA_55', 'K0', '{"porte_convois","veteran"}', 'Il passe ses journées à la Porte des Convois, assis sur un banc de pierre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_04', 'NPC_GRA_55', 'K1', '{"traité","copie"}', 'Il a gardé une copie personnelle du traité. Un paragraphe est dans une langue inconnue.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_05', 'NPC_GRA_55', 'K1', '{"ratification","cardinal"}', 'Le Cardinal n''a jamais ratifié le traité. Seuls les Lords des deux clans l''ont signé.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_06', 'NPC_GRA_55', 'K1', '{"sentinelle","patrouille"}', 'La Sentinelle (`NPC_GRA_56`) a vu des patrouilles Leprechaunes franchir la frontière.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_07', 'NPC_GRA_55', 'K2', '{"langue","inconnue"}', 'La langue du paragraphe manquant ressemble à du langage sismique — des runes qui vibrent.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_08', 'NPC_GRA_55', 'K2', '{"paix","armistice"}', '« La paix n''est qu''un armistice. Le Cardinal nous prépare à quelque chose. Les Leprechauns aussi. »', '`QUEST:QST_GRA_TRAITE_PERDU`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_09', 'NPC_GRA_55', 'K3', '{"traité","cardinal"}', 'Le traité a été signé par le Cardinal via le Noyau de Pierre — une clause secrète lie les deux seeds miniers des deux territoires en un seul protocole serveur.', NULL, '*(il plie la copie du traité et la glisse dans sa poche)* « Ce papier sent la mort. Je ne le montre plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_55_10', 'NPC_GRA_55', 'KX', '{"*(tout le reste)*"}', '*(il regarde l''horizon)* « Le soleil se couche sur Granzam. Tu trouves ça beau ? Moi je trouve que ça ressemble à un incendie. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_01', 'NPC_GRA_56', 'K0', '{"carrieres","frontiere"}', 'Les Carrières Brisées sont à la frontière du territoire Leprechaun.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_02', 'NPC_GRA_56', 'K0', '{"sentinelle","patrouille"}', 'Elle patrouille 12 heures par jour, seule.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_03', 'NPC_GRA_56', 'K0', '{"bofrik","prime"}', 'Bofrik (`NPC_GRA_03`) lui verse une prime pour chaque preuve d''intrusion.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_04', 'NPC_GRA_56', 'K1', '{"spirale","caillou"}', 'Elle trouve des spirales de cailloux disposées au sol, parfaitement géométriques.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_05', 'NPC_GRA_56', 'K1', '{"empreinte","botte"}', 'Des empreintes de bottes anormalement petites — taille 35 — tracent des cercles autour des spirales.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_06', 'NPC_GRA_56', 'K1', '{"rune","metal"}', 'Un morceau de métal gravé de runes Leprechaunes fiché dans une faille. Les runes forment un mot : « MITHRIL ».', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_07', 'NPC_GRA_56', 'K2', '{"spirale","alignement"}', 'Les spirales sont alignées parfaitement nord-sud. Elle en a trouvé 12, formant une ligne.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_08', 'NPC_GRA_56', 'K2', '{"leprechaun","trêve"}', '« Les Leprechauns ne franchissent pas la frontière. Les spirales non plus. Elles poussent seules. »', '`QUEST:QST_GRA_FRONTIERE_SPIRALE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_09', 'NPC_GRA_56', 'K3', '{"pacte","protocole_serveur"}', 'Le pacte entre Gnomes et Leprechauns est un protocole serveur entre deux seeds miniers — les spirales de cailloux sont des marqueurs de checkpoint du Cardinal.', NULL, '*(elle pose la main sur son épée)* « Je garde la frontière, je ne pose pas de questions sur ce qui la dessine. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_56_10', 'NPC_GRA_56', 'KX', '{"*(tout le reste)*"}', '*(elle ramasse un caillou et le glisse dans sa poche)* « Douze spirales. Douze cailloux. J''en garde un à chaque fois. Au cas où. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_01', 'NPC_GRA_57', 'K0', '{"lord","conseil"}', 'Elle sert le Lord Gnome à la Salle du Conseil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_02', 'NPC_GRA_57', 'K0', '{"ceremonie","protocole"}', 'Elle gère le protocole des audiences avec le Lord.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_03', 'NPC_GRA_57', 'K0', '{"salle_conseil","trone"}', 'Le trône sismique est au centre de la Salle du Conseil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_04', 'NPC_GRA_57', 'K1', '{"lord","immobile"}', 'Le Lord ne mange, ne boit, ne cligne jamais des yeux.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_05', 'NPC_GRA_57', 'K1', '{"main","traversee"}', 'Sa main a traversé la sienne. « Il n''est pas solide. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_06', 'NPC_GRA_57', 'K1', '{"deformation","image"}', 'Elle a vu le Lord se déformer quand personne n''était là. « Comme de l''eau. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_07', 'NPC_GRA_57', 'K2', '{"hologramme","projection"}', 'Le Lord est une projection lumineuse. Pas de corps, pas de chaleur.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_08', 'NPC_GRA_57', 'K2', '{"chancelier","savoir"}', 'Le Chancelier (`NPC_GRA_08`) sait aussi. Il lui a fait jurer le silence.', '`QUEST:QST_GRA_NATURE_LORD`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_09', 'NPC_GRA_57', 'K3', '{"lord","hologramme_noyau"}', 'Le Lord Gnome est un hologramme généré par le Noyau de Pierre (`NPC_GRA_00`) — une interface-système qui n''a jamais été un être vivant.', NULL, '*(elle baisse les yeux, arrange sa robe)* « Je ne peux pas parler du Lord. Il nous écoute toujours. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_57_10', 'NPC_GRA_57', 'KX', '{"*(tout le reste)*"}', '*(elle époussette le trône avec un plumeau)* « La poussière tombe sur son siège. Mais jamais sur lui. C''est étrange, non ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_01', 'NPC_GRA_58', 'K0', '{"scribe","conseil"}', 'Il transcrit les édits du Lord Gnome.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_02', 'NPC_GRA_58', 'K0', '{"edit","parchemin"}', 'Chaque édit est gravé sur parchemin de pierre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_03', 'NPC_GRA_58', 'K0', '{"rune","sismique"}', 'Le lexique sismique compte 88 runes connues.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_04', 'NPC_GRA_58', 'K1', '{"signature","inconnue"}', 'Il a trouvé une rune de signature qui n''existe pas dans le lexique.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_05', 'NPC_GRA_58', 'K1', '{"edit","six_mois"}', 'La même signature apparaît sur tous les édits depuis six mois.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_06', 'NPC_GRA_58', 'K1', '{"dame","silence"}', 'Il n''en a pas parlé à la Dame (`NPC_GRA_57`). « Elle a assez de soucis avec le Lord. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_07', 'NPC_GRA_58', 'K2', '{"copie","cachee"}', 'Il a gardé une copie de l''édit avec la signature inconnue. Il la cache dans les archives.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_08', 'NPC_GRA_58', 'K2', '{"rune","noyau"}', 'Il a comparé la rune aux gravures du sous-sol du Conseil : c''est la même.', '`QUEST:QST_GRA_SIGNATURE_EDIT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_09', 'NPC_GRA_58', 'K3', '{"edit","cardinal_noyau"}', 'L''édit vient du Cardinal via le Noyau de Pierre — la signature inconnue est la signature système du Cardinal lui-même.', NULL, '*(il range ses plumes)* « Mes transcriptions sont dans les archives. Je ne commente pas leur contenu. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_58_10', 'NPC_GRA_58', 'KX', '{"*(tout le reste)*"}', '*(il trempe sa plume)* « Un mot mal écrit peut tout changer. Je ne laisse rien au hasard. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_01', 'NPC_GRA_59', 'K0', '{"heraut","annonce"}', 'Il annonce les édits du Lord Gnome depuis la tribune.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_02', 'NPC_GRA_59', 'K0', '{"conseil","rouleau"}', 'Il reçoit ses rouleaux du Scribe Royal (`NPC_GRA_58`).', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_03', 'NPC_GRA_59', 'K0', '{"salle_conseil","tribune"}', 'La tribune est au centre de la Salle du Conseil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_04', 'NPC_GRA_59', 'K1', '{"rouleau","apparition"}', 'Un rouleau s''est écrit tout seul sur son pupitre.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_05', 'NPC_GRA_59', 'K1', '{"nouvelle","deja_ecrite"}', 'Les rouleaux arrivent déjà écrits, déroulés, prêts à être lus.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_06', 'NPC_GRA_59', 'K1', '{"scribe","ignorance"}', 'Le Scribe (`NPC_GRA_58`) jure qu''il n''a pas écrit les rouleaux de la semaine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_07', 'NPC_GRA_59', 'K2', '{"injection","parchemin"}', 'Les rouleaux portent la signature inconnue que le Scribe a découverte.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_08', 'NPC_GRA_59', 'K2', '{"systeme","message"}', '« Ce que je crie n''est pas du Conseil. C''est une voix d''ailleurs qui se sert de ma gorge. »', '`QUEST:QST_GRA_VOIX_SYSTEME`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_09', 'NPC_GRA_59', 'K3', '{"nouvelles","injectees_systeme"}', 'Les nouvelles sont injectées directement par le système — le Héraut est une interface de diffusion du Cardinal.', NULL, '*(il porte une main à sa gorge)* « Mes cordes vocales sont à moi. Le message appartient à un autre. Et je ne sais pas à qui. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_59_10', 'NPC_GRA_59', 'KX', '{"*(tout le reste)*"}', '*(il déroule un rouleau vide et lit d''une voix forte)* « Le… silence… est… proclamé ! … Il est vide. Ils le sont tous aujourd''hui. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_01', 'NPC_GRA_60', 'K0', '{"forge","lames_fines"}', 'Il forge des lames fines en mithril.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_02', 'NPC_GRA_60', 'K0', '{"mithril","durete"}', 'Le mithril de Granzam est réputé pour sa dureté exceptionnelle.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_03', 'NPC_GRA_60', 'K0', '{"atelier","profondeurs"}', 'Il travaille à l''Atelier des Profondeurs, niveau −8.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_04', 'NPC_GRA_60', 'K1', '{"lame","emousser"}', 'Ses lames ne s''émoussent jamais, même après des centaines de coupes.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_05', 'NPC_GRA_60', 'K1', '{"mithril","anormal"}', 'Le lot de mithril qu''il utilise est différent : il brille faiblement sans source de lumière.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_06', 'NPC_GRA_60', 'K1', '{"enchanteur","analyse"}', 'L''Enchanteur (`NPC_GRA_61`) n''a trouvé aucune magie sur le métal. « C''est physique, pas magique. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_07', 'NPC_GRA_60', 'K2', '{"mithril","provenance"}', 'Le Marchand de Mithril (`NPC_GRA_68`) refuse de dire d''où il vient. « Il vient de la mine. Quelle mine ? »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_08', 'NPC_GRA_60', 'K2', '{"filon","corruption"}', 'Le mithril garde sa structure à l''échelle atomique — comme s''il était figé dans le temps.', '`QUEST:QST_GRA_MITHRIL_ETERNE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_60_09', 'NPC_GRA_60', 'K3', '{"lame_seed_interaction"}', 'La lame ne s''émousse pas car le mithril est une émanation directe du seed matériel — il ignore l''usure car il est re-généré à chaque tick serveur.', NULL, '*(il caresse le fil de la lame)* « Je ne sais pas pourquoi elle dure. Je sais qu''elle dure. Et je la forgerai tant que le métal parlera. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_01', 'NPC_GRA_61', 'K0', '{"enchantement","terre"}', 'Il enchante des armes avec des sorts de terre et de protection.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_02', 'NPC_GRA_61', 'K0', '{"bastion","ouest"}', 'Son atelier est au Bastion de l''Ouest, salle des gardes.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_03', 'NPC_GRA_61', 'K0', '{"arme","protection"}', 'Une arme enchantée dure 24h — normalement.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_04', 'NPC_GRA_61', 'K1', '{"sort","durée"}', 'Son dernier sort de protection a duré 47 heures au lieu de 4.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_05', 'NPC_GRA_61', 'K1', '{"commandant","lame"}', 'La lame du Commandant (`NPC_GRA_09`) a gardé son enchantement une semaine.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_06', 'NPC_GRA_61', 'K1', '{"pierre","absorption"}', 'La pierre de l''atelier est chaude au toucher après une incantation.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_07', 'NPC_GRA_61', 'K2', '{"rune","persistante"}', 'Les runes qu''il trace au sort restent visibles sur la pierre des heures après.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_08', 'NPC_GRA_61', 'K2', '{"resonance","filon"}', 'Les sort persistent plus longtemps près des filons chantants identifiés par Durgan.', '`QUEST:QST_GRA_SORT_PERSISTANT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_09', 'NPC_GRA_61', 'K3', '{"sort","protocole_cardinal"}', 'Le sort est un protocole système que le Cardinal ré-exécute en boucle sur le seed minéral — il ne se dissipe pas car le serveur le rejoue à chaque tick.', NULL, '*(il ferme son grimoire)* « Certaines incantations ne devraient pas être répétées. Celle-ci est de celles-là. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_61_10', 'NPC_GRA_61', 'KX', '{"*(tout le reste)*"}', '*(il dessine une rune sur le mur avec le doigt)* « Tiens. Regarde. Elle brille encore. Elle ne devrait pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_01', 'NPC_GRA_62', 'K0', '{"apprentissage","forge"}', 'Il apprend la forge depuis six mois.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_02', 'NPC_GRA_62', 'K0', '{"bofrik","maitre"}', 'Son maître est Bofrik (`NPC_GRA_03`), l''Armurier du Bastion.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_03', 'NPC_GRA_62', 'K0', '{"atelier","profondeurs"}', 'L''Atelier des Profondeurs est son lieu de travail.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_04', 'NPC_GRA_62', 'K1', '{"lame","fausse_note"}', 'Sa dernière lame émet une note discordante quand on la frappe.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_05', 'NPC_GRA_62', 'K1', '{"chant","seul"}', 'La lame chante toute seule la nuit, sans qu''on la touche.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_06', 'NPC_GRA_62', 'K1', '{"cachee","sous_établi"}', 'Il a caché la lame sous son établi. Elle chante toutes les nuits à la même heure.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_07', 'NPC_GRA_62', 'K2', '{"note","frequence"}', 'La note fausse est à 0,47 Hz — une fréquence que le Maître Forgeron Lames (`NPC_GRA_60`) n''a jamais entendue.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_08', 'NPC_GRA_62', 'K2', '{"echo","strate"}', 'La note fait vibrer les parois de l''atelier, comme si elle réveillait la pierre.', '`QUEST:QST_GRA_LAME_FAUSSE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_09', 'NPC_GRA_62', 'K3', '{"lame_fausse","anomalie_seed"}', 'La lame « qui chante faux » est le résultat d''une fréquence de seed qui ne correspond à aucun biome minier connu — une anomalie de génération procédurale.', NULL, '*(il attrape la lame et la glisse dans le four)* « Elle chante mal. Je dois la reforger. Peut-être qu''elle se taira. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_62_10', 'NPC_GRA_62', 'KX', '{"*(tout le reste)*"}', '*(il frappe son enclume d''un coup timide)* « Un jour, je forgerai une lame parfaite. Qui chantera juste. Ou qui chantera pas du tout. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_01', 'NPC_GRA_63', 'K0', '{"archive","bannissement"}', 'Il a été banni du Conseil pour « possession de documents interdits ».', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_02', 'NPC_GRA_63', 'K0', '{"plan","fondation"}', 'Il garde des plans originaux de la construction de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_03', 'NPC_GRA_63', 'K0', '{"mine_mithril","cache"}', 'Il se cache dans la Mine de Mithril dans un renfoncement secret.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_04', 'NPC_GRA_63', 'K1', '{"plan","vide"}', 'Un plan montre une strate vide sous la ville. « Pas de la terre. Pas de la roche. Du rien. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_05', 'NPC_GRA_63', 'K1', '{"roche","annulation"}', 'Le plan décrit un dispositif qui annule la structure de la roche.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_06', 'NPC_GRA_63', 'K1', '{"vieux_mineur","cache"}', 'Le Vieux Mineur (`NPC_GRA_65`) l''a aidé à dissimuler le plan.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_07', 'NPC_GRA_63', 'K2', '{"sceau","conseil"}', 'Le plan porte le sceau du Conseil — mais d''un Conseil qui n''existe plus. L''ancien sceau d''avant-guerre.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_08', 'NPC_GRA_63', 'K2', '{"poche","vide"}', '« Sous la Salle du Conseil, il y a une poche. Pas creusée. Naturelle. Comme si la montagne n''avait jamais existé là. »', '`QUEST:QST_GRA_PLAN_VIDE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_09', 'NPC_GRA_63', 'K3', '{"plan","annulation_roche"}', 'Le plan décrit une seed d''annulation — un code qui désactive la génération de matière minérale autour d''un point. C''est une commande de debug du Cardinal.', NULL, '*(il referme le parchemin vivement)* « Certaines choses ne doivent pas être vues. Celle-ci en particulier. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_63_10', 'NPC_GRA_63', 'KX', '{"*(tout le reste)*"}', '*(il regarde ses mains couvertes de poussière)* « La poussière des archives se glisse partout. Dans mes poumons, dans mes rêves. Je ne peux plus m''en défaire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_01', 'NPC_GRA_64', 'K0', '{"mine_mithril","garde"}', 'Il garde l''entrée de la Mine de Mithril.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_02', 'NPC_GRA_64', 'K0', '{"profondeur","rotation"}', 'Il descend au fond du puits −40 une fois par nuit.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_03', 'NPC_GRA_64', 'K0', '{"grattement","mur"}', 'Il entend des grattements dans les murs de la mine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_04', 'NPC_GRA_64', 'K1', '{"fissure","lueur"}', 'Il a vu une fissure noire qui pulsait d''une lueur ambrée au fond du puits.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_05', 'NPC_GRA_64', 'K1', '{"craquement","son"}', 'Il a entendu un craquement sec suivi d''un bourdonnement grave.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_06', 'NPC_GRA_64', 'K1', '{"gardien_mine","doute"}', 'Le Gardien de la Mine (`NPC_GRA_16`) l''a traité de fou. « Il ne veut pas descendre voir. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_07', 'NPC_GRA_64', 'K2', '{"fissure","martellement"}', 'La fissure s''agrandit chaque nuit. Il a mesuré 3 cm de plus en une semaine.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_08', 'NPC_GRA_64', 'K2', '{"vibration","noyau"}', 'La veine noire vibre à la même fréquence que le bourdonnement du Conseil.', '`QUEST:QST_GRA_FISSURE_MINE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_09', 'NPC_GRA_64', 'K3', '{"noyau","fissure_seed"}', 'Le craquement qu''il a entendu est une corruption du seed matériel — le Noyau de Pierre (`NPC_GRA_00`) se fissure et saigne dans la mine. Le seed est en train de se corrompre.', NULL, '*(il recule d''un pas)* « La fissure. Il ne faut pas en parler trop fort. Elle pourrait t''entendre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_64_10', 'NPC_GRA_64', 'KX', '{"*(tout le reste)*"}', '*(il pose la main sur le mur de la mine)* « Écoute. Tu l''entends avec l''oreille ou c''est dans ta tête ? Moi, je l''entends dans mes os maintenant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_01', 'NPC_GRA_65', 'K0', '{"vieux_mineur","retraite"}', 'Il est mineur retraité. Assis à la Porte des Convois.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_02', 'NPC_GRA_65', 'K0', '{"porte_convois","banc"}', 'Son banc est le troisième en partant de l''est. Il ne le quitte jamais longtemps.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_03', 'NPC_GRA_65', 'K0', '{"durgan","apprentissage"}', 'Il a formé Durgan au minage. « Durgan cognait fort, mais cognait juste. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_04', 'NPC_GRA_65', 'K1', '{"carte","filon_charbon"}', 'Il a trouvé une carte dans un filon de charbon. Il l''a suivie jusqu''au bout.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_05', 'NPC_GRA_65', 'K1', '{"mur","granit_parfait"}', 'Au bout du tunnel : un mur de granit sans fissure, sans veine, parfait — pas naturel.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_06', 'NPC_GRA_65', 'K1', '{"archiviste","confident"}', 'Il a parlé du mur à l''Archiviste Interdit (`NPC_GRA_63`) un soir de pluie.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_07', 'NPC_GRA_65', 'K2', '{"carte_brulee","memoire"}', 'Il a brûlé la carte, mais il pourrait la redessiner de mémoire.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_08', 'NPC_GRA_65', 'K2', '{"chemin","coeur"}', '« Le chemin descend 47 strates. Puis la roche s''arrête. Après, c''est la lumière. »', '`QUEST:QST_GRA_CARTE_BRULEE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_09', 'NPC_GRA_65', 'K3', '{"carte","noyau_pierre"}', 'La carte qu''il a brûlée menait au Noyau de Pierre (`NPC_GRA_00`) — le bloc de seed matériel au centre du serveur. Il s''est tenu devant sans le savoir.', NULL, '*(il prend sa pipe éteinte et la contemple)* « Y a des chemins qu''on ne doit pas prendre deux fois. J''ai fait mon choix. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_65_10', 'NPC_GRA_65', 'KX', '{"*(tout le reste)*"}', '*(il crache par terre)* « La mine, c''était mieux avant. On creusait, on trouvait. Maintenant on creuse, on écoute. J''sais pas ce qui est pire. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_01', 'NPC_GRA_66', 'K0', '{"gemme","vente"}', 'Il vend des gemmes brutes et taillées. Prix : 100-3000 Yuld.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_02', 'NPC_GRA_66', 'K0', '{"grande_halle","commerce"}', 'La Grande Halle est le cœur commercial de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_03', 'NPC_GRA_66', 'K0', '{"marla","association"}', 'Il travaille avec Marla (`NPC_GRA_02`) pour les grosses transactions.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_04', 'NPC_GRA_66', 'K1', '{"gemme_battante","pouls"}', 'Une gemme dans sa vitrine émet un pouls régulier, comme un battement de cœur.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_05', 'NPC_GRA_66', 'K1', '{"nuit","cognement"}', 'La gemme cogne contre le verre de la vitrine la nuit.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_06', 'NPC_GRA_66', 'K1', '{"alchimiste","similitude"}', 'L''Alchimiste (`NPC_GRA_35`) dit que c''est le même matériau que la gemme noire de Marla.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_07', 'NPC_GRA_66', 'K2', '{"pouls","frequence"}', 'Le pouls de la gemme est de 72 battements par minute — un pouls humain.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_08', 'NPC_GRA_66', 'K2', '{"provenance","inconnue"}', 'Le prospecteur qui la lui a vendue n''avait pas de nom. Il portait un capuchon de pierre.', '`QUEST:QST_GRA_GEMME_BAT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_09', 'NPC_GRA_66', 'K3', '{"gemme_bat","noyau"}', 'La gemme qui bat est un fragment du Noyau de Pierre (`NPC_GRA_00`) — elle pulse encore à la fréquence du serveur.', NULL, '*(il ferme le tiroir à clé)* « Je l''achète ? Je la vends ? Ni l''un ni l''autre. Elle reste là. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_66_10', 'NPC_GRA_66', 'KX', '{"*(tout le reste)*"}', '*(il polir une gemme ordinaire sans y prêter attention)* « Y a des pierres qui valent de l''or. Y en a qui valent des questions. Les miennes valent les deux. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_01', 'NPC_GRA_67', 'K0', '{"minerais_rares","vente"}', 'Il vend des minerais rares. Prix : 500-4000 Yuld.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_02', 'NPC_GRA_67', 'K0', '{"grande_halle","stand"}', 'Son stand est dans l''aile est de la Grande Halle.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_03', 'NPC_GRA_67', 'K0', '{"argent","fer_lunaire"}', 'Il a de l''argent, du fer lunaire, de l''obsidienne de faille.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_04', 'NPC_GRA_67', 'K1', '{"minerai_noyau","lueur"}', 'Un lot de minerais brille sans lampe. « Comme s''ils avaient une lumière intérieure. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_05', 'NPC_GRA_67', 'K1', '{"lumiere","cache"}', 'La lumière faiblit quand un client s''approche. Les minerais « se cachent ».', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_06', 'NPC_GRA_67', 'K1', '{"boite_plombee"}', 'Il a gardé les minerais dans une boîte plombée. « Au cas où. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_07', 'NPC_GRA_67', 'K2', '{"provenance","sans_nom"}', 'Le mineur qui a livré les échantillons n''est jamais revenu chercher son paiement.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_08', 'NPC_GRA_67', 'K2', '{"minerai","meme_strate"}', 'L''Alchimiste (`NPC_GRA_35`) a confirmé : les minerais proviennent de la strate −47 — la strate du Noyau.', '`QUEST:QST_GRA_MINERAIS_LUMIERE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_09', 'NPC_GRA_67', 'K3', '{"minerai_lumineux","seed"}', 'Les minerais brillent car ils sont encore « connectés » au seed de génération — ils émettent la lumière résiduelle du Noyau de Pierre (`NPC_GRA_00`).', NULL, '*(il tapote la boîte plombée)* « Ceux-là, on les vend pas. On les regarde pas longtemps non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_67_10', 'NPC_GRA_67', 'KX', '{"*(tout le reste)*"}', '*(il sort une pépite d''obsidienne de sa poche)* « Regarde. Elle brille à peine maintenant. Mais la nuit, elle éclaire toute la pièce. Inquiétant. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_01', 'NPC_GRA_68', 'K0', '{"mithril","vente"}', 'Il vend du mithril. Prix : 2000 Yuld/kg.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_02', 'NPC_GRA_68', 'K0', '{"exclusivite","D15"}', 'Il a l''exclusivité de la vente de mithril par décret D15 du Conseil.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_03', 'NPC_GRA_68', 'K0', '{"mine_mithril","entree"}', 'Il tient son comptoir à l''entrée de la Mine de Mithril.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_04', 'NPC_GRA_68', 'K1', '{"poids","variable"}', 'Un même lingot pèse différemment chaque jour.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_05', 'NPC_GRA_68', 'K1', '{"lingot","fluctuation"}', 'Il a pesé le même lingot vingt fois : vingt résultats différents.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_06', 'NPC_GRA_68', 'K1', '{"forgeron_lames","confident"}', 'Le Maître Forgeron Lames (`NPC_GRA_60`) a aussi remarqué. « Le métal est instable. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_07', 'NPC_GRA_68', 'K2', '{"correction","cardinal"}', 'La fluctuation suit un cycle de 24h. Le poids est stable à minuit pile.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_08', 'NPC_GRA_68', 'K2', '{"mine_profonde","-45"}', 'Plus le métal vient de profondeur, plus la fluctuation est forte.', '`QUEST:QST_GRA_POIDS_MITHRIL`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_09', 'NPC_GRA_68', 'K3', '{"mithril","densite_seed"}', 'La densité du mithril fluctue car sa génération est en conflit avec la corruption du seed — il est partiellement « re-généré » à chaque tick serveur.', NULL, '*(il range le lingot sous son comptoir)* « Le mithril est capricieux. Il a ses humeurs. Je ne les commente pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_68_10', 'NPC_GRA_68', 'KX', '{"*(tout le reste)*"}', '*(il soupèse un lingot)* « Aujourd''hui il pèse 2,1 kg. Hier 1,8 kg. Demain… qui sait ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_01', 'NPC_GRA_69', 'K0', '{"noyau","golem"}', 'Il vend des noyaux de golem. Prix : 300-1500 Yuld selon l''état.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_02', 'NPC_GRA_69', 'K0', '{"steppes","ruines"}', 'Il collecte les noyaux dans les ruines des Steppes de Granit.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_03', 'NPC_GRA_69', 'K0', '{"itinérant","commerce"}', 'Il est marchand itinérant — pas de boutique fixe.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_04', 'NPC_GRA_69', 'K1', '{"noyau","chaud"}', 'Il a trouvé un noyau encore chaud. « Il était tiède dans ma main toute la nuit. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_05', 'NPC_GRA_69', 'K1', '{"pulsation","faible"}', 'Le noyau pulse faiblement, comme un cœur en arrêt.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_07', 'NPC_GRA_69', 'K2', '{"lueur","noyau"}', 'La nuit, le noyau émet une lueur ambrée — la couleur du Noyau de la Salle du Conseil.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_08', 'NPC_GRA_69', 'K2', '{"steppes","ruine_recente"}', 'La ruine où il a trouvé le noyau n''était pas là le mois dernier. Le Gardien (`NPC_GRA_10`) le confirme.', '`QUEST:QST_GRA_NOYAU_CHAUD`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_09', 'NPC_GRA_69', 'K3', '{"noyau_golem","seed_pulse"}', 'Le noyau pulse encore car il contient une copie partielle du seed matériel — un golem « mort » dont le noyau est resté connecté au serveur.', NULL, '*(il glisse la main dans le sac de plomb)* « Tu veux l''acheter ? Non. Tu veux le voir ? Même pas. Il reste là. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_69_10', 'NPC_GRA_69', 'KX', '{"*(tout le reste)*"}', '*(il regarde l''horizon des Steppes)* « Y a des jours où les ruines sont plus nombreuses que la veille. Des ruines neuves. Ça te dit rien ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_01', 'NPC_GRA_70', 'K0', '{"porte","granzam"}', 'Il garde l''entrée principale de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_02', 'NPC_GRA_70', 'K0', '{"horaire","garde"}', 'Il est posté de 20h à 08h — le quart de nuit.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_03', 'NPC_GRA_70', 'K0', '{"registre","entree"}', 'Il tient un registre des entrées et sorties.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_05', 'NPC_GRA_70', 'K1', '{"trace","poussière"}', 'Des traces de pas dans la poussière mènent à la Salle du Conseil et s''arrêtent net.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_06', 'NPC_GRA_70', 'K1', '{"serrure","intacte"}', 'La serrure est en parfait état. Aucun signe d''effraction.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_07', 'NPC_GRA_70', 'K2', '{"registre","sans_entree"}', 'Il a croisé son registre : les nuits où la porte s''ouvre, zéro entrée enregistrée.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_08', 'NPC_GRA_70', 'K2', '{"porte","acces_systeme"}', 'Les ouvertures coïncident avec les vibrations du Bastion signalées par le Stratège (`NPC_GRA_54`).', '`QUEST:QST_GRA_PORTE_SILENCIEUSE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_09', 'NPC_GRA_70', 'K3', '{"entree_silencieuse","systeme_load"}', 'Les entrées sans bruit sont des spawns du Cardinal — des PNJ ou des objets générés par le système qui « entrent » dans Granzam par la porte par défaut.', NULL, '*(il pose la main sur la porte)* « Je ne demande pas qui entre. Je note que rien n''entre. Et la porte s''ouvre quand même. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_70_10', 'NPC_GRA_70', 'KX', '{"*(tout le reste)*"}', '*(il racle la poussière du sol avec sa botte)* « Regarde. L''empreinte s''arrête là. Comme si le sol avait avalé le marcheur. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_01', 'NPC_GRA_71', 'K0', '{"douane","registre"}', 'Il tient le registre des entrées et sorties.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_02', 'NPC_GRA_71', 'K0', '{"porte_granzam","controle"}', 'Il contrôle les cargaisons à la Porte de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_03', 'NPC_GRA_71', 'K0', '{"noms","provenances"}', 'Il note le nom, la provenance et la cargaison de chaque visiteur.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_04', 'NPC_GRA_71', 'K1', '{"nom_roche","liste"}', 'Il a noté des visiteurs nommés Granit, Schiste, Basalte, Arkose.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_05', 'NPC_GRA_71', 'K1', '{"registre","verification"}', 'Il a vérifié au Conseil : ces noms n''existent dans aucun registre officiel.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_06', 'NPC_GRA_71', 'K1', '{"gardien_porte","temoin"}', 'Le Gardien (`NPC_GRA_70`) a vu ces personnes. « Il les a laissés passer'' les a oubliés. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_07', 'NPC_GRA_71', 'K2', '{"liste","six_mois"}', 'La liste des noms de roche fait trois pages. 47 visiteurs.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_08', 'NPC_GRA_71', 'K2', '{"noms","systeme"}', '« Ces personnes — si ce sont des personnes — n''ont pas d''identité. Elles existent le temps de franchir la porte. »', '`QUEST:QST_GRA_NOMS_ROCHE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_09', 'NPC_GRA_71', 'K3', '{"noms_roches","pnjs_systeme"}', 'Les visiteurs nommés Granit, Schiste, etc. sont des PNJ générés par le système pour des tests de seed — des « marcheurs fantomes » du Cardinal.', NULL, '*(il referme son registre)* « Je ne les ai jamais vus. Je les ai notés. C''est différent. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_71_10', 'NPC_GRA_71', 'KX', '{"*(tout le reste)*"}', '*(il rature un nom dans son registre)* « Lui'' il est venu trois fois. Granit. Chaque fois'' il repartait sans rien. Juste entrer et ressortir. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_01', 'NPC_GRA_72', 'K0', '{"rempart","surveillance"}', 'Il surveille les Steppes depuis les remparts extérieurs.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_02', 'NPC_GRA_72', 'K0', '{"horaire","nuit"}', 'Il est posté la nuit — de 20h à 06h.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_03', 'NPC_GRA_72', 'K0', '{"steppes","horizon"}', 'Les Steppes sont calmes le jour. La nuit, elles bougent.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_04', 'NPC_GRA_72', 'K1', '{"ombre","creusement"}', 'Il voit des ombres creuser dans les Steppes la nuit.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_05', 'NPC_GRA_72', 'K1', '{"trous","cylindriques"}', 'Des trous parfaitement cylindriques apparaissent le matin. 23 en 30 jours.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_06', 'NPC_GRA_72', 'K1', '{"commandant","rapport"}', 'Il a rapporté les trous au Commandant (`NPC_GRA_09`). « Il a dit que c''était l''érosion. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_07', 'NPC_GRA_72', 'K2', '{"trous","profondeur"}', 'Les trous font exactement 1 m de diamètre et 12 m de profondeur. Identiques.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_08', 'NPC_GRA_72', 'K2', '{"trous","alignement"}', 'Les trous forment une ligne droite qui pointe vers la Salle du Conseil.', '`QUEST:QST_GRA_OMBRES_CREUSENT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_09', 'NPC_GRA_72', 'K3', '{"ombres_creuser","seed_erosion"}', 'Les ombres qui creusent sont des artefacts visuels de corruption du seed — le terrain des Steppes est « rongé » par des boucles de génération défectueuses.', NULL, '*(il désigne les Steppes)* « Tu vois ces ombres ? Non ? T''as de la chance. Moi je les vois toutes les nuits depuis un mois. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_72_10', 'NPC_GRA_72', 'KX', '{"*(tout le reste)*"}', '*(il compte des points sur ses doigts)* « 23. Comme 23 noms sur une liste. J''ai arrêté de compter. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_01', 'NPC_GRA_73', 'K0', '{"alarme","effondrement"}', 'Il sonne la cloche d''alarme en cas d''effondrement.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_02', 'NPC_GRA_73', 'K0', '{"cloche","rempart"}', 'La cloche est au sommet du rempart est.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_03', 'NPC_GRA_73', 'K0', '{"signal","trois_coups"}', 'Trois coups longs = effondrement dans la mine.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_04', 'NPC_GRA_73', 'K1', '{"cloche","sonne_seule"}', 'La cloche sonne seule chaque nuit à 3h du matin.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_05', 'NPC_GRA_73', 'K1', '{"seul","auditeur"}', 'Personne d''autre ne l''entend. Les gardes disent qu''elle ne sonne pas.', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_06', 'NPC_GRA_73', 'K1', '{"margrim","écoute"}', 'Margrim (`NPC_GRA_06`) est venu l''écouter une nuit. Il a dit « C''est la montagne. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_07', 'NPC_GRA_73', 'K2', '{"heure","3h"}', 'La cloche sonne à 3h précises chaque nuit. Pas une minute de décalage.', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_08', 'NPC_GRA_73', 'K2', '{"vibration","coincidences"}', 'À 3h, le mur du rempart est chaud au toucher. La chaleur disparaît après le troisième coup.', '`QUEST:QST_GRA_CLOCHE_3H`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_09', 'NPC_GRA_73', 'K3', '{"cloche","noyau_pulse"}', 'La cloche sonne quand le Noyau de Pierre (`NPC_GRA_00`) pulse un warp de seed — c''est le système qui déclenche l''alarme par erreur, interprétant le warp comme un effondrement.', NULL, '*(il décroche la corde)* « Je ne tire plus. La cloche tire seule. Je ne fais que l''écouter maintenant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_73_10', 'NPC_GRA_73', 'KX', '{"*(tout le reste)*"}', '*(il met sa main sur la cloche)* « Elle est froide en journée. À 2h59, elle est chaude. Comme si quelqu''un la chauffait de l''intérieur. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_01', 'NPC_GRA_74', 'K0', '{"monture","location"}', 'Il loue des montures de roche. 100 Yuld/jour.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_02', 'NPC_GRA_74', 'K0', '{"lezard_roche","cheval_pierre"}', 'Il a des lézards de roche et des chevaux de pierre.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_03', 'NPC_GRA_74', 'K0', '{"porte","remise"}', 'Sa remise est à gauche de la Porte de Granzam.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_04', 'NPC_GRA_74', 'K1', '{"lezard","retour_seul"}', 'Un lézard loué est revenu seul, la selle vide. Les yeux blancs.', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_05', 'NPC_GRA_74', 'K1', '{"hennissement","nuit"}', 'Une monture a hennit dans le noir. Un son régulier. « Comme une alarme. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_06', 'NPC_GRA_74', 'K1', '{"monture","peur"}', 'Les montures refusent de sortir la nuit. Elles tremblent dans leur enclos.', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_07', 'NPC_GRA_74', 'K2', '{"hennissement","periide"}', 'Le prospecteur qui a loué le lézard est porté disparu. Retrouvé nulle part. Les registres du Douanier (`NPC_GRA_71`) disent « Jamais sorti ».', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_08', 'NPC_GRA_74', 'K2', '{"monture","systeme"}', '« Les bêtes sentent. Elles savent quand quelque chose arrive. Depuis un mois, elles ne dorment plus. »', '`QUEST:QST_GRA_MONTURE_HENNIT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_09', 'NPC_GRA_74', 'K3', '{"monture_hennit","instabilité_seed"}', 'Les montures hennissent et refuchent la nuit car elles perçoivent l''instabilité du seed matériel — leurs sens animaux captent les warp du Noyau que les Gnomes ignorent.', NULL, '*(il caresse le lézard)* « Lui, il sait des choses. Il ne peut pas me le dire. Mais il tremble. Et ça suffit pour me faire peur. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_74_10', 'NPC_GRA_74', 'KX', '{"*(tout le reste)*"}', '*(il essuie le flanc d''un cheval de pierre)* « La pierre est froide. Mais la bête est chaude. Et elle a peur. Pourquoi un rocher aurait peur ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_01', 'NPC_GRA_75', 'K0', '{"ferrure","montures"}', 'Ferrage de montures, types de fers par race, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_02', 'NPC_GRA_75', 'K0', '{"porte","granzam"}', 'Description de la Porte de Granzam, flux de voyageurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_03', 'NPC_GRA_75', 'K0', '{"gnome","metal"}', 'Son métier de maréchal-ferrant gnome, traditions de forge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_04', 'NPC_GRA_75', 'K1', '{"sabot","marque"}', 'Certains sabots portent des marques de roche inconnue sous Granzam', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_05', 'NPC_GRA_75', 'K1', '{"fer","son creux"}', 'Depuis peu, certains fers « sonnent creux » après un jour de route', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_06', 'NPC_GRA_75', 'K1', '{"voyageurs","destinations"}', 'Les voyageurs qu''il ferre viennent de toutes les routes — une augmentation du trafic', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_07', 'NPC_GRA_75', 'K2', '{"fer","provenance"}', 'Le fer qu''il utilise n''est plus le même depuis deux mois — le minerai a une teinte grise anormale', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_08', 'NPC_GRA_75', 'K2', '{"roche","filon"}', 'Un marchand lui a dit qu''un filon s''était déplacé sous la montagne — le Filonant', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_09', 'NPC_GRA_75', 'K3', '{"fer","sonde"}', 'Le fer gris est en réalité un alliage de surface mêlé à un minerai qui n''affleure nulle part — les fers qui sonnent creux sont en train de fondre de l''intérieur, comme si la roche les « buvait » pour se nourrir, un signe que le Noyau de Pierre aspire les métaux de la surface dans les strates profondes', NULL, '*(il tape sur l''enclume)* « Un fer qui sonne creux ? C''est l''usure, p''tit. L''usure, ça arrive. Mes fers sont bons, je les fais moi-même. Le minerai vient de la Mine — c''est la même veine depuis cent ans. Y a rien d''anormal. Rien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_75_10', 'NPC_GRA_75', 'KX', '{"*(hors sujet)*"}', '« Tu parles de cailloux ? Moi je parle de fers à cheval. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_01', 'NPC_GRA_76', 'K0', '{"porte","horaires"}', 'La Porte ferme à minuit, rouvre à l''aube — aucun passe-droit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_02', 'NPC_GRA_76', 'K0', '{"granzam","securite"}', 'Les procédures de sécurité nocturnes de Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_03', 'NPC_GRA_76', 'K0', '{"rempart","ouest"}', 'Description du rempart ouest — le plus sombre, aucune torche', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_04', 'NPC_GRA_76', 'K1', '{"pas","seuls"}', 'Des pas montent le rempart ouest toutes les nuits vers 2h — jamais de descente', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_05', 'NPC_GRA_76', 'K1', '{"inspection","traces"}', 'Il a inspecté trois fois — zéro trace, zéro poussière déplacée', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_06', 'NPC_GRA_76', 'K1', '{"marechal","fer"}', 'Le Maréchal `NPC_GRA_75` lui a dit que ses fers « sonnent creux » la nuit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_07', 'NPC_GRA_76', 'K2', '{"pas","rythme"}', 'Les pas ont un rythme régulier — comme une patrouille — mais il n''y a personne', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_08', 'NPC_GRA_76', 'K2', '{"eclaireur","confirmation"}', 'L''Éclaireur `NPC_GRA_50` a aussi vu des formes sur le rempart depuis les steppes — qui disparaissent en touchant le mur', '`QUEST:QST_GRA_PAS_SEULS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_09', 'NPC_GRA_76', 'K3', '{"seed","echo","marcheur"}', 'Les pas sont un écho de seed — le Cardinal rejoue des séquences de pathfinding de PNJ supprimés, des « fantômes de mobs » qui n''existent plus dans la base de données mais dont les scripts de déplacement tournent encore en boucle sur le serveur', NULL, '*(il serre sa lance)* « J''ai rien entendu. La nuit, on entend toujours des trucs. Faut pas leur prêter attention. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_76_10', 'NPC_GRA_76', 'KX', '{"*(hors sujet)*"}', '*(il regarde l''horizon sombre)* « La nuit porte conseil, dit-on. Moi j''dis qu''elle porte des pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_01', 'NPC_GRA_77', 'K0', '{"accueil","visiteurs"}', 'Accueil des visiteurs — procédure, registre d''entrée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_02', 'NPC_GRA_77', 'K0', '{"granzam","porte jour"}', 'La vie à la Porte de Granzam pendant la journée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_03', 'NPC_GRA_77', 'K0', '{"laissez_passer"}', 'Types de laissez-passer — commerce, pèlerinage, mine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_04', 'NPC_GRA_77', 'K1', '{"ombre","pilier"}', 'Une ombre apparaît sur le pilier gauche à midi — sans personne pour la projeter', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_05', 'NPC_GRA_77', 'K1', '{"marechal","aveugle"}', 'Le Maréchal ne voit rien quand il lui montre l''ombre', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_06', 'NPC_GRA_77', 'K1', '{"guide","temoin"}', 'Le Guide `NPC_GRA_79` a vu l''ombre bouger — « comme un drap qu''on retire »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_07', 'NPC_GRA_77', 'K2', '{"ombre","independante"}', 'L''ombre se déplace parfois — elle change de pilier d''un jour à l''autre', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_08', 'NPC_GRA_77', 'K2', '{"trace","absence"}', 'Il a touché l''ombre — sa main est passée au travers, mais elle était froide', '`QUEST:QST_GRA_OMBRE_MAITRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_09', 'NPC_GRA_77', 'K3', '{"ombre","faille","rendu"}', 'L''ombre est un défaut de rendu du client de jeu — un artefact graphique généré par un plantage du moteur d''ombres portées. Le Cardinal ne peut pas la supprimer car elle est liée à un objet « père » supprimé. C''est un vestige visuel de la version beta du décor', NULL, '*(il rit jaune)* « C''est juste un pilier. Les piliers ont des ombres. Tout le monde sait ça. Même quand y a pas de soleil. C''est… normal. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_77_10', 'NPC_GRA_77', 'KX', '{"*(hors sujet)*"}', '*(il désigne la herse)* « Belle porte, hein ? Fer forgé, mithril incrusté. Dix mille heures de travail. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_01', 'NPC_GRA_78', 'K0', '{"coursier","itineraire"}', 'Sa tournée quotidienne — Porte, Halle, Conseil, Mine', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_02', 'NPC_GRA_78', 'K0', '{"message","transport"}', 'Service de messagerie interne de Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_03', 'NPC_GRA_78', 'K0', '{"granzam","circulation"}', 'Les axes de circulation dans Granzam — il les connaît tous', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_04', 'NPC_GRA_78', 'K1', '{"pli","perte"}', 'Il a perdu un pli scellé pour le Lord — l''encre a coulé en tombant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_05', 'NPC_GRA_78', 'K1', '{"parchemin","fragment"}', 'Des fragments de texte apparaissent dans ses poches — il ne les a pas écrits', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_06', 'NPC_GRA_78', 'K1', '{"vice_chancelier","message"}', 'Le Vice-Chancelier `NPC_GRA_27` lui a confié le pli — « urgent et confidentiel »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_07', 'NPC_GRA_78', 'K2', '{"encre","disparition"}', 'L''encre du pli se dissout au contact de l''air — comme un message à durée limitée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_08', 'NPC_GRA_78', 'K2', '{"lord","absence"}', 'Il n''a jamais remis le pli au Lord — il n''a pas trouvé la Salle du Conseil ce jour-là, les couloirs avaient changé', '`QUEST:QST_GRA_PLI_PERDU`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_09', 'NPC_GRA_78', 'K3', '{"pli","seed","message"}', 'Le pli n''était pas un message politique — c''était un fichier de configuration du Cardinal, encodé dans une encre thermosensible qui se désintègre à l''air libre. Le Vice-Chancelier transmet des mises à jour système déguisées en courrier officiel', NULL, '*(il regarde sa sacoche vide)* « J''ai dû le perdre. C''est pas grave. C''était juste un mot. Les mots, ça se perd. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_78_10', 'NPC_GRA_78', 'KX', '{"*(hors sujet)*"}', '*(il boit une gourde à toute vitesse)* « Coursier, c''est courir. Je cours, je livre, je repars. Pas le temps de causer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_01', 'NPC_GRA_79', 'K0', '{"guide","visite"}', 'Visites guidées de Granzam — circuits, durée, tarifs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_02', 'NPC_GRA_79', 'K0', '{"granzam","monuments"}', 'Description des monuments de Granzam pour les visiteurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_03', 'NPC_GRA_79', 'K0', '{"accueil","nouveaux"}', 'Procédure d''accueil des nouveaux joueurs à Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_04', 'NPC_GRA_79', 'K1', '{"visiteur","sans ombre"}', 'Un visiteur sans ombre — aucune projection sous aucun éclairage', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_05', 'NPC_GRA_79', 'K1', '{"couloir","impasse"}', 'Le visiteur a disparu dans un couloir sans issue — le mur du fond était chaud', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_06', 'NPC_GRA_79', 'K1', '{"huissier","reaction"}', 'L''Huissier `NPC_GRA_28` a su tout de suite de qui il parlait — « encore un »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_07', 'NPC_GRA_79', 'K2', '{"visiteur","description"}', 'Le visiteur portait une cape grise, aucune odeur de pierre, pas de poussière de granit', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_08', 'NPC_GRA_79', 'K2', '{"disparitions","multiple"}', 'L''Huissier lui a dit que d''autres visiteurs sans ombre sont entrés — ils ne sont jamais ressortis', '`QUEST:QST_GRA_VISITEUR_OMBRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_09', 'NPC_GRA_79', 'K3', '{"visiteur","npc_admin"}', 'Le visiteur sans ombre était un PNJ d''administration — un « technicien » du Cardinal qui patche le serveur en direct. Il n''a pas d''ombre car le moteur de rendu ne lui alloue pas de budget graphique pour les ombres — c''est un NPC de debug qui n''existe pas dans le build final', NULL, '*(il rit nerveusement)* « Une cape grise, tu dis ? Ah non, je… je confonds peut-être avec un marchand. Beaucoup de marchands portent des capes grises. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_79_10', 'NPC_GRA_79', 'KX', '{"*(hors sujet)*"}', '*(il sort un plan de la ville)* « Tu veux voir la carte ? Je la connais par cœur. Demande-moi n''importe quelle rue ! »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_01', 'NPC_GRA_80', 'K0', '{"autel","resurrection"}', 'Fonctionnement de l''Autel de Résurrection de Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_02', 'NPC_GRA_80', 'K0', '{"chant","litanie"}', 'Les litanies de pierre — chants rituels de résurrection', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_03', 'NPC_GRA_80', 'K0', '{"pretre","role"}', 'Son rôle de Prêtre du Socle — gardien des rituels', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_04', 'NPC_GRA_80', 'K1', '{"resurrection","excessive"}', 'Un mineur ressuscité est revenu sans aucune séquelle — « trop parfait »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_05', 'NPC_GRA_80', 'K1', '{"chant","amplification"}', 'Son chant résonne dans l''autel — le son revient multiplié', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_06', 'NPC_GRA_80', 'K1', '{"autel","pierre"}', 'La pierre de l''autel est chaude au toucher — anormal pour du granit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_07', 'NPC_GRA_80', 'K2', '{"resonance","coeur"}', 'La résonance de son chant correspond à la fréquence du sous-sol du Conseil', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_08', 'NPC_GRA_80', 'K2', '{"acolyte","observation"}', 'L''Acolyte `NPC_GRA_82` a vu l''autel « respirer » pendant le chant', '`QUEST:QST_GRA_CHANT_TROP_FORT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_09', 'NPC_GRA_80', 'K3', '{"autel","seed","amplification"}', 'L''Autel de Résurrection est connecté au Cœur de Granit `NPC_GRA_00` — le granit amplifie la magie de résurrection en puisant directement dans le seed de régénération du monde. Chaque résurrection consomme une infime portion de la seed, ce qui use la matrice du monde plus vite que prévu', NULL, '*(il cesse de chanter net)* « Le chant est un don de la pierre. Je ne contrôle pas ce qu''elle donne. Si elle donne trop… ce n''est pas mon affaire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_80_10', 'NPC_GRA_80', 'KX', '{"*(hors sujet)*"}', '*(il ajuste son étole de granit)* « Les âmes ont besoin de chansons, pas de questions. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_01', 'NPC_GRA_81', 'K0', '{"calcite","veines"}', 'Lecture des veines de calcite — art divinatoire minéral', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_02', 'NPC_GRA_81', 'K0', '{"autel","rites"}', 'Rites secondaires de l''Autel — purification, bénédiction', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_03', 'NPC_GRA_81', 'K0', '{"silence","voeu"}', '« Elle a fait vœu de silence. » (c''est ce qu''ils disent)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_04', 'NPC_GRA_81', 'K1', '{"silence","cause"}', 'Elle a crié en regardant la calcite un soir — puis plus jamais parlé', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_05', 'NPC_GRA_81', 'K1', '{"ardoise","message"}', 'Elle écrit des messages d''alerte — « N''écoutez pas la pierre », « La calcite ment »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_06', 'NPC_GRA_81', 'K1', '{"acolyte","craie"}', 'L''Acolyte `NPC_GRA_82` lui apporte de la craie — elle en use des pains entiers par jour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_07', 'NPC_GRA_81', 'K2', '{"calcite","carte"}', 'Elle a vu une carte de Granzam dans les veines de calcite — avec des galeries qui n''existent pas', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_08', 'NPC_GRA_81', 'K2', '{"veines","sang"}', 'La calcite était rouge cette nuit-là — « comme si la pierre saignait »', '`QUEST:QST_GRA_SILENCE_CALCITE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_09', 'NPC_GRA_81', 'K3', '{"calcite","reseau","surveillance"}', 'Les veines de calcite sont un réseau naturel de transmission de données du Cardinal — elles relient tous les autels de résurrection du jeu. Ce qu''elle a vu dans la calcite, c''est un flux de données brutes : les enregistrements de mort de tous les joueurs de Granzam, classés par seed d''âme. La calcite est une fibre optique magique', NULL, '*(elle efface son ardoise d''un geste sec et écrit)* « Je ne parle pas. La pierre non plus. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_81_10', 'NPC_GRA_81', 'KX', '{"*(hors sujet)*"}', '*(elle hausse les épaules et retourne à sa calcite)*', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_01', 'NPC_GRA_82', 'K0', '{"acolyte","novice"}', 'Sa formation — nettoyage, encens, préparation des rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_02', 'NPC_GRA_82', 'K0', '{"autel","entretien"}', 'L''entretien quotidien de l''Autel de Résurrection', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_03', 'NPC_GRA_82', 'K0', '{"granzam","clergé"}', 'Hiérarchie du clergé de la pierre à Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_04', 'NPC_GRA_82', 'K1', '{"pas","entite"}', 'Des pas traversent l''autel la nuit — jamais de jour', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_05', 'NPC_GRA_82', 'K1', '{"pierres","deplacees"}', 'Il a posé des repères — les pierres sont déplacées chaque matin', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_06', 'NPC_GRA_82', 'K1', '{"pretresse","ouie"}', 'La Prêtresse `NPC_GRA_81` a hoché la tête quand il lui en a parlé — elle les entend aussi', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_07', 'NPC_GRA_82', 'K2', '{"trajectoire","autel"}', 'Les pas forment un cercle autour de l''autel — exactement le périmètre du socle', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_08', 'NPC_GRA_82', 'K2', '{"pas","coeur"}', 'Les pas viennent du sous-sol — ils montent par les fondations de l''autel', '`QUEST:QST_GRA_PAS_AUTEL`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_09', 'NPC_GRA_82', 'K3', '{"pas","seed","fantome"}', 'Les pas sont ceux d''un prêtre supprimé de la base de données — un NPC retiré du jeu il y a trois ans, mais dont le script de marche continue de s''exécuter sur le serveur, lié à l''autel comme point d''ancrage', NULL, '*(il pâlit)* « C''est une vieille histoire. Le Prêtre dit que ce sont les âmes des mineurs. Mais j''ai regardé dans les registres. Le rythme des pas correspond à un seul homme. Un prêtre radié. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_82_10', 'NPC_GRA_82', 'KX', '{"*(hors sujet)*"}', '*(il frotte une tache sur l''autel)* « La pierre, ça se nettoie. Les taches, ça part toujours. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_01', 'NPC_GRA_83', 'K0', '{"rite","granit"}', 'Le Chant de Granit — rite hebdomadaire, horaires', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_02', 'NPC_GRA_83', 'K0', '{"vestale","role"}', 'Son rôle de Vestale — gardienne des rites majeurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_03', 'NPC_GRA_83', 'K0', '{"autel","ceremonies"}', 'Les cérémonies de l''Autel — pleine lune, équinoxe de pierre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_04', 'NPC_GRA_83', 'K1', '{"chant","assourdissant"}', 'Son chant fissure les murs maintenant — ça n''arrivait pas avant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_05', 'NPC_GRA_83', 'K1', '{"voix","involontaire"}', 'Une fois le rite commencé, elle ne peut plus s''arrêter — sa voix « continue seule »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_06', 'NPC_GRA_83', 'K1', '{"acolyte","souffrance"}', 'L''Acolyte `NPC_GRA_82` saigne des oreilles après les rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_07', 'NPC_GRA_83', 'K2', '{"voix","frequence"}', 'Sa voix a changé de fréquence — elle est plus grave qu''avant, en dessous du seuil humain', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_08', 'NPC_GRA_83', 'K2', '{"rite","hors_controle"}', 'Le dernier rite a ouvert une fissure dans le sol de l''autel — on voit une lueur en dessous', '`QUEST:QST_GRA_CHANT_FISSURE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_09', 'NPC_GRA_83', 'K3', '{"chant","seed","resonance"}', 'Le Chant de Granit résonne à la fréquence exacte du Cœur de Granit `NPC_GRA_00` — le rite est en réalité une synchronisation de seed. Le Cardinal utilise la voix de la Vestale pour calibrer la résonance du monde souterrain. Les fissures sont des surcharges de seed quand la synchronisation échoue', NULL, '*(elle détourne le regard)* « Je ne suis qu''une chanteuse. La pierre décide de la note. Si elle veut une note qui casse, je la chante. Point. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_83_10', 'NPC_GRA_83', 'KX', '{"*(hors sujet)*"}', '*(elle inspire profondément, prête à chanter)* « Recule-toi. Ça va vibrer. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_01', 'NPC_GRA_84', 'K0', '{"necromancie","gemmes"}', 'La nécromancie par gemmes — principes de base', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_02', 'NPC_GRA_84', 'K0', '{"mine","mithril interdit"}', 'La Mine de Mithril Interdite — accès, dangers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_03', 'NPC_GRA_84', 'K0', '{"granzam","excommunié"}', 'Son excommunication — banni du clergé de la pierre', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_04', 'NPC_GRA_84', 'K1', '{"gemme","enregistrement"}', 'Les gemmes noires enregistrent les derniers instants des défunts', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_05', 'NPC_GRA_84', 'K1', '{"mort","voix"}', 'Un mort ranimé a parlé — « la poutre était sciée, c''était pas un accident »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_06', 'NPC_GRA_84', 'K1', '{"fossoyeur","livraison"}', 'Le Fossoyeur `NPC_GRA_85` lui livre des corps de mineurs « morts par accident »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_07', 'NPC_GRA_84', 'K2', '{"gemme","accusation"}', 'La gemme du mineur contient l''image d''un contremaître qui a scié l''étai', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_08', 'NPC_GRA_84', 'K2', '{"garde","silence"}', 'Les Gardes du Conseil `NPC_GRA_86` ont fermé l''enquête sur cette mort', '`QUEST:QST_GRA_GEMME_ACCUSE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_09', 'NPC_GRA_84', 'K3', '{"gemme_noire","seed_ame"}', 'Les gemmes noires sont des réceptacles de seed — elles copient la seed d''âme du joueur défunt et la rejouent dans un corps vide. Le Cardinal a créé ces gemmes pour sauvegarder les âmes des joueurs, mais la nécromancie les détourne pour interroger les morts : chaque gemme est un fragment de la matrice du monde qui contient l''historique complet des interactions du défunt', NULL, '*(il serre la gemme dans son poing)* « Les morts devraient se taire. Mes gemmes, elles les font parler. Parfois trop. Va-t''en. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_84_10', 'NPC_GRA_84', 'KX', '{"*(hors sujet)*"}', '*(il polît une gemme noire)* « J''ai pas de conseil à donner. J''ai des morts à faire parler. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_01', 'NPC_GRA_85', 'K0', '{"fossoyeur","tombes"}', 'L''inhumation dans la roche — creusement, scellement, rites', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_02', 'NPC_GRA_85', 'K0', '{"granzam","cimetiere"}', 'Le cimetière de granit — cavités funéraires dans les parois', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_03', 'NPC_GRA_85', 'K0', '{"morts","mineurs"}', 'Les morts de la mine — statistiques, causes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_04', 'NPC_GRA_85', 'K1', '{"corps","fremissement"}', 'Les corps frémissent après l''inhumation — « la pierre tremble »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_05', 'NPC_GRA_85', 'K1', '{"cavite","vibration"}', 'Il a posé la main sur une cavité scellée — elle vibrait à 0,5 Hz', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_06', 'NPC_GRA_85', 'K1', '{"necromancien","visites"}', 'Le Nécromancien `NPC_GRA_84` vient parfois « récupérer » des corps avant l''inhumation', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_07', 'NPC_GRA_85', 'K2', '{"corps","plusieurs"}', 'Cinq cavités vibrent maintenant — toutes du côté de la faille −47', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_08', 'NPC_GRA_85', 'K2', '{"sceau","granit"}', 'Il a doublé l''épaisseur de granit sur les cavités — les vibrations traversent quand même', '`QUEST:QST_GRA_FREMISSEMENTS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_09', 'NPC_GRA_85', 'K3', '{"corps","seed","resonance"}', 'Les corps ne frémissent pas — ce sont les gemmes noires implantées par le Nécromancien `NPC_GRA_84` qui résonnent avec le Cœur de Granit `NPC_GRA_00`. Chaque gemme enterrée est une balise qui communique avec le seed matériel. Les morts sont des antennes', NULL, '*(il crache par terre)* « Les morts, ça bouge pas. C''est la pierre qui bouge. C''est tout. J''ai rien à ajouter. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_85_10', 'NPC_GRA_85', 'KX', '{"*(hors sujet)*"}', '*(il taille une pierre tombale)* « Celle-ci, c''est pour le mineur de la semaine dernière. Bel homme. Bon mineur. La roche l''a repris. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_01', 'NPC_GRA_86', 'K0', '{"garde","conseil"}', 'Son rôle — garde rapprochée du Lord et du Conseil', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_02', 'NPC_GRA_86', 'K0', '{"salle","securite"}', 'Sécurité de la Salle du Conseil — accès, procédures', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_03', 'NPC_GRA_86', 'K0', '{"granzam","elite"}', 'Le corps de garde d''élite de Granzam — recrutement, entraînement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_04', 'NPC_GRA_86', 'K1', '{"lord","vacillement"}', 'Le Lord est devenu flou pendant dix secondes — « comme un mirage »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_05', 'NPC_GRA_86', 'K1', '{"clignement","absent"}', 'Le Lord ne cligne pas des yeux — jamais. Il l''a chronométré', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_06', 'NPC_GRA_86', 'K1', '{"vice_chancelier","regard"}', 'Le Vice-Chancelier `NPC_GRA_27` regarde le Lord avec un drôle d''air — « pas de la peur »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_07', 'NPC_GRA_86', 'K2', '{"lord","pixel"}', 'Pendant le vacillement, il a vu des lignes — « des chiffres et des lettres sous la peau »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_08', 'NPC_GRA_86', 'K2', '{"ombre","conseil"}', 'L''Ombre du Conseil `NPC_GRA_88` l''observe — « il sait que j''ai vu quelque chose »', '`QUEST:QST_GRA_LORD_VACILLE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_09', 'NPC_GRA_86', 'K3', '{"lord","hologramme","seed"}', 'Le Lord Gnome est un PNG holographique — un modèle 3D animé par un script d''IA administrative du Cardinal. Son « corps » est rendu en temps réel à partir d''une seed de personnalité. Le vacillement était une surcharge de rendu : le Cardinal patché le modèle en direct. Le vrai dirigeant de Granzam, c''est le Conseil algorithmique', NULL, '*(il se raidit)* « Le Lord est le Lord. Je ne discute pas les ordres. Je ne discute pas la réalité. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_86_10', 'NPC_GRA_86', 'KX', '{"*(hors sujet)*"}', '*(il ajuste son armure)* « Tu veux entrer au Conseil ? Fais une demande. Sinon, circule. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_01', 'NPC_GRA_87', 'K0', '{"intendant","tresor"}', 'Gestion du trésor de Granzam — budget, réserves', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_02', 'NPC_GRA_87', 'K0', '{"or","monnaie"}', 'La monnaie de Granzam — pièces de granit, d''or, de mithril', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_03', 'NPC_GRA_87', 'K0', '{"granzam","finances"}', 'Les finances de la cité — impôts, taxes minières', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_04', 'NPC_GRA_87', 'K1', '{"piece","son mou"}', 'Des pièces d''or sonnent « mou » — comme du plomb doré', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_05', 'NPC_GRA_87', 'K1', '{"leprechaun","analyse"}', 'Le Marchand Leprechaun `NPC_GRA_91` a confirmé la falsification', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_06', 'NPC_GRA_87', 'K1', '{"chambre","acces"}', 'Seuls lui et le Vice-Chancelier ont la clé de la chambre forte', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_07', 'NPC_GRA_87', 'K2', '{"vice_chancelier","fonds"}', 'Le Vice-Chancelier `NPC_GRA_27` a fait un retrait important il y a deux mois — « pour un projet du Conseil »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_08', 'NPC_GRA_87', 'K2', '{"plomb","origine"}', 'Le plomb sous l''or vient de la Mine de Mithril — un minerai de rebut', '`QUEST:QST_GRA_OR_FALSIFIE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_09', 'NPC_GRA_87', 'K3', '{"or","seed","duplication"}', 'L''or falsifié est créé par duplication de seed — quelqu''un utilise le Cœur de Granit `NPC_GRA_00` pour dupliquer des ressources en copiant la signature de seed des pièces originales. Le plomb est le matériau hôte, la pellicule d''or est une impression de seed. Le Vice-Chancelier finance quelque chose avec cette fausse monnaie', NULL, '*(il referme le coffre à clé)* « Je me suis trompé. Les pièces sont bonnes. La réverbération de la salle, sans doute. Tout va bien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_87_10', 'NPC_GRA_87', 'KX', '{"*(hors sujet)*"}', '*(il compte des pièces sur son bureau)* « L''or, ça s''compte. Les secrets, ça se compte pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_01', 'NPC_GRA_88', 'K0', '{"secretaire","conseil"}', 'Son rôle officiel — prise de notes, archivage des débats', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_02', 'NPC_GRA_88', 'K0', '{"espionnage","granzam"}', 'Les pratiques d''espionnage à Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_03', 'NPC_GRA_88', 'K0', '{"alliances","granzam"}', 'Les alliances officielles de Granzam — Brokkheim, Alne, Voulg', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_04', 'NPC_GRA_88', 'K1', '{"leprechaun","secret"}', 'Le Marchand Leprechaun `NPC_GRA_91` négocie avec Voulg en secret', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_05', 'NPC_GRA_88', 'K1', '{"salamander","balrog"}', 'Un messager a dit « Le Balrog `NPC_VOU_04` sait. Il faut le faire taire. »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_06', 'NPC_GRA_88', 'K1', '{"trafic","mithril"}', 'Du mithril part de Granzam vers des destinataires inconnus — sans passer par la comptabilité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_07', 'NPC_GRA_88', 'K2', '{"trafiquant","reseau"}', 'Le Trafiquant `NPC_GRA_93` est le nœud du réseau — gemmes, mithril, informations', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_08', 'NPC_GRA_88', 'K2', '{"vice_chancelier","financement"}', 'Le Vice-Chancelier `NPC_GRA_27` finance un projet — l''or falsifié de l''Intendant `NPC_GRA_87`', '`QUEST:QST_GRA_OMBRE_DU_CONSEIL`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_09', 'NPC_GRA_88', 'K3', '{"reseau","inter_cites","seed"}', 'Le trafic de gemmes et de mithril entre Granzam, Brokkheim, Voulg, Alne et Gatorisande n''est pas un simple marché noir — c''est un réseau de distribution de seeds de duplication. Les gemmes noires du Nécromancien `NPC_GRA_84` transportent des fragments de seed qui permettent de dupliquer des ressources d''une ville à l''autre, créant une inflation parallèle de l''économie du jeu', NULL, '*(il range ses notes)* « Je ne suis qu''un secrétaire. Je note ce que j''entends. Je n''interprète pas. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_88_10', 'NPC_GRA_88', 'KX', '{"*(hors sujet)*"}', '*(il écrit dans un registre)* « Les mots écrits restent. Les mots parlés s''envolent. Mais moi, je les rattrape. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_01', 'NPC_GRA_89', 'K0', '{"memorial","stèle"}', 'Le Mémorial des Mineurs — histoire, inscriptions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_02', 'NPC_GRA_89', 'K0', '{"granzam","hommage"}', 'Les hommages aux morts de la mine à Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_03', 'NPC_GRA_89', 'K0', '{"names","gravure"}', 'La gravure des noms — art du burin sur granit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_04', 'NPC_GRA_89', 'K1', '{"nom","resonance"}', 'Un nom gravé résonne — il l''a entendu prononcé par la pierre', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_05', 'NPC_GRA_89', 'K1', '{"lettre","chaleur"}', 'Les lettres de certains noms sont chaudes au toucher', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_06', 'NPC_GRA_89', 'K1', '{"voix","memorial"}', 'Il a touché le nom d''un mineur mort en −47 — il a entendu « je suis encore là »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_07', 'NPC_GRA_89', 'K2', '{"noms","plusieurs"}', 'Cinq noms sont chauds maintenant — tous des morts de la strate −47', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_08', 'NPC_GRA_89', 'K2', '{"necromancien","consultation"}', 'Le Nécromancien `NPC_GRA_84` vient lire les noms chauds — « il cherche quelque chose »', '`QUEST:QST_GRA_NOMS_RESONNANTS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_09', 'NPC_GRA_89', 'K3', '{"memorial","seed","sauvegarde"}', 'Le mémorial est un point de sauvegarde de seed — chaque nom est lié à la seed d''âme du défunt stockée dans le Cœur de Granit `NPC_GRA_00`. Les noms chauds sont ceux dont la seed est encore active : les morts dont l''âme n''a pas été effacée du serveur. Ce sont des sauvegardes zombies', NULL, '*(il recule d''un pas)* « Les pierres sont froides. Les noms sont froids. Tout va bien. Laisse le mémorial tranquille. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_89_10', 'NPC_GRA_89', 'KX', '{"*(hors sujet)*"}', '*(il passe un chiffon sur la stèle)* « La poussière de granit, ça s''essuie. Les noms, non. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_01', 'NPC_GRA_90', 'K0', '{"salamander","refuge"}', 'Sa vie de réfugié dans les Steppes de Granit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_02', 'NPC_GRA_90', 'K0', '{"voulg","tribu"}', 'La tribu Salamander de Voulg — coutumes, hiérarchie', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_03', 'NPC_GRA_90', 'K0', '{"steppes","survie"}', 'La survie dans les Steppes de Granit — gibier, abris, dangers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_04', 'NPC_GRA_90', 'K1', '{"balrog","fuite"}', 'Balrog `NPC_VOU_04` a organisé sa fuite — « il a ouvert la porte sud »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_05', 'NPC_GRA_90', 'K1', '{"raid","commanditaire"}', 'Le raid contre Granzam était commandité par des trafiquants — « des marchands d''ombre »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_06', 'NPC_GRA_90', 'K1', '{"leprechaun","menace"}', 'Le Marchand Leprechaun `NPC_GRA_91` l''a repéré — « il sait que je suis là, il va parler »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_07', 'NPC_GRA_90', 'K2', '{"balrog","secret"}', 'Balrog sait où se trouve le réseau de trafic de gemmes entre Voulg et Granzam', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_08', 'NPC_GRA_90', 'K2', '{"trafiquant","reseau"}', 'Le trafic passe par les Steppes — des convois de nuit, sans bannière', '`QUEST:QST_GRA_SALAMANDER_FUITE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_09', 'NPC_GRA_90', 'K3', '{"voulg","balrog","seed"}', 'Balrog `NPC_VOU_04` n''est pas un simple Salamander — il est un gardien de seed locale pour Voulg, comme le Lord Gnome pour Granzam. Sa vraie nature est un secret que le Cardinal protège', NULL, '*(il crache du feu par les narines)* « Balrog est mort. J''ai rien à dire. Laisse couler. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_90_10', 'NPC_GRA_90', 'KX', '{"*(hors sujet)*"}', '*(il attise un feu de camp)* « Le feu, ça réchauffe. Ça brûle. Les deux sont vrais. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_01', 'NPC_GRA_91', 'K0', '{"commerce","gemmes"}', 'Achat/vente de gemmes brutes et taillées — prix, qualités', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_02', 'NPC_GRA_91', 'K0', '{"brokkheim","leprechaun"}', 'La cité de Brokkheim — culture Leprechaun, commerce', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_03', 'NPC_GRA_91', 'K0', '{"mithril","echange"}', 'Échange de mithril — lingots, armes, outils', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_04', 'NPC_GRA_91', 'K1', '{"voulg","negociation"}', 'Il négocie avec Voulg — des gemmes contre des faveurs Salamander', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_05', 'NPC_GRA_91', 'K1', '{"balrog","contact"}', 'Balrog `NPC_VOU_04` est son contact direct à Voulg', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_06', 'NPC_GRA_91', 'K1', '{"forgeson","zarn"}', 'Il envoie du mithril à Forgeson, maître forgeron de Zarn — « pour des commandes spéciales »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_07', 'NPC_GRA_91', 'K2', '{"gemmes","fausses"}', 'Certaines gemmes qu''il vend sont des « copies » — vraies à l''œil, fausses à la loupe', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_08', 'NPC_GRA_91', 'K2', '{"trafiquant","reseau"}', 'Le Trafiquant `NPC_GRA_93` est son acheteur principal pour les gemmes « spéciales »', '`QUEST:QST_GRA_LEPRECHAUN_DOUBLE_JEU`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_09', 'NPC_GRA_91', 'K3', '{"gemmes","seed","duplication"}', 'Les fausses gemmes sont produites par duplication de seed — le Trafiquant `NPC_GRA_93` utilise une gemme-souche du Nécromancien `NPC_GRA_84` pour copier la signature de gemmes rares, créant des contrefaçons parfaites qui trompent même les experts du Conseil', NULL, '*(il rit)* « Des fausses gemmes ? Moi ? P''tit, tu regardes trop d''ombres. Mes gemmes sont pures comme les rivières de Brokkheim. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_91_10', 'NPC_GRA_91', 'KX', '{"*(hors sujet)*"}', '*(il sort un sachet de gemmes)* « Regarde celle-ci — elle vient de la strate −30. Une beauté, non ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_01', 'NPC_GRA_92', 'K0', '{"alne","diplomatie"}', 'La cité d''Alne — culture Sylphe, politique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_02', 'NPC_GRA_92', 'K0', '{"commerce","inter_cites"}', 'Les accords commerciaux entre Alne et Granzam', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_03', 'NPC_GRA_92', 'K0', '{"courtier","role"}', 'Le métier de courtier diplomatique', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_04', 'NPC_GRA_92', 'K1', '{"bomil","mission"}', 'Bomil `NPC_ALN_93` l''a envoyé pour enquêter sur le trafic de gemmes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_05', 'NPC_GRA_92', 'K1', '{"leprechaun","identifie"}', 'Il a identifié le Marchand Leprechaun `NPC_GRA_91` comme un trafiquant', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_06', 'NPC_GRA_92', 'K1', '{"trafiquant","reseau"}', 'Il suspecte le Trafiquant `NPC_GRA_93` d''être le nœud du réseau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_07', 'NPC_GRA_92', 'K2', '{"ombre","surveillance"}', 'L''Ombre du Conseil `NPC_GRA_88` le suit — « un espion qui en espionne un autre »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_08', 'NPC_GRA_92', 'K2', '{"gemmes","seed"}', 'Il a découvert que les gemmes du trafic sont des répliques de seed — pas des gemmes naturelles', '`QUEST:QST_GRA_COURTIER_ALNE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_09', 'NPC_GRA_92', 'K3', '{"bomil","reseau","seed"}', 'Bomil `NPC_ALN_93` cherche à contrôler le réseau de duplication de seed des gemmes pour Alne — il veut faire d''Alne le hub central de l''économie parallèle du jeu, en court-circuitant Granzam comme plaque tournante du minage', NULL, '*(il sourit, lisse sa manche)* « Bomil est un ami. Un partenaire commercial. Je ne suis qu''un messager. Les messagers ne savent rien. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_92_10', 'NPC_GRA_92', 'KX', '{"*(hors sujet)*"}', '*(il regarde par une fenêtre)* « Le vent d''Alne me manque. Ici, l''air est lourd. Chargé de pierre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_01', 'NPC_GRA_93', 'K0', '{"commerce","noir"}', 'Le marché noir de Granzam — discrétion, codes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_02', 'NPC_GRA_93', 'K0', '{"gemmes","valeur"}', 'La valeur des gemmes — rareté, pureté, poids', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_03', 'NPC_GRA_93', 'K0', '{"grande_halle","cache"}', 'Les caches de la Grande Halle — il connaît toutes les planques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_04', 'NPC_GRA_93', 'K1', '{"torvin","swilwffe"}', 'Torvin `NPC_SWI_93` lui envoie des acheteurs quatre fois par lune', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_05', 'NPC_GRA_93', 'K1', '{"ilka","gatorisande"}', 'Ilka `NPC_GAT_33` commande des gemmes noires — « pour sa collection personnelle »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_06', 'NPC_GRA_93', 'K1', '{"balrog","voulg"}', 'Balrog `NPC_VOU_04` lui fournit des gemmes brutes de Voulg en échange d''armes en mithril', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_07', 'NPC_GRA_93', 'K2', '{"gemmes","duplication"}', 'Les gemmes « noires » sont des copies — produites à partir d''une gemme-souche unique', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_08', 'NPC_GRA_93', 'K2', '{"necromancien","fournisseur"}', 'Le Nécromancien `NPC_GRA_84` est son meilleur client — « les gemmes des morts paient bien »', '`QUEST:QST_GRA_TRAFIQUANT_RESEAU`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_09', 'NPC_GRA_93', 'K3', '{"reseau","seed","inflation"}', 'Le réseau de trafic couvre cinq cités et utilise la duplication de seed pour créer des gemmes parfaites — Torvin les écoule chez les Swilwffe, Ilka chez les Gnomes de Gatorisande, Balrog chez les Salamanders. Chaque gemme dupliquée pompe une micro-fraction de la seed du monde, accélérant l''épuisement du serveur minier', NULL, '*(il recule dans l''ombre)* « J''suis qu''un petit marchand, moi. Les gemmes ? Je les trouve, je les vends. D''où elles viennent ? Demande à la montagne. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_93_10', 'NPC_GRA_93', 'KX', '{"*(hors sujet)*"}', '*(il sort une gemme de sa poche)* « Celle-ci, elle vient de la strate −40. Unique. J''t''ai déjà vue quelque part ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_01', 'NPC_GRA_94', 'K0', '{"courtage","inter_racial"}', 'Le courtage entre races — commissions, contrats', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_02', 'NPC_GRA_94', 'K0', '{"grande_halle","commerce"}', 'Le commerce légitime de la Grande Halle', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_03', 'NPC_GRA_94', 'K0', '{"races","langues"}', 'Les langues raciales qu''il parle — gnome, leprechaun, sylphe, salamander, nain', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_04', 'NPC_GRA_94', 'K1', '{"trafiquant","couverture"}', 'Il blanchit les gemmes du Trafiquant `NPC_GRA_93` via des transactions légitimes', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_05', 'NPC_GRA_94', 'K1', '{"registres","doubles"}', 'Il tient deux registres — le vrai et le « présentable »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_06', 'NPC_GRA_94', 'K1', '{"leprechaun","prete_nom"}', 'Le Marchand Leprechaun `NPC_GRA_91` signe des faux contrats pour lui', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_07', 'NPC_GRA_94', 'K2', '{"ombre","enquete"}', 'L''Ombre du Conseil `NPC_GRA_88` a inspecté ses comptes — « trois fois. Rien trouvé. »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_08', 'NPC_GRA_94', 'K2', '{"courrier_alne","rival"}', 'Le Courtier d''Alne `NPC_GRA_92` le concurrence — « un Sylphe ne me battra pas sur mon terrain »', '`QUEST:QST_GRA_COURTIER_BLANCHIMENT`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_09', 'NPC_GRA_94', 'K3', '{"reseau","toutes_cites","seed"}', 'Il est le seul à connaître l''étendue réelle du réseau : Torvin `NPC_SWI_93`, Ilka `NPC_GAT_33`, Balrog `NPC_VOU_04`, Bomil `NPC_ALN_93` — tous paient des commissions à Granzam via lui. Il est le banquier central de l''économie parallèle de seed dupliquée. Ses registres vrais contiennent la carte complète du trafic inter-cités', NULL, '*(il tapote son registre)* « Tout est en ordre. Vérifié par le Conseil. Si tu veux voir mes livres, adresse-toi au Chancelier. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_94_10', 'NPC_GRA_94', 'KX', '{"*(hors sujet)*"}', '*(il signe un parchemin)* « Les affaires sont les affaires. Les races sont les races. L''argent n''a pas de race. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_01', 'NPC_GRA_95', 'K0', '{"convoi","securite"}', 'La sécurisation des convois — itinéraires, dangers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_02', 'NPC_GRA_95', 'K0', '{"routes","commerciales"}', 'Les routes commerciales de Granzam — destinations, durées', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_03', 'NPC_GRA_95', 'K0', '{"veteran","experience"}', 'Son expérience de trente ans de convois — récits', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_04', 'NPC_GRA_95', 'K1', '{"attaque","pierre"}', 'Son dernier convoi attaqué par des « créatures de pierre » — il est le seul survivant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_05', 'NPC_GRA_95', 'K1', '{"galeries","nocturnes"}', 'Des galeries s''ouvrent la nuit sur les routes — « la montagne avale les caravanes »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_06', 'NPC_GRA_95', 'K1', '{"eclaireur","confirmation"}', 'L''Éclaireur `NPC_GRA_50` a vu les mêmes galeries depuis les remparts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_07', 'NPC_GRA_95', 'K2', '{"creatures","description"}', 'Les créatures étaient faites de granit et de calcite — elles ne saignaient pas, elles s''effritaient', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_08', 'NPC_GRA_95', 'K2', '{"route","strate_47"}', 'Les galeries nocturnes mènent toutes vers la strate −47 — « un niveau qui n''existe pas sur les cartes »', '`QUEST:QST_GRA_CONVOIS_PERDUS`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_09', 'NPC_GRA_95', 'K3', '{"creatures","mainteneurs"}', 'Les « créatures de pierre » sont des golems de maintenance du Cardinal — des scripts de défense du seed qui protègent le Cœur de Granit `NPC_GRA_00` en éliminant les caravanes qui s''approchent trop près de strates sensibles. La montagne « cache » le serveur minier', NULL, '*(il crache par terre)* « C''étaient des monstres. Des vrais. La montagne est vivante et elle a faim. J''veux plus en parler. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_95_10', 'NPC_GRA_95', 'KX', '{"*(hors sujet)*"}', '*(il regarde la route)* « La poussière, le granit, le soleil. C''est tout ce qu''il reste quand t''as perdu ton convoi. La poussière. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_01', 'NPC_GRA_96', 'K0', '{"minage","apprentissage"}', 'L''apprentissage du minage — méthodes, outils, sécurité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_02', 'NPC_GRA_96', 'K0', '{"steppes","entrainement"}', 'L''entraînement dans les Steppes de Granit — parcours, épreuves', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_03', 'NPC_GRA_96', 'K0', '{"gnome","tradition"}', 'Les traditions gnomes de transmission du métier de mineur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_04', 'NPC_GRA_96', 'K1', '{"eleves","voix"}', 'Ses élèves entendent des voix dans la pierre — « la montagne parle »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_05', 'NPC_GRA_96', 'K1', '{"pulsation","detection"}', 'Ils décrivent tous une pulsation — un battement régulier sous la roche', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_06', 'NPC_GRA_96', 'K1', '{"helga","gemme_prêt"}', 'Helga `NPC_GRA_05` lui a prêté une gemme qui amplifie le son de la roche', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_07', 'NPC_GRA_96', 'K2', '{"voix","fin_du_monde"}', 'Un élève a entendu « la fin du monde » — une prophétie de destruction de la montagne', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_08', 'NPC_GRA_96', 'K2', '{"coeur","pulsation"}', 'La pulsation vient du sous-sol du Conseil — « les élèves captent le même battement que Margrim »', '`QUEST:QST_GRA_VOIX_ROCHES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_09', 'NPC_GRA_96', 'K3', '{"coeur","seed","eleves"}', 'Les élèves les plus sensibles captent le seed du Cœur de Granit `NPC_GRA_00` via la résonance des strates — ils « entendent » littéralement les données du serveur minier qui traversent la roche. La « voix de la fin du monde » est un message d''erreur du Cardinal annonçant une corruption de seed', NULL, '*(il serre le poing)* « Les élèves ont de l''imagination. La montagne ne parle pas. C''est le vent dans les failles. Rien d''autre. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_96_10', 'NPC_GRA_96', 'KX', '{"*(hors sujet)*"}', '*(il tend une pioche à un élève)* « Frappe là. Juste là. Tu verras, la pierre s''ouvre. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_01', 'NPC_GRA_97', 'K0', '{"fondation","granzam"}', 'La fondation de Granzam — date, fondateurs, histoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_02', 'NPC_GRA_97', 'K0', '{"pierre","fondations"}', 'La Pierre des Fondations — symbole, signification', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_03', 'NPC_GRA_97', 'K0', '{"conseil","histoire"}', 'L''histoire de la Salle du Conseil — construction, rénovations', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_04', 'NPC_GRA_97', 'K1', '{"pierre","poids"}', 'La Pierre des Fondations devient plus lourde — il a dû renforcer le plancher', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_05', 'NPC_GRA_97', 'K1', '{"mesure","poids"}', 'Il a pesé la pierre — « elle n''a pas changé de masse, mais elle pèse plus »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_06', 'NPC_GRA_97', 'K1', '{"archiviste","plans"}', 'L''Archiviste `NPC_GRA_26` lui a montré les plans — la pierre est posée sur une cavité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_07', 'NPC_GRA_97', 'K2', '{"cavite","sous_sol"}', 'Sous la pierre, les plans montrent une cavité −47 — « la chambre du Cœur »', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_08', 'NPC_GRA_97', 'K2', '{"poids","coeur"}', 'La pierre pèse parce qu''elle est au-dessus du Cœur « qui grossit ou qui se remplit de données »', '`QUEST:QST_GRA_PIERRE_PESE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_09', 'NPC_GRA_97', 'K3', '{"pierre","seed","stockage"}', 'La Pierre des Fondations n''est pas un simple monument — c''est un cache-seed local, un point de stockage physique de la seed matérielle. Elle « pèse » plus lourd car le Cœur de Granit `NPC_GRA_00` y écrit des données de sauvegarde. Chaque décision du Conseil, chaque transaction, chaque mort de mineur est gravée dans la pierre en seed de backup', NULL, '*(il tousse)* « La pierre a toujours été lourde. C''est du granit. Le granit, ça pèse. C''est tout. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_97_10', 'NPC_GRA_97', 'KX', '{"*(hors sujet)*"}', '*(il pose la main sur la pierre)* « Pose la main. Tu sens ? C''est l''histoire de la cité. Ça pèse. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_01', 'NPC_GRA_98', 'K0', '{"oracle","propheties"}', 'Les prophéties de l''Oracle — consultation, rituels', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_02', 'NPC_GRA_98', 'K0', '{"veines","calcite"}', 'La lecture des veines de calcite — art divinatoire', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_03', 'NPC_GRA_98', 'K0', '{"mine","mithril"}', 'La Mine de Mithril — lieux, dangers, profondeurs', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_04', 'NPC_GRA_98', 'K1', '{"vision","eboulement"}', 'Elle a prédit l''éboulement de la galerie −22 trois jours avant', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_05', 'NPC_GRA_98', 'K1', '{"vision","arrivee"}', 'Elle a annoncé l''arrivée du Marchand Leprechaun `NPC_GRA_91` avant qu''il n''entre en ville', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_06', 'NPC_GRA_98', 'K1', '{"margrim","partage"}', 'Margrim `NPC_GRA_06` vient la voir chaque semaine — il compare ses visions à ses relevés sismiques', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_07', 'NPC_GRA_98', 'K2', '{"vision","maintenance"}', 'Elle a vu « un œil qui s''éteint et se rallume » — description exacte d''un redémarrage du serveur', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_08', 'NPC_GRA_98', 'K2', '{"vision","faille"}', '« La montagne saigne parfois » — une vision de la calcite rouge que la Prêtresse `NPC_GRA_81` a aussi vue', '`QUEST:QST_GRA_ORACLE_VEINES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_09', 'NPC_GRA_98', 'K3', '{"oracle","terminal","cardinal"}', 'L''Oracle ne prédit pas l''avenir — elle décode les flux de données du Cardinal qui traversent la calcite. Chaque « vision » est un log système : spawn timers, alertes de maintenance, notifications de seed. Le Cardinal utilise son cerveau comme processeur de décompression de données. Elle est un « terminal humain »', NULL, '*(elle ferme les yeux)* « Je ne vois plus rien. Les veines sont noires aujourd''hui. Reviens quand la montagne aura soif. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_98_10', 'NPC_GRA_98', 'KX', '{"*(hors sujet)*"}', '*(elle touche une veine de calcite)* « La pierre parle à qui sait l''écouter. Toi, tu écoutes avec tes oreilles. Moi, j''écoute avec mes os. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_01', 'NPC_GRA_99', 'K0', '{"memoire","granzam"}', 'Elle est la mémoire de Granzam — elle se souvient de tout', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_02', 'NPC_GRA_99', 'K0', '{"coeur","granit"}', 'Elle a vu naître le Cœur de Granit `NPC_GRA_00`', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_03', 'NPC_GRA_99', 'K0', '{"cite","fondation"}', 'Elle se souvient de la fondation de Granzam — chaque pierre posée', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_04', 'NPC_GRA_99', 'K1', '{"margrim","pulsation"}', 'Margrim `NPC_GRA_06` n''est pas fou — les pulsations sont réelles, il capte le Cœur', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_05', 'NPC_GRA_99', 'K1', '{"lord","hologramme"}', 'Le Lord Gnome `NPC_GRA_07` est un programme — elle l''a vu chargé dans sa salle', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_06', 'NPC_GRA_99', 'K1', '{"oracle","guide"}', 'Elle a guidé l''Oracle `NPC_GRA_98` dans ses premières visions — « je lui ai appris à lire la calcite »', '`QUEST:QST_GRA_MEMOIRE`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_07', 'NPC_GRA_99', 'K2', '{"coeur","ancrage"}', 'Le Cœur de Granit est l''ancrage physique du serveur dans le data center', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_08', 'NPC_GRA_99', 'K2', '{"seed","materiel"}', 'La seed matérielle est la clé de génération de TOUS les minerais d''ALO', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_09', 'NPC_GRA_99', 'K2', '{"resection","faille"}', 'Le Cœur a des « failles de code » — des fissures dans la seed qui corrompent les filons', '`QUEST:QST_GRA_COEUR_FAILLES`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_10', 'NPC_GRA_99', 'K3', '{"coeur","communication"}', '**SECRET** : Le Cœur ne répond qu''à une fréquence précise — celle du Chant de Granit de la Vestale `NPC_GRA_83`, modulée par le rythme cardiaque d''un joueur vivant. Pour parler au Cœur, il faut chanter sa propre signature biologique à travers la pierre. La Mémoire peut enseigner ce chant', NULL, '*(les voix se taisent)* « Je n''entends plus la fréquence. Le cœur bat hors de ma portée. Va. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_11', 'NPC_GRA_99', 'K3', '{"seed","corruption","fin"}', '**SECRET** : La seed matérielle est corrompue à 34%. Chaque résurrection à l''Autel (`NPC_GRA_80`), chaque gemme dupliquée par le Trafiquant (`NPC_GRA_93`), chaque faux or de l''Intendant (`NPC_GRA_87`) pompe la seed. Quand elle atteindra 100%, le serveur minier plantera — tous les minerais, gemmes et strates disparaîtront. Le monde d''ALO perdra sa géologie. La Mémoire connaît le seul moyen d''arrêter la corruption : reconnecter le Cœur au Cardinal via un rituel de resynchronisation', NULL, '*(les voix chuchotent)* « La pierre s''effrite. La fin est écrite dans les veines. Mais l''encre n''est pas encore sèche. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_GRA_99_12', 'NPC_GRA_99', 'KX', '{"*(hors sujet)*"}', '*(un silence, puis une seule voix, celle d''un enfant)* « Tu veux que je te raconte l''histoire du premier caillou ? »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_01', 'NPC_LIO_00', 'K0', '{"lac","note"}', 'La Note Suspendue au fond du Lac-Tambour — personne n''ose dire l''avoir entendue', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_02', 'NPC_LIO_00', 'K0', '{"harmonie","fond"}', '« Je suis le la de la ville. Écoute, et tu seras accordé. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_03', 'NPC_LIO_00', 'K0', '{"instruments","accord"}', 'Tout instrument de Lioda se cale sur sa fréquence, même sans musicien', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_04', 'NPC_LIO_00', 'K1', '{"accord","parfait"}', 'L''Accord Parfait ne dure qu''une seconde — le temps que la note se rappelle', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_05', 'NPC_LIO_00', 'K1', '{"ville","faux"}', 'Certains soirs la ville « joue faux » — la note se décale d''un souffle', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_06', 'NPC_LIO_00', 'K1', '{"partition","vivante"}', 'La note semble suivre une partition qu''aucun barde n''a écrite', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_07', 'NPC_LIO_00', 'K2', '{"origine","seed"}', 'La note n''est pas naturelle — elle a été « posée » au fond du lac, il y a très longtemps', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_08', 'NPC_LIO_00', 'K2', '{"cardinal","harmonie"}', 'L''Harmonie de Fond diffusée sur Lioda est émise depuis cette note — un relais du Cardinal', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_09', 'NPC_LIO_00', 'K2', '{"silence","vide"}', 'Quand la note s''arrête, un silence absolu tombe — le même vide que sous la ville', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_10', 'NPC_LIO_00', 'K3', '{"cardinal","seed"}', 'Elle EST le seed du Cardinal — la fréquence fondamentale avec laquelle le Système compile Lioda et garde la cité dans ses paramètres', NULL, '*(la note monte d''un demi-ton et se tait)* « Je ne suis qu''une note. Une note ne nomme pas sa propre main. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_11', 'NPC_LIO_00', 'K3', '{"partition","originelle"}', 'Elle sait que la Partition Originelle est la même fréquence que celle du Cardinal ; le monde entier est une de ses répétitions', NULL, '*(le lac se ride sans vent)* « Certaines partitions ne doivent pas être chantées. Repars, accordé. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_00_12', 'NPC_LIO_00', 'KX', '{"*(tout le reste)*"}', '*(un vibrato continu)* « Suivant. Je tiens la note. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_01', 'NPC_LIO_01', 'K0', '{"luths","arcs"}', 'Ses luths-arcs — portée, dégâts, prix', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_02', 'NPC_LIO_01', 'K0', '{"tambours","guerre"}', 'Ses tambours de guerre — buffs de cadence au combat', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_03', 'NPC_LIO_01', 'K0', '{"atelier","cordes"}', 'L''Atelier des Cordes — visite, commandes', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_04', 'NPC_LIO_01', 'K1', '{"corde","secret"}', '« Ma corde ne casse jamais. C''est un secret de famille. » (elle ment)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_05', 'NPC_LIO_01', 'K1', '{"fibre","provenance"}', 'La fibre de sa corde — trop résistante, « comme si elle venait d''ailleurs »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_06', 'NPC_LIO_01', 'K1', '{"commandes","seigneur"}', 'Elle fournit le Seigneur Silencieux `NPC_LIO_07` en instruments qu''il ne joue jamais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_07', 'NPC_LIO_01', 'K2', '{"fibre","etrange"}', 'Un rouleau de fibre récent porte des mesures qui ne correspondent à aucun instrument connu', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_08', 'NPC_LIO_01', 'K2', '{"cardinal","plan"}', 'Le sceau au dos du rouleau de fibre n''est pas celui du Seigneur — un glyph qu''elle n''a vu nulle part', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_09', 'NPC_LIO_01', 'K2', '{"partition","vivante"}', 'Un de ses luths joue seul, la nuit, une mélodie qu''elle n''a pas écrite', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_10', 'NPC_LIO_01', 'K3', '{"armes","tier superieur"}', 'Les plans de sa fibre viennent du Cardinal — ses luths-arcs dépassent le tier que Lioda devrait savoir forger ; ils sont prêts pour une armée que le serveur prépare en silence', NULL, '*(elle enroule la corde autour de son poignet)* « Mes cordes ? Cordes de famille. Si tu veux du mystère, va voir les prêtres du Silence. Moi je tends. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_11', 'NPC_LIO_01', 'K3', '{"harmonie","fond"}', 'Elle sait que sa fibre vibre à la même fréquence que l''Harmonie de Fond du Cardinal ; c''est pour ça qu''elle ne casse jamais', NULL, '*(la corde chante un demi-ton)* « Certaines fréquences ne se nomment pas. Repars, accordée. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_01_12', 'NPC_LIO_01', 'KX', '{"*(hors sujet)*"}', '*(elle polit une cheville)* « Une corde ne répond qu''à qui sait la tendre. Là, je tends. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_01', 'NPC_LIO_02', 'K0', '{"sorts","musicaux"}', 'Les sorts musicaux qu''il enseigne — effets, coûts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_02', 'NPC_LIO_02', 'K0', '{"kiosque","cours"}', 'Le Grand Kiosque — cours, inscriptions', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_03', 'NPC_LIO_02', 'K0', '{"lecon","apprenti"}', 'Sa méthode d''enseignement — pour qui, à quel niveau', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_04', 'NPC_LIO_02', 'K1', '{"sort","seul"}', '« Un de mes sorts joue seul. Un chef-d''œuvre qui vit sans moi. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_05', 'NPC_LIO_02', 'K1', '{"harmonie","fond"}', 'Le sort semble puiser dans « l''air même de la ville » — l''Harmonie de Fond', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_06', 'NPC_LIO_02', 'K1', '{"concert","ville"}', 'Les concerts où son sort a « débordé » hors de la scène', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_07', 'NPC_LIO_02', 'K2', '{"sort","etrange"}', 'Le sort seul suit une partition que Viel n''a jamais composée', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_08', 'NPC_LIO_02', 'K2', '{"cardinal","freq"}', 'La mélodie du sort se cale exactement sur la Note Suspendue `NPC_LIO_00` — la fréquence seed du Cardinal', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_09', 'NPC_LIO_02', 'K3', '{"partition","originelle"}', 'Le sort vient du Cardinal — il a compilé la magie musicale de Lioda depuis la Partition Originelle ; le « sort qui joue seul » est le monde qui se joue de lui-même', NULL, '*(il dirige un orchestre imaginaire)* « Mon sort ? Génie de Viel, rien que Viel. Si tu cherches le divin, va au Lac-Tambour. Moi j''enseigne. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_02_10', 'NPC_LIO_02', 'KX', '{"*(hors sujet)*"}', '*(il bat la mesure dans le vide)* « Une mesure ne répond qu''à qui sait la diriger. Là, je dirige. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_01', 'NPC_LIO_03', 'K0', '{"repas","buff"}', 'Ses plats sonores — buffs, prix, effets', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_02', 'NPC_LIO_03', 'K0', '{"taverne","refrain"}', 'La Taverne Le Refrain — chambres, ambiance', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_03', 'NPC_LIO_03', 'K0', '{"boissons","accord"}', 'Ses boissons qui résonnent — effets légers', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_04', 'NPC_LIO_03', 'K1', '{"refrain","ombre"}', '« Certaines nuits, un refrain passe que personne n''a commandé. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_05', 'NPC_LIO_03', 'K1', '{"clients","transe"}', 'Des clients partis en transe après un de ces refrains — elle les a réveillés au matin', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_06', 'NPC_LIO_03', 'K1', '{"lac","vague"}', 'Le refrain semble monter du Lac-Tambour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_07', 'NPC_LIO_03', 'K2', '{"ombre","lien"}', 'Le refrain de l''ombre suit la même cadence que l''Harmonie de Fond — un lien avec le Cardinal', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_08', 'NPC_LIO_03', 'K2', '{"oracle","vague"}', 'L''Oracle des Notes `NPC_LIO_98` lui a dit de ne jamais rejouer ce refrain', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_09', 'NPC_LIO_03', 'K3', '{"silence","vide"}', 'Le seul moment où le refrain s''arrête, c''est le silence absolu sous la ville — le vide du Cardinal ; la taverne entière se tait alors', NULL, '*(elle essuie un verre qui tintinnabule)* « Mon refrain ? Comptine de taverne. Si tu veux du mystère, va au Lac. Moi je sers. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_03_10', 'NPC_LIO_03', 'KX', '{"*(hors sujet)*"}', '*(elle fredonne en polissant)* « Une note ne répond qu''à qui paie son pot. Là, je sers. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_01', 'NPC_LIO_04', 'K0', '{"accord","prix"}', 'Ses services d''accord — tarifs, délais', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_02', 'NPC_LIO_04', 'K0', '{"enchant","outils"}', 'Ses enchantements d''instruments — types, coûts', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_03', 'NPC_LIO_04', 'K0', '{"atelier","cordes"}', 'L''Atelier des Cordes — coin d''accord', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_04', 'NPC_LIO_04', 'K1', '{"luth","faux"}', '« J''ai un luth qui chante faux exprès. Pour l''étude. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_05', 'NPC_LIO_04', 'K1', '{"desaccord","rythme"}', 'Le luth faux se décale toujours au même moment — l''Accord Parfait', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_06', 'NPC_LIO_04', 'K1', '{"cordes","fibre"}', 'Les cordes de Cordelia `NPC_LIO_01` ne se désaccordent jamais — sauf le luth faux', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_07', 'NPC_LIO_04', 'K2', '{"luth","etrange"}', 'Le luth faux capte une fréquence que Fitz ne peut pas nommer — elle vient du lac', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_08', 'NPC_LIO_04', 'K2', '{"cardinal","freq"}', 'La fréquence est celle de la Note Suspendue `NPC_LIO_00`, seed du Cardinal', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_09', 'NPC_LIO_04', 'K3', '{"partition","originelle"}', 'Le luth faux est une antenne vivante de la Partition Originelle — le Cardinal l''utilise pour mesurer la justesse de Lioda', NULL, '*(il serre une cheville au point de la faire crisser)* « Mon luth ? Curiosité d''atelier. Si tu veux le divin, va au Lac. Moi j''accorde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_04_10', 'NPC_LIO_04', 'KX', '{"*(hors sujet)*"}', '*(il tourne une cheville dans le vide)* « Une corde ne répond qu''à qui sait l''entendre. Là, j''écoute. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_01', 'NPC_LIO_05', 'K0', '{"quete","partitions"}', 'La quête « Partitions Perdues » — objectif, récompense', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_02', 'NPC_LIO_05', 'K0', '{"archive","portées"}', 'La Bibliothèque des Portées — fonds, accès', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_03', 'NPC_LIO_05', 'K0', '{"fragment","lecture"}', 'Le fragment qu''elle étudie — aspect, âge', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_04', 'NPC_LIO_05', 'K1', '{"fragment","brulure"}', '« Le fragment brûle les doigts. Sans marque. Comme s''il refusait d''être tenu. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_05', 'NPC_LIO_05', 'K1', '{"partition","originelle"}', 'Elle cherche la Partition Originelle — « la première mesure du monde »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_06', 'NPC_LIO_05', 'K1', '{"lac","freq"}', 'Le fragment vibre à la fréquence du Lac-Tambour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_07', 'NPC_LIO_05', 'K2', '{"fragment","etrange"}', 'Le fragment se complète seul quand personne ne regarde', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_08', 'NPC_LIO_05', 'K2', '{"cardinal","freq"}', 'La fréquence du fragment est celle de la Note Suspendue `NPC_LIO_00`, seed du Cardinal', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_09', 'NPC_LIO_05', 'K3', '{"partition","originelle"}', 'La Partition Originelle EST la fréquence du Cardinal — il a compilé Lioda depuis cette mesure ; le fragment est un morceau du code source du monde', NULL, '*(elle referme l''étui du fragment)* « Ma partition ? Recherche d''archiviste. Si tu veux le divin, va au Lac. Moi je classe. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_05_10', 'NPC_LIO_05', 'KX', '{"*(hors sujet)*"}', '*(elle range une portée)* « Une mesure ne répond qu''à qui sait la lire. Là, je lis. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_01', 'NPC_LIO_06', 'K0', '{"quetes","journalieres"}', 'Ses quêtes quotidiennes — disponibilité, récompense', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_02', 'NPC_LIO_06', 'K0', '{"rumeurs","place"}', 'Ses annonces — actu de Lioda', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_03', 'NPC_LIO_06', 'K0', '{"mesure","place"}', 'La Place de la Mesure — point de ralliement', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_04', 'NPC_LIO_06', 'K1', '{"ville","faux"}', '« Certains soirs, la ville joue faux. Ma voix dévie d''un souffle. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_05', 'NPC_LIO_06', 'K1', '{"cadence","accord"}', 'La dérive arrive toujours à l''Accord Parfait', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_06', 'NPC_LIO_06', 'K1', '{"pierre","resonance"}', 'Les pavés de la place résonnent alors comme un tambour', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_07', 'NPC_LIO_06', 'K2', '{"ville","etrange"}', 'La dérive suit la fréquence du Lac-Tambour — la Note Suspendue `NPC_LIO_00`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_08', 'NPC_LIO_06', 'K2', '{"cardinal","harmonie"}', 'La ville est accordée par l''Harmonie de Fond du Cardinal ; quand elle dévie, c''est le système qui corrige', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_09', 'NPC_LIO_06', 'K3', '{"partition","originelle"}', 'Lioda entière est une partition que le Cardinal joue — le « faux » de certains soirs est une note de correction silencieuse du monde', NULL, '*(il tousse et reprend son cri)* « Ma ville qui joue faux ? Vent qui passe. Si tu veux le divin, va au Lac. Moi je crie. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_06_10', 'NPC_LIO_06', 'KX', '{"*(hors sujet)*"}', '*(il s''éclaircit la voix)* « Une annonce ne répond qu''à qui sait écouter. Là, j''annonce. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_01', 'NPC_LIO_07', 'K0', '{"seigneur","musique"}', 'Il ne parle qu''en musique — chaque accord est un édit', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_02', 'NPC_LIO_07', 'K0', '{"balcon","amphitheatre"}', 'Le Balcon de l''Amphithéâtre — sa résidence', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_03', 'NPC_LIO_07', 'K0', '{"voix","perdue"}', 'Il a perdu sa voix — personne ne sait quand', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_04', 'NPC_LIO_07', 'K1', '{"hologramme","nature"}', '« Le Seigneur n''est pas toujours le Seigneur. » (dit la Dame de Compagnie)', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_05', 'NPC_LIO_07', 'K1', '{"silence","vu"}', 'Il a vu le silence sous la ville — « le vide qui ne sonne pas »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_06', 'NPC_LIO_07', 'K1', '{"chancelier","gouvernement"}', 'Le Chancelier `NPC_LIO_08` gouverne quand il se tait', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_07', 'NPC_LIO_07', 'K2', '{"hologramme","cardinal"}', 'Le Seigneur est une projection maintenue par le Cardinal — il n''a jamais eu de voix physique', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_08', 'NPC_LIO_07', 'K2', '{"harmonie","fond"}', 'Sa musique EST l''Harmonie de Fond diffusée sur Lioda, émise depuis la Note Suspendue `NPC_LIO_00`', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_09', 'NPC_LIO_07', 'K2', '{"oracle","hook"}', 'L''Oracle des Notes `NPC_LIO_98` reçoit ses accords comme prophéties', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_10', 'NPC_LIO_07', 'K3', '{"cardinal","avatar"}', 'Il EST un avatar du Cardinal — une interface sonore pour régner sur Lioda et garder la cité dans les paramètres du serveur', NULL, '*(l''hologramme joue un accord suspensif puis se fige)* « … » (aucune parole ne vient)');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_11', 'NPC_LIO_07', 'K3', '{"partition","originelle"}', 'Il sait que la Partition Originelle est la partition même du Cardinal ; sa « perte de voix » est le moment où le Cardinal a pris le contrôle de la sienne', NULL, '*(le balcon s''assourdit d''un coup)* « … » (le silence tombe, puis la musique reprend)');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_07_12', 'NPC_LIO_07', 'KX', '{"*(tout le reste)*"}', '*(un accord final)* « … » (il se contente de jouer)', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_01', 'NPC_LIO_08', 'K0', '{"gouvernement","regence"}', 'Il gouverne Lioda à la place du Seigneur', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_02', 'NPC_LIO_08', 'K0', '{"harmonie","loi"}', 'Ses édits « d''harmonie » — lois de la cité', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_03', 'NPC_LIO_08', 'K0', '{"balcon","amphitheatre"}', 'Le Balcon de l''Amphithéâtre — siège du régent', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_04', 'NPC_LIO_08', 'K1', '{"silence","vu"}', '« J''ai vu le silence sous la ville. Le vide qui ne sonne pas. »', '`AFF>=60`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_05', 'NPC_LIO_08', 'K1', '{"accord","parfait"}', 'Il craint l''Accord Parfait — « le moment où tout se tait vraiment »', '`AFF>=65`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_06', 'NPC_LIO_08', 'K1', '{"ville","calme"}', 'Il maintient Lioda calme par la musique diffusée en permanence', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_07', 'NPC_LIO_08', 'K2', '{"silence","vide"}', 'Le silence est le vide du Cardinal — sous la ville, aucune fréquence', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_08', 'NPC_LIO_08', 'K2', '{"harmonie","cardinal"}', 'L''Harmonie de Fond diffusée vient de la Note Suspendue `NPC_LIO_00`, relais du Cardinal', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_09', 'NPC_LIO_08', 'K2', '{"oracle","hook"}', 'L''Oracle des Notes `NPC_LIO_98` lui rapporte les vagues du lac comme signaux', '`AFF>=90`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_10', 'NPC_LIO_08', 'K3', '{"cardinal","vide"}', 'Le silence sous la ville EST le Cardinal en dehors de sa partition — le Chancelier sait qu''il ne gouverne qu''avec l''autorisation du système', NULL, '*(il se tait une seconde, le balcon s''assourdit)* « Certains vides ne se nomment pas. Reprends ton affaire. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_11', 'NPC_LIO_08', 'K3', '{"partition","originelle"}', 'Il sait que la Partition Originelle est la loi du Cardinal ; toute sa régence n''est que l''exécution de cette mesure', NULL, '*(il ferme les yeux, un accord grave monte)* « La partition ne se discute pas. Suivant. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_08_12', 'NPC_LIO_08', 'KX', '{"*(tout le reste)*"}', '*(il range un sceau)* « Une cité ne répond qu''à qui sait la maintenir. Là, je maintiens. »', '—', NULL);
