INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_17_07', 'NPC_LIO_17', 'K2', '{"salle","etrange"}', 'La salle muette annule la fréquence de la Note Suspendue `NPC_LIO_00`', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_17_08', 'NPC_LIO_17', 'K2', '{"cardinal","harmonie"}', 'La salle est le point où l''Harmonie de Fond du Cardinal s''interrompt — un nœud mort', '`QUEST:QST_LIO_ORIGIN_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_LIO_17_09', 'NPC_LIO_17', 'K3', '{"partition","originelle"}', 'La salle muette est l''endroit où la Partition Originelle se tait — le Cardinal y a laissé un blanc, la seule faille de son monde', NULL, '*(il referme la carte)* « Ma salle ? Erreur de relevé. Si tu veux le divin, va au Lac. Moi je cartographie. »');
