INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_SWI_32_07', 'NPC_SWI_32', 'K2', '{"commandes","disparues"}', 'Des commandes qui disparaissent — livrées mais jamais arrivées en réserve', '`AFF>=85`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_SWI_32_08', 'NPC_SWI_32', 'K2', '{"piste","receptionnaire"}', 'La signature du réceptionnaire — un garde qu''elle ne connaît pas, affecté à un étage qu''elle ne connaît pas', '`QUEST:QST_SWI_PROVISIONS_01`', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_SWI_32_09', 'NPC_SWI_32', 'K3', '{"etage","inexistant"}', 'Les commandes disparues sont réceptionnées par un étage sans numéro — un niveau qui ne figure pas dans le plan officiel de la Tour, approvisionné en secret par le Cardinal. Le Murmure de la Tour', NULL, '*(elle serre son cahier contre elle)* « Je dois avoir fait une erreur de comptage. Les registres sont exacts. La Tour n''a pas d''étage sans numéro — ce serait absurde. »');
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_SWI_32_10', 'NPC_SWI_32', 'KX', '{"*(hors sujet)*"}', '« Une intendante compte. Elle ne raconte pas. »', '—', NULL);
INSERT INTO T_NPC_KNOWLEDGE (qi_id, npc_id, k_level, topic_tags, content, unlock_condition, deflection_line) VALUES
('QI_SWI_33_01', 'NPC_SWI_33', 'K0', '{"diplomatie","role"}', 'Son rôle — conseillère diplomatique, négociations en cours', '—', NULL);
